"""web-article renderer — block list → clean HTML.

Takes a list of typed block dicts (conforming to schema.yaml) and returns
a single HTML string ready to store in Firestore or any web CMS.

No markdown conversion. No Quill. No stripping surprises.
"""

from typing import List, Dict, Any
import array as _cn_array, decimal, re, math, base64, urllib.request, urllib.error, json as _json
from datetime import datetime, timezone, timedelta
import bisect, calendar
from pathlib import Path
import markdown as _md_lib
from markdown.treeprocessors import Treeprocessor as _MdTree


def _md_url_ok(v):
    # Strip ASCII tab/newline/CR before scheme-sniffing, matching what a browser does before
    # navigating a URL (WHATWG URL spec's "remove all ASCII tab or newline" step) -- otherwise
    # "java\tscript:alert(1)" slips past (no match => treated as scheme-less) even though a
    # browser still runs it as javascript: once it strips the tab itself.
    v = re.sub(r'[\t\n\r]', '', v)
    # A browser also strips leading C0 controls and spaces before reading the scheme ("\x01javascript:" runs as javascript:)
    v = re.sub(r'^[\x00-\x20]+', '', v)
    m = re.match(r'^([a-zA-Z][a-zA-Z0-9+.-]*):', v)
    return not m or m.group(1).lower() in ('http', 'https', 'mailto', 'tel')


def _safe_href(v, schemes=('http', 'https', 'mailto', 'tel')):
    """Guard for every atom that builds <a href=...> straight from a payload field (not
    through _SafeMarkdown's _MdSafeUrls, which only covers markdown-rendered text). Returns
    v (tab/newline/CR stripped, same reasoning as _md_url_ok above) if its scheme -- if any --
    is in `schemes`, else ''. Mirrors the GAS twin's _hrefIsSafe."""
    if not isinstance(v, str):
        return ''
    v = re.sub(r'^[\x00-\x20]+', '', re.sub(r'[\t\n\r]', '', v).strip())   # leading C0 controls: see _md_url_ok
    if not v:
        return ''
    m = re.match(r'^([a-zA-Z][a-zA-Z0-9+.-]*):', v)
    if not m:
        return v
    return v if m.group(1).lower() in schemes else ''


def _href_is_safe_motion_pill(v):
    """motion_pill's schema promises: "https, mailto or a relative path; anything else is
    dropped." Narrower than _safe_href's default set (no bare http:, no tel:) -- kept as its
    own call so tightening/loosening one contract never silently changes the other."""
    return _safe_href(v, schemes=('https', 'mailto'))


class _MdSafeUrls(_MdTree):
    """Drop href/src values whose scheme is not http(s)/mailto/tel/relative (javascript:, data:, vbscript: ...)."""
    def run(self, root):
        for el in root.iter():
            for attr in ('href', 'src'):
                v = el.get(attr)
                if v is not None and not _md_url_ok(v):
                    del el.attrib[attr]


class _SafeMarkdown:
    """Drop-in for markdown.markdown() (2026-10-01): raw HTML in the source is shown as text, never parsed as markup, and unsafe
    link/image schemes are removed. Every renderer here that renders payload markdown goes through this."""
    @staticmethod
    def markdown(text, **kw):
        m = _md_lib.Markdown(**kw)
        m.preprocessors.deregister('html_block')
        m.inlinePatterns.deregister('html')
        m.treeprocessors.register(_MdSafeUrls(m), 'a2ui_safe_urls', 0)
        return m.convert(text if isinstance(text, str) else str(text))


_md = _SafeMarkdown()


def _render_unknown(block: Dict[str, Any]) -> str:
    """Fallback for a child block whose type isn't in _RENDERERS. Referenced
    (via _RENDERERS.get(type, _render_unknown)) in 8+ places but was never
    actually defined anywhere in this file — since dict.get()'s default
    argument is evaluated eagerly, every one of those call sites crashed
    with NameError on ANY children content, unconditionally, regardless of
    whether the fallback branch was ever taken. Found live 2026-07-18
    building demo data for the templates browser. Degrades to nothing
    rather than raising — silent > broken for an unrecognized child type."""
    return ""


