def _render_pricing_tier_card(b: dict) -> str:
    """Renders a single pricing plan: name, price, key features, and an optional CTA."""
    name       = _esc(b.get("plan_name", b.get("name", "")))
    price      = _esc(str(b.get("price", "")))
    currency   = _esc(b.get("currency", "$"))
    frequency  = _esc(b.get("frequency", ""))
    features   = b.get("features", [])
    cta_label  = _esc(b.get("call_to_action_label", ""))
    cta_url    = _esc(b.get("call_to_action_url", "#"))
    highlighted = bool(b.get("is_highlighted"))
    border = "2px solid #b5432f" if highlighted else "1px solid #e2e2e2"
    bg = "#fdf3f0" if highlighted else "#fff"
    badge = (
        '<div style="position:absolute;top:-10px;left:16px;background:#b5432f;color:#fff;'
        'font-size:0.62rem;font-weight:700;letter-spacing:0.04em;padding:2px 9px;'
        'border-radius:20px;text-transform:uppercase;">Popular</div>'
    ) if highlighted else ""
    freq_html = f'<span style="font-size:0.75rem;font-weight:600;color:#6b6558;">/{frequency}</span>' if frequency else ""
    feat_html = "".join(
        f'<li style="margin-bottom:6px;">{_esc(str(f))}</li>' for f in features
    )
    cta_html = (
        f'<a href="{cta_url}" style="display:block;text-align:center;margin-top:14px;'
        f'padding:9px 14px;border-radius:8px;background:#b5432f;color:#fff;'
        f'font-size:0.85rem;font-weight:600;text-decoration:none;">{cta_label}</a>'
    ) if cta_label else ""
    plan_k = b.get("plan_name", b.get("name", ""))
    return (
        f'<div data-cb="item" data-key="{_esc(str(plan_k))}" style="position:relative;flex:1;min-width:180px;border:{border};'
        f'border-radius:12px;padding:18px 18px 20px;background:{bg};font-family:system-ui,sans-serif;">'
        f'{badge}'
        f'<div data-cb="label" data-key="{_esc(str(plan_k))}" style="font-weight:700;font-size:0.95rem;">{name}</div>'
        f'<div style="font-size:1.7rem;font-weight:800;margin:8px 0 10px;">{currency}{price}{freq_html}</div>'
        f'<ul style="margin:0;padding-left:18px;font-size:0.82rem;color:#4b463e;line-height:1.7;">{feat_html}</ul>'
        f'{cta_html}</div>'
    )

def _render_pricing_tier_group(b: dict) -> str:
    """Renders a collection of pricing tier cards side by side."""
    tiers = b.get("tiers", [])
    cards = "".join(_render_pricing_tier_card(t) for t in tiers)
    return (
        f'<div style="display:flex;gap:12px;flex-wrap:wrap;margin:1rem 0;">{cards}</div>'
    )

def _render_skill_bars(b: dict) -> str:
    skills  = b.get("skills", b.get("items", []))
    accent  = b.get("accent", "#4f46e5")
    height  = b.get("height", 10)
    rad     = "99px" if b.get("style", "rounded") == "rounded" else "4px"
    show_pct = b.get("show_percent", True)
    rows = ""
    for s in skills:
        pct   = min(100, max(0, int(s.get("value", s.get("percent", 0)))))
        color = s.get("color", s.get("accent", accent))
        label = s.get("label", s.get("name", ""))
        rows += (
            f'<div style="margin-bottom:14px;">'
            f'<div style="display:flex;justify-content:space-between;margin-bottom:5px;">'
            f'<span style="font-size:13px;font-weight:600;color:#374151;">{_cv_esc(label)}</span>'
            + (f'<span style="font-size:12px;color:var(--muted,#5f6368);">{pct}%</span>' if show_pct else "")
            + f'</div><div style="height:{_cv_esc(height)}px;background:#e5e7eb;border-radius:{rad};overflow:hidden;">'
            f'<div style="height:100%;width:{pct}%;background:{_cv_esc(color)};border-radius:{rad};"></div>'
            f'</div>'
            + (f'<div style="font-size:11px;color:var(--muted,#5f6368);margin-top:3px;">{_cv_esc(s["sublabel"])}</div>' if s.get("sublabel") else "")
            + '</div>'
        )
    title_html = f'<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:16px;">{_cv_esc(b["title"])}</div>' if b.get("title") else ""
    return f'{title_html}<div style="margin:1rem 0;">{rows}</div>'


def _render_icon_stat_row(b: dict) -> str:
    stats  = b.get("stats", b.get("items", []))
    accent = b.get("accent", "#4f46e5")
    cols   = min(len(stats), b.get("cols", 4))
    cells  = ""
    for s in stats:
        color = s.get("accent", s.get("color", accent))
        icon_html = (f'<div style="font-size:32px;margin-bottom:8px;">{_cv_esc(s["icon"])}</div>' if s.get("icon")
                     else f'<div style="width:40px;height:40px;border-radius:50%;background:{_cv_esc(color)}18;margin:0 auto 8px;"></div>')
        cells += (
            f'<div style="text-align:center;padding:20px 12px;">{icon_html}'
            f'<div style="font-size:28px;font-weight:900;color:{_cv_esc(color)};line-height:1;margin-bottom:4px;">'
            + (f'<span style="font-size:16px;">{_cv_esc(s["prefix"])}</span>' if s.get("prefix") else "")
            + _cv_esc(str(s.get("value", "")))
            + (f'<span style="font-size:16px;">{_cv_esc(s["suffix"])}</span>' if s.get("suffix") else "")
            + f'</div><div style="font-size:12px;font-weight:600;color:var(--muted,#5f6368);text-transform:uppercase;letter-spacing:0.04em;">{_cv_esc(s.get("label",""))}</div>'
            + (f'<div style="font-size:11px;color:var(--muted,#5f6368);margin-top:2px;">{_cv_esc(s["sub"])}</div>' if s.get("sub") else "")
            + '</div>'
        )
    return f'<div style="display:grid;grid-template-columns:repeat({cols},1fr);border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;background:#fff;margin:1.5rem 0;">{cells}</div>'


# ── theme tokens ──────────────────────────────────────────────────────────────
# Shared colour set for the "blueprint"/technical atoms (color_section,
# page_header, sequence_diagram, flow_connector, numbered_list-cards). Three
# modes:
#   "dark"  — baked dark (Meet stage, MCP Apps, or an explicitly-dark embed)
#   "site"  — follow the HOST PAGE's CSS custom properties (the blog site's
#             light/dark toggle flips them live); the literal fallbacks keep
#             it identical to today's light default on any surface that never
#             defined those vars (Meet stage, standalone render, tests).
#   else    — baked light (the historical default; unchanged)
# Only "site" is new — "dark"/"light"/unset behave exactly as before, so no
# existing payload or surface changes.
def _theme_tokens(theme: str) -> dict:
    if theme == "dark":
        return {"text": "#e5e7eb", "dim": "#94a3b8", "surface": "#1e293b",
                "surface2": "#0f172a", "border": "rgba(148,163,184,0.25)"}
    if theme == "site":
        return {"text": "var(--text,#111827)", "dim": "var(--text-muted,#6b7280)",
                "surface": "var(--surface,#fff)", "surface2": "var(--surface-2,#f8fafc)",
                "border": "var(--border,#e5e7eb)"}
    return {"text": "#111827", "dim": "#6b7280", "surface": "#fff",
            "surface2": "#f8fafc", "border": "#e5e7eb"}


def _render_color_section(b: dict) -> str:
    accent  = b.get("accent", "#4f46e5")
    style   = b.get("style", "tint")
    # "site" follows the host page theme (see _theme_tokens); dark/solid/tint/
    # light unchanged.
    if style == "site":
        _t = _theme_tokens("site")
        base_bg, tc = _t["surface2"], _t["text"]
    else:
        base_bg = (f"{_cv_esc(accent)}10" if style == "tint" else accent if style == "solid" else "#0f172a" if style == "dark" else "#f8fafc")
        tc      = "#fff" if style in ("solid", "dark") else "#111827"
    padding = b.get("padding", "24px")
    # Optional grid-paper texture (added 2026-07-24 for technical/blueprint-
    # style sections) — two thin repeating line layers on top of the base
    # colour, same "graph paper" idiom as a real blueprint sheet. Line
    # colour is a faint tint of the accent so it reads as texture, not
    # decoration competing with the content.
    if b.get("grid"):
        grid_line = f"{_cv_esc(accent)}14" if style in ("light", "tint") else f"{_cv_esc(accent)}20"
        bg = (
            f"linear-gradient({grid_line} 1px, transparent 1px) 0 0 / 32px 32px, "
            f"linear-gradient(90deg, {grid_line} 1px, transparent 1px) 0 0 / 32px 32px, "
            f"{_cv_esc(base_bg)}"
        )
    else:
        bg = base_bg
    inner   = "".join(_RENDERERS.get(bl.get("type",""), _render_unknown)(bl) for bl in (b.get("blocks") or []))
    # overflow:hidden establishes a new block formatting context, so a
    # child's top/bottom margin (or a bare <h3>'s user-agent margin) can't
    # collapse straight through this wrapper and leak the page's own
    # background into what should be a solid-colour section — bit us with
    # padding:"0" + a callout's own margin at the end of a dark section.
    # Optional max_width (2026-07-24): cap + centre the section (e.g. "90%")
    # so a wide blueprint doesn't run the full column width when that reads
    # as too far right; omitted → full width as before.
    mw = b.get("max_width")
    max_css = f"max-width:{_cv_esc(mw)};margin-left:auto;margin-right:auto;" if mw else ""
    return f'<div style="background:{_cv_esc(bg)};border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:{_cv_esc(padding)};margin:1.5rem 0;color:{tc};overflow:hidden;{max_css}">{inner}</div>'


def _render_tag_cloud(b: dict) -> str:
    """tags (alias items): {label, weight?, color?} or a plain string; sizes run from min_size to max_size by weight."""
    tags = _c136_list(b.get('tags') if isinstance(b.get('tags'), list) else b.get('items'), 500)
    accent = _c136_css(b.get('accent'), 'var(--a2ui-accent,#4f46e5)')
    mn = min(max(_c136_num(b.get('min_size'), 12), 6), 96)
    mx = max(min(max(_c136_num(b.get('max_size'), 22), 6), 96), mn)
    rng = mx - mn
    rows = []
    for t in tags:
        if isinstance(t, dict):
            label = _c136_txt(t.get('label')) or _c136_txt(t.get('text'))
            w = max(_c136_num(t.get('weight'), 1), 0)
            color = _c136_css(t.get('color'), accent)
        else:
            label, w, color = _c136_txt(t), 1, accent
        if label:
            rows.append((label, w, color))
    max_w = max([r[1] for r in rows] or [1])
    if max_w <= 0:
        max_w = 1
    html = ''
    for label, w, color in rows:
        ratio = w / max_w
        size = _c136_round(mn + ratio * rng)
        a = _c136_round(10 + ratio * 25)
        if re.fullmatch(r'#[0-9a-fA-F]{6}', color):
            bg = color + ('0' + format(a, 'x'))[-2:]
        else:
            bg = 'color-mix(in srgb,' + color + ' ' + str(_c136_round(a / 255 * 100)) + '%,transparent)'
        html += ('<span data-cb="item" data-key="' + _cv_esc(label) + '" style="display:inline-block;margin:4px;padding:4px 12px;font-size:' + _c136_fmt(size)
                 + 'px;font-weight:' + ('700' if size > 16 else '500') + ';color:' + _cv_esc(color) + ';background:' + _cv_esc(bg)
                 + ';border-radius:99px;cursor:default;">' + _cv_esc(label) + '</span>')
    title = _c136_txt(b.get('title'))
    return ((('<div style="font-size:16px;font-weight:700;color:var(--text,#111827);margin-bottom:14px;">' + _cv_esc(title) + '</div>') if title else '')
            + '<div style="display:flex;flex-wrap:wrap;align-items:center;gap:2px;margin:1rem 0;">' + html + '</div>')


def _render_step_progress(b: dict) -> str:
    steps  = b.get("steps", [])
    curr   = b.get("current", 1) - 1
    accent = b.get("accent", "#4f46e5")
    items  = ""
    for i, s in enumerate(steps):
        done   = i < curr
        active = i == curr
        circ_bg = accent if (done or active) else "#e5e7eb"
        circ_tc = "#fff" if (done or active) else "#9ca3af"
        label_c = "#111827" if active else "#374151" if done else "#9ca3af"
        fw      = "700" if active else "500"
        icon    = "✓" if done else str(i + 1)
        line_bg = accent if done else "#e5e7eb"
        line    = f'<div style="flex:1;height:2px;background:{_cv_esc(line_bg)};margin-top:-1px;"></div>' if i < len(steps) - 1 else ""
        items  += (
            f'<div style="display:flex;flex-direction:column;align-items:center;flex:1 1 0;">'
            f'<div style="display:flex;align-items:center;width:100%;">'
            f'<div style="width:28px;height:28px;border-radius:50%;background:{_cv_esc(circ_bg)};color:{circ_tc};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;flex-shrink:0;">{icon}</div>'
            f'{line}</div>'
            f'<div style="margin-top:6px;font-size:11px;font-weight:{fw};color:{label_c};text-align:center;width:100%;">{_cv_esc(s.get("label", s.get("title","")))}</div>'
            f'</div>'
        )
    return f'<div style="display:flex;align-items:flex-start;gap:0;margin:1.5rem 0;padding:0 8px;">{items}</div>'


def _render_split_pane(b: dict) -> str:
    left  = b.get("left",  {})
    right = b.get("right", {})
    left_bg  = left.get("bg",  left.get("background",  b.get("left_bg",  "#f8fafc")))
    right_bg = right.get("bg", right.get("background", b.get("right_bg", "#fff")))
    left_inner  = "".join(_RENDERERS.get(bl.get("type",""), _render_unknown)(bl) for bl in (left.get("blocks")  or []))
    right_inner = "".join(_RENDERERS.get(bl.get("type",""), _render_unknown)(bl) for bl in (right.get("blocks") or []))
    return (
        f'<div style="display:grid;grid-template-columns:1fr 1fr;border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);margin:1.5rem 0;">'
        f'<div style="background:{_cv_esc(left_bg)};padding:24px;">{left_inner}</div>'
        f'<div style="background:{_cv_esc(right_bg)};padding:24px;border-left:1px solid #e5e7eb;">{right_inner}</div>'
        f'</div>'
    )


def _render_gradient_hero(b: dict) -> str:
    accent  = b.get("accent", "#4f46e5")
    accent2 = b.get("accent2", "#8b5cf6")
    grad    = b.get("gradient", f"linear-gradient(135deg,{_cv_esc(accent)}22 0%,{_cv_esc(accent2)}18 60%,#fff8 100%)")
    align   = "center" if b.get("align") == "center" else "left"
    mx      = "margin-left:auto;margin-right:auto;" if align == "center" else ""
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("title"), "gradient_hero")}" style="padding:48px 32px;border-radius:16px;background:{_cv_esc(grad)};margin:0 0 1.5rem;text-align:{align};">'
        + (f'<div style="display:inline-block;background:{_cv_esc(accent)};color:#fff;border-radius:99px;padding:3px 14px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:14px;">{_cv_esc(b["badge"])}</div>' if b.get("badge") else "")
        + f'<div style="font-size:36px;font-weight:900;line-height:1.15;color:#111827;margin-bottom:12px;letter-spacing:-0.02em;">{_md_inline(b.get("title", b.get("heading","")))}</div>'
        + (f'<div style="font-size:17px;color:#4b5563;line-height:1.6;margin-bottom:20px;max-width:600px;{mx}">{_md_inline(b["subtitle"] if b.get("subtitle") else b.get("subtext",""))}</div>' if b.get("subtitle") or b.get("subtext") else "")
        + (f'<a href="{_cv_esc(b["cta_url"])}" style="display:inline-block;background:{_cv_esc(accent)};color:#fff;border-radius:10px;padding:12px 28px;font-size:15px;font-weight:700;text-decoration:none;">{_cv_esc(b["cta_label"])}</a>' if b.get("cta_label") and b.get("cta_url") else "")
        + '</div>'
    )


def _render_icon_list(b: dict) -> str:
    accent   = b.get("accent", "#4f46e5")
    size     = b.get("size", "md")
    icon_px  = "42px" if size == "lg" else "28px" if size == "sm" else "36px"
    font_px  = "15px" if size == "lg" else "13px" if size == "sm" else "14px"
    icon_em  = "20px" if size == "lg" else "13px" if size == "sm" else "16px"
    pt       = "10px" if size == "lg" else "6px"
    rows = ""
    for item in b.get("items", []):
        color = item.get("color", accent)
        icon  = item.get("icon", "•")
        rows += (
            f'<div data-cb="item" data-key="{_cv_esc(str(item.get("label") or item.get("text") or ""))}" style="display:flex;gap:14px;align-items:flex-start;margin-bottom:14px;">'
            f'<div style="flex:0 0 {icon_px};height:{icon_px};border-radius:50%;background:{_cv_esc(color)}18;display:flex;align-items:center;justify-content:center;font-size:{icon_em};">{_cv_esc(icon)}</div>'
            f'<div style="flex:1;padding-top:{pt};">'
            + (f'<div data-cb="label" data-key="{_cv_esc(str(item.get("label") or item.get("text") or ""))}" style="font-size:{font_px};font-weight:700;color:#111827;margin-bottom:2px;">{_cv_esc(item["label"])}</div>' if item.get("label") else "")
            + (f'<div style="font-size:{font_px};color:#4b5563;line-height:1.5;">{_md_inline(item["text"])}</div>' if item.get("text") else "")
            + '</div></div>'
        )
    title_html = f'<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:14px;">{_cv_esc(b["title"])}</div>' if b.get("title") else ""
    return f'{title_html}<div style="margin:1rem 0;">{rows}</div>'


def _render_highlight_box(b: dict) -> str:
    accent = b.get("accent", "#4f46e5")
    style  = b.get("style", "gradient")
    bg     = (f"linear-gradient(135deg,{_cv_esc(accent)}18 0%,{_cv_esc(accent)}08 100%)" if style == "gradient"
              else f"{_cv_esc(accent)}12" if style == "solid" else "#fff")
    border = f"2px solid {_cv_esc(accent)}" if style == "outline" else f"1px solid {_cv_esc(accent)}30"
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("title"), "highlight_box")}" style="background:{bg};border:{border};border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:24px 28px;margin:1.5rem 0;">'
        + (f'<span style="font-size:28px;margin-bottom:10px;display:block;">{_cv_esc(b["icon"])}</span>' if b.get("icon") else "")
        + (f'<div style="font-size:18px;font-weight:800;color:#111827;margin-bottom:8px;">{_md_inline(b["title"])}</div>' if b.get("title") else "")
        + f'<div style="font-size:14px;color:#374151;line-height:1.65;">{_md_inline(b.get("text",""))}</div>'
        + '</div>'
    )


def _render_two_tone_card(b: dict) -> str:
    accent    = b.get("accent", "#4f46e5")
    dark      = b.get("header_theme") == "dark"
    header_bg = "#0f172a" if dark else accent
    sub_col   = "#94a3b8" if dark else "rgba(255,255,255,0.8)"
    inner     = "".join(_RENDERERS.get(bl.get("type",""), _render_unknown)(bl) for bl in (b.get("blocks") or b.get("content") or []))
    return (
        f'<div style="border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);margin:1rem 0;">'
        f'<div style="background:{_cv_esc(header_bg)};padding:20px 24px;">'
        + (f'<span style="font-size:24px;margin-bottom:8px;display:block;">{_cv_esc(b["icon"])}</span>' if b.get("icon") else "")
        + f'<div style="font-size:18px;font-weight:800;color:#fff;margin-bottom:4px;">{_cv_esc(b.get("title",""))}</div>'
        + (f'<div style="font-size:13px;color:{sub_col};">{_cv_esc(b["subtitle"])}</div>' if b.get("subtitle") else "")
        + f'</div><div style="background:#fff;padding:20px 24px;">{inner}</div></div>'
    )


def _render_metric_row(b: dict) -> str:
    metrics = b.get("metrics", b.get("items", []))
    cols    = min(len(metrics), b.get("cols", 4))
    cells   = ""
    for i, m in enumerate(metrics):
        accent = m.get("accent", m.get("color", b.get("accent", "#4f46e5")))
        trend  = "↑" if m.get("trend") == "up" else "↓" if m.get("trend") == "down" else ""
        tc     = "#16a34a" if m.get("trend") == "up" else "#dc2626" if m.get("trend") == "down" else "#6b7280"
        # Divider as a BORDER on the cell, not a sibling element. It used to be
        # its own <div>, which made it a grid ITEM: 4 metrics emitted 7
        # children into a repeat(4,1fr) grid, so the separators ate half the
        # cells and the row wrapped to 2 metrics with blanks between them.
        # Any cols > 2 was silently wrong. Suppressing the border on the first
        # cell of each row keeps the visual result identical for cols <= 2.
        edge   = "" if i % cols == 0 else "border-left:1px solid #e5e7eb;"
        _mk = _cv_esc(str(m.get('label') or m.get('id') or m.get('title') or m.get('name') or i))
        cells += (
            f'<div data-cb="tile" data-key="{_mk}" style="text-align:center;padding:16px 8px;{edge}">'
            f'<div style="font-size:32px;font-weight:900;color:{_cv_esc(accent)};line-height:1;margin-bottom:4px;">'
            + (f'<span style="font-size:18px;">{_cv_esc(m["prefix"])}</span>' if m.get("prefix") else "")
            + _cv_esc(str(m.get("value","")))
            + (f'<span style="font-size:18px;">{_cv_esc(m["suffix"])}</span>' if m.get("suffix") else "")
            + (f'<span style="font-size:16px;color:{tc};margin-left:4px;">{trend}</span>' if trend else "")
            + f'</div><div data-cb="label" data-key="{_mk}" style="font-size:12px;font-weight:600;color:var(--muted,#5f6368);text-transform:uppercase;letter-spacing:0.04em;">{_cv_esc(m.get("label",""))}</div>'
            + (f'<div style="font-size:11px;color:var(--muted,#5f6368);margin-top:2px;">{_cv_esc(m["sub"])}</div>' if m.get("sub") else "")
            + '</div>'
        )
    return f'<div style="display:grid;grid-template-columns:repeat({cols},1fr);border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;margin:1.5rem 0;background:#ffffff;background:var(--a2ui-surface,#ffffff);">{cells}</div>'


def _render_numbered_list(b: dict) -> str:
    accent = b.get("accent", "#4f46e5")
    style  = b.get("style", "large")
    theme  = b.get("theme")
    dark   = theme == "dark"

    if style == "cards":
        _t = _theme_tokens(theme)
        text_c = _t["text"]
        dim_c = _t["dim"]
        bg = _t["surface"]
        border = _t["border"]
        # Ghost number: accent-tinted so the "blueprint" feel reads on both a
        # light and a dark ground (var(--border) would vanish on light).
        num_c = f"{_cv_esc(accent)}44"
        cards = ""
        for i, item in enumerate(b.get("items", [])):
            num = item.get("number", i + 1)
            top_border = f"border-top:1px solid {border};" if i > 0 else ""
            tags_html = "".join(
                f'<span style="font-family:ui-monospace,monospace;font-size:10.5px;text-transform:uppercase;'
                f'letter-spacing:0.05em;padding:2px 8px;border:1px solid {_cv_esc(accent)}55;color:{_cv_esc(accent)};'
                f'border-radius:3px;margin-right:6px;">{_esc(t)}</span>'
                for t in (item.get("tags") or [])
            )
            k_card = _cv_esc(str(item.get("title", item.get("label", ""))))
            cards += (
                f'<div data-cb="item" data-key="{k_card}" style="display:grid;grid-template-columns:44px 1fr;gap:14px;padding:18px 0;{top_border}">'
                + f'<div style="grid-row:span 2;font-size:30px;font-weight:800;color:{num_c};line-height:1;">{_cv_esc(num)}</div>'
                + f'<div data-cb="label" data-key="{k_card}" style="font-weight:700;font-size:15px;color:{text_c};display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
                + _esc(item.get("title", "")) + tags_html + '</div>'
                + f'<div style="color:{dim_c};font-size:13.5px;line-height:1.55;">{_md_inline(item.get("text",""))}</div>'
                + '</div>'
            )
        # A surface panel lifts the cards off a coloured section ground (dark
        # blueprint or site-themed); on a plain light page there's no ground
        # to lift off, so no panel.
        wrapper_bg = f'background:{bg};border-radius:10px;padding:0 18px;' if theme in ("dark", "site") else ''
        return f'<div style="{wrapper_bg}">{cards}</div>'

    rows   = ""
    for i, item in enumerate(b.get("items", [])):
        num = i + 1
        if style == "large":
            num_el = f'<div style="font-size:48px;font-weight:900;color:{_cv_esc(accent)}20;line-height:1;position:absolute;top:-8px;left:0;">{num}</div>'
            wrap   = "position:relative;padding-left:44px;margin-bottom:28px;"
            pt     = ' style="padding-top:4px;"'
        else:
            num_el = f'<div style="flex:0 0 28px;height:28px;border-radius:50%;background:{_cv_esc(accent)};color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:800;">{num}</div>'
            wrap   = "display:flex;gap:14px;align-items:flex-start;margin-bottom:20px;"
            pt     = ""
        k_row = _cv_esc(str(item.get("title", item.get("label", ""))))
        rows += (
            f'<div data-cb="item" data-key="{k_row}" style="{wrap}">{num_el}<div{pt}>'
            + (f'<div data-cb="label" data-key="{k_row}" style="font-size:15px;font-weight:700;color:#111827;margin-bottom:3px;">{_cv_esc(item["label"])}</div>' if item.get("label") else "")
            + (f'<div style="font-size:14px;color:#4b5563;line-height:1.6;">{_md_inline(item["text"])}</div>' if item.get("text") else "")
            + '</div></div>'
        )
    title_html = f'<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:16px;">{_cv_esc(b["title"])}</div>' if b.get("title") else ""
    return f'{title_html}<div style="margin:1rem 0;">{rows}</div>'


def _render_page_header(b: dict) -> str:
    accent = b.get("accent", "#4f46e5")
    theme  = b.get("theme")
    dark   = theme == "dark"
    site   = theme == "site"  # follow host page theme (see _theme_tokens)
    # A `background` override now applies in dark mode too — it used to be
    # discarded unconditionally in favour of the #0f172a default, so a
    # caller couldn't ask for both theme:dark AND a specific bg (e.g. a
    # blueprint navy rather than the generic dark slate).
    if site:
        _t = _theme_tokens("site")
        bg = b.get("background") or _t["surface2"]
        tc, sc = _t["text"], _t["dim"]
    else:
        bg = b.get("background") or ("#0f172a" if dark else f"linear-gradient(135deg,{_cv_esc(accent)}18 0%,#fff 60%)")
        tc = "#f8fafc" if dark else "#111827"
        sc = "#94a3b8" if dark else "#6b7280"
    meta = b.get("meta") or []
    meta_html = ""
    if meta:
        border_c = _theme_tokens("site")["border"] if site else ("rgba(248,250,252,0.18)" if dark else "#e5e7eb")
        cells = "".join(
            f'<div style="padding:10px 20px 0 0;margin-right:20px;border-right:1px solid {border_c};">'
            f'<b style="color:{tc};font-weight:700;">{_esc(m.get("label",""))}</b> {_esc(m.get("value",""))}</div>'
            for m in meta
        )
        meta_html = (
            f'<div style="display:flex;flex-wrap:wrap;border-top:1px solid {border_c};'
            f'font-family:ui-monospace,monospace;font-size:12px;color:{sc};letter-spacing:0.02em;'
            f'margin-top:14px;">{cells}</div>'
        )
    # Condensed/blueprint title treatment (added 2026-07-24), opt-in only —
    # same "Arial Narrow" rationale as _render_subheading's condensed flag.
    title_font = ("font-family:'Arial Narrow','Helvetica Neue Condensed',sans-serif;"
                  "text-transform:uppercase;letter-spacing:0.03em;") if b.get("condensed") else ""
    tag_font = ("font-family:'Arial Narrow','Helvetica Neue Condensed',sans-serif;letter-spacing:0.08em;"
                if b.get("condensed") else "")
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("title"), "page_header")}" style="padding:32px 28px 24px;margin:0 0 1.5rem;border-radius:14px;background:{_cv_esc(bg)};border-bottom:3px solid {_cv_esc(accent)};">'
        + (f'<span style="font-size:36px;margin-bottom:10px;display:block;">{_cv_esc(b["icon"])}</span>' if b.get("icon") else "")
        + f'<div style="font-size:28px;font-weight:800;color:{tc};line-height:1.2;margin-bottom:6px;{title_font}">{_md_inline(b.get("title",""))}</div>'
        + (f'<div style="font-size:15px;color:{sc};line-height:1.5;margin-bottom:10px;">{_md_inline(b["subtitle"])}</div>' if b.get("subtitle") else "")
        + (f'<span style="display:inline-block;background:{_cv_esc(accent)};color:#fff;border-radius:99px;padding:2px 12px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;{tag_font}">{_cv_esc(b["tag"])}</span>' if b.get("tag") else "")
        + meta_html
        + '</div>'
    )


def _render_back_button(b: dict) -> str:
    label  = b.get("label", "← Back")
    accent = b.get("accent", "#4f46e5")
    style  = b.get("style", "ghost")
    url    = b.get("url", b.get("nav_slug", "#"))
    if b.get("nav_slug") and not b.get("url"):
        url = f'?nav={_cv_esc(b["nav_slug"])}'
    css = (
        f'border:1.5px solid {_cv_esc(accent)};color:{_cv_esc(accent)};background:#fff;border-radius:8px;padding:6px 16px;' if style == "outline"
        else f'color:{_cv_esc(accent)};background:none;padding:4px 0;' if style == "text"
        else f'background:{_cv_esc(accent)}14;color:{_cv_esc(accent)};border-radius:8px;padding:6px 16px;'
    )
    return (
        f'<div style="margin:0.5rem 0 1rem;">'
        f'<a href="{_cv_esc(url)}" style="display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:600;text-decoration:none;{css}">{_cv_esc(label)}</a>'
        f'</div>'
    )


def _render_section_break(b: dict) -> str:
    accent      = b.get("accent", "#e5e7eb")
    style       = b.get("style", "line")
    label       = b.get("label", "")
    border_style = "dashed" if style == "dashed" else "dotted" if style == "dots" else "solid"
    if not label:
        return f'<hr style="border:none;border-top:1px {border_style} {_cv_esc(accent)};margin:2rem 0;" />'
    return (
        f'<div style="display:flex;align-items:center;gap:12px;margin:2rem 0;">'
        f'<div style="flex:1;border-top:1px {border_style} {_cv_esc(accent)};"></div>'
        f'<span style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:var(--muted,#5f6368);white-space:nowrap;">{_cv_esc(label)}</span>'
        f'<div style="flex:1;border-top:1px {border_style} {_cv_esc(accent)};"></div>'
        f'</div>'
    )


def _render_chip_group(b: dict) -> str:
    scroll = b.get("layout") == "scroll"
    chips_html = ""
    for c in b.get("chips", []):
        bg  = (c.get("color", "#4f46e5") if c.get("active") else (_cv_esc(c["color"]) + "18" if c.get("color") else "#f3f4f6"))
        tc  = "#fff" if c.get("active") else (c.get("color") or "#374151")
        tag = f'a href="{_cv_esc(c["url"])}"' if c.get("url") else "span"
        end = "a" if c.get("url") else "span"
        chips_html += f'<{tag} style="display:inline-flex;align-items:center;background:{_cv_esc(bg)};color:{_cv_esc(tc)};border-radius:99px;padding:4px 14px;font-size:12px;font-weight:500;text-decoration:none;white-space:nowrap;">{_cv_esc(c.get("label",""))}</{end}>'
    wrap = "display:flex;flex-wrap:nowrap;overflow-x:auto;gap:8px;padding-bottom:4px;" if scroll else "display:flex;flex-wrap:wrap;gap:8px;"
    label_html = f'<div style="font-size:12px;font-weight:600;color:var(--muted,#5f6368);margin-bottom:6px;">{_cv_esc(b["label"])}</div>' if b.get("label") else ""
    return f'{label_html}<div style="{wrap}margin:0.75rem 0;">{chips_html}</div>'


def _render_columns(b: dict) -> str:
    """Generic multi-column layout container."""
    cols  = max(2, min(6, int(b.get("cols", b.get("columns", 2)))))
    gap   = b.get("gap", "1.5rem")
    align = {"top": "flex-start", "center": "center", "stretch": "stretch"}.get(b.get("align", "top"), "flex-start")
    items = b.get("items", [])
    col_html = ""
    for item in items:
        blocks = item.get("blocks", item.get("content", []))
        inner  = "".join(_RENDERERS.get(bl.get("type", ""), _render_unknown)(bl) for bl in blocks)
        col_html += f'<div style="min-width:0;">{inner}</div>'
    return (
        f'<div style="display:grid;grid-template-columns:repeat({cols},1fr);gap:{_cv_esc(gap)};'
        f'align-items:{align};margin:1.5rem 0;">'
        f'{col_html}</div>'
    )


def _render_person_card(b: dict) -> str:
    """Individual person card with name, role, photo, bio, tags, links."""
    accent = b.get("accent", "#4f46e5")
    photo  = b.get("photo_url", b.get("photo", ""))
    name   = b.get("name", "")
    initial = (name[:1] or "?").upper()
    avatar = (f'<img src="{_cv_esc(photo)}" style="width:56px;height:56px;border-radius:50%;object-fit:cover;" />'
              if photo else
              f'<span style="font-size:22px;font-weight:700;color:#fff;">{_cv_esc(initial)}</span>')
    tags_html = "".join(
        f'<span style="background:#f3f4f6;color:#374151;border-radius:99px;padding:2px 10px;font-size:11px;font-weight:500;">{_cv_esc(t)}</span>'
        for t in b.get("tags", [])
    )
    links_html = ""
    if b.get("email"):    links_html += f'<a href="mailto:{_cv_esc(b["email"])}" style="color:{_cv_esc(accent)};font-size:12px;text-decoration:none;">✉ {_cv_esc(b["email"])}</a>'
    if b.get("linkedin"): links_html += f'<a href="{_cv_esc(b["linkedin"])}" style="color:{_cv_esc(accent)};font-size:12px;text-decoration:none;margin-left:10px;">in LinkedIn</a>'
    bio_html = f'<div style="font-size:13px;color:#374151;line-height:1.5;margin-bottom:8px;">{_md_inline(b["bio"])}</div>' if b.get("bio") else ""
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("name"), "person_card")}" style="border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:20px;display:flex;gap:16px;align-items:flex-start;margin:0.5rem 0;background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
        f'<div style="flex:0 0 56px;height:56px;border-radius:50%;background:{_cv_esc(accent)};display:flex;align-items:center;justify-content:center;overflow:hidden;">{avatar}</div>'
        f'<div style="flex:1;min-width:0;">'
        f'<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:2px;">{_cv_esc(name)}</div>'
        + (f'<div style="font-size:13px;color:var(--muted,#5f6368);margin-bottom:8px;">{_cv_esc(b["role"])}</div>' if b.get("role") else "")
        + bio_html
        + (f'<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;">{tags_html}</div>' if tags_html else "")
        + (f'<div>{links_html}</div>' if links_html else "")
        + '</div></div>'
    )


def _render_agenda_block(b: dict) -> str:
    """Time-slotted schedule for a day or event."""
    accent = b.get("accent", "#4f46e5")
    type_colors = {"break": "#f3f4f6", "keynote": "#ede9fe", "workshop": "#dbeafe", "panel": "#d1fae5", "social": "#fef3c7"}
    slots_html = ""
    for s in b.get("slots", []):
        bg = type_colors.get(s.get("type", ""), "#fff")
        slots_html += (
            f'<div style="display:flex;border-bottom:1px solid #f3f4f6;">'
            f'<div style="flex:0 0 72px;padding:12px 8px;font-size:12px;font-weight:600;color:{_cv_esc(accent)};border-right:2px solid {_cv_esc(accent)};text-align:right;">{_cv_esc(s.get("time",""))}</div>'
            f'<div style="flex:1;padding:10px 14px;background:{bg};">'
            f'<div style="font-size:14px;font-weight:600;color:#111827;">{_cv_esc(s.get("title",""))}</div>'
            + (f'<div style="font-size:12px;color:var(--muted,#5f6368);margin-top:2px;">👤 {_cv_esc(s["speaker"])}</div>' if s.get("speaker") else "")
            + (f'<div style="font-size:12px;color:var(--muted,#5f6368);margin-top:2px;">📍 {_cv_esc(s["location"])}</div>' if s.get("location") else "")
            + (f'<div style="font-size:12px;color:#374151;margin-top:4px;">{_cv_esc(s["description"])}</div>' if s.get("description") else "")
            + (f'<div style="font-size:10px;font-weight:600;text-transform:uppercase;color:var(--muted,#5f6368);margin-top:4px;">{_cv_esc(s["type"])}</div>' if s.get("type") else "")
            + '</div></div>'
        )
    header = ""
    if b.get("title") or b.get("date"):
        header = (
            f'<div style="padding:12px 16px;background:#f9fafb;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:center;">'
            + (f'<span style="font-size:15px;font-weight:700;color:#111827;">{_cv_esc(b["title"])}</span>' if b.get("title") else "<span></span>")
            + (f'<span style="font-size:12px;color:var(--muted,#5f6368);">{_cv_esc(b["date"])}</span>' if b.get("date") else "")
            + '</div>'
        )
    return f'<div style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin:1.5rem 0;">{header}{slots_html}</div>'


def _render_risk_flag(b: dict) -> str:
    """Structured risk callout list with severity levels."""
    level_cfg = {
        "critical": ("#fef2f2", "#ef4444", "Critical"),
        "high":     ("#fff7ed", "#f97316", "High"),
        "medium":   ("#fefce8", "#eab308", "Medium"),
        "low":      ("#f0fdf4", "#22c55e", "Low"),
    }
    rows = ""
    for r in b.get("risks", []):
        bg, border, label = level_cfg.get(r.get("level", "medium"), level_cfg["medium"])
        rows += (
            f'<div style="border-left:4px solid {border};background:{bg};border-radius:0 8px 8px 0;padding:12px 16px;margin-bottom:10px;">'
            f'<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">'
            f'<span style="background:{ {"#ef4444":"#b91c1c","#f97316":"#c2410c","#eab308":"#a16207","#22c55e":"#15803d"}.get(border,border) };color:#fff;border-radius:4px;padding:1px 8px;font-size:10px;font-weight:700;text-transform:uppercase;">{label}</span>'
            f'<span style="font-size:14px;font-weight:600;color:#111827;">{_cv_esc(r.get("title",""))}</span></div>'
            + (f'<div style="font-size:13px;color:#374151;line-height:1.5;">{_md_inline(r["description"])}</div>' if r.get("description") else "")
            + (f'<div style="font-size:12px;color:var(--muted,#5f6368);margin-top:6px;">💡 <em>{_cv_esc(r["mitigation"])}</em></div>' if r.get("mitigation") else "")
            + '</div>'
        )
    title_html = f'<div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--muted,#5f6368);margin-bottom:8px;">{_cv_esc(b["title"])}</div>' if b.get("title") else ""
    return title_html + rows


def _render_action_items(b: dict) -> str:
    """Action items table with owner, due date, status."""
    status_cfg = {
        "done":        ("✅", "#16a34a", "#f0fdf4"),
        "in_progress": ("🔄", "#2563eb", "#eff6ff"),
        "open":        ("⭕", "#6c7586", "#fff"),
    }
    rows = ""
    for i, item in enumerate(b.get("items", [])):
        icon, color, bg = status_cfg.get(item.get("status", "open"), status_cfg["open"])
        row_bg = "#fff" if i % 2 == 0 else "#f9fafb"
        status_label = item.get("status", "open").replace("_", " ")
        rows += (
            f'<tr style="background:{row_bg};">'
            f'<td style="padding:10px 14px;font-size:13px;color:#111827;">{_md_inline(item.get("action",""))}</td>'
            f'<td style="padding:10px 14px;font-size:12px;color:var(--muted,#5f6368);white-space:nowrap;">{_cv_esc(item.get("owner","—"))}</td>'
            f'<td style="padding:10px 14px;font-size:12px;color:var(--muted,#5f6368);white-space:nowrap;">{_cv_esc(item.get("due","—"))}</td>'
            f'<td style="padding:10px 14px;text-align:center;"><span style="font-size:12px;color:{color};background:{bg};border-radius:99px;padding:2px 10px;font-weight:600;">{icon} {_cv_esc(status_label)}</span></td>'
            '</tr>'
        )
    title_html = f'<div style="padding:10px 16px;background:#f9fafb;border-bottom:1px solid #e5e7eb;font-size:14px;font-weight:700;color:#111827;">{_cv_esc(b["title"])}</div>' if b.get("title") else ""
    return (
        f'<div style="margin:1.5rem 0;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">'
        f'{title_html}'
        f'<table style="width:100%;border-collapse:collapse;">'
        f'<thead><tr style="background:#f3f4f6;">'
        f'<th style="padding:8px 14px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--muted,#5f6368);">Action</th>'
        f'<th style="padding:8px 14px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--muted,#5f6368);">Owner</th>'
        f'<th style="padding:8px 14px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--muted,#5f6368);">Due</th>'
        f'<th style="padding:8px 14px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--muted,#5f6368);">Status</th>'
        '</tr></thead>'
        f'<tbody>{rows}</tbody></table></div>'
    )


def _render_pros_cons_list(b: dict) -> str:
    # This was an unfinished auto-generated stub (its own docstring said "TODO") that never
    # read the schema's real fields (subject/pros/cons) at all (surface-parity debt). Ported
    # from GAS's real two-column implementation. 2026-09-27.
    subject = _esc(b.get("subject", ""))
    pros = b.get("pros", [])
    cons = b.get("cons", [])
    pros_html = "".join(f'<li data-cb="item" data-key="{_esc(p)}" style="display:flex;gap:8px;margin-bottom:6px;">'
                         f'<span style="color:#11813b;flex-shrink:0;">✓</span><span data-cb="label" data-key="{_esc(p)}">{_esc(p)}</span></li>' for p in pros)
    cons_html = "".join(f'<li data-cb="item" data-key="{_esc(c)}" style="display:flex;gap:8px;margin-bottom:6px;">'
                         f'<span style="color:#dc2626;flex-shrink:0;">✗</span><span data-cb="label" data-key="{_esc(c)}">{_esc(c)}</span></li>' for c in cons)
    title_html = (f'<div style="font-size:16px;font-weight:700;color:#111827;padding:14px 16px;'
                  f'border-bottom:1px solid #e5e7eb;background:#f9fafb;">{subject}</div>') if subject else ""
    return (f'<div style="margin:1rem 0;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">'
            f'{title_html}'
            f'<div style="display:grid;grid-template-columns:1fr 1fr;">'
            f'<div style="padding:16px;border-right:1px solid #e5e7eb;background:#f0fdf4;">'
            f'<div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;'
            f'margin-bottom:10px;color:#11813b;">Pros</div>'
            f'<ul style="list-style:none;padding:0;margin:0;font-size:0.85rem;color:#374151;">{pros_html}</ul></div>'
            f'<div style="padding:16px;background:#fff5f5;">'
            f'<div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;'
            f'margin-bottom:10px;color:#dc2626;">Cons</div>'
            f'<ul style="list-style:none;padding:0;margin:0;font-size:0.85rem;color:#374151;">{cons_html}</ul></div>'
            f'</div></div>')

def _render_side_by_side_spec(b: dict) -> str:
    """item_a_name / item_b_name over specs ({name, item_a, item_b}): two panes of label / value rows. Old payloads (left / right {title, specs[{label, value}]}) fill the same panes."""
    specs = b.get('specs') if isinstance(b.get('specs'), list) else None
    panes = ''
    for side, nm, old, fld in (('a', 'item_a_name', 'left', 'item_a'), ('b', 'item_b_name', 'right', 'item_b')):
        o = _c136_obj(b.get(old))
        name = _c136_txt(b.get(nm)) or _c136_txt(o.get('title'))
        if specs is not None:
            rows = [(_c136_txt(_c136_obj(s).get('name')) or _c136_txt(_c136_obj(s).get('label')), _c136_txt(_c136_obj(s).get(fld))) for s in specs[:200]]
        else:
            rows = [(_c136_txt(_c136_obj(s).get('label')), _c136_txt(_c136_obj(s).get('value'))) for s in _c136_list(o.get('specs'), 200)]
        trs = ''
        for i, (lab, val) in enumerate(rows):
            k = _c136_key(lab, 'spec ' + str(i + 1)) + ('' if side == 'a' else ' (B)')
            trs += ('<tr data-cb="item" data-key="' + k + '"' + (' style="background:#f9fafb;"' if i % 2 else '') + '><td style="padding:9px 16px;color:var(--muted,#5f6368);font-weight:500;width:45%;border-bottom:1px solid #f3f4f6;">' + _cv_esc(lab)
                    + '</td><td style="padding:9px 16px;color:#111827;font-weight:600;border-bottom:1px solid #f3f4f6;">' + _cv_esc(val) + '</td></tr>')
        panes += ('<div' + (' style="border-left:1px solid #e5e7eb;"' if side == 'b' else '') + '><div style="font-size:15px;font-weight:700;color:#fff;background:#7c3aed;padding:12px 16px;">'
                  + _cv_esc(name) + '</div><table style="width:100%;border-collapse:collapse;font-size:14px;"><tbody>' + trs + '</tbody></table></div>')
    return '<div style="margin:1rem 0;display:grid;grid-template-columns:1fr 1fr;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">' + panes + '</div>'

def _render_product_spec_table(b: dict) -> str:
    # This was an unfinished auto-generated stub (its own docstring said "TODO") that never
    # read the schema's real fields (product_name + specs:[{label,value,note?}]) at all
    # (surface-parity debt). Ported from GAS's real implementation. 2026-09-27.
    product_name = _esc(b.get("product_name", ""))
    specs = b.get("specs", [])
    rows = ""
    for s in specs:
        note = s.get("note", "")
        note_html = f'<span style="color:var(--muted,#5f6368);font-size:0.78rem;"> — {_esc(note)}</span>' if note else ""
        spec_k = s.get("key", s.get("name", s.get("label", "")))
        rows += (f'<tr data-cb="item" data-key="{_esc(str(spec_k))}"><td data-cb="label" data-key="{_esc(str(spec_k))}" style="padding:10px 16px;color:var(--muted,#5f6368);font-weight:600;width:40%;'
                 f'border-bottom:1px solid #f3f4f6;vertical-align:top;">{_esc(s.get("label",""))}</td>'
                 f'<td style="padding:10px 16px;color:#111827;border-bottom:1px solid #f3f4f6;vertical-align:top;">'
                 f'{_esc(s.get("value",""))}{note_html}</td></tr>')
    title_html = (f'<div style="font-size:15px;font-weight:700;color:#111827;background:#f9fafb;'
                  f'padding:12px 16px;border-bottom:1px solid #e5e7eb;">{product_name}</div>') if product_name else ""
    return (f'<div style="margin:1rem 0;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
            f'border-radius:10px;border-radius:var(--a2ui-radius,10px);overflow:hidden;">'
            f'{title_html}<table style="width:100%;border-collapse:collapse;font-size:14px;">'
            f'<tbody>{rows}</tbody></table></div>')

def _render_comparison_grid(b: dict) -> str:
    """products (columns) x features ({name, values[]}, a true / false value shows a tick / cross); old payloads' items ({name, value, highlight}) show as cards."""
    products = _c136_names(b.get('products'))
    feats = [f for f in _c136_list(b.get('features'), 200)]
    ncols = len(products)
    for f in feats:
        if isinstance(f, dict) and isinstance(f.get('values'), list):
            ncols = max(ncols, min(len(f['values']), 50))
    ncols = min(ncols, 50)
    table = ''
    if products or feats:
        th = 'padding:11px 16px;text-align:center;background:#7c3aed;color:#fff;font-size:13px;font-weight:700;'
        head = '<th style="padding:11px 16px;text-align:left;background:#6d28d9;color:#fff;font-size:13px;font-weight:700;">Feature</th>'
        for j in range(ncols):
            p = products[j] if j < len(products) else ''
            head += ('<th data-cb="label" data-key="' + _c136_key(p, 'product ' + str(j + 1)) + '" style="' + th + '">' + _cv_esc(p) + '</th>') if p else '<th style="' + th + '">Product ' + str(j + 1) + '</th>'
        rows = ''
        for i, f in enumerate(feats):
            o = f if isinstance(f, dict) else {}
            name = (_c136_txt(o.get('name')) or _c136_txt(o.get('label'))) if isinstance(f, dict) else _c136_txt(f)
            vals = _c136_list(o.get('values'), 50)
            cells = ''
            for j in range(ncols):
                v = vals[j] if j < len(vals) else None
                if v is True or v == 'true':
                    c = '<span style="color:#16a34a;font-weight:700;font-size:16px;">&#10003;</span>'
                elif v is False or v == 'false':
                    c = '<span style="color:#dc2626;font-size:16px;">&#10007;</span>'
                else:
                    c = _cv_esc(_c136_txt(v))
                cells += '<td style="padding:11px 16px;border-bottom:1px solid #f3f4f6;color:#374151;text-align:center;">' + c + '</td>'
            rows += ('<tr data-cb="item" data-key="' + _c136_key(name, 'feature ' + str(i + 1)) + '"><td style="padding:11px 16px;border-bottom:1px solid #f3f4f6;font-weight:600;color:#111827;">'
                     + _cv_esc(name) + '</td>' + cells + '</tr>')
        table = ('<div style="overflow-x:auto;border:1px solid #e5e7eb;border-radius:10px;"><table style="width:100%;border-collapse:collapse;font-size:14px;">'
                 '<thead><tr>' + head + '</tr></thead><tbody>' + rows + '</tbody></table></div>')
    cards = ''
    for i, it in enumerate(_c136_list(b.get('items'), 200)):
        o = _c136_obj(it)
        name = _c136_txt(o.get('name'))
        h = o.get('highlight')
        hl = h is True or h == 'true' or h == 1
        cards += ('<div data-cb="item" data-key="' + _c136_key(name, 'item ' + str(i + 1)) + '" style="padding:16px;border:1.5px solid ' + ('#7c3aed' if hl else '#e5e7eb')
                  + ';border-radius:10px;background:' + ('#faf5ff' if hl else '#fff') + ';text-align:center;">'
                  '<div style="font-size:22px;font-weight:800;color:#7c3aed;margin-bottom:4px;">' + _cv_esc(_c136_txt(o.get('value'))) + '</div>'
                  '<div style="font-size:13px;color:var(--muted,#5f6368);font-weight:500;">' + _cv_esc(name) + '</div></div>')
    title = _c136_txt(b.get('title'))
    return ('<div style="margin:1rem 0;">'
            + ('<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:12px;">' + _cv_esc(title) + '</div>' if title else '')
            + table
            + ('<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px;' + ('margin-top:12px;' if table else '') + '">' + cards + '</div>' if cards else '')
            + '</div>')

def _c136_names(v):
    """comparison_points / products: strings, or objects naming the entry."""
    out = []
    for x in _c136_list(v, 200):
        s = _c136_txt(x)
        if isinstance(x, dict):
            s = _c136_txt(x.get('label')) or _c136_txt(x.get('name')) or _c136_txt(x.get('point')) or _c136_txt(x.get('text'))
        out.append(s)
    return out


def _render_versus_block(b: dict) -> str:
    """Two entities side by side with a VS divider: entity_a_* / entity_b_* (name, description, image_url) and the comparison_points list.
    Old payloads (left / right {title, items}, metric_label) fill the same columns."""
    cols = ''
    for side, bg, f_name, f_desc, f_img, old, fb in (('a', '#eff6ff', 'entity_a_name', 'entity_a_description', 'entity_a_image_url', 'left', 'entity_a'),
                                                     ('b', '#fdf4ff', 'entity_b_name', 'entity_b_description', 'entity_b_image_url', 'right', 'entity_b')):
        o = _c136_obj(b.get(old))
        name = _c136_txt(b.get(f_name)) or _c136_txt(o.get('title'))
        desc = _c136_txt(b.get(f_desc))
        img = _safe_href(b.get(f_img), schemes=('https', 'mailto'))
        lis = ''.join('<li style="font-size:14px;color:#374151;padding:4px 0;border-bottom:1px solid rgba(0,0,0,0.05);">' + _cv_esc(_c136_txt(x)) + '</li>'
                      for x in _c136_list(o.get('items'), 200))
        cols += ('<div data-cb="item" data-key="' + _c136_key(name, fb) + '" style="padding:20px;background:' + bg + ';">'
                 + ('<img src="' + _cv_esc(img) + '" alt="' + _cv_esc(name) + '" style="display:block;max-width:100%;max-height:96px;margin:0 auto 12px;border-radius:8px;object-fit:contain;">' if img else '')
                 + '<div style="font-size:16px;font-weight:700;color:#111827;margin-bottom:12px;">' + _cv_esc(name) + '</div>'
                 + ('<div style="font-size:14px;color:#4b5563;margin-bottom:12px;">' + _cv_esc(desc) + '</div>' if desc else '')
                 + ('<ul style="list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:6px;">' + lis + '</ul>' if lis else '')
                 + '</div>')
        if side == 'a':
            cols += ('<div style="display:flex;align-items:center;justify-content:center;padding:0 12px;background:#fff;border-left:1px solid #e5e7eb;border-right:1px solid #e5e7eb;">'
                     '<span style="font-size:16px;font-weight:800;color:var(--muted,#5f6368);writing-mode:vertical-lr;letter-spacing:0.1em;">VS</span></div>')
    metric = _c136_txt(b.get('metric_label'))
    pts = ''.join('<li>' + _cv_esc(p) + '</li>' for p in _c136_names(b.get('comparison_points')) if p)
    return ('<div style="margin:1rem 0;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">'
            + ('<div style="text-align:center;font-size:13px;font-weight:600;color:var(--muted,#5f6368);background:#f9fafb;padding:8px;border-bottom:1px solid #e5e7eb;text-transform:uppercase;letter-spacing:0.04em;">' + _cv_esc(metric) + '</div>' if metric else '')
            + '<div style="display:grid;grid-template-columns:1fr auto 1fr;">' + cols + '</div>'
            + ('<div style="padding:14px 20px;border-top:1px solid #e5e7eb;"><div style="font-size:12px;font-weight:700;color:var(--muted,#5f6368);text-transform:uppercase;letter-spacing:0.04em;margin-bottom:6px;">Compared on</div>'
               '<ul style="margin:0;padding-left:20px;font-size:14px;color:#374151;">' + pts + '</ul></div>' if pts else '')
            + '</div>')

def _render_rating_comparison(b: dict) -> str:
    """TODO: Renders a comparison of multiple items based on star ratings or numerical scores"""
    label = b.get("label", b.get("title", b.get("name", "")))
    text  = b.get("text", b.get("content", b.get("value", "")))
    inner = (f"<strong>{_cv_esc(label)}</strong><br/>" if label else "") + (f"{_cv_esc(text)}" if text else f"<em style='color:#6b7280;'>[ rating_comparison ]</em>")
