def _render_live_demo_embed(b: dict) -> str:
    import html as _h
    url    = b.get("url", "#")
    height = b.get("height", "80vh")
    label  = b.get("label", "Open in new tab →")
    title  = b.get("title", "Live demo")
    # html.escape only blocks attribute breakout, not a dangerous scheme --
    # a bare `javascript:`/`data:` url would otherwise land straight in
    # iframe src. Same http(s)-only gate the live JS controller's own
    # isSafeEmbedUrl applies (cloud-run-renderer/static/a2ui-atoms-live.v1.js).
    if not url.startswith(('http://', 'https://')):
        url = '#'
    safe_url = _h.escape(url)
    safe_label = _h.escape(label)
    safe_title = _h.escape(title)
    return (
        f'<div style="margin:1.5rem 0;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.06);">'
        f'<div style="padding:8px 14px;background:#f8fafc;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;">'
        f'<span style="font-size:12px;color:var(--muted,#5f6368);font-family:monospace;">{safe_url}</span>'
        f'<a href="{safe_url}" target="_blank" rel="noopener" style="font-size:12px;color:#4f46e5;text-decoration:none;white-space:nowrap;">{safe_label}</a>'
        f'</div>'
        f'<iframe src="{safe_url}" title="{safe_title}" style="width:100%;height:{_h.escape(str(height))};border:none;display:block;" loading="lazy" sandbox="allow-scripts allow-popups allow-forms"></iframe>'
        f'</div>'
    )

def _render_benchmark_comparison(b: dict) -> str:
    """items [{label, value}] as horizontal bars (old payloads: benchmarks [{name, value, max_value, unit, color}] and title)."""
    items = [d for d in _c136_list(b.get('items') if isinstance(b.get('items'), list) else b.get('benchmarks'), 100) if isinstance(d, dict)]
    if not items:
        return '<div class="a2ui-chart-empty">No benchmarks</div>'
    vals = [_c136_pf(d.get('value')) for d in items]
    gmax = max(vals)
    pad_l, pad_r, pad_t, row_h, row_gap, width = 130, 80, 30, 36, 4, 560
    total_h = pad_t + len(items) * (row_h + row_gap) + 20
    chart_w = width - pad_l - pad_r
    title = _c136_txt(b.get('title'))
    svg = '<svg viewBox="0 0 ' + str(width) + ' ' + str(total_h) + '" width="100%" preserveAspectRatio="xMidYMid meet">'
    if title:
        svg += '<text x="' + str(width // 2) + '" y="20" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e293b">' + _cv_esc(title) + '</text>'
    for i, d in enumerate(items):
        val = vals[i]
        max_v = _c136_pf(d.get('max_value')) or gmax or 1
        if max_v <= 0:
            max_v = 1
        bw = max(min(val / max_v, 1), 0) * chart_w
        y = pad_t + i * (row_h + row_gap)
        color = _c136_css(d.get('color'), _C136_PALETTE[i % len(_C136_PALETTE)])
        unit = _c136_txt(d.get('unit'))
        name = _c136_txt(d.get('label')) or _c136_txt(d.get('name'))
        short = ''.join(list(name)[:18])
        if i % 2 == 0:
            svg += '<rect x="0" y="' + str(y) + '" width="' + str(width) + '" height="' + str(row_h) + '" fill="#f8fafc" rx="2"/>'
        svg += ('<text data-cb="label" data-key="' + _c136_key(name, 'item ' + str(i + 1)) + '" x="' + str(pad_l - 8) + '" y="' + str(y + row_h // 2 + 4)
                + '" text-anchor="end" font-size="11" fill="#334155"><title>' + _cv_esc(name) + '</title>' + _cv_esc(short) + '</text>')
        svg += '<rect x="' + str(pad_l) + '" y="' + str(y + 8) + '" width="' + str(chart_w) + '" height="' + str(row_h - 16) + '" rx="4" fill="#e2e8f0"/>'
        svg += ('<rect data-cb="bar" data-key="' + _c136_key(name, 'item ' + str(i + 1)) + '" x="' + str(pad_l) + '" y="' + str(y + 8) + '" width="' + _c136_fmt(bw)
                + '" height="' + str(row_h - 16) + '" rx="4" fill="' + _cv_esc(color) + '"/>')
        svg += ('<text x="' + str(pad_l + chart_w + 6) + '" y="' + str(y + row_h // 2 + 4) + '" font-size="11" font-weight="600" fill="#1e293b">'
                + _cv_esc(_c136_fmt(val) + (' ' + unit if unit else '')) + '</text>')
    return '<div class="a2ui-benchmark-comparison">' + svg + '</svg></div>'

# ── shared chart-axis helper (plotly core-bar) ──────────────────────────────────────────────────────────────────────────────
# d3-format 3.1.0 subset (types d f e g s % and n; flags fill/align, sign, $, 0, width, comma, precision, ~), d3-scale 4.0.2
# scaleLog ticks and nice (base 10) and the linear nice/ticks the histogram already ports. Types b c o p r x X are NOT ported: such a
# specifier is rejected (the caller shows plain numbers and says so) rather than answered wrongly. Twin of _ax* in atoms_infographic.gs.
_AX_SPEC = re.compile(r'^(?:(.)?([<>=^]))?([+\-( ])?([$#])?(0)?([0-9]+)?(,)?(\.[0-9]+)?(~)?([a-z%])?$', re.I)
_AX_SI = ['y', 'z', 'a', 'f', 'p', 'n', 'µ', 'm', '', 'k', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']
_AX_TYPES = ('d', 'f', 'e', 'g', 's', '%', 'n', '')


def _ax_parse(spec):
    """d3 formatSpecifier, or None when d3 would throw or the type is outside the ported subset."""
    if not isinstance(spec, str) or len(spec) > 24 or '\n' in spec or '\r' in spec:
        return None
    m = _AX_SPEC.match(spec)
    if m is None:
        return None
    fill, align, sign, symbol, zero, width, comma, prec, trim, typ = m.groups()
    typ = typ or ''
    if typ not in _AX_TYPES:
        return None
    return {'fill': fill or ' ', 'align': align or '>', 'sign': sign or '-', 'symbol': symbol or '', 'zero': bool(zero),
            'width': int(width) if width is not None else None, 'comma': bool(comma), 'precision': int(prec[1:]) if prec else None,
            'trim': bool(trim), 'type': typ}


def _ax_toexp(x, p=None):
    """JavaScript x.toExponential(p) for finite x >= 0 (p None = as many digits as needed): 1.5e+3, 1e-7."""
    if x == 0:
        return '0' + ('.' + '0' * p if p else '') + 'e+0'
    if p is None:
        d = decimal.Decimal(repr(float(x))).normalize()
        dg = d.as_tuple().digits
        e = len(dg) - 1 + d.as_tuple().exponent
        ds = ''.join(str(i) for i in dg)
    else:
        d = decimal.Context(prec=p + 1, rounding=decimal.ROUND_HALF_UP).create_decimal(decimal.Decimal(float(x)))
        dg = d.as_tuple().digits
        e = len(dg) - 1 + d.as_tuple().exponent
        ds = ''.join(str(i) for i in dg).ljust(p + 1, '0')[:p + 1]
    return ds[0] + ('.' + ds[1:] if len(ds) > 1 else '') + 'e' + ('+' if e >= 0 else '-') + str(abs(e))


def _ax_toprec(x, p):
    """JavaScript x.toPrecision(p) for finite x >= 0."""
    if x == 0:
        return '0' + ('.' + '0' * (p - 1) if p > 1 else '')
    mant, e = _ax_toexp(x, p - 1).split('e')
    e = int(e)
    dg = mant.replace('.', '')
    if e < -6 or e >= p:
        return mant + 'e' + ('+' if e >= 0 else '-') + str(abs(e))
    if e == p - 1:
        return dg
    if e >= 0:
        return dg[:e + 1] + '.' + dg[e + 1:]
    return '0.' + '0' * (-(e + 1)) + dg


def _ax_dparts(x, p):
    s = _ax_toexp(x, p - 1) if p else _ax_toexp(x, None)
    c, e = s.split('e')
    return (c[0] + c[2:] if len(c) > 1 else c), int(e)


def _ax_prefix_auto(x, p):
    """d3 formatPrefixAuto -> (digits, prefixExponent)."""
    coef, ex = _ax_dparts(x, p)
    pe = max(-8, min(8, math.floor(ex / 3))) * 3
    i, n = ex - pe + 1, len(coef)
    if i == n:
        return coef, pe
    if i > n:
        return coef + '0' * (i - n), pe
    if i > 0:
        return coef[:i] + '.' + coef[i:], pe
    return '0.' + '0' * (1 - i - 1) + _ax_dparts(x, max(0, p + i - 1))[0], pe


def _ax_trim(s):
    i0, i1, i, n = -1, 0, 1, len(s)
    while i < n:
        c = s[i]
        if c == '.':
            i0 = i1 = i
        elif c == '0':
            if i0 == 0:
                i0 = i
            i1 = i
        else:
            if not (c in '123456789'):
                break
            if i0 > 0:
                i0 = 0
        i += 1
    return s[:i0] + s[i1 + 1:] if i0 > 0 else s


def _ax_group(value, width):
    i, t, g, length = len(value), [], 3, 0
    while i > 0 and g > 0:
        if length + g + 1 > width:
            g = max(1, width - length)
        t.append(value[max(0, i - g):i])
        i -= g
        length += g + 1
        if length > width:
            break
    return ','.join(reversed(t))


def _ax_format(spec, v):
    """d3.format(spec)(v) for a finite number (NaN and the infinities come back as plain words)."""
    s = _ax_parse(spec)
    v = float(v)
    if s is None or v != v or v in (_HG_INF, -_HG_INF):
        return 'NaN' if v != v else ('Infinity' if v > 0 else '−Infinity')
    typ, prec, trim, comma, fill, align, sign, zero, width = s['type'], s['precision'], s['trim'], s['comma'], s['fill'], s['align'], s['sign'], s['zero'], s['width']
    if typ == 'n':
        comma, typ = True, 'g'
    elif typ not in ('d', 'f', 'e', 'g', 's', '%'):
        if prec is None:
            prec = 12
        trim, typ = True, 'g'
    if zero or (fill == '0' and align == '='):
        zero, fill, align = True, '0', '='
    prec = 6 if prec is None else (max(1, min(21, prec)) if typ in ('g', 's') else max(0, min(20, prec)))
    cur = s['symbol'] == '$'
    prefix = '$' if cur else ''
    suffix = '' if cur else ('%' if typ == '%' else '')
    neg = v < 0 or (v == 0 and math.copysign(1.0, v) < 0)
    a, pe = abs(v), 0
    if typ == '%':
        body = _ax_fixed(a * 100, prec)
    elif typ == 'd':
        body = _ax_decimal(a)
    elif typ == 'e':
        body = _ax_toexp(a, prec)
    elif typ == 'f':
        body = _ax_fixed(a, prec)
    elif typ == 'g':
        body = _ax_toprec(a, prec)
    else:
        body, pe = _ax_prefix_auto(a, prec)
    if trim:
        body = _ax_trim(body)
    try:
        isz = float(body) == 0
    except ValueError:
        isz = False
    if neg and isz and sign != '+':
        neg = False
    pre = ('(' if sign == '(' else '−') if neg else ('' if sign in ('-', '(') else sign)
    pre += prefix
    suf = (_AX_SI[8 + pe // 3] if typ == 's' else '') + suffix + (')' if neg and sign == '(' else '')
    for i, c in enumerate(body):
        if not ('0' <= c <= '9'):
            suf = ('.' + body[i + 1:] if c == '.' else body[i:]) + suf
            body = body[:i]
            break
    if comma and not zero:
        body = _ax_group(body, _HG_INF)
    length = len(pre) + len(body) + len(suf)
    pad = fill * (width - length) if width is not None and length < width else ''
    if comma and zero:
        body, pad = _ax_group(pad + body, (width - len(suf)) if pad else _HG_INF), ''
    if align == '<':
        return pre + body + suf + pad
    if align == '=':
        return pre + pad + body + suf
    if align == '^':
        h = len(pad) >> 1
        return pad[:h] + pre + body + suf + pad[h:]
    return pad + pre + body + suf


def _ax_fixed(x, d):
    return _if_numstr(x) if x >= 1e21 else _if_fixed(x, d)


def _ax_decimal(x):
    r = _hg_round(x)
    return _if_numstr(r) if r < 1e21 else format(decimal.Decimal(repr(float(r))), 'f')


def _ax_log_ticks(u, v, n):
    """scaleLog().domain([u, v]).ticks(n), base 10, u and v > 0."""
    rev = v < u
    if rev:
        u, v = v, u
    i, j = math.log10(u), math.log10(v)
    z = []
    if j - i < n:
        i, j = math.floor(i), math.ceil(j)
        while i <= j:
            for k in range(1, 10):
                t = k / _hg_pow10(-i) if i < 0 else k * _hg_pow10(i)
                if t < u:
                    continue
                if t > v:
                    break
                z.append(t)
            i += 1
        if len(z) * 2 < n:
            z = _hg_ticks(u, v, n)
    else:
        z = [_hg_pow10(int(q)) for q in _hg_ticks(i, j, min(j - i, n))]
    return z[::-1] if rev else z


def _ax_log_nice(u, v):
    """scaleLog().domain([u, v]).nice().domain()."""
    rev = v < u
    a, b = (v, u) if rev else (u, v)
    a, b = _hg_pow10(int(math.floor(math.log10(a)))), _hg_pow10(int(math.ceil(math.log10(b))))
    return (b, a) if rev else (a, b)


def _ax_scale(lo, hi, log, rng, reverse, count):
    """The value axis of a bar chart: {lo, hi, ticks, log, pos(v) -> 0..1 along the axis}. lo and hi are the data extent (zero
    included for linear); rng is a usable [a, b] or None; for a log axis the extent is of the positive values."""
    if rng:
        lo, hi = rng
    elif log:
        lo, hi = _ax_log_nice(lo, hi)
        if lo == hi:
            hi = lo * 10
    else:
        if lo == hi:
            lo, hi = (lo - 1, hi + 1) if lo != 0 else (0, 1)
        lo, hi = _hg_nice(lo, hi, count)
    ticks = _ax_log_ticks(lo, hi, count) if log else _hg_ticks(lo, hi, count)
    if log:
        major = [t for t in ticks if t == _hg_pow10(int(round(math.log10(t))))]      # d3 gives 1..9 of each decade; the axis labels the powers of ten
        if len(major) >= 2:
            ticks = major
    if log:
        l0, l1 = math.log10(lo), math.log10(hi)
        f = lambda v: (math.log10(v) - l0) / (l1 - l0)
    else:
        f = lambda v: (v - lo) / (hi - lo)
    return {'lo': lo, 'hi': hi, 'ticks': ticks, 'log': log, 'pos': (lambda v: 1 - f(v)) if reverse else f}


# ── chartjs_bar (plotly core-bar) ── static HTML bars on the shared axis helper above. Twin of _RENDERERS['chartjs_bar'] in atoms_infographic.gs.
# mode group | stack | relative | overlay, orientation v | h, show_values + value_format, legend_position, y_scale linear | log, y_range, y_format,
# y_ticks, y_reverse, gap. Series are told apart by fill pattern as well as colour; every value is in the hidden table.
_CB_COL = ['var(--accent,#0369A1)', 'var(--chart-2,#9A6120)', 'var(--chart-3,#0F6C4F)', 'var(--chart-4,#810998)', 'var(--chart-5,#19294E)',
           'var(--chart-6,#B91C1C)', 'var(--chart-7,#0E7490)', 'var(--chart-8,#5B21B6)']
_CB_CATS, _CB_SERIES, _CB_PH, _CB_CHIP = 40, 8, 240, 'position:absolute;z-index:1;font-size:0.75rem;line-height:1.25;padding:0 3px;border-radius:3px;white-space:nowrap;background:var(--surface,#F8FAFC);color:var(--text,#0F172A);border:1px solid '
_CB_LABW = 'clamp(64px,24cqw,150px)'


def _cb_fill(i, col):
    k = i % 4
    if k == 0:
        return 'background:' + col + ';'
    if k == 1:
        return 'background-color:var(--bg,#fff);background-image:repeating-linear-gradient(45deg,' + col + ' 0 3px,transparent 3px 7px);'
    if k == 2:
        return 'background-color:var(--bg,#fff);background-image:radial-gradient(' + col + ' 1.6px,transparent 1.9px);background-size:7px 7px;'
    return 'background-color:var(--bg,#fff);background-image:repeating-linear-gradient(45deg,' + col + ' 0 2px,transparent 2px 6px),repeating-linear-gradient(-45deg,' + col + ' 0 2px,transparent 2px 6px);'


def _cb_str(v, mx):
    return '' if (v is None or v is _IF_UNDEF or isinstance(v, (dict, list))) else _if_str(v)[:mx]


def _cb_num(v):
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) <= 1e12 else None


def _cb_pc(f):
    return _if_fixed(f * 100, 3) + '%'


def _cb_spec(v):
    return v if isinstance(v, str) and v != '' and _ax_parse(v) is not None else None


def _cb_data(b):
    """-> (labels, [(name, color or None, [value or None, ...])], skipped, (categories given, series given)); at most 200 categories and 24 series are read."""
    ds, labs, skipped, series = _if_g(b, 'datasets'), _if_arr(_if_g(b, 'labels'), 200), 0, []
    given_n = len(_if_g(b, 'labels')) if isinstance(_if_g(b, 'labels'), list) else 0
    if not (isinstance(ds, list) and ds):
        rows = _if_arr(_if_g(b, 'data'), 200)
        given_n = len(_if_g(b, 'data')) if isinstance(_if_g(b, 'data'), list) else 0
        if rows:
            labs = [_cb_str(_if_g(r, 'label'), 40) if isinstance(r, dict) else '' for r in rows]
            ds = [{'label': _cb_str(_if_g(b, 'title'), 40) or 'Value', 'data': [_if_g(r, 'value') if isinstance(r, dict) else None for r in rows]}]
        else:
            ds = []
    given_s = len(ds) if isinstance(ds, list) else 0
    for k, d in enumerate(_if_arr(ds, 24)):
        if not isinstance(d, dict):
            skipped += 1
            continue
        raw = _if_arr(_if_g(d, 'data'), 200)
        vals = [_cb_num(x) for x in raw]
        skipped += sum(1 for x in vals if x is None)
        given_n = max(given_n, len(_if_g(d, 'data')) if isinstance(_if_g(d, 'data'), list) else 0)
        col = _if_g(d, 'color')
        series.append((_cb_str(_if_g(d, 'label'), 40) or 'Series ' + str(k + 1),
                       col if isinstance(col, str) and re.fullmatch(r'#[0-9a-fA-F]{6}', col) else None, vals))
    n = max([len(labs)] + [len(s[2]) for s in series])
    labels = [(_cb_str(labs[i], 40) if i < len(labs) and labs[i] is not None else '') or str(i + 1) for i in range(n)]
    return labels, series, skipped, (max(given_n, n), max(given_s, len(series)))


def _render_chartjs_bar(b: dict) -> str:
    labels, series, skipped, given = _cb_data(b)
    n, S = len(labels), len(series)
    if n == 0 or not any(v is not None for s in series for v in s[2]):
        return _if_wrap(_if_title(b) + _hg_note('No numbers to draw as bars.'))
    notes = _hg_skip_note(skipped) if skipped else ''
    nd, sd = min(n, _CB_CATS), min(S, _CB_SERIES)
    if given[0] > nd:
        notes += _hg_note('The first ' + str(nd) + ' of ' + str(given[0]) + ' categories are drawn; ' + ('the table has all of them.' if given[0] == n else 'the table has the first ' + str(n) + '.'))
    if given[1] > sd:
        notes += _hg_note('The first ' + str(sd) + ' of ' + str(given[1]) + ' series are drawn; ' + ('the table has all of them.' if given[1] == S else 'the table has the first ' + str(S) + '.'))
    horiz = _if_g(b, 'orientation') in ('h', 'horizontal')
    mode = _if_pick(_if_g(b, 'mode'), ('group', 'stack', 'relative', 'overlay'), 'group')
    log = _if_g(b, 'y_scale') == 'log'
    cnt = math.floor(_if_n(_if_g(b, 'y_ticks'), 2, 12, 5))
    gap = _if_n(_if_g(b, 'gap'), 0, 0.8, 0.3)
    show = _if_truthy(_if_g(b, 'show_values')) and _if_g(b, 'show_values') != 'false'
    lp = _if_pick(_if_g(b, 'legend_position'), ('top', 'bottom', 'right', 'none'), 'top' if S > 1 else 'none')
    rev = _if_g(b, 'y_reverse') is True or _if_g(b, 'y_reverse') == 'true'
    yf, vf0 = _if_g(b, 'y_format'), _if_g(b, 'value_format')
    for nm, sp in (('y_format', yf), ('value_format', vf0)):
        if _if_truthy(sp) and _cb_spec(sp) is None:
            notes += _hg_note(nm + ' "' + _if_s(sp, 24) + '" is not a number format this chart knows; plain numbers are shown.')
    yf, vf0 = _cb_spec(yf), _cb_spec(vf0)
    vals = [v for s in series[:sd] for v in s[2][:nd] if v is not None]
    allv = [v for s in series for v in s[2] if v is not None]
    if log and mode in ('stack', 'relative'):
        mode = 'group'
        notes += _hg_note('Stacked bars need a linear axis; the bars are drawn grouped on the log axis.')
    rng = _if_g(b, 'y_range')
    rng = [float(rng[0]), float(rng[1])] if isinstance(rng, list) and len(rng) == 2 and _cb_num(rng[0]) is not None and _cb_num(rng[1]) is not None and rng[0] != rng[1] else None
    if rng is None and _if_truthy(_if_g(b, 'y_range')):
        notes += _hg_note('y_range was not two different numbers; it was ignored.')
    if rng and rng[0] > rng[1]:
        rng = [rng[1], rng[0]]
    if rng and log and rng[0] <= 0:
        rng = None
        notes += _hg_note('y_range must be above zero on a log axis; it was ignored.')
    # segments [(cat, series, v0, v1, value)] in value space
    segs, lo, hi = [], 0.0, 0.0
    drop = 0
    for i in range(nd):
        cum, pos_c, neg_c = 0.0, 0.0, 0.0
        for k in range(sd):
            v = series[k][2][i] if i < len(series[k][2]) else None
            if v is None:
                continue
            if log and v <= 0:
                drop += 1
                continue
            if mode == 'stack':
                a, e = cum, cum + v
                cum = e
            elif mode == 'relative':
                if v >= 0:
                    a, e = pos_c, pos_c + v
                    pos_c = e
                else:
                    a, e = neg_c, neg_c + v
                    neg_c = e
            else:
                a, e = None, v
            segs.append((i, k, a, e, v))
    if log:
        if drop:
            notes += _hg_note(str(drop) + (' number is' if drop == 1 else ' numbers are') + ' not above zero, so ' + ('it cannot' if drop == 1 else 'they cannot') + ' be drawn on a log axis; the table has ' + ('it' if drop == 1 else 'them') + '.')
        pv = [s[4] for s in segs]
        if not pv:
            return _if_wrap(_if_title(b) + _hg_note('No numbers above zero to draw on a log axis.') + notes)
        lo, hi = min(pv), max(pv)
        if lo == hi:
            hi = lo * 10
    else:
        ends = [x for s in segs for x in ((0.0 if s[2] is None else s[2]), s[3])]
        lo, hi = min(ends + [0.0]), max(ends + [0.0])
    ax = _ax_scale(lo, hi, log, rng, rev, cnt)
    pos = ax['pos']
    clip = [False]
    base = ax['lo'] if log else (ax['lo'] if ax['lo'] > 0 else ax['hi'] if ax['hi'] < 0 else 0.0)
    def fr(v):
        f = pos(v)
        if f < -1e-9 or f > 1 + 1e-9:
            clip[0] = True
        return min(1.0, max(0.0, f))
    dec = _hg_decimals(allv)
    vf = (lambda v: _ax_format(vf0, v)) if vf0 else ((lambda v: _ax_format(yf, v)) if yf else (lambda v: _hg_num(v, dec)))
    tdec = _hg_decimals(ax['ticks'])
    tf = (lambda t: _ax_format(yf, t)) if yf else ((lambda t: _ax_format('~s', t)) if log else (lambda t: _hg_num(t, tdec)))
    tlab = [tf(t) for t in ax['ticks']]
    tw = max([len(x) for x in tlab] + [1])
    # geometry: slots along the category axis, a fraction of each slot for the bars
    inner = 1 - gap
    kk = sd if mode == 'group' else 1
    colr = [(series[k][1] or _CB_COL[k % 8]) for k in range(sd)]
    chip_w = max([len(vf(s[4])) for s in segs] + [1]) * 7 + 10
    slot_px = max(34, (sd if mode in ('group', 'overlay') else 1) * 24 + 10)
    if horiz:      # a category label wraps in the narrowest label column (about 69px of text), so the row is as tall as its longest label needs
        slot_px = max(slot_px, min(6, math.ceil(max([len(x) for x in labels[:nd]] + [1]) * 6.6 / 69)) * 15 + 6)
    outside = show and mode in ('group', 'overlay')
    pad_top = (22 + (sd - 1) * 18 if mode == 'overlay' else 22) if (outside and not horiz) else 8
    pad_right = (chip_w + 6 if outside else 12) if horiz else 12
    gut_px = math.ceil(tw * 7.5) + 14
    grid = ''
    for t, tl in zip(ax['ticks'], tlab):
        f = pos(t)
        if f < -1e-9 or f > 1 + 1e-9:
            continue
        if horiz:
            grid += '<div style="position:absolute;top:0;bottom:0;left:' + _cb_pc(f) + ';border-left:1px dashed var(--border,#CBD5E1);"></div>'
        else:
            grid += '<div style="position:absolute;left:0;right:0;bottom:' + _cb_pc(f) + ';border-top:1px dashed var(--border,#CBD5E1);"></div>'
            grid += '<div style="position:absolute;right:100%;bottom:' + _cb_pc(f) + ';transform:translateY(50%);padding-right:6px;font-size:0.75rem;line-height:1;white-space:nowrap;color:' + _IF_MUTED + ';">' + _cv_esc(tl) + '</div>'
    zf = None if (log or not (ax['lo'] <= 0 <= ax['hi'])) else pos(0)
    if zf is not None:
        grid += ('<div style="position:absolute;top:0;bottom:0;left:' + _cb_pc(zf) + ';border-left:1.5px solid var(--muted,#475569);"></div>' if horiz
                 else '<div style="position:absolute;left:0;right:0;bottom:' + _cb_pc(zf) + ';border-top:1.5px solid var(--muted,#475569);"></div>')
    byc = {}
    for s in segs:
        byc.setdefault(s[0], []).append(s)
    bars, thresholds = '', {}
    for i in range(nd):
        inner_html = ''
        lst = byc.get(i, [])
        if mode == 'overlay':      # the largest is drawn first so the smaller ones stay in front of it
            lst = sorted(lst, key=lambda t: (-t[4], t[1]))
        for (_, k, a, e, v) in lst:
            f0, f1 = fr(a if a is not None else base), fr(e)
            low, size = min(f0, f1), abs(f1 - f0)
            gw = inner / kk if mode == 'group' else inner
            off = (1 - inner) / 2 + (k * gw if mode == 'group' else 0)
            col = colr[k]
            geo = ('top:' + _cb_pc((i + off) / nd) + ';height:' + _cb_pc(gw / nd) + ';left:' + _cb_pc(low) + ';width:' + _cb_pc(size) + ';min-width:2px;') if horiz else \
                  ('left:' + _cb_pc((i + off) / nd) + ';width:' + _cb_pc(gw / nd) + ';bottom:' + _cb_pc(low) + ';height:' + _cb_pc(size) + ';min-height:2px;')
            chip = ''
            if show:
                txt = vf(v)
                need = len(txt) * 7 + 10
                inside = mode in ('stack', 'relative')
                if inside and (size < (0.1 if horiz else 0.075)):
                    chip = ''
                else:
                    if inside:
                        place = 'left:50%;top:50%;transform:translate(-50%,-50%);'
                        frac = size if horiz else gw / nd
                    elif horiz:
                        st = (k - (sd - 1) / 2) * 18 if mode == 'overlay' else 0
                        place = 'left:calc(100% + 3px);top:calc(50% + ' + _if_fixed(st, 1) + 'px);transform:translateY(-50%);'
                        frac = 1
                    else:
                        st = k * 18 if mode == 'overlay' else 0
                        place = 'left:50%;bottom:calc(100% + 2px + ' + str(st) + 'px);transform:translateX(-50%);'
                        frac = gw / nd
                    wk = None
                    if not (horiz and not inside):
                        lead = (150 + pad_right) if horiz else (gut_px + 12)
                        wk = 99999 if frac <= 0 else int(math.ceil((lead + need / frac) / 50.0)) * 50
                    if wk is not None:
                        thresholds[wk] = True
                    chip = '<div class="cbv' + (' cbw' + str(wk) if wk is not None else '') + '" style="' + _CB_CHIP + col + ';' + place + '">' + _cv_esc(txt) + '</div>'
            inner_html += ('<div' + (' data-cb="bar" data-key="' + _cb_kj([labels[i], series[k][0]]) + '"' if sd > 1 else '') + ' style="position:absolute;box-sizing:border-box;border:1.5px solid ' + col + ';' + _cb_fill(k, col) + geo
                           + '">' + chip + '</div>')
        bars += '<div' + (' data-cb="bar" data-key="' + _cb_key(labels[i]) + '"' if sd == 1 else '') + ' style="position:absolute;inset:0;' + _if_k(i, nd) + _IF_FADE + '">' + inner_html + '</div>'
    css = '<style>' + ''.join('@container (max-width:' + str(w) + 'px){.ifcb .cbw' + str(w) + '{display:none}}' for w in sorted(thresholds)) + '@container (max-width:560px){.ifcb .cbx:not(.cbc){display:none}}</style>'
    gut = _CB_LABW if horiz else str(gut_px) + 'px'
    xs = ''
    if horiz:
        for i in range(nd):
            xs += ('<div data-cb="label" data-key="' + _cb_key(labels[i]) + '" style="position:absolute;right:100%;top:' + _cb_pc((i + 0.5) / nd) + ';transform:translateY(-50%);width:' + _CB_LABW
                   + ';box-sizing:border-box;padding-right:8px;text-align:right;font-size:0.75rem;line-height:1.15;color:' + _IF_MUTED
                   + ';overflow-wrap:anywhere;">' + _cv_esc(labels[i]) + '</div>')
        axis = ''
        for j, (t, tl) in enumerate(zip(ax['ticks'], tlab)):
            f = pos(t)
            if f < -1e-9 or f > 1 + 1e-9:
                continue
            axis += ('<div class="cbx' + (' cbc' if j % 2 == 0 else '') + '" style="position:absolute;top:6px;left:' + _cb_pc(f) + ';transform:translateX(-50%);font-size:0.75rem;line-height:1;white-space:nowrap;color:' + _IF_MUTED + ';">' + _cv_esc(tl) + '</div>')
        plot = ('<div role="img" aria-label="@ARIA@" style="position:relative;height:' + str(nd * slot_px) + 'px;border-left:1px solid var(--muted,#475569);">' + grid + bars + xs + '</div>'
                '<div style="position:relative;height:26px;margin-top:2px;">' + axis + '</div>')
    else:
        for i in range(nd):
            xs += '<div data-cb="label" data-key="' + _cb_key(labels[i]) + '" style="flex:0 0 ' + _cb_pc(1 / nd) + ';box-sizing:border-box;padding:4px 2px 0;text-align:center;font-size:0.75rem;line-height:1.2;color:' + _IF_MUTED + ';overflow-wrap:anywhere;">' + _cv_esc(labels[i]) + '</div>'
        plot = ('<div role="img" aria-label="@ARIA@" style="position:relative;height:' + str(_CB_PH) + 'px;border-bottom:1px solid var(--muted,#475569);">' + grid + bars + '</div>'
                '<div style="display:flex;">' + xs + '</div>')
    i_hi = max(range(len(segs)), key=lambda q: (segs[q][4], -q))
    i_lo = min(range(len(segs)), key=lambda q: (segs[q][4], q))
    def where(q):
        return series[segs[q][1]][0] + ', ' + labels[segs[q][0]] if sd > 1 else labels[segs[q][0]]
    aria = (('Stacked ' if mode == 'stack' else 'Relative stacked ' if mode == 'relative' else 'Overlaid ' if mode == 'overlay' else 'Grouped ' if sd > 1 else '') + ('horizontal ' if horiz else '') + 'bar chart of '
            + str(nd) + (' category' if nd == 1 else ' categories') + (' and ' + str(sd) + ' series' if sd > 1 else '') + '. Highest value ' + vf(segs[i_hi][4]) + ' (' + where(i_hi)
            + '), lowest ' + vf(segs[i_lo][4]) + ' (' + where(i_lo) + '). Value axis' + (' (log)' if log else '') + ' from ' + tf(ax['lo']) + ' to ' + tf(ax['hi']) + (', reversed' if rev else '') + '.')
    plot = plot.replace('@ARIA@', _cv_esc(aria))
    if clip[0]:
        notes += _hg_note('Bars that pass the y_range are cut at the axis; the table has the full values.')
    if show:
        notes += _hg_note('Value labels hide when the chart is too narrow to fit them; the table has every value.')
    legend = ''
    if lp != 'none' and sd > 0:
        legend = ('<div style="display:flex;flex-wrap:wrap;gap:4px 14px;font-size:0.75rem;line-height:1.2;' + ('flex-direction:column;' if lp == 'right' else '') + '">'
                  + ''.join('<div style="display:flex;align-items:center;gap:6px;"><span aria-hidden="true" style="flex:0 0 auto;width:14px;height:14px;box-sizing:border-box;border:1.5px solid ' + colr[k] + ';' + _cb_fill(k, colr[k]) + '"></span>'
                            '<span>' + _cv_esc(series[k][0]) + '</span></div>' for k in range(sd)) + '</div>')
    box = ('<div style="flex:1 1 260px;min-width:0;"><div style="position:relative;margin:' + str(pad_top) + 'px ' + str(pad_right) + 'px 0 ' + gut + ';">' + plot + '</div></div>')
    body = ('<div style="display:flex;flex-wrap:wrap;gap:8px 16px;align-items:flex-start;">' + box + (legend if lp == 'right' else '') + '</div>') if lp == 'right' else box
    chart = ('<div class="ifcb" style="container-type:inline-size;max-width:100%;overflow:hidden;">' + css + (legend if lp == 'top' else '') + body + (legend if lp == 'bottom' else '') + '</div>')
    head = ['Category'] + [s[0] for s in series]
    rows = [[labels[i]] + [_hg_num(series[k][2][i], dec) if i < len(series[k][2]) and series[k][2][i] is not None else '' for k in range(S)] for i in range(n)]
    return _if_wrap(_if_title(b) + chart + notes + _hg_version_note(b, 'chartjs_bar') + _if_table(head, rows))


def _render_chartjs_line(b: dict) -> str:
    datasets = b.get("datasets", [])
    labels   = b.get("labels", [])
    if not datasets:
        return ""
    
    # Flatten data to get global min/max for scale matching across datasets
    all_vals = []
    for ds in datasets:
        all_vals.extend(ds.get("data", []))
    if not all_vals:
        return ""
        
    mn, mx = min(all_vals), max(all_vals)
    rng = (mx - mn) or 1
    
    # SVG canvas dimensions: 500x200
    w, h = 500, 200
    pad_l, pad_r, pad_t, pad_b = 60, 20, 30, 40
    chart_w = w - pad_l - pad_r
    chart_h = h - pad_t - pad_b
    
    chart_id = f"line_{_wa_oid(b)}"
    
    # Draw horizontal grid lines (e.g., 4 intervals)
    grid_lines = ""
    for grid_idx in range(5):
        grid_y = pad_t + (grid_idx / 4) * chart_h
        grid_v = mx - (grid_idx / 4) * rng
        val_str = f"{grid_v:,.1f}" if grid_v % 1 != 0 else f"{grid_v:,.0f}"
        grid_lines += f"""
        <line x1="{pad_l}" y1="{grid_y}" x2="{pad_l + chart_w}" y2="{grid_y}" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3" />
        <text x="{pad_l - 10}" y="{grid_y + 3}" fill="rgba(255,255,255,0.65)" font-size="9" font-family="monospace" text-anchor="end">{val_str}</text>
        """
        
    # Draw x-axis labels
    x_labels = ""
    n_labels = len(labels)
    if n_labels > 1:
        for i, lbl in enumerate(labels):
            # Only render some labels if there are too many (e.g., max 8 labels)
            if n_labels > 8 and i % (n_labels // 4) != 0 and i != n_labels - 1:
                continue
            x = pad_l + (i / (n_labels - 1)) * chart_w
            x_labels += f'<text data-cb="label" data-key="{_cv_esc(lbl)}" x="{x}" y="{pad_t + chart_h + 20}" fill="rgba(255,255,255,0.65)" font-size="9" font-family="monospace" text-anchor="middle">{_cv_esc(lbl)}</text>'
            
    # Draw paths for datasets
    colors = [
        {"stroke": "#3b82f6", "stop": "#3b82f6"}, # blue
        {"stroke": "#10b981", "stop": "#10b981"}, # emerald green
        {"stroke": "#a855f7", "stop": "#a855f7"}, # purple
        {"stroke": "#f59e0b", "stop": "#f59e0b"}, # amber
        {"stroke": "#ec4899", "stop": "#ec4899"}, # pink
    ]
    
    defs = []
    series_elements = []
    
    for di, ds in enumerate(datasets):
        vals = ds.get("data", [])
        if not vals:
            continue
        n = len(vals)
        coords = []
        for i, v in enumerate(vals):
            x = pad_l + (i / (n - 1) if n > 1 else 0.5) * chart_w
            y = pad_t + (1 - (v - mn) / rng) * chart_h
            coords.append((x, y))
            
        color_set = colors[di % len(colors)]
        stroke_color = color_set["stroke"]
        stop_color = color_set["stop"]
        
        grad_id = f"grad_{chart_id}_{_cv_esc(di)}"
        glow_id = f"glow_{chart_id}_{_cv_esc(di)}"
        
        defs.append(f"""
        <linearGradient id="{grad_id}" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="{stop_color}" stop-opacity="0.22" />
          <stop offset="100%" stop-color="{stop_color}" stop-opacity="0.0" />
        </linearGradient>
        <filter id="{glow_id}" x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="3" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        """)
        
        path_pts = " ".join(f"{x},{y}" for x, y in coords)
        area_pts = f"{pad_l},{pad_t + chart_h} " + path_pts + f" {pad_l + chart_w},{pad_t + chart_h}"
        
        series_elements.append(f'<polygon points="{area_pts}" fill="url(#{grad_id})" />')
        ds_key = _cv_esc(ds.get("label") or ds.get("name") or str(di))
        series_elements.append(f'<polyline data-cb="branch" data-key="{ds_key}" points="{path_pts}" fill="none" stroke="{stroke_color}" stroke-width="2.5" filter="url(#{glow_id})" stroke-linecap="round" stroke-linejoin="round" />')
        for x, y in coords:
            series_elements.append(f'<circle cx="{x}" cy="{y}" r="3.5" fill="#0f172a" stroke="{stroke_color}" stroke-width="2" />')
            
    svg_defs = "\n".join(defs)
    series_html = "\n".join(series_elements)
    
    label = datasets[0].get("label", "") if datasets else ""
    label_html = f'<div style="font-size:0.75rem;font-weight:700;color:#94a3b8;margin-bottom:8px;font-family:monospace;letter-spacing:0.05em;text-transform:uppercase;">{_cv_esc(label)}</div>' if label else ""
    
    return f"""
    <div style="margin:1.5rem 0;padding:20px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {label_html}
      <div style="width:100%;height:200px;">
        <svg role="img" aria-label="{_cv_esc(label or b.get('title') or 'Chart')}" viewBox="0 0 {w} {h}" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" style="overflow:visible;">
          <defs>
            {svg_defs}
          </defs>
          <!-- Grid & Y-Axes -->
          {grid_lines}
          <!-- X-Axes -->
          {x_labels}
          <!-- Series -->
          {series_html}
        </svg>
      </div>
    </div>
    """

def _render_data_table_sortable(b: dict) -> str:
    """Was a hardcoded "Header 1 / Data 1" placeholder that ignored its block
    entirely — so an agent composing this atom with real data silently got
    fake output, on the live site included (found 2026-07-31 by building a
    dashboard out of catalogue atoms; the table rendered someone else's
    example data).

    Accepts BOTH shapes on purpose, because three sources disagreed:
      * spec.json documents  headers: [str]        + rows: [[cell, ...]]
      * the GAS renderer     columns: [str|{key,label}] + rows: [{key: val}]
      * this function        implemented neither
    Rather than pick a winner and break whichever callers exist, both are
    read. Header inference from dict keys mirrors the GAS behaviour."""
    cols = b.get("columns") or b.get("headers") or []
    rows = b.get("rows") or []
    cols = [c if isinstance(c, dict) else {"key": c, "label": c} for c in cols]
    if not cols and rows and isinstance(rows[0], dict):
        cols = [{"key": k, "label": k} for k in rows[0].keys()]
    if not cols and rows and isinstance(rows[0], (list, tuple)):
        cols = [{"key": i, "label": f"Column {i + 1}"} for i in range(len(rows[0]))]
    if not cols:
        return '<div style="color:var(--muted,#5f6368);font-style:italic;margin:1rem 0;">No columns defined</div>'

    pad = "6px 10px" if b.get("compact") else "8px 12px"
    th = "".join(f'<th style="padding:{pad};text-align:left;border:1px solid #e5e7eb;'
                 f'font-weight:600;">{_esc(c.get("label", c.get("key")))}</th>' for c in cols)
    body = ""
    for i, r in enumerate(rows):
        bg = "background:#fafafa;" if (b.get("striped") and i % 2) else ""
        if isinstance(r, dict):
            cells = [r.get(c.get("key"), "") for c in cols]
        elif isinstance(r, (list, tuple)):
            cells = list(r) + [""] * (len(cols) - len(r))
        else:
            cells = [r] + [""] * (len(cols) - 1)
        r_key = _esc(str(r.get("id") or r.get("name") or r.get("label") or r.get("title") or cells[0]) if isinstance(r, dict) else str(cells[0] if cells else ""))
        body += f'<tr data-cb="item" data-key="{r_key}" style="{bg}">' + "".join(
            f'<td style="padding:{pad};border:1px solid #e5e7eb;">{_esc(v)}</td>'
            for v in cells[:len(cols)]) + "</tr>"

    title = (f'<div style="font-weight:600;margin:1rem 0 .4rem;">{_esc(b["title"])}</div>'
             if b.get("title") else "")
    return (f'{title}<div style="overflow-x:auto;"><table style="width:100%;margin:0 0 1rem;'
            f'border-collapse:collapse;font-size:.9rem;"><thead><tr style="background:#f3f4f6;">'
            f'{th}</tr></thead><tbody>{body}</tbody></table></div>')

def _render_metric_comparison_card(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    label = _first_text(b.get("label"), b.get("title"), "Metric")

    # Support schema fields: label, value, previous, lower_is_better (default True)
    # Also support GAS shape fallback: baseline {label, value, unit}, comparison {label, value, unit}
    baseline_obj = b.get("baseline") if isinstance(b.get("baseline"), dict) else None
    comp_obj = b.get("comparison") if isinstance(b.get("comparison"), dict) else None

    if baseline_obj is not None or comp_obj is not None:
        base = baseline_obj or {}
        comp = comp_obj or {}
        c_lbl = _first_text(comp.get("label"), "Comparison")
        b_lbl = _first_text(base.get("label"), "Baseline")
        c_val_num = _num_loose(comp.get("value"))
        b_val_num = _num_loose(base.get("value"))
        c_unit = _first_text(comp.get("unit"), "")
        b_unit = _first_text(base.get("unit"), "")
        higher_better = b.get("higher_is_better") is not False
    else:
        c_lbl = "Current"
        b_lbl = "Previous"
        c_val_num = _num_loose(b.get("value"))
        b_val_num = _num_loose(b.get("previous"))
        c_unit = ""
        b_unit = ""
        lower_better = b.get("lower_is_better") is not False
        higher_better = not lower_better

    c_val = c_val_num if c_val_num is not None else 0.0
    b_val = b_val_num if b_val_num is not None else 0.0

    delta = ((c_val - b_val) / abs(b_val) * 100.0) if b_val != 0.0 else 0.0
    better = (c_val >= b_val) if higher_better else (c_val <= b_val)
    delta_color = "#12863d" if better else "#dc2626"
    arrow = "↑" if c_val >= b_val else "↓"

    delta_fixed = _fixed_str(abs(delta), 1)
    sign = "+" if delta >= 0.0 else "-"
    delta_txt = f"{sign}{delta_fixed}%"

    b_val_str = _text_loose(int(b_val) if b_val == int(b_val) else _rhu(b_val, 4))
    c_val_str = _text_loose(int(c_val) if c_val == int(c_val) else _rhu(c_val, 4))

    b_unit_html = f' <span class="a2ui-metric-unit">{_cv_esc(b_unit)}</span>' if b_unit else ""
    c_unit_html = f' <span class="a2ui-metric-unit">{_cv_esc(c_unit)}</span>' if c_unit else ""

    node_key = _cv_esc(label)

    return (
        f'<style>{_METRIC_CSS}</style>'
        f'<div data-cb="node" data-key="{node_key}" class="a2ui-metric-comparison">'
        f'<div class="a2ui-metric-cmp-title">{_cv_esc(label)}</div>'
        f'<div class="a2ui-metric-cmp-body">'
        f'<div class="a2ui-metric-cmp-col">'
        f'<div class="a2ui-metric-cmp-lbl">{_cv_esc(b_lbl)}</div>'
        f'<div class="a2ui-metric-cmp-val">{_cv_esc(b_val_str)}{b_unit_html}</div>'
        f'</div>'
        f'<div class="a2ui-metric-cmp-delta" style="color:{delta_color};border-color:{delta_color};">{arrow} {_cv_esc(delta_txt)}</div>'
        f'<div class="a2ui-metric-cmp-col">'
        f'<div class="a2ui-metric-cmp-lbl">{_cv_esc(c_lbl)}</div>'
        f'<div class="a2ui-metric-cmp-val">{_cv_esc(c_val_str)}{c_unit_html}</div>'
        f'</div>'
        f'</div></div>'
    )


def _render_mini_sparkline_set(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    series_raw = b.get("series")
    if not isinstance(series_raw, list):
        series_raw = b.get("sparklines")
    series = series_raw[:200] if isinstance(series_raw, list) else []

    if not series:
        return f'<style>{_SPARK_CSS}</style><div class="a2ui-chart-empty">No sparklines</div>'

    rows = []
    svg_w, svg_h = 80, 30

    for si, sp in enumerate(series):
        s_obj = sp if isinstance(sp, dict) else {}
        data_raw = s_obj.get("data")
        data_list = data_raw[:200] if isinstance(data_raw, list) else []

        data = []
        for val in data_list:
            v_num = _num_loose(val)
            data.append(v_num if v_num is not None else 0.0)

        color = _safe_css(s_obj.get("color"), "#4f46e5")
        label = _first_text(s_obj.get("label"), "")
        unit = _first_text(s_obj.get("unit"), "")

        last_val = data[-1] if data else 0.0
        last_str = _text_loose(int(last_val) if last_val == int(last_val) else _rhu(last_val, 2))

        sk_raw = _first_text(s_obj.get("name"), s_obj.get("id"), s_obj.get("label"), s_obj.get("title"), str(si))
        sk = _cv_esc(sk_raw)

        min_v = min(data) if data else 0.0
        max_v = max(data) if data else 0.0
        if max_v == min_v:
            max_v += 1.0

        n = len(data)
        pts = []
        for i, v in enumerate(data):
            x = (i / (n - 1) * svg_w) if n > 1 else (svg_w / 2.0)
            y = (svg_h - 2.0) - ((v - min_v) / (max_v - min_v)) * (svg_h - 4.0)
            x_str = _text_loose(int(x + 0.5) if x == int(x) else _rhu(x, 1))
            y_str = _text_loose(int(y + 0.5) if y == int(y) else _rhu(y, 1))
            pts.append(f"{x_str},{y_str}")

        pts_str = " ".join(pts)
        polyline = f'<polyline points="{pts_str}" fill="none" stroke="{color}" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>' if len(data) > 1 else ""

        spark_svg = (
            f'<svg role="img" aria-label="{_cv_esc((label or "Sparkline") + ": " + last_str + (" " + unit if unit else ""))}" viewBox="0 0 {svg_w} {svg_h}" width="{svg_w}" height="{svg_h}" style="display:inline-block;vertical-align:middle;">'
            f'{polyline}'
            f'</svg>'
        )

        unit_str = f" {_cv_esc(unit)}" if unit else ""

        rows.append(
            f'<div data-cb="item" data-key="{sk}" class="a2ui-sparkline-row">'
            f'<span data-cb="label" data-key="{sk}" class="a2ui-sparkline-label">{_cv_esc(label)}</span>'
            f'{spark_svg}'
            f'<span class="a2ui-sparkline-val" style="color:{color};">{_cv_esc(last_str)}{unit_str}</span>'
            f'</div>'
        )

    return f'<style>{_SPARK_CSS}</style><div class="a2ui-sparkline-set">{"".join(rows)}</div>'


def _render_donut_stat(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    val_num = _num_loose(b.get("value"))
    val = val_num if val_num is not None else 0.0

    max_num = _num_loose(b.get("max_value"))
    max_val = max_num if (max_num is not None and max_num > 0) else 100.0

    pct = (val / max_val * 100.0) if max_val > 0 else 0.0
    pct = min(100.0, max(0.0, pct))

    label = _first_text(b.get("label"), "")
    unit = _first_text(b.get("unit"), "%")
    color = _safe_css(b.get("color"), "#22d3ee")

    size_raw = b.get("size")
    size_m = re.fullmatch(r'\s*([0-9]+(?:\.[0-9]+)?)\s*(?:px)?\s*', size_raw) if isinstance(size_raw, str) and len(size_raw) < 40 else None
    size_num = float(size_m.group(1)) if size_m else _num_loose(size_raw)
    size = int(size_num + 0.5) if (size_num is not None and size_num > 0) else 160
    size = min(400, max(40, size))

    uid = f"donut-{_wa_uid(b)}"
    r = size / 2.0 - 14.0
    if r < 1.0:
        r = 1.0
    cx = size / 2.0
    cy = size / 2.0
    circ = 2.0 * 3.141592653589793 * r
    dash_offset = circ * (1.0 - pct / 100.0)

    circ_str = _fixed_str(circ, 2)
    dash_str = _fixed_str(dash_offset, 2)

    cx_str = _text_loose(int(cx) if cx == int(cx) else _rhu(cx, 1))
    cy_str = _text_loose(int(cy) if cy == int(cy) else _rhu(cy, 1))
    r_str = _text_loose(int(r) if r == int(r) else _rhu(r, 1))

    f1 = int(size * 0.18 + 0.5)
    f2 = int(size * 0.1 + 0.5)
    y1 = int(cy - 4 + 0.5)
    y2 = int(cy + int(size * 0.14 + 0.5) + 0.5)

    v_round = int(val + 0.5) if val >= 0 else int(val - 0.5)
    center_val_str = _text_loose(v_round)

    label_html = f'<div class="a2ui-donut-label" style="margin-top:4px;font-size:13px;color:var(--muted,#5f6368);">{_cv_esc(label)}</div>' if label else ""
    node_key = _cv_esc(label)

    return (
        f'<style>'
        f'@keyframes donut-spin-{uid}{{from{{stroke-dashoffset:{circ_str};}}to{{stroke-dashoffset:{dash_str};}}}}'
        f'@media (prefers-reduced-motion:reduce){{.a2ui-donut-arc-{uid}{{animation:none !important;stroke-dashoffset:{dash_str} !important;}}}}'
        f'</style>'
        f'<div data-cb="node" data-key="{node_key}" class="a2ui-donut-stat" style="display:inline-block;text-align:center;">'
        f'<svg role="img" aria-label="Donut statistic" viewBox="0 0 {size} {size}" width="{size}" height="{size}">'
        f'<circle cx="{cx_str}" cy="{cy_str}" r="{r_str}" fill="none" stroke="#e2e8f0" stroke-width="12"/>'
        f'<circle class="a2ui-donut-arc-{uid}" cx="{cx_str}" cy="{cy_str}" r="{r_str}" fill="none" stroke="{color}" stroke-width="12" stroke-linecap="round" '
        f'stroke-dasharray="{circ_str}" stroke-dashoffset="{circ_str}" transform="rotate(-90 {cx_str} {cy_str})" '
        f'style="animation:donut-spin-{uid} 1s ease-out forwards;stroke-dashoffset:{dash_str};"/>'
        f'<text x="{cx_str}" y="{y1}" text-anchor="middle" font-size="{f1}" font-weight="bold" fill="#1e293b">{_cv_esc(center_val_str)}</text>'
        f'<text x="{cx_str}" y="{y2}" text-anchor="middle" font-size="{f2}" fill="#64748b">{_cv_esc(unit)}</text>'
        f'</svg>'
        f'{label_html}'
        f'</div>'
    )


def _interpolate_color(c1: str, c2: str, weight: float) -> str:
    c1 = c1.lstrip("#")
    r1, g1, b1 = int(c1[0:2], 16), int(c1[2:4], 16), int(c1[4:6], 16)
    c2 = c2.lstrip("#")
    r2, g2, b2 = int(c2[0:2], 16), int(c2[2:4], 16), int(c2[4:6], 16)
    r = int(r1 + (r2 - r1) * weight)
    g = int(g1 + (g2 - g1) * weight)
    b = int(b1 + (b2 - b1) * weight)
    return f"#{r:02x}{g:02x}{b:02x}"

def _get_color_from_scale(scale: list[str], weight: float) -> str:
    if not scale:
        return "#10b981"
    if len(scale) == 1:
        return scale[0]
    weight = min(1.0, max(0.0, weight))
    num_segments = len(scale) - 1
    segment = int(weight * num_segments)
    if segment >= num_segments:
        segment = num_segments - 1
    segment_w = 1.0 / num_segments
    segment_percent = (weight - (segment * segment_w)) / segment_w
    return _interpolate_color(scale[segment], scale[segment+1], segment_percent)

def _hmg_is_matrix(data) -> bool:
    """Schema shape: data is a list of rows, each row a list of numbers (legacy shape: a list of {row, col, value} dicts)."""
    return isinstance(data, list) and any(isinstance(r, list) for r in data)


def _render_heatmap(b: dict) -> str:
    """Route by shape: a list of lists is the schema heatmap (the extended grid, _hm_ext), anything else the legacy {row, col, value} list."""
    if isinstance(b, dict) and _hmg_is_matrix(b.get("data")):
        return _hm_ext(_hm_matrix_prep(b))
    return _render_heatmap_items(b)


def _render_status_dashboard(b: dict) -> str:
    """Overall-status banner + per-service rows. Mirrors the GAS renderer
    (apps-script-surface/atom.gs): title, items [{name, status, description?}],
    status enum operational|degraded|outage|maintenance, banner = worst status.
    Legacy shapes still accepted: `metrics` [{label, value, color}] (the old
    schema.yaml doc) and `services` (old demo alias for `items`)."""
    import html as _h
    COLORS = {"operational": "#15793a", "degraded": "#925d06",
              "outage": "#ef4444", "maintenance": "#4f46e5"}
    LABELS = {"operational": "Operational", "degraded": "Degraded",
              "outage": "Outage", "maintenance": "Maintenance"}
    OVERALL = {"operational": "All systems operational",
               "degraded": "Some systems are experiencing degraded performance",
               "outage": "One or more systems are experiencing an outage",
               "maintenance": "Scheduled maintenance in progress"}
    rows = []  # (name, description, status_key or None, label, color)
    for m in (b.get("items") or b.get("services") or []):
        if not isinstance(m, dict):
            continue
        key = str(m.get("status") or "operational").lower()
        rows.append((m.get("name", m.get("label", "")), m.get("description", ""), key,
                     LABELS.get(key, str(m.get("status", ""))), COLORS.get(key, "#94a3b8")))
    for m in (b.get("metrics") or []):
        if isinstance(m, dict):
            rows.append((m.get("label", ""), "", None, str(m.get("value", "")),
                         str(m.get("color", "#94a3b8"))))
    if not rows:
        return ('<div style="margin:1rem 0;padding:12px;border:1px solid var(--a2ui-border,#eaeaea);box-shadow:var(--a2ui-shadow,0 1px 2px rgba(0,0,0,.04),0 4px 12px rgba(0,0,0,.04));'
                'border-radius:var(--a2ui-radius,12px);color:var(--a2ui-muted,#666666);font-size:.85rem;">No status items provided.</div>')
    keys = {r[2] for r in rows if r[2]}
    overall = next((k for k in ("outage", "degraded", "maintenance") if k in keys), "operational")
    title = b.get("title", "System Status")
    esc = lambda v: _h.escape(str(v))
    out = [f'<div style="margin:1rem 0;border:1px solid var(--a2ui-border,#eaeaea);box-shadow:var(--a2ui-shadow,0 1px 2px rgba(0,0,0,.04),0 4px 12px rgba(0,0,0,.04));border-radius:var(--a2ui-radius,12px);overflow:hidden;background:var(--a2ui-surface,#ffffff);">',
           f'<div style="display:flex;align-items:center;gap:10px;padding:14px 16px;background:{COLORS[overall]};color:#fff;">'
           f'<span style="width:10px;height:10px;border-radius:50%;background:var(--a2ui-surface,#ffffff);opacity:.9;flex-shrink:0;"></span>'
           f'<div>' + (f'<div style="font-weight:700;font-size:.95rem;">{esc(title)}</div>' if title else "") +
           f'<div style="font-size:.8rem;opacity:.95;">{OVERALL[overall]}</div></div></div>']
    for name, desc, _k, label, color in rows:
        c = esc(color)
        out.append(
            f'<div style="display:flex;align-items:center;gap:10px;padding:10px 16px;border-top:1px solid var(--a2ui-border-soft,#f1f1f1);">'
            f'<span style="width:8px;height:8px;border-radius:50%;background:{c};flex-shrink:0;"></span>'
            f'<div style="flex:1;min-width:0;"><span style="font-size:.88rem;color:var(--a2ui-text,#171717);">{esc(name)}</span>'
            + (f'<span style="display:block;font-size:.75rem;color:var(--a2ui-muted,#666666);">{esc(desc)}</span>' if desc else "") +
            f'</div><span style="font-size:.75rem;font-weight:600;padding:2px 10px;border-radius:12px;'
            f'background:{c}20;color:{c};border:1px solid {c}40;">{esc(label)}</span></div>')
    out.append('</div>')
    return "".join(out)

def _render_uptime_timeline(b: dict) -> str:
    label = _text_loose(b.get('label'))
    pct = _num_loose(b.get('uptime'))
    if pct is None:
        pct = _num_loose(b.get('uptime_percent'))
    if pct is not None:
        pct = max(0, min(100, pct))
    period = _text_loose(b.get('period'))
    raw = b.get('days')
    days = raw[-240:] if isinstance(raw, list) else []

    def day_color(d):
        s = d.get('status') if isinstance(d, dict) else d
        if s is True:
            v = 1
        elif s is False:
            v = 0
        else:
            v = _num_loose(s)
        if v is None:
            return '#94a3b8'
        if v >= 1:
            return '#22c55e'
        if v >= 0.5:
            return '#f59e0b'
        return '#ef4444'

    def day_title(d, i):
        t = _text_loose(d.get('date')) if isinstance(d, dict) else ''
        return t or ('Day ' + str(i + 1))
    block_w = max(2, min(8, 480 // len(days))) if days else 6
    block_h, gap, pad_l, pad_r, pad_t, width = 24, 1, 10, 70, 20, 560
    svg_w = width - pad_l - pad_r
    hundredths = None if pct is None else int(math.floor(pct * 100 + 0.5))
    pct_txt = '' if hundredths is None else str(hundredths // 100) + '.' + ('0' + str(hundredths % 100))[-2:]
    aria = (label or 'Uptime') + ((' ' + pct_txt + '%') if pct_txt else '') + ((', ' + period) if period else '')
    svg = '<svg role="img" aria-label="' + _cv_esc(aria) + '" viewBox="0 0 ' + str(width) + ' ' + str(block_h + pad_t + 10) + '" width="100%" preserveAspectRatio="xMidYMid meet">'
    if label:
        svg += '<text x="' + str(pad_l) + '" y="14" font-size="12" font-weight="600" style="fill:var(--a2ui-text,#171717)">' + _cv_esc(label) + '</text>'
    x = pad_l
    for i, d in enumerate(days):
        svg += ('<rect x="' + str(x) + '" y="' + str(pad_t) + '" width="' + str(block_w - gap) + '" height="' + str(block_h) + '" rx="1.5" fill="' + day_color(d) + '"><title>'
                + _cv_esc(day_title(d, i)) + '</title></rect>')
        x += block_w
    if not days:
        svg += '<rect x="' + str(pad_l) + '" y="' + str(pad_t) + '" width="' + str(svg_w) + '" height="' + str(block_h) + '" rx="3" style="fill:var(--a2ui-border,#eaeaea)"/>'
    bx = width - pad_r + 4
    if pct is not None:
        badge = '#22c55e' if pct >= 99 else ('#f59e0b' if pct >= 95 else '#ef4444')
        svg += '<text x="' + str(bx) + '" y="' + str(pad_t + block_h // 2 + 5) + '" font-size="12" font-weight="700" fill="' + badge + '">' + pct_txt + '%</text>'
    if period:
        svg += '<text x="' + str(bx) + '" y="' + str(pad_t + block_h + 10) + '" font-size="9" style="fill:var(--a2ui-muted,#666666)">' + _cv_esc(period) + '</text>'
    svg += '</svg>'
    return '<div class="a2ui-uptime-row">' + svg + '</div>'


def _render_command_palette(b: dict) -> str:
    """Twin of _RENDERERS['command_palette'] in atoms_charts.gs. This used to be a hardcoded
    stub that drew "Command 1 / Command 2" for every payload. `text` is the documented command
    field; `name` is what the GAS renderer first read, so both work. `group` is an alias of
    `category`. The class CSS lives in the GAS/MCP Apps stylesheet, so it is inlined here."""
    commands = b.get('commands') if isinstance(b.get('commands'), list) else []
    placeholder = b.get('placeholder') or 'Search commands…'
    uid = _wa_uid(b)
    groups, order = {}, []
    for cmd in commands:
        if not isinstance(cmd, dict):
            continue
        cat = cmd.get('group') or cmd.get('category') or 'General'
        if cat not in groups:
            groups[cat] = []
            order.append(cat)
        groups[cat].append(cmd)
    h = '<div class="a2ui-cmd-palette" id="cp-' + uid + '">'
    h += '<div class="a2ui-cmd-search-wrap">'
    h += ('<svg aria-hidden="true" class="a2ui-cmd-search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5f738f" stroke-width="2">'
          '<circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>')
    h += ('<input class="a2ui-cmd-input" type="text" placeholder="' + _cv_esc(placeholder) + '"'
          ' oninput="(function(v){var items=document.querySelectorAll(\'#cp-' + uid + ' .a2ui-cmd-item\');var cats=document.querySelectorAll(\'#cp-' + uid + ' .a2ui-cmd-cat\');'
          'items.forEach(function(el){var t=el.textContent.toLowerCase();el.style.display=t.indexOf(v.toLowerCase())>-1?\'\':\'none\';});'
          'cats.forEach(function(cat){var anyVis=false;var next=cat.nextElementSibling;while(next&&!next.classList.contains(\'a2ui-cmd-cat\')){if(next.classList.contains(\'a2ui-cmd-item\')&&next.style.display!==\'none\')anyVis=true;next=next.nextElementSibling;}cat.style.display=anyVis?\'\':\'none\';});'
          '})(this.value)"/>')
    h += '</div><div class="a2ui-cmd-list">'
    for cat in order:
        h += '<div class="a2ui-cmd-cat">' + _cv_esc(cat) + '</div>'
        for cmd in groups[cat]:
            icon = cmd.get('icon')
            glyph = ''.join(list(str(icon).strip())[:4]) if icon not in (None, '') else ''
            h += '<div class="a2ui-cmd-item"' + (' data-id="' + _cv_esc(cmd.get('id')) + '"' if cmd.get('id') else '') + '>'
            if glyph:
                h += '<span aria-hidden="true">' + _cv_esc(glyph) + '</span>'
            h += '<span class="a2ui-cmd-name">' + _cv_esc(cmd.get('text') or cmd.get('name') or '') + '</span>'
            if cmd.get('description'):
                h += '<span class="a2ui-cmd-desc">' + _cv_esc(cmd['description']) + '</span>'
            if cmd.get('shortcut'):
                h += '<kbd class="a2ui-cmd-shortcut">' + _cv_esc(cmd['shortcut']) + '</kbd>'
            h += '</div>'
    h += '</div></div>'
    return '<style>.a2ui-cmd-palette{border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;background:#fff;box-shadow:0 4px 16px rgba(0,0,0,0.07);max-width:560px}.a2ui-cmd-search-wrap{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid #f1f5f9}.a2ui-cmd-search-icon{flex-shrink:0}.a2ui-cmd-input{flex:1;border:none;outline:none;font-size:14px;color:#1e293b;background:transparent;font-family:inherit}.a2ui-cmd-list{max-height:320px;overflow-y:auto}.a2ui-cmd-cat{padding:6px 14px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:var(--muted,#5f6368);background:#f8fafc;border-bottom:1px solid #f1f5f9}.a2ui-cmd-item{display:flex;align-items:center;gap:8px;padding:9px 14px;border-bottom:1px solid #f8fafc;cursor:default}.a2ui-cmd-item:hover{background:#f0f9ff}.a2ui-cmd-name{font-size:13px;font-weight:500;color:#1e293b;flex-shrink:0}.a2ui-cmd-desc{font-size:12px;color:var(--muted,#5f6368);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.a2ui-cmd-shortcut{font-size:11px;background:#f1f5f9;color:#475569;border:1px solid #cbd5e1;border-radius:4px;padding:1px 5px;font-family:monospace;flex-shrink:0}</style>' + h

def _render_search_result_card(b: dict) -> str:
    url_raw = b.get('url') if isinstance(b.get('url'), str) else ''
    safe_url = _safe_href(url_raw, schemes=('https', 'mailto'))

    favicon_raw = b.get('favicon_url') if isinstance(b.get('favicon_url'), str) else ''
    safe_favicon = _safe_href(favicon_raw, schemes=('https', 'mailto'))

    bc_list = b.get('breadcrumb') if isinstance(b.get('breadcrumb'), list) else []
    bc_strings = [_cv_esc(x) for x in bc_list if isinstance(x, str) and x]

    meta_parts = []
    if safe_favicon:
        meta_parts.append(f'<img src="{_cv_esc(safe_favicon)}" width="16" height="16" style="border-radius:3px;" onerror="this.style.display=\'none\'"/>')

    if bc_strings:
        bc_text = ' › '.join(bc_strings)
        meta_parts.append(f'<span>{bc_text}</span>')
    elif url_raw:
        meta_parts.append(f'<span>{_cv_esc(url_raw)}</span>')

    meta_row = ''
    if meta_parts:
        meta_row = f'<div style="display:flex;align-items:center;gap:6px;font-size:0.7rem;color:var(--muted,#5f6368);margin-bottom:4px;">{" ".join(meta_parts)}</div>'

    title_text = _text_loose(b.get('title'))
    title_html = ''
    if title_text:
        if safe_url:
            title_html = f'<a href="{_cv_esc(safe_url)}" target="_blank" rel="noopener noreferrer" style="font-weight:600;font-size:0.9rem;color:#7c3aed;text-decoration:none;display:inline-block;margin-bottom:4px;">{_cv_esc(title_text)}</a>'
        else:
            title_html = f'<div style="font-weight:600;font-size:0.9rem;color:#7c3aed;margin-bottom:4px;">{_cv_esc(title_text)}</div>'

    date_text = _text_loose(b.get('date'))
    desc_text = _text_loose(b.get('description'))
    desc_html = ''
    if date_text or desc_text:
        date_prefix = f'<span>{_cv_esc(date_text)} — </span>' if date_text else ''
        desc_html = f'<div style="font-size:0.8rem;color:var(--muted,#5f6368);">{date_prefix}{_cv_esc(desc_text)}</div>'

    return (
        f'<div data-cb="node" data-key="{_ck(b.get("url"), "search_result_card")}" '
        f'style="margin:1rem 0;padding:12px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);">'
        f'{meta_row}{title_html}{desc_html}</div>'
    )

def _render_punch_card(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    data_raw = b.get("data")
    if not isinstance(data_raw, list):
        data_raw = []
    data = []
    for row in data_raw:
        if isinstance(row, list):
            data.append(row[:200])
        if len(data) >= 200:
            break

    if not data or not data[0]:
        return '<div class="a2ui-punch-card"></div>'

    labels_raw = b.get("labels_days")
    if not isinstance(labels_raw, list):
        labels_raw = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    labels_days = [_text_loose(lbl) for lbl in labels_raw[:200]]
    while len(labels_days) < len(data):
        labels_days.append("")

    color = _safe_css(b.get("color"), "#00f2ff")
    title = _first_text(b.get("title"), "")
    subtitle = _first_text(b.get("subtitle"), "")

    num_rows = len(data)
    num_cols = len(data[0])

    flat_data = []
    for row in data:
        for val in row:
            num = _num_loose(val)
            flat_data.append(num if num is not None else 0.0)

    mn = min(flat_data) if flat_data else 0.0
    mx = max(flat_data) if flat_data else 0.0
    rng = (mx - mn) or 1.0

    cell_size = 28
    cell_gap = 5
    pad_l, pad_r, pad_t, pad_b = 60, 25, 40, 25

    grid_w = num_cols * cell_size + (num_cols - 1) * cell_gap
    grid_h = num_rows * cell_size + (num_rows - 1) * cell_gap

    w = pad_l + grid_w + pad_r
    h = pad_t + grid_h + pad_b

    x_labels = []
    for c_idx in range(num_cols):
        x = pad_l + c_idx * (cell_size + cell_gap) + cell_size / 2.0
        x_str = _text_loose(int(x + 0.5) if x == int(x) else _rhu(x, 1))
        lbl = f"{c_idx:02d}"
        x_labels.append(f'<text x="{x_str}" y="{pad_t - 12}" fill="rgba(255,255,255,0.4)" font-size="8" font-family="monospace" text-anchor="middle">{lbl}</text>')

    y_labels = []
    for r_idx in range(min(num_rows, len(labels_days))):
        lbl = labels_days[r_idx]
        y = pad_t + r_idx * (cell_size + cell_gap) + cell_size / 2.0 + 3.0
        y_str = _text_loose(int(y + 0.5) if y == int(y) else _rhu(y, 1))
        y_labels.append(f'<text x="{pad_l - 12}" y="{y_str}" fill="rgba(255,255,255,0.65)" font-size="9" font-family="monospace" text-anchor="end">{_cv_esc(lbl)}</text>')

    uid = f"punch-{_wa_uid(b)}"
    bubbles_html = []

    for r_idx, row in enumerate(data):
        day_lbl = labels_days[r_idx] if r_idx < len(labels_days) else ""
        for c_idx in range(num_cols):
            val_raw = row[c_idx] if c_idx < len(row) else 0.0
            val_num = _num_loose(val_raw)
            val = val_num if val_num is not None else 0.0
            x = pad_l + c_idx * (cell_size + cell_gap) + cell_size / 2.0
            y = pad_t + r_idx * (cell_size + cell_gap) + cell_size / 2.0
            x_str = _text_loose(int(x + 0.5) if x == int(x) else _rhu(x, 1))
            y_str = _text_loose(int(y + 0.5) if y == int(y) else _rhu(y, 1))

            if val <= 0:
                bubbles_html.append(f'<circle cx="{x_str}" cy="{y_str}" r="2" fill="rgba(255,255,255,0.06)" />')
                continue

            weight = (val - mn) / rng if rng > 0 else 0.5
            r = 3.0 + weight * 10.0
            opacity = 0.3 + weight * 0.7
            glow_attr = f' filter="url(#{uid}_glow)"' if weight > 0.6 else ""
            r_str = _fixed_str(r, 1)
            op_str = _fixed_str(opacity, 2)
            c_label = f"{c_idx:02d}"
            v_int = int(val + 0.5) if val >= 0 else int(val - 0.5)
            val_str = f"{v_int:,}"

            title_text = f"{day_lbl} {c_label}:00 - {val_str} commits"
            bubbles_html.append(
                f'<circle cx="{x_str}" cy="{y_str}" r="{r_str}" fill="{color}" fill-opacity="{op_str}"{glow_attr}>'
                f'<title>{_cv_esc(title_text)}</title>'
                f'</circle>'
            )

    header_html = ""
    if title or subtitle:
        title_tag = f'<div style="font-size:1.1rem;font-weight:800;color:#f1f5f9;margin-bottom:2px;">{_cv_esc(title)}</div>' if title else ""
        sub_tag = f'<div style="font-size:0.75rem;color:rgba(255,255,255,0.62);font-family:monospace;">{_cv_esc(subtitle)}</div>' if subtitle else ""
        header_html = (
            f'<div style="margin-bottom:16px;display:flex;justify-content:space-between;align-items:flex-end;">'
            f'<div>{title_tag}{sub_tag}</div>'
            f'<div style="display:flex;gap:12px;font-size:0.75rem;color:rgba(255,255,255,0.62);font-family:monospace;align-items:center;">'
            f'<span>Less</span>'
            f'<span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:{color};opacity:0.3;"></span>'
            f'<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:{color};opacity:0.6;"></span>'
            f'<span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:{color};opacity:1.0;"></span>'
            f'<span>More</span>'
            f'</div></div>'
        )

    aria_lbl = title or _first_text(b.get("label"), "Chart")
    bubbles_joined = "".join(bubbles_html)
    y_joined = "".join(y_labels)
    x_joined = "".join(x_labels)

    svg_html = (
        f'<svg role="img" aria-label="{_cv_esc(aria_lbl)}" viewBox="0 0 {w} {h}" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" style="overflow:visible;">'
        f'<defs>'
        f'<filter id="{uid}_glow" x="-30%" y="-30%" width="160%" height="140%">'
        f'<feGaussianBlur stdDeviation="2" result="blur" />'
        f'<feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>'
        f'</filter>'
        f'</defs>'
        f'{y_joined}'
        f'{x_joined}'
        f'{bubbles_joined}'
        f'</svg>'
    )

    return (
        f'<div class="a2ui-punch-card" style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">'
        f'{header_html}'
        f'<div style="width:100%;overflow-x:auto;">'
        f'<div style="min-width:{w}px;max-width:100%;height:{h}px;margin:0 auto;">'
        f'{svg_html}'
        f'</div></div></div>'
    )


# ── sankey_flow ───────────────────────────────────────────────────────────────────────────────────────────────
# Layout is a hand port of d3-sankey 0.12.3 (BSD-3-Clause, Copyright 2015 Mike Bostock; see THIRD-PARTY-NOTICES.md): node value = max(in, out),
# the 6 relaxation passes with alpha/beta, ascendingTargetBreadth / ascendingSourceBreadth link ordering, sankeyLinkHorizontal link paths.
# GAS twin: _sk* in apps-script-surface/gas-wired-renderer/atoms_charts.gs (same logic, camelCase). Server-side SVG; no script is shipped.
import functools as _sk_functools
_SK_W, _SK_H, _SK_COL_W, _SK_NODE_W, _SK_PAD, _SK_ITER, _SK_MAXCOL = 640, 340, 220, 16, 16, 6, 15
_SK_PAL = ['#38bdf8', '#10b981', '#a78bfa', '#f59e0b', '#f472b6']
_SK_SR = 'position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;'
_SK_NUM_RE = re.compile(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$')


def _sk_val(v):
    """A flow value: a finite number, a numeric string, or 1 when absent. Anything else is 0 and the flow is not drawn."""
    if v is None:
        return 1.0
    if isinstance(v, bool):
        return 0.0
    if isinstance(v, (int, float)):
        f = float(v)
        return f if f - f == 0 else 0.0
    if isinstance(v, str):
        t = v.strip(' \t\n\r\f\v ﻿')
        if _SK_NUM_RE.match(t):
            f = float(t)
            return f if f - f == 0 else 0.0
    return 0.0


def _sk_str(v):
    if isinstance(v, str):
        return v
    if isinstance(v, (int, float)) and not isinstance(v, bool) and float(v) - float(v) == 0:
        return str(int(v)) if float(v).is_integer() and abs(v) < 1e21 else repr(float(v))
    return ''


def _sk_r(x):
    x = float(x)
    if x - x != 0:
        return 0
    return int(max(-9e15, min(9e15, math.floor(x * 100 + 0.5))))


def _sk_n(x):
    """A number rounded half-up to 2 decimals, built from integers so Python and JavaScript print the same text."""
    r = _sk_r(x)
    a = abs(r)
    w, f = a // 100, a % 100
    s = str(w)
    if f:
        s += '.' + ('0' + str(f) if f < 10 else str(f))
        if f % 10 == 0:
            s = s[:-1]
    return ('-' if r < 0 else '') + s


def _sk_fmt(x):
    r = _sk_r(x)
    a = abs(r)
    w, f = a // 100, a % 100
    s = f'{w:,}'
    if f:
        s += '.' + ('0' + str(f) if f < 10 else str(f))
        if f % 10 == 0:
            s = s[:-1]
    return ('-' if r < 0 else '') + s


def _sk_hash(s):
    h = 0x811c9dc5
    b = s.encode('utf-16-le', 'surrogatepass')
    for i in range(0, len(b), 2):
        h ^= b[i] | (b[i + 1] << 8)
        h = (h * 0x01000193) & 0xffffffff
    return format(h, 'x')


def _sk_short(s):
    return s[:21] + '…' if len(s) > 22 else s


def _sk_layout(nodes, links, x0, y0, x1, y1, dx, dy, iterations):
    """d3-sankey 0.12.3 layout. nodes: [{'layer'}], links: [{'source': node, 'target': node, 'value'}].
    Sets node x0/x1/y0/y1/value and link width/y0/y1."""
    for i, n in enumerate(nodes):
        n['index'] = i
        n['sourceLinks'] = []
        n['targetLinks'] = []
    for i, l in enumerate(links):
        l['index'] = i
        l['source']['sourceLinks'].append(l)
        l['target']['targetLinks'].append(l)

    def vsum(a):
        s = 0.0
        for d in a:
            v = d['value']
            if v == v:
                s += v
        return s

    nan = float('nan')

    def asc_source(a, b):
        d = a['source'].get('y0', nan) - b['source'].get('y0', nan)    # JavaScript: NaN || index difference
        return d if d == d and d != 0 else a['index'] - b['index']

    def asc_target(a, b):
        d = a['target'].get('y0', nan) - b['target'].get('y0', nan)
        return d if d == d and d != 0 else a['index'] - b['index']

    _key_source = _sk_functools.cmp_to_key(asc_source)
    _key_target = _sk_functools.cmp_to_key(asc_target)

    for n in nodes:
        n['value'] = max(vsum(n['sourceLinks']), vsum(n['targetLinks']))
    nl = 1
    for n in nodes:
        nl = max(nl, n['layer'] + 1)
    kx = (x1 - x0 - dx) / (nl - 1) if nl > 1 else 0.0
    by_layer = {}
    for n in nodes:
        by_layer.setdefault(n['layer'], []).append(n)
        n['x0'] = x0 + n['layer'] * kx
        n['x1'] = n['x0'] + dx
    columns = [by_layer[k] for k in sorted(by_layer) if by_layer[k]]
    max_len = max((len(c) for c in columns), default=0)
    py = min(dy, (y1 - y0) / (max_len - 1) if max_len > 1 else float('inf'))

    def reorder_links(ns):
        for n in ns:
            n['sourceLinks'].sort(key=_key_target)
            n['targetLinks'].sort(key=_key_source)

    def reorder_node_links(n):
        for l in n['targetLinks']:
            l['source']['sourceLinks'].sort(key=_key_target)
        for l in n['sourceLinks']:
            l['target']['targetLinks'].sort(key=_key_source)

    ky = float('inf')
    for c in columns:
        k = (y1 - y0 - (len(c) - 1) * py) / vsum(c)
        if k < ky:
            ky = k
    for ns in columns:
        y = y0
        for n in ns:
            n['y0'] = y
            n['y1'] = y + n['value'] * ky
            y = n['y1'] + py
            for l in n['sourceLinks']:
                l['width'] = l['value'] * ky
        y = (y1 - y + py) / (len(ns) + 1)
        for i, n in enumerate(ns):
            n['y0'] += y * (i + 1)
            n['y1'] += y * (i + 1)
        reorder_links(ns)

    def target_top(source, target):
        y = source['y0'] - (len(source['sourceLinks']) - 1) * py / 2
        for l in source['sourceLinks']:
            if l['target'] is target:
                break
            y += l['width'] + py
        for l in target['targetLinks']:
            if l['source'] is source:
                break
            y -= l['width']
        return y

    def source_top(source, target):
        y = target['y0'] - (len(target['targetLinks']) - 1) * py / 2
        for l in target['targetLinks']:
            if l['source'] is source:
                break
            y += l['width'] + py
        for l in source['sourceLinks']:
            if l['target'] is target:
                break
            y -= l['width']
        return y

    def collide_down(ns, y, i, alpha):
        while i < len(ns):
            n = ns[i]
            d = (y - n['y0']) * alpha
            if d > 1e-6:
                n['y0'] += d
                n['y1'] += d
            y = n['y1'] + py
            i += 1

    def collide_up(ns, y, i, alpha):
        while i >= 0:
            n = ns[i]
            d = (n['y1'] - y) * alpha
            if d > 1e-6:
                n['y0'] -= d
                n['y1'] -= d
            y = n['y0'] - py
            i -= 1

    def resolve_collisions(ns, alpha):
        i = len(ns) >> 1
        subject = ns[i]
        collide_up(ns, subject['y0'] - py, i - 1, alpha)
        collide_down(ns, subject['y1'] + py, i + 1, alpha)
        collide_up(ns, y1, len(ns) - 1, alpha)
        collide_down(ns, y0, 0, alpha)

    def left_to_right(alpha, beta):
        for i in range(1, len(columns)):
            column = columns[i]
            for target in column:
                y = w = 0.0
                for l in target['targetLinks']:
                    v = l['value'] * (target['layer'] - l['source']['layer'])
                    y += target_top(l['source'], target) * v
                    w += v
                if not w > 0:
                    continue
                d = (y / w - target['y0']) * alpha
                target['y0'] += d
                target['y1'] += d
                reorder_node_links(target)
            column.sort(key=lambda n: n['y0'])
            resolve_collisions(column, beta)

    def right_to_left(alpha, beta):
        for i in range(len(columns) - 2, -1, -1):
            column = columns[i]
            for source in column:
                y = w = 0.0
                for l in source['sourceLinks']:
                    v = l['value'] * (l['target']['layer'] - source['layer'])
                    y += source_top(source, l['target']) * v
                    w += v
                if not w > 0:
                    continue
                d = (y / w - source['y0']) * alpha
                source['y0'] += d
                source['y1'] += d
                reorder_node_links(source)
            column.sort(key=lambda n: n['y0'])
            resolve_collisions(column, beta)

    # d3 uses Math.pow(0.99, i); the running product agrees to the last bit or two and cannot differ between Python and JavaScript.
    alpha = 1.0
    for it in range(iterations):
        beta = max(1 - alpha, (it + 1) / iterations)
        right_to_left(alpha, beta)
        left_to_right(alpha, beta)
        alpha *= 0.99
    for n in nodes:
        a = n['y0']
        b = a
        for l in n['sourceLinks']:
            l['y0'] = a + l['width'] / 2
            a += l['width']
        for l in n['targetLinks']:
            l['y1'] = b + l['width'] / 2
            b += l['width']


def _sk_model(b):
    """Reads the payload into nodes + drawable flows. Flows that cannot be drawn are listed in `dropped`: a flow on a cycle (every flow whose two
    ends can reach each other, so A->B and B->A are both listed), and a flow that would not run left to right once `column` hints and graph depth have
    placed its ends. Flows with no usable end or a value that is not positive are ignored, as are nodes left with no flow."""
    b = b if isinstance(b, dict) else {}
    raw_n = b.get('nodes') if isinstance(b.get('nodes'), list) else []
    raw_l = b.get('links') if isinstance(b.get('links'), list) else []
    ids, at, decl = [], {}, {}
    for n in raw_n:
        if not isinstance(n, dict):
            continue
        i = _sk_str(n.get('id'))
        if i == '':
            continue
        if i not in at:
            at[i] = len(ids)
            ids.append(i)
        decl[i] = n
    flows = []
    for l in raw_l:
        if not isinstance(l, dict):
            continue
        s, t, v = _sk_str(l.get('source')), _sk_str(l.get('target')), _sk_val(l.get('value'))
        if s == '' or t == '' or not v > 0:
            continue
        for i in (s, t):
            if i not in at:
                at[i] = len(ids)
                ids.append(i)
        c = l.get('color')
        flows.append({'s': at[s], 't': at[t], 'value': v, 'color': c if isinstance(c, str) and c else ''})
    N = len(ids)

    def label_of(i):
        d = decl.get(ids[i])
        if d is not None:
            lb = _sk_str(d.get('label'))
            return lb if lb != '' else ids[i]
        return ids[i][:1].upper() + ids[i][1:].lower()

    gone = [False] * len(flows)
    adj = [[] for _ in range(N)]
    for f in flows:
        adj[f['s']].append(f['t'])
    for k, f in enumerate(flows):
        seen, stack, hit = set(), [f['t']], False
        while stack and not hit:
            u = stack.pop()
            if u == f['s']:
                hit = True
                break
            if u in seen:
                continue
            seen.add(u)
            for w in adj[u]:
                if w not in seen:
                    stack.append(w)
        if hit:
            gone[k] = True
    hint = []
    for i in range(N):
        dn = decl.get(ids[i])
        c = dn.get('column') if dn else None
        ok = isinstance(c, (int, float)) and not isinstance(c, bool) and float(c) - float(c) == 0
        hint.append(min(_SK_MAXCOL, max(0, math.floor(c))) if ok else -1)
    layer, used, ncols = [], [], 2
    while True:
        live = [f for k, f in enumerate(flows) if not gone[k]]
        used = [False] * N
        for f in live:
            used[f['s']] = used[f['t']] = True
        depth, n_out = [0] * N, [0] * N
        for f in live:
            n_out[f['s']] += 1
        cur, x = [i for i in range(N) if used[i]], 0
        while cur:
            nxt, in_n = [], set()
            for u in cur:
                depth[u] = x
                for f in live:
                    if f['s'] == u and f['t'] not in in_n:
                        in_n.add(f['t'])
                        nxt.append(f['t'])
            x += 1
            cur = nxt
        md = max([depth[i] for i in range(N) if used[i]], default=0)
        mh = max([hint[i] for i in range(N) if used[i]], default=0)
        ncols = max(md + 1, mh + 1, 2)
        layer = [-1 if not used[i] else (min(hint[i], ncols - 1) if hint[i] >= 0 else (depth[i] if n_out[i] else ncols - 1)) for i in range(N)]
        bad = False
        for k, f in enumerate(flows):
            if not gone[k] and layer[f['t']] <= layer[f['s']]:
                gone[k] = True
                bad = True
        if not bad:
            break
    ncols = max(2, max(layer, default=0) + 1)
    dropped = [{'source': label_of(f['s']), 'target': label_of(f['t']), 'value': f['value']} for k, f in enumerate(flows) if gone[k]]
    nodes, pos = [], {}
    for i in range(N):
        if used[i]:
            d2 = decl.get(ids[i])
            col = d2.get('color') if d2 else None
            pos[i] = len(nodes)
            nodes.append({'id': ids[i], 'label': label_of(i), 'layer': layer[i], 'color': col if isinstance(col, str) and col else ''})
    links = [{'source': nodes[pos[f['s']]], 'target': nodes[pos[f['t']]], 'value': f['value'], 'color': f['color']} for k, f in enumerate(flows) if not gone[k]]
    W = _SK_W + _SK_COL_W * (ncols - 2)

    def room(layer_no):
        m = max([min(len(_sk_short(n['label'])), 22) for n in nodes if n['layer'] == layer_no], default=0)
        return min(190, max(60, math.ceil(m * 6.7) + 16))

    pad_l, pad_r = room(0), room(ncols - 1)
    if links:
        _sk_layout(nodes, links, pad_l, 50, W - pad_r, 300, _SK_NODE_W, _SK_PAD, _SK_ITER)
    return {'nodes': nodes, 'links': links, 'dropped': dropped, 'ncols': ncols, 'w': W, 'h': _SK_H, 'padL': pad_l, 'padR': pad_r}


def _sk_color(n):
    return n['color'] or _SK_PAL[n['layer'] % len(_SK_PAL)]


def _sk_svg(m, title, sid, keyed=False):
    g, lk, nd, tx = [], [], [], []
    seen = {}
    for i, l in enumerate(m['links']):
        s, t = l['source'], l['target']
        a, c = s['x1'], t['x0']
        mx = (a + c) / 2
        d = 'M' + _sk_n(a) + ',' + _sk_n(l['y0']) + 'C' + _sk_n(mx) + ',' + _sk_n(l['y0']) + ',' + _sk_n(mx) + ',' + _sk_n(l['y1']) + ',' + _sk_n(c) + ',' + _sk_n(l['y1'])
        if l['color']:
            stroke = _cv_esc(l['color'])
        else:
            stroke = 'url(#' + sid + 'g' + str(i) + ')'
            g.append('<linearGradient id="' + sid + 'g' + str(i) + '" gradientUnits="userSpaceOnUse" x1="' + _sk_n(a) + '" y1="0" x2="' + _sk_n(c) + '" y2="0"><stop offset="0%" stop-color="' + _cv_esc(_sk_color(s)) + '"/><stop offset="100%" stop-color="' + _cv_esc(_sk_color(t)) + '"/></linearGradient>')
        ck = ''
        if keyed:
            k0 = s['id'] + '>' + t['id']
            seen[k0] = seen.get(k0, 0) + 1
            ck = ' data-cb="link" data-key="' + _cv_esc(k0 if seen[k0] == 1 else k0 + '#' + str(seen[k0])) + '"'
        lk.append('<path class="sk-l"' + ck + ' d="' + d + '" stroke="' + stroke + '" stroke-width="' + _sk_n(max(1, l['width'])) + '"><title>' + _cv_esc(s['label']) + ' → ' + _cv_esc(t['label']) + ': ' + _sk_fmt(l['value']) + '</title></path>')
    for i, n in enumerate(m['nodes']):
        c = _sk_color(n)
        h = n['y1'] - n['y0']
        mid = n['y0'] + h / 2
        last, first = n['layer'] == m['ncols'] - 1, n['layer'] == 0
        g.append('<linearGradient id="' + sid + 'n' + str(i) + '" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="' + _cv_esc(c) + '"/><stop offset="100%" stop-color="' + _cv_esc(c) + '" stop-opacity="0.6"/></linearGradient>')
        nd.append('<rect' + (' data-cb="node" data-key="' + _cv_esc(n['id']) + '"' if keyed else '') + ' x="' + _sk_n(n['x0']) + '" y="' + _sk_n(n['y0']) + '" width="' + _sk_n(n['x1'] - n['x0']) + '" height="' + _sk_n(max(h, 1)) + '" rx="3" ry="3" fill="url(#' + sid + 'n' + str(i) + ')"><title>' + _cv_esc(n['label']) + ': ' + _sk_fmt(n['value']) + '</title></rect>')
        left = first and not last
        ax = _sk_n(n['x0'] - 8) if left else _sk_n(n['x1'] + 8)
        anc = 'end' if left else 'start'
        halo = '' if (first or last) else ' stroke="rgb(15,23,42)" stroke-width="3" stroke-linejoin="round" paint-order="stroke"'
        tx.append('<text' + (' data-cb="label" data-key="' + _cv_esc(n['id']) + '"' if keyed else '') + ' x="' + ax + '" y="' + _sk_n(mid + 4) + '" fill="#f1f5f9" font-size="11" font-weight="700" font-family="monospace" text-anchor="' + anc + '"' + halo + '>' + _cv_esc(_sk_short(n['label'])) + '</text>'
                  + '<text x="' + ax + '" y="' + _sk_n(mid + 15) + '" fill="rgba(255,255,255,0.65)" font-size="9" font-family="monospace" text-anchor="' + anc + '"' + halo + '>' + _sk_fmt(n['value']) + '</text>')
    minw = int(math.floor(m['w'] * 0.8 + 0.5))
    return ('<svg role="img" aria-label="' + _cv_esc(title or 'Sankey flow chart') + '" viewBox="0 0 ' + str(m['w']) + ' ' + str(m['h']) + '" width="100%" xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:auto;min-width:' + str(minw) + 'px;overflow:visible;">'
            + '<style>#' + sid + ' .sk-l{fill:none;stroke-opacity:0.35;transition:stroke-opacity 0.2s}#' + sid + ' .sk-l:hover{stroke-opacity:0.65}</style>'
            + '<defs>' + ''.join(g) + '</defs><g id="' + sid + '">' + ''.join(lk) + '</g>' + ''.join(nd) + ''.join(tx) + '</svg>')


def _render_sankey_flow(b: dict) -> str:
    m = _sk_model(b)
    title = _sk_str(b.get('title')) if isinstance(b, dict) else ''
    if not m['links'] and not m['dropped']:
        return ''
    head = ('<div style="margin-bottom:16px;"><div style="font-size:1.1rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px;">' + _cv_esc(title) + '</div></div>') if title else ''
    body = ''
    if m['links']:
        key = '\u0001'.join(n['id'] for n in m['nodes']) + '\u0002' + '\u0001'.join(l['source']['id'] + '\u0003' + l['target']['id'] + '\u0003' + _sk_fmt(l['value']) for l in m['links'])
        sid = 'sk' + _sk_hash(key)
        body = ('<div style="width:100%;max-width:100%;overflow-x:auto;">' + _sk_svg(m, title, sid, isinstance(b, dict) and b.get('keyed') is True) + '</div>'
                + '<table style="' + _SK_SR + '"><thead><tr><th scope="col">Source</th><th scope="col">Target</th><th scope="col">Value</th></tr></thead><tbody>'
                + ''.join('<tr><th scope="row">' + _cv_esc(l['source']['label']) + '</th><td>' + _cv_esc(l['target']['label']) + '</td><td>' + _sk_fmt(l['value']) + '</td></tr>' for l in m['links']) + '</tbody></table>')
    note = ''
    if m['dropped']:
        c = len(m['dropped'])
        note = ('<div role="note" style="margin-top:14px;padding:10px 14px;border:1px solid rgba(248,113,113,0.45);border-radius:8px;background:rgba(248,113,113,0.1);color:#fecaca;font-size:0.82rem;line-height:1.5;">'
                '<strong>' + str(c) + ' flow' + ('s' if c != 1 else '') + ' not shown.</strong> This chart draws flows from left to right; a flow that closes a cycle (A → B → A) or that would run backwards or sideways between the columns set by `column` can\'t be drawn, so it is listed here:'
                '<ul style="margin:6px 0 0;padding-left:18px;">' + ''.join('<li>' + _cv_esc(d['source']) + ' → ' + _cv_esc(d['target']) + ': ' + _sk_fmt(d['value']) + '</li>' for d in m['dropped']) + '</ul></div>')
    return ('<div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;border-radius:var(--a2ui-radius,12px);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);position:relative;max-width:100%;min-width:0;box-sizing:border-box;">'
            + head + body + note + '</div>')

def _render_cohort_retention(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    cohorts_raw = b.get("cohorts")
    cohorts = cohorts_raw if isinstance(cohorts_raw, list) else []
    periods_raw = b.get("periods")
    periods = periods_raw if isinstance(periods_raw, list) else []
    title = _first_text(b.get("title"), "")

    if not cohorts:
        return '<div class="a2ui-chart-empty">No cohort data</div>'

    # Determine max cols if periods not explicitly given
    col_names = []
    if periods:
        for p in periods[:200]:
            col_names.append(_text_loose(p))
    else:
        max_len = 0
        for c in cohorts[:200]:
            if isinstance(c, dict):
                r = c.get("retention_rates")
                if not isinstance(r, list):
                    r = c.get("data")
                if isinstance(r, list) and len(r) > max_len:
                    max_len = len(r)
        max_len = min(max_len, 200)
        for w in range(max_len):
            col_names.append(f"Week {w}")

    num_cols = len(col_names)
    scale = []
    sc_raw = b.get("color_scale")
    for sc in (sc_raw[:8] if isinstance(sc_raw, list) else []):
        if isinstance(sc, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", sc):
            scale.append((int(sc[1:3], 16), int(sc[3:5], 16), int(sc[5:7], 16)))
    if len(scale) < 2:
        scale = [(237, 233, 254), (99, 102, 241)]
    has_size = any(isinstance(c, dict) and _text_loose(c.get("original_size")) for c in cohorts[:200])

    # Table headers
    th_html = '<th class="a2ui-cohort-th" style="padding:10px 12px;text-align:left;font-weight:700;color:#64748b;border-bottom:1px solid #e2e8f0;font-size:0.75rem;text-transform:uppercase;letter-spacing:0.05em;">Cohort</th>'
    if has_size:
        th_html += '<th class="a2ui-cohort-th" style="padding:10px 12px;text-align:right;font-weight:700;color:#64748b;border-bottom:1px solid #e2e8f0;font-size:0.75rem;text-transform:uppercase;letter-spacing:0.05em;">Size</th>'
    for cname in col_names:
        th_html += f'<th class="a2ui-cohort-th" style="padding:10px 12px;text-align:center;font-weight:700;color:#64748b;border-bottom:1px solid #e2e8f0;font-size:0.75rem;text-transform:uppercase;letter-spacing:0.05em;">{_cv_esc(cname)}</th>'

    rows_html = ""
    for c in cohorts[:200]:
        if not isinstance(c, dict):
            continue
        c_name = _first_text(c.get("cohort_name"), c.get("label"), "")
        rates_raw = c.get("retention_rates")
        if not isinstance(rates_raw, list):
            rates_raw = c.get("data")
        rates = rates_raw if isinstance(rates_raw, list) else []

        cells = f'<td class="a2ui-cohort-label" style="padding:10px 12px;font-weight:600;color:#1e293b;border-bottom:1px solid #f1f5f9;white-space:nowrap;">{_cv_esc(c_name)}</td>'
        if has_size:
            sz = _num_loose(c.get("original_size"))
            sz_txt = (f"{int(max(sz, 0.0) + 0.5):,}" if sz < 1e15 else "") if sz is not None else _text_loose(c.get("original_size"))
            cells += f'<td class="a2ui-cohort-size" style="padding:10px 12px;text-align:right;font-family:monospace;color:#64748b;border-bottom:1px solid #f1f5f9;">{_cv_esc(sz_txt)}</td>'
        for idx in range(num_cols):
            val_num = None
            if idx < len(rates):
                val_num = _num_loose(rates[idx])
            if val_num is None:
                cells += '<td class="a2ui-cohort-cell" style="padding:8px;background:#f8fafc;border-bottom:1px solid #f1f5f9;"></td>'
            else:
                pct = max(0.0, min(100.0, float(val_num)))
                alpha = pct / 100.0
                pos = alpha * (len(scale) - 1)
                lo = min(int(pos), len(scale) - 2)
                fr = pos - lo
                r, g, bv = [int(scale[lo][k] + (scale[lo + 1][k] - scale[lo][k]) * fr + 0.5) for k in range(3)]
                bg = f"rgb({r},{g},{bv})"
                fg = "#ffffff" if (0.299 * r + 0.587 * g + 0.114 * bv) / 255.0 < 0.64 else "#2e3b4d"
                pct_str = _fixed_str(pct, 1)
                cells += f'<td class="a2ui-cohort-cell" style="padding:8px;text-align:center;font-family:monospace;font-weight:700;font-size:0.8rem;background:{bg};color:{fg};border-bottom:1px solid #f1f5f9;">{pct_str}%</td>'
        rows_html += f"<tr>{cells}</tr>"

    title_html = f'<div class="a2ui-cohort-title" style="font-size:1rem;font-weight:700;color:#0f172a;margin-bottom:12px;">{_cv_esc(title)}</div>' if title else ""

    return (
        f'<div class="a2ui-cohort-retention" style="margin:1.5rem 0;padding:16px;background:#ffffff;border:1px solid #e2e8f0;border-radius:12px;">'
        f'{title_html}'
        f'<div style="overflow-x:auto;">'
        f'<table class="a2ui-cohort-table" style="border-collapse:collapse;font-size:12px;width:100%;min-width:320px;">'
        f'<thead><tr>{th_html}</tr></thead>'
        f'<tbody>{rows_html}</tbody>'
        f'</table></div></div>'
    )


def _render_task_list(b: dict) -> str:
    title = b.get("title", "")
    tasks = b.get("tasks", [])
    
    header_html = ""
    if title:
        header_html = f"""
        <div style="margin-bottom:20px; display:flex; align-items:center; justify-content:space-between;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#00f2ff; font-weight:900;">⬡</span> {_cv_esc(title)}
          </div>
          <div style="font-size:0.75rem; font-family:monospace; color:rgba(255,255,255,0.4); background:rgba(255,255,255,0.04); padding:4px 8px; border-radius:12px;border-radius:var(--a2ui-radius,12px); border:1px solid rgba(255,255,255,0.06);">
            {len(tasks)} Tasks
          </div>
        </div>
        """
        
    tasks_html = []
    for task in tasks:
        text = task.get("text", "")
        completed = task.get("completed", False)
        priority = task.get("priority", "medium").lower()
        due_date = task.get("due_date", "")
        assignee = task.get("assignee", "")
        
        if completed:
            checkbox_style = "background:#10b981; border-color:#10b981; color:#0f172a; box-shadow: 0 0 10px rgba(16,185,129,0.4);"
            checkbox_inner = '<span style="font-size:11px; font-weight:900;">✓</span>'
            text_style = "text-decoration:line-through; color:rgba(255,255,255,0.4);"
        else:
            checkbox_style = "background:rgba(255,255,255,0.03); border-color:rgba(255,255,255,0.2); color:transparent;"
            checkbox_inner = ""
            text_style = "color:#f3f4f6;"
            
        if priority == "high":
            p_style = "background:rgba(239, 68, 68, 0.1); color:#ef4444; border: 1px solid rgba(239,68,68,0.25);"
            p_label = "HIGH"
        elif priority == "low":
            p_style = "background:rgba(59, 130, 246, 0.1); color:#3b82f6; border: 1px solid rgba(59,130,246,0.25);"
            p_label = "LOW"
        else:
            p_style = "background:rgba(245, 158, 11, 0.1); color:#f59e0b; border: 1px solid rgba(245,158,11,0.25);"
            p_label = "MED"
            
        assignee_html = ""
        if assignee:
            assignee_html = f"""
            <div style="width:24px; height:24px; border-radius:50%; background:linear-gradient(135deg, #00f2ff 0%, #0072ff 100%); display:flex; align-items:center; justify-content:center; font-size:10px; font-weight:800; color:#fff; font-family:monospace; border:1px solid rgba(255,255,255,0.2); flex-shrink:0;" title="Assignee: {_cv_esc(assignee)}">
              {_cv_esc(assignee[:2].upper())}
            </div>
            """
            
        due_html = ""
        if due_date:
            due_html = f"""
            <div style="font-size:0.75rem; font-family:monospace; color:rgba(255,255,255,0.5); display:flex; align-items:center; gap:4px; padding:3px 8px; border-radius:4px; background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.04); flex-shrink:0;">
              <span style="font-size:0.7rem;">📅</span> {_cv_esc(due_date)}
            </div>
            """
            
        tasks_html.append(f"""
        <div style="display:flex; align-items:center; justify-content:space-between; padding:12px 16px; background:rgba(15,23,42,0.2); border:1px solid rgba(255,255,255,0.04); border-radius:8px; gap:16px; transition:all 0.2s ease-in-out;" onmouseover="this.style.background='rgba(255,255,255,0.03)';this.style.borderColor='rgba(0,242,255,0.15)';" onmouseout="this.style.background='rgba(15,23,42,0.2)';this.style.borderColor='rgba(255,255,255,0.04)';">
          <div style="display:flex; align-items:center; gap:12px; flex-grow:1; min-width:0;">
            <div style="width:18px; height:18px; border-radius:4px; border:1.5px solid; display:flex; align-items:center; justify-content:center; flex-shrink:0; cursor:pointer; transition:all 0.15s ease-in-out; {checkbox_style}">
              {checkbox_inner}
            </div>
            <div style="font-size:0.9rem; font-weight:500; font-family:sans-serif; text-overflow:ellipsis; overflow:hidden; white-space:nowrap; {text_style}">
              {_cv_esc(text)}
            </div>
          </div>
          
          <div style="display:flex; align-items:center; gap:10px; flex-shrink:0;">
            <div style="font-size:0.65rem; font-weight:800; font-family:monospace; padding:3px 6px; border-radius:4px; letter-spacing:0.05em; {p_style}">
              {p_label}
            </div>
            {due_html}
            {assignee_html}
          </div>
        </div>
        """)
        
    tasks_container = f'<div style="display:flex; flex-direction:column; gap:8px;">{"".join(tasks_html)}</div>'
    
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {header_html}
      {tasks_container}
    </div>
    """


def _render_sentiment_summary(b: dict) -> str:
    title = b.get("title", "")
    sentiment_index = b.get("sentiment_index", 75)
    emotional_journey = b.get("emotional_journey", [])
    themes = b.get("themes", [])
    
    header_html = ""
    if title:
        header_html = f"""
        <div style="margin-bottom:20px;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#ec4899; font-weight:900;">⬡</span> {_cv_esc(title)}
          </div>
        </div>
        """
        
    gauge_id = f"sent_gauge_{_wa_oid(b)}"
    stroke_dasharray = 109.956
    stroke_dashoffset = stroke_dasharray - (sentiment_index / 100.0) * stroke_dasharray
    
    if sentiment_index >= 75:
        sentiment_color = "#0c855d"
        sentiment_label = "POSITIVE"
    elif sentiment_index >= 50:
        sentiment_color = "#38bdf8"
        sentiment_label = "BALANCED"
    else:
        sentiment_color = "#f59e0b"
        sentiment_label = "ATTENTION"
        
    gauge_svg = f"""
    <div style="width:160px; height:140px; display:flex; flex-direction:column; align-items:center; justify-content:center; background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.04); border-radius:12px; padding:10px; flex-shrink:0;">
      <svg viewBox="0 0 100 80" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="{gauge_id}_grad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#f59e0b" />
            <stop offset="50%" stop-color="#38bdf8" />
            <stop offset="100%" stop-color="#0c855d" />
          </linearGradient>
          <filter id="{gauge_id}_glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="2" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <path d="M 15 60 A 35 35 0 0 1 85 60" fill="none" stroke="rgba(255,255,255,0.06)" stroke-width="8" stroke-linecap="round" />
        <path d="M 15 60 A 35 35 0 0 1 85 60" fill="none" stroke="url(#{gauge_id}_grad)" stroke-width="8" stroke-linecap="round"
              stroke-dasharray="{stroke_dasharray}" stroke-dashoffset="{stroke_dashoffset}" filter="url(#{gauge_id}_glow)" />
        <text x="50" y="53" text-anchor="middle" font-weight="900" font-size="18" fill="#f1f5f9" font-family="monospace">{_cv_esc(sentiment_index)}%</text>
        <text x="50" y="70" text-anchor="middle" font-weight="800" font-size="7" fill="{sentiment_color}" font-family="monospace" letter-spacing="0.1em">{sentiment_label}</text>
      </svg>
    </div>
    """
    
    journey_svg = ""
    if emotional_journey:
        points = []
        width = 280
        height = 120
        n_points = len(emotional_journey)
        center_y = height / 2.0
        x_min = 15
        x_max = width - 15
        y_min = 15
        y_max = height - 15
        
        for i, val in enumerate(emotional_journey):
            x = x_min + (i / max(1, n_points - 1)) * (x_max - x_min)
            y = center_y - val * (center_y - y_min)
            points.append((x, y))
            
        line_path = " ".join(f"{'M' if i == 0 else 'L'} {px:.1f} {py:.1f}" for i, (px, py) in enumerate(points))
        
        area_points = list(points)
        area_points.append((points[-1][0], center_y))
        area_points.append((points[0][0], center_y))
        area_path = " ".join(f"{'M' if i == 0 else 'L'} {px:.1f} {py:.1f}" for i, (px, py) in enumerate(area_points)) + " Z"
        
        journey_id = f"sent_journey_{_wa_oid(b)}"
        
        journey_svg = f"""
        <div style="flex-grow:1; height:140px; background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.04); border-radius:12px; padding:10px; display:flex; flex-direction:column; justify-content:space-between; min-width:240px;">
          <div style="font-size:0.7rem; font-family:monospace; color:rgba(255,255,255,0.4); text-transform:uppercase; letter-spacing:0.05em; margin-bottom:4px;">Emotional Journey (Timeline)</div>
          <div style="width:100%; height:110px;">
            <svg viewBox="0 0 {width} {height}" width="100%" height="100%" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
              <defs>
                <linearGradient id="{journey_id}_line_grad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stop-color="#0c855d" />
                  <stop offset="50%" stop-color="#38bdf8" />
                  <stop offset="100%" stop-color="#ef4444" />
                </linearGradient>
                <linearGradient id="{journey_id}_area_grad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stop-color="#0c855d" stop-opacity="0.25" />
                  <stop offset="50%" stop-color="#38bdf8" stop-opacity="0.1" />
                  <stop offset="100%" stop-color="#ef4444" stop-opacity="0.02" />
                </linearGradient>
                <filter id="{journey_id}_glow" x="-10%" y="-10%" width="120%" height="120%">
                  <feGaussianBlur stdDeviation="1.5" result="blur" />
                  <feMerge>
                    <feMergeNode in="blur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>
              <line x1="{x_min}" y1="{center_y}" x2="{x_max}" y2="{center_y}" stroke="rgba(255,255,255,0.15)" stroke-dasharray="3,3" stroke-width="1" />
              <path d="{area_path}" fill="url(#{journey_id}_area_grad)" />
              <path d="{line_path}" stroke="url(#{journey_id}_line_grad)" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round" filter="url(#{journey_id}_glow)" />
              <text x="{x_max}" y="{y_min+4}" text-anchor="end" font-size="8" fill="#0c855d" font-family="monospace">Positive</text>
              <text x="{x_max}" y="{center_y-4}" text-anchor="end" font-size="8" fill="rgba(255,255,255,0.3)" font-family="monospace">Neutral</text>
              <text x="{x_max}" y="{y_max-4}" text-anchor="end" font-size="8" fill="#ef4444" font-family="monospace">Negative</text>
            </svg>
          </div>
        </div>
        """
        
    themes_html = []
    for theme in themes:
        theme_name = theme.get("theme", "")
        mood = theme.get("mood", "")
        score = theme.get("score", 50)
        
        if mood.lower() in ("analytical", "calm", "neutral"):
            theme_color = "#38bdf8"
        elif mood.lower() in ("engaged", "excited", "happy", "positive"):
            theme_color = "#0c855d"
        elif mood.lower() in ("hesitant", "skeptical", "concerned", "negative"):
            theme_color = "#f59e0b"
        else:
            theme_color = "#a7f3d0"
            
        themes_html.append(f"""
        <div style="display:flex; flex-direction:column; gap:4px; padding:8px 12px; background:rgba(255,255,255,0.01); border:1px solid rgba(255,255,255,0.03); border-radius:6px;">
          <div style="display:flex; align-items:center; justify-content:space-between; font-size:0.8rem;">
            <div style="font-weight:600; color:#f1f5f9; text-overflow:ellipsis; overflow:hidden; white-space:nowrap; max-width:70%;">{_cv_esc(theme_name)}</div>
            <div style="font-size:0.7rem; font-family:monospace; color:{theme_color}; background:rgba(255,255,255,0.03); padding:1px 6px; border-radius:4px; border:1px solid rgba(255,255,255,0.05); text-transform:uppercase;">{_cv_esc(mood)}</div>
          </div>
          <div style="width:100%; height:4px; background:rgba(255,255,255,0.04); border-radius:2px; overflow:hidden;">
            <div style="width:{_cv_esc(score)}%; height:100%; background:{theme_color}; border-radius:2px; box-shadow:0 0 4px {theme_color};"></div>
          </div>
        </div>
        """)
        
    themes_container = ""
    if themes:
        themes_container = f"""
        <div style="display:flex; flex-direction:column; gap:8px;">
          <div style="font-size:0.7rem; font-family:monospace; color:rgba(255,255,255,0.4); text-transform:uppercase; letter-spacing:0.05em; margin-bottom:4px;">Top Moods & Themes Analysis</div>
          <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap:10px;">
            {"".join(themes_html)}
          </div>
        </div>
        """
        
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px); display:flex; flex-direction:column; gap:20px;">
      {header_html}
      <div style="display:flex; flex-wrap:wrap; gap:16px;">
        {gauge_svg}
        {journey_svg}
      </div>
      {themes_container}
    </div>
    """


def _render_conversion_funnel(b: dict) -> str:
    title = b.get("title", "")
    steps = b.get("steps", [])
    if not steps:
        return ""
        
    header_html = ""
    if title:
        header_html = f"""
        <div style="margin-bottom:20px; display:flex; align-items:center; justify-content:space-between;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#10b981; font-weight:900;">▼</span> {_cv_esc(title)}
          </div>
        </div>
        """
        
    # Standard width 480, height 260
    w, h = 480, 260
    pad_l, pad_r, pad_t, pad_b = 30, 30, 20, 20
    draw_w = w - pad_l - pad_r
    draw_h = h - pad_t - pad_b
    
    n_steps = len(steps)
    step_h = draw_h / max(1, n_steps)
    bar_h = step_h * 0.75
    
    max_val = max(float(s.get("value", 1)) for s in steps)
    
    funnel_id = f"funnel_{_wa_oid(b)}"
    elements = []
    
    # Render defs for neon glow & linear gradients
    elements.append(f"""
      <defs>
        <linearGradient id="{funnel_id}_grad" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stop-color="#10b981" stop-opacity="0.3" />
          <stop offset="50%" stop-color="#00f2ff" stop-opacity="0.15" />
          <stop offset="100%" stop-color="#10b981" stop-opacity="0.3" />
        </linearGradient>
        <filter id="{funnel_id}_glow" x="-10%" y="-10%" width="120%" height="120%">
          <feGaussianBlur stdDeviation="3" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
    """)
    
    for i, step in enumerate(steps):
        name = step.get("stage", "")
        val = float(step.get("value", 0))
        
        curr_ratio = val / max_val if max_val > 0 else 1.0
        
        next_ratio = curr_ratio
        if i + 1 < n_steps:
            next_ratio = float(steps[i+1].get("value", 0)) / max_val if max_val > 0 else 1.0
            
        y1 = pad_t + i * step_h
        y2 = y1 + bar_h
        
        half_w1 = (curr_ratio * draw_w) / 2.0
        half_w2 = (next_ratio * draw_w) / 2.0
        cx = pad_l + draw_w / 2.0
        
        x1_top = cx - half_w1
        x2_top = cx + half_w1
        x1_bot = cx - half_w2
        x2_bot = cx + half_w2
        
        pts = f"{x1_top:.1f},{y1:.1f} {x2_top:.1f},{y1:.1f} {x2_bot:.1f},{y2:.1f} {x1_bot:.1f},{y2:.1f}"
        
        leak_html = ""
        if i > 0:
            prev_val = float(steps[i-1].get("value", 1))
            drop_percent = ((prev_val - val) / prev_val) * 100 if prev_val > 0 else 0
            if drop_percent > 5:
                leak_html += f"""
                <path d="M {x1_top - 10:.1f} {y1 - 5:.1f} Q {x1_top - 25:.1f} {y1 + 10:.1f} {x1_top - 35:.1f} {y1 + 5:.1f}" fill="none" stroke="#ef4444" stroke-width="1.5" stroke-dasharray="2,2" />
                <polygon points="{x1_top - 35:.1f},{y1 + 2:.1f} {x1_top - 40:.1f},{y1 + 8:.1f} {x1_top - 32:.1f},{y1 + 8:.1f}" fill="#ef4444" />
                <text x="{x1_top - 42:.1f}" y="{y1 + 12:.1f}" fill="#ef4444" font-size="7.5" font-family="monospace" text-anchor="end">-{drop_percent:.0f}%</text>
                """
        
        percent_label = f"{val:,.0f}"
        if i > 0:
            first_val = float(steps[0].get("value", 1))
            retention = (val / first_val) * 100 if first_val > 0 else 100
            percent_label += f" ({retention:.0f}%)"
            
        elements.append(f"""
        <polygon points="{pts}" fill="url(#{funnel_id}_grad)" stroke="#00f2ff" stroke-width="1.5" filter="url(#{funnel_id}_glow)" style="transition:all 0.2s;" />
        <text x="{cx:.1f}" y="{y1 + bar_h / 2.0 + 3:.1f}" fill="#f1f5f9" font-size="9.5" font-weight="800" font-family="monospace" text-anchor="middle">{_cv_esc(name)}: {percent_label}</text>
        {leak_html}
        """)
        
    svg_content = f"""
    <div style="width:100%; height:260px; background:rgba(255,255,255,0.01); border:1px solid rgba(255,255,255,0.03); border-radius:12px; padding:12px; box-sizing:border-box;">
      <svg role="img" aria-label="{_cv_esc(b.get('title') or b.get('label') or 'Chart')}" viewBox="0 0 {w} {h}" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
        {"".join(elements)}
      </svg>
    </div>
    """
    
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {header_html}
      {svg_content}
    </div>
    """


def _render_gauge_sla(b: dict) -> str:
    import math
    title = b.get("title", "")
    val = float(b.get("value", 0))
    max_val = float(b.get("max_value", 100))
    unit = b.get("unit", "")
    label = b.get("label", "SLA Status")
    
    header_html = ""
    if title:
        header_html = f"""
        <div style="margin-bottom:15px; display:flex; align-items:center; justify-content:space-between;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#00f2ff; font-weight:900;">◵</span> {_cv_esc(title)}
          </div>
        </div>
        """
        
    pct = (val / max_val) * 100 if max_val > 0 else 0
    pct = min(100.0, max(0.0, pct))
    
    path_len = 314.159
    dash_offset = path_len - (pct / 100.0) * path_len
    
    angle = 180 + (pct / 100.0) * 180
    rad = math.radians(angle)
    nx = 150 + 85 * math.cos(rad)
    ny = 140 + 85 * math.sin(rad)
    
    gauge_id = f"gauge_sla_{_wa_oid(b)}"
    
    if pct >= 95:
        status_color = "#10b981"
        status_label = "HEALTHY"
    elif pct >= 85:
        status_color = "#38bdf8"
        status_label = "WARNING"
    else:
        status_color = "#ef4444"
        status_label = "BREACHED"
        
    svg_html = f"""
    <div style="width:100%; height:200px; display:flex; justify-content:center; align-items:center;">
      <svg role="img" aria-label="SLA gauge" viewBox="0 0 300 180" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="{gauge_id}_grad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#ef4444" />
            <stop offset="60%" stop-color="#f59e0b" />
            <stop offset="100%" stop-color="#10b981" />
          </linearGradient>
          <filter id="{gauge_id}_glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="3" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        
        <path d="M 50 140 A 100 100 0 0 1 250 140" fill="none" stroke="rgba(255,255,255,0.04)" stroke-width="14" stroke-linecap="round" />
        
        <path d="M 50 140 A 100 100 0 0 1 250 140" fill="none" stroke="url(#{gauge_id}_grad)" stroke-width="14" stroke-linecap="round"
              stroke-dasharray="{path_len}" stroke-dashoffset="{dash_offset}" filter="url(#{gauge_id}_glow)" />
              
        <line x1="50" y1="140" x2="60" y2="140" stroke="rgba(255,255,255,0.2)" stroke-width="2" />
        <line x1="150" y1="40" x2="150" y2="50" stroke="rgba(255,255,255,0.2)" stroke-width="2" />
        <line x1="240" y1="140" x2="250" y2="140" stroke="rgba(255,255,255,0.2)" stroke-width="2" />
        
        <line x1="150" y1="140" x2="{nx:.1f}" y2="{ny:.1f}" stroke="{status_color}" stroke-width="3" stroke-linecap="round" filter="url(#{gauge_id}_glow)" />
        <circle cx="150" cy="140" r="8" fill="#0f172a" stroke="{status_color}" stroke-width="3" />
        
        <text x="150" y="115" text-anchor="middle" font-size="24" font-weight="900" fill="#f1f5f9" font-family="monospace">{val:,.1f}{_cv_esc(unit)}</text>
        <text x="150" y="132" text-anchor="middle" font-size="8" font-weight="800" fill="{status_color}" font-family="monospace" letter-spacing="0.1em">{status_label} · {_cv_esc(label.upper())}</text>
      </svg>
    </div>
    """
    
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {header_html}
      {svg_html}
    </div>
    """


_CALIBRATION_PALETTE = ["#8b5cf6", "#dc2626", "#0891b2", "#16a34a", "#d97706", "#db2777"]


def _svg_calibration_plot(b: dict, tokens: dict) -> str:
    series = [x for x in (b.get("series") or []) if isinstance(x, dict) and x.get("points")]
    if not series:
        return ""

    w, h = 520, 300
    pad_l, pad_r, pad_t, pad_b = 55, 20, 20, 45
    chart_w = w - pad_l - pad_r
    chart_h = h - pad_t - pad_b
    oid = _wa_oid(b)

    def px(v):
        return pad_l + max(0.0, min(1.0, v)) * chart_w

    def py(v):
        return pad_t + (1 - max(0.0, min(1.0, v))) * chart_h

    grid = ""
    for i in range(5):
        frac = i / 4.0
        gx, gy = pad_l + frac * chart_w, pad_t + frac * chart_h
        grid += (f'<line x1="{pad_l}" y1="{gy:.1f}" x2="{pad_l + chart_w}" y2="{gy:.1f}" '
                f'stroke="{tokens["border"]}" stroke-dasharray="2,3" />'
                f'<text x="{pad_l - 10}" y="{gy + 3:.1f}" fill="{tokens["dim"]}" font-size="9" '
                f'font-family="ui-monospace,monospace" text-anchor="end">{1 - frac:.2f}</text>'
                f'<line x1="{gx:.1f}" y1="{pad_t}" x2="{gx:.1f}" y2="{pad_t + chart_h}" '
                f'stroke="{tokens["border"]}" stroke-dasharray="2,3" />'
                f'<text x="{gx:.1f}" y="{pad_t + chart_h + 16}" fill="{tokens["dim"]}" font-size="9" '
                f'font-family="ui-monospace,monospace" text-anchor="middle">{frac:.2f}</text>')

    diagonal = (f'<line x1="{px(0):.1f}" y1="{py(0):.1f}" x2="{px(1):.1f}" y2="{py(1):.1f}" '
               f'stroke="{tokens["dim"]}" stroke-width="1.5" stroke-dasharray="5,4" />')

    points_html, legend_html = [], []
    for i, s in enumerate(series):
        color = s.get("color") or _CALIBRATION_PALETTE[i % len(_CALIBRATION_PALETTE)]
        label = _esc(s.get("label", f"Series {i + 1}"))
        for pt in s["points"]:
            if not isinstance(pt, dict) or "predicted" not in pt or "observed" not in pt:
                continue
            cx, cy = px(pt["predicted"]), py(pt["observed"])
            r = 4.5
            if pt.get("n"):
                r = max(3.5, min(9.0, 3.5 + (pt["n"] ** 0.5) * 0.4))
            if pt.get("ci_low") is not None and pt.get("ci_high") is not None:
                y_lo, y_hi = py(pt["ci_low"]), py(pt["ci_high"])
                points_html.append(f'<line x1="{cx:.1f}" y1="{y_lo:.1f}" x2="{cx:.1f}" y2="{y_hi:.1f}" '
                                   f'stroke="{_cv_esc(color)}" stroke-width="1.5" opacity="0.55" />')
            points_html.append(f'<circle cx="{cx:.1f}" cy="{cy:.1f}" r="{r:.1f}" fill="{_cv_esc(color)}" '
                               f'fill-opacity="0.85" stroke="{tokens["surface"]}" stroke-width="1.2" />')
        legend_html.append(f'<span style="display:inline-flex;align-items:center;gap:6px;margin-right:14px;">'
                           f'<span style="width:9px;height:9px;border-radius:50%;background:{_cv_esc(color)};display:inline-block;"></span>'
                           f'<span style="font-size:12px;color:{tokens["dim"]};">{label}</span></span>')

    x_label = _esc(b.get("x_label", "Predicted probability"))
    y_label = _esc(b.get("y_label", "Observed accuracy"))
    svg = (f'<svg viewBox="0 0 {w} {h}" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">'
          f'{grid}{diagonal}{"".join(points_html)}'
          f'<text x="{pad_l + chart_w / 2:.1f}" y="{h - 4}" fill="{tokens["dim"]}" font-size="10" '
          f'text-anchor="middle" letter-spacing="0.03em">{x_label}</text>'
          f'<text x="14" y="{pad_t + chart_h / 2:.1f}" fill="{tokens["dim"]}" font-size="10" '
          f'text-anchor="middle" letter-spacing="0.03em" '
          f'transform="rotate(-90 14 {pad_t + chart_h / 2:.1f})">{y_label}</text>'
          f'</svg>')
    return svg, "".join(legend_html)


def _render_calibration_plot(b: dict) -> str:
    """Reliability diagram: predicted probability vs observed accuracy, a dashed
    diagonal for perfect calibration, optional confidence-interval bars and
    multiple colour-coded series. Point radius grows with `n` (sample size)
    when given, so a bin backed by more evidence visibly stands out. Answers
    a question a plain scatter/line/bar chart can't: is this model's own
    confidence trustworthy, or just confident?"""
    tokens = _theme_tokens(b.get("theme"))
    result = _svg_calibration_plot(b, tokens)
    if not result:
        return ""
    svg, legend = result
    title = b.get("title", "")
    title_html = (f'<div style="font-size:1.05rem;font-weight:700;color:{tokens["text"]};margin-bottom:4px;">'
                  f'{_esc(title)}</div>' if title else "")
    legend_html = f'<div style="margin-top:8px;">{legend}</div>' if legend else ""
    return (f'<div style="margin:1.5rem 0;padding:20px;background:{tokens["surface2"]};'
           f'border:1px solid {tokens["border"]};border-radius:12px;">'
           f'{title_html}<div style="width:100%;height:280px;">{svg}</div>{legend_html}</div>')


def _render_scatter_trend(b: dict) -> str:
    title = b.get("title", "")
    data_points = b.get("data_points", [])
    label_x = b.get("label_x", "X Axis")
    label_y = b.get("label_y", "Y Axis")
    
    header_html = ""
    if title:
        header_html = f"""
        <div style="margin-bottom:20px; display:flex; align-items:center; justify-content:space-between;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#10b981; font-weight:900;">⬡</span> {_cv_esc(title)}
          </div>
        </div>
        """
        
    if not data_points:
        return ""
        
    w, h = 520, 240
    pad_l, pad_r, pad_t, pad_b = 55, 25, 30, 45
    chart_w = w - pad_l - pad_r
    chart_h = h - pad_t - pad_b
    
    xs = [float(p[0]) for p in data_points]
    ys = [float(p[1]) for p in data_points]
    
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    
    rng_x = (max_x - min_x) or 1.0
    rng_y = (max_y - min_y) or 1.0
    
    n = len(data_points)
    sum_x = sum(xs)
    sum_y = sum(ys)
    sum_xy = sum(x*y for x, y in data_points)
    sum_xx = sum(x*x for x in xs)
    
    denom = (n * sum_xx - sum_x * sum_x)
    if denom != 0:
        m = (n * sum_xy - sum_x * sum_y) / denom
        c = (sum_y - m * sum_x) / n
    else:
        m = 0.0
        c = sum_y / n
        
    x1_val = min_x
    y1_val = m * x1_val + c
    x2_val = max_x
    y2_val = m * x2_val + c
    
    x1_proj = pad_l + ((x1_val - min_x) / rng_x) * chart_w
    y1_proj = pad_t + (1 - (y1_val - min_y) / rng_y) * chart_h
    x2_proj = pad_l + ((x2_val - min_x) / rng_x) * chart_w
    y2_proj = pad_t + (1 - (y2_val - min_y) / rng_y) * chart_h
    
    grid_lines = ""
    for grid_idx in range(5):
        grid_y = pad_t + (grid_idx / 4) * chart_h
        grid_v = max_y - (grid_idx / 4) * rng_y
        grid_lines += f"""
        <line x1="{pad_l}" y1="{grid_y}" x2="{pad_l + chart_w}" y2="{grid_y}" stroke="rgba(255,255,255,0.05)" stroke-dasharray="3,3" />
        <text x="{pad_l - 12}" y="{grid_y + 3}" fill="rgba(255,255,255,0.4)" font-size="8.5" font-family="monospace" text-anchor="end">{grid_v:,.1f}</text>
        """
        
    for tick_idx in range(5):
        tick_ratio = tick_idx / 4
        tick_x = pad_l + tick_ratio * chart_w
        tick_v = min_x + tick_ratio * rng_x
        grid_lines += f"""
        <line x1="{tick_x}" y1="{pad_t}" x2="{tick_x}" y2="{pad_t + chart_h}" stroke="rgba(255,255,255,0.03)" stroke-width="1" />
        <text x="{tick_x}" y="{pad_t + chart_h + 16}" fill="rgba(255,255,255,0.4)" font-size="8.5" font-family="monospace" text-anchor="middle">{tick_v:,.1f}</text>
        """
        
    dots_html = []
    for i, (px, py) in enumerate(data_points):
        cx = pad_l + ((px - min_x) / rng_x) * chart_w
        cy = pad_t + (1 - (py - min_y) / rng_y) * chart_h
        dots_html.append(f"""
        <circle cx="{cx:.1f}" cy="{cy:.1f}" r="4.5" fill="#10b981" stroke="#fff" stroke-width="1.5" filter="url(#scatter_glow_{_wa_oid(b)})" style="cursor:pointer;" />
        """)
        
    svg_html = f"""
    <div style="width:100%; height:240px; background:rgba(255,255,255,0.01); border:1px solid rgba(255,255,255,0.03); border-radius:12px; padding:12px; box-sizing:border-box;">
      <svg role="img" aria-label="{_cv_esc(b.get('title') or b.get('label') or 'Chart')}" viewBox="0 0 {w} {h}" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <filter id="scatter_glow_{_wa_oid(b)}" x="-30%" y="-30%" width="160%" height="160%">
            <feGaussianBlur stdDeviation="2" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        
        {grid_lines}
        
        <text x="{pad_l + chart_w / 2.0}" y="{pad_t + chart_h + 34}" fill="rgba(255,255,255,0.5)" font-size="9" font-family="monospace" text-anchor="middle" letter-spacing="0.05em">{_cv_esc(label_x.upper())}</text>
        
        <line x1="{x1_proj:.1f}" y1="{y1_proj:.1f}" x2="{x2_proj:.1f}" y2="{y2_proj:.1f}" stroke="#00f2ff" stroke-width="2.5" stroke-dasharray="4,4" filter="url(#scatter_glow_{_wa_oid(b)})" />
        
        {"".join(dots_html)}
      </svg>
    </div>
    """
    
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {header_html}
      {svg_html}
    </div>
    """


def _render_call_mood_board(b: dict) -> str:
    title = b.get("title", "")
    moods = b.get("moods", [])
    themes = b.get("themes", [])
    summary = b.get("summary", "")
    
    header_html = ""
    if title:
        header_html = f"""
        <div style="margin-bottom:20px; display:flex; align-items:center; justify-content:space-between;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#d946ef; font-weight:900;">⬡</span> {_cv_esc(title)}
          </div>
        </div>
        """
        
    moods_html = []
    for mood in moods:
        name = mood.get("mood", "")
        intensity = mood.get("intensity", 50)
        color = mood.get("color", "#d946ef")
        moods_html.append(f"""
        <div style="background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.04); border-radius:10px; padding:12px; display:flex; flex-direction:column; gap:8px;">
          <div style="display:flex; align-items:center; justify-content:space-between;">
            <span style="font-size:0.85rem; font-weight:700; color:#e2e8f0; display:flex; align-items:center; gap:6px;">
              <span style="width:8px; height:8px; border-radius:50%; background:{_cv_esc(color)}; box-shadow:0 0 8px {_cv_esc(color)}; display:inline-block;"></span>
              {_cv_esc(name)}
            </span>
            <span style="font-size:0.75rem; font-family:monospace; font-weight:800; color:{_cv_esc(color)};">{_cv_esc(intensity)}%</span>
          </div>
          <div style="width:100%; height:6px; background:rgba(255,255,255,0.05); border-radius:10px; overflow:hidden;">
            <div style="width:{_cv_esc(intensity)}%; height:100%; background:linear-gradient(90deg, {_cv_esc(color)}88, {_cv_esc(color)}); border-radius:10px; box-shadow:0 0 6px {_cv_esc(color)}66;"></div>
          </div>
        </div>
        """)
        
    themes_html = []
    for theme in themes:
        term = theme.get("term", "")
        weight = theme.get("weight", 50)
        sentiment = theme.get("sentiment", "neutral").lower()
        
        if sentiment in ["positive", "joy"]:
            bg = "rgba(16,185,129,0.1)"
            border = "rgba(16,185,129,0.2)"
            color_theme = "#10b981"
        elif sentiment in ["concern", "negative", "anxious"]:
            bg = "rgba(239,68,68,0.1)"
            border = "rgba(239,68,68,0.2)"
            color_theme = "#ef4444"
        elif sentiment in ["confused", "curious"]:
            bg = "rgba(245,158,11,0.1)"
            border = "rgba(245,158,11,0.2)"
            color_theme = "#f59e0b"
        else:
            bg = "rgba(56,189,248,0.1)"
            border = "rgba(56,189,248,0.2)"
            color_theme = "#38bdf8"
            
        font_size = 0.75 + (weight / 200.0)
        themes_html.append(f"""
        <span style="display:inline-block; font-size:{font_size:.2f}rem; font-weight:700; color:{color_theme}; background:{bg}; border:1px solid {border}; padding:6px 12px; border-radius:20px; margin:4px; box-shadow: 0 2px 8px rgba(0,0,0,0.15);">
          {_cv_esc(term)}
        </span>
        """)
        
    summary_html = ""
    if summary:
        summary_html = f"""
        <div style="margin-top:20px; padding:12px 16px; background:rgba(255,255,255,0.02); border-left:3px solid #d946ef; border-radius:0 8px 8px 0; font-size:0.85rem; line-height:1.6; color:rgba(255,255,255,0.7); font-style:italic;">
          {_cv_esc(summary)}
        </div>
        """
        
    moods_section = f"""
    <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(140px, 1fr)); gap:12px; margin-bottom:20px;">
      {"".join(moods_html)}
    </div>
    """ if moods else ""
    
    themes_section = f"""
    <div style="background:rgba(255,255,255,0.01); border:1px solid rgba(255,255,255,0.03); border-radius:10px; padding:16px; display:flex; flex-wrap:wrap; align-items:center; justify-content:center;">
      {"".join(themes_html)}
    </div>
    """ if themes else ""
    
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {header_html}
      {moods_section}
      {themes_section}
      {summary_html}
    </div>
    """


def _render_github_activity_grid(b: dict) -> str:
    title = b.get("title", "")
    username = b.get("username", "")
    total = b.get("total_contributions", 342)
    streak = b.get("streak_days", 18)
    activity = b.get("activity", [])
    
    header_html = ""
    if title or username:
        user_badge = f"""
        <div style="display:flex; align-items:center; gap:8px;">
          <span style="font-size:0.75rem; font-family:monospace; color:rgba(255,255,255,0.4); background:rgba(255,255,255,0.04); padding:4px 8px; border-radius:12px; border:1px solid rgba(255,255,255,0.06); display:flex; align-items:center; gap:4px;">
            <svg aria-hidden="true" width="12" height="12" viewBox="0 0 16 16" fill="rgba(255,255,255,0.5)">
              <path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0016 8c0-4.42-3.58-8-8-8z"/>
            </svg>
            @{_cv_esc(username)}
          </span>
        </div>
        """ if username else ""
        
        header_html = f"""
        <div style="margin-bottom:20px; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px;">
          <div style="font-size:1.15rem;font-weight:800;color:#f1f5f9;letter-spacing:-0.2px; display:flex; align-items:center; gap:8px;">
            <span style="color:#26a641; font-weight:900;">⬡</span> {_cv_esc(title or "GitHub Contribution Stream")}
          </div>
          {user_badge}
        </div>
        """
        
    cols, rows = 28, 7
    squares = []
    colors = ["#161b22", "#0e4429", "#006d32", "#26a641", "#39d353"]
    
    total_cells = cols * rows
    import random
    seed_val = len(username or title or "github")
    
    levels = []
    if activity and len(activity) >= total_cells:
        levels = activity[:total_cells]
    else:
        r_gen = random.Random(seed_val)
        for _ in range(total_cells):
            v = r_gen.choices([0, 1, 2, 3, 4], weights=[50, 20, 15, 10, 5])[0]
            levels.append(v)
            
    square_size = 9
    spacing = 3
    for col in range(cols):
        col_x = col * (square_size + spacing)
        for row in range(rows):
            row_y = row * (square_size + spacing)
            idx = col * rows + row
            lvl = levels[idx] if idx < len(levels) else 0
            color = colors[lvl]
            squares.append(f'<rect x="{col_x}" y="{row_y}" width="{square_size}" height="{square_size}" rx="1.5" fill="{color}" />')
            
    grid_svg = f"""
    <svg role="img" aria-label="Contribution heatmap, {cols} weeks of daily activity" viewBox="0 0 {cols * (square_size + spacing) - spacing} {rows * (square_size + spacing) - spacing}" width="100%" height="95" xmlns="http://www.w3.org/2000/svg">
      {"".join(squares)}
    </svg>
    """
    
    stats_html = f"""
    <div style="display:flex; align-items:center; gap:16px; margin-bottom:16px;">
      <div style="background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.04); border-radius:10px; padding:10px 16px; flex-grow:1; min-width:100px;">
        <div style="font-size:0.65rem; font-family:monospace; color:rgba(255,255,255,0.4); text-transform:uppercase; letter-spacing:0.05em; margin-bottom:2px;">Contributions</div>
        <div style="font-size:1.3rem; font-weight:800; color:#f1f5f9; font-family:monospace; display:flex; align-items:baseline; gap:4px;">
          {_cv_esc(total)} <span style="font-size:0.75rem; color:#26a641; font-weight:bold;">YTD</span>
        </div>
      </div>
      <div style="background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.04); border-radius:10px; padding:10px 16px; flex-grow:1; min-width:100px;">
        <div style="font-size:0.65rem; font-family:monospace; color:rgba(255,255,255,0.4); text-transform:uppercase; letter-spacing:0.05em; margin-bottom:2px;">Active Streak</div>
        <div style="font-size:1.3rem; font-weight:800; color:#f1f5f9; font-family:monospace; display:flex; align-items:baseline; gap:4px;">
          {_cv_esc(streak)} <span style="font-size:0.75rem; color:#39d353; font-weight:bold;">days 🔥</span>
        </div>
      </div>
    </div>
    """
    
    return f"""
    <div style="margin:1.5rem 0;padding:24px;background:rgb(15,23,42);border:1px solid rgba(255,255,255,0.06);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);">
      {header_html}
      {stats_html}
      <div style="background:rgba(255,255,255,0.01); border:1px solid rgba(255,255,255,0.03); border-radius:10px; padding:16px; box-sizing:border-box; display:flex; align-items:center; justify-content:center;">
        <div style="width:100%; max-width:350px;">
          {grid_svg}
        </div>
      </div>
    </div>
    """


# ── OpenUI atoms (sourced from github.com/thesysdev/openui, MIT) ─────────────

def _form_field_html(field: dict) -> str:
    """Render one field inside a form."""
    ftype       = field.get("type", "text")
    label       = field.get("label", "")
    name        = field.get("name", "")
    placeholder = field.get("placeholder", "")
    rules       = field.get("rules", [])
    required    = "required" in rules

    req_star = '<span style="color:#ea4335;margin-left:2px;">*</span>' if required else ""
    label_html = (
        f'<label for="{_cv_esc(name)}" style="display:block;font-size:0.83rem;font-weight:600;'
        f'color:#3c4043;margin-bottom:5px;">{_cv_esc(label)}{req_star}</label>'
    )
    input_style = (
        "width:100%;padding:9px 12px;border:1px solid #dadce0;border-radius:6px;"
        "font-size:0.9rem;color:#3c4043;background:#fff;box-sizing:border-box;"
        "font-family:inherit;outline:none;"
    )
    if ftype == "textarea":
        ctrl = (f'<textarea id="{_cv_esc(name)}" name="{_cv_esc(name)}" placeholder="{_cv_esc(placeholder)}" '
                f'style="{input_style}height:88px;resize:vertical;" '
                f'{"required" if required else ""}></textarea>')
    elif ftype == "select":
        opts = f'<option value="">{_cv_esc(placeholder or "Select…")}</option>' + "".join(
            f'<option value="{_cv_esc(o["value"])}">{_cv_esc(o["label"])}</option>'
            for o in field.get("options", [])
        )
        ctrl = (f'<select id="{_cv_esc(name)}" name="{_cv_esc(name)}" style="{input_style}" '
                f'{"required" if required else ""}>{opts}</select>')
    else:
        ctrl = (f'<input id="{_cv_esc(name)}" type="{_cv_esc(ftype)}" name="{_cv_esc(name)}" '
                f'placeholder="{_cv_esc(placeholder)}" style="{input_style}" '
                f'{"required" if required else ""}>')

    return f'<div style="display:flex;flex-direction:column;">{label_html}{ctrl}</div>'


def _render_form(b: dict) -> str:
    """Full form — field list with typed inputs, validation hints, submit/cancel."""
    title        = b.get("title", "")
    description  = b.get("description", "")
    fields       = b.get("fields", [])
    submit_label = b.get("submit_label", "Submit")
    cancel_label = b.get("cancel_label", "")

    title_html = (
        f'<div style="font-size:1.0rem;font-weight:700;color:#1a1a2e;margin-bottom:4px;">{_cv_esc(title)}</div>'
        if title else ""
    )
    desc_html = (
        f'<p style="font-size:0.85rem;color:#5f6368;margin-bottom:16px;">{_md_inline(description)}</p>'
        if description else ""
    )
    fields_html = "".join(_form_field_html(f) for f in fields)

    cancel_btn = (
        f'<button type="button" style="padding:9px 20px;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
        f'background:#ffffff;background:var(--a2ui-surface,#ffffff);color:#3c4043;font-size:0.88rem;font-weight:500;cursor:pointer;">'
        f'{_cv_esc(cancel_label)}</button>'
    ) if cancel_label else ""

    return (
        f'<div style="border:1px solid #e0e0e0;border-radius:10px;padding:24px;margin:1.5rem 0;background:#fff;">'
        f'{title_html}{desc_html}'
        f'<div style="display:flex;flex-direction:column;gap:14px;">'
        f'{fields_html}'
        f'<div style="display:flex;gap:10px;justify-content:flex-end;padding-top:6px;">'
        f'{cancel_btn}'
        f'<button type="button" style="padding:9px 24px;border-radius:6px;border:none;'
        f'background:#1a73e8;color:#fff;font-size:0.88rem;font-weight:600;cursor:pointer;">'
        f'{_cv_esc(submit_label)}</button>'
        f'</div></div></div>'
    )


def _render_form_input(b: dict) -> str:
    """Standalone labeled text input."""
    label       = b.get("label", "")
    name        = b.get("name", "")
    ftype       = b.get("type", "text")
    placeholder = b.get("placeholder", "")
    value       = b.get("value", "")
    rules       = b.get("rules", [])
    required    = "required" in rules
    req_star = '<span style="color:#ea4335;margin-left:2px;">*</span>' if required else ""
    return (
        f'<div style="margin:1rem 0;">'
        f'<label for="{_cv_esc(name)}" style="display:block;font-size:0.83rem;font-weight:600;'
        f'color:#3c4043;margin-bottom:5px;">{_cv_esc(label)}{req_star}</label>'
        f'<input id="{_cv_esc(name)}" type="{_cv_esc(ftype)}" name="{_cv_esc(name)}" placeholder="{_cv_esc(placeholder)}" '
        f'value="{_cv_esc(value)}" style="width:100%;padding:9px 12px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
        f'border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);font-size:0.9rem;color:#3c4043;box-sizing:border-box;" '
        f'{"required" if required else ""}>'
        f'</div>'
    )


def _render_form_select(b: dict) -> str:
    """Standalone labeled select dropdown."""
    label       = b.get("label", "")
    name        = b.get("name", "")
    placeholder = b.get("placeholder", "")
    options     = b.get("options", [])
    rules       = b.get("rules", [])
    required    = "required" in rules
    req_star = '<span style="color:#ea4335;margin-left:2px;">*</span>' if required else ""
    opts = f'<option value="">{_cv_esc(placeholder or "Select…")}</option>' + "".join(
        f'<option value="{_cv_esc(o["value"])}">{_cv_esc(o["label"])}</option>' for o in options
    )
    return (
        f'<div style="margin:1rem 0;">'
        f'<label for="{_cv_esc(name)}" style="display:block;font-size:0.83rem;font-weight:600;'
        f'color:#3c4043;margin-bottom:5px;">{_cv_esc(label)}{req_star}</label>'
        f'<select id="{_cv_esc(name)}" name="{_cv_esc(name)}" style="width:100%;padding:9px 12px;'
        f'border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);font-size:0.9rem;color:#3c4043;'
        f'background:#ffffff;background:var(--a2ui-surface,#ffffff);box-sizing:border-box;" {"required" if required else ""}>'
        f'{opts}</select>'
        f'</div>'
    )


def _render_form_radio_group(b: dict) -> str:
    """Group of radio buttons — single selection."""
    label         = b.get("label", "")
    name          = b.get("name", "")
    options       = b.get("options", [])
    default_value = b.get("default_value", "")

    items_html = ""
    for opt in options:
        val     = opt.get("value", "")
        lbl     = opt.get("label", "")
        desc    = opt.get("description", "")
        checked = "checked" if val == default_value else ""
        desc_html = f'<span style="font-size:0.78rem;color:#5f6368;margin-top:1px;">{_cv_esc(desc)}</span>' if desc else ""
        items_html += (
            f'<label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;'
            f'padding:10px 12px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
            f'<input type="radio" name="{_cv_esc(name)}" value="{_cv_esc(val)}" {checked} '
            f'style="margin-top:3px;accent-color:#1a73e8;flex-shrink:0;">'
            f'<span style="display:flex;flex-direction:column;">'
            f'<span style="font-size:0.88rem;font-weight:600;color:#3c4043;">{_cv_esc(lbl)}</span>'
            f'{desc_html}</span></label>'
        )

    return (
        f'<div style="margin:1rem 0;">'
        f'<div style="font-size:0.83rem;font-weight:600;color:#3c4043;margin-bottom:8px;">{_cv_esc(label)}</div>'
        f'<div style="display:flex;flex-direction:column;gap:6px;">{items_html}</div>'
        f'</div>'
    )


def _render_form_checkbox_group(b: dict) -> str:
    """Group of checkboxes — multi-selection."""
    label   = b.get("label", "")
    name    = b.get("name", "")
    options = b.get("options", [])

    items_html = ""
    for opt in options:
        oname   = opt.get("name", "")
        lbl     = opt.get("label", "")
        desc    = opt.get("description", "")
        checked = "checked" if opt.get("default_checked") else ""
        desc_html = f'<span style="font-size:0.78rem;color:#5f6368;margin-top:1px;">{_cv_esc(desc)}</span>' if desc else ""
        items_html += (
            f'<label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;'
            f'padding:10px 12px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
            f'<input type="checkbox" name="{_cv_esc(name)}[{_cv_esc(oname)}]" {checked} '
            f'style="margin-top:3px;accent-color:#1a73e8;flex-shrink:0;">'
            f'<span style="display:flex;flex-direction:column;">'
            f'<span style="font-size:0.88rem;font-weight:600;color:#3c4043;">{_cv_esc(lbl)}</span>'
            f'{desc_html}</span></label>'
        )

    return (
        f'<div style="margin:1rem 0;">'
        f'<div style="font-size:0.83rem;font-weight:600;color:#3c4043;margin-bottom:8px;">{_cv_esc(label)}</div>'
        f'<div style="display:flex;flex-direction:column;gap:6px;">{items_html}</div>'
        f'</div>'
    )


def _render_form_switch_group(b: dict) -> str:
    """Toggle switches with labels and optional descriptions — CSS-only."""
    import hashlib
    label = b.get("label", "")
    name  = b.get("name", "")
    items = b.get("items", [])

    label_html = (
        f'<div style="font-size:0.83rem;font-weight:600;color:#3c4043;margin-bottom:8px;">{_cv_esc(label)}</div>'
        if label else ""
    )

    rows = ""
    for item in items:
        iname   = item.get("name", "")
        ilabel  = item.get("label", "")
        idesc   = item.get("description", "")
        checked = item.get("default_checked", False)
        sid     = "sw_" + hashlib.md5(f"{name}_{iname}".encode()).hexdigest()[:6]
        desc_html = f'<span style="font-size:0.78rem;color:#5f6368;">{_cv_esc(idesc)}</span>' if idesc else ""
        rows += (
            f'<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;'
            f'padding:12px 14px;border-bottom:1px solid #f0f0f0;">'
            f'<div style="display:flex;flex-direction:column;gap:2px;">'
            f'<span style="font-size:0.88rem;font-weight:600;color:#3c4043;">{_cv_esc(ilabel)}</span>'
            f'{desc_html}</div>'
            # CSS-only toggle: hidden checkbox + styled label
            f'<input type="checkbox" id="{sid}" name="{_cv_esc(name)}[{_cv_esc(iname)}]" '
            f'{"checked" if checked else ""} style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">'
            f'<label for="{sid}" style="position:relative;display:inline-block;'
            f'width:42px;height:24px;flex-shrink:0;cursor:pointer;">'
            f'<span style="position:absolute;inset:0;border-radius:12px;'
            f'background:{"#1a73e8" if checked else "#dadce0"};transition:background 0.2s;"></span>'
            f'<span style="position:absolute;top:3px;left:{"21px" if checked else "3px"};'
            f'width:18px;height:18px;border-radius:50%;background:#fff;'
            f'box-shadow:0 1px 4px rgba(0,0,0,0.2);transition:left 0.2s;"></span>'
            f'</label>'
            f'</div>'
        )

    header = (
        '<div style="padding:12px 14px;border-bottom:1px solid #e0e0e0;">' + label_html + '</div>'
        if label else ""
    )
    return (
        f'<div style="margin:1rem 0;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
        f'{header}'
        f'{rows}'
        f'</div>'
    )


def _render_form_slider(b: dict) -> str:
    """Range slider — native <input type=range> so the thumb is actually draggable."""
    import hashlib
    label = b.get("label", "")
    name  = b.get("name", "")
    mn    = b.get("min", 0)
    mx    = b.get("max", 100)
    step  = b.get("step", 1)
    val   = b.get("value", mn)
    unit  = b.get("unit", "")
    sid   = "sl_" + hashlib.md5(name.encode()).hexdigest()[:6]
    unit_str = f" {_cv_esc(unit)}" if unit else ""

    return (
        f'<style>'
        f'#{sid}{{-webkit-appearance:none;appearance:none;width:100%;height:6px;'
        f'border-radius:3px;background:linear-gradient(to right,#1a73e8 0%,'
        f'#1a73e8 {int((val-mn)/max(mx-mn,1)*100)}%,'
        f'#e0e0e0 {int((val-mn)/max(mx-mn,1)*100)}%,#e0e0e0 100%);'
        f'outline:none;cursor:pointer;}}'
        f'#{sid}::-webkit-slider-thumb{{-webkit-appearance:none;appearance:none;'
        f'width:18px;height:18px;border-radius:50%;background:#1a73e8;'
        f'border:2px solid #fff;box-shadow:0 1px 4px rgba(26,115,232,0.5);cursor:pointer;}}'
        f'#{sid}::-moz-range-thumb{{width:18px;height:18px;border-radius:50%;'
        f'background:#1a73e8;border:2px solid #fff;cursor:pointer;box-sizing:border-box;}}'
        f'</style>'
        f'<div style="margin:1rem 0;">'
        f'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">'
        f'<label for="{sid}" style="font-size:0.83rem;font-weight:600;color:#3c4043;">{_cv_esc(label)}</label>'
        f'<span style="font-size:0.88rem;font-weight:700;color:#1a73e8;">{_cv_esc(val)}{unit_str}</span>'
        f'</div>'
        f'<input id="{sid}" type="range" aria-label="{_cv_esc(label or name or "Slider")}" name="{_cv_esc(name)}" min="{_cv_esc(mn)}" max="{_cv_esc(mx)}" step="{_cv_esc(step)}" value="{_cv_esc(val)}" '
        f'style="width:100%;margin:0;">'
        f'<div style="display:flex;justify-content:space-between;margin-top:6px;">'
        f'<span style="font-size:0.75rem;color:#9aa0a6;">{_cv_esc(mn)}{unit_str}</span>'
        f'<span style="font-size:0.75rem;color:#9aa0a6;">{_cv_esc(mx)}{unit_str}</span>'
        f'</div>'
        f'</div>'
    )


def _render_form_date_picker(b: dict) -> str:
    """Date input — single date or date-range display."""
    label = b.get("label", "")
    name  = b.get("name", "")
    mode  = b.get("mode", "single")
    value = b.get("value", "")
    mn    = b.get("min", "")
    mx    = b.get("max", "")
    rules = b.get("rules", [])
    required = "required" in rules
    req_star = '<span style="color:#ea4335;margin-left:2px;">*</span>' if required else ""

    if mode == "range":
        ctrl = (
            f'<div style="display:flex;gap:10px;">'
            f'<div style="flex:1;">'
            f'<label style="display:block;font-size:0.75rem;color:#5f6368;margin-bottom:3px;">From</label>'
            f'<input type="date" aria-label="{_cv_esc((label + " ") if label else "")}From" name="{_cv_esc(name)}_from" min="{_cv_esc(mn)}" max="{_cv_esc(mx)}" '
            f'style="width:100%;padding:9px 12px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);'
            f'font-size:0.88rem;color:#3c4043;box-sizing:border-box;"></div>'
            f'<div style="flex:1;">'
            f'<label style="display:block;font-size:0.75rem;color:#5f6368;margin-bottom:3px;">To</label>'
            f'<input type="date" aria-label="{_cv_esc((label + " ") if label else "")}To" name="{_cv_esc(name)}_to" min="{_cv_esc(mn)}" max="{_cv_esc(mx)}" '
            f'style="width:100%;padding:9px 12px;border:1px solid #dadce0;border-radius:6px;'
            f'font-size:0.88rem;color:#3c4043;box-sizing:border-box;"></div>'
            f'</div>'
        )
    else:
        ctrl = (
            f'<input id="{_cv_esc(name)}" type="date" name="{_cv_esc(name)}" value="{_cv_esc(value)}"{"" if label else " aria-label=Date"} '
            f'min="{_cv_esc(mn)}" max="{_cv_esc(mx)}" '
            f'style="width:100%;padding:9px 12px;border:1px solid #dadce0;border-radius:6px;'
            f'font-size:0.9rem;color:#3c4043;box-sizing:border-box;" '
            f'{"required" if required else ""}>'
        )

    return (
        f'<div style="margin:1rem 0;">'
        f'<label for="{_cv_esc(name)}" style="display:block;font-size:0.83rem;font-weight:600;'
        f'color:#3c4043;margin-bottom:5px;">{_cv_esc(label)}{req_star}</label>'
        f'{ctrl}'
        f'</div>'
    )


def _render_modal(b: dict) -> str:
    """CSS-only modal — checkbox trigger, title, optional blocks, confirm/cancel buttons.

    Source: OpenUI/Thesys standard library (MIT), adapted for A2UI.
    """
    import hashlib
    title         = b.get("title", "")
    description   = b.get("description", "")
    trigger_label = b.get("trigger_label", "Open")
    confirm_label = b.get("confirm_label", "Confirm")
    cancel_label  = b.get("cancel_label", "Cancel")
    blocks        = b.get("blocks", [])
    mid           = "m_" + hashlib.md5(title.encode()).hexdigest()[:6]

    inner_html = ""
    for block in blocks:
        btype = block.get("component") or block.get("type")
        fn = _RENDERERS.get(btype)
        inner_html += fn(block) if fn else f'<p>{_cv_esc(block)}</p>'

    desc_html = f'<p style="font-size:0.88rem;color:#94a3b8;margin:4px 0 16px;">{_md_inline(description)}</p>' if description else ""

    return (
        f'<div style="margin:1rem 0;">'
        # CSS: hide backdrop by default; show when checkbox checked.
        # !important needed to beat the inline display:none that srcdoc would otherwise cache.
        f'<style>'
        f'#{mid}{{display:none;}}'
        f'.{mid}-bd{{display:none;position:fixed;inset:0;z-index:9000;'
        f'align-items:center;justify-content:center;background:rgba(0,0,0,0.45);}}'
        f'#{mid}:checked~.{mid}-bd{{display:flex!important;}}'
        f'</style>'
        # Trigger button
        f'<label for="{mid}" style="display:inline-block;padding:9px 22px;border-radius:6px;'
        f'background:#1a73e8;color:#fff;font-size:0.88rem;font-weight:600;cursor:pointer;">'
        f'{_cv_esc(trigger_label)}</label>'
        f'<input type="checkbox" id="{mid}">'
        # Backdrop + dialog
        f'<div class="{mid}-bd">'
        f'<div style="background:#1e293b;border-radius:12px;padding:28px 28px 20px;'
        f'max-width:480px;width:90%;box-shadow:0 20px 60px rgba(0,0,0,0.5);">'
        f'<div style="font-size:1.0rem;font-weight:700;color:#f1f5f9;margin-bottom:4px;">{_cv_esc(title)}</div>'
        f'{desc_html}'
        f'{inner_html}'
        f'<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:20px;">'
        f'<label for="{mid}" style="padding:9px 20px;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);'
        f'border:1px solid rgba(255,255,255,0.15);'
        f'background:rgba(255,255,255,0.06);color:#e2e8f0;font-size:0.88rem;font-weight:500;cursor:pointer;">'
        f'{_cv_esc(cancel_label)}</label>'
        f'<label for="{mid}" style="padding:9px 22px;border-radius:6px;border:none;'
        f'background:#3b82f6;color:#fff;font-size:0.88rem;font-weight:600;cursor:pointer;">'
        f'{_cv_esc(confirm_label)}</label>'
        f'</div></div></div>'
        f'</div>'
    )


def _hex_to_rgba(hex_color: str, alpha: float) -> str:
    """Convert a #rrggbb hex color + alpha float to rgba(r,g,b,a)."""
    h = hex_color.lstrip("#")
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    try:
        r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)
        return f"rgba({r},{g},{b},{alpha})"
    except Exception:
        return hex_color


def _render_follow_up_chips(b: dict) -> str:
    """Conversation follow-up suggestion chips — styled pill buttons.

    Source: OpenUI/Thesys FollowUpBlock (MIT), adapted for A2UI.
    On meet-stage: renders as static styled buttons (CSP blocks click handlers).
    """
    items  = b.get("items", [])
    label  = b.get("label", "")
    accent = b.get("accent", "#1558b4")

    bg     = _hex_to_rgba(accent, 0.12)
    border = _hex_to_rgba(accent, 0.45)

    label_html = (
        f'<div style="font-size:0.75rem;font-weight:600;color:#9aa0a6;'
        f'text-transform:uppercase;letter-spacing:0.06em;margin-bottom:8px;">{_cv_esc(label)}</div>'
    ) if label else ""

    chips = "".join(
        f'<span data-cb="item" data-key="{_cv_esc(item if isinstance(item, str) else (item.get("text") or item.get("label") or ""))}" style="display:inline-flex;align-items:center;gap:5px;padding:8px 14px;'
        f'border-radius:100px;border:1px solid {border};background:{bg};'
        f'color:{_cv_esc(accent)};font-size:0.85rem;font-weight:500;cursor:pointer;white-space:nowrap;">'
        f'{_cv_esc(item)}'
        f'<svg aria-hidden="true" width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'
        f'<path d="M2 5h6M5.5 2l3 3-3 3"/>'
        f'</svg>'
        f'</span>'
        for item in items
    )

    return (
        f'<div style="margin:1rem 0;">'
        f'{label_html}'
        f'<div style="display:flex;flex-wrap:wrap;gap:8px;">{chips}</div>'
        f'</div>'
    )


def _render_choicebox_group(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    uid = _wa_uid(b)
    prefix = f"cbg-{uid}"
    label = _first_text(b.get("label"), b.get("question"))
    name = _first_text(b.get("name"), f"choice_{uid}")
    multiple = b.get("multiple") is True
    accent = _safe_css(b.get("accent"), "#1a73e8")
    submit_label = _text_loose(b.get("submit_label"))

    raw_items = b.get("items")
    if not isinstance(raw_items, list):
        raw_items = b.get("options")
    if not isinstance(raw_items, list):
        raw_items = []
    items = raw_items[:200]

    input_type = "checkbox" if multiple else "radio"
    cards_html = ""
    for i, item in enumerate(items):
        if not isinstance(item, dict):
            val = _text_loose(item) or str(i)
            lbl = _text_loose(item)
            desc = ""
            icon = ""
            disabled = False
        else:
            val = _first_text(item.get("value"), str(i))
            lbl = _first_text(item.get("title"), item.get("label"))
            desc = _first_text(item.get("description"), item.get("desc"))
            icon = _text_loose(item.get("icon"))
            disabled = item.get("disabled") is True

        cid = f"{prefix}-{i}"
        dis_attr = " disabled" if disabled else ""
        opacity = "opacity:0.45;" if disabled else ""
        cursor = "default" if disabled else "pointer"
        icon_html = f'<span class="{prefix}-icon">{_cv_esc(icon)}</span>' if icon else ""
        desc_html = f'<span class="{prefix}-desc">{_cv_esc(desc)}</span>' if desc else ""

        cards_html += (
            f'<div class="{prefix}-item-wrap">'
            f'<input type="{input_type}" id="{cid}" name="{_cv_esc(name)}" value="{_cv_esc(val)}" class="{prefix}-input"{dis_attr}>'
            f'<label for="{cid}" class="{prefix}-card" style="cursor:{cursor};{opacity}">'
            f'{icon_html}'
            f'<span class="{prefix}-text">'
            f'<span class="{prefix}-label">{_cv_esc(lbl)}</span>'
            f'{desc_html}'
            f'</span>'
            f'</label>'
            f'</div>'
        )

    submit_html = (
        f'<button type="submit" style="margin-top:12px;padding:9px 22px;border-radius:6px;border:none;'
        f'background:{accent};color:#fff;font-size:0.88rem;font-weight:600;cursor:pointer;">'
        f'{_cv_esc(submit_label)}</button>'
    ) if submit_label else ""

    label_html = f'<div class="{prefix}-question">{_cv_esc(label)}</div>' if label else ""
    group_label = f' aria-label="{_cv_esc(label)}"' if label else ""

    return (
        f'<style>'
        f'.{prefix}-wrap{{margin:1rem 0;}}'
        f'.{prefix}-question{{font-size:16px;font-weight:700;color:#111827;margin-bottom:12px;}}'
        f'.{prefix}-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;}}'
        f'.{prefix}-input{{position:absolute;opacity:0;width:0;height:0;}}'
        f'.{prefix}-card{{display:flex;align-items:flex-start;gap:12px;padding:16px;border:2px solid #e5e7eb;border-radius:10px;background:#fff;transition:border-color 0.15s,background 0.15s;box-sizing:border-box;}}'
        f'.{prefix}-card:hover{{border-color:#9aa0a6;}}'
        f'.{prefix}-input:checked + .{prefix}-card{{border-color:{accent};background:#f3f7fe;background:color-mix(in srgb,{accent} 7%,#fff);}}'
        f'.{prefix}-input:focus-visible + .{prefix}-card{{outline:2px solid #4f46e5;outline-offset:2px;}}'
        f'.{prefix}-icon{{font-size:22px;flex-shrink:0;line-height:1.3;}}'
        f'.{prefix}-text{{display:flex;flex-direction:column;gap:3px;}}'
        f'.{prefix}-label{{font-size:15px;font-weight:600;color:#111827;}}'
        f'.{prefix}-desc{{font-size:13px;color:var(--muted,#5f6368);}}'
        f'@media (prefers-reduced-motion:reduce){{.{prefix}-card{{transition:none;}}}}'
        f'</style>'
        f'<div class="{prefix}-wrap" role="group"{group_label}>'
        f'{label_html}'
        f'<div class="{prefix}-grid">{cards_html}</div>'
        f'{submit_html}'
        f'</div>'
    )


def _render_feedback_prompt(b: dict) -> str:
    """In-context feedback widget — thumbs up/down or 1–5 stars, CSS-only.

    Inspired by Vercel Geist Feedback pattern.
    thumbs: two pill buttons, :has(input:checked) highlights selection.
    stars: classic CSS row-reverse trick; input:checked ~ label fills preceding stars.
    """
    import hashlib
    fid         = "fp_" + hashlib.md5(b.get("question", "feedback").encode()).hexdigest()[:6]
    question    = b.get("question", "Was this helpful?")
    style       = b.get("style", "thumbs")
    placeholder = b.get("placeholder", "")
    action_url  = b.get("action_url", "")

    wrap_open  = f'<form action="{_cv_esc(action_url)}" method="post">' if action_url else ""
    wrap_close = "</form>" if action_url else ""

    q_html = (
        f'<div style="font-size:0.88rem;font-weight:500;color:#3c4043;margin-bottom:10px;">'
        f'{_cv_esc(question)}</div>'
    ) if question else ""

    if style == "stars":
        star_inputs = "".join(
            f'<input type="radio" id="{fid}_s{i}" name="{fid}_rating" value="{i}" style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">'
            f'<label for="{fid}_s{i}" title="{i} star{"s" if i>1 else ""}">★</label>'
            for i in range(5, 0, -1)
        )
        widget_html = (
            f'<style>'
            f'.{fid}-stars{{display:flex;flex-direction:row-reverse;gap:3px;}}'
            f'.{fid}-stars label{{font-size:1.7rem;color:#dadce0;cursor:pointer;line-height:1;transition:color 0.1s;}}'
            f'.{fid}-stars input:checked~label,'
            f'.{fid}-stars label:hover~label,'
            f'.{fid}-stars label:hover{{color:#f59e0b;}}'
            f'</style>'
            f'<div class="{fid}-stars">{star_inputs}</div>'
        )
    else:
        widget_html = (
            f'<style>'
            f'.{fid}-up:has(input:focus-visible),.{fid}-dn:has(input:focus-visible){{outline:2px solid #4f46e5;outline-offset:2px;}}'
            f'.{fid}-up:has(input:checked){{border-color:#1a73e8!important;'
            f'background:rgba(26,115,232,0.08)!important;color:#1a73e8!important;}}'
            f'.{fid}-dn:has(input:checked){{border-color:#ea4335!important;'
            f'background:rgba(234,67,53,0.08)!important;color:#ea4335!important;}}'
            f'</style>'
            f'<div style="display:flex;gap:8px;">'
            f'<label class="{fid}-up" style="display:inline-flex;align-items:center;gap:6px;'
            f'padding:8px 16px;border:1.5px solid #dadce0;border-radius:100px;cursor:pointer;'
            f'font-size:0.88rem;font-weight:500;color:#3c4043;background:#fff;">'
            f'<input type="radio" name="{fid}_rating" value="up" style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">👍 Yes</label>'
            f'<label class="{fid}-dn" style="display:inline-flex;align-items:center;gap:6px;'
            f'padding:8px 16px;border:1.5px solid #dadce0;border-radius:100px;cursor:pointer;'
            f'font-size:0.88rem;font-weight:500;color:#3c4043;background:#fff;">'
            f'<input type="radio" name="{fid}_rating" value="down" style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">👎 No</label>'
            f'</div>'
        )

    text_html = (
        f'<textarea name="{fid}_comment" placeholder="{_cv_esc(placeholder)}" '
        f'style="display:block;margin-top:10px;width:100%;box-sizing:border-box;padding:8px 10px;'
        f'border:1px solid #dadce0;border-radius:6px;font-size:0.85rem;color:#3c4043;'
        f'resize:vertical;min-height:64px;background:#fff;"></textarea>'
    ) if placeholder else ""

    submit_html = (
        f'<button type="submit" style="margin-top:8px;padding:7px 18px;border-radius:6px;'
        f'border:none;background:#1a73e8;color:#fff;font-size:0.85rem;font-weight:600;cursor:pointer;">'
        f'Submit</button>'
    ) if action_url else ""

    return (
        f'{wrap_open}'
        f'<div style="margin:1rem 0;padding:16px 18px;border:1px solid #e0e0e0;'
        f'border-radius:10px;background:#fff;">'
        f'{q_html}'
        f'{widget_html}'
        f'{text_html}'
        f'{submit_html}'
        f'</div>'
        f'{wrap_close}'
    )


# ── Aceternity UI-inspired atoms ──────────────────────────────────────────────

def _render_marquee_strip(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    uid = _wa_uid(b)
    prefix = f"mqs_{uid}"

    raw_items = b.get("items")
    if not isinstance(raw_items, list):
        raw_items = b.get("tags")
    if not isinstance(raw_items, list):
        raw_items = b.get("words")
    if not isinstance(raw_items, list):
        raw_items = []
    items = raw_items[:200]

    speed_raw = b.get("speed")
    speed_num = _num_loose(speed_raw)
    if speed_num is not None and speed_num > 0:
        dur = _text_loose(min(max(speed_num, 1.0), 3600.0)) + "s"
    else:
        durations = {"slow": "40s", "normal": "25s", "fast": "12s"}
        dur = durations.get(_text_loose(speed_raw).strip().lower(), "25s")

    direction = _text_loose(b.get("direction")).lower()
    anim_dir = "reverse" if direction == "right" else "normal"
    pause_on_hover = b.get("pause_on_hover", True) is not False
    label = _first_text(b.get("label"), b.get("title"))
    gap_raw = b.get("gap")
    gap = (_text_loose(gap_raw) + "px") if isinstance(gap_raw, (int, float)) and _text_loose(gap_raw) else _safe_css(gap_raw, "40px")
    bg = _safe_css(_first_text(b.get("background"), b.get("bg")), "")
    color = _safe_css(b.get("color"), "")
    separator = _text_loose(b.get("separator"))

    def _render_item(item, is_dup=False):
        sep_span = f'<span style="opacity:0.3;margin-left:8px;" aria-hidden="true">{_cv_esc(separator)}</span>' if separator else ""
        if isinstance(item, dict):
            img = _safe_href(item.get("image_url"), schemes=("http", "https", "data"))
            text = _first_text(item.get("text"), item.get("label"))
            icon = _text_loose(item.get("icon"))
            k = text or img or icon
            attr = f' data-cb="tile" data-key="{_cv_esc(k)}"' if not is_dup else ""
            img_html = (
                f'<img src="{img}" alt="{_cv_esc(text)}" '
                f'style="height:28px;object-fit:contain;vertical-align:middle;opacity:0.75;">'
            ) if img else ""
            icon_html = f'<span style="margin-right:4px;">{_cv_esc(icon)}</span>' if icon else ""
            return (
                f'<span{attr} style="display:inline-flex;align-items:center;gap:8px;white-space:nowrap;font-size:0.9rem;font-weight:500;">'
                f'{img_html}{icon_html}{_cv_esc(text)}{sep_span}</span>'
            )
        t = _text_loose(item)
        attr = f' data-cb="tile" data-key="{_cv_esc(t)}"' if not is_dup else ""
        return (
            f'<span{attr} style="display:inline-block;white-space:nowrap;font-size:0.9rem;font-weight:500;">'
            f'{_cv_esc(t)}{sep_span}</span>'
        )

    items_content = "".join(_render_item(it, False) for it in items)
    items_content_dup = "".join(_render_item(it, True) for it in items)

    track_content = (
        f'<span style="display:inline-flex;align-items:center;gap:{gap};padding-right:{gap};">'
        f'{items_content}</span>'
        f'<span aria-hidden="true" style="display:inline-flex;align-items:center;gap:{gap};padding-right:{gap};">'
        f'{items_content_dup}</span>'
    )

    label_html = (
        f'<div style="font-size:0.75rem;font-weight:600;color:var(--muted,#5f6368);'
        f'letter-spacing:0.08em;text-transform:uppercase;margin-bottom:10px;">'
        f'{_cv_esc(label)}</div>'
    ) if label else ""

    pause_css = f".{prefix}-track:hover{{animation-play-state:paused!important;}}" if pause_on_hover else ""

    container_bg = f"background:{bg};border-radius:12px;" if bg else "border-top:1px solid #f0f0f0;border-bottom:1px solid #f0f0f0;"
    container_color = f"color:{color};" if color else "color:#5f6368;"

    return (
        f'<style>'
        f'@keyframes {prefix}-scroll{{from{{transform:translateX(0);}}to{{transform:translateX(-50%);}}}}'
        f'.{prefix}-track{{display:flex;animation:{prefix}-scroll {dur} linear infinite;'
        f'animation-direction:{anim_dir};will-change:transform;}}'
        f'{pause_css}'
        f'@media (prefers-reduced-motion:reduce){{.{prefix}-track{{animation:none;}}}}'
        f'</style>'
        f'<div style="margin:1rem 0;overflow:hidden;padding:12px 0;{container_bg}{container_color}">'
        f'{label_html}'
        f'<div class="{prefix}-track">{track_content}</div>'
        f'</div>'
    )


def _render_typewriter_text(b: dict) -> str:
    text = _first_text(b.get('text'), b.get('content'), b.get('label'))
    size = _safe_css(b.get('size'), '28px')
    weight = _safe_css(b.get('weight'), '700')
    color = _safe_css(b.get('color'), '#1a1a1a')
    speed = b.get('speed')
    cursor = b.get('cursor') is not False
    delay = b.get('delay')
    if not (isinstance(delay, str) and re.fullmatch(r'[0-9]{1,4}(\.[0-9]{1,3})?(s|ms)', delay)):
        delay = '0s'
    tid = 'tw-' + _wa_uid(b)
    chars = max(1, len(text))
    typing = chars <= 30 and '\n' not in text and '\r' not in text and all(ord(c) < 0x2E80 for c in text)
    per = {'slow': 12, 'normal': 7, 'fast': 4}.get(speed, 7) if isinstance(speed, str) else 7
    sn = _num_loose(speed)
    if sn is not None:
        per = 12 if sn >= 90 else (4 if sn <= 25 else 7)
    tenths = (chars * per + 5) // 10
    dur = str(tenths // 10) + '.' + str(tenths % 10) + 's'
    cursor_css = ('.' + tid + '::after{content:"|";animation:' + tid + '-blink 0.75s step-end infinite;color:' + color + ';margin-left:2px;}'
                  '@keyframes ' + tid + '-blink{0%,100%{opacity:1}50%{opacity:0}}') if (cursor and typing) else ''
    if typing:
        rule = ('.' + tid + '{display:inline-block;overflow:hidden;white-space:nowrap;width:0;animation:' + tid + '-type ' + dur + ' steps(' + str(chars) + ',end) forwards;animation-delay:' + delay + ';}'
                '@keyframes ' + tid + '-type{to{width:' + str(chars) + 'ch}}')
    else:
        rule = '.' + tid + '{display:block;white-space:pre-wrap;overflow-wrap:anywhere;}'
    return ('<style>'
            + rule + cursor_css +
            '@media (prefers-reduced-motion:reduce){.' + tid + '{animation:none;width:auto;white-space:pre-wrap;overflow:visible;}.' + tid + '::after{animation:none;}}'
            '</style>'
            '<div data-cb="node" data-key="' + _ck(b.get('text'), 'typewriter_text') + '" style="margin:1rem 0;font-size:' + size + ';font-weight:' + weight + ';'
            'color:' + color + ';line-height:1.2;font-family:monospace;">'
            '<span class="' + tid + '">' + _cv_esc(text) + '</span>'
            '</div>')


def _render_animated_border_card(b: dict) -> str:
    import hashlib
    # title/body are schema'd as plain strings, but an agent composing this
    # atom occasionally sends a list (e.g. bullet points) instead of a
    # pre-joined string -- coerce rather than let hashlib.md5's .encode()
    # raise "can only concatenate str (not 'list') to str" on the very
    # first line (found live 2026-08-26, a poster/CTA prompt on
    # streaming-testbench's /catalog demo).
    def _as_str(v):
        return "\n".join(str(x) for x in v) if isinstance(v, list) else str(v) if v is not None else ""
    title   = _as_str(b.get("title", ""))
    body    = _as_str(b.get("body", ""))
    cid     = "abc_" + hashlib.md5((title + body).encode()).hexdigest()[:6]
    accent  = b.get("accent", "#38bdf8")
    accent2 = b.get("accent2", "#818cf8")
    bg      = b.get("background", "#ffffff")
    speed   = b.get("speed", "normal")
    bw      = int(b.get("border_width", 2))

    durations = {"slow": "4s", "normal": "2.5s", "fast": "1.2s"}
    dur = durations.get(speed, "2.5s")
    pad = bw + 1  # inner card inset

    title_html = (
        f'<div style="font-size:1rem;font-weight:700;color:#202124;margin-bottom:8px;">'
        f'{_cv_esc(title)}</div>'
    ) if title else ""

    body_html = _md_inline(body) if body else ""

    return (
        f'<style>'
        f'.{cid}-wrap{{position:relative;border-radius:12px;padding:{pad}px;'
        f'overflow:hidden;background:{_cv_esc(bg)};margin:1rem 0;}}'
        f'.{cid}-wrap::before{{content:"";position:absolute;inset:-100%;'
        f'width:300%;height:300%;'
        f'background:conic-gradient(from 0deg,transparent 0deg,{_cv_esc(accent)} 60deg,'
        f'{_cv_esc(accent2)} 120deg,transparent 180deg);'
        f'animation:{cid}-spin {dur} linear infinite;z-index:0;}}'
        f'.{cid}-inner{{position:relative;z-index:1;background:{_cv_esc(bg)};'
        f'border-radius:{12 - pad}px;padding:20px 22px;}}'
        f'@keyframes {cid}-spin{{to{{transform:rotate(360deg)}}}}'
        f'</style>'
        f'<div data-cb="node" data-key="{_cv_esc(str(b["title"])) if b.get("title") else "animated_border_card"}" class="{cid}-wrap">'
        f'<div class="{cid}-inner">'
        f'{title_html}'
        f'<div style="font-size:0.92rem;color:#3c4043;line-height:1.6;">{body_html}</div>'
        f'</div>'
        f'</div>'
    )


def _render_aurora_background(b: dict) -> str:
    import hashlib
    aid    = "au_" + hashlib.md5(str(b.get("colors", "")).encode()).hexdigest()[:6]
    colors = b.get("colors", ["#38bdf8", "#818cf8", "#34d399"])
    speed  = b.get("speed", "slow")
    title  = b.get("title", "")
    body   = b.get("body", "")
    opacity   = b.get("opacity", 0.5)
    background = b.get("background", "#0a0f1d")

    d1, d2, d3 = {"slow": ("14s","18s","11s"), "normal": ("7s","10s","6s"),
                  "fast": ("3s","5s","3s")}.get(speed, ("14s","18s","11s"))
    c1 = colors[0] if len(colors) > 0 else "#38bdf8"
    c2 = colors[1] if len(colors) > 1 else "#818cf8"
    c3 = colors[2] if len(colors) > 2 else "#34d399"

    title_html = (
        f'<div style="font-size:1.1rem;font-weight:700;color:#f1f5f9;margin-bottom:8px;">'
        f'{_cv_esc(title)}</div>'
    ) if title else ""
    body_html = (
        f'<div style="font-size:0.9rem;color:var(--muted,#5f6368);line-height:1.65;">'
        f'{_md_inline(body)}</div>'
    ) if body else ""

    return (
        f'<style>'
        f'.{aid}{{position:relative;border-radius:16px;overflow:hidden;'
        f'background:{_cv_esc(background)};padding:40px 36px;margin:1rem 0;min-height:120px;}}'
        f'.{aid}-blobs{{position:absolute;inset:0;overflow:hidden;opacity:{_cv_esc(opacity)};}}'
        f'.{aid}-b1{{position:absolute;top:-20%;left:-10%;width:60%;height:80%;'
        f'background:radial-gradient(ellipse at center,{_cv_esc(c1)} 0%,transparent 70%);'
        f'animation:{aid}-b1 {d1} ease-in-out infinite;}}'
        f'.{aid}-b2{{position:absolute;top:10%;right:-15%;width:70%;height:70%;'
        f'background:radial-gradient(ellipse at center,{_cv_esc(c2)} 0%,transparent 70%);'
        f'animation:{aid}-b2 {d2} ease-in-out infinite;}}'
        f'.{aid}-b3{{position:absolute;bottom:-20%;left:30%;width:50%;height:60%;'
        f'background:radial-gradient(ellipse at center,{_cv_esc(c3)} 0%,transparent 70%);'
        f'animation:{aid}-b3 {d3} ease-in-out infinite;}}'
        f'.{aid}-content{{position:relative;z-index:1;}}'
        f'@keyframes {aid}-b1{{0%,100%{{transform:translate(0,0) scale(1)}}'
        f'50%{{transform:translate(25%,-15%) scale(1.2)}}}}'
        f'@keyframes {aid}-b2{{0%,100%{{transform:translate(0,0) scale(1.1)}}'
        f'50%{{transform:translate(-20%,25%) scale(0.85)}}}}'
        f'@keyframes {aid}-b3{{0%,100%{{transform:translate(0,0)}}'
        f'50%{{transform:translate(-15%,-20%) scale(1.1)}}}}'
        f'</style>'
        f'<div class="{aid}">'
        f'<div class="{aid}-blobs">'
        f'<div class="{aid}-b1"></div>'
        f'<div class="{aid}-b2"></div>'
        f'<div class="{aid}-b3"></div>'
        f'</div>'
        f'<div class="{aid}-content">{title_html}{body_html}</div>'
        f'</div>'
    )


def _render_dot_grid_background(b: dict) -> str:
    import hashlib
    did      = "dg_" + hashlib.md5(str(b.get("variant","dots")).encode()).hexdigest()[:6]
    variant  = b.get("variant", "dots")
    title    = b.get("title", "")
    body     = b.get("body", "")
    dot_color = _safe_css(b.get("dot_color"), "rgba(148,163,184,0.35)")
    background = b.get("background", "#0d1525")
    spacing  = int(b.get("spacing", 24))
    dot_size = _safe_css(b.get("dot_size"), "1")

    if variant == "grid":
        pattern = (f'linear-gradient({_cv_esc(dot_color)} 1px,transparent 1px),'
                   f'linear-gradient(90deg,{_cv_esc(dot_color)} 1px,transparent 1px)')
    elif variant == "cross":
        # thick "+" markers at each intersection
        pattern = (f'linear-gradient({_cv_esc(dot_color)} 1px,transparent 1px),'
                   f'linear-gradient(90deg,{_cv_esc(dot_color)} 1px,transparent 1px)')
    else:  # dots
        pattern = f'radial-gradient(circle,{_cv_esc(dot_color)} {_cv_esc(dot_size)}px,transparent {_cv_esc(dot_size)}px)'

    title_html = (
        f'<div style="font-size:1rem;font-weight:700;color:#f1f5f9;margin-bottom:8px;">'
        f'{_cv_esc(title)}</div>'
    ) if title else ""
    body_html = (
        f'<div style="font-size:0.9rem;color:var(--muted,#5f6368);line-height:1.65;">'
        f'{_md_inline(body)}</div>'
    ) if body else ""

    return (
        f'<div style="margin:1rem 0;border-radius:12px;overflow:hidden;padding:36px;'
        f'background-color:{_cv_esc(background)};background-image:{pattern};'
        f'background-size:{spacing}px {spacing}px;">'
        f'{title_html}{body_html}'
        f'</div>'
    )


def _render_shimmer_button(b: dict) -> str:
    sid = 'sb-' + _wa_uid(b)
    label = _first_text(b.get('label'), b.get('text'), b.get('title')) or 'Click me'
    href = _safe_href(b.get('href'))
    size = b.get('size')
    accent = _safe_css(b.get('accent'), '#38bdf8')
    bg = _safe_css(b.get('background'), '#1e293b')
    speed = b.get('speed')
    description = _text_loose(b.get('description'))
    dur = {'slow': '3s', 'normal': '1.8s', 'fast': '0.9s'}.get(speed, '1.8s') if isinstance(speed, str) else '1.8s'
    pad, fsize = ({'sm': ('8px 18px', '0.82rem'), 'md': ('12px 28px', '0.92rem'), 'lg': ('16px 40px', '1.05rem')}.get(size, ('12px 28px', '0.92rem'))
                  if isinstance(size, str) else ('12px 28px', '0.92rem'))
    hm = re.fullmatch(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})', accent)
    if hm:
        h = hm.group(1)
        h = ''.join(c * 2 for c in h) if len(h) == 3 else h
        hl = 'rgba(' + str(int(h[0:2], 16)) + ',' + str(int(h[2:4], 16)) + ',' + str(int(h[4:6], 16)) + ',0.5)'
    else:
        hl = 'color-mix(in srgb, ' + accent + ' 50%, transparent)'
    tag = 'a' if href else 'button'
    href_attr = (' href="' + _cv_esc(href) + '" target="_top" rel="noopener"') if href else ' type="button"'
    desc_html = ('<div style="margin-top:6px;font-size:0.78rem;color:var(--muted,#5f6368);">' + _cv_esc(description) + '</div>') if description else ''
    return ('<style>'
            '@keyframes ' + sid + '-sw{0%{background-position:-200% center}100%{background-position:200% center}}'
            '.' + sid + '{display:inline-block;padding:' + pad + ';font-size:' + fsize + ';font-weight:600;'
            'color:#f1f5f9;border:1px solid rgba(255,255,255,0.14);border-radius:8px;cursor:pointer;'
            'background:linear-gradient(105deg,' + bg + ' 38%,' + hl + ' 50%,' + bg + ' 62%);'
            'background-size:200% auto;animation:' + sid + '-sw ' + dur + ' linear infinite;'
            'text-decoration:none;letter-spacing:0.01em;}'
            '@media (prefers-reduced-motion:reduce){.' + sid + '{animation:none;}}'
            '</style>'
            '<div data-cb="node" data-key="' + _ck(b.get('label'), 'shimmer_button') + '" style="margin:1rem 0;">'
            '<' + tag + href_attr + ' class="' + sid + '">' + _cv_esc(label) + '</' + tag + '>'
            + desc_html + '</div>')


def _render_card_stack(b: dict) -> str:
    import hashlib
    cid   = "csk_" + hashlib.md5(str(b.get("cards","")).encode()).hexdigest()[:6]
    cards = b.get("cards", [])[:4]
    if not cards:
        return ""
    bg    = b.get("background", "#1e293b")
    border = b.get("border_color", "rgba(255,255,255,0.08)")
    h     = int(b.get("height", 160))

    n = len(cards)
    # angles and vertical offsets per position (front → back)
    all_angles  = [0, -2.5, -4.5, -6.5][:n]
    all_offsets = [0,   6,   12,   18][:n]
    # z-index: front card highest
    z_indices   = list(range(n, 0, -1))

    cards_html = []
    for i, (card, ang, off, z) in enumerate(zip(cards, all_angles, all_offsets, z_indices)):
        is_front = (i == 0)
        z = i + 1
        title = card.get("title", "")
        body  = card.get("body", "")
        accent = card.get("accent", "#38bdf8")
        opacity = 1.0 if is_front else max(0.40, 1.0 - i * 0.22)

        title_html = (
            f'<div style="font-size:0.95rem;font-weight:700;color:#f1f5f9;margin-bottom:5px;">'
            f'{_cv_esc(title)}</div>'
        ) if title and is_front else ""
        body_html = (
            f'<div style="font-size:0.85rem;color:var(--muted,#5f6368);line-height:1.5;'
            f'overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;">'
            f'{_md_inline(body)}</div>'
        ) if body and is_front else ""
        accent_bar = (
            f'<div style="width:28px;height:3px;background:{_cv_esc(accent)};'
            f'border-radius:2px;margin-bottom:10px;"></div>'
        ) if is_front else ""

        cards_html.append(
            f'<div style="position:absolute;top:0;left:0;right:0;height:{h}px;'
            f'border:1px solid {_cv_esc(border)};background:{_cv_esc(bg)};border-radius:12px;border-radius:var(--a2ui-radius,12px);'
            f'padding:20px 22px;box-sizing:border-box;'
            f'transform:rotate({_cv_esc(ang)}deg) translateY({_cv_esc(off)}px);'
            f'z-index:{z};opacity:{opacity};">'
            f'{accent_bar}{title_html}{body_html}'
            f'</div>'
        )

    wrapper_h = h + 18  # extra room for back-card translateY
    return (
        f'<div style="position:relative;height:{wrapper_h}px;'
        f'margin:1.5rem 1rem 1rem;">'
        f'{"".join(cards_html)}'
        f'</div>'
    )


def _render_entity_list(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    items_raw = b.get("items")
    if not isinstance(items_raw, list):
        items_raw = b.get("entities")
    items = items_raw[:200] if isinstance(items_raw, list) else []

    title = _first_text(b.get("title"), "")

    type_colors = {
        "person": "#4f46e5",
        "organization": "#22d3ee",
        "location": "#34d399",
        "product": "#fb923c",
        "event": "#f472b6",
    }
    status_colors = {
        "active": ("#d1fae5", "#059669"),
        "inactive": ("#f3f4f6", "#6b7280"),
        "error": ("#fee2e2", "#dc2626"),
        "pending": ("#fef9c3", "#ca8a04"),
        "in-progress": ("#dbeafe", "#2563eb"),
    }

    cards = []
    for item in items:
        i_obj = item if isinstance(item, dict) else {}
        name = _first_text(i_obj.get("name"), i_obj.get("label"), "")
        raw_k = _first_text(i_obj.get("id"), name)
        k = _cv_esc(raw_k)

        item_type = _first_text(i_obj.get("type"), "").lower()
        type_color = type_colors.get(item_type, "#94a3b8")

        desc = _first_text(i_obj.get("description"), i_obj.get("subtitle"), "")
        icon = _first_text(i_obj.get("icon"), "")
        avatar_url = _safe_href(i_obj.get("avatar_url"), ["http", "https"])
        link = _safe_href(i_obj.get("link"), ["http", "https"])
        status = _first_text(i_obj.get("status"), "")
        meta = _first_text(i_obj.get("meta"), "")

        initial = name[:1].upper() if name else "?"

        if icon:
            avatar_inner = f'<div class="a2ui-entity-initials" style="background:{type_color};">{_cv_esc(icon)}</div>'
        elif avatar_url:
            avatar_inner = (
                f'<img src="{_cv_esc(avatar_url)}" width="40" height="40" style="border-radius:50%;object-fit:cover;" '
                f'onerror="this.style.display=\'none\';this.nextSibling.style.display=\'flex\'"/>'
                f'<div class="a2ui-entity-initials" style="display:none;background:{type_color};">{_cv_esc(initial)}</div>'
            )
        else:
            avatar_inner = f'<div class="a2ui-entity-initials" style="background:{type_color};">{_cv_esc(initial)}</div>'

        avatar_html = f'<div class="a2ui-entity-avatar">{avatar_inner}</div>'

        type_badge = (
            f'<span class="a2ui-entity-type" style="background:{type_color}20;color:{type_color};border:1px solid {type_color}40;">{_cv_esc(item_type)}</span>'
        ) if item_type else ""

        status_badge = ""
        if status:
            sc = status_colors.get(status.lower(), ("#f3f4f6", "#6b7280"))
            status_badge = f'<span class="a2ui-entity-status" style="display:inline-block;font-size:0.72rem;font-weight:600;padding:2px 8px;border-radius:100px;background:{sc[0]};color:{sc[1]};">{_cv_esc(status)}</span>'

        desc_html = f'<div class="a2ui-entity-desc">{_cv_esc(desc)}</div>' if desc else ""
        meta_html = f'<div class="a2ui-entity-meta">{_cv_esc(meta)}</div>' if meta else ""

        info_html = (
            f'<div class="a2ui-entity-info">'
            f'<div data-cb="label" data-key="{k}" class="a2ui-entity-name">{_cv_esc(name)}</div>'
            f'{type_badge}'
            f'{status_badge}'
            f'{desc_html}'
            f'{meta_html}'
            f'</div>'
        )

        if link:
            cards.append(f'<a data-cb="item" data-key="{k}" class="a2ui-entity-card" href="{_cv_esc(link)}" target="_blank" rel="noopener" style="text-decoration:none;">{avatar_html}{info_html}</a>')
        else:
            cards.append(f'<div data-cb="item" data-key="{k}" class="a2ui-entity-card">{avatar_html}{info_html}</div>')

    title_html = f'<div class="a2ui-entity-list-title">{_cv_esc(title)}</div>' if title else ""
    return f'<style>{_ENTITY_CSS}</style><div class="a2ui-entity-list">{title_html}<div class="a2ui-entity-grid">{"".join(cards)}</div></div>'


def _render_prompt_template(b: dict) -> str:
    """LLM prompt with {slot} (or {{slot}}) placeholders highlighted. Copy button included."""
    template = _text_loose(b.get('template'))
    accent = _safe_css(b.get('accent'), '#7c3aed')
    copyable = b.get('copyable') is not False
    label = _text_loose(b.get('label'))
    title = _text_loose(b.get('title')) or 'prompt template'
    use_case = _text_loose(b.get('use_case'))
    variables = b.get('variables') if isinstance(b.get('variables'), list) else []
    pid = 'pt_' + _wa_uid(b)
    hm = re.fullmatch(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})', accent)
    if hm:
        h = hm.group(1)
        h = ''.join(c * 2 for c in h) if len(h) == 3 else h
        slot_bg = 'rgba(' + str(int(h[0:2], 16)) + ',' + str(int(h[2:4], 16)) + ',' + str(int(h[4:6], 16)) + ',0.1)'
    else:
        slot_bg = 'color-mix(in srgb, ' + accent + ' 10%, transparent)'

    def _highlight(m):
        return ('<span style="background:' + slot_bg + ';color:' + accent + ';font-weight:600;border-radius:3px;padding:0 3px;">' + m.group(0) + '</span>')
    highlighted = re.sub(r'\{\{[^{}]+\}\}|\{[^{}]+\}', _highlight, _cv_esc(template)).replace('\n', '<br>')
    label_html = ('<div style="font-size:0.72rem;font-weight:600;color:var(--muted,#5f6368);text-transform:uppercase;letter-spacing:0.06em;margin-bottom:6px;">'
                  + _cv_esc(label) + '</div>') if label else ''
    copy_btn = ('<button type="button" onclick="navigator.clipboard.writeText(document.getElementById(\'' + pid + '-src\').innerText)" '
                'style="padding:4px 10px;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
                'background:#ffffff;background:var(--a2ui-surface,#ffffff);font-size:0.75rem;color:#5f6368;cursor:pointer;flex-shrink:0;">Copy</button>') if copyable else ''
    use_html = ('<span style="font-size:0.72rem;color:var(--muted,#5f6368);">' + _cv_esc(use_case) + '</span>') if use_case else ''
    right = ('<span style="display:flex;align-items:center;gap:10px;">' + use_html + copy_btn + '</span>') if (use_html and copy_btn) else (use_html + copy_btn)
    braced = '{{%s}}' if '{{' in template else '{%s}'
    rows = ''
    n = 0
    for v in variables:
        if not isinstance(v, dict):
            continue
        name = _text_loose(v.get('name'))
        desc = _text_loose(v.get('description'))
        ex = _text_loose(v.get('example'))
        if not (name or desc or ex):
            continue
        rows += ('<tr' + ('' if n % 2 == 0 else ' style="background:#f9fafb;"') + '>'
                 '<td style="padding:8px 10px;font-family:monospace;font-size:0.82rem;color:' + accent + ';white-space:nowrap;">' + (_cv_esc(braced % name) if name else '') + '</td>'
                 '<td style="padding:8px 10px;font-size:0.82rem;color:#374151;">' + _cv_esc(desc) + '</td>'
                 '<td style="padding:8px 10px;font-size:0.78rem;color:#6b7280;font-style:italic;">' + _cv_esc(ex) + '</td></tr>')
        n += 1
    vars_html = ('<div style="padding:14px 16px;border-top:1px solid #e0e0e0;"><div style="font-size:0.72rem;font-weight:700;color:var(--muted,#5f6368);text-transform:uppercase;letter-spacing:0.06em;margin-bottom:8px;">Variables</div>'
                 '<table style="width:100%;border-collapse:collapse;font-size:0.82rem;"><thead><tr style="background:#f3f4f6;">'
                 '<th scope="col" style="padding:7px 10px;text-align:left;font-size:0.75rem;color:#6b7280;">Variable</th>'
                 '<th scope="col" style="padding:7px 10px;text-align:left;font-size:0.75rem;color:#6b7280;">Description</th>'
                 '<th scope="col" style="padding:7px 10px;text-align:left;font-size:0.75rem;color:#6b7280;">Example</th></tr></thead><tbody>' + rows + '</tbody></table></div>') if rows else ''
    return ('<div data-cb="node" data-key="' + _ck(b.get('label'), 'prompt_template') + '" style="margin:1rem 0;">'
            + label_html
            + '<div style="border:1px solid #e0e0e0;border-radius:8px;overflow:hidden;">'
            '<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 12px;background:#f9fafb;border-bottom:1px solid #e0e0e0;">'
            '<span style="font-size:0.72rem;color:var(--muted,#5f6368);font-family:monospace;">' + _cv_esc(title) + '</span>'
            + right
            + '</div>'
            '<pre id="' + pid + '-src" style="margin:0;padding:14px 16px;font-size:0.84rem;font-family:monospace;line-height:1.6;color:#374151;background:#fff;white-space:pre-wrap;word-break:break-word;">'
            + highlighted + '</pre>'
            + vars_html
            + '</div></div>')


def _render_model_card(b: dict) -> str:
    """AI model spec card: name, provider, context window, pricing, capability badges."""
    name         = b.get("name", "")
    provider     = b.get("provider", "")
    context_win  = b.get("context_window", "")
    pricing      = b.get("pricing", "")
    # Schema says capabilities are plain badge strings, but a common alternate shape sends
    # {label, supported} objects; _esc(str(dict)) happened to still embed the label via
    # Python's repr (an accident, not a design -- GAS's String(obj) on the same shape
    # stringifies to the literal text "[object Object]", losing every badge). Normalise
    # explicitly instead of relying on either language's incidental object-to-string
    # behaviour (surface-parity debt). 2026-09-27.
    capabilities = [c if isinstance(c, str) else (c.get("label") or c.get("text") or str(c))
                     for c in b.get("capabilities", [])]
    accent       = b.get("accent", "#7c3aed")
    badge_bg     = _hex_to_rgba(accent, 0.08)
    badge_border = _hex_to_rgba(accent, 0.30)

    provider_html = (
        f'<span style="font-size:0.72rem;font-weight:600;color:{_cv_esc(accent)};'
        f'text-transform:uppercase;letter-spacing:0.07em;">{_cv_esc(provider)}</span>'
    ) if provider else ""

    meta_items = []
    if context_win:
        meta_items.append(("context", context_win))
    if pricing:
        meta_items.append(("pricing", pricing))
    meta_html = "".join(
        f'<div style="display:flex;flex-direction:column;gap:1px;">'
        f'<span style="font-size:0.68rem;color:var(--muted,#5f6368);text-transform:uppercase;'
        f'letter-spacing:0.05em;">{_cv_esc(k)}</span>'
        f'<span style="font-size:0.82rem;font-weight:600;color:#374151;">{_cv_esc(v)}</span>'
        f'</div>'
        for k, v in meta_items
    )
    meta_wrap = (
        f'<div style="display:flex;gap:24px;margin-top:10px;padding-top:10px;'
        f'border-top:1px solid #f3f4f6;">{meta_html}</div>'
    ) if meta_items else ""

    badges = "".join(
        f'<span style="font-size:0.72rem;padding:3px 8px;border-radius:100px;'
        f'background:{badge_bg};color:{_cv_esc(accent)};border:1px solid {badge_border};'
        f'font-weight:500;">{_esc(cap)}</span>'
        for cap in capabilities
    )
    badges_html = (
        f'<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;">{badges}</div>'
    ) if badges else ""

    return (
        f'<div data-cb="node" data-key="{_ck(b.get("name"), "model_card")}" style="margin:1rem 0;padding:16px 18px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
        f'border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
        f'{provider_html}'
        f'<div style="font-size:1.1rem;font-weight:700;color:#111827;margin-top:2px;">{_cv_esc(name)}</div>'
        f'{badges_html}'
        f'{meta_wrap}'
        f'</div>'
    )


def _render_conversation_snippet(b: dict) -> str:
    """User prompt + AI response as chat bubbles."""
    user_label = b.get("user_label", "You")
    user_text  = b.get("user", "")
    ai_label   = b.get("ai_label", "Assistant")
    ai_text    = b.get("response", "")
    accent     = b.get("accent", "#1a73e8")
    user_bg    = _hex_to_rgba(accent, 0.10)
    user_bd    = _hex_to_rgba(accent, 0.25)

    def bubble(label, text, align, bg, bd, label_color):
        return (
            f'<div style="display:flex;flex-direction:column;'
            f'align-items:{"flex-end" if align == "right" else "flex-start"};gap:4px;">'
            f'<span style="font-size:0.7rem;font-weight:600;color:{_cv_esc(label_color)};'
            f'padding:0 4px;">{_cv_esc(label)}</span>'
            f'<div style="max-width:80%;padding:10px 14px;border-radius:12px;border-radius:var(--a2ui-radius,12px);'
            f'border:1px solid {bd};background:{bg};font-size:0.86rem;'
            f'color:#374151;line-height:1.5;white-space:pre-wrap;">{_cv_esc(text)}</div>'
            f'</div>'
        )

    return (
        f'<div data-cb="node" data-key="{_ck(b.get("user_label"), "conversation_snippet")}" style="margin:1rem 0;display:flex;flex-direction:column;gap:12px;">'
        f'{bubble(user_label, user_text, "right", user_bg, user_bd, accent)}'
        f'{bubble(ai_label, ai_text, "left", "#f9fafb", "#e5e7eb", "#6b7280")}'
        f'</div>'
    )


def _render_shortcut_legend(b: dict) -> str:
    """Keyboard shortcut cheat-sheet grid — multiple combos with action labels."""
    title = b.get("title", "")
    items = b.get("items", [])

    title_html = (
        f'<div style="font-size:0.8rem;font-weight:700;color:#374151;margin-bottom:10px;">{_cv_esc(title)}</div>'
    ) if title else ""

    rows = ""
    for item in items:
        keys   = item.get("keys", [])
        action = item.get("action", "")
        kbd_html = "".join(
            f'<kbd style="display:inline-block;padding:2px 7px;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);'
            f'border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);background:#fafafa;background:var(--a2ui-surface-muted,#fafafa);font-family:monospace;'
            f'font-size:0.78rem;color:#374151;box-shadow:0 1px 0 #d1d5db;">{_cv_esc(k)}</kbd>'
            for k in keys
        )
        rows += (
            f'<div style="display:flex;align-items:center;justify-content:space-between;'
            f'padding:6px 0;border-bottom:1px solid #f3f4f6;">'
            f'<span style="font-size:0.82rem;color:#374151;">{_cv_esc(action)}</span>'
            f'<div style="display:flex;gap:3px;align-items:center;">{kbd_html}</div>'
            f'</div>'
        )
    return (
        f'<div style="margin:1rem 0;padding:12px 16px;border:1px solid #e5e7eb;'
        f'border-radius:8px;background:#fff;">'
        f'{title_html}'
        f'{rows}'
        f'</div>'
    )


def _render_rating_summary_bar(b: dict) -> str:
    """Aggregate star-rating histogram with percentage bars per level."""
    average   = b.get("average", 0.0)
    total     = b.get("total", 0)
    breakdown = b.get("breakdown", [])
    accent    = b.get("accent", "#f59e0b")

    max_count = max((entry.get("count", 0) for entry in breakdown), default=1) or 1

    header = (
        f'<div style="display:flex;align-items:baseline;gap:8px;margin-bottom:12px;">'
        f'<span style="font-size:2rem;font-weight:700;color:#111827;">{average:.1f}</span>'
        f'<span style="font-size:0.85rem;color:var(--muted,#5f6368);">/ 5 · {total:,} ratings</span>'
        f'</div>'
    )

    bars = ""
    for entry in breakdown:
        stars = entry.get("stars", 0)
        count = entry.get("count", 0)
        pct   = round(count / total * 100) if total else 0
        width = round(count / max_count * 100)
        bars += (
            f'<div style="display:flex;align-items:center;gap:8px;">'
            f'<span style="font-size:0.78rem;color:#374151;width:2ch;text-align:right;">{_cv_esc(stars)}</span>'
            f'<span style="font-size:0.82rem;color:{_cv_esc(accent)};">★</span>'
            f'<div style="flex:1;height:8px;border-radius:100px;background:#f3f4f6;">'
            f'<div style="width:{width}%;height:100%;border-radius:100px;background:{_cv_esc(accent)};"></div>'
            f'</div>'
            f'<span style="font-size:0.75rem;color:var(--muted,#5f6368);width:3ch;text-align:right;">{pct}%</span>'
            f'</div>'
        )

    return (
        f'<div style="margin:1rem 0;padding:16px 18px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
        f'border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
        f'{header}'
        f'<div style="display:flex;flex-direction:column;gap:6px;">{bars}</div>'
        f'</div>'
    )


def _render_roadmap_card(b: dict) -> str:
    """Product roadmap: periods of items with done / in-progress / planned / deferred badges (a single legacy card with quarter, status and items also renders)."""
    STATUS = {
        'done': ('#d1fae5', '#065f46', '✓', 'done'),
        'in-progress': ('#dbeafe', '#1d4ed8', '→', 'in progress'),
        'planned': ('#f3f4f6', '#4b5563', '○', 'planned'),
        'deferred': ('#fef3c7', '#92400e', '⏸', 'deferred'),
    }

    def norm(s):
        return s.lower().replace('_', '-').replace(' ', '-') if isinstance(s, str) else 'planned'
    title = _text_loose(b.get('title'))
    description = _text_loose(b.get('description'))
    raw = b.get('periods')
    if isinstance(raw, list):
        periods = [p for p in raw[:50] if isinstance(p, dict)]
    elif isinstance(b.get('items'), list) or _text_loose(b.get('quarter')):
        legacy = b.get('items') if isinstance(b.get('items'), list) else []
        periods = [{'label': b.get('quarter'), 'items': [{'text': t, 'status': b.get('status')} for t in legacy]}]
    else:
        periods = []
    title_html = ('<div style="font-size:0.9rem;font-weight:700;color:#111827;margin-bottom:14px;">' + _cv_esc(title) + '</div>') if title else ''
    desc_html = ('<p style="font-size:0.875rem;color:#4b5563;margin:0 0 12px;line-height:1.5;">' + _cv_esc(description) + '</p>') if description else ''
    cols = ''
    for period in periods:
        label = _text_loose(period.get('label'))
        ri = period.get('items')
        item_rows = ''
        for item in (ri[:100] if isinstance(ri, list) else []):
            if isinstance(item, dict):
                text, status = _text_loose(item.get('text')), norm(item.get('status'))
            else:
                text, status = _text_loose(item), 'planned'
            if not text:
                continue
            bg, fg, icon, name = STATUS.get(status, STATUS['planned'])
            item_rows += ('<div style="display:flex;align-items:flex-start;gap:7px;padding:5px 0;">'
                          '<span style="font-size:0.72rem;font-weight:700;padding:1px 5px;border-radius:4px;background:' + bg + ';color:' + fg + ';flex-shrink:0;">'
                          '<span aria-hidden="true">' + icon + '</span>'
                          '<span style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;">' + name + ': </span></span>'
                          '<span style="font-size:0.8rem;color:#374151;">' + _cv_esc(text) + '</span></div>')
        cols += ('<div style="flex:1;min-width:120px;">'
                 + ('<div style="font-size:0.72rem;font-weight:700;color:var(--muted,#5f6368);text-transform:uppercase;letter-spacing:0.06em;margin-bottom:8px;">' + _cv_esc(label) + '</div>' if label else '')
                 + item_rows + '</div>')
    return ('<div style="margin:1rem 0;padding:16px 18px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
            'border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#ffffff;background:var(--a2ui-surface,#ffffff);">'
            + title_html + desc_html
            + '<div style="display:flex;gap:16px;flex-wrap:wrap;">' + cols + '</div></div>')


def _render_notification_stack(b: dict) -> str:
    """Persistent notification inbox: icon + title + body + time + unread dot."""
    title = b.get("title", "")
    items = b.get("items", [])

    title_html = (
        f'<div style="font-size:0.82rem;font-weight:700;color:#374151;'
        f'padding:0 14px 8px;border-bottom:1px solid #f1f1f1;border-bottom:1px solid var(--a2ui-border-soft,#f1f1f1);">{_cv_esc(title)}</div>'
    ) if title else ""

    rows = ""
    for idx, item in enumerate(items):
        icon   = item.get("icon", "🔔")
        ntitle = item.get("title", "")
        body   = item.get("body", "")
        time   = item.get("time", "")
        unread = item.get("unread", False)
        nkey = _cv_esc(item.get("id") or item.get("title") or (idx + 1))

        body_html = (
            f'<div style="font-size:0.75rem;color:#6b7280;margin-top:1px;'
            f'white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{_cv_esc(body)}</div>'
        ) if body else ""
        time_html = (
            f'<div style="font-size:0.7rem;color:#9ca3af;white-space:nowrap;flex-shrink:0;">{_cv_esc(time)}</div>'
        ) if time else ""
        dot = (
            f'<div style="width:8px;height:8px;border-radius:50%;background:#1a73e8;'
            f'flex-shrink:0;margin-top:4px;"></div>'
        ) if unread else '<div style="width:8px;"></div>'

        rows += (
            f'<div data-cb="item" data-key="{nkey}" style="display:flex;align-items:flex-start;gap:10px;padding:10px 14px;'
            f'background:{"#f0f7ff" if unread else "#fff"};'
            f'border-bottom:1px solid #f3f4f6;">'
            f'<span style="font-size:1.2rem;line-height:1;flex-shrink:0;">{_cv_esc(icon)}</span>'
            f'<div style="flex:1;min-width:0;">'
            f'<div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;">'
            f'<span data-cb="label" data-key="{nkey}" style="font-size:0.82rem;font-weight:{"700" if unread else "500"};'
            f'color:#111827;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">{_cv_esc(ntitle)}</span>'
            f'{time_html}'
            f'</div>'
            f'{body_html}'
            f'</div>'
            f'{dot}'
            f'</div>'
        )

    return (
        f'<div style="margin:1rem 0;border:1px solid #e0e0e0;border-radius:10px;'
        f'overflow:hidden;background:#fff;">'
        f'{title_html}'
        f'{rows}'
        f'</div>'
    )


def _render_inline_alert(b: dict) -> str:
    """Compact inline alert: icon + message + optional detail."""
    PALETTES = {
        "info":    {"bg": "#eff6ff", "border": "#93c5fd", "text": "#1e40af", "icon": "ℹ️"},
        "warning": {"bg": "#fffbeb", "border": "#fcd34d", "text": "#92400e", "icon": "⚠️"},
        "error":   {"bg": "#fef2f2", "border": "#fca5a5", "text": "#991b1b", "icon": "🚫"},
        "success": {"bg": "#f0fdf4", "border": "#86efac", "text": "#166534", "icon": "✅"},
    }
    atype  = b.get("type", "info")
    msg    = b.get("message", "")
    detail = b.get("detail", "")
    p      = PALETTES.get(atype, PALETTES["info"])
    icon   = b.get("icon") or p["icon"]

    detail_html = (
        f'<div style="font-size:0.75rem;color:{p["text"]};opacity:0.8;margin-top:2px;">{_cv_esc(detail)}</div>'
    ) if detail else ""

    return (
        f'<div style="display:inline-flex;align-items:flex-start;gap:6px;'
        f'background:{p["bg"]};border:1px solid {p["border"]};border-radius:6px;'
        f'padding:5px 10px;margin:2px 0;max-width:100%;box-sizing:border-box;">'
        f'<span style="font-size:1rem;line-height:1.4;flex-shrink:0;">{_cv_esc(icon)}</span>'
        f'<div>'
        f'<span style="font-size:0.82rem;font-weight:600;color:{p["text"]};'
        f'line-height:1.4;">{_cv_esc(msg)}</span>'
        f'{detail_html}'
        f'</div>'
        f'</div>'
    )


def _render_source_citation(b: dict) -> str:
    # Inline-numbered RAG source reference card list with metadata, excerpt quotes, and notes.
    raw_heading = b.get('heading')
    heading_text = _first_text(raw_heading) if raw_heading is not None else 'Sources'

    raw_sources = b.get('sources')
    if isinstance(raw_sources, list):
        sources = raw_sources[:100]
    elif _first_text(b.get('title')):
        authors_val = b.get('authors') if isinstance(b.get('authors'), list) else b.get('author')
        author_str = ', '.join(_text_loose(a) for a in authors_val if _text_loose(a)) if isinstance(authors_val, list) else _first_text(b.get('author'))
        sources = [{
            'number': 1,
            'title': _first_text(b.get('title')),
            'url': _first_text(b.get('url')),
            'author': author_str,
            'date': _first_text(b.get('year'), b.get('date')),
            'publisher': _first_text(b.get('publisher')),
            'note': _first_text(b.get('note'))
        }]
    else:
        sources = []

    heading_html = (
        f'<div style="font-size:0.78rem;font-weight:700;color:#374151;letter-spacing:0.06em;text-transform:uppercase;margin-bottom:8px;">'
        f'{_cv_esc(heading_text)}</div>'
    ) if heading_text else ''

    cards = []
    for idx, s in enumerate(sources):
        if isinstance(s, dict):
            num = _first_text(s.get('number')) or str(idx + 1)
            title = _first_text(s.get('title'))
            url = _first_text(s.get('url'))
            excerpt = _first_text(s.get('excerpt'))
            authors_val = s.get('authors') if isinstance(s.get('authors'), list) else s.get('author')
            if isinstance(authors_val, list):
                author = ', '.join(_text_loose(a) for a in authors_val if _text_loose(a))
            else:
                author = _first_text(s.get('author'))
            date = _first_text(s.get('date'), s.get('year'))
            publisher = _first_text(s.get('publisher'))
            note = _first_text(s.get('note'))
        elif (isinstance(s, str) or (isinstance(s, (int, float)) and not isinstance(s, bool))):
            num = str(idx + 1)
            title = _text_loose(s)
            url = ''
            excerpt = ''
            author = ''
            date = ''
            publisher = ''
            note = ''
        else:
            continue

        meta_parts = [p for p in (author, date) if p]
        meta = ' · '.join(meta_parts)
        safe_url = _safe_href(url, schemes=('https', 'mailto'))

        if safe_url:
            title_el = f'<a href="{_cv_esc(safe_url)}" target="_blank" rel="noopener" style="font-size:0.82rem;font-weight:600;color:#1a73e8;text-decoration:none;">{_cv_esc(title)}</a>'
        else:
            title_el = f'<span style="font-size:0.82rem;font-weight:600;color:#111827;">{_cv_esc(title)}</span>'

        excerpt_el = f'<div style="font-size:0.75rem;color:var(--muted,#5f6368);margin-top:3px;font-style:italic;border-left:2px solid #e5e7eb;padding-left:8px;">"{_cv_esc(excerpt)}"</div>' if excerpt else ''
        meta_el = f'<div style="font-size:0.7rem;color:var(--muted,#5f6368);margin-top:2px;">{_cv_esc(meta)}</div>' if meta else ''
        publisher_el = f'<div style="font-size:0.7rem;color:var(--muted,#5f6368);margin-top:2px;font-style:italic;">{_cv_esc(publisher)}</div>' if publisher else ''
        note_el = f'<div style="font-size:0.75rem;color:#4b5563;margin-top:4px;background:#f3f4f6;padding:4px 8px;border-radius:4px;">{_cv_esc(note)}</div>' if note else ''

        cards.append(
            f'<li style="display:flex;gap:10px;padding:8px 10px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);background:#fafafa;background:var(--a2ui-surface-muted,#fafafa);">'
            f'<span style="font-size:0.72rem;font-weight:700;color:#fff;background:#6b7280;border-radius:3px;padding:1px 5px;flex-shrink:0;align-self:flex-start;margin-top:1px;"><span style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;">Source </span>[{_cv_esc(num)}]</span>'
            f'<div style="flex:1;min-width:0;">{title_el}{excerpt_el}{meta_el}{publisher_el}{note_el}</div>'
            f'</li>'
        )

    return (
        f'<div style="margin:1rem 0;">'
        f'{heading_html}'
        f'<ol style="list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;">{"".join(cards)}</ol>'
        f'</div>'
    )


def _render_llm_comparison_table(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    prompt = _first_text(b.get("prompt"), "")
    models_raw = b.get("models")
    models = models_raw[:200] if isinstance(models_raw, list) else []

    show_meta = b.get("show_meta")
    if show_meta is None:
        show_meta = any(
            isinstance(m, dict) and (m.get("latency_ms") is not None or m.get("cost_usd") is not None or m.get("tokens") is not None)
            for m in models
        )
    else:
        show_meta = show_meta is True

    model_colors = ["#2d5fd0", "#c2185b", "#2e7d32", "#b45309", "#8e24aa"]

    prompt_html = (
        f'<div style="margin-bottom:10px;padding:8px 12px;background:#f8fafc;'
        f'border:1px solid #e2e8f0;border-radius:6px;font-size:0.8rem;'
        f'color:#475569;font-family:monospace;">'
        f'<span style="font-weight:700;color:#374151;">Prompt: </span>{_cv_esc(prompt)}</div>'
    ) if prompt else ""

    col_w = f"{100 // max(len(models), 1)}%"
    headers = []
    outputs = []
    meta_row = []

    for idx, m in enumerate(models):
        m_obj = m if isinstance(m, dict) else {}
        color = model_colors[idx % len(model_colors)]
        name = _first_text(m_obj.get("name"), f"Model {idx+1}")
        out = _first_text(m_obj.get("output"), "")

        lat_num = _num_loose(m_obj.get("latency_ms"))
        cost_num = _num_loose(m_obj.get("cost_usd"))
        toks_num = _num_loose(m_obj.get("tokens"))

        headers.append(
            f'<th data-cb="label" data-key="{_cv_esc(name)}" style="width:{col_w};padding:8px 10px;text-align:left;'
            f'border-bottom:2px solid {color};font-size:0.8rem;font-weight:700;'
            f'color:{color};">{_cv_esc(name)}</th>'
        )
        outputs.append(
            f'<td data-cb="item" data-key="{_cv_esc(name)}" style="width:{col_w};padding:8px 10px;vertical-align:top;'
            f'border-right:1px solid #f3f4f6;font-size:0.8rem;color:#111827;'
            f'line-height:1.55;">{_cv_esc(out)}</td>'
        )
        if show_meta:
            parts = []
            if lat_num is not None:
                parts.append(f"{_text_loose(int(lat_num) if lat_num == int(lat_num) else _rhu(lat_num, 1))} ms")
            if toks_num is not None:
                parts.append(f"{_text_loose(int(toks_num) if toks_num == int(toks_num) else _rhu(toks_num, 1))} tok")
            if cost_num is not None:
                parts.append(f"${_fixed_str(cost_num, 4)}")
            meta_row.append(
                f'<td style="padding:6px 10px;font-size:0.7rem;color:var(--muted,#5f6368);'
                f'border-right:1px solid #f3f4f6;">{_cv_esc(" · ".join(parts))}</td>'
            )

    meta_tr = f'<tr style="background:#f9fafb;">{"".join(meta_row)}</tr>' if (show_meta and meta_row) else ""

    headers_html = "".join(headers)
    outputs_html = "".join(outputs)

    return (
        f'<div style="margin:1rem 0;overflow-x:auto;">'
        f'{prompt_html}'
        f'<table style="width:100%;border-collapse:collapse;'
        f'border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">'
        f'<thead><tr style="background:#f9fafb;">{headers_html}</tr></thead>'
        f'<tbody>'
        f'<tr>{outputs_html}</tr>'
        f'{meta_tr}'
        f'</tbody></table></div>'
    )


def _render_confidence_bar(b: dict) -> str:
    # 0-100 percentage probability bar(s) with accessible ARIA progressbar and colour bands
    import math

    color_override = _safe_css(b.get('color'), '')

    def _render_single(lbl: str, val_raw, is_pct=False) -> str:
        num = _num_loose(val_raw)
        val = 0.0 if num is None else num
        if 0 < val <= 1 and not is_pct:
            val = val * 100   # a fraction (old GAS payloads sent 0-1), as cloud-run-renderer/static/a2ui-atoms-live.v1.js does
        pct = max(0.0, min(100.0, val))
        rounded = math.floor(pct + 0.5)

        if color_override:
            bar_color = color_override
            text_color = color_override
        elif rounded >= 70:
            bar_color = '#22c55e'
            text_color = '#15803d'
        elif rounded >= 40:
            bar_color = '#f59e0b'
            text_color = '#b45309'
        else:
            bar_color = '#ef4444'
            text_color = '#dc2626'

        aria_label = f"{lbl}: {rounded}%" if lbl else f"{rounded}%"
        return (
            f'<div style="margin-bottom:8px;">'
            f'<div style="display:flex;justify-content:space-between;font-size:0.78rem;color:#374151;margin-bottom:3px;">'
            f'<span>{_cv_esc(lbl)}</span>'
            f'<span style="font-weight:700;color:{text_color};">{rounded}%</span>'
            f'</div>'
            f'<div role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{rounded}" aria-label="{_cv_esc(aria_label)}" style="background:#f3f4f6;border-radius:4px;height:8px;overflow:hidden;">'
            f'<div style="width:{rounded}%;height:100%;background:{bar_color};border-radius:4px;transition:width .4s;"></div>'
            f'</div></div>'
        )

    raw_items = b.get('items') if isinstance(b.get('items'), list) else []
    block_label = _first_text(b.get('label'))

    if raw_items:
        head_html = f'<div style="font-size:0.875rem;font-weight:600;color:#374151;margin-bottom:8px;">{_cv_esc(block_label)}</div>' if block_label else ''
        bars = []
        for item in raw_items[:20]:
            if isinstance(item, dict):
                i_lbl = _first_text(item.get('label'), item.get('name'))
                i_val = item.get('value', 0)
                bars.append(_render_single(i_lbl, i_val, item.get('isPercent') is True or b.get('isPercent') is True))
            else:
                bars.append(_render_single('', item, b.get('isPercent') is True))
        content = head_html + ''.join(bars)
    else:
        label_val = block_label if block_label else 'Confidence'
        content = _render_single(label_val, b.get('value', 0), b.get('isPercent') is True)

    return f'<div data-cb="node" data-key="{_ck(b.get("label"), "confidence_bar")}" style="margin:0.75rem 0;">{content}</div>'


def _render_token_budget_meter(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    used_raw = _num_loose(b.get("used"))
    used = min(int(used_raw + 0.5), 10 ** 14) if used_raw is not None and used_raw >= 0 else 0
    total_raw = _num_loose(b.get("total"))
    total = max(1, min(int(total_raw + 0.5), 10 ** 14)) if total_raw is not None and total_raw > 0 else 1

    label = _first_text(b.get("label"), "Context window")
    model = _text_loose(b.get("model"))
    unit = _text_loose(b.get("unit"))
    unit_txt = (" " + unit) if unit else ""
    warn_at_raw = _num_loose(b.get("warn_at"))
    warn_at = warn_at_raw if warn_at_raw is not None else 70.0
    crit_at_raw = _num_loose(b.get("critical_at"))
    crit_at = crit_at_raw if crit_at_raw is not None else 90.0
    animate = b.get("animate") is True
    dur_raw = _num_loose(b.get("duration"))
    duration = min(max(dur_raw, 0.05), 3600.0) if dur_raw is not None and dur_raw > 0 else 2.0

    pct = (used / total) * 100.0
    pct_int = int(pct + 0.5)
    pct_clamped = min(pct, 100.0)

    color = (
        "#ef4444" if pct >= crit_at else
        "#f59e0b" if pct >= warn_at else
        "#15803d"
    )

    def _fmt(n: int) -> str:
        if n >= 1000:
            t = (n * 10 + 500) // 1000
            return f"{t // 10}.{t % 10}k"
        return str(n)

    ck_val = _first_text(b.get("model"), "token_budget_meter")
    model_html = f'<span style="font-size:0.72rem;color:#9ca3af;margin-left:6px;">{_cv_esc(model)}</span>' if model else ""

    if animate:
        uid = _wa_uid(b)
        dur_str = _text_loose(duration)
        return (
            f'<style>'
            f'@property --tok_{uid}{{syntax:"<integer>";initial-value:0;inherits:false;}}'
            f'.tbm_{uid}{{--tok_{uid}:0;counter-reset:tbct_{uid} var(--tok_{uid});'
            f'animation:tbmc_{uid} {dur_str}s ease-in-out forwards;}}'
            f'.tbm_{uid}::before{{content:counter(tbct_{uid});}}'
            f'.tbf_{uid}{{width:0%;animation:tbmb_{uid} {dur_str}s ease-in-out forwards;}}'
            f'@keyframes tbmc_{uid}{{from{{--tok_{uid}:0;}}to{{--tok_{uid}:{used};}}}}'
            f'@keyframes tbmb_{uid}{{from{{width:0%;}}to{{width:{_fixed_str(pct_clamped, 2)}%;}}}}'
            f'@media (prefers-reduced-motion:reduce){{'
            f'.tbm_{uid}{{animation:none;--tok_{uid}:{used};}}'
            f'.tbf_{uid}{{animation:none;width:{_fixed_str(pct_clamped, 2)}%;}}'
            f'}}'
            f'</style>'
            f'<div data-cb="node" data-key="{_cv_esc(ck_val)}" style="margin:0.75rem 0;padding:10px 14px;border:1px solid #374151;'
            f'border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#111827;">'
            f'<div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px;">'
            f'<span style="font-size:1rem;font-weight:700;color:#ffffff;">'
            f'{_cv_esc(label)}{model_html}</span>'
            f'<span style="font-size:2rem;font-weight:800;color:#ffffff;font-family:monospace;">'
            f'<span class="tbm_{uid}" aria-hidden="true"></span>'
            f'<span style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;">{used} of {total}</span>'
            f'<span style="color:#6b7280;"> / {_fmt(total)}{_cv_esc(unit_txt)}</span>'
            f'<span style="font-size:1rem;color:#9ca3af;margin-left:8px;">({pct_int}%)</span>'
            f'</span>'
            f'</div>'
            f'<div style="background:#374151;border-radius:4px;height:10px;overflow:hidden;">'
            f'<div class="tbf_{uid}" style="height:100%;background:{color};border-radius:4px;"></div>'
            f'</div>'
            f'</div>'
        )

    return (
        f'<div data-cb="node" data-key="{_cv_esc(ck_val)}" style="margin:0.75rem 0;padding:10px 14px;border:1px solid #e5e7eb;'
        f'border-radius:8px;background:#fafafa;">'
        f'<div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px;">'
        f'<span style="font-size:0.8rem;font-weight:600;color:#374151;">'
        f'{_cv_esc(label)}{model_html}</span>'
        f'<span style="font-size:0.78rem;font-weight:700;color:{color};">'
        f'{_fmt(used)} / {_fmt(total)}{_cv_esc(unit_txt)} ({pct_int}%)</span>'
        f'</div>'
        f'<div style="background:#e5e7eb;border-radius:4px;height:10px;overflow:hidden;">'
        f'<div style="width:{_fixed_str(pct_clamped, 1)}%;height:100%;background:{color};border-radius:4px;"></div>'
        f'</div>'
        f'</div>'
    )


def _render_chartjs_pie(b: dict) -> str:
    """Multi-slice pie/donut SVG chart with legend. Source: OpenUI/Thesys MIT."""
    import math
    title       = b.get("title", "")
    variant     = b.get("variant", "donut")
    data        = b.get("data", [])
    show_legend = b.get("show_legend", True)
    show_labels = b.get("show_labels", True)
    custom_colors = b.get("colors", [])

    DEFAULT_COLORS = [
        "#2d5fd0","#c2185b","#2e7d32","#b45309","#8e24aa",
        "#26c6da","#ef5350","#8d6e63","#78909c","#26a69a",
    ]

    total = sum(item.get("value", 0) for item in data) or 1
    cx, cy, r = 120, 120, 90
    hole = 54 if variant == "donut" else 0

    def polar(cx, cy, r, angle_deg):
        rad = math.radians(angle_deg - 90)
        return cx + r * math.cos(rad), cy + r * math.sin(rad)

    slices_svg = ""
    legend_html = ""
    start = 0.0
    for idx, item in enumerate(data):
        label = item.get("label", f"Slice {idx+1}")
        value = item.get("value", 0)
        pct   = value / total
        sweep = pct * 360
        color = custom_colors[idx] if idx < len(custom_colors) else DEFAULT_COLORS[idx % len(DEFAULT_COLORS)]

        end = start + sweep
        large = 1 if sweep > 180 else 0

        x1, y1 = polar(cx, cy, r, start)
        x2, y2 = polar(cx, cy, r, end)

        if hole:
            xi1, yi1 = polar(cx, cy, hole, start)
            xi2, yi2 = polar(cx, cy, hole, end)
            path = (
                f"M {x1:.2f} {y1:.2f} "
                f"A {r} {r} 0 {large} 1 {x2:.2f} {y2:.2f} "
                f"L {xi2:.2f} {yi2:.2f} "
                f"A {hole} {hole} 0 {large} 0 {xi1:.2f} {yi1:.2f} Z"
            )
        else:
            path = (
                f"M {cx} {cy} "
                f"L {x1:.2f} {y1:.2f} "
                f"A {r} {r} 0 {large} 1 {x2:.2f} {y2:.2f} Z"
            )
        slices_svg += f'<path data-cb="arc" data-key="{_cv_esc(label)}" d="{path}" fill="{_cv_esc(color)}" stroke="#fff" stroke-width="2"/>'

        if show_labels and pct > 0.04:
            mid = start + sweep / 2
            lx, ly = polar(cx, cy, (r + hole) / 2 if hole else r * 0.65, mid)
            slices_svg += (
                f'<text x="{lx:.1f}" y="{ly:.1f}" text-anchor="middle" '
                f'dominant-baseline="middle" font-size="10" fill="#fff" font-weight="600">'
                f'{round(pct*100)}%</text>'
            )

        if show_legend:
            legend_html += (
                f'<div data-cb="label" data-key="{_cv_esc(label)}" style="display:flex;align-items:center;gap:6px;font-size:0.75rem;color:#374151;">'
                f'<span style="width:10px;height:10px;border-radius:2px;background:{_cv_esc(color)};flex-shrink:0;"></span>'
                f'<span>{_cv_esc(label)}</span>'
                f'<span style="margin-left:auto;font-weight:600;">{round(pct*100)}%</span>'
                f'</div>'
            )
        start = end

    title_html = (
        f'<div style="font-size:0.85rem;font-weight:700;color:#111827;text-align:center;'
        f'margin-bottom:6px;">{_cv_esc(title)}</div>'
    ) if title else ""

    legend_block = (
        f'<div style="display:flex;flex-direction:column;gap:5px;margin-top:10px;">{legend_html}</div>'
    ) if show_legend else ""

    return (
        f'<div style="margin:1rem 0;text-align:center;">'
        f'{title_html}'
        f'<svg viewBox="0 0 240 240" width="200" height="200" role="img" aria-label="{_cv_esc(title or "Pie chart")}" style="overflow:visible;">'
        f'{slices_svg}'
        f'</svg>'
        f'{legend_block}'
        f'</div>'
    )


def _render_text_callout(b: dict) -> str:
    """Lightweight tinted tip/note block. Source: OpenUI/Thesys MIT."""
    PALETTES = {
        "info":    {"bg": "#eff6ff", "border": "#dbeafe", "title": "#1e40af", "body": "#1e3a8a"},
        "success": {"bg": "#f0fdf4", "border": "#dcfce7", "title": "#166534", "body": "#14532d"},
        "warning": {"bg": "#fffbeb", "border": "#fef3c7", "title": "#92400e", "body": "#78350f"},
        "neutral": {"bg": "#f9fafb", "border": "#e5e7eb", "title": "#374151", "body": "#4b5563"},
    }
    variant = b.get("variant", "neutral")
    title   = b.get("title", "")
    desc    = b.get("description", "")
    p       = PALETTES.get(variant, PALETTES["neutral"])

    return (
        f'<div data-cb="node" data-key="{_ck(b.get("title"), "text_callout")}" style="margin:0.5rem 0;padding:8px 12px;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);'
        f'background:{p["bg"]};border:1px solid {p["border"]};">'
        f'<div style="font-size:0.78rem;font-weight:700;color:{p["title"]};'
        f'margin-bottom:2px;">{_cv_esc(title)}</div>'
        f'<div style="font-size:0.8rem;color:{p["body"]};line-height:1.5;">{_cv_esc(desc)}</div>'
        f'</div>'
    )


def _render_tag_block(b: dict) -> str:
    """Horizontal wrap of neutral content chip labels. Source: OpenUI/Thesys MIT."""
    tags   = b.get("tags", [])
    color  = b.get("color", "")
    bg     = color or "#f3f4f6"
    border = color or "#d1d5db"
    text   = "#374151"

    chips = "".join(
        f'<span style="display:inline-block;padding:3px 10px;border-radius:9999px;'
        f'background:{_cv_esc(bg)};border:1px solid {_cv_esc(border)};color:{text};'
        f'font-size:0.78rem;font-weight:500;white-space:nowrap;">{_cv_esc(t)}</span>'
        for t in tags
    )
    return (
        f'<div style="display:flex;flex-wrap:wrap;gap:6px;margin:0.75rem 0;">'
        f'{chips}'
        f'</div>'
    )


def _render_variant_selector(b: dict) -> str:
    """CSS-only radio card group for variant picking. Source: OpenUI/Thesys MIT."""
    name = _text_loose(b.get('name')) or ('variant-' + _wa_uid(b))
    label = _text_loose(b.get('label'))
    raw = b.get('items') if isinstance(b.get('items'), list) and b.get('items') else b.get('variants')
    items = [v for v in raw[:100] if isinstance(v, dict) or _text_loose(v)] if isinstance(raw, list) else []
    default = _text_loose(b.get('default_value'))
    uid = 'vs-' + _wa_uid(b)
    label_html = ('<div style="font-size:0.82rem;font-weight:600;color:#374151;margin-bottom:8px;">' + _cv_esc(label) + '</div>') if label else ''
    style = ('<style>'
             '.' + uid + ' label{display:block;padding:10px 14px;border:1px solid #d1d5db;border-radius:8px;cursor:pointer;transition:border-color .15s,background .15s;background:#fff;}'
             '.' + uid + ' label:has(input:checked){border-color:#1a73e8;background:#eff6ff;}'
             '.' + uid + ' label:has(input:focus-visible){outline:2px solid #1a73e8;outline-offset:2px;}'
             '.' + uid + ' label:has(input:disabled){opacity:0.4;cursor:not-allowed;}'
             '.' + uid + ' label:hover{border-color:#9ca3af;}'
             '.' + uid + ' input{position:absolute;opacity:0;width:0;height:0;}'
             '</style>')
    cards = ''
    checked_done = False
    for v in items:
        if isinstance(v, dict):
            val = _text_loose(v.get('value'))
            title = _first_text(v.get('title'), v.get('label'), v.get('value'))
            desc = _text_loose(v.get('description'))
            color = _safe_css(v.get('color'), '')
            disabled = v.get('disabled') is True
        else:
            val = title = _text_loose(v)
            desc = color = ''
            disabled = False
        chk = ''
        if not checked_done and default and val == default:
            chk = ' checked'
            checked_done = True
        dot = ('<span aria-hidden="true" style="display:inline-block;width:12px;height:12px;border-radius:50%;background:' + color + ';margin-right:8px;vertical-align:middle;"></span>') if color else ''
        desc_html = ('<div style="font-size:0.75rem;color:var(--muted,#5f6368);margin-top:2px;">' + _cv_esc(desc) + '</div>') if desc else ''
        cards += ('<label><input type="radio" name="' + _cv_esc(name) + '" value="' + _cv_esc(val) + '"' + chk + (' disabled' if disabled else '') + '>'
                  '<div style="font-size:0.85rem;font-weight:600;color:#111827;">' + dot + _cv_esc(title) + '</div>' + desc_html + '</label>')
    return (style + '<div style="margin:0.75rem 0;">' + label_html
            + '<div class="' + uid + '" role="radiogroup" aria-label="' + _cv_esc(label or name) + '" style="display:flex;flex-direction:column;gap:8px;">' + cards + '</div></div>')


def _render_markdown_block(b: dict) -> str:
    """GFM markdown string rendered to HTML. Source: OpenUI/Thesys MIT."""
    content = b.get("content", "")
    variant = b.get("variant", "default")
    margin  = "0.5rem 0" if variant == "compact" else "1rem 0"

    html = _md.markdown(
        content,
        extensions=["tables", "fenced_code", "nl2br"],
    )
    return (
        f'<div class="md-block" style="margin:{margin};'
        f'font-size:0.9rem;line-height:1.65;color:#202124;">'
        f'{html}'
        f'</div>'
    )


# ── React/Tailwind second wave ────────────────────────────────────────────────

def _render_multi_select_input(b: dict) -> str:
    """Tag/chip style multi-value select — shadcn multi-select pattern."""
    import html as _h
    label       = b.get("label", "")
    name        = b.get("name", "ms")
    options     = b.get("options", [])
    selected    = b.get("selected", [])
    placeholder = b.get("placeholder", "Add option…")

    chips_html = "".join(
        f'<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px 3px 10px;'
        f'background:#e8f0fe;color:#1558b4;border-radius:14px;font-size:0.82rem;font-weight:500;">'
        f'{_h.escape(next((o.get("label", v) for o in options if o.get("value")==v), v))}'
        f'<span style="color:#5f6368;margin-left:1px;cursor:pointer;">×</span></span>'
        for v in selected
    )
    avail = [o for o in options if o.get("value") not in selected]
    avail_html = "".join(
        f'<div style="display:flex;align-items:center;gap:8px;padding:8px 12px;'
        f'cursor:pointer;font-size:0.87rem;color:#3c4043;">'
        f'<span style="width:16px;height:16px;border:2px solid #dadce0;border-radius:3px;'
        f'flex-shrink:0;display:inline-block;"></span>'
        f'{_h.escape(o.get("label",""))}</div>'
        for o in avail[:6]
    )
    label_html = (
        f'<label style="display:block;font-size:0.83rem;font-weight:600;'
        f'color:#3c4043;margin-bottom:5px;">{_h.escape(label)}</label>'
    ) if label else ""
    return (
        f'<div style="margin:1rem 0;max-width:360px;">{label_html}'
        f'<div style="border:1px solid #dadce0;border-radius:6px;overflow:hidden;'
        f'box-shadow:0 4px 14px rgba(0,0,0,0.07);">'
        f'<div style="display:flex;flex-wrap:wrap;gap:6px;padding:8px 10px;background:#fff;'
        f'border-bottom:1px solid #f1f3f4;min-height:42px;align-items:center;">'
        f'{chips_html}'
        f'<input type="text" placeholder="{_h.escape(placeholder)}" '
        f'style="border:none;outline:none;font-size:0.87rem;color:#3c4043;'
        f'background:transparent;min-width:90px;flex:1;padding:2px 0;"></div>'
        f'{avail_html}</div></div>'
    )


def _render_otp_input(b: dict) -> str:
    """6-box one-time password input — shadcn OTP field pattern."""
    import html as _h
    length = int(b.get("length", 6))
    value  = str(b.get("value", ""))
    label  = b.get("label", "")

    boxes = ""
    for i in range(length):
        digit        = value[i] if i < len(value) else ""
        border_color = "#1a73e8" if digit else "#dadce0"
        bg           = "#f0f4ff" if digit else "#fff"
        boxes += (
            f'<input type="text" maxlength="1" value="{_cv_esc(digit)}" '
            f'style="width:44px;height:52px;text-align:center;font-size:1.3rem;'
            f'font-weight:700;border:2px solid {border_color};border-radius:8px;'
            f'background:{bg};color:#202124;outline:none;'
            f'transition:border-color .15s,background .15s;">'
        )
    label_html = (
        f'<div style="font-size:0.83rem;font-weight:600;color:#3c4043;margin-bottom:10px;">'
        f'{_h.escape(label)}</div>'
    ) if label else ""
    return f'<div style="margin:1rem 0;">{label_html}<div style="display:flex;gap:8px;">{boxes}</div></div>'


def _render_bento_grid(b: dict) -> str:
    """Asymmetric bento box feature grid — MagicUI/shadcn pattern."""
    import html as _h
    tiles   = b.get("tiles", [])
    heading = b.get("heading", "")
    cols    = int(b.get("columns", 3))

    heading_html = (
        f'<h3 style="font-size:1.3rem;font-weight:700;color:#202124;margin:0 0 16px;">'
        f'{_h.escape(heading)}</h3>'
    ) if heading else ""

    _COLORS = ["#1a73e8","#34a853","#ea4335","#fbbc04","#9c27b0","#00bcd4","#ff6d00","#00897b"]
    tiles_html = ""
    for i, tile in enumerate(tiles):
        title    = tile.get("title", "")
        subtitle = tile.get("subtitle", tile.get("description", ""))
        icon     = tile.get("icon", "")
        span     = int(tile.get("span", 1))
        color    = tile.get("color", _COLORS[i % len(_COLORS)])
        bg       = tile.get("background", f"{_cv_esc(color)}0d")
        col_span = f"1 / span {min(span, cols)}" if span > 1 else "auto"
        icon_html = f'<span style="font-size:1.7rem;margin-bottom:4px;">{_cv_esc(icon)}</span>' if icon else ""
        tiles_html += (
            f'<div style="grid-column:{col_span};background:{_cv_esc(bg)};border:1px solid {_cv_esc(color)}28;'
            f'border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:20px 22px;display:flex;flex-direction:column;gap:6px;">'
            f'{icon_html}'
            f'<div style="font-size:{"1.05rem" if span>1 else "0.92rem"};'
            f'font-weight:700;color:#202124;">{_h.escape(title)}</div>'
            f'<div style="font-size:0.82rem;color:#5f6368;line-height:1.55;">{_h.escape(subtitle)}</div>'
            f'</div>'
        )
    return (
        f'<div style="margin:1.5rem 0;">{heading_html}'
        f'<div style="display:grid;grid-template-columns:repeat({cols},1fr);gap:12px;">'
        f'{tiles_html}</div></div>'
    )


def _render_cta_section(b: dict) -> str:
    """Full-width call-to-action section — Tailwind UI pattern."""
    import html as _h
    heading   = b.get("heading", "")
    body      = b.get("body", b.get("description", ""))
    primary   = b.get("primary_cta", {})
    secondary = b.get("secondary_cta", {})
    bg        = b.get("background", "#1a73e8")

    primary_html = (
        f'<a href="{_h.escape(primary.get("url","#"))}" '
        f'style="display:inline-flex;align-items:center;padding:11px 22px;'
        f'background:#ffffff;background:var(--a2ui-surface,#ffffff);color:{_cv_esc(bg)};font-size:0.9rem;font-weight:700;'
        f'border-radius:12px;border-radius:var(--a2ui-radius,12px);text-decoration:none;">{_h.escape(primary.get("label",""))}</a>'
    ) if primary else ""
    secondary_html = (
        f'<a href="{_h.escape(secondary.get("url","#"))}" '
        f'style="display:inline-flex;align-items:center;padding:11px 22px;'
        f'background:rgba(255,255,255,0.15);color:#fff;font-size:0.9rem;font-weight:600;'
        f'border-radius:8px;text-decoration:none;border:1px solid rgba(255,255,255,0.4);">'
        f'{_h.escape(secondary.get("label",""))}</a>'
    ) if secondary else ""

    return (
        f'<div style="margin:1.5rem 0;background:{_cv_esc(bg)};border-radius:14px;padding:36px 32px;text-align:center;">'
        f'<h3 style="font-size:1.4rem;font-weight:800;color:#fff;margin:0 0 10px;">{_h.escape(heading)}</h3>'
        f'<p style="font-size:0.93rem;color:rgba(255,255,255,0.85);margin:0 auto 24px;'
        f'max-width:480px;line-height:1.65;">{_h.escape(body)}</p>'
        f'<div style="display:flex;justify-content:center;gap:12px;flex-wrap:wrap;">'
        f'{primary_html}{secondary_html}</div></div>'
    )


def _render_animated_counter(b: dict) -> str:
    """CSS @property counter animation — counts up to target values without JS."""
    counters = b.get("counters", [])
    if not counters and b.get("value") is not None:
        counters = [{"value": b.get("value"), "label": b.get("label", ""),
                     "suffix": b.get("suffix", ""), "prefix": b.get("prefix", "")}]
    duration = float(b.get("duration", 2))
    _COLORS  = ["#1a73e8","#34a853","#ea4335","#9c27b0","#ff6d00","#00bcd4"]
    uid      = abs(_wa_shash(str(counters))) % 100000

    style_parts = []
    items_html  = ""
    for i, c in enumerate(counters):
        raw_val = str(c.get("value", 0)).replace(",", "").rstrip("%+kKmM")
        try:
            val = int(float(raw_val))
        except ValueError:
            val = 0
        label  = c.get("label", "")
        suffix = c.get("suffix", "")
        prefix = c.get("prefix", "")
        color  = c.get("color", _COLORS[i % len(_COLORS)])
        prop   = f"--ac{uid}p{_cv_esc(i)}"
        cv     = f"ac{uid}cv{_cv_esc(i)}"
        cid    = f"ac{uid}i{_cv_esc(i)}"
        style_parts.append(
            f'@property {prop}{{syntax:"<integer>";initial-value:0;inherits:false;}}'
            f'@keyframes {cid}{{from{{{prop}:0}}to{{{prop}:{val}}}}}'
            f'.{cid}{{animation:{cid} {duration}s ease-out forwards;counter-reset:{cv} var({prop});}}'
            f'.{cid}::after{{content:"{_cv_esc(prefix)}" counter({cv}) "{_cv_esc(suffix)}";'
            f'font-size:2.2rem;font-weight:800;color:{_cv_esc(color)};}}'
        )
        items_html += (
            f'<div style="text-align:center;padding:16px 28px;">'
            f'<div class="{cid}"></div>'
            f'<div style="font-size:0.84rem;color:#5f6368;margin-top:4px;font-weight:500;">'
            f'{_cv_esc(label)}</div></div>'
        )

    return (
        f'<style>{"".join(style_parts)}</style>'
        f'<div style="margin:1.5rem 0;display:flex;flex-wrap:wrap;justify-content:center;'
        f'gap:8px;border:1px solid #e5e7eb;border-radius:12px;background:#fff;padding:12px 0;">'
        f'{items_html}</div>'
    )


# ── React/Tailwind ecosystem atoms (shadcn/ui, Radix, Tailwind UI patterns) ──

def _render_combobox(b: dict) -> str:
    """Searchable filterable dropdown — shadcn/Headless UI combobox pattern."""
    import html as _h
    label       = b.get("label", "")
    name        = b.get("name", "cb")
    placeholder = b.get("placeholder", "Search…")
    options     = b.get("options", [])
    selected    = b.get("selected", "")
    rules       = b.get("rules", [])
    req_star    = '<span style="color:#ea4335;margin-left:2px;">*</span>' if "required" in rules else ""

    datalist_id   = f"dl-{_cv_esc(name)}"
    datalist_opts = "".join(f'<option value="{_h.escape(o.get("label",""))}"></option>' for o in options)

    selected_label = next((o.get("label","") for o in options if o.get("value") == selected), "")

    opts_html = ""
    for o in options[:7]:
        is_sel  = o.get("value") == selected
        bg      = "#f0f4ff" if is_sel else "#fff"
        fw      = "600"     if is_sel else "400"
        check   = "✓ "      if is_sel else " "
        opts_html += (
            f'<div style="display:flex;align-items:center;gap:6px;padding:8px 12px;'
            f'cursor:pointer;background:{bg};font-size:0.88rem;color:#3c4043;font-weight:{fw};">'
            f'<span style="color:#1a73e8;width:14px;flex-shrink:0;">{check}</span>'
            f'{_h.escape(o.get("label",""))}</div>'
        )
    if len(options) > 7:
        opts_html += (
            f'<div style="padding:6px 12px;font-size:0.78rem;color:#5f6368;border-top:1px solid #f1f3f4;">'
            f'{len(options)-7} more options…</div>'
        )

    label_html = (
        f'<label for="{_cv_esc(name)}" style="display:block;font-size:0.83rem;font-weight:600;'
        f'color:#3c4043;margin-bottom:5px;">{_h.escape(label)}{req_star}</label>'
    ) if label else ""

    return (
        f'<div style="margin:1rem 0;max-width:360px;">'
        f'{label_html}'
        f'<div style="border:1px solid #dadce0;border-radius:6px;overflow:hidden;'
        f'box-shadow:0 4px 14px rgba(0,0,0,0.08);">'
        f'<div style="display:flex;align-items:center;padding:0 10px;gap:6px;background:#fff;'
        f'border-bottom:1px solid #f1f3f4;">'
        f'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5f6368" stroke-width="2">'
        f'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>'
        f'<input type="text" id="{_cv_esc(name)}" name="{_cv_esc(name)}" list="{datalist_id}" '
        f'placeholder="{_h.escape(placeholder)}" value="{_h.escape(selected_label)}" '
        f'style="flex:1;border:none;outline:none;padding:9px 0;font-size:0.9rem;'
        f'color:#3c4043;background:transparent;">'
        f'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#5f6368" stroke-width="2">'
        f'<path d="M6 9l6 6 6-6"/></svg>'
        f'</div>'
        f'<datalist id="{datalist_id}">{datalist_opts}</datalist>'
        f'{opts_html}'
        f'</div>'
        f'</div>'
    )


def _render_feature_grid(b: dict) -> str:
    """Icon + title + description grid — Tailwind UI feature section pattern."""
    import html as _h
    heading     = b.get("heading", "")
    description = b.get("description", "")
    features    = b.get("features", [])
    columns     = int(b.get("columns", 3))

    heading_html = (
        f'<h3 style="font-size:1.3rem;font-weight:700;color:#202124;margin:0 0 8px;">'
        f'{_h.escape(heading)}</h3>'
    ) if heading else ""
    desc_html = (
        f'<p style="font-size:0.93rem;color:#5f6368;margin:0 0 28px;max-width:560px;line-height:1.6;">'
        f'{_h.escape(description)}</p>'
    ) if description else ""

    _COLORS = ["#1a73e8","#34a853","#ea4335","#fbbc04","#9c27b0","#00bcd4","#ff6d00","#00897b"]
    items_html = ""
    for i, feat in enumerate(features):
        icon  = feat.get("icon", "◆")
        title = feat.get("title", "")
        desc  = feat.get("description", "")
        badge = feat.get("badge", "")
        color = feat.get("color", _COLORS[i % len(_COLORS)])
        badge_html = (
            f'<span style="font-size:0.68rem;font-weight:600;letter-spacing:.05em;'
            f'text-transform:uppercase;color:{_cv_esc(color)};background:{_cv_esc(color)}1a;'
            f'padding:2px 7px;border-radius:10px;margin-left:8px;">{_h.escape(badge)}</span>'
        ) if badge else ""
        k = _h.escape(str(title))
        items_html += (
            f'<div data-cb="tile" data-key="{k}" style="display:flex;flex-direction:column;gap:10px;">'
            f'<div style="width:42px;height:42px;border-radius:10px;background:{_cv_esc(color)}18;'
            f'display:flex;align-items:center;justify-content:center;font-size:1.15rem;">{_cv_esc(icon)}</div>'
            f'<div data-cb="label" data-key="{k}" style="font-size:0.95rem;font-weight:600;color:#202124;">'
            f'{_h.escape(title)}{badge_html}</div>'
            f'<div style="font-size:0.85rem;color:#5f6368;line-height:1.6;">{_h.escape(desc)}</div>'
            f'</div>'
        )

    return (
        f'<div style="margin:1.5rem 0;">'
        f'{heading_html}{desc_html}'
        f'<div style="display:grid;grid-template-columns:repeat({columns},1fr);gap:28px 24px;">'
        f'{items_html}'
        f'</div>'
        f'</div>'
    )


def _render_navigation_menu(b: dict) -> str:
    """Multi-level horizontal nav bar — Radix NavigationMenu pattern."""
    import html as _h
    brand     = b.get("brand", "")
    brand_url = b.get("brand_url", "#")
    items     = b.get("items", [])
    cta       = b.get("cta", None)

    brand_html = (
        f'<a href="{_h.escape(brand_url)}" style="font-size:0.97rem;font-weight:700;'
        f'color:#202124;text-decoration:none;margin-right:20px;white-space:nowrap;'
        f'letter-spacing:-.01em;">{_h.escape(brand)}</a>'
    ) if brand else ""

    nav_items_html = ""
    first_submenu_html = ""
    for idx, item in enumerate(items):
        label    = item.get("label", "")
        url      = item.get("url", "#")
        children = item.get("children", [])
        is_active = idx == 0
        active_style = "background:#f0f4ff;color:#1a73e8;" if is_active else "color:#3c4043;"
        if children:
            nav_items_html += (
                f'<span style="display:inline-flex;align-items:center;gap:3px;padding:6px 11px;'
                f'font-size:0.87rem;font-weight:500;border-radius:6px;cursor:pointer;{active_style}">'
                f'{_h.escape(label)}'
                f'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M6 9l6 6 6-6"/></svg>'
                f'</span>'
            )
            if is_active:
                child_items = ""
                for child in children:
                    c_url  = child.get("url", "#")
                    c_lbl  = child.get("label", "")
                    c_desc = child.get("description", "")
                    desc_h = (
                        f'<div style="font-size:0.77rem;color:#5f6368;margin-top:2px;">{_h.escape(c_desc)}</div>'
                    ) if c_desc else ""
                    child_items += (
                        f'<a href="{_h.escape(c_url)}" style="display:block;padding:9px 12px;'
                        f'border-radius:6px;text-decoration:none;">'
                        f'<div style="font-size:0.87rem;font-weight:500;color:#202124;">{_h.escape(c_lbl)}</div>'
                        f'{desc_h}</a>'
                    )
                first_submenu_html = (
                    f'<div style="border-top:1px solid #e8eaed;background:#fafafa;padding:8px 16px 12px;">'
                    f'<div style="font-size:0.72rem;font-weight:600;color:#80868b;letter-spacing:.07em;'
                    f'text-transform:uppercase;padding:6px 12px 4px;">{_h.escape(label)}</div>'
                    f'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:2px;">'
                    f'{child_items}</div>'
                    f'</div>'
                )
        else:
            nav_items_html += (
                f'<a href="{_h.escape(url)}" style="padding:6px 11px;font-size:0.87rem;'
                f'font-weight:500;{active_style}text-decoration:none;border-radius:6px;">'
                f'{_h.escape(label)}</a>'
            )

    cta_html = (
        f'<a href="{_h.escape(cta.get("url","#"))}" style="margin-left:auto;padding:7px 16px;'
        f'background:#1a73e8;color:#fff;font-size:0.84rem;font-weight:600;'
        f'border-radius:6px;text-decoration:none;white-space:nowrap;">'
        f'{_h.escape(cta.get("label",""))}</a>'
    ) if cta else ""

    return (
        f'<div style="margin:1.5rem 0;border:1px solid #dadce0;border-radius:10px;overflow:hidden;">'
        f'<nav style="display:flex;align-items:center;padding:8px 16px;background:#fff;gap:2px;">'
        f'{brand_html}{nav_items_html}{cta_html}'
        f'</nav>'
        f'{first_submenu_html}'
        f'</div>'
    )


