# ── Learning atoms ─────────────────────────────────────────────────────────────

def _render_quiz_question(b: dict) -> str:
    import hashlib
    uid      = "q" + hashlib.md5(str(b).encode()).hexdigest()[:6]
    question = b.get("question", "")
    # Schema says options are plain strings, but a common alternate shape sends
    # {label, value} objects; f-string formatting of a dict happened to still embed the
    # label via Python's repr (an accident, not a design -- GAS's _esc(obj) on the same
    # shape stringifies to the literal text "[object Object]", losing every option).
    # Normalise explicitly (surface-parity debt). 2026-09-27.
    options  = [o if isinstance(o, str) else (o.get("label") or o.get("text") or o.get("value") or str(o))
                for o in b.get("options", [])]
    correct  = int(b.get("correct", 0))
    explain  = b.get("explanation", "")
    style    = b.get("style", "default")
    bg       = "#0f172a" if style == "dark" else "#fff"
    border   = "#1e293b" if style == "dark" else "#e2e8f0"
    text_col = "#f1f5f9" if style == "dark" else "#1e293b"
    sub_col  = "#94a3b8" if style == "dark" else "#64748b"

    inputs = ""
    labels = ""
    for i, opt in enumerate(options):
        inp_id = f"{uid}_o{_cv_esc(i)}"
        is_correct = (i == correct)
        correct_css = (
            f'#{inp_id}:checked ~ .{uid}_opts label[for="{inp_id}"]'
            f'{{background:#d1fae5;border-color:#10b981;color:#065f46;font-weight:600;}}'
        ) if is_correct else (
            f'#{inp_id}:checked ~ .{uid}_opts label[for="{inp_id}"]'
            f'{{background:#fee2e2;border-color:#ef4444;color:#991b1b;text-decoration:line-through;opacity:0.7;}}'
        )
        reveal_css = (
            f'#{inp_id}:checked ~ .{uid}_explain{{display:block;}}'
        ) if explain else ""
        inputs += f'<input type="radio" id="{inp_id}" name="{uid}" style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">'
        focus_css = f'#{inp_id}:focus-visible ~ .{uid}_opts label[for="{inp_id}"]{{outline:2px solid #4f46e5;outline-offset:2px;}}'
        inputs += f'<style>{correct_css}{reveal_css}{focus_css}</style>'
        labels += (
            f'<label for="{inp_id}" style="display:block;padding:10px 14px;margin:6px 0;'
            f'border:1.5px solid {border};border-radius:8px;cursor:pointer;'
            f'font-size:0.9rem;color:{text_col};transition:all 0.2s;">'
            f'{_esc(opt)}</label>'
        )

    explain_html = (
        f'<div class="{uid}_explain" style="display:none;margin-top:12px;padding:12px 14px;'
        f'background:#eff6ff;border-left:3px solid #3b82f6;border-radius:0 6px 6px 0;'
        f'font-size:0.85rem;color:#1e40af;">{_cv_esc(explain)}</div>'
    ) if explain else ""

    return (
        f'<div style="border:1.5px solid {border};border-radius:12px;padding:20px 24px;'
        f'margin:1.2rem 0;background:{bg};">'
        f'<p style="font-weight:600;font-size:0.95rem;color:{text_col};margin:0 0 14px;">{_cv_esc(question)}</p>'
        f'{inputs}'
        f'<div class="{uid}_opts">{labels}</div>'
        f'{explain_html}'
        f'<p style="font-size:0.75rem;color:{sub_col};margin:12px 0 0;">Select an option to reveal the answer.</p>'
        f'</div>'
    )


# ── Shopify Polaris atoms ──────────────────────────────────────────────────────

def _render_product_thumbnail(b: dict) -> str:
    title          = b.get("title", "Product")
    vendor         = b.get("vendor", "")
    sku            = b.get("sku", "")
    price          = b.get("price", "")
    compare_price  = b.get("compare_at_price", "")
    status         = b.get("status", "active")
    image_url      = b.get("image_url", "")
    tags           = b.get("tags", [])

    STATUS = {
        "active":   ("#d4edda", "#155724", "Active"),
        "draft":    ("#fff3cd", "#856404", "Draft"),
        "archived": ("#e2e3e5", "#383d41", "Archived"),
    }
    bg, fg, label = STATUS.get(status, STATUS["active"])

    img = (
        f'<img src="{_cv_esc(image_url)}" alt="{_cv_esc(title)}" style="width:100%;height:120px;object-fit:cover;border-radius:4px;margin-bottom:12px;">'
        if image_url else
        '<div style="width:100%;height:120px;background:#f4f6f8;border-radius:4px;margin-bottom:12px;display:flex;align-items:center;justify-content:center;color:#8c9196;font-size:24px;">🖼</div>'
    )
    price_html = f'<span style="font-size:18px;font-weight:700;color:#202223;">{_cv_esc(price)}</span>'
    if compare_price:
        price_html += f'<span style="font-size:14px;color:#8c9196;text-decoration:line-through;margin-left:8px;">{_cv_esc(compare_price)}</span>'

    tags_html = "".join(
        f'<span style="background:#f1f2f3;color:#6d7175;font-size:11px;padding:2px 8px;border-radius:20px;">{_cv_esc(t)}</span>'
        for t in tags
    )
    tags_section = f'<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:10px;">{tags_html}</div>' if tags else ""

    return (
        f'<div style="background:#fff;border:1px solid #e1e3e5;border-radius:8px;padding:16px;max-width:280px;">'
        f'{img}'
        f'<div style="font-size:13px;font-weight:600;color:#202223;margin-bottom:2px;">{_cv_esc(title)}</div>'
        + (f'<div style="font-size:12px;color:#6d7175;margin-bottom:8px;">{_cv_esc(vendor)}</div>' if vendor else '')
        + (f'<div style="font-size:11px;color:#8c9196;font-family:monospace;margin-bottom:8px;">SKU: {_cv_esc(sku)}</div>' if sku else '')
        + f'<div style="margin-bottom:10px;">{price_html}</div>'
        f'<span style="background:{bg};color:{fg};font-size:11px;font-weight:600;padding:2px 8px;border-radius:20px;">{label}</span>'
        f'{tags_section}'
        f'</div>'
    )


def _render_order_status_card(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    order_num = _first_text(b.get("order_number"), b.get("order_id"), "")
    date = _first_text(b.get("date"), "")
    raw_status = _first_text(b.get("status"), "unfulfilled").lower()
    customer = _first_text(b.get("customer"), "")
    total = _first_text(b.get("total"), "")
    est_delivery = _first_text(b.get("estimated_delivery"), "")

    steps = ["Placed", "Processing", "Shipped", "Delivered"]
    status_index = {"placed": 0, "processing": 1, "shipped": 2, "delivered": 3, "cancelled": -1}
    schema_status = {"fulfilled": 3, "unfulfilled": 0, "partial": 2, "refunded": -1}

    st = schema_status.get(raw_status) if raw_status in schema_status else status_index.get(raw_status)
    current_step = st if st is not None and st >= 0 else 0
    cancelled = raw_status in ("cancelled", "refunded")

    stepper_parts = ['<div style="display:flex;align-items:center;margin:16px 0 24px;">']
    for s_idx, step_name in enumerate(steps):
        done = not cancelled and s_idx <= current_step
        active = not cancelled and s_idx == current_step
        dot_bg = "#fee2e2" if cancelled else ("#7c3aed" if done else "#e5e7eb")
        dot_color = "#991b1b" if cancelled else ("#fff" if done else "#9ca3af")
        step_content = "✓" if (done and not active) else _text_loose(s_idx + 1)
        name_color = "#7c3aed" if active else "#6b7280"
        name_weight = "700" if active else "400"

        stepper_parts.append(
            f'<div style="display:flex;flex-direction:column;align-items:center;flex:1;">'
            f'<div style="width:28px;height:28px;border-radius:50%;background:{dot_bg};color:{dot_color};font-size:0.75rem;font-weight:700;display:flex;align-items:center;justify-content:center;">{step_content}</div>'
            f'<div style="font-size:0.72rem;margin-top:4px;color:{name_color};font-weight:{name_weight};text-align:center;">{step_name}</div>'
            f'</div>'
        )
        if s_idx < len(steps) - 1:
            line_bg = "#7c3aed" if (not cancelled and s_idx < current_step) else "#e5e7eb"
            stepper_parts.append(f'<div style="flex:1;height:2px;background:{line_bg};margin-bottom:16px;"></div>')
    stepper_parts.append("</div>")
    stepper_html = "".join(stepper_parts)

    items_raw = b.get("items")
    items = items_raw[:200] if isinstance(items_raw, list) else []

    item_rows = []
    for item in items:
        i_obj = item if isinstance(item, dict) else {}
        name = _first_text(i_obj.get("title"), i_obj.get("name"), "")
        qty_num = _num_loose(i_obj.get("qty"))
        qty = _text_loose(min(max(int(qty_num + 0.5), 0), 10 ** 9) if qty_num is not None else 1)
        price = _first_text(i_obj.get("price"), "")
        item_rows.append(
            f'<tr><td style="padding:8px 4px;font-size:0.875rem;color:#111827;">{_cv_esc(name)}</td>'
            f'<td style="padding:8px 4px;font-size:0.875rem;color:var(--muted,#5f6368);text-align:center;">×{_cv_esc(qty)}</td>'
            f'<td style="padding:8px 4px;font-size:0.875rem;color:#111827;text-align:right;">{_cv_esc(price)}</td></tr>'
        )
    items_html = "".join(item_rows)

    sub_parts = [p for p in (customer, date) if p]
    sub_meta = f'<span style="font-size:0.8rem;color:var(--muted,#5f6368);">{_cv_esc(" · ".join(sub_parts))}</span>' if sub_parts else ""
    badge_title = (raw_status[:1].upper() + raw_status[1:]) if _first_text(b.get("status")) else ""
    bstyle = "background:#fee2e2;color:#991b1b" if cancelled else "background:#ede9fe;color:#5b21b6"
    cancelled_badge = f'<span style="{bstyle};font-size:0.78rem;font-weight:600;padding:3px 10px;border-radius:999px;">{_cv_esc(badge_title)}</span>' if badge_title else ""

    deliv_html = f'<div style="margin-top:10px;font-size:0.82rem;color:var(--muted,#5f6368);">Estimated delivery: <strong style="color:#111827;">{_cv_esc(est_delivery)}</strong></div>' if est_delivery else ""

    order_title = f"Order {order_num}" if order_num else "Order"
    node_key = _cv_esc(order_num or "order")

    return (
        f'<div data-cb="node" data-key="{node_key}" style="border:1px solid #e5e7eb;border-radius:14px;padding:20px;margin:1rem 0;background:#fff;">'
        f'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">'
        f'<span style="font-weight:700;color:#111827;font-size:1rem;">{_cv_esc(order_title)}</span>'
        f'{sub_meta}'
        f'{cancelled_badge}'
        f'</div>'
        f'{stepper_html}'
        f'<table style="width:100%;border-collapse:collapse;border-top:1px solid #f3f4f6;">{items_html}</table>'
        f'<div style="display:flex;justify-content:space-between;padding-top:10px;border-top:1px solid #e5e7eb;margin-top:8px;font-weight:700;color:#111827;">'
        f'<span>Total</span><span>{_cv_esc(total)}</span>'
        f'</div>'
        f'{deliv_html}'
        f'</div>'
    )


def _render_inventory_table(b: dict) -> str:
    title = b.get("title", "")
    items = b.get("items", [])

    rows_html = ""
    for item in items:
        available  = item.get("available", 0)
        threshold  = item.get("threshold")
        low_stock  = threshold is not None and available < threshold
        row_bg     = "background:#fff3cd;" if low_stock else ""
        qty_style  = "color:#856404;font-weight:600;" if low_stock else "color:#202223;"
        rows_html += (
            f'<tr style="{row_bg}">'
            f'<td style="padding:10px 12px;font-family:monospace;font-size:12px;color:#6d7175;">{_cv_esc(item.get("sku",""))}</td>'
            f'<td style="padding:10px 12px;font-size:13px;font-weight:500;color:#202223;">{_cv_esc(item.get("product",""))}</td>'
            f'<td style="padding:10px 12px;text-align:right;{qty_style}">{_cv_esc(available)}{"⚠" if low_stock else ""}</td>'
            f'<td style="padding:10px 12px;text-align:right;color:#6d7175;">{_cv_esc(item.get("committed","—"))}</td>'
            f'<td style="padding:10px 12px;font-size:12px;color:#6d7175;">{_cv_esc(item.get("location","—"))}</td>'
            f'</tr>'
        )

    title_html = f'<div style="background:#f1f2f3;padding:12px 16px;font-weight:600;font-size:13px;color:#202223;border-bottom:1px solid #e1e3e5;">{_cv_esc(title)}</div>' if title else ''
    return (
        f'<div style="border:1px solid #e1e3e5;border-radius:8px;overflow:hidden;">'
        f'{title_html}'
        f'<table style="width:100%;border-collapse:collapse;font-size:13px;">'
        f'<thead><tr style="background:#f6f6f7;border-bottom:1px solid #e1e3e5;">'
        f'<th style="padding:8px 12px;text-align:left;font-size:12px;font-weight:600;color:#6d7175;">SKU</th>'
        f'<th style="padding:8px 12px;text-align:left;font-size:12px;font-weight:600;color:#6d7175;">Product</th>'
        f'<th style="padding:8px 12px;text-align:right;font-size:12px;font-weight:600;color:#6d7175;">Available</th>'
        f'<th style="padding:8px 12px;text-align:right;font-size:12px;font-weight:600;color:#6d7175;">Committed</th>'
        f'<th style="padding:8px 12px;text-align:left;font-size:12px;font-weight:600;color:#6d7175;">Location</th>'
        f'</tr></thead>'
        f'<tbody>{rows_html}</tbody>'
        f'</table></div>'
    )


# ── Atlassian Design System atoms ─────────────────────────────────────────────

def _render_jira_ticket(b: dict) -> str:
    key         = b.get("key", "PROJ-1")
    issue_type  = b.get("issue_type", "task")
    summary     = b.get("summary", "")
    status      = b.get("status", "To Do")
    priority    = b.get("priority", "medium")
    assignee    = b.get("assignee", "")
    description = b.get("description", "")
    labels      = b.get("labels", [])

    TYPE_ICONS = {
        "bug":     ("🐛", "#e34935"),
        "story":   ("📖", "#36b37e"),
        "task":    ("✓",  "#0052cc"),
        "epic":    ("⚡", "#6554c0"),
        "subtask": ("↗",  "#0052cc"),
    }
    icon, _ = TYPE_ICONS.get(issue_type, ("✓", "#0052cc"))

    PRIORITY_ICONS = {
        "highest": "🔴", "high": "🟠", "medium": "🟡", "low": "🔵", "lowest": "⚪",
    }
    p_icon = PRIORITY_ICONS.get(priority, "🟡")

    STATUS_COLORS = {
        "To Do":      ("#dfe1e6", "#42526e"),
        "In Progress":("#deebff", "#0747a6"),
        "Done":       ("#e3fcef", "#006644"),
        "Blocked":    ("#ffebe6", "#bf2600"),
        "Review":     ("#fffae6", "#172b4d"),
    }
    s_bg, s_fg = STATUS_COLORS.get(status, ("#dfe1e6", "#42526e"))

    labels_html = "".join(
        f'<span style="background:#dfe1e6;color:#172b4d;font-size:11px;padding:2px 6px;border-radius:3px;">{_cv_esc(lbl)}</span>'
        for lbl in labels
    )

    return (
        f'<div data-cb="node" data-key="{_ck(b.get("key"), "jira_ticket")}" style="background:#ffffff;background:var(--a2ui-surface,#ffffff);border:1px solid #dfe1e6;border-radius:3px;padding:16px;font-family:-apple-system,sans-serif;">'
        f'<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">'
        f'<span style="font-size:15px;">{icon}</span>'
        f'<span style="font-size:12px;font-weight:600;color:#0052cc;">{_cv_esc(key)}</span>'
        f'<span style="margin-left:auto;background:{s_bg};color:{s_fg};font-size:10px;font-weight:700;padding:2px 8px;border-radius:3px;text-transform:uppercase;letter-spacing:0.05em;">{_cv_esc(status)}</span>'
        f'</div>'
        f'<div style="font-size:15px;font-weight:500;color:#172b4d;margin-bottom:10px;line-height:1.4;">{_cv_esc(summary)}</div>'
        + (f'<div style="font-size:13px;color:#5e6c84;margin-bottom:12px;line-height:1.5;">{_cv_esc(description)}</div>' if description else '')
        + f'<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;">'
        f'<span style="font-size:12px;color:#5e6c84;">{p_icon} {_cv_esc(priority.capitalize())}</span>'
        + (f'<span style="font-size:12px;color:#5e6c84;">👤 {_cv_esc(assignee)}</span>' if assignee else '')
        + labels_html
        + '</div></div>'
    )


def _render_sprint_board(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    sprint_name = _first_text(b.get("sprint_name"), b.get("title"))
    raw_columns = b.get("columns")
    if not isinstance(raw_columns, list):
        raw_columns = []
    columns = raw_columns[:200]

    type_icons = {
        "bug": "🐛", "story": "📖", "task": "✓", "epic": "⚡", "subtask": "↗",
    }
    priority_colors = {
        "highest": "#e34935", "high": "#ff7a00", "medium": "#f79e1b",
        "low": "#0065ff", "lowest": "#6b778c",
    }

    cols_html = ""
    for col in columns:
        if not isinstance(col, dict):
            continue
        cname = _first_text(col.get("name"), col.get("title"))
        raw_items = col.get("items")
        if not isinstance(raw_items, list):
            raw_items = col.get("cards")
        if not isinstance(raw_items, list):
            raw_items = []
        items = raw_items[:200]

        cards_html = ""
        for t in items:
            if not isinstance(t, dict):
                continue
            ttype = _text_loose(t.get("type")).lower()
            icon = type_icons.get(ttype, "✓")
            tpriority = _text_loose(t.get("priority")).lower()
            p_color = priority_colors.get(tpriority, "#d1d5db")
            summary = _first_text(t.get("summary"), t.get("title"))
            key = _first_text(t.get("key"), t.get("id"))

            assignee = _text_loose(t.get("assignee"))
            assignee_html = (
                f'<div style="width:20px;height:20px;border-radius:50%;background:#7c3aed;color:#fff;'
                f'font-size:0.65rem;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;">'
                f'{_cv_esc(assignee[:1].upper())}</div>'
            ) if assignee else ""

            labels_html = ""
            raw_labels = t.get("labels")
            if isinstance(raw_labels, list) and raw_labels:
                lbls = "".join(
                    f'<span style="background:#ede9fe;color:#5b21b6;font-size:0.65rem;padding:1px 5px;border-radius:999px;">{_cv_esc(_text_loose(lbl))}</span>'
                    for lbl in raw_labels[:20] if _text_loose(lbl)
                )
                if lbls:
                    labels_html = f'<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">{lbls}</div>'

            cards_html += (
                f'<div style="background:#ffffff;background:var(--a2ui-surface,#ffffff);border:1px solid #dfe1e6;'
                f'border-radius:3px;padding:10px;margin-bottom:6px;">'
                f'<div style="display:flex;align-items:flex-start;gap:6px;">'
                f'<span style="font-size:11px;flex-shrink:0;margin-top:1px;" aria-hidden="true">{icon}</span>'
                f'<div style="flex:1;min-width:0;">'
                f'<div style="font-size:12px;font-weight:500;color:#172b4d;line-height:1.3;margin-bottom:4px;">{_cv_esc(summary)}</div>'
                f'<div style="display:flex;align-items:center;gap:6px;">'
                f'<span style="font-size:10px;color:#0052cc;font-weight:600;">{_cv_esc(key)}</span>'
                f'<span style="width:7px;height:7px;border-radius:50%;background:{p_color};flex-shrink:0;" aria-hidden="true"></span>'
                f'</div>'
                f'{labels_html}'
                f'</div>'
                f'{assignee_html}'
                f'</div>'
                f'</div>'
            )

        cols_html += (
            f'<div style="background:#f4f5f7;border-radius:3px;padding:10px;flex:1;min-width:160px;">'
            f'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">'
            f'<span style="font-size:11px;font-weight:700;color:#5e6c84;text-transform:uppercase;letter-spacing:0.05em;">{_cv_esc(cname)}</span>'
            f'<span style="background:#dfe1e6;color:#172b4d;font-size:11px;font-weight:600;padding:1px 6px;border-radius:20px;">{len(items)}</span>'
            f'</div>'
            f'{cards_html}'
            f'</div>'
        )

    name_html = f'<div style="font-size:14px;font-weight:700;color:#172b4d;margin-bottom:12px;">{_cv_esc(sprint_name)}</div>' if sprint_name else ""
    return (
        f'<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,sans-serif;margin:1rem 0;">'
        f'{name_html}'
        f'<div style="display:flex;gap:10px;overflow-x:auto;padding-bottom:4px;">{cols_html}</div>'
        f'</div>'
    )


def _render_lozenge(b: dict) -> str:
    items = b.get("items")
    if items is None:
        items = [{"text": b.get("text", "Status"), "appearance": b.get("appearance", "default")}]

    APPEARANCES = {
        "default":    ("#dfe1e6", "#172b4d"),
        "success":    ("#e3fcef", "#006644"),
        "removed":    ("#ffebe6", "#bf2600"),
        "inprogress": ("#deebff", "#0747a6"),
        "moved":      ("#fffae6", "#172b4d"),
        "new":        ("#e6fcff", "#008da6"),
    }

    pills = "".join(
        '<span style="display:inline-block;background:{};color:{};font-size:11px;font-weight:700;'
        'padding:2px 8px;border-radius:3px;text-transform:uppercase;letter-spacing:0.05em;">{}</span>'.format(
            *APPEARANCES.get(item.get("appearance", "default"), APPEARANCES["default"]),
            item.get("text", "")
        )
        for item in items
    )
    return f'<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;">{pills}</div>'


# ── IBM Carbon Design System atoms ────────────────────────────────────────────

def _render_data_grid(b: dict) -> str:
    title      = b.get("title", "")
    columns    = b.get("columns", [])
    rows       = b.get("rows", [])
    selectable = b.get("selectable", False)
    pagination = b.get("pagination")
    per_page   = (pagination.get("per_page", 10) if pagination else len(rows)) or len(rows) or 10

    # Split rows into pages; if no pagination field, single page
    pages      = [rows[i:i+per_page] for i in range(0, max(len(rows), 1), per_page)] if pagination else [rows]
    multi      = len(pages) > 1
    total      = len(rows)
    uid        = abs(_wa_shash(title + str(len(columns)) + str(total) + str(per_page))) % 999983

    STATUS_COLORS = {
        "active":   ("#d4edda", "#155724"), "inactive": ("#e2e3e5", "#383d41"),
        "error":    ("#f8d7da", "#721c24"), "warning":  ("#fff3cd", "#856404"),
    }

    def _header():
        cells = ""
        if selectable:
            cells += '<th style="padding:10px 12px;width:36px;"><input type="checkbox"></th>'
        for col in columns:
            sort = ' <span style="color:#a8b0bd;font-size:10px;">⇅</span>' if col.get("sortable") else ""
            cells += (
                f'<th style="padding:10px 12px;text-align:left;font-size:12px;font-weight:600;'
                f'color:#161616;white-space:nowrap;border-right:1px solid #e0e0e0;">'
                f'{col.get("header","")}{sort}</th>'
            )
        return f'<tr style="background:#e0e0e0;border-bottom:2px solid #8d8d8d;">{cells}</tr>'

    def _tbody(page_rows, offset):
        html = ""
        for i, row in enumerate(page_rows):
            row_bg = "#fff" if (i + offset) % 2 == 0 else "#f4f4f4"
            cells  = '<td style="padding:10px 12px;"><input type="checkbox"></td>' if selectable else ""
            for col in columns:
                key      = col.get("key", "")
                col_type = col.get("type", "string")
                value    = row.get(key, "")
                border   = "border-right:1px solid #e0e0e0;"
                if col_type == "number":
                    cells += f'<td style="padding:10px 12px;text-align:right;font-size:13px;color:#161616;font-variant-numeric:tabular-nums;{border}">{_cv_esc(value)}</td>'
                elif col_type == "status":
                    sc_bg, sc_fg = STATUS_COLORS.get(str(value).lower(), ("#e2e3e5", "#383d41"))
                    cells += (f'<td style="padding:10px 12px;{border}"><span style="background:{sc_bg};'
                              f'color:{sc_fg};font-size:11px;font-weight:600;padding:2px 8px;border-radius:20px;">{_cv_esc(value)}</span></td>')
                elif col_type == "tag":
                    cells += (f'<td style="padding:10px 12px;{border}"><span style="background:#d0e2ff;'
                              f'color:#0043ce;font-size:11px;padding:2px 8px;border-radius:3px;">{_cv_esc(value)}</span></td>')
                else:
                    cells += f'<td style="padding:10px 12px;font-size:13px;color:#161616;{border}">{_cv_esc(value)}</td>'
            html += f'<tr style="background:{row_bg};border-bottom:1px solid #e0e0e0;">{cells}</tr>'
        return html

    title_html = f'<div style="background:#161616;color:#fff;padding:12px 16px;font-size:14px;font-weight:600;">{_cv_esc(title)}</div>' if title else ''

    if not multi:
        # Simple render — no CSS pagination needed
        return (
            f'<div style="border:1px solid #e0e0e0;font-family:-apple-system,sans-serif;overflow:hidden;">'
            f'{title_html}'
            f'<table style="width:100%;border-collapse:collapse;">'
            f'<thead>{_header()}</thead>'
            f'<tbody>{_tbody(rows, 0)}</tbody>'
            f'</table>'
            f'<div style="padding:8px 16px;background:#f4f4f4;font-size:12px;color:#525252;">{total} items</div>'
            f'</div>'
        )

    # ── CSS-radio tab pagination ───────────────────────────────────────────────
    # Radio inputs must be siblings of the wrapper so ~ selector reaches inside it
    n = len(pages)
    css = (
        f'<style>'
        # hide all pages
        f'.dg{uid}pg{{display:none;}}'
        # show/highlight active page via checked radio
        + "".join(
            f'#dg{uid}r{i}:checked~.dg{uid}w .dg{uid}pg{i}{{display:block;}}'
            f'#dg{uid}r{i}:checked~.dg{uid}w .dg{uid}lbl{i}'
            f'{{background:#0043ce!important;color:#fff!important;}}'
            for i in range(n)
        )
        + f'.dg{uid}lbl{{display:inline-flex;align-items:center;justify-content:center;'
        f'width:28px;height:28px;border-radius:3px;cursor:pointer;font-size:12px;'
        f'font-weight:600;background:#e0e0e0;color:#525252;margin:0 2px;}}'
        f'</style>'
    )
    radios = "".join(
        f'<input type="radio" id="dg{uid}r{i}" name="dg{uid}" {"checked" if i==0 else ""} style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">'
        for i in range(n)
    )
    pages_html = "".join(
        f'<div class="dg{uid}pg dg{uid}pg{_cv_esc(i)}">'
        f'<table style="width:100%;border-collapse:collapse;">'
        f'<thead>{_header()}</thead>'
        f'<tbody>{_tbody(pg, i * per_page)}</tbody>'
        f'</table></div>'
        for i, pg in enumerate(pages)
    )
    labels = "".join(
        f'<label for="dg{uid}r{i}" class="dg{uid}lbl dg{uid}lbl{i}">{i+1}</label>'
        for i in range(n)
    )
    footer = (
        f'<div style="display:flex;justify-content:space-between;align-items:center;'
        f'padding:10px 16px;border-top:1px solid #e0e0e0;background:#f4f4f4;">'
        f'<span style="font-size:12px;color:#525252;">{total} items &nbsp;·&nbsp; {n} pages</span>'
        f'<div>{labels}</div>'
        f'</div>'
    )

    return (
        f'{css}{radios}'
        f'<div class="dg{uid}w" style="border:1px solid #e0e0e0;font-family:-apple-system,sans-serif;overflow:hidden;">'
        f'{title_html}{pages_html}{footer}'
        f'</div>'
    )


def _render_tree_view(b: dict) -> str:
    title = b.get("title", "")
    nodes = b.get("nodes", [])

    def render_node(node, depth=0):
        label    = node.get("label", "")
        icon     = node.get("icon", "")
        meta     = node.get("meta", "")
        children = node.get("children", [])
        expanded = node.get("expanded", True)

        indent_px = depth * 20
        if children:
            expander = "▼" if expanded else "▶"
            exp_html = f'<span style="color:#525252;font-size:9px;width:14px;display:inline-block;flex-shrink:0;">{expander}</span>'
        else:
            exp_html = '<span style="width:14px;display:inline-block;flex-shrink:0;"></span>'

        icon_html = f'<span style="margin-right:4px;">{_cv_esc(icon)}</span>' if icon else ""
        meta_html = f'<span style="margin-left:auto;font-size:11px;color:#8d8d8d;white-space:nowrap;">{_cv_esc(meta)}</span>' if meta else ""
        children_html = "".join(render_node(c, depth + 1) for c in children) if (children and expanded) else ""

        return (
            f'<div style="padding-left:{indent_px}px;">'
            f'<div style="display:flex;align-items:center;padding:4px 8px;cursor:pointer;">'
            f'{exp_html}{icon_html}'
            f'<span style="font-size:13px;color:#161616;flex:1;">{_cv_esc(label)}</span>'
            f'{meta_html}'
            f'</div>'
            f'{children_html}'
            f'</div>'
        )

    title_html = f'<div style="background:#f4f4f4;padding:10px 16px;font-size:13px;font-weight:600;color:#161616;border-bottom:1px solid #e0e0e0;">{_cv_esc(title)}</div>' if title else ''
    nodes_html = "".join(render_node(n) for n in nodes)

    return (
        f'<div style="border:1px solid #e0e0e0;font-family:-apple-system,sans-serif;overflow:hidden;">'
        f'{title_html}'
        f'<div style="padding:8px 0;">{nodes_html}</div>'
        f'</div>'
    )


def _render_heatmap_calendar(b: dict) -> str:
    import math
    from datetime import date, timedelta
    import calendar as _cal

    title       = b.get("title", "")
    data        = b.get("data", [])
    months      = b.get("months", 3)
    color_scale = b.get("color_scale", ["#f4f4f4", "#d0e2ff", "#4589ff", "#0043ce", "#001d6c"])
    unit        = b.get("unit", "")

    data_dict = {item.get("date", ""): item.get("count", 0) for item in data} if isinstance(data, list) else dict(data)
    max_val = max(data_dict.values(), default=1) or 1

    def get_color(val):
        if val == 0:
            return color_scale[0]
        ratio = val / max_val
        idx = min(int(ratio * (len(color_scale) - 1)) + 1, len(color_scale) - 1)
        return color_scale[idx]

    today = date.today()
    DOW = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]

    months_html = ""
    for m_offset in range(months - 1, -1, -1):
        month = today.month - m_offset
        year  = today.year
        while month <= 0:
            month += 12
            year  -= 1

        num_days     = _cal.monthrange(year, month)[1]
        first_dow    = date(year, month, 1).weekday()
        month_abbr   = _cal.month_abbr[month]

        cells = ['<td style="width:16px;height:16px;"></td>'] * first_dow
        for day in range(1, num_days + 1):
            d_str = f"{year}-{month:02d}-{day:02d}"
            count = data_dict.get(d_str, 0)
            color = get_color(count)
            tip   = f'{d_str}: {_cv_esc(count)}{" "+_cv_esc(unit) if unit else ""}'
            cells.append(
                f'<td title="{tip}" style="width:16px;height:16px;background:{color};'
                f'border-radius:2px;border:1px solid rgba(0,0,0,0.04);cursor:default;"></td>'
            )
        while len(cells) % 7:
            cells.append('<td style="width:16px;height:16px;"></td>')

        weeks    = [cells[i:i+7] for i in range(0, len(cells), 7)]
        dow_row  = "".join(f'<th style="font-size:8px;color:#8d8d8d;text-align:center;padding:0;width:16px;font-weight:400;">{d}</th>' for d in DOW)
        rows_html = "".join(f'<tr>{"".join(w)}</tr>' for w in weeks)

        months_html += (
            f'<div style="display:inline-block;margin-right:14px;vertical-align:top;">'
            f'<div style="font-size:11px;color:#525252;margin-bottom:6px;text-align:center;">{month_abbr} {year}</div>'
            f'<table style="border-collapse:separate;border-spacing:2px;">'
            f'<thead><tr>{dow_row}</tr></thead>'
            f'<tbody>{rows_html}</tbody>'
            f'</table></div>'
        )

    legend = (
        '<div style="display:flex;align-items:center;gap:4px;margin-top:12px;">'
        '<span style="font-size:10px;color:#8d8d8d;margin-right:2px;">Less</span>'
        + "".join(f'<span style="width:12px;height:12px;background:{_cv_esc(c)};border-radius:2px;border:1px solid rgba(0,0,0,0.04);display:inline-block;"></span>' for c in color_scale)
        + '<span style="font-size:10px;color:#8d8d8d;margin-left:2px;">More</span></div>'
    )

    title_html = f'<div style="font-size:14px;font-weight:600;color:#161616;margin-bottom:12px;">{_cv_esc(title)}</div>' if title else ''
    return (
        f'<div style="font-family:-apple-system,sans-serif;">'
        f'{title_html}'
        f'<div style="overflow-x:auto;">{months_html}</div>'
        f'{legend}'
        f'</div>'
    )


# ── Stage-first atoms ─────────────────────────────────────────────────────────

def _render_media_stream_card(b: dict) -> str:
    import html as _h, re
    url    = b.get("url", "")
    title  = b.get("title", "")
    height = b.get("height", "360px")

    embed_url = _h.escape(url)
    platform  = "Media"
    # True only when embed_url was REWRITTEN to a platform's own canonical
    # embed endpoint below, never for the untouched custom-stream fallback
    # -- see this function's own sandbox comment further down for why this
    # distinction is the actual fix, not a blanket choice either way.
    matched   = False

    # autoplay=1 alone does nothing -- browsers block unmuted autoplay
    # outright, so mute=1 has to go alongside it (matches the same pairing
    # already shipped for this atom's GAS/mcp-apps-bundle sibling,
    # apps-script-surface/gas-wired-renderer/atoms_unstub.gs, and
    # meetstudio's own gdm_stage_video_panel.ts before that). `allow=` two
    # blocks down already includes autoplay in its Permissions Policy --
    # only the query param was missing here.
    # NOT applied to a screenshot capture's own visual outcome the way it
    # is for a live-viewed page: this function also backs /render.png and
    # /render.gif (real Chromium screenshot capture, not a live browser
    # session) -- autoplay there just means the captured frame is
    # whatever moment mid-buffer/mid-playback the screenshot happened to
    # land on, not necessarily better or worse than the static thumbnail
    # state, and genuinely untested either way. Kept for embed-URL/query-
    # param parity with the other two implementations regardless, since
    # that consistency is the actual thing this fix is for.
    yt = re.search(r'(?:youtube\.com/watch\?v=|youtu\.be/)([A-Za-z0-9_-]+)', url)
    if yt:
        embed_url = f"https://www.youtube.com/embed/{yt.group(1)}?rel=0&autoplay=1&mute=1"
        platform  = "YouTube"
        matched   = True

    loom = re.search(r'loom\.com/share/([a-zA-Z0-9]+)', url)
    if loom:
        embed_url = f"https://www.loom.com/embed/{loom.group(1)}?autoplay=1"
        platform  = "Loom"
        matched   = True

    slides = re.search(r'docs\.google\.com/presentation/d/([^/]+)', url)
    if slides:
        embed_url = f"https://docs.google.com/presentation/d/{slides.group(1)}/embed?start=false&loop=false"
        platform  = "Google Slides"
        matched   = True

    vimeo = re.search(r'vimeo\.com/(\d+)', url)
    if vimeo:
        embed_url = f"https://player.vimeo.com/video/{vimeo.group(1)}"
        platform  = "Vimeo"
        matched   = True

    # A non-matched (custom-stream) url is echoed through unescaped-for-
    # HTML-syntax but otherwise UNCHECKED above -- html.escape only blocks
    # attribute breakout, not a dangerous scheme. A bare `javascript:`/
    # `data:` url would otherwise land straight in iframe src. Same
    # http(s)-only gate the live JS controller's own isSafeEmbedUrl
    # applies (cloud-run-renderer/static/a2ui-atoms-live.v1.js).
    if not embed_url.startswith(('http://', 'https://')):
        embed_url = ''

    label     = title or platform
    title_html = (
        f'<div style="padding:8px 14px;background:#1e293b;'
        f'font-size:0.78rem;color:#94a3b8;display:flex;align-items:center;gap:6px;">'
        f'<span style="color:#64748b;font-size:0.68rem;">▶</span>'
        f'<span style="font-weight:500;">{_h.escape(label)}</span>'
        f'</div>'
    )
    if not embed_url:
        message = 'Media URL was rejected (not http/https)' if url else 'No URL provided'
        return (
            f'<div style="margin:1rem 0;border:1px solid #334155;border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;">'
            f'{title_html}'
            f'<div style="height:{_cv_esc(height)};background:#0f172a;display:flex;align-items:center;'
            f'justify-content:center;color:#475569;font-size:0.85rem;">{message}</div>'
            f'</div>'
        )
    # allow-same-origin only for a REWRITTEN, platform-rewritten embed_url
    # (YouTube/Loom/Slides/Vimeo's own canonical embed endpoint) -- verified
    # live, headless Chromium, 2026-09-10: YouTube's iframe embed script
    # reads document.cookie during init and throws ("Failed to read the
    # 'cookie' property... sandboxed and lacks the 'allow-same-origin'
    # flag") without it, producing a black box, not a working player. The
    # allow-scripts+allow-same-origin combination is only a real anti-
    # pattern here for the UNMATCHED custom-stream fallback -- an arbitrary,
    # unvalidated url with no platform rewrite -- which keeps the harder
    # sandbox (matches the fix already shipped in a2uicatalog/a2ui#60).
    sandbox = ('allow-scripts allow-same-origin allow-popups allow-forms' if matched
               else 'allow-scripts allow-popups allow-forms')
    return (
        f'<div style="margin:1rem 0;border:1px solid #334155;border-radius:8px;overflow:hidden;background:#0f172a;">'
        f'{title_html}'
        f'<div style="position:relative;height:{_cv_esc(height)};background:#0f172a;">'
        f'<iframe src="{embed_url}" title="{_cv_esc(b.get("title") or "Media stream")}" '
        f'style="position:absolute;inset:0;width:100%;height:100%;border:none;" '
        f'allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture" '
        f'allowfullscreen sandbox="{sandbox}">'
        f'</iframe>'
        f'</div>'
        f'</div>'
    )


def _render_live_aggregator(b: dict) -> str:
    import html as _h
    items     = b.get("items", [])
    title     = b.get("title", "")
    max_val   = b.get("max_value", None)
    show_vals = b.get("show_values", True)

    if not items:
        return ""

    values = []
    for item in items:
        v = item.get("value", item.get("count", item.get("votes", 0)))
        try:
            values.append(float(v))
        except (ValueError, TypeError):
            values.append(0.0)

    auto_max      = max(values) if values else 1
    effective_max = float(max_val) if max_val is not None else auto_max
    if effective_max == 0:
        effective_max = 1

    _C = ["#1a73e8","#34a853","#9c27b0","#ea4335","#fbbc04","#00bcd4","#ff6d00","#00897b"]

    title_html = (
        f'<div style="font-size:0.78rem;font-weight:600;color:#94a3b8;'
        f'text-transform:uppercase;letter-spacing:.07em;margin-bottom:14px;">'
        f'{_h.escape(title)}</div>'
    ) if title else ""

    rows = ""
    for i, (item, val) in enumerate(zip(items, values)):
        label = item.get("label", f"Option {i+1}")
        pct   = min(100.0, (val / effective_max) * 100)
        color = item.get("color", _C[i % len(_C)])
        disp  = int(val) if val == int(val) else round(val, 1)
        val_html = (
            f'<span style="font-size:0.75rem;color:#94a3b8;white-space:nowrap;">{disp}</span>'
        ) if show_vals else ""
        rows += (
            f'<div style="margin-bottom:12px;">'
            f'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px;">'
            f'<span style="font-size:0.85rem;color:#e2e8f0;font-weight:500;">{_h.escape(label)}</span>'
            f'{val_html}</div>'
            f'<div style="height:8px;background:#1e293b;border-radius:4px;overflow:hidden;">'
            f'<div style="height:100%;width:{pct:.1f}%;background:{_cv_esc(color)};border-radius:4px;'
            f'transition:width 0.5s ease;"></div>'
            f'</div></div>'
        )
    return (
        f'<div style="margin:1rem 0;padding:18px 20px;background:#0f172a;'
        f'border:1px solid #1e293b;border-radius:12px;">'
        f'{title_html}{rows}'
        f'</div>'
    )


def _render_vote_button_group(b: dict) -> str:
    import html as _h
    options = b.get("options", [])
    style   = b.get("style", "pill")
    title   = b.get("title", "")
    multi   = b.get("allow_multi", False)
    uid     = abs(_wa_shash(str(options) + style + title)) % 100000
    inp     = "checkbox" if multi else "radio"
    name    = f"vbg{uid}"

    title_html = (
        f'<div style="font-size:0.78rem;font-weight:600;color:#94a3b8;'
        f'text-transform:uppercase;letter-spacing:.07em;margin-bottom:12px;">'
        f'{_h.escape(title)}</div>'
    ) if title else ""

    if style == "neon":
        css = (
            f'<style>'
            f'.{name} label{{display:inline-block;padding:9px 20px;border-radius:8px;cursor:pointer;'
            f'font-size:0.87rem;font-weight:500;color:#94a3b8;border:1px solid #1e293b;'
            f'background:#0a0f1e;transition:all .18s;}}'
            f'.{name} input:checked+label,.{name} label:hover{{border-color:#00f2ff;color:#00f2ff;'
            f'box-shadow:0 0 10px rgba(0,242,255,.3),inset 0 0 10px rgba(0,242,255,.04);}}'
            f'.{name} input{{position:absolute;opacity:0;width:1px;height:1px;margin:0;}}'
            f'</style>'
        )
        wrap = "background:#0f172a;border:1px solid #1e293b;border-radius:12px;padding:16px 18px;"
    elif style == "default":
        css = (
            f'<style>'
            f'.{name} label{{display:inline-block;padding:8px 18px;border-radius:6px;cursor:pointer;'
            f'font-size:0.87rem;font-weight:500;color:#3c4043;border:1px solid #dadce0;'
            f'background:#fff;transition:all .15s;}}'
            f'.{name} input:checked+label,.{name} label:hover{{background:#e8f0fe;border-color:#1a73e8;'
            f'color:#1a73e8;font-weight:600;}}'
            f'.{name} input{{position:absolute;opacity:0;width:1px;height:1px;margin:0;}}'
            f'</style>'
        )
        wrap = "background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px 16px;"
    else:
        css = (
            f'<style>'
            f'.{name} label{{display:inline-block;padding:8px 18px;border-radius:20px;cursor:pointer;'
            f'font-size:0.87rem;font-weight:500;color:#cbd5e1;border:1px solid #334155;'
            f'background:#1e293b;transition:all .15s;}}'
            f'.{name} input:checked+label,.{name} label:hover{{background:#1a73e8;border-color:#1a73e8;color:#fff;}}'
            f'.{name} input{{position:absolute;opacity:0;width:1px;height:1px;margin:0;}}'
            f'</style>'
        )
        wrap = "background:#0f172a;border:1px solid #1e293b;border-radius:12px;padding:16px 18px;"

    btns = ""
    for i, opt in enumerate(options):
        label    = opt.get("label", "")
        value    = opt.get("value", label)
        checked  = "checked" if opt.get("selected", False) else ""
        bid      = f"{name}_{_cv_esc(i)}"
        btns += (
            f'<span style="display:inline-block;">'
            f'<input type="{inp}" id="{bid}" name="{name}" value="{_h.escape(value)}" {checked}>'
            f'<label for="{bid}">{_h.escape(label)}</label>'
            f'</span>'
        )
    return (
        f'{css}'
        f'<div class="{name}" style="margin:1rem 0;{wrap}">'
        f'{title_html}'
        f'<div style="display:flex;flex-wrap:wrap;gap:8px;">{btns}</div>'
        f'</div>'
    )




def _render_skeleton_stage_card(b: dict) -> str:
    variant = b.get("variant", "card")
    lines   = max(1, int(b.get("lines", 3)))
    count   = max(1, int(b.get("count", 1)))
    uid     = abs(_wa_shash(variant + str(lines) + str(count))) % 100000

    css = (
        f'<style>'
        f'@keyframes ssc_sh{uid}{{0%{{background-position:-200% 0}}'
        f'100%{{background-position:200% 0}}}}'
        f'.ssc{uid}{{background:linear-gradient(90deg,#1e293b 25%,#2d3a4a 50%,#1e293b 75%);'
        f'background-size:200% 100%;animation:ssc_sh{uid} 1.8s infinite linear;border-radius:4px;}}'
        f'</style>'
    )

    def _card():
        line_rows = "".join(
            f'<div class="ssc{uid}" style="height:11px;width:{"70%" if i==lines-1 else "100%"};'
            f'margin-bottom:8px;"></div>'
            for i in range(lines)
        )
        return (
            f'<div style="background:#0f172a;border:1px solid #1e293b;border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:16px;">'
            f'<div style="display:flex;gap:12px;align-items:flex-start;margin-bottom:14px;">'
            f'<div class="ssc{uid}" style="width:40px;height:40px;border-radius:50%;flex-shrink:0;"></div>'
            f'<div style="flex:1;">'
            f'<div class="ssc{uid}" style="height:12px;width:50%;margin-bottom:7px;"></div>'
            f'<div class="ssc{uid}" style="height:9px;width:32%;"></div>'
            f'</div></div>'
            f'{line_rows}</div>'
        )

    def _list():
        rows = "".join(
            f'<div style="display:flex;align-items:center;gap:10px;padding:9px 0;'
            f'border-bottom:1px solid #1e293b;">'
            f'<div class="ssc{uid}" style="width:32px;height:32px;border-radius:50%;flex-shrink:0;"></div>'
            f'<div style="flex:1;">'
            f'<div class="ssc{uid}" style="height:10px;width:58%;margin-bottom:6px;"></div>'
            f'<div class="ssc{uid}" style="height:8px;width:38%;"></div>'
            f'</div></div>'
            for _ in range(lines)
        )
        return (
            f'<div style="background:#0f172a;border:1px solid #1e293b;border-radius:10px;padding:12px;">'
            f'{rows}</div>'
        )

    def _media():
        return (
            f'<div style="background:#0f172a;border:1px solid #1e293b;border-radius:10px;overflow:hidden;">'
            f'<div class="ssc{uid}" style="height:180px;border-radius:0;"></div>'
            f'<div style="padding:12px;">'
            f'<div class="ssc{uid}" style="height:12px;width:68%;margin-bottom:8px;"></div>'
            f'<div class="ssc{uid}" style="height:10px;width:44%;"></div>'
            f'</div></div>'
        )

    def _chat():
        bubbles = ""
        for i in range(lines):
            ml = "margin-left:auto;" if i % 2 == 1 else ""
            r  = "12px 12px 4px 12px" if i % 2 == 1 else "12px 12px 12px 4px"
            bubbles += (
                f'<div style="max-width:62%;{ml}margin-bottom:10px;">'
                f'<div class="ssc{uid}" style="height:38px;border-radius:{r};"></div>'
                f'</div>'
            )
        return (
            f'<div style="background:#0f172a;border:1px solid #1e293b;border-radius:10px;padding:14px;">'
            f'{bubbles}</div>'
        )

    fn = {"list": _list, "media": _media, "chat": _chat}.get(variant, _card)
    cards = "".join(
        f'<div style="{"margin-bottom:10px;" if count>1 else ""}">{fn()}</div>'
        for _ in range(count)
    )
    return f'{css}<div style="margin:1rem 0;">{cards}</div>'


# ── Functional state-driven atoms (Magic UI / CSS-only) ───────────────────────

def _render_word_flip(atom: dict) -> str:
    import hashlib
    words = atom.get("words", [])
    if not words or len(words) < 2:
        return f'<span>{_cv_esc(words[0] if words else "")}</span>'
    uid      = hashlib.md5(str(atom).encode()).hexdigest()[:6]
    speed_s  = {"slow": 4.0, "normal": 2.5, "fast": 1.2}.get(atom.get("speed", "normal"), 2.5)
    n        = len(words)
    total    = round(speed_s * n, 2)
    color    = atom.get("color", "var(--accent,#0369a1)")
    size     = atom.get("size", "inherit")
    weight   = atom.get("weight", "700")
    prefix   = atom.get("prefix", "")
    suffix   = atom.get("suffix", "")
    # N+1 spans: words + duplicate first for seamless loop reset
    spans    = "".join(
        f'<span style="display:block;height:1.2em;line-height:1.2em;">{_cv_esc(w)}</span>'
        for w in [*words, words[0]]
    )
    # translateY target: -N/(N+1)*100% moves through N words; steps(N,end) snaps to each
    target   = round(n / (n + 1) * 100, 4)
    return (
        f'<style>'
        f'@keyframes wf_{uid}{{0%{{transform:translateY(0);}}100%{{transform:translateY(-{target}%);}}}}'
        f'.wfi_{uid}{{animation:wf_{uid} {total}s steps({n},end) infinite;display:block;}}'
        f'</style>'
        f'<span data-cb="node" data-key="{_ck((atom.get("words") or [None])[0], "word_flip")}" style="font-size:{_cv_esc(size)};">'
        f'{_cv_esc(prefix)}'
        f'<span style="display:inline-flex;overflow:hidden;height:1.2em;vertical-align:middle;'
        f'color:{_cv_esc(color)};font-weight:{_cv_esc(weight)};">'
        f'<span class="wfi_{uid}">{spans}</span>'
        f'</span>'
        f'{_cv_esc(suffix)}'
        f'</span>'
    )


def _render_sonar_pulse(atom: dict) -> str:
    uid = 'sp-' + _wa_uid(atom)
    colors = {'critical': '#ef4444', 'success': '#34d399', 'info': '#38bdf8', 'warning': '#f59e0b'}
    variant = atom.get('variant')
    vkey = variant if isinstance(variant, str) and variant in colors else 'critical'
    color = _safe_css(atom.get('color'), colors[vkey])
    active = atom.get('active') is not False
    label = _first_text(atom.get('label'), atom.get('title'), atom.get('text'))
    body = _text_loose(atom.get('body'))
    size = atom.get('size')
    sz = {'sm': 60, 'md': 90, 'lg': 130}.get(size, 90) if isinstance(size, str) else 90
    dot_r = max(8, sz // 8)
    sr = 'position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;'
    label_html = ('<span style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:' + str(dot_r - 1) + 'px;font-weight:700;color:' + color
                  + ';z-index:2;white-space:nowrap;">' + _cv_esc(label) + '</span>') if label else ''
    body_html = ('<div style="font-size:0.82rem;color:var(--muted,#5f6368);margin-top:10px;text-align:center;">' + _cv_esc(body) + '</div>') if body else ''
    rings_css = ''
    rings_html = ''
    if active:
        rings_css = ('@keyframes ' + uid + '{0%{transform:scale(0.8);opacity:0.55;}100%{transform:scale(2.6);opacity:0;}}'
                     '@media (prefers-reduced-motion:reduce){.' + uid + '-r{animation:none!important;}}')
        rings_html = ''.join('<div aria-hidden="true" class="' + uid + '-r" style="position:absolute;inset:0;border-radius:50%;border:2px solid ' + color + ';opacity:0;animation:' + uid + ' 3s ease-out ' + str(i) + 's infinite;"></div>' for i in range(3))
    return ('<style>' + rings_css + '</style>'
            '<div data-cb="node" data-key="' + _ck(atom.get('label'), 'sonar_pulse') + '" style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;">'
            '<div style="position:relative;width:' + str(sz) + 'px;height:' + str(sz) + 'px;">'
            + rings_html +
            '<div aria-hidden="true" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:' + str(dot_r * 2) + 'px;height:' + str(dot_r * 2) + 'px;border-radius:50%;background:' + color + ';'
            'box-shadow:0 0 ' + str(dot_r * 2) + 'px color-mix(in srgb,' + color + ' 53%,transparent);z-index:1;"></div>'
            '<span style="' + sr + '">' + vkey + '</span>'
            + label_html
            + '</div>' + body_html + '</div>')


# ── Motion-primitive atoms (Magic UI-inspired, CSS-only) ──────────────────────

def _render_blur_fade_in(atom: dict) -> str:
    import hashlib
    uid       = hashlib.md5(str(atom).encode()).hexdigest()[:6]
    speed_map = {"slow": "1.2s", "normal": "0.7s", "fast": "0.35s"}
    dur       = speed_map.get(atom.get("speed", "normal"), "0.7s")
    delay     = atom.get("delay", "0s")
    blur      = atom.get("blur", "8px")
    bg        = atom.get("background", "transparent")
    direction = atom.get("direction", "up")
    drift_map = {
        "up":    "translateY(16px)", "down":  "translateY(-16px)",
        "left":  "translateX(16px)", "right": "translateX(-16px)",
        "none":  "translateY(0)",
    }
    from_transform = drift_map.get(direction, "translateY(16px)")
    title = atom.get("title", "")
    body  = atom.get("body", "")
    title_html = f'<div style="font-size:1.1rem;font-weight:700;color:#4878a8;margin-bottom:8px;">{_cv_esc(title)}</div>' if title else ""
    body_html  = f'<div style="font-size:0.9rem;color:var(--muted,#5f6368);line-height:1.65;">{_cv_esc(body)}</div>' if body else ""
    content    = title_html + body_html if (title or body) else '<div style="font-size:0.9rem;color:var(--muted,#5f6368);">Content fades in with blur reveal.</div>'
    return (
        f'<style>'
        f'@keyframes bfi_{uid}{{from{{opacity:0;filter:blur({_cv_esc(blur)});transform:{from_transform};}}'
        f'to{{opacity:1;filter:blur(0);transform:translate(0);}}}}'
        f'.bfi_{uid}{{animation:bfi_{uid} {dur} ease-out {_cv_esc(delay)} both;'
        f'background:{_cv_esc(bg)};border-radius:12px;padding:24px 28px;margin:1rem 0;}}'
        f'</style>'
        f'<div class="bfi_{uid}">{content}</div>'
    )


def _render_glow_button(atom: dict) -> str:
    uid = 'gb-' + _wa_uid(atom)
    label = _first_text(atom.get('label'), atom.get('text'), atom.get('title')) or 'Button'
    st = atom.get('state')
    state = st if isinstance(st, str) and st in ('disabled', 'fired') else 'ready'
    href = '' if state == 'disabled' else _safe_href(atom.get('href'))
    color_r = _safe_css(atom.get('color_ready'), _safe_css(atom.get('color'), '#38bdf8'))
    color_f = _safe_css(atom.get('color_fired'), '#34d399')
    desc = _text_loose(atom.get('description'))
    sz = atom.get('size')
    pad, fsize = ({'sm': ('12px 22px', '13px'), 'md': ('14px 28px', '15px'), 'lg': ('18px 36px', '17px')}.get(sz, ('14px 28px', '15px'))
                  if isinstance(sz, str) else ('14px 28px', '15px'))

    def mix(c, p):
        return 'color-mix(in srgb,' + c + ' ' + str(p) + '%,transparent)'
    if state == 'disabled':
        bg, shadow, cursor, text_color, pulse = '#374151', '0 0 0 transparent', 'not-allowed', '#6b7280', ''
    elif state == 'fired':
        bg, cursor, text_color = '#0f2e1e', 'default', color_f
        shadow = '0 0 16px ' + color_f + ', 0 0 32px ' + mix(color_f, 27)
        pulse = ('@keyframes ' + uid + '-pulse{0%,100%{box-shadow:' + shadow + ';}50%{box-shadow:0 0 8px ' + mix(color_f, 53) + ';}}'
                 '.' + uid + '{animation:' + uid + '-pulse 1.8s ease-in-out infinite;}')
    else:
        bg, cursor, text_color = '#0c1e2e', 'pointer', color_r
        shadow = '0 0 14px ' + color_r + ', 0 0 28px ' + mix(color_r, 27)
        pulse = ('@keyframes ' + uid + '-pulse{0%,100%{box-shadow:' + shadow + ';}50%{box-shadow:0 0 6px ' + mix(color_r, 40) + ';}}'
                 '.' + uid + '{animation:' + uid + '-pulse 2.4s ease-in-out infinite;}')
    desc_html = ('<div style="font-size:12px;color:var(--muted,#5f6368);margin-top:6px;text-align:center;">' + _cv_esc(desc) + '</div>') if desc else ''
    if href:
        open_tag = '<a href="' + _cv_esc(href) + '" target="_top" rel="noopener" class="' + uid + '">'
        close_tag = '</a>'
    elif state == 'disabled':
        open_tag, close_tag = '<button type="button" disabled class="' + uid + '">', '</button>'
    else:
        open_tag, close_tag = '<button type="button" class="' + uid + '">', '</button>'
    return ('<style>'
            '.' + uid + '{display:inline-block;background:' + bg + ';color:' + text_color + ';font-size:' + fsize + ';font-weight:600;padding:' + pad + ';border-radius:8px;'
            'border:1px solid ' + mix(text_color, 27) + ';box-shadow:' + shadow + ';cursor:' + cursor + ';text-decoration:none;transition:box-shadow 0.2s;}'
            + pulse +
            '@media (prefers-reduced-motion:reduce){.' + uid + '{animation:none;}}'
            '</style>'
            '<div data-cb="node" data-key="' + _ck(atom.get('label'), 'glow_button') + '" style="margin:1rem 0;display:inline-block;">'
            + open_tag + _cv_esc(label) + close_tag + desc_html + '</div>')


def _render_animated_beam(atom: dict) -> str:
    import hashlib
    uid      = hashlib.md5(str(atom).encode()).hexdigest()[:6]
    from_lbl = atom.get("from_label", "Source")
    to_lbl   = atom.get("to_label", "Target")
    label    = atom.get("label", "")
    body     = atom.get("body", "")
    active   = atom.get("active", True)
    color    = atom.get("color", "#38bdf8")
    curved   = atom.get("curved", True)
    speed_map = {"slow": "3s", "normal": "1.8s", "fast": "1s"}
    dur      = speed_map.get(atom.get("speed", "normal"), "1.8s")
    # SVG layout constants
    W, H, NR = 340, 90, 18
    lx, rx   = NR + 10, W - NR - 10
    cy       = H // 2
    ctrl     = f"M{lx},{cy} C{lx+70},{cy-30} {rx-70},{cy-30} {rx},{cy}" if curved else f"M{lx},{cy} L{rx},{cy}"
    path_len = 260  # approximate
    anim_css = (
        f'@keyframes beam_{uid}{{0%{{stroke-dashoffset:{path_len};opacity:0;}}'
        f'10%{{opacity:1;}}90%{{opacity:1;}}100%{{stroke-dashoffset:0;opacity:0;}}}}'
        f'.bm_{uid}{{stroke-dasharray:{path_len};stroke-dashoffset:{path_len};'
        f'animation:beam_{uid} {dur} linear infinite;}}'
    ) if active else ""
    label_html = f'<div style="font-size:12px;font-weight:600;color:#64748b;margin-bottom:6px;letter-spacing:.05em;text-transform:uppercase;">{_cv_esc(label)}</div>' if label else ""
    body_html  = f'<div style="font-size:0.85rem;color:#94a3b8;margin-top:6px;">{_cv_esc(body)}</div>' if body else ""
    k = _cv_esc(str(atom['label'])) if atom.get('label') else 'animated_beam'
    return (
        f'<style>{anim_css}</style>'
        f'<div data-cb="node" data-key="{k}" style="background:#0f172a;border:1px solid #1e293b;border-radius:14px;'
        f'padding:20px 24px;margin:1rem 0;">'
        f'{label_html}'
        f'<svg role="img" aria-label="Animated beam diagram" width="{W}" height="{H}" viewBox="0 0 {W} {H}" '
        f'style="display:block;max-width:100%;">'
        # path track
        f'<path d="{ctrl}" fill="none" stroke="{_cv_esc(color)}22" stroke-width="2"/>'
        # animated beam dot
        f'<path class="bm_{uid}" d="{ctrl}" fill="none" stroke="{_cv_esc(color)}" '
        f'stroke-width="2.5" stroke-linecap="round"/>'
        # nodes
        f'<circle cx="{lx}" cy="{cy}" r="{NR}" fill="#1e293b" stroke="{_cv_esc(color)}" stroke-width="2"/>'
        f'<circle cx="{rx}" cy="{cy}" r="{NR}" fill="#1e293b" stroke="{_cv_esc(color)}" stroke-width="2"/>'
        # labels inside nodes (truncated)
        f'<text x="{lx}" y="{cy+1}" text-anchor="middle" dominant-baseline="middle" '
        f'font-size="9" font-family="monospace" fill="{_cv_esc(color)}">{_cv_esc(from_lbl[:6])}</text>'
        f'<text x="{rx}" y="{cy+1}" text-anchor="middle" dominant-baseline="middle" '
        f'font-size="9" font-family="monospace" fill="{_cv_esc(color)}">{_cv_esc(to_lbl[:6])}</text>'
        f'</svg>'
        f'{body_html}</div>'
    )


def _render_encrypted_reveal(atom: dict) -> str:
    import hashlib, random, string
    uid      = hashlib.md5(str(atom).encode()).hexdigest()[:6]
    text     = atom.get("text", "LOADING")
    size     = atom.get("size", "28px")
    weight   = atom.get("weight", "700")
    color    = atom.get("color", "#f1f5f9")
    s_color  = atom.get("scramble_color", "#38bdf8")
    delay    = atom.get("delay", "0s")
    frames   = min(max(atom.get("frames", 8), 3), 20)
    bg       = atom.get("background", "transparent")
    speed_map = {"slow": "2.4s", "normal": "1.4s", "fast": "0.8s"}
    total_dur = speed_map.get(atom.get("speed", "normal"), "1.4s")
    rng      = random.Random(uid)
    charset  = string.ascii_uppercase + string.digits + "@#$%&*"
    # Build CSS @keyframes: each frame step shows one scrambled string,
    # final step shows the real text.
    pct_step = 100 // (frames + 1)
    kf_stops = []
    for i in range(frames):
        scrambled = "".join(rng.choice(charset) for _ in text)
        pct       = i * pct_step
        kf_stops.append(
            f'{pct}%{{content:"{scrambled}";color:{_cv_esc(s_color)};}}'
        )
    kf_stops.append(f'100%{{content:"{_cv_esc(text)}";color:{_cv_esc(color)};}}')
    kf_body = "".join(kf_stops)
    pad = "24px 28px" if bg != "transparent" else "0"
    br  = "12px" if bg != "transparent" else "0"
    return (
        f'<style>'
        f'@keyframes er_{uid}{{{kf_body}}}'
        f'.er_{uid}::after{{content:"{_cv_esc(text)}";font-size:{_cv_esc(size)};font-weight:{_cv_esc(weight)};'
        f'color:{_cv_esc(color)};letter-spacing:.04em;font-family:monospace;'
        f'animation:er_{uid} {total_dur} steps(1,end) {_cv_esc(delay)} forwards;}}'
        f'.er_wrap_{uid}{{background:{_cv_esc(bg)};border-radius:{br};padding:{pad};margin:1rem 0;}}'
        f'</style>'
        f'<div data-cb="node" data-key="{_ck(None, "encrypted_reveal")}" class="er_wrap_{uid}"><span class="er_{uid}"></span></div>'
    )


