# ── Animation atoms ───────────────────────────────────────────────────────────

def _render_typewriter(b: dict) -> str:
    import hashlib
    uid      = hashlib.md5(str(b).encode()).hexdigest()[:6]
    text     = b.get("text", "Hello, world.")
    speed    = {"slow": 120, "normal": 60, "fast": 30}.get(b.get("speed", "normal"), 60)
    n        = len(text)
    dur      = round(n * speed / 1000, 2)
    cursor   = b.get("cursor", True)
    color    = b.get("color", "#0f172a")
    size     = b.get("size", "1.4rem")
    weight   = b.get("weight", "600")
    bg       = b.get("background", "#f8fafc")
    cursor_css = (
        f'@keyframes tw_blink_{uid}{{0%,100%{{border-color:transparent}}50%{{border-color:{_cv_esc(color)}}}}}'
        f'.tw_{uid}{{border-right:2px solid {_cv_esc(color)};animation:tw_{uid} {dur}s steps({n},end) forwards,'
        f'tw_blink_{uid} 0.75s step-end {dur}s infinite;}}'
    ) if cursor else (
        f'.tw_{uid}{{animation:tw_{uid} {dur}s steps({n},end) forwards;}}'
    )
    escaped = text.replace("'", "\\'")
    return (
        f'<style>'
        f'@keyframes tw_{uid}{{from{{width:0}}to{{width:{n}ch}}}}'
        f'{cursor_css}'
        f'</style>'
        f'<div style="padding:20px 24px;background:{_cv_esc(bg)};border-radius:10px;'
        f'border:1px solid #e2e8f0;margin:1rem 0;font-family:monospace;">'
        f'<span class="tw_{uid}" style="display:inline-block;overflow:hidden;'
        f'white-space:nowrap;font-size:{_cv_esc(size)};font-weight:{_cv_esc(weight)};color:{_cv_esc(color)};">'
        f'{_cv_esc(text)}</span></div>'
    )


def _render_number_odometer(b: dict) -> str:
    import hashlib
    uid    = hashlib.md5(str(b).encode()).hexdigest()[:6]
    value  = str(b.get("value", "1337"))
    label  = b.get("label", "")
    color  = b.get("color", "#0f172a")
    accent = b.get("accent", "#4f46e5")
    size   = b.get("size", "3rem")
    dur    = float(b.get("duration", 1.2))
    digits_html = ""
    for i, ch in enumerate(value):
        if ch.isdigit():
            d = int(ch)
            delay = round(i * 0.08, 2)
            strip = "".join(f'<div style="height:1.1em;line-height:1.1em;">{n}</div>' for n in range(10))
            digits_html += (
                f'<style>'
                f'@keyframes od_{uid}_{_cv_esc(i)}{{from{{transform:translateY(0)}}to{{transform:translateY(-{d * 10}%)}}}}'
                f'</style>'
                f'<div style="overflow:hidden;height:1.1em;">'
                f'<div style="animation:od_{uid}_{_cv_esc(i)} {dur}s cubic-bezier(.4,0,.2,1) {delay}s both;">'
                f'{strip}</div></div>'
            )
        else:
            digits_html += f'<div style="padding:0 2px;">{_cv_esc(ch)}</div>'
    label_html = f'<div style="font-size:0.8rem;color:var(--muted,#5f6368);margin-top:6px;letter-spacing:0.05em;text-transform:uppercase;">{_cv_esc(label)}</div>' if label else ""
    return (
        f'<div style="display:inline-flex;flex-direction:column;align-items:center;'
        f'padding:20px 28px;background:#fff;border:1px solid #e2e8f0;border-radius:12px;margin:1rem 0;">'
        f'<div style="display:flex;align-items:center;font-size:{_cv_esc(size)};font-weight:800;'
        f'color:{_cv_esc(color)};font-family:monospace;gap:1px;">'
        f'{digits_html}</div>'
        f'{label_html}</div>'
    )


def _render_typing_indicator(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    uid = _wa_uid(b)
    name = _first_text(b.get("name"), b.get("label"), b.get("text"), "Agent")
    variant = _text_loose(b.get("variant")).lower()
    is_light = variant == "light"

    bg_default = "#f1f5f9" if is_light else "#1e293b"
    bg = _safe_css(b.get("bg"), bg_default)
    dot_default = "#64748b" if is_light else "#617592"
    dot_col = _safe_css(_first_text(b.get("color"), b.get("accent")), dot_default)
    text_col = "#64748b" if is_light else "#617592"

    initial = name[:1].upper() if name else "A"
    prefix = f"ti_{uid}"
    ck_val = _first_text(b.get("name"), "typing_indicator")

    return (
        f'<style>'
        f'@keyframes {prefix}_bounce{{0%,80%,100%{{transform:translateY(0);}}40%{{transform:translateY(-6px);}}}}'
        f'.{prefix}_dot{{width:8px;height:8px;border-radius:50%;background:{dot_col};display:inline-block;margin:0 2px;}}'
        f'.{prefix}_dot:nth-child(1){{animation:{prefix}_bounce 1.2s ease-in-out 0s infinite;}}'
        f'.{prefix}_dot:nth-child(2){{animation:{prefix}_bounce 1.2s ease-in-out 0.2s infinite;}}'
        f'.{prefix}_dot:nth-child(3){{animation:{prefix}_bounce 1.2s ease-in-out 0.4s infinite;}}'
        f'@media (prefers-reduced-motion:reduce){{.{prefix}_dot{{animation:none!important;}}}}'
        f'</style>'
        f'<div data-cb="node" data-key="{_cv_esc(ck_val)}" role="status" style="display:flex;align-items:flex-end;gap:8px;margin:1rem 0;">'
        f'<div style="width:32px;height:32px;border-radius:50%;background:{dot_col};display:flex;align-items:center;justify-content:center;'
        f'font-size:13px;font-weight:700;color:#fff;flex-shrink:0;" aria-hidden="true">{_cv_esc(initial)}</div>'
        f'<div style="display:flex;flex-direction:column;gap:3px;">'
        f'<span style="font-size:11px;color:{text_col};font-weight:500;">{_cv_esc(name)}</span>'
        f'<span style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;">is typing</span>'
        f'<div style="background:{bg};border-radius:18px 18px 18px 4px;padding:12px 16px;display:inline-flex;align-items:center;gap:2px;">'
        f'<span class="{prefix}_dot" aria-hidden="true"></span>'
        f'<span class="{prefix}_dot" aria-hidden="true"></span>'
        f'<span class="{prefix}_dot" aria-hidden="true"></span>'
        f'</div>'
        f'</div>'
        f'</div>'
    )


def _render_countdown_timer(b: dict) -> str:
    import hashlib
    uid     = hashlib.md5(str(b).encode()).hexdigest()[:6]
    hours   = int(b.get("hours", 0))
    minutes = int(b.get("minutes", 4))
    seconds = int(b.get("seconds", 59))
    label   = b.get("label", "")
    variant = b.get("variant", "dark")
    bg      = "#0a0f1e" if variant == "dark" else "#fff"
    border  = "#1e293b" if variant == "dark" else "#e2e8f0"
    txt     = "#f1f5f9" if variant == "dark" else "#0f172a"
    sub_col = "#6d7e96"
    accent  = b.get("accent", "#00f2ff")

    def segment(val, lbl):
        d0, d1 = val // 10, val % 10
        return (
            f'<div style="display:flex;flex-direction:column;align-items:center;gap:4px;">'
            f'<div style="display:flex;gap:4px;">'
            + "".join(
                f'<div style="width:44px;height:60px;background:{bg};border:1px solid {border};'
                f'border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);display:flex;align-items:center;justify-content:center;'
                f'font-size:2rem;font-weight:800;color:{txt};font-family:monospace;">{d}</div>'
                for d in [d0, d1]
            )
            + f'</div>'
            f'<span style="font-size:10px;color:{sub_col};text-transform:uppercase;letter-spacing:0.1em;">{lbl}</span>'
            f'</div>'
        )

    sep = f'<div style="font-size:2rem;font-weight:800;color:{_cv_esc(accent)};padding-bottom:16px;align-self:flex-end;padding-right:2px;">:</div>'
    parts = []
    if hours:
        parts.append(segment(hours, "hrs"))
        parts.append(sep)
    parts.append(segment(minutes, "min"))
    parts.append(sep)
    parts.append(segment(seconds, "sec"))

    label_html = f'<div style="font-size:0.82rem;color:{sub_col};margin-top:10px;letter-spacing:0.06em;">{_cv_esc(label)}</div>' if label else ""
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("label"), "countdown_timer")}" style="display:inline-flex;flex-direction:column;align-items:center;'
        f'padding:24px 28px;background:{bg};border:1px solid {border};border-radius:14px;margin:1rem 0;">'
        f'<div style="display:flex;align-items:center;gap:8px;">'
        + "".join(parts)
        + f'</div>{label_html}</div>'
    )


def _render_gradient_text(b: dict) -> str:
    import hashlib
    uid    = hashlib.md5(str(b).encode()).hexdigest()[:6]
    text   = b.get("text", "Build something beautiful.")
    from_c = b.get("from", "#4f46e5")
    to_c   = b.get("to", "#06b6d4")
    via    = b.get("via", "")
    size   = b.get("size", "2rem")
    weight = b.get("weight", "800")
    dur    = float(b.get("duration", 4))
    grad   = f"{_cv_esc(from_c)}, {_cv_esc(via)}, {_cv_esc(to_c)}" if via else f"{_cv_esc(from_c)}, {_cv_esc(to_c)}"
    return (
        f'<style>'
        f'@keyframes gt_{uid}{{0%,100%{{background-position:0% 50%}}50%{{background-position:100% 50%}}}}'
        f'.gt_{uid}{{background:linear-gradient(90deg,{grad},{_cv_esc(from_c)});background-size:200% auto;'
        f'-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;'
        f'animation:gt_{uid} {dur}s ease infinite;}}'
        f'</style>'
        f'<div style="margin:1rem 0;padding:16px 0;">'
        f'<span class="gt_{uid}" style="font-size:{_cv_esc(size)};font-weight:{_cv_esc(weight)};line-height:1.2;">'
        f'{_cv_esc(text)}</span></div>'
    )


def _render_reveal_on_scroll(b: dict) -> str:
    title = _text_loose(b.get('title'))
    body = _first_text(b.get('body'), b.get('text'), b.get('content'))
    direction = b.get('direction')
    drift = {'up': 'translateY(32px)', 'down': 'translateY(-32px)', 'left': 'translateX(32px)', 'right': 'translateX(-32px)'}
    from_t = drift.get(direction, 'translateY(32px)') if isinstance(direction, str) else 'translateY(32px)'
    dn = _num_loose(b.get('duration'))
    dur_h = 70 if dn is None else max(0, min(3000, int(math.floor(dn * 100 + 0.5))))
    wn = _num_loose(b.get('delay'))
    wait_h = 0 if wn is None else max(0, min(3000, int(math.floor(wn * 100 + 0.5))))
    dur = format(dur_h / 100, 'g') + 's ease' + ((' ' + format(wait_h / 100, 'g') + 's') if wait_h > 0 else '')
    bg = _safe_css(b.get('background'), '#f8fafc')
    accent = _safe_css(b.get('accent'), '#4f46e5')
    uid = 'ros-' + _wa_uid(b)
    return ('<style>'
            '.' + uid + '.ros-js{opacity:0;transform:' + from_t + ';transition:opacity ' + dur + ',transform ' + dur + ';}'
            '.' + uid + '.ros-js.visible{opacity:1;transform:translate(0);}'
            '@media (prefers-reduced-motion:reduce){.' + uid + '.ros-js{opacity:1;transform:none;transition:none;}}'
            '</style>'
            '<div data-cb="node" data-key="' + _ck(b.get('title'), 'reveal_on_scroll') + '" id="' + uid + '" class="' + uid + '" style="padding:24px 28px;background:' + bg + ';border-left:3px solid ' + accent + ';'
            'border-radius:0 10px 10px 0;margin:1rem 0;">'
            + ('<div style="font-weight:700;color:#0f172a;margin-bottom:6px;">' + _cv_esc(title) + '</div>' if title else '')
            + ('<div style="font-size:0.9rem;color:var(--muted,#5f6368);line-height:1.6;">' + _md_inline(body) + '</div>' if body else '')
            + '</div>'
            '<script>(function(){var el=document.getElementById("' + uid + '");if(!el)return;el.classList.add("ros-js");'
            'function show(){el.classList.add("visible");}'
            'if("IntersectionObserver" in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){show();io.disconnect();}},{threshold:0.15});io.observe(el);}else{show();}'
            '})();</script>')


def _render_word_scramble(b: dict) -> str:
    import hashlib, random
    uid    = hashlib.md5(str(b).encode()).hexdigest()[:6]
    text   = b.get("text", "A2UI")
    dur    = float(b.get("duration", 2.0))
    color  = b.get("color", "#0f172a")
    scramble_color = b.get("scramble_color", "#4f46e5")
    size   = b.get("size", "2.5rem")
    weight = b.get("weight", "800")
    n      = len(text)
    chars  = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&"
    frames = 10
    rng    = random.Random(uid)
    keyframe_steps = []
    for f in range(frames):
        pct = round(f / frames * 100)
        revealed = int(f / frames * n)
        scrambled = "".join(
            text[i] if i < revealed else rng.choice(chars)
            for i in range(n)
        )
        keyframe_steps.append(f'{pct}%{{content:"{_cv_esc(scrambled)}"}}')
    keyframe_steps.append(f'100%{{content:"{_cv_esc(text)}"}}')
    return (
        f'<style>'
        f'@keyframes ws_{uid}{{{";".join(keyframe_steps)}}}'
        f'.ws_{uid}::after{{content:"{_cv_esc(text)}";animation:ws_{uid} {dur}s steps({frames},end) forwards;}}'
        f'</style>'
        f'<div style="margin:1rem 0;padding:16px 0;">'
        f'<span class="ws_{uid}" style="font-size:{_cv_esc(size)};font-weight:{_cv_esc(weight)};'
        f'color:{_cv_esc(color)};font-family:monospace;letter-spacing:0.04em;">'
        f'<span style="display:none;">{_cv_esc(text)}</span>'
        f'</span></div>'
    )


def _render_svg_path_draw(b: dict) -> str:
    import hashlib
    uid   = hashlib.md5(str(b).encode()).hexdigest()[:6]
    color = b.get("color", "#4f46e5")
    dur   = float(b.get("duration", 1.5))
    label = b.get("label", "")
    label_html = f'<div style="font-size:0.8rem;color:var(--muted,#5f6368);text-align:center;margin-top:4px;">{_cv_esc(label)}</div>' if label else ""

    # Text mode — SVG <text> stroke-dashoffset draw animation
    text = b.get("text", "")
    if text:
        font_size   = int(b.get("font_size", 48))
        weight      = b.get("weight", "900")
        font         = b.get("font", "monospace")
        char_by_char = b.get("letter_by_letter", False)

        char_w = font_size * 0.62   # monospace char width estimate
        vw     = max(len(text) * char_w + font_size * 0.4, 200)
        vh     = font_size * 1.6
        y      = font_size * 1.1

        if char_by_char:
            # Each character drawn sequentially with staggered delay
            char_dur  = dur / max(len(text), 1)     # time per character
            char_len  = int(font_size * 2.8)         # estimated stroke length per glyph
            chars_svg = []
            for i, ch in enumerate(text):
                delay = i * char_dur
                cid   = f"c{_cv_esc(i)}_{uid}"
                x     = font_size * 0.2 + i * char_w + char_w / 2
                chars_svg.append(
                    f'<style>'
                    f'@keyframes sc_{cid}{{from{{stroke-dashoffset:{char_len}}}to{{stroke-dashoffset:0}}}}'
                    f'.sc_{cid}{{stroke-dasharray:{char_len};stroke-dashoffset:{char_len};fill:none;'
                    f'animation:sc_{cid} {char_dur:.3f}s ease-out {delay:.3f}s forwards;}}'
                    f'</style>'
                    f'<text class="sc_{cid}" x="{x:.1f}" y="{y:.1f}" text-anchor="middle" '
                    f'font-size="{font_size}" font-weight="{_cv_esc(weight)}" font-family="{_cv_esc(font)}" '
                    f'stroke="{_cv_esc(color)}" stroke-width="1.5">{_cv_esc(ch)}</text>'
                )
            return (
                f'<div data-cb="node" data-key="{_ck(b.get("label"), "svg_path_draw")}" style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;overflow-x:auto;">'
                f'<svg role="img" aria-label="Path drawing animation" viewBox="0 0 {vw:.0f} {vh:.0f}" width="100%" style="max-width:{vw:.0f}px;">'
                + "".join(chars_svg) +
                f'</svg>{label_html}</div>'
            )

        # Single-element draw (whole text at once)
        length = int(len(text) * font_size * 0.85)
        return (
            f'<style>'
            f'@keyframes spt_{uid}{{from{{stroke-dashoffset:{length}}}to{{stroke-dashoffset:0}}}}'
            f'.spt_{uid}{{stroke-dasharray:{length};stroke-dashoffset:{length};fill:none;'
            f'animation:spt_{uid} {dur}s ease-out forwards;}}'
            f'</style>'
            f'<div data-cb="node" data-key="{_ck(b.get("label"), "svg_path_draw")}" style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;overflow-x:auto;">'
            f'<svg role="img" aria-label="Path drawing animation" viewBox="0 0 {vw:.0f} {vh:.0f}" width="100%" style="max-width:{vw:.0f}px;">'
            f'<text class="spt_{uid}" x="{vw/2:.0f}" y="{y:.0f}" '
            f'text-anchor="middle" font-size="{font_size}" font-weight="{_cv_esc(weight)}" '
            f'font-family="{_cv_esc(font)}" stroke="{_cv_esc(color)}" stroke-width="1.5">'
            f'{_cv_esc(text)}</text></svg>'
            f'{label_html}</div>'
        )

    # Shape mode
    width  = int(b.get("width", 3))
    shape  = b.get("shape", "arrow")

    # Tree — multi-path sequential draw
    if shape == "tree":
        # (path_d, approx_length, stroke_width)  — drawn trunk→branches→twigs
        segments = [
            ("M 100 220 L 100 155",    65, 4),   # trunk
            ("M 100 185 L 58 148",     55, 3),   # mid-left
            ("M 100 185 L 142 148",    55, 3),   # mid-right
            ("M 100 155 L 100 108",    47, 3),   # upper trunk
            ("M 100 130 L 48 92",      60, 2.5), # left main
            ("M 100 130 L 152 92",     60, 2.5), # right main
            ("M 48 92  L 22 62",       38, 2),   # left-left
            ("M 48 92  L 62 58",       36, 2),   # left-right
            ("M 152 92 L 138 58",      36, 2),   # right-left
            ("M 152 92 L 178 62",      38, 2),   # right-right
            ("M 100 108 L 72 72",      44, 2),   # top-left
            ("M 100 108 L 128 72",     44, 2),   # top-right
            ("M 100 108 L 100 68",     40, 2),   # top-center
            ("M 100 68  L 84 44",      28, 1.5), # apex-left
            ("M 100 68  L 116 44",     28, 1.5), # apex-right
            ("M 72 72   L 58 50",      27, 1.5), # twig ll
            ("M 128 72  L 142 50",     27, 1.5), # twig rr
        ]
        total     = sum(s[1] for s in segments)
        seg_parts = []
        t = 0.0
        for i, (pd, plen, sw) in enumerate(segments):
            delay    = t / total * dur
            seg_dur  = plen / total * dur
            sid      = f"tr{_cv_esc(i)}_{uid}"
            seg_parts.append(
                f'<style>'
                f'@keyframes {sid}{{from{{stroke-dashoffset:{plen}}}to{{stroke-dashoffset:0}}}}'
                f'</style>'
                f'<path stroke-dasharray="{plen}" stroke-dashoffset="{plen}" fill="none" '
                f'stroke="{_cv_esc(color)}" stroke-width="{sw}" stroke-linecap="round" stroke-linejoin="round" '
                f'style="animation:{sid} {seg_dur:.3f}s ease-out {delay:.3f}s forwards;" d="{pd}"/>'
            )
            t += plen
        return (
            f'<div data-cb="node" data-key="{_ck(b.get("label"), "svg_path_draw")}" style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;">'
            f'<svg role="img" aria-label="Path drawing animation" viewBox="0 0 200 230" width="220" height="230">'
            + "".join(seg_parts) +
            f'</svg>{label_html}</div>'
        )

    if shape == "iso_city":
        import math
        u   = int(b.get("unit", 20))
        s32 = math.sqrt(3) / 2
        ox, oy = 220, 195
        vw, vh = 440, 290

        grid_data = b.get("grid", [
            (0,0,3),(1,0,5),(2,0,2),(3,0,4),
            (0,1,4),(1,1,7),(2,1,3),(3,1,2),
            (0,2,2),(1,2,4),(2,2,6),(3,2,3),
            (0,3,5),(1,3,3),(2,3,4),(3,3,2),
        ])
        # painter's order: back → front
        grid_sorted = sorted(grid_data, key=lambda b: (b[0]+b[1]))

        def iso_pts(*coords):
            out = []
            for ix, iy, iz in coords:
                sx = ox + (ix - iy) * u * s32
                sy = oy + (ix + iy) * u * 0.5 - iz * u
                out.append(f"{sx:.1f},{sy:.1f}")
            return " ".join(out)

        def poly(pts, fill, stroke, sw=1.2):
            return f'<polygon points="{iso_pts(*pts)}" fill="{fill}" stroke="{_cv_esc(stroke)}" stroke-width="{sw}" stroke-linejoin="round"/>'

        parts  = []
        n      = len(grid_sorted)
        stagger = dur * 0.8 / n
        b_dur   = dur * 0.35

        for i, (gx, gy, h) in enumerate(grid_sorted):
            bid   = f"ic{_cv_esc(i)}_{uid}"
            delay = i * stagger
            # right wall (x=gx+1)
            rf = poly([(gx+1,gy,0),(gx+1,gy,h),(gx+1,gy+1,h),(gx+1,gy+1,0)],
                      "rgba(0,40,70,0.92)", "#0369a1", 1)
            # left wall (y=gy+1)
            lf = poly([(gx,gy+1,0),(gx,gy+1,h),(gx+1,gy+1,h),(gx+1,gy+1,0)],
                      "rgba(0,65,105,0.88)", "#0891b2", 1)
            # top face
            tf = poly([(gx,gy,h),(gx+1,gy,h),(gx+1,gy+1,h),(gx,gy+1,h)],
                      "rgba(0,210,240,0.18)", color, 1.8)
            parts.append(
                f'<style>@keyframes {bid}{{from{{opacity:0;transform:translateY(10px)}}'
                f'to{{opacity:1;transform:translateY(0)}}}}</style>'
                f'<g style="animation:{bid} {b_dur:.2f}s ease-out {delay:.2f}s both;">'
                + rf + lf + tf + '</g>'
            )

        return (
            f'<div style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;">'
            f'<svg viewBox="0 0 {vw} {vh}" width="{vw}" height="{vh}">'
            + "".join(parts) +
            f'</svg>{label_html}</div>'
        )

    if shape == "neural_net":
        import math
        layers     = b.get("layers", [3, 5, 5, 2])
        r          = int(b.get("node_radius", 11))
        edge_color = b.get("edge_color", "#1e3a5f")
        vw, vh     = 400, 300
        circ       = int(2 * math.pi * r) + 1

        # Compute node positions
        n_layers = len(layers)
        xs = [vw * (i + 1) / (n_layers + 1) for i in range(n_layers)]
        nodes = []   # (layer, x, y)
        for li, (x, count) in enumerate(zip(xs, layers)):
            for ni in range(count):
                y = vh * (ni + 1) / (count + 1)
                nodes.append((li, x, y))

        parts = []
        t = 0.0
        node_phase = 0.35 * dur   # first 35% of duration: nodes appear
        edge_phase = 0.65 * dur   # remaining 65%: edges draw in layer order

        # ── Phase 1: nodes (circles) ──────────────────────────────────────
        n_nodes = len(nodes)
        for idx, (li, x, y) in enumerate(nodes):
            delay    = node_phase * idx / n_nodes
            seg_dur  = node_phase / n_nodes + 0.15
            nid      = f"nn{_cv_esc(idx)}_{uid}"
            # layer colour: input=cyan, hidden=purple, output=green
            ncol = [color, "#a78bfa", "#a78bfa", "#34d399"]
            nc   = ncol[li] if li < len(ncol) else color
            parts.append(
                f'<style>@keyframes {nid}{{from{{stroke-dashoffset:{circ};opacity:0}}'
                f'to{{stroke-dashoffset:0;opacity:1}}}}</style>'
                f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{r}" fill="rgba(0,0,0,0.6)" '
                f'stroke="{_cv_esc(nc)}" stroke-width="2" '
                f'stroke-dasharray="{circ}" stroke-dashoffset="{circ}" '
                f'style="animation:{nid} {seg_dur:.3f}s ease-out {delay:.3f}s forwards;opacity:0;"/>'
            )

        # ── Phase 2: edges, drawn layer by layer ──────────────────────────
        # Collect edges grouped by layer transition
        layer_edges = []
        for li in range(n_layers - 1):
            from_n = [(x, y) for (l, x, y) in nodes if l == li]
            to_n   = [(x, y) for (l, x, y) in nodes if l == li + 1]
            for fx, fy in from_n:
                for tx, ty in to_n:
                    layer_edges.append((li, fx, fy, tx, ty))

        n_edges     = len(layer_edges)
        # Spread edges evenly across edge_phase, but stagger within each layer
        layer_starts = {}
        for li in range(n_layers - 1):
            layer_starts[li] = node_phase + edge_phase * li / (n_layers - 1)

        layer_edge_counts = {}
        for li, *_ in layer_edges:
            layer_edge_counts[li] = layer_edge_counts.get(li, 0) + 1

        layer_edge_idx = {li: 0 for li in range(n_layers - 1)}
        layer_edge_dur = edge_phase / (n_layers - 1)

        for eidx, (li, fx, fy, tx, ty) in enumerate(layer_edges):
            elen     = math.sqrt((tx - fx) ** 2 + (ty - fy) ** 2)
            elen_i   = int(elen) + 1
            count_in_layer = layer_edge_counts[li]
            idx_in_layer   = layer_edge_idx[li]
            delay    = layer_starts[li] + layer_edge_dur * idx_in_layer / count_in_layer
            seg_dur  = layer_edge_dur / count_in_layer + 0.12
            eid      = f"ne{_cv_esc(eidx)}_{uid}"
            layer_edge_idx[li] += 1
            parts.append(
                f'<style>@keyframes {eid}{{from{{stroke-dashoffset:{elen_i};opacity:0}}'
                f'to{{stroke-dashoffset:0;opacity:0.35}}}}</style>'
                f'<line x1="{fx:.1f}" y1="{fy:.1f}" x2="{tx:.1f}" y2="{ty:.1f}" '
                f'stroke="{_cv_esc(edge_color)}" stroke-width="1" '
                f'stroke-dasharray="{elen_i}" stroke-dashoffset="{elen_i}" '
                f'style="animation:{eid} {seg_dur:.3f}s ease-out {delay:.3f}s forwards;opacity:0;"/>'
            )

        return (
            f'<div data-cb="node" data-key="{_ck(b.get("label"), "svg_path_draw")}" style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;">'
            f'<svg viewBox="0 0 {vw} {vh}" width="{vw}" height="{vh}">'
            + "".join(parts) +
            f'</svg>{label_html}</div>'
        )

    shapes = {
        "arrow":    ("M 20 60 L 80 60 L 65 45 M 80 60 L 65 75", 100, 100),
        "check":    ("M 20 55 L 42 78 L 80 28",                   100, 100),
        "circle":   ("M 50 10 A 40 40 0 1 1 49.9 10",             100, 100),
        "zigzag":   ("M 10 50 L 30 20 L 50 50 L 70 20 L 90 50",   100, 70),
        "infinity": ("M 35 50 C 35 30 10 30 10 50 C 10 70 35 70 50 50 C 65 30 90 30 90 50 C 90 70 65 70 50 50", 100, 100),
    }
    path_d, vw, vh = shapes.get(shape, shapes["arrow"])
    length = {"arrow": 110, "check": 80, "circle": 252, "zigzag": 140, "infinity": 200}.get(shape, 150)
    return (
        f'<style>'
        f'@keyframes sp_{uid}{{from{{stroke-dashoffset:{length}}}to{{stroke-dashoffset:0}}}}'
        f'.sp_{uid}{{stroke-dasharray:{length};stroke-dashoffset:{length};'
        f'animation:sp_{uid} {dur}s ease-out forwards;}}'
        f'</style>'
        f'<div data-cb="node" data-key="{_ck(b.get("label"), "svg_path_draw")}" style="display:flex;flex-direction:column;align-items:center;margin:1rem 0;">'
        f'<svg role="img" aria-label="{_cv_esc(label or "Path drawing animation")}" viewBox="0 0 {vw} {vh}" width="160" height="160" fill="none" '
        f'stroke="{_cv_esc(color)}" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round">'
        f'<path class="sp_{uid}" d="{path_d}"/></svg>'
        f'{label_html}</div>'
    )


_SKETCHPAD_ALLOWED_TAGS = {"circle", "ellipse", "rect", "line", "polyline", "polygon", "path", "g"}
_SKETCHPAD_ALLOWED_ATTRS = {
    "cx", "cy", "r", "rx", "ry", "x", "y", "width", "height",
    "x1", "y1", "x2", "y2", "points", "d",
    "fill", "stroke", "stroke-width", "opacity", "fill-opacity",
    "stroke-opacity", "stroke-linecap", "stroke-linejoin", "transform",
}
_SKETCHPAD_SAFE_VALUE = __import__("re").compile(r"^[A-Za-z0-9#.,\-\s()%]*$")


def _validate_sketchpad_element(fragment: str):
    """Real, defensive validation -- never trust `element` as pre-cleaned
    just because the agent that sent it (streaming-testbench's
    sketch_agent.py) already validates its own output before emitting;
    this atom is a generic a2uicatalog atom, reachable from any caller.
    Ported from sketch_agent.py's own validate_svg_fragment (same
    allowlist, same real XML parser rather than a regex over raw markup --
    a crafted fragment can bypass a regex via parser-differential tricks,
    matching that module's own docstring reasoning). Returns the parsed
    ET.Element (not yet re-serialized -- the caller may still need to set
    the draw-in-animation attributes on it) if `fragment` is exactly ONE
    element (nesting allowed under <g>) built entirely from the allowlist,
    else None. The 4096-char raw-length cap (checked BEFORE parsing) is
    resource-exhaustion defense, not a correctness rule -- a real element
    is never anywhere near this long; it just stops a pathologically huge
    string from being handed to the XML parser at all."""
    if len(fragment) > 4096:
        return None
    import xml.etree.ElementTree as ET
    try:
        root = ET.fromstring("<g>" + fragment + "</g>")
    except ET.ParseError:
        return None
    children = list(root)
    if len(children) != 1:
        return None
    if not _validate_sketchpad_subtree(children[0]):
        return None
    return children[0]


def _validate_sketchpad_subtree(el) -> bool:
    tag = el.tag.split("}")[-1]
    if tag not in _SKETCHPAD_ALLOWED_TAGS:
        return False
    for key, value in el.attrib.items():
        if key not in _SKETCHPAD_ALLOWED_ATTRS or not _SKETCHPAD_SAFE_VALUE.match(value):
            return False
    return all(_validate_sketchpad_subtree(child) for child in el)


def _render_agent_sketchpad(b: dict) -> str:
    """2026-08-24, redesigned 2026-08-24: a composite multi-shape canvas --
    see the .gs renderer (apps-script-surface/gas-wired-renderer/
    atoms_charts.gs) for the full design rationale, ported here 1:1 since
    works_on:web requires a real renderer in THIS file (tests/
    test_schema.py enforces it). Every re-render draws all elements except
    the LAST as already-complete; only the newest element gets the real
    draw-in animation -- stateless, no memory of prior renders needed."""
    import hashlib
    import html as _html
    strokes = b.get("strokes") if isinstance(b.get("strokes"), list) else []
    view_box = b.get("viewBox", "0 0 400 200")
    label = b.get("label", "")
    uid = hashlib.md5(str(b).encode()).hexdigest()[:6]
    label_html = (
        f'<div style="font-size:0.85rem;font-weight:600;color:var(--muted,#5f6368);margin-bottom:8px;">{_html.escape(label)}</div>'
        if label else ""
    )
    import xml.etree.ElementTree as ET
    last_idx = len(strokes) - 1
    elements = []
    for i, s in enumerate(strokes):
        if i >= 250:
            break
        raw = s.get("element") if isinstance(s, dict) else None
        el = _validate_sketchpad_element(raw) if isinstance(raw, str) and raw else None
        if el is None:
            continue
        k = s.get("id") or s.get("label") or s.get("title") or str(i) if isinstance(s, dict) else str(i)
        el.set("data-cb", "link")
        el.set("data-key", str(k))
        if i == last_idx:
            el.set("stroke-dasharray", "1000")
            el.set("stroke-dashoffset", "1000")
            el.set("style", f"animation:sketch-draw-{uid} 1.2s ease-out forwards;")
        elements.append(ET.tostring(el, encoding="unicode"))
    return (
        f'<div style="margin:1rem 0;">'
        f'<style>@keyframes sketch-draw-{uid}{{to{{stroke-dashoffset:0;}}}}</style>'
        f'{label_html}'
        f'<svg viewBox="{_html.escape(view_box)}" role="img" aria-label="{_html.escape(label or "Agent sketchpad drawing")}" style="width:100%;height:auto;'
        f'border:1px solid #e5e7eb;border-radius:8px;" xmlns="http://www.w3.org/2000/svg">'
        + "".join(elements) +
        f'</svg></div>'
    )


def _render_toast_notification(b: dict) -> str:
    import hashlib
    uid     = hashlib.md5(str(b).encode()).hexdigest()[:6]
    title   = b.get("title", "Changes saved")
    message = b.get("message", "Your updates have been applied successfully.")
    variant = b.get("variant", "success")
    pos     = b.get("position", "bottom-right")
    color_map = {"success": "#22c55e", "error": "#ef4444", "info": "#3b82f6", "warning": "#f59e0b"}
    icon_map  = {"success": "✓", "error": "✕", "info": "ℹ", "warning": "⚠"}
    accent = color_map.get(variant, "#22c55e")
    icon   = icon_map.get(variant, "✓")
    pos_css = {"bottom-right": "bottom:20px;right:20px", "bottom-left": "bottom:20px;left:20px",
               "top-right": "top:20px;right:20px", "top-left": "top:20px;left:20px"}.get(pos, "bottom:20px;right:20px")
    from_t  = "translateX(120%)" if "right" in pos else "translateX(-120%)"
    return (
        f'<style>'
        f'@keyframes tn_in_{uid}{{from{{transform:{from_t};opacity:0}}to{{transform:translateX(0);opacity:1}}}}'
        f'@keyframes tn_out_{uid}{{from{{transform:translateX(0);opacity:1}}to{{transform:{from_t};opacity:0}}}}'
        f'.tn_{uid}{{position:fixed;{pos_css};z-index:9999;min-width:280px;max-width:360px;'
        f'background:#fff;border-radius:10px;box-shadow:0 8px 32px rgba(0,0,0,0.12);'
        f'border:1px solid #e2e8f0;padding:14px 16px;display:flex;align-items:flex-start;gap:12px;'
        f'animation:tn_in_{uid} 0.3s ease forwards,tn_out_{uid} 0.3s ease 3.5s forwards;}}'
        f'</style>'
        f'<div style="position:relative;height:80px;margin:1rem 0;border:1px dashed #e2e8f0;'
        f'border-radius:10px;background:#f8fafc;display:flex;align-items:center;justify-content:center;">'
        f'<span style="font-size:0.8rem;color:var(--muted,#5f6368);">Toast appears fixed in viewport →</span>'
        f'</div>'
        f'<div class="tn_{uid}">'
        f'<div style="width:28px;height:28px;border-radius:50%;background:{accent};flex-shrink:0;'
        f'display:flex;align-items:center;justify-content:center;font-size:14px;color:#fff;font-weight:700;">{icon}</div>'
        f'<div style="flex:1;min-width:0;">'
        f'<div style="font-size:0.88rem;font-weight:700;color:#0f172a;margin-bottom:2px;">{_cv_esc(title)}</div>'
        f'<div style="font-size:0.8rem;color:var(--muted,#5f6368);line-height:1.4;">{_cv_esc(message)}</div>'
        f'</div></div>'
    )


def _render_parallax_card(b: dict) -> str:
    import hashlib
    uid     = hashlib.md5(str(b).encode()).hexdigest()[:6]
    title   = b.get("title", "Parallax Card")
    body    = b.get("body", "Hover to see the 3D tilt effect.")
    badge   = b.get("badge", "")
    accent  = b.get("accent", "#4f46e5")
    bg      = b.get("background", "#0f172a")
    depth   = int(b.get("depth", 15))
    return (
        f'<style>'
        f'.pc_{uid}{{background:{_cv_esc(bg)};border-radius:16px;padding:28px;margin:1rem 0;'
        f'max-width:320px;border:1px solid rgba(255,255,255,0.08);'
        f'box-shadow:0 20px 60px rgba(0,0,0,0.3);transform-style:preserve-3d;'
        f'transition:transform 0.15s ease,box-shadow 0.15s ease;cursor:default;'
        f'perspective:800px;}}'
        f'.pc_{uid}:hover{{box-shadow:0 30px 80px rgba(0,0,0,0.4);}}'
        f'.pc_inner_{uid}{{transform-style:preserve-3d;}}'
        f'.pc_badge_{uid}{{display:inline-block;background:{_cv_esc(accent)};color:#fff;'
        f'font-size:11px;font-weight:700;padding:3px 10px;border-radius:20px;'
        f'margin-bottom:14px;transform:translateZ(20px);}}'
        f'.pc_title_{uid}{{font-size:1.25rem;font-weight:800;color:#f1f5f9;margin-bottom:8px;'
        f'transform:translateZ(30px);display:block;}}'
        f'.pc_body_{uid}{{font-size:0.85rem;color:var(--muted,#5f6368);line-height:1.6;transform:translateZ(15px);display:block;}}'
        f'</style>'
        f'<div class="pc_{uid}">'
        f'<div class="pc_inner_{uid}">'
        + (f'<div class="pc_badge_{uid}">{_cv_esc(badge)}</div>' if badge else '')
        + f'<span class="pc_title_{uid}">{_cv_esc(title)}</span>'
        f'<span class="pc_body_{uid}">{_cv_esc(body)}</span>'
        f'</div></div>'
        f'<script>(function(){{'
        f'var c=document.currentScript.previousElementSibling;'
        f'if(!c)return;'
        f'c.addEventListener("mousemove",function(e){{'
        f'var r=c.getBoundingClientRect();'
        f'var x=(e.clientX-r.left)/r.width-0.5;'
        f'var y=(e.clientY-r.top)/r.height-0.5;'
        f'c.style.transform="perspective(800px) rotateY("+x*{depth}+"deg) rotateX("+(-y*{depth})+"deg) scale(1.02)";'
        f'}});'
        f'c.addEventListener("mouseleave",function(){{'
        f'c.style.transform="perspective(800px) rotateY(0) rotateX(0) scale(1)";'
        f'}});}})();</script>'
    )


def _render_hint_reveal(b: dict) -> str:
    import hashlib
