def _render_match_exercise(b: dict) -> str:
    import hashlib, random as _random
    uid = "mx" + hashlib.md5(str(b).encode()).hexdigest()[:6]
    raw = b.get("pairs")
    pairs = [p for p in raw if isinstance(p, dict)] if isinstance(raw, list) else []
    if not pairs:
        return ""
    terms = [_first_text(p.get("term"), p.get("left"), p.get("key")) for p in pairs]
    defs = [_first_text(p.get("definition"), p.get("right"), p.get("value")) for p in pairs]
    if b.get("shuffle") is not False:
        defs = defs[:]
        # Seeded off the same content digest `uid` already derives from, so the
        # exercise shuffles identically on every render. Unseeded, this was the
        # last renderer that could rewrite its own markup with no input change.
        _random.Random(uid).shuffle(defs)

    left_col = "".join(
        f'<div data-cb="item" data-key="{_cv_esc(t)}" style="padding:8px 14px;border:1.5px solid #e2e8f0;border-radius:12px;border-radius:var(--a2ui-radius,12px);'
        f'margin:4px 0;font-size:0.88rem;color:#1e293b;background:#f8fafc;">{_cv_esc(t)}</div>'
        for t in terms
    )
    right_col = "".join(
        f'<div style="padding:8px 14px;border:1.5px solid #ddd6fe;border-radius:8px;'
        f'margin:4px 0;font-size:0.88rem;color:#4c1d95;background:#f5f3ff;cursor:grab;">{_cv_esc(d)}</div>'
        for d in defs
    )
    return (
        f'<div style="margin:1.2rem 0;">'
        f'<p style="font-size:0.78rem;color:var(--muted,#5f6368);margin-bottom:8px;">Match each term to its definition.</p>'
        f'<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">'
        f'<div>{left_col}</div><div>{right_col}</div>'
        f'</div></div>'
    )


def _render_fill_in_blank(b: dict) -> str:
    import hashlib, re
    uid      = "fib" + hashlib.md5(str(b).encode()).hexdigest()[:6]
    template = _cv_esc(b.get("template", ""))
    answers  = b.get("answers", [])
    hint     = b.get("hint", "")
    case_s   = b.get("case_sensitive", False)

    idx = [0]
    def make_input(m):
        i = idx[0]; idx[0] += 1
        ans = answers[i] if i < len(answers) else ""
        accepted = ans if isinstance(ans, list) else [ans]
        flag = "" if case_s else ".toLowerCase()"
        check_js = f'var v=this.value{flag};var ok={_js_json([str(a).lower() if not case_s else str(a) for a in accepted])}.indexOf(v)>-1;this.style.borderColor=ok?"#10b981":"#ef4444";this.style.background=ok?"#d1fae5":"#fee2e2";'
        return (
            f'<input id="{uid}_{i}" type="text" onblur="{_cv_esc(check_js)}" '
            f'style="border:1.5px solid #cbd5e1;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);padding:4px 8px;'
            f'font-size:0.9em;width:120px;margin:0 4px;transition:all 0.2s;" '
            f'placeholder="___" autocomplete="off"/>'
        )

    body = re.sub(r'\{blank\}', make_input, template)
    hint_html = f'<p style="font-size:0.8rem;color:var(--muted,#5f6368);margin-top:10px;">💡 {_cv_esc(hint)}</p>' if hint else ""
    return (
        f'<div style="border:1.5px solid #e2e8f0;border-radius:12px;padding:20px 24px;margin:1.2rem 0;background:#fff;">'
        f'<p style="font-size:0.95rem;color:#1e293b;margin:0 0 8px;line-height:1.9;">{body}</p>'
        f'{hint_html}'
        f'</div>'
    )


