def _render_countdown_ring(b: dict) -> str:
    import hashlib, math
    uid      = hashlib.md5(str(b).encode()).hexdigest()[:6]
    duration = int(b.get("duration_sec", 60))
    size     = int(b.get("size", 80))
    color    = b.get("color", "var(--a2ui-accent,#4f46e5)")
    label    = b.get("label", "")
    sw       = max(4, size // 12)
    r        = (size - sw) / 2
    circ     = round(2 * math.pi * r, 2)
    cx = cy  = size / 2
    label_html = f'<div style="font-size:0.75rem;color:var(--muted,#5f6368);margin-top:4px;text-align:center;">{_cv_esc(label)}</div>' if label else ""
    return (
        f'<style>'
        f'@keyframes cr_{uid}{{from{{stroke-dasharray:{circ} 0;}}to{{stroke-dasharray:0 {circ};}}}}'
        f'</style>'
        f'<div data-cb="node" data-key="{_ck(b.get("label"), "countdown_ring")}" style="margin:1rem 0;display:inline-flex;flex-direction:column;align-items:center;">'
        f'<div style="position:relative;width:{size}px;height:{size}px;">'
        f'<svg role="img" aria-label="Countdown timer" width="{size}" height="{size}" style="transform:rotate(-90deg);">'
        f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="#334155" stroke-width="{sw}"/>'
        f'<circle id="crring_{uid}" cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{_cv_esc(color)}" stroke-width="{sw}"'
        f' stroke-linecap="round" stroke-dasharray="{circ} 0"'
        f' style="animation:cr_{uid} {duration}s linear forwards;"/>'
        f'</svg>'
        f'<div id="crtxt_{uid}" style="position:absolute;inset:0;display:flex;align-items:center;'
        f'justify-content:center;font-size:{size//5}px;font-weight:700;color:#f1f5f9;">{duration}</div>'
        f'</div>{label_html}</div>'
        f'<script>(function(){{'
        f'var t={duration};var el=document.getElementById("crtxt_{uid}");'
        f'var iv=setInterval(function(){{t--;if(el)el.textContent=t;if(t<=0)clearInterval(iv);}},1000);'
        f'}})();</script>'
    )

_RENDERERS["countdown_ring"] = _render_countdown_ring


def _render_skeleton(b: dict) -> str:
    import hashlib
    uid  = hashlib.md5(str(b).encode()).hexdigest()[:6]
    kind = b.get("type_", b.get("skeleton_type", "text"))
    rows = int(b.get("rows", 3))
    cols = int(b.get("cols", 3))
    height = b.get("height", "200px")
    base = (
        f'<style>'
        f'@keyframes sk_{uid}{{0%{{background-position:-200% 0;}}100%{{background-position:200% 0;}}}}'
        f'.skb_{uid}{{background:linear-gradient(90deg,#1e293b 25%,#334155 50%,#1e293b 75%);'
        f'background-size:200% 100%;animation:sk_{uid} 1.6s linear infinite;border-radius:6px;}}'
        f'</style>'
    )
    line = f'<div class="skb_{uid}" style="height:14px;margin:8px 0;border-radius:4px;"></div>'
    if kind == "card":
        return base + (
            f'<div style="border:1px solid #334155;border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:20px;margin:1rem 0;">'
            f'<div class="skb_{uid}" style="height:120px;border-radius:8px;margin-bottom:12px;"></div>'
            f'<div class="skb_{uid}" style="height:14px;width:70%;margin-bottom:8px;"></div>'
            f'<div class="skb_{uid}" style="height:12px;width:50%;"></div>'
            f'</div>'
        )
    elif kind == "avatar_row":
        return base + (
            f'<div style="display:flex;align-items:center;gap:12px;margin:1rem 0;">'
            f'<div class="skb_{uid}" style="width:44px;height:44px;border-radius:50%;flex-shrink:0;"></div>'
            f'<div style="flex:1;">'
            f'<div class="skb_{uid}" style="height:13px;width:60%;margin-bottom:7px;"></div>'
            f'<div class="skb_{uid}" style="height:11px;width:40%;"></div>'
            f'</div></div>'
        )
    elif kind == "image":
        return base + f'<div class="skb_{uid}" style="height:{_cv_esc(height)};border-radius:10px;margin:1rem 0;"></div>'
    elif kind == "list":
        items = "".join(
            f'<div style="display:flex;gap:10px;align-items:center;margin:8px 0;">'
            f'<div class="skb_{uid}" style="width:16px;height:16px;border-radius:3px;flex-shrink:0;"></div>'
            f'<div class="skb_{uid}" style="flex:1;height:12px;"></div>'
            f'</div>'
            for _ in range(rows)
        )
        return base + f'<div style="margin:1rem 0;">{items}</div>'
    elif kind == "table":
        header = "".join(
            f'<div class="skb_{uid}" style="flex:1;height:14px;margin:0 4px;"></div>'
            for _ in range(cols)
        )
        body_rows = "".join(
            f'<div style="display:flex;gap:0;margin-top:10px;">' + "".join(
                f'<div class="skb_{uid}" style="flex:1;height:12px;margin:0 4px;opacity:0.7;"></div>'
                for _ in range(cols)
            ) + '</div>'
            for _ in range(rows)
        )
        return base + (
            f'<div style="margin:1rem 0;">'
            f'<div style="display:flex;margin-bottom:10px;">{header}</div>'
            f'{body_rows}</div>'
        )
    else:  # text
        widths = ["100%", "85%", "60%"]
        lines = "".join(
            f'<div class="skb_{uid}" style="height:13px;width:{widths[i % 3]};margin:7px 0;"></div>'
            for i in range(rows)
        )
        return base + f'<div style="margin:1rem 0;">{lines}</div>'

_RENDERERS["skeleton"] = _render_skeleton


def _render_marquee(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    uid = _wa_uid(b)
    prefix = f"mq_{uid}"

    raw_items = b.get("items")
    if not isinstance(raw_items, list):
        raw_items = []
    items = raw_items[:200]

    title = _first_text(b.get("title"), b.get("label"))
    speed_raw = _num_loose(b.get("speed"))
    speed = min(max(speed_raw, 1.0), 3600.0) if speed_raw is not None and speed_raw > 0 else 30
    gap_raw = _num_loose(b.get("gap"))
    gap = min(int(gap_raw + 0.5), 400) if gap_raw is not None and gap_raw >= 0 else 48
    direction = _text_loose(b.get("direction")).lower()
    anim_dir = "reverse" if direction == "right" else "normal"
    separator = _text_loose(b.get("separator"))
    pause_on_hover = b.get("pause_on_hover", True) is not False
    bg = _safe_css(b.get("bg"), "var(--surface,#f9fafb)")
    rounded = b.get("rounded", True) is not False
    color_icons = b.get("color_icons") is True
    accent = _safe_css(b.get("accent"), "var(--muted,#d1d5db)")
    border_radius = "10px" if rounded else "0"

    def _render_entry(item, is_dup=False):
        if not isinstance(item, dict):
            k = _text_loose(item)
            attr = f' data-cb="tile" data-key="{_cv_esc(k)}"' if not is_dup else ""
            return f'<span{attr} style="font-size:0.875rem;color:var(--text,#374151);white-space:nowrap;">{_cv_esc(k)}</span>'

        k = _first_text(item.get("text"), item.get("label"), item.get("image_url"), item.get("url"), item.get("icon"))
        attr = f' data-cb="tile" data-key="{_cv_esc(k)}"' if not is_dup else ""

        img_url = _safe_href(item.get("image_url"), schemes=("http", "https", "data"))
        raw_url = _safe_href(item.get("url"), schemes=("http", "https", "mailto"))
        icon = _text_loose(item.get("icon"))
        text = _first_text(item.get("text"), item.get("label"))

        inner = ""
        if img_url:
            img_style = "height:32px;object-fit:contain;" + ("" if color_icons else "opacity:0.7;filter:grayscale(1);")
            inner += f'<img src="{img_url}" alt="{_cv_esc(text)}" style="{img_style}">'
        if icon:
            inner += f'<span style="font-size:1.1rem;">{_cv_esc(icon)}</span>'
        if text:
            inner += f'<span style="font-size:0.875rem;color:var(--text,#374151);white-space:nowrap;">{_cv_esc(text)}</span>'

        if raw_url:
            return f'<a{attr} href="{raw_url}" target="_top" style="display:inline-flex;align-items:center;gap:6px;text-decoration:none;">{inner}</a>'
        return f'<span{attr} style="display:inline-flex;align-items:center;gap:6px;">{inner}</span>'

    sep_html = f'<span style="color:{accent};margin:0 4px;" aria-hidden="true">{_cv_esc(separator)}</span>' if separator else ""
    items_html = "".join(
        f'<span style="padding:0 {gap}px;display:inline-flex;align-items:center;">{_render_entry(it, False)}{sep_html}</span>'
        for it in items
    )
    items_dup_html = "".join(
        f'<span style="padding:0 {gap}px;display:inline-flex;align-items:center;">{_render_entry(it, True)}{sep_html}</span>'
        for it in items
    )

    pause_css = f'#{prefix}:hover #{prefix}-track{{animation-play-state:paused;}}' if pause_on_hover else ""
    speed_str = _text_loose(speed)

    title_html = (
        f'<div style="font-size:0.75rem;font-weight:700;color:var(--muted,#9ca3af);text-transform:uppercase;letter-spacing:0.06em;padding:8px 16px 0;">'
        f'{_cv_esc(title)}</div>'
    ) if title else ""

    return (
        f'<style>'
        f'@keyframes {prefix}{{from{{transform:translateX(0);}}to{{transform:translateX(-50%);}}}}'
        f'#{prefix}-track{{display:inline-flex;animation:{prefix} {speed_str}s linear infinite {anim_dir};white-space:nowrap;}}'
        f'{pause_css}'
        f'@media (prefers-reduced-motion:reduce){{#{prefix}-track{{animation:none;}}}}'
        f'</style>'
        f'{title_html}'
        f'<div id="{prefix}" style="overflow:hidden;background:{bg};border-radius:{border_radius};border:1px solid var(--border,#e5e7eb);padding:12px 0;margin:1rem 0;">'
        f'<div id="{prefix}-track">{items_html}<span aria-hidden="true" style="display:inline-flex;">{items_dup_html}</span></div>'
        f'</div>'
    )


_RENDERERS["marquee"] = _render_marquee


# ─── MagicUI cursor & motion atoms ────────────────────────────────────────────

def _render_cursor_glow(b: dict) -> str:
    import hashlib
    uid    = hashlib.md5(str(b).encode()).hexdigest()[:6]
    color  = b.get("colour", b.get("color", "#4f46e5"))
    size   = int(b.get("size", 380))
    opacity = float(b.get("opacity", 0.18))
    speed  = float(b.get("speed", 0.1))
    blend  = b.get("blend", "screen")
    h      = int(b.get("height", 220))
    return (
        f'<div id="cgw_{uid}" style="position:relative;overflow:hidden;height:{h}px;'
        f'background:var(--bg,#0c1117);border-radius:12px;border-radius:var(--a2ui-radius,12px);">'
        f'<div id="cg_{uid}" style="position:absolute;pointer-events:none;'
        f'width:{size}px;height:{size}px;border-radius:50%;'
        f'background:radial-gradient(circle,{_cv_esc(color)} 0%,transparent 70%);'
        f'opacity:{opacity};mix-blend-mode:{_cv_esc(blend)};'
        f'transform:translate(-50%,-50%);top:-999px;left:-999px;transition:none;"></div>'
        f'</div>'
        f'<script>(function(){{'
        f'var wrap=document.getElementById("cgw_{uid}");'
        f'var el=document.getElementById("cg_{uid}");'
        f'var tx=-999,ty=-999,cx=-999,cy=-999;'
        f'wrap.addEventListener("mousemove",function(e){{'
        f'var r=wrap.getBoundingClientRect();tx=e.clientX-r.left;ty=e.clientY-r.top;}});'
        f'wrap.addEventListener("mouseleave",function(){{tx=-999;ty=-999;}});'
        f'(function loop(){{'
        f'cx+=(tx-cx)*{speed};cy+=(ty-cy)*{speed};'
        f'el.style.left=Math.round(cx)+"px";el.style.top=Math.round(cy)+"px";'
        f'requestAnimationFrame(loop);}})();}})();</script>'
    )

_RENDERERS["cursor_glow"] = _render_cursor_glow


def _render_cursor_trail(b: dict) -> str:
    import hashlib
    uid    = hashlib.md5(str(b).encode()).hexdigest()[:6]
    color  = b.get("colour", b.get("color", "#4f46e5"))
    length = int(b.get("length", 16))
    size   = int(b.get("size", 10))
    speed  = float(b.get("speed", 0.35))
    h      = int(b.get("height", 200))
    return (
        f'<div id="ctw_{uid}" style="position:relative;overflow:hidden;height:{h}px;'
        f'background:var(--bg,#0c1117);border-radius:12px;border-radius:var(--a2ui-radius,12px);cursor:none;"></div>'
        f'<script>(function(){{'
        f'var wrap=document.getElementById("ctw_{uid}");'
        f'var n={length},s={speed},col="{_cv_esc(color)}",dotSz={size};'
        f'var dots=[],pts=[],active=false;'
        f'for(var i=0;i<n;i++){{'
        f'var d=document.createElement("div");var scale=1-i/n;'
        f'd.style.cssText="position:absolute;pointer-events:none;border-radius:50%;'
        f'width:"+Math.round(dotSz*scale)+"px;height:"+Math.round(dotSz*scale)+"px;'
        f'background:"+col+";opacity:"+(1-i/n*0.8)+";transform:translate(-50%,-50%);'
        f'top:-999px;left:-999px;";'
        f'wrap.appendChild(d);dots.push(d);pts.push([-999,-999]);'
        f'}}'
        f'var mx=-999,my=-999;'
        f'wrap.addEventListener("mousemove",function(e){{'
        f'var r=wrap.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top;active=true;}});'
        f'wrap.addEventListener("mouseleave",function(){{active=false;}});'
        f'(function loop(){{'
        f'if(active){{'
        f'pts[0][0]+=(mx-pts[0][0])*s;pts[0][1]+=(my-pts[0][1])*s;'
        f'for(var j=1;j<n;j++){{'
        f'pts[j][0]+=(pts[j-1][0]-pts[j][0])*s;pts[j][1]+=(pts[j-1][1]-pts[j][1])*s;}}'
        f'for(var k=0;k<n;k++){{'
        f'dots[k].style.left=Math.round(pts[k][0])+"px";dots[k].style.top=Math.round(pts[k][1])+"px";}}}}'
        f'requestAnimationFrame(loop);}})();}})();</script>'
    )

_RENDERERS["cursor_trail"] = _render_cursor_trail


def _render_particle_burst(b: dict) -> str:
    import hashlib
    uid     = hashlib.md5(str(b).encode()).hexdigest()[:6]
    count   = int(b.get("count", 14))
    colours = b.get("colours", b.get("colors")) or ["#4f46e5","#a855f7","#ec4899","#f59e0b","#34d399"]
    size    = int(b.get("size", 8))
    dur     = int(b.get("duration", 700))
    gravity = float(b.get("gravity", 1.2))
    cols_js = _js_json([c for c in colours if isinstance(c, str) and _gd_css(c)] if isinstance(colours, list) else []) if colours else '[]'
    return (
        f'<script>(function(){{'
        f'var cols={cols_js},n={count},sz={size},dur={dur},g={gravity};'
        f'document.addEventListener("click",function(e){{'
        f'for(var i=0;i<n;i++){{'
        f'var el=document.createElement("div");'
        f'el.style.cssText="position:fixed;width:"+sz+"px;height:"+sz+"px;border-radius:50%;'
        f'pointer-events:none;z-index:9999;background:"+cols[i%cols.length]'
        f'+";left:"+e.clientX+"px;top:"+e.clientY+"px;";'
        f'document.body.appendChild(el);'
        f'var vx=(Math.random()-0.5)*12;var vy=-(Math.random()*10+3);'
        f'var t=0;var x=e.clientX;var y=e.clientY;'
        f'var id=setInterval(function(elem,cx,cy,dx,dy){{'
        f'dy+=g*0.5;cx+=dx;cy+=dy;'
        f'elem.style.left=cx+"px";elem.style.top=cy+"px";'
        f'elem.style.opacity=Math.max(0,1-t/dur);'
        f't+=16;if(t>dur){{clearInterval(id);elem.remove();}}'
        f'}}.bind(null,el,x,y,vx,vy),16);'
        f'}}}});}})()</script>'
    )

_RENDERERS["particle_burst"] = _render_particle_burst


def _render_spotlight_cursor(b: dict) -> str:
    import hashlib
    uid      = hashlib.md5(str(b).encode()).hexdigest()[:6]
    radius   = int(b.get("radius", 180))
    darkness = float(b.get("darkness", 0.82))
    color    = b.get("colour", b.get("color", "rgba(0,0,0)"))
