def _render_split_stat(b: dict) -> str:
    # Keynote-style glowing stat card with flip orientation support
    val_loose = _text_loose(b.get('value'))
    value = val_loose if val_loose else '—'
    prefix = _text_loose(b.get('prefix'))
    suffix = _text_loose(b.get('suffix'))
    heading = _text_loose(b.get('heading'))
    body = _text_loose(b.get('body'))
    raw_col = _first_text(b.get('colour'), b.get('color'))
    colour = _safe_css(raw_col, '#4f46e5')
    flip = b.get('flip') is True

    prefix_html = f'<span style="font-size:0.45em;opacity:0.7;vertical-align:0.55em;">{_cv_esc(prefix)}</span>' if prefix else ''
    suffix_html = f'<span style="font-size:0.4em;opacity:0.7;vertical-align:0.6em;margin-left:2px;">{_cv_esc(suffix)}</span>' if suffix else ''

    stat_col = (
        f'<div style="flex:0 0 auto;text-align:center;padding:0 24px;">'
        f'<div style="font-size:clamp(3rem,8vw,5rem);font-weight:900;line-height:1;color:#fff;'
        f'text-shadow:0 0 20px {colour},0 0 60px color-mix(in srgb, {colour} 33%, transparent);">'
        f'{prefix_html}{_cv_esc(value)}{suffix_html}</div>'
        f'<div style="width:60px;height:3px;margin:10px auto 0;border-radius:99px;'
        f'background:{colour};box-shadow:0 0 16px {colour};"></div>'
        f'</div>'
    )

    border_side = 'border-right:1px solid rgba(255,255,255,0.08);' if flip else 'border-left:1px solid rgba(255,255,255,0.08);'
    heading_html = f'<div style="font-size:1.1rem;font-weight:800;color:#f1f5f9;margin-bottom:8px;">{_cv_esc(heading)}</div>' if heading else ''
    body_html = f'<div style="font-size:0.88rem;color:#94a3b8;line-height:1.65;">{_md_inline(body)}</div>' if body else ''

    text_col = (
        f'<div style="flex:1;min-width:0;padding:0 8px;{border_side}">'
        f'{heading_html}{body_html}</div>'
    )

    left = text_col if flip else stat_col
    right = stat_col if flip else text_col

    return (
        f'<div data-cb="node" data-key="{_ck(b.get("heading"), "split_stat")}" style="display:flex;align-items:center;gap:24px;padding:28px;'
        f'margin:1.5rem 0;border:1px solid #1e293b;border-radius:14px;background:#0f172a;">'
        f'{left}{right}</div>'
    )

_RENDERERS["split_stat"] = _render_split_stat


def _render_section_label(b: dict) -> str:
    import html as _html
    text   = _html.escape(b.get("text", "")).upper()
    color  = b.get("colour", b.get("color", "var(--a2ui-accent,#4f46e5)"))
    margin = b.get("margin", "24px 0 12px")
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("text"), "section_label")}" style="display:inline-flex;align-items:center;gap:8px;margin:{_cv_esc(margin)};">'
        f'<span style="display:inline-block;width:8px;height:8px;border-radius:50%;'
        f'background:{_cv_esc(color)};box-shadow:0 0 8px {_cv_esc(color)};"></span>'
        f'<span style="font-size:0.72rem;font-weight:700;letter-spacing:0.12em;'
        f'text-transform:uppercase;color:{_cv_esc(color)};">{text}</span>'
        f'</div>'
    )

_RENDERERS["section_label"] = _render_section_label


def _sanitize_mathml(raw: str) -> str:
    """Defense-in-depth strip of active content from agent-authored MathML.
    MathML can embed HTML via <annotation-xml encoding="text/html"> and carry
    event handlers, so remove scripts, annotation-xml, on*= handlers and
    javascript: URLs before the markup is passed through unescaped."""
    import re
    raw = re.sub(r'(?is)<script.*?</script>', '', raw)
    raw = re.sub(r'(?is)<annotation-xml.*?</annotation-xml>', '', raw)
    raw = re.sub(r'(?i)\son\w+\s*=\s*"[^"]*"', '', raw)
    raw = re.sub(r"(?i)\son\w+\s*=\s*'[^']*'", '', raw)
    raw = re.sub(r'(?i)\son\w+\s*=\s*[^\s>]+', '', raw)
    raw = re.sub(r'(?i)javascript:', '', raw)
    return raw


def _render_math_block(b: dict) -> str:
    """Native MathML equation, typeset with `font-family: math` (STIX/Latin
    Modern Math) — no JS, no external library. The agent emits standard
    MathML; the surface draws it. Works on every surface with a MathML engine
    (all modern browsers, Baseline since 2023)."""
    import html as _html
    mathml = _sanitize_mathml(b.get("mathml", "") or "")
    if "<math" not in mathml.lower():
        mathml = '<math display="block">' + mathml + '</math>'
    caption = _html.escape(b.get("caption", ""))
    number = _html.escape(b.get("number", ""))
    align = "left" if b.get("align") == "left" else "center"
    size = _html.escape(str(b.get("size", "clamp(1.1rem,2.5vw,1.6rem)")))
    num_html = (
        f'<span style="position:absolute;right:0;top:50%;transform:translateY(-50%);'
        f'font-size:0.9rem;color:var(--text-muted,#6b7280);font-family:ui-monospace,monospace;">'
        f'{number}</span>'
    ) if number else ""
    cap_html = (
        f'<div style="margin-top:8px;font-size:0.82rem;color:var(--text-muted,#6b7280);'
        f'text-align:{align};line-height:1.5;">{caption}</div>'
    ) if caption else ""
    return (
        f'<div data-cb="node" data-key="{_ck(b.get("caption"), "math_block")}" class="a2ui-math" style="margin:1.5rem 0;position:relative;">'
        f'<div style="text-align:{align};font-family:math,\'Latin Modern Math\',\'STIX Two Math\',serif;'
        f'font-size:{size};color:var(--text,#1f2937);overflow-x:auto;">{mathml}</div>'
        f'{num_html}{cap_html}</div>'
    )

_RENDERERS["math_block"] = _render_math_block


def _render_text_highlight(b: dict) -> str:
    import re, html as _html
    text   = b.get("text", "")
    size   = b.get("size", "1.2rem")
    color  = b.get("colour", b.get("color", "var(--a2ui-accent,#4f46e5)"))
    weight = b.get("weight", 600)
    align  = b.get("align", "left")
    def _replace(m):
        word = _html.escape(m.group(1))
        return (
            f'<mark style="background:transparent;color:{color};font-weight:700;'
            f'border-bottom:2px solid {color};">{word}</mark>'
        )
    processed = re.sub(r'\*\*(.+?)\*\*', _replace, _html.escape(text).replace(r'\*\*', '**'))
    return (
        f'<p data-cb="node" data-key="{_ck(b.get("text"), "text_highlight")}" style="font-size:{_cv_esc(size)};font-weight:{_cv_esc(weight)};color:var(--text,#e2e8f0);'
        f'line-height:1.7;text-align:{_cv_esc(align)};margin:1rem 0;">{processed}</p>'
    )

_RENDERERS["text_highlight"] = _render_text_highlight


