# ─── palette ──────────────────────────────────────────────────────────────────
# Design tokens: report-cluster renderers read var(--a2ui-<token>,<historical value>);
# `palette` sets them. Names/fields/presets/whitelist are GENERATED from
# atoms/design-tokens.yaml (scripts/gen_design_tokens.py) into _design_tokens.py
# and the GAS twin atoms_tokens.gs -- edit the YAML, never a copy.
def _load_design_tokens():
    # Loaded by file path, not `from renderers._design_tokens import ...`: this
    # module is imported both as `renderers.web_article` and as bare top-level
    # `web_article` (generate_atom_pages.py, cloud-run-renderer), and only the
    # first can resolve a package-qualified import. Same reason as qrcodegen.
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "_a2ui_design_tokens", Path(__file__).resolve().parent / "_design_tokens.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.token_css, module.CHROME_STYLES

_token_css, _CHROME_STYLES = _load_design_tokens()


def _card_chrome(inner_html: str, recipe: str, extra_style: str = "") -> str:
    """Wrap `inner_html` in a <div style="..."> using a CLOSED-ENUM chrome recipe (see
    atoms/design-tokens.yaml `recipes:`). No override parameter FOR CHROME PROPERTIES,
    deliberately: a call site picks a named recipe, never patches radius/border/background/
    shadow individually -- reviewed 2026-09-26, chrome-helper-draft.md. `extra_style` is a
    DIFFERENT axis: plain, component-owned layout (padding, display, min-width, ...) that was
    never meant to be shared across atoms in the first place; it can never touch a chrome
    property because CHROME_STYLES is appended last and wins the cascade on any clash.
    CHROME_STYLES is GENERATED DATA (ready CSS strings, double-declaration pattern), not a
    generated function -- the Python/GAS twin (_cardChrome in atom.gs) is hand-written once
    per language against that same data, since a generated function risks silent drift
    between the two languages' string/default-arg semantics that a generated constant
    doesn't have."""
    return f'<div style="{extra_style}{_CHROME_STYLES[recipe]}">{inner_html}</div>'

_MOTION_PRESETS = {
    'calm': {'duration': 1.3, 'intensity': 0.6, 'stagger': 1.25},
    'standard': {'duration': 1, 'intensity': 1, 'stagger': 1},
    'expressive': {'duration': 1.1, 'intensity': 1.5, 'stagger': 1.3},
}
_MOTION_RM_RULES = '@keyframes a2ui-rm-in{from{opacity:0}}@keyframes a2ui-rm-out{to{opacity:0}}@media (prefers-reduced-motion:reduce){:root .mo-x{animation:a2ui-rm-in calc(200ms * var(--a2ui-motion-duration-scale,1)) ease both!important}:root .mo-leave[data-mo-exit]{animation:a2ui-rm-out var(--mo-exit-dur,200ms) ease both!important}:root [data-a2ui-menu] details[open]>[role=menu]{animation:a2ui-rm-in calc(160ms * var(--a2ui-motion-duration-scale,1)) ease both!important}}'


def _motion_policy_var(b: dict) -> str:
    return '--a2ui-reduced-motion:fade;' if b.get('reduced_motion') == 'fade' else ''


def _motion_policy_rules(b: dict) -> str:
    return _MOTION_RM_RULES if b.get('reduced_motion') == 'fade' else ''


def _motion_scale_css(b: dict) -> str:
    """Motion policy v0: see _motionScaleCss in atom.gs (the byte-for-byte twin)."""
    out = ''
    pre = _MOTION_PRESETS.get(b.get('motion_preset')) if isinstance(b.get('motion_preset'), str) else None
    for field, name, lo, hi in (('duration_scale', 'duration', 0.25, 3), ('intensity_scale', 'intensity', 0, 2),
                                ('stagger_scale', 'stagger', 0, 3)):
        v = b.get(field)
        if isinstance(v, str) and re.match(r'^[0-9]+(\.[0-9]+)?$', v.strip()):
            v = float(v.strip())
        if (isinstance(v, bool) or not isinstance(v, (int, float)) or v != v or abs(v) == float('inf')) and pre:
            v = pre[name]
        if isinstance(v, bool) or not isinstance(v, (int, float)) or v != v or abs(v) == float('inf'):
            continue
        n = int(min(hi, max(lo, v)) * 100 + 0.5)
        whole, frac = n // 100, n % 100
        txt = str(whole) + (('.' + ('0' if frac < 10 else '') + str(frac).rstrip('0')) if frac else '')
        out += '--a2ui-motion-' + name + '-scale:' + txt + ';'
    return out


def _render_palette(b: dict) -> str:
    accent  = b.get("accent", "#4f46e5")
    accent2 = b.get("accent2", b.get("accent", "#8b5cf6"))
    gap     = b.get("block_gap", "1.25rem")
    extra   = ""
    if b.get("text_color"): extra += f"--text:{_cv_esc(b['text_color'])};"
    if b.get("bg_color"):   extra += f"--bg:{_cv_esc(b['bg_color'])};"
    if b.get("muted_color"):extra += f"--muted:{_cv_esc(b['muted_color'])};"
    extra += _token_css(b)
    extra += _motion_scale_css(b)
    extra += _motion_policy_var(b)
    return f"<style>:root{{--a2ui-accent:{_cv_esc(accent)};--a2ui-accent2:{_cv_esc(accent2)};--a2ui-block-gap:{_cv_esc(gap)};{extra}}}{_motion_policy_rules(b)}</style>"

_RENDERERS["palette"] = _render_palette


# ─── drive_image ──────────────────────────────────────────────────────────────
def _render_drive_image(b: dict) -> str:
    import re, urllib.parse
    raw = b.get("url") or b.get("id") or ""
    m = re.search(r"/d/([a-zA-Z0-9_-]+)", raw)
    file_id = m.group(1) if m else raw
    src = f"https://drive.google.com/uc?id={urllib.parse.quote(file_id)}&export=view"
    alt = b.get("alt") or b.get("caption") or ""
    caption_html = f'<figcaption style="font-size:0.82rem;color:var(--muted,#5f6368);margin-top:8px;font-style:italic;">{_cv_esc(b["caption"])}</figcaption>' if b.get("caption") else ""
    radius = "border-radius:8px;" if b.get("rounded", True) else ""
    w = f"width:{_cv_esc(b['width'])};" if b.get("width") else "max-width:100%;"
    return f'<figure data-cb="node" data-key="{_ck(b.get("id"), "drive_image")}" style="margin:1.2rem 0;text-align:center;"><img src="{src}" alt="{_cv_esc(alt)}" style="{w}{radius}display:block;margin:0 auto;" loading="lazy">{caption_html}</figure>'

_RENDERERS["drive_image"] = _render_drive_image


# ─── print_button ─────────────────────────────────────────────────────────────
def _render_print_button(b: dict) -> str:
    label  = b.get("label", "Print this page")
    align  = b.get("align", "left")
    accent = b.get("accent", "var(--a2ui-accent,#4f46e5)")
    size   = {"sm": "0.8rem", "lg": "1rem"}.get(b.get("size", "md"), "0.875rem")
    icon   = "🖨️ " if b.get("icon", True) else ""
    return (f'<div style="margin:var(--a2ui-block-gap,1.25rem) 0;text-align:{_cv_esc(align)};">'
            f'<button onclick="window.print()" style="background:{_cv_esc(accent)};color:#fff;border:none;border-radius:8px;padding:10px 20px;font-size:{size};font-weight:600;cursor:pointer;">'
            f'{icon}{_cv_esc(label)}</button></div>')

_RENDERERS["print_button"] = _render_print_button


# ─── maps_embed ───────────────────────────────────────────────────────────────
def _render_maps_embed(b: dict) -> str:
    import urllib.parse
    q       = b.get("q") or b.get("query") or b.get("location") or ""
    height  = str(b.get("height", 360))
    zoom    = str(b.get("zoom", 14))
    caption = b.get("caption", "")
    src     = f"https://maps.google.com/maps?q={urllib.parse.quote(q)}&output=embed&z={_cv_esc(zoom)}"
    cap_html = f'<figcaption style="font-size:0.82rem;color:var(--muted,#5f6368);margin-top:6px;">{_cv_esc(caption)}</figcaption>' if caption else ""
    return (f'<figure style="margin:var(--a2ui-block-gap,1.25rem) 0;">'
            f'<iframe src="{src}" width="100%" height="{_cv_esc(height)}" style="border:0;border-radius:10px;display:block;" allowfullscreen loading="lazy" referrerpolicy="no-referrer-when-downgrade" title="{_cv_esc(q)}"></iframe>'
            f'{cap_html}</figure>')

_RENDERERS["maps_embed"] = _render_maps_embed


# ─── sheet_form ───────────────────────────────────────────────────────────────
# In the web/PDF renderer context there's no google.script.run — render a static note.
def _render_sheet_form(b: dict) -> str:
    title = b.get("title", "Form")
    fields = b.get("fields", [])
    req_star = '&nbsp;<span style="color:#ef4444">*</span>'
    field_rows = "".join(
        '<div style="margin-bottom:10px;font-size:0.85rem;"><strong>' + _cv_esc(f.get("label", "")) + '</strong>'
        + (req_star if f.get("required") else "")
        + '<div style="padding:6px 10px;border:1px solid #e5e7eb;border-radius:6px;color:var(--muted,#5f6368);margin-top:4px;">'
        + _cv_esc(f.get("placeholder", "")) + '&nbsp;</div></div>'
        for f in fields
    )
    note = '<div style="margin-top:12px;font-size:0.78rem;color:var(--muted,#5f6368);font-style:italic;">⚠ sheet_form requires Google Apps Script — form submission not available in this renderer.</div>'
    title_div = '<div style="font-weight:700;margin-bottom:14px;">' + _cv_esc(title) + "</div>" if title else ""
    return ('<div style="margin:var(--a2ui-block-gap,1.25rem) 0;padding:20px;border:1px solid #e5e7eb;border-radius:10px;">'
            + title_div + field_rows + note + '</div>')

_RENDERERS["sheet_form"] = _render_sheet_form


# ─── Material Symbol icon atoms ───────────────────────────────────────────────
_MS_CSS_OUTLINED = (
    '<style>'
    '@import url("https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined'
    ':opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200");'
    '.ms-icon{font-family:"Material Symbols Outlined";font-weight:normal;font-style:normal;'
    'font-size:inherit;line-height:1;display:inline-block;text-transform:none;'
    'letter-spacing:normal;word-wrap:normal;white-space:nowrap;direction:ltr;'
    '-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;'
    "font-variation-settings:'FILL' var(--ms-fill,0),'wght' var(--ms-w,400),"
    "'GRAD' var(--ms-g,0),'opsz' var(--ms-o,24);}"
    '</style>'
)
_MS_CSS_ROUNDED = (
    '<style>'
    '@import url("https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded'
    ':opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200");'
    '.ms-icon{font-family:"Material Symbols Rounded";font-weight:normal;font-style:normal;'
    'font-size:inherit;line-height:1;display:inline-block;text-transform:none;'
    'letter-spacing:normal;word-wrap:normal;white-space:nowrap;direction:ltr;'
    '-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;'
    "font-variation-settings:'FILL' var(--ms-fill,0),'wght' var(--ms-w,400),"
    "'GRAD' var(--ms-g,0),'opsz' var(--ms-o,24);}"
    '</style>'
)

def _ms_font(style: str) -> str:
    return _MS_CSS_ROUNDED if style == "rounded" else _MS_CSS_OUTLINED

def _ms_vars(fill: int, weight: int, grade: int, opsz: int) -> str:
    return f"--ms-fill:{fill};--ms-w:{weight};--ms-g:{grade};--ms-o:{opsz}"


def _render_google_icon(b: dict) -> str:
    import html as _h
    name   = _h.escape(str(b.get("name") or b.get("icon") or "star"))
    size   = _h.escape(str(b.get("size") or "24px"))
    color  = b.get("color") or b.get("accent") or "currentColor"
    fill   = 1 if b.get("filled") else 0
    weight = int(b.get("weight") or 400)
    opsz   = int((b.get("size") or "24").replace("px","").strip() or 24)
    style  = b.get("style") or "outlined"
    inline = b.get("inline", True) is not False
    label  = f'<span style="font-size:0.82rem;color:var(--muted,#6b7280);margin-left:6px;">{_h.escape(str(b["label"]))}</span>' if b.get("label") else ""
    css_vars = _ms_vars(fill, weight, 0, opsz)
    icon_span = f'<span class="ms-icon" style="{css_vars};font-size:{size};color:{_cv_esc(color)};" aria-hidden="true">{name}</span>'
    disp = "inline-flex" if inline else "flex"
    margin = "" if inline else "margin:var(--a2ui-block-gap,1.25rem) 0;"
    return _ms_font(style) + f'<span data-cb="node" data-key="{_ck(b.get("name"), "google_icon")}" style="display:{disp};align-items:center;{margin}">{icon_span}{label}</span>'

_RENDERERS["google_icon"] = _render_google_icon


def _render_icon_badge(b: dict) -> str:
    import html as _h
    name   = _h.escape(str(b.get("name") or b.get("icon") or "star"))
    size   = int(b.get("icon_size") or 24)
    bg     = b.get("bg") or b.get("accent") or "var(--a2ui-accent,#4f46e5)"
    color  = b.get("color") or "#fff"
    pad    = _h.escape(str(b.get("padding") or "12px"))
    radius = _h.escape(str(b.get("radius") or "50%"))
    fill   = 1 if b.get("filled") else 0
    weight = int(b.get("weight") or 400)
    style  = b.get("style") or "outlined"
    label  = f'<div style="font-size:0.78rem;color:var(--muted,#6b7280);margin-top:4px;text-align:center;">{_h.escape(str(b["label"]))}</div>' if b.get("label") else ""
    css_vars = _ms_vars(fill, weight, 0, size)
    return (
        _ms_font(style)
        + '<div data-cb="node" data-key="' f'{_ck(b.get("name"), "icon_badge")}' '" style="display:inline-flex;flex-direction:column;align-items:center;text-align:center;margin:var(--a2ui-block-gap,1.25rem) 0;">'
        + f'<div style="display:flex;align-items:center;justify-content:center;background:{_cv_esc(bg)};padding:{pad};border-radius:{radius};">'
        + f'<span class="ms-icon" style="{css_vars};font-size:{size}px;color:{_cv_esc(color)};" aria-hidden="true">{name}</span>'
        + f'</div>{label}</div>'
    )

_RENDERERS["icon_badge"] = _render_icon_badge


def _render_icon_row(b: dict) -> str:
    import html as _h
    items   = b.get("items") or []
    size    = int(b.get("icon_size") or 20)
    color   = b.get("color") or b.get("accent") or "var(--a2ui-accent,#4f46e5)"
    fill    = 1 if b.get("filled") else 0
    style   = b.get("style") or "outlined"
    gap     = _h.escape(str(b.get("gap") or "12px"))
    css_base = _ms_vars(fill, 400, 0, size)
    cells = "".join(
        f'<div data-cb="node" data-key="{_cv_esc(str(item.get("name") or item.get("label") or item.get("text") or item.get("icon") or ""))}" style="display:flex;align-items:center;gap:8px;">'
        + f'<span class="ms-icon" style="{css_base};font-size:{size}px;color:{_cv_esc(item.get("color") or item.get("accent") or color)};flex-shrink:0;" aria-hidden="true">{_h.escape(str(item.get("name") or item.get("icon") or "check"))}</span>'
        + (f'<span data-cb="label" data-key="{_cv_esc(str(item.get("name") or item.get("label") or item.get("text") or item.get("icon") or ""))}" style="font-size:0.875rem;color:var(--text,#374151);">{_h.escape(str(item.get("label") or item.get("text") or ""))}</span>' if item.get("label") or item.get("text") else "")
        + '</div>'
        for item in items
    )
    return _ms_font(style) + f'<div style="display:flex;flex-wrap:wrap;gap:{gap};margin:var(--a2ui-block-gap,1.25rem) 0;">{cells}</div>'

