def _render_trend_indicator(b: dict) -> str:
    d = b.get("trend_direction") or b.get("direction", "stable")
    label = b.get("label", "")
    ctx = b.get("context", "")
    cfg = {"up": ("↑","#0b7a55","#d1fae5"), "down": ("↓","#ef4444","#fee2e2"), "stable": ("→","#6b7280","#f3f4f6")}.get(d, ("→","#6b7280","#f3f4f6"))
    col = b.get("color", cfg[1])
