def _render_changelog_entry(b: dict) -> str:
    version = b.get('version', '')
    date = b.get('date', '')
    changes = b.get('changes', [])
    type_map = {'added':('#10b981','Added'),'changed':('#3b82f6','Changed'),'fixed':('#f59e0b','Fixed'),'removed':('#ef4444','Removed')}
    header = f'<div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;">'
    header += f'<span style="font-weight:800;font-size:1.1rem;color:#111827;">{_esc(version)}</span>'
    if date:
        header += f'<span style="font-size:0.82rem;color:var(--muted,#5f6368);">{_esc(date)}</span>'
    header += '</div>'
    groups: dict = {}
    for c in changes:
        t = c.get('type', 'changed') if isinstance(c, dict) else 'changed'
        txt = c.get('text', str(c)) if isinstance(c, dict) else str(c)
        groups.setdefault(t, []).append(txt)
    body = ''
    for t, txts in groups.items():
        col, lbl = type_map.get(t, ('#6b7280', t.title()))
        body += f'<div style="margin-bottom:8px;"><span style="display:inline-block;padding:1px 8px;border-radius:4px;background:{col}22;color:{_dk(col)};font-size:0.72rem;font-weight:700;text-transform:uppercase;margin-bottom:4px;">{lbl}</span>'
        body += '<ul style="margin:0;padding-left:18px;">' + ''.join(f'<li style="font-size:0.85rem;color:#374151;">{_md_inline(txt)}</li>' for txt in txts) + '</ul></div>'
    return (f'<div data-cb="node" data-key="{_ck(b.get("version"), "changelog_entry")}" style="border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:16px 20px;margin:1.2rem 0;">'
            f'{header}{body}</div>')

_RENDERERS['changelog_entry'] = _render_changelog_entry


def _render_checklist_interactive(b: dict) -> str:
    uid = _wa_uid(b)
    items = b.get('items', [])
    rows = ''
    for i, item in enumerate(items):
        # Object-shaped items can use either key (GAS already reads item.text||item.label);
        # only checking 'text' dropped 'label'-shaped items entirely (surface-parity debt).
        # 2026-09-27.
        text = item if isinstance(item, str) else (item.get('text') or item.get('label') or '')
        checked = '' if isinstance(item, str) else ('checked' if item.get('checked') else '')
        k = _esc(item.get('id') if isinstance(item, dict) else '') or _esc(text)
        rows += (f'<label data-cb="item" data-key="{k}" style="display:flex;align-items:flex-start;gap:10px;padding:8px 4px;cursor:pointer;">'
                 f'<input type="checkbox" {checked} style="margin-top:2px;accent-color:#4f46e5;">'
                 f'<span data-cb="label" data-key="{k}" style="font-size:0.88rem;color:#374151;">{_md_inline(text)}</span></label>')
    title_html = f'<div style="font-weight:700;margin-bottom:8px;">{_esc(b["title"])}</div>' if b.get('title') else ''
    return f'<div style="border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:12px 16px;margin:1rem 0;">{title_html}{rows}</div>'

_RENDERERS['checklist_interactive'] = _render_checklist_interactive


def _render_chip_group(b: dict) -> str:
    # Static filter/tag chips matching GAS look; supports safe links and wrap/scroll layouts.
    label_txt = _first_text(b.get('label'))
    scroll = _first_text(b.get('layout')) == 'scroll'
    same_tab = b.get('same_tab') is True
    target = '_top' if same_tab else '_blank'

    raw_chips = b.get('chips') if isinstance(b.get('chips'), list) else []
    chips_html = []
    for c in raw_chips[:100]:
        if isinstance(c, dict):
            c_label = _first_text(c.get('label'), c.get('text'))
            c_color = _first_text(c.get('color'))
            c_url = _first_text(c.get('url'))
            c_active = c.get('active') is True
        elif (isinstance(c, str) or (isinstance(c, (int, float)) and not isinstance(c, bool))):
            c_label = _text_loose(c)
            c_color = ''
            c_url = ''
            c_active = False
        else:
            continue

        safe_color = _safe_css(c_color, '')
        if c_active:
            bg = safe_color if safe_color else '#4f46e5'
            tc = '#fff'
        else:
            if safe_color.startswith('#') and len(safe_color) == 7:
                bg = safe_color + '18'
            else:
                bg = '#f3f4f6'
            tc = safe_color if safe_color else '#374151'

        safe_link = _safe_href(c_url, schemes=('https', 'mailto'))
        escaped_label = _cv_esc(c_label)
        ck_val = _ck(c_label, '')
        style = f'display:inline-flex;align-items:center;background:{bg};color:{tc};border-radius:99px;padding:4px 14px;font-size:12px;font-weight:500;text-decoration:none;white-space:nowrap;cursor:{"pointer" if safe_link else "default"};'

        if safe_link:
            curr_attr = ' aria-current="true"' if c_active else ''
            chips_html.append(f'<a href="{_cv_esc(safe_link)}" target="{target}" rel="noopener" data-cb="item" data-key="{ck_val}"{curr_attr} style="{style}">{escaped_label}</a>')
        else:
            chips_html.append(f'<span data-cb="item" data-key="{ck_val}" style="{style}">{escaped_label}</span>')

    wrap = 'display:flex;flex-wrap:nowrap;overflow-x:auto;gap:8px;padding-bottom:4px;scrollbar-width:none;' if scroll else 'display:flex;flex-wrap:wrap;gap:8px;'
    heading_html = f'<div style="font-size:12px;font-weight:600;color:var(--muted,#6b7280);margin-bottom:6px;">{_cv_esc(label_txt)}</div>' if label_txt else ''
    aria_attr = f' role="group" aria-label="{_cv_esc(label_txt)}"' if label_txt else ''
    return f'{heading_html}<div{aria_attr} style="{wrap}margin:0.75rem 0;">{"".join(chips_html)}</div>'

_RENDERERS['chip_group'] = _render_chip_group


