def _render_color_swatch_grid(b: dict) -> str:
    colors = b.get('colors', [])
    cols = b.get('cols', 4)
    swatches = ''
    for c in colors:
        if isinstance(c, str):
            hex_val, name = c, c
        else:
            hex_val = c.get('hex') or c.get('color', '#ccc')
            name = c.get('name', hex_val)
        swatches += (f'<div data-cb="item" data-key="{_esc(hex_val)}" style="text-align:center;">'
                     f'<div style="width:100%;aspect-ratio:1;border-radius:12px;border-radius:var(--a2ui-radius,12px);background:{_esc(hex_val)};'
                     f'border:1px solid #00000015;margin-bottom:4px;"></div>'
                     f'<div data-cb="label" data-key="{_esc(hex_val)}" style="font-size:0.72rem;color:#374151;font-weight:600;">{_esc(name)}</div>'
                     f'<div style="font-family:monospace;font-size:0.68rem;color:var(--muted,#5f6368);">{_esc(hex_val)}</div></div>')
    return (f'<div style="display:grid;grid-template-columns:repeat({_cv_esc(cols)},1fr);gap:12px;margin:1.5rem 0;">'
            f'{swatches}</div>')

_RENDERERS['color_swatch_grid'] = _render_color_swatch_grid

# NOTE: a second _render_columns used to be defined here, reading b.get('columns', [])
# for the content array instead of 'items' -- disagreeing with atoms/schema.yaml (items,
# required), the GAS ground-truth renderer (atom.gs:4021, b.items), AND the ORIGINAL
# _render_columns at line ~2086 in this same file (which already read 'items' correctly).
# Python silently let the second definition win by rebinding the name, so real payloads
# (which correctly send 'items' per the schema) rendered a valid-looking but EMPTY
# columns container -- no error, no fallback-to-unknown, nothing to signal the mismatch.
# Removed 2026-09-16 (Curtis, live-site bug report) rather than fixed in place: the
# original definition at line ~2086 was already correct AND more complete (respects
# cols/align, which this duplicate ignored entirely), so there was nothing worth keeping
# from this version. See ROAST-2026-05-03.md-style incident writeups' own convention for
# the class of bug this is: a recognized atom type failing silently, not routing through
# _render_unknown, so nothing in the render pipeline itself could have caught it.

# ── NEW WEB RENDERERS — Batch 2 (comparison_table → faq_accordion, ~36 atoms) ─

def _render_comparison_table(b: dict) -> str:
    rows = b.get('rows', [])
    cols = b.get('columns', [])
    title = b.get('title', '')
    highlight = b.get('highlight_col', None)
    ths = ''.join(f'<th style="padding:10px 14px;text-align:center;background:#f9fafb;font-size:0.82rem;'
                  f'font-weight:700;color:{"#7c3aed" if i==highlight else "#374151"};'
                  f'border-bottom:1px solid #e5e7eb;">{_esc(c)}</th>'
                  for i, c in enumerate(['Feature'] + cols))
    body = ''
    for i, row in enumerate(rows):
        cells = ''.join(
            f'<td style="padding:9px 14px;text-align:center;font-size:0.84rem;'
            f'border-bottom:1px solid #f3f4f6;background:{"#faf5ff" if j-1==highlight else ""};">'
            f'{("✅" if v is True else "❌" if v is False else _esc(str(v)))}</td>'
            for j, v in enumerate([row.get('feature', '')] + [row.get(c, '—') for c in cols])
        )
        body += f'<tr style="background:{"#f9fafb" if i%2==0 else "#fff"};">{cells}</tr>'
    title_html = (f'<div style="padding:10px 16px;font-weight:700;border-bottom:1px solid #e5e7eb;">'
                  f'{_esc(title)}</div>' if title else '')
    return (f'<div style="border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin:1.5rem 0;">'
            f'{title_html}<div style="overflow-x:auto;">'
            f'<table style="width:100%;border-collapse:collapse;min-width:400px;">'
            f'<thead><tr>{ths}</tr></thead><tbody>{body}</tbody></table></div></div>')

_RENDERERS['comparison_table'] = _render_comparison_table


def _render_concept_map(b: dict) -> str:
    uid = _wa_uid(b)
    nodes = b.get('nodes', [])
    center = b.get('center', b.get('title', 'Core Concept'))
    accent = b.get('accent', '#4f46e5')
    items = ''
    n = len(nodes)
    for i, node in enumerate(nodes):
        label = node if isinstance(node, str) else node.get('label', str(node))
        deg = (360 / n * i) if n else 0
        rad = 3.14159 / 180 * deg
        x = 50 + 38 * 0.951056516 * (1 if deg < 180 else -1) * abs((deg % 180) / 90 - 1) * ((1 if deg < 90 or deg > 270 else -1))
        import math
        x2 = 50 + 38 * math.cos(math.radians(deg))
        y2 = 50 + 38 * math.sin(math.radians(deg))
        items += (f'<div style="position:absolute;left:{x2:.1f}%;top:{y2:.1f}%;transform:translate(-50%,-50%);'
                  f'background:#ffffff;background:var(--a2ui-surface,#ffffff);border:1.5px solid {_cv_esc(accent)};border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:5px 10px;'
                  f'font-size:0.75rem;font-weight:600;color:{_cv_esc(accent)};white-space:nowrap;">{_esc(label)}</div>')
    return (f'<div style="position:relative;width:100%;aspect-ratio:1;max-width:360px;margin:1.5rem auto;">'
            f'<div style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);'
            f'background:{_cv_esc(accent)};color:#fff;border-radius:12px;padding:10px 16px;font-weight:700;'
            f'font-size:0.9rem;text-align:center;">{_esc(center)}</div>'
            f'{items}</div>')

_RENDERERS['concept_map'] = _render_concept_map


def _render_contact_card(b: dict) -> str:
    name = b.get('name', '')
    role = b.get('role') or b.get('title', '')
    email = b.get('email', '')
    phone = b.get('phone', '')
    avatar = b.get('avatar') or b.get('image', '')
    initial = name[0].upper() if name else '?'
    av = (f'<img src="{_esc(avatar)}" alt="{_esc(name)}" style="width:56px;height:56px;border-radius:50%;object-fit:cover;">'
          if avatar else
          f'<div style="width:56px;height:56px;border-radius:50%;background:#e8f0fe;display:flex;'
          f'align-items:center;justify-content:center;font-weight:700;font-size:1.4rem;color:#1a73e8;">{_esc(initial)}</div>')
    rows = ''
    if email:
        rows += f'<div>📧 <a href="mailto:{_esc(email)}" style="color:#7c3aed;font-size:0.85rem;text-decoration:none;">{_esc(email)}</a></div>'
    if phone:
        rows += f'<div>📞 <span style="font-size:0.85rem;color:#374151;">{_esc(phone)}</span></div>'
    return (f'<div style="border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:16px 20px;'
            f'display:flex;gap:16px;align-items:center;margin:1rem 0;">'
            f'{av}<div>'
            f'<div style="font-weight:700;color:#111827;">{_esc(name)}</div>'
            f'{"<div style=font-size:0.82rem;color:var(--muted,#5f6368);margin-bottom:6px;>"+_esc(role)+"</div>" if role else ""}'
            f'{rows}</div></div>')

_RENDERERS['contact_card'] = _render_contact_card


def _render_copy_code_button(b: dict) -> str:
    # Schema's only declared field is `text_to_copy` -- a standalone copy button, not a
    # code block. This used to read the non-existent `code`/`language` (an older schema
    # shape) and never touched text_to_copy at all (surface-parity debt: GAS already
    # implements the current, minimal design). Kept `code` as a fallback for any payload
    # still sending the old shape. 2026-09-27.
    text = b.get('text_to_copy', b.get('code', ''))
    escaped = _cv_esc(_js_json(str(text)))
    return (f'<div style="display:inline-block;margin:0.5rem 0;">'
            f'<button onclick="navigator.clipboard.writeText({escaped})" '
            f'style="display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border:1px solid #d1d5db;'
            f'border-radius:6px;background:#f9fafb;cursor:pointer;font-size:0.82rem;color:#374151;">'
            f'<svg aria-hidden="true" width="14" height="14" viewBox="0 0 16 16" fill="currentColor">'
            f'<path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 '
            f'.138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 '
            f'16h-7.5A1.75 1.75 0 0 1 0 14.25Z"/><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 '
            f'.784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 '
            f'0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"/></svg>'
            f'Copy</button></div>')

_RENDERERS['copy_code_button'] = _render_copy_code_button


def _render_copy_to_clipboard(b: dict) -> str:
    text = b.get('text', '')
    label = b.get('label', 'Copy')
    uid = _wa_uid(b)
    import base64
    encoded = base64.b64encode(text.encode()).decode()
    return (f'<button onclick="navigator.clipboard.writeText(atob(\'{encoded}\'));this.textContent=\'✓\';'
            f'setTimeout(()=>this.textContent=\'{_esc(label)}\',2000)" '
            f'style="display:inline-flex;align-items:center;gap:6px;padding:6px 14px;background:#4f46e5;'
            f'color:#fff;border:none;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);font-size:0.84rem;font-weight:600;cursor:pointer;'
            f'font-family:inherit;">📋 {_esc(label)}</button>')

_RENDERERS['copy_to_clipboard'] = _render_copy_to_clipboard


