# NOTE: an inferior duplicate _render_numbered_list (plain <ol>, ignoring
# accent/style/title entirely) used to live here and shadow the real
# implementation at line ~1804 via re-registration below. Removed
# 2026-07-24 — the earlier, feature-complete definition (large ghost-number
# / badge / cards styles) is now the only one and wins by default.

# ── NEW WEB RENDERERS — Batch 4 (pagination → quiz_block, ~36 atoms) ───────────

def _render_pagination(b: dict) -> str:
    current = b.get('current', 1)
    total = b.get('total', 1)
    accent = b.get('accent', '#4f46e5')
    def page_btn(n, label=None, disabled=False):
        lbl = label or str(n)
        active = n == current
        style = (f'display:inline-flex;align-items:center;justify-content:center;'
                 f'min-width:32px;height:32px;padding:0 10px;border-radius:6px;font-size:0.82rem;'
                 f'{"background:"+accent+";color:#fff;font-weight:700;" if active else "background:#f9fafb;color:#374151;"}'
                 f'{"opacity:0.4;cursor:default;" if disabled else "cursor:pointer;"}'
                 f'border:1px solid #e5e7eb;')
        return f'<span style="{style}">{_esc(lbl)}</span>'
    pages = ''
    pages += page_btn(current - 1, '←', current <= 1)
    for i in range(1, total + 1):
        if i == 1 or i == total or abs(i - current) <= 2:
            pages += page_btn(i)
        elif abs(i - current) == 3:
            pages += '<span style="padding:0 4px;color:var(--muted,#5f6368);">…</span>'
    pages += page_btn(current + 1, '→', current >= total)
    return f'<div style="display:flex;gap:4px;justify-content:center;margin:1.5rem 0;flex-wrap:wrap;">{pages}</div>'

_RENDERERS['pagination'] = _render_pagination


def _render_parallax_card(b: dict) -> str:
    title = b.get('title') if isinstance(b.get('title'), str) and b.get('title') else ''
    raw_body = b.get('body') if isinstance(b.get('body'), str) and b.get('body') else (
        b.get('text') if isinstance(b.get('text'), str) and b.get('text') else (
            b.get('description') if isinstance(b.get('description'), str) and b.get('description') else (
                b.get('subtitle') if isinstance(b.get('subtitle'), str) and b.get('subtitle') else ''
            )
        )
    )
    badge = b.get('badge') if isinstance(b.get('badge'), str) and b.get('badge') else ''
    accent = _safe_css(b.get('accent'), '#4f46e5')
    bg = _safe_css(b.get('background'), '#0f172a')

    img = b.get('image', '')
    bg_css = bg
    if isinstance(img, str) and img and re.fullmatch(r'[A-Za-z0-9:/._~%?&=#+,@!$*-]+', img):
        if img.startswith('https://') or img.startswith('/'):
            bg_css = f'linear-gradient(rgba(0,0,0,0.4),rgba(0,0,0,0.4)),url({img}) center/cover,{bg}'

    height = b.get('height')
    min_height = ''
    if isinstance(height, str) and re.fullmatch(r'[0-9]{2,3}(\.[0-9]+)?(px|rem|em|vh)', height):
        min_height = f'min-height:{height};'

    depth_val = b.get('depth')
    if isinstance(depth_val, bool) or depth_val is None:
        depth = 15
    elif isinstance(depth_val, (int, float)):
        try:
            depth = 15 if (depth_val != depth_val or abs(depth_val) == float('inf')) else int(_gm.floor(depth_val + 0.5))
        except OverflowError:
            depth = 45 if depth_val > 0 else 0
    elif isinstance(depth_val, str) and re.fullmatch(r'[0-9]+', depth_val.strip()):
        depth = int(depth_val.strip())
    else:
        depth = 15
    if depth < 0:
        depth = 0
    elif depth > 45:
        depth = 45

    badge_html = f'<span style="display:inline-block;padding:2px 10px;border-radius:999px;background:{accent};color:#fff;font-size:0.7rem;font-weight:700;margin-bottom:10px;">{_cv_esc(badge)}</span>' if badge else ''
    title_html = f'<h3 style="margin:0 0 8px;font-size:1.4rem;">{_cv_esc(title)}</h3>' if title else ''
    body_html = f'<p style="margin:0;font-size:0.9rem;opacity:0.9;">{_md_inline(raw_body)}</p>' if raw_body else ''

    return (f'<div data-cb="node" data-key="{_ck(b.get("title"), "parallax_card")}" data-depth="{depth}" '
            f'onpointermove="var r=this.getBoundingClientRect(),d={depth},x=(event.clientX-r.left)/r.width-0.5,y=(event.clientY-r.top)/r.height-0.5;this.style.transform=\'perspective(800px) rotateX(\'+(-y*d).toFixed(1)+\'deg) rotateY(\'+(x*d).toFixed(1)+\'deg)\'" '
            f'onpointerleave="this.style.transform=\'\'" '
            f'style="position:relative;overflow:hidden;border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:28px;margin:1.5rem 0;color:#fff;background:{bg_css};{min_height}transition:transform 0.15s ease-out;will-change:transform;">'
            f'{badge_html}{title_html}{body_html}</div>')

_RENDERERS['parallax_card'] = _render_parallax_card


def _render_pdf_preview(b: dict) -> str:
    raw_pdf = b.get('pdf_url') if isinstance(b.get('pdf_url'), str) and b.get('pdf_url') else (b.get('url') if isinstance(b.get('url'), str) else '')
    pdf_url = _safe_href(raw_pdf, schemes=('https', 'mailto')) if raw_pdf else ''
    raw_thumb = b.get('thumbnail_url') if isinstance(b.get('thumbnail_url'), str) else ''
    thumb_url = _safe_href(raw_thumb, schemes=('https', 'mailto')) if raw_thumb else ''
    title = b.get('title') if isinstance(b.get('title'), str) and b.get('title') else 'PDF Document'
    alt_text = b.get('alt_text') if isinstance(b.get('alt_text'), str) and b.get('alt_text') else title

    if thumb_url:
        media_html = f'<img src="{_cv_esc(thumb_url)}" alt="{_cv_esc(alt_text)}" style="width:40px;height:48px;object-fit:cover;border-radius:4px;flex-shrink:0;" loading="lazy">'
    else:
        media_html = '<div style="width:40px;height:48px;background:#e71414;border-radius:4px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:0.7rem;font-weight:700;flex-shrink:0;">PDF</div>'

    sub_text = 'Click to open PDF' if pdf_url else 'No PDF URL provided'
    text_html = f'<div><div style="font-size:0.9rem;font-weight:600;color:#111827;">{_cv_esc(title)}</div><div style="font-size:0.75rem;color:var(--muted,#5f6368);margin-top:2px;">{sub_text}</div></div>'

    key = _ck(raw_pdf, 'pdf_preview')
    base_style = 'display:flex;align-items:center;gap:12px;padding:14px 16px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);text-decoration:none;margin:1rem 0;'

    if pdf_url:
        return f'<a data-cb="node" data-key="{key}" href="{_cv_esc(pdf_url)}" target="_blank" rel="noopener noreferrer" style="{base_style}">{media_html}{text_html}</a>'
    return f'<div data-cb="node" data-key="{key}" style="{base_style}">{media_html}{text_html}</div>'

_RENDERERS['pdf_preview'] = _render_pdf_preview


