def _render_repo_links(b: dict) -> str:
    links = [l for l in (b.get('links') or []) if isinstance(l, dict)]
    if not links and b.get('url'):
        links = [{'url': b['url'], 'label': b.get('label', 'Repository'), 'icon': '🐙'}]
    items = ''
    for link in links:
        url = link.get('url') or '#'
        # no label: show the URL without its scheme, so the link is never blank
        label = link.get('label') or link.get('text') or re.sub(r'/$', '', re.sub(r'^[a-zA-Z][a-zA-Z0-9+.-]*://', '', str(url)))
        icon = link.get('icon', '🐙')
        items += (f'<a href="{_esc(url)}" target="_blank" rel="noopener" '
                  f'style="display:inline-flex;align-items:center;gap:6px;padding:6px 14px;'
                  f'border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);text-decoration:none;color:#374151;'
                  f'font-size:0.84rem;background:#fafafa;background:var(--a2ui-surface-muted,#fafafa);margin:4px;">{_cv_esc(icon)} {_esc(label)}</a>')
    return f'<div style="margin:1rem 0;">{items}</div>'

_RENDERERS['repo_links'] = _render_repo_links


def _render_resources_list(b: dict) -> str:
    # Inventory list of downloadable assets or reference files with size and type tags.
    raw_items = b.get('items') if isinstance(b.get('items'), list) else []
    items = raw_items[:100]
    heading_title = _first_text(b.get('title')) or 'Resources'

    rows = []
    for item in items:
        if isinstance(item, dict):
            title = _first_text(item.get('title'), item.get('label'), item.get('name'))
            url = _first_text(item.get('url'))
            size = _first_text(item.get('size'))
            type_val = _first_text(item.get('type'))
            icon = _first_text(item.get('icon'))
        elif (isinstance(item, str) or (isinstance(item, (int, float)) and not isinstance(item, bool))):
            title = _text_loose(item)
            url = ''
            size = ''
            type_val = ''
            icon = ''
        else:
            continue

        safe_url = _safe_href(url, schemes=('https', 'mailto'))
        size_html = f'<span style="font-size:0.75rem;color:var(--muted,#6b7280);">{_cv_esc(size)}</span>' if size else ''
        type_html = f'<span style="font-size:0.72rem;background:var(--surface2,#e8f0fe);padding:2px 6px;border-radius:4px;color:var(--muted,#1558b4);">{_cv_esc(type_val.upper())}</span>' if type_val else ''
        icon_html = f'<span aria-hidden="true">{_cv_esc(icon)} </span>' if icon else ''

        meta_group = f'<div style="display:flex;align-items:center;gap:8px;">{size_html}{type_html}</div>' if (size_html or type_html) else ''
        content = (
            f'<span style="font-size:0.88rem;color:var(--accent,#7c3aed);font-weight:500;">{icon_html}{_cv_esc(title)}</span>'
            f'{meta_group}'
        )

        inner_style = 'display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--border,#f3f4f6);text-decoration:none;'
        if safe_url:
            inner = f'<a href="{_cv_esc(safe_url)}" target="_blank" rel="noopener" style="{inner_style}">{content}</a>'
        else:
            inner = f'<div style="{inner_style}">{content}</div>'

        rows.append(f'<li>{inner}</li>')

    return (
        f'<div style="border:1px solid var(--border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);padding:16px 20px;margin:1.2rem 0;">'
        f'<div style="font-weight:700;color:var(--text,#374151);margin-bottom:4px;">📎 {_cv_esc(heading_title)}</div>'
        f'<ul style="list-style:none;padding:0;margin:0;">{"".join(rows)}</ul>'
        f'</div>'
    )

_RENDERERS['resources_list'] = _render_resources_list


def _render_roadmap(b: dict) -> str:
    phases = b.get('phases', [])
    accent = b.get('accent', '#4f46e5')
    status_cfg = {
        'done':        ('#10b981', '✅ Done'),
        'in_progress': ('#3b82f6', '🔄 In Progress'),
        'planned':     ('#9ca3af', '📅 Planned'),
        'blocked':     ('#ef4444', '🚫 Blocked'),
    }
    html = f'<div style="margin:1.5rem 0;">'
    for phase in phases:
        name = phase.get('name') or phase.get('label', '')
        status = phase.get('status', 'planned')
        items = phase.get('items', [])
        fg, status_label = status_cfg.get(status, ('#9ca3af', status))
        html += (f'<div style="margin-bottom:12px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);border-radius:12px;border-radius:var(--a2ui-radius,12px);overflow:hidden;">'
                 f'<div style="padding:10px 16px;background:#f9fafb;border-bottom:1px solid #e5e7eb;'
                 f'display:flex;justify-content:space-between;align-items:center;">'
                 f'<span style="font-weight:700;">{_esc(name)}</span>'
                 f'<span style="font-size:0.78rem;color:{fg};font-weight:600;">{status_label}</span></div>')
        html += '<ul style="list-style:none;padding:0;margin:0;">'
        for item in items:
            txt = item if isinstance(item, str) else item.get('label', str(item))
            html += f'<li style="padding:7px 16px;border-bottom:1px solid #f9fafb;font-size:0.86rem;">• {_esc(txt)}</li>'
        html += '</ul></div>'
    html += '</div>'
    return html

_RENDERERS['roadmap'] = _render_roadmap


