def _render_intro(b: dict) -> str:
    parts = []
    cb_attrs = f' data-cb="node" data-key="{_ck(b.get("series_label"), "intro")}"'
    if b.get("series_label") and b.get("series_url"):
        parts.append(
            f'<p{cb_attrs}><em>In <a href="{_cv_esc(b["series_url"])}">{_cv_esc(b["series_label"])}</a>, '
            f'{_md_inline(b.get("continuation", "I covered the background. This article picks up from there."))}</em></p>'
        )
    if b.get("note"):
        parts.append(f'<p{cb_attrs if not parts else ""}><em>{_md_inline(b["note"])}</em></p>')
    return "\n".join(parts)
_RENDERERS["intro"] = _render_intro

# NOTE: a third, even more inferior duplicate _render_subheading used to
# live here (always <h3>, ignores `level` AND `condensed` entirely) and
# was winning over BOTH earlier definitions via re-registration below —
# same class of bug as numbered_list/color_section. Removed 2026-07-24.

def _render_quote(b: dict) -> str:
    html = f'<blockquote data-cb="node" data-key="{_ck(b.get("attribution"), "quote")}"><p>{_md_inline(b.get("text", ""))}</p>'
    if b.get("attribution"):
        html += f'<footer>— {_cv_esc(b["attribution"])}</footer>'
    html += '</blockquote>'
    return html
_RENDERERS["quote"] = _render_quote

def _render_pipeline(b: dict) -> str:
    steps = b.get("steps", [])
    flow = " ──► ".join(f'<code data-cb="node" data-key="{_cv_esc(s)}">{_cv_esc(s)}</code>' for s in steps)
    return f'<p style="font-family:monospace;background:#f4f4f4;padding:12px 16px;border-radius:6px;border-radius:var(--a2ui-radius-sm,6px);">{flow}</p>'
_RENDERERS["pipeline"] = _render_pipeline

def _render_tabs(b: dict, _tab_counter=[0]) -> str:
    """CSS-only tabbed panels — typically used for multi-language code examples."""
    _tab_counter[0] += 1
    group = f"tmtabs{_tab_counter[0]}"
    tabs = b.get("tabs", [])
    if not tabs:
        return ""

    accent = b.get("accent", "#1a73e8")

    # Dynamic CSS for this tab group's checked states
    checked_css = "".join(
        f'#{group}_t{i}:checked ~ .tm-tab-labels .tm-tab-label[for="{group}_t{i}"]'
        f'{{background:var(--surface,#fff);color:{_cv_esc(accent)};border-bottom-color:{_cv_esc(accent)};font-weight:700;}}\n'
        f'#{group}_t{i}:checked ~ .tm-tab-panels > .tm-tab-panel:nth-child({i})'
        f'{{display:block;}}\n'
        for i in range(1, len(tabs) + 1)
    )

    inputs = "".join(
        f'<input type="radio" id="{group}_t{_cv_esc(i)}" name="{group}" {"checked" if i == 1 else ""}>'
        for i, _ in enumerate(tabs, 1)
    )
    labels = "".join(
        f'<label class="tm-tab-label" for="{group}_t{_cv_esc(i)}">{_cv_esc(tab.get("label","Tab"))}</label>'
        for i, tab in enumerate(tabs, 1)
    )
    panels = "".join(
        f'<div class="tm-tab-panel">{_render_code(tab)}</div>'
        for tab in tabs
    )

    return (
        f'{_TAB_CSS}'
        f'<style>{checked_css}</style>'
        f'<div class="tm-tabs">'
        f'{inputs}'
        f'<div class="tm-tab-labels">{labels}</div>'
        f'<div class="tm-tab-panels">{panels}</div>'
        f'</div>'
    )
_RENDERERS["tabs"] = _render_tabs

def _render_content_tabs(b: dict, _ct_counter=[0]) -> str:
    """CSS-only tabbed panels holding real nested atom blocks per pane —
    content_tabs' sibling of _render_tabs (single code string per pane) and
    _render_columns (nested blocks, no tab switching). Reuses _TAB_CSS's
    exact markup/CSS convention so both tab atoms share one visual system;
    each pane is rendered via the same _RENDERERS.get(type, _render_unknown)
    dispatch idiom _render_columns/_render_color_section use for children."""
    _ct_counter[0] += 1
    group = f"cttabs{_ct_counter[0]}"
    tabs = b.get("tabs", [])
    if not tabs:
        return ""

    accent = b.get("accent", "#1a73e8")
    default_index = b.get("default_index", 0)
    if not isinstance(default_index, int) or not (0 <= default_index < len(tabs)):
        default_index = 0

    checked_css = "".join(
        f'#{group}_t{i}:checked ~ .tm-tab-labels .tm-tab-label[for="{group}_t{i}"]'
        f'{{background:var(--surface,#fff);color:{_cv_esc(accent)};border-bottom-color:{_cv_esc(accent)};font-weight:700;}}\n'
        f'#{group}_t{i}:checked ~ .tm-tab-panels > .tm-tab-panel:nth-child({i})'
        f'{{display:block;}}\n'
        for i in range(1, len(tabs) + 1)
    )
    inputs = "".join(
        f'<input type="radio" id="{group}_t{_cv_esc(i)}" name="{group}" '
        f'{"checked" if (i - 1) == default_index else ""}>'
        for i, _ in enumerate(tabs, 1)
    )
    labels = "".join(
        f'<label class="tm-tab-label" for="{group}_t{_cv_esc(i)}">{_esc(tab.get("label", "Tab"))}</label>'
        for i, tab in enumerate(tabs, 1)
    )
    def _panel_style(tab):
        # Optional per-tab max_width (2026-07-24): caps + centres THIS
        # panel's content — applies at the tab level so it's consistent
        # regardless of whether the tab's own content wraps itself in a
        # color_section or not (a plain heading/body/table tab gets the
        # same treatment as a color_section-wrapped one).
        mw = tab.get("max_width")
        return f' style="max-width:{_cv_esc(mw)};margin-left:auto;margin-right:auto;"' if mw else ""

    panels = "".join(
        f'<div class="tm-tab-panel"{_panel_style(tab)}>'
        + "".join(_RENDERERS.get(bl.get("type", ""), _render_unknown)(bl) for bl in (tab.get("blocks") or []))
        + '</div>'
        for tab in tabs
    )

    return (
        f'{_TAB_CSS}'
        f'<style>{checked_css}</style>'
        f'<div class="tm-tabs">'
        f'{inputs}'
        f'<div class="tm-tab-labels">{labels}</div>'
        f'<div class="tm-tab-panels">{panels}</div>'
        f'</div>'
    )
_RENDERERS["content_tabs"] = _render_content_tabs

def _pin_num(v):
    """A pin coordinate (percent of the image) as a plain number for a style or attribute: anything else is 0."""
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        try:
            v = float(v)
        except (TypeError, ValueError):
            return 0
    return v if v == v and abs(v) != float("inf") else 0


