_PLATE_JS = """
<script>
(function(){
  if (window.__a2uiPlateLayout) return;
  window.__a2uiPlateLayout = function(root) {
    if (window.matchMedia('(max-width:860px)').matches) return;
    (root || document).querySelectorAll('.pp-plate').forEach(function(plate){
      var imgwrap = plate.querySelector('.pp-imgwrap');
      var pins = [].slice.call(plate.querySelectorAll('.pp-pin'));
      if (!pins.length) return;
      var plateRect = plate.getBoundingClientRect();
      // Shared lookup by data-pin-idx (2026-09-11, two-sided layout): a
      // label's line always targets ITS OWN pin's real position, however
      // many sides exist and whichever one that label landed in --
      // replaces the old same-index-both-arrays assumption, which broke
      // the moment there could be two independent label columns instead
      // of one.
      var pinYByIdx = {};
      pins.forEach(function(p){
        var r = p.getBoundingClientRect();
        pinYByIdx[p.getAttribute('data-pin-idx')] = (r.top + r.height / 2) - plateRect.top;
      });

      ['left', 'right'].forEach(function(side){
        var labelsBox = plate.querySelector('.pp-labels-side.' + side);
        var gap = plate.querySelector('.pp-gap-side[data-side="' + side + '"]');
        if (!labelsBox || !gap) return; // that side has zero pins -- collapsed server-side, nothing to lay out
        var labels = [].slice.call(labelsBox.querySelectorAll('.pp-label'));
        if (!labels.length) return;
        var pinYs = labels.map(function(l){ return pinYByIdx[l.getAttribute('data-pin-idx')]; });

        labels.forEach(function(l){ l.style.top = '0px'; l.style.visibility = 'hidden'; });
        var heights = labels.map(function(l){ return l.getBoundingClientRect().height; });
        // Stack in CURRENT pin-Y order, not DOM/original-index order
        // (fixed 2026-09-11, same reasoning as the shared lookup above --
        // a dragged/repositioned pin must not leave its label stranded in
        // its old rank). Sort by actual pinY, scatter computed tops back
        // to each label's own original index.
        var GAP = 14;
        var order = pinYs.map(function(_, i){ return i; });
        order.sort(function(a, b){ return pinYs[a] - pinYs[b]; });
        var tops = new Array(pinYs.length);
        var prevBottom = null;
        order.forEach(function(idx){
          var top = pinYs[idx] - heights[idx] / 2;
          if (prevBottom !== null) top = Math.max(top, prevBottom + GAP);
          tops[idx] = top;
          prevBottom = top + heights[idx];
        });
        tops.forEach(function(top, i){
          labels[i].style.top = top + 'px';
          labels[i].style.visibility = 'visible';
          labels[i].classList.add('pp-placed');
        });
        var imgRect = imgwrap.getBoundingClientRect();
        var totalH = Math.max(imgRect.height, prevBottom);
        labelsBox.style.minHeight = totalH + 'px';
        gap.style.minHeight = totalH + 'px';

        var gapRect = gap.getBoundingClientRect();
        var svgNS = 'http://www.w3.org/2000/svg';
        var existing = gap.querySelector('svg');
        if (existing) existing.remove();
        var svg = document.createElementNS(svgNS, 'svg');
        svg.setAttribute('width', gapRect.width);
        svg.setAttribute('height', totalH);
        svg.setAttribute('viewBox', '0 0 ' + gapRect.width + ' ' + totalH);
        // Mirrored for the left side: starts at the gap's RIGHT edge
        // (touching the image's LEFT edge) instead of its left edge.
        var fromX = side === 'left' ? gapRect.width : 0;
        var toX = side === 'left' ? 0 : gapRect.width;
        var nearLabelX = side === 'left' ? 6 : gapRect.width - 6;
        var midX = gapRect.width * 0.5;
        pinYs.forEach(function(y, i){
          var labelCenterY = tops[i] + heights[i] / 2;
          var path = document.createElementNS(svgNS, 'path');
          path.setAttribute('d', 'M' + fromX.toFixed(1) + ',' + y.toFixed(1) +
            ' L' + midX.toFixed(1) + ',' + y.toFixed(1) +
            ' L' + nearLabelX.toFixed(1) + ',' + labelCenterY.toFixed(1) +
            ' L' + toX.toFixed(1) + ',' + labelCenterY.toFixed(1));
          path.setAttribute('fill', 'none');
          path.setAttribute('stroke', 'var(--accent,#1a73e8)');
          path.setAttribute('stroke-width', '1');
          path.setAttribute('opacity', '0.75');
          svg.appendChild(path);
          var dot = document.createElementNS(svgNS, 'circle');
          dot.setAttribute('cx', fromX);
          dot.setAttribute('cy', y.toFixed(1));
          dot.setAttribute('r', 2.4);
          dot.setAttribute('fill', 'var(--accent,#1a73e8)');
          svg.appendChild(dot);
        });
        gap.appendChild(svg);
      });
    });
  };
  function runAll(){ requestAnimationFrame(function(){ window.__a2uiPlateLayout(document); }); }
  // Wait for the WHOLE document to finish parsing before the first run —
  // querying '.pp-imgwrap img' from whichever plate's own inline <script>
  // happens to run first only sees plates parsed so far. An early decode()
  // resolving mid-parse raced ahead and hit a later plate's '.pp-labels'
  // before that div existed, throwing null on querySelectorAll (2026-07-25).
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', runAll);
  } else {
    runAll();
  }
  window.addEventListener('load', runAll); // catches any images that were still loading
  document.addEventListener('change', function(e){
    if (e.target && e.target.matches('.pp-toggles input')) runAll();
  });
  var t;
  window.addEventListener('resize', function(){ clearTimeout(t); t = setTimeout(runAll, 150); });
})();
</script>
"""

def _render_primitive_plate(b: dict, _pp_counter=[0]) -> str:
    """A real UI capture, pin-annotated — each pin is a declarative
    {x, y, field, note} coordinate (0-100, percent of the image), not a
    hand-drawn illustration. Multiple `states` render as CSS-only toggle
    chips (the same checked-radio idiom as content_tabs) over the SAME
    pin/label layout engine; a single state renders no toggle UI at all."""
    _pp_counter[0] += 1
    uid = f"pp{_pp_counter[0]}"
    title = _esc(b.get("title", ""))
    kind = _esc(b.get("kind", ""))
    caption = b.get("caption", "")
    width = b.get("width", 460)
    states = b.get("states") or []
    if not states:
        return ""

    n_states = len(states)

    def _state_body(state, idx):
        pins = state.get("pins") or []
        img = state.get("image", "")
        # In-image line is OFF BY DEFAULT (2026-09-11): unconditionally
        # drawing x1={pin's own x} to x2="100" meant a left-side pin drew a
        # line crossing the ENTIRE image over whatever sat between it and
        # the right edge -- a source of obscuring on any dense screenshot,
        # separate from the pin dot itself. Re-added 2026-09-11 (later same
        # day) as an explicit per-pin OPT-IN (`"connector": "continuous"`):
        # some pins genuinely sit over empty background where a full line
        # obscures nothing, and the author is in a better position to know
        # that than a blanket rule either way. Default (no connector field,
        # or any other value) stays the safe behavior -- only the .pp-gap
        # line (JS, below), which starts at the image's right edge and
        # reads each pin's real position from the DOM directly.
        lines = "".join(
            f'<line x1="{_pin_num(p.get("x"))}" y1="{_pin_num(p.get("y"))}" x2="100" y2="{_pin_num(p.get("y"))}" '
            f'stroke="var(--accent,#1a73e8)" stroke-width="0.4"/>'
            for p in pins if p.get("connector") == "continuous"
        )
        # Unified numbering across BOTH sides (2026-09-11), by actual y
        # position, not left-side-then-right-side or declaration order --
        # "3" always means the third-highest pin regardless of which
        # column it lands in. Arabic, not roman: the circular badge
        # already disambiguates a pin number from any digit that happens
        # to appear in the screenshot itself, so roman's main advantage
        # was redundant, and roman gets genuinely hard to read past ~vi
        # on a busy plate.
        order_by_y = sorted(range(len(pins)), key=lambda i: pins[i].get("y", 0))
        display_num = {orig_i: n + 1 for n, orig_i in enumerate(order_by_y)}

        markers = []
        for i, p in enumerate(pins):
            advance = p.get("advance") and idx + 1 < n_states
            adv_cls = " pp-pin-advance" if advance else ""
            adv_attr = (
                f' role="button" tabindex="0" '
                f'onclick="var r=document.getElementById(\'{uid}_t{idx + 1}\');'
                f'if(r){{r.checked=true;r.dispatchEvent(new Event(\'change\',{{bubbles:true}}));}}"'
                if advance else ""
            )
            markers.append(
                f'<div class="pp-pin{adv_cls}" data-pin-idx="{_cv_esc(i)}" '
                f'style="top:{_pin_num(p.get("y"))}%;left:{_pin_num(p.get("x"))}%;"{adv_attr}>'
                f'{display_num[i]}</div>'
            )
        markers = "".join(markers)

        # Split by horizontal position (2026-09-11): a pin left of center
        # routes to a label column on the LEFT of the image instead of
        # always the right, so the connector line is roughly proportional
        # to actual distance instead of every left-side pin drawing the
        # longest possible line across to a single right-hand column. A
        # side with zero pins renders neither its gap nor its label
        # column -- collapses to exactly today's one-sided look, not an
        # empty reserved space.
        left_labels, right_labels = [], []
        for i, p in enumerate(pins):
            chrome_cls = " pp-chrome" if p.get("chrome") else ""
            # field now goes through _md_inline (2026-09-11), same as
            # caption/note already did -- was plain _esc only, so **bold**
            # worked in a note but not in the field label right next to it,
            # an inconsistency with no real reason behind it.
            field = _md_inline(p.get("field", ""))
            note = _md_inline(p.get("note", ""))
            badge = p.get("badge")
            badge_html = f'<span class="pp-badge pp-badge-{_esc(badge)}">{_esc(badge.replace("-", " "))}</span>' if badge else ""
            # Optional per-pin size overrides (2026-09-11) -- CSS length
            # strings (e.g. "0.9rem"), author's call for a plate with an
            # unusually long note or a field name that needs to stand out.
            # Absent -> no inline style at all, falls through to the normal
            # CSS class size exactly as before this existed.
            _field_sz = _safe_css(p.get("field_size"), "") if p.get("field_size") else ""
            field_style = f' style="font-size:{_esc(_field_sz)}"' if _field_sz else ""
            _note_sz = _safe_css(p.get("note_size"), "") if p.get("note_size") else ""
            note_style = f' style="font-size:{_esc(_note_sz)}"' if _note_sz else ""
            label_html = (
                f'<div class="pp-label" data-pin-idx="{_cv_esc(i)}"><span class="pp-field"{field_style}>{field}{badge_html}</span>'
                f'<span class="pp-note{chrome_cls}"{note_style}><span class="pp-num">{display_num[i]}.</span> {note}</span></div>'
            )
            (left_labels if p.get("x", 0) < 50 else right_labels).append(label_html)

        left_side_html = (
            f'<div class="pp-labels-side left">{"".join(left_labels)}</div>'
            f'<div class="pp-gap-side" data-side="left"></div>'
        ) if left_labels else ""
        right_side_html = (
            f'<div class="pp-gap-side" data-side="right"></div>'
            f'<div class="pp-labels-side right">{"".join(right_labels)}</div>'
        ) if right_labels else ""

        active = " active" if idx == 0 else ""
        display = "display:block;" if idx == 0 else "display:none;"
        state_k = state.get("id", state.get("label", state.get("name", f"State {idx+1}")))
        return (
            f'<div data-cb="node" data-key="{_cv_esc(state_k)}" class="pp-state{active}" data-state="{uid}_{_cv_esc(idx)}" style="{display}">'
            f'<div class="pp-plate">'
            f'{left_side_html}'
            f'<div class="pp-imgwrap" style="width:{width}px;">'
            f'<img src="{_cv_esc(img)}" alt="{_esc(state["alt"]) if state.get("alt") else f"{title} — captured UI state"}">'
            f'<svg viewBox="0 0 100 100" preserveAspectRatio="none">{lines}</svg>'
            f'{markers}'
            f'</div>'
            f'{right_side_html}'
            f'</div>'
            f'</div>'
        )

    toggles_html = ""
    if len(states) > 1:
        # input+label MUST be adjacent siblings, in that order — the CSS
        # ".pp-toggles input:checked + label" rule is an adjacent-sibling
        # selector; grouping all inputs then all labels (the previous
        # structure) made it match "whichever label follows ANY checked
        # input", i.e. always the label right after the LAST input,
        # regardless of which one was actually checked (real bug, found
        # 2026-07-25 while adding click-to-advance pins).
        pairs = "".join(
            f'<input type="radio" name="{uid}_toggle" id="{uid}_t{_cv_esc(i)}"'
            f'{" checked" if i == 0 else ""} '
            f'onchange="document.querySelectorAll(\'[data-state^=\\\'{uid}_\\\']\').forEach(function(el){{'
            f'el.style.display = (el.dataset.state === \'{uid}_{_cv_esc(i)}\') ? \'block\' : \'none\';}});">'
            f'<label data-cb="label" data-key="{_cv_esc(s.get("id", s.get("label", s.get("name", f"State {i+1}"))))}" for="{uid}_t{_cv_esc(i)}">{_esc(s.get("label", f"State {i+1}"))}</label>'
            for i, s in enumerate(states)
        )
        toggles_html = f'<div class="pp-toggles">{pairs}</div>'

    states_html = "".join(_state_body(s, i) for i, s in enumerate(states))
    caption_html = f'<p class="pp-caption">{_md_inline(caption)}</p>' if caption else ""
    kind_html = f'<span class="pp-kind">{kind}</span>' if kind else ""

    # Generic surface-comparison badge -- any target ("Google Chat Cards
    # v2", "Slack Block Kit", "a bare <select>", whatever the author is
    # actually comparing against), not hardcoded to one Google surface.
    # Renamed from the original `chat_equivalent` (single hardcoded "Chat
    # Cards v2" target) so this atom documents ANY software, not just A2UI
    # hosts -- see a2uithoughts.md's decoupling-from-Gemini entry.
    equiv = b.get("equivalent_in")
    chat_html = ""
    if equiv:
        status = equiv.get("status", "no")
        icon = {"yes": "✓", "partial": "~", "no": "✗"}.get(status, "?")
        cls = f"pp-chat-{_cv_esc(status)}"
        note = _esc(equiv.get("note", ""))
        title_attr = f' title="{note}"' if note else ""
        surface = _esc(equiv.get("surface", "equivalent"))
        chat_html = f'<span class="pp-chat {cls}"{title_attr}>{surface} {icon}</span>'

    repo_html = ""
    if "repo_url" in b:
        repo_url = b.get("repo_url") or ""
        placeholder = not repo_url
        href = repo_url if repo_url else "#"
        placeholder_cls = " pp-repo-placeholder" if placeholder else ""
        title_attr = ' title="Repo not yet public"' if placeholder else ""
        repo_html = f'<a class="pp-repo{placeholder_cls}" href="{_esc(href)}" target="_blank" rel="noopener noreferrer"{title_attr}>GitHub ↗</a>'

    return (
        f'{_PLATE_CSS}{_PLATE_JS}'
        f'<div class="pp-wrap" id="{_esc(b.get("id", uid))}">'
        f'<div class="pp-head"><h4>{title}</h4>{kind_html}{chat_html}{repo_html}</div>'
        f'{caption_html}{toggles_html}{states_html}'
        f'</div>'
    )
_RENDERERS["primitive_plate"] = _render_primitive_plate

def _scrollspy_script(ids: list) -> str:
    """Registers this gallery's sub-item ids for the shared scrollspy, and
    (once per page, guarded) sets up the IntersectionObserver that tracks
    which one is in view and toggles .sg-active-link on every matching
    #anchor on the page — nav sub-link AND any other link (e.g. a TL;DR
    table row) pointing at the same id."""
    ids_json = _js_json(ids)
    return (
        "<script>"
        "(function(){"
        f"window.__a2uiSpyIds = (window.__a2uiSpyIds || []).concat({ids_json});"
        "if (window.__a2uiSpyInit) return;"
        "window.__a2uiSpyInit = true;"
        "document.addEventListener('DOMContentLoaded', function(){"
        "  var ids = window.__a2uiSpyIds || [];"
        "  var targets = ids.map(function(id){ return document.getElementById(id); }).filter(Boolean);"
        "  if (!targets.length) return;"
        "  var current = null;"
        "  function setActive(id){"
        "    if (id === current) return;"
        "    current = id;"
        "    document.querySelectorAll('.sg-active-link').forEach(function(el){ el.classList.remove('sg-active-link'); });"
        "    if (!id) return;"
        "    document.querySelectorAll('a[href=\"#' + id + '\"]').forEach(function(el){ el.classList.add('sg-active-link'); });"
        "  }"
        "  var io = new IntersectionObserver(function(entries){"
        "    var visible = entries.filter(function(e){ return e.isIntersecting; });"
        "    if (!visible.length) return;"
        "    visible.sort(function(a,b){ return a.boundingClientRect.top - b.boundingClientRect.top; });"
        "    setActive(visible[0].target.id);"
        "  }, {rootMargin: '-15% 0px -70% 0px', threshold: 0});"
        "  targets.forEach(function(t){ io.observe(t); });"
        "});"
        "})();"
        "</script>"
    )


def _render_scroll_gallery(b: dict, _sg_counter=[0]) -> str:
    """Sticky nested-nav rail + a vertical sequence of grouped sections —
    the 'scroll instead of tabs' sibling of content_tabs, for long
    reference galleries (e.g. a primitive-by-primitive field guide) where
    a reader wants to browse continuously rather than switch panels."""
    _sg_counter[0] += 1
    uid = f"sg{_sg_counter[0]}"
    sections = b.get("sections") or []
    if not sections:
        return ""

    def _anchor(text, idx, sub_idx=None):
        base = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
        return f"{uid}_{_cv_esc(idx)}_{_cv_esc(sub_idx)}_{base}" if sub_idx is not None else f"{uid}_{_cv_esc(idx)}_{base}"

    nav_items = []
    section_htmls = []
    spy_ids = []
    for si, section in enumerate(sections):
        label = section.get("label", f"Section {si + 1}")
        blocks = section.get("blocks", [])
        sec_anchor = _anchor(label, si)
        sub_links = []
        for bi, blk in enumerate(blocks):
            sub_title = blk.get("title") or blk.get("label")
            if sub_title:
                sub_anchor = blk.get("id") or _anchor(sub_title, si, bi)
                if not blk.get("id"):
                    blk = dict(blk)
                    blk["id"] = sub_anchor
                    blocks[bi] = blk
                sub_links.append(f'<a class="sg-sub" href="#{_cv_esc(sub_anchor)}">{_esc(sub_title)}</a>')
                spy_ids.append(sub_anchor)
        nav_items.append(
            f'<div class="sg-navsection">'
            f'<a class="sg-navhead" href="#{sec_anchor}"><span class="sg-navnum">{si + 1:02d}</span>{_esc(label)}</a>'
            f'{"".join(sub_links)}'
            f'</div>'
        )
        body = "".join(_RENDERERS.get(blk.get("type", ""), _render_unknown)(blk) for blk in blocks)
        section_htmls.append(
            f'<section class="sg-section" id="{sec_anchor}">'
            f'<h3 class="sg-sechead"><span class="sg-navnum">{si + 1:02d}</span>{_esc(label)}</h3>'
            f'{body}'
            f'</section>'
        )

    return (
        '<style>'
        '.sg-layout{display:grid;grid-template-columns:190px 1fr;gap:36px;align-items:start;'
        'margin:1.4rem auto;max-width:90%;}'
        '.sg-nav{position:sticky;top:70px;display:flex;flex-direction:column;gap:14px;'
        'border-right:1px solid var(--border,#e0e0e0);padding-right:18px;max-height:calc(100vh - 94px);overflow-y:auto;}'
        '.sg-navsection{display:flex;flex-direction:column;gap:2px;}'
        '.sg-navhead{display:flex;align-items:baseline;gap:8px;color:var(--text,#1f2328);'
        'text-decoration:none;font-weight:600;font-size:.86rem;padding:4px 0;}'
        '.sg-navnum{font-family:ui-monospace,monospace;font-size:.68rem;color:var(--accent-2,var(--accent,#1a73e8));}'
        '.sg-sub{display:block;color:var(--text-muted,#5f6368);text-decoration:none;font-size:.78rem;'
        'padding:3px 0 3px 22px;}'
        '.sg-sub:hover{color:var(--accent,#1a73e8);}'
        '.sg-sechead{display:flex;align-items:baseline;gap:10px;font-size:1.3rem;font-weight:700;'
        'color:var(--text,#1f2328);border-bottom:1px solid var(--border,#e0e0e0);'
        'padding-bottom:10px;margin:0 0 22px;}'
        '.sg-section{margin-bottom:64px;scroll-margin-top:24px;}'
        '@media (max-width:860px){.sg-layout{grid-template-columns:1fr;}'
        '.sg-nav{position:static;flex-direction:row;flex-wrap:wrap;border-right:none;'
        'border-bottom:1px solid var(--border,#e0e0e0);padding:0 0 14px;max-height:none;}}'
        # Scrollspy result: ANY anchor elsewhere on the page pointing at the
        # in-view primitive (the TL;DR table's own #card/#text/... links,
        # not just this nav) gets highlighted — a table row lights up via
        # :has() rather than needing the table atom to know about the spy.
        '.sg-sub.sg-active-link{color:var(--accent,#1a73e8);font-weight:700;}'
        'a.sg-active-link{color:var(--accent,#1a73e8);font-weight:700;}'
        'tr:has(a.sg-active-link){background:var(--surface-2,#f8f9fa);}'
        '</style>'
        f'<div class="sg-layout"><nav class="sg-nav">{"".join(nav_items)}</nav>'
        f'<main>{"".join(section_htmls)}</main></div>'
        f'{_scrollspy_script(spy_ids)}'
    )
_RENDERERS["scroll_gallery"] = _render_scroll_gallery

def _render_key_value(b: dict) -> str:
    """Key-value pairs — for env vars, config options, API fields."""
    items = b.get("items", [])
    title = b.get("title", "")
    title_html = f'<p style="font-weight:600;margin-bottom:8px;">{_cv_esc(title)}</p>' if title else ""
    def _kv_row(item):
        required_html = "<strong>Required</strong> — " if item.get("required") else ""
        default_val = item.get("default")
        default_html = f'<br/><code style="color:#34a853;">default: {_cv_esc(default_val)}</code>' if default_val is not None else ""
        k_key = _cv_esc(item.get("key") or item.get("name") or "")
        return (
            f'<tr data-cb="item" data-key="{k_key}">'
            f'<td data-cb="label" data-key="{k_key}" style="padding:8px 12px;font-family:monospace;font-size:0.85em;color:#1a73e8;white-space:nowrap;'
            f'border-bottom:1px solid #f0f0f0;vertical-align:top;font-weight:600;">{_cv_esc(item.get("key",""))}</td>'
            f'<td style="padding:8px 12px;color:#5f6368;font-size:0.85em;border-bottom:1px solid #f0f0f0;">'
            f'{required_html}{_md_inline(item.get("description",""))}{default_html}'
            f'</td></tr>'
        )
    rows = "".join(_kv_row(item) for item in items)
    return (
        f'{title_html}'
        f'<div style="overflow-x:auto;margin:1.2rem 0;">'
        f'<table style="border-collapse:collapse;width:100%;background:#fafafa;border-radius:8px;overflow:hidden;">'
        f'<tbody>{rows}</tbody>'
        f'</table></div>'
    )
_RENDERERS["key_value"] = _render_key_value

def _render_api_reference(b: dict) -> str:
    """API / function reference block — name, description, parameters table, returns, example."""
    name        = b.get("name", "")
    kind        = b.get("kind", "function")   # function, endpoint, class, method
    description = b.get("description", "")
    params      = b.get("parameters", [])
    returns     = b.get("returns", "")
    example     = b.get("example", {})
    http_method = b.get("method", "")         # GET, POST etc. for endpoints
    deprecated  = b.get("deprecated", False)

    # Header badge
    kind_colors = {
        "function": ("#e8f0fe", "#1558b4"),
        "endpoint": ("#e6f4ea", "#137333"),
        "class":    ("#fef7e0", "#e37400"),
        "method":   ("#f3e8fd", "#8430ce"),
    }
    bg, color = kind_colors.get(kind, kind_colors["function"])
    method_badge = f'<span style="background:#137333;color:#fff;padding:2px 8px;border-radius:4px;font-size:0.75rem;font-weight:700;margin-right:8px;">{_cv_esc(http_method)}</span>' if http_method else ""
    deprecated_html = '<span style="background:#c5221f;color:#fff;padding:2px 8px;border-radius:4px;font-size:0.75rem;margin-left:8px;">DEPRECATED</span>' if deprecated else ""

    # Parameters table
    param_rows = ""
    if params:
        def _param_row(i, p):
            bg = "background:#f8f9fa;" if i % 2 else ""
            req = "✓" if p.get("required") else ""
            default_val = p.get("default")
            default_html = f'<br/><code style="color:#34a853;font-size:0.9em;">default: {_cv_esc(default_val)}</code>' if default_val is not None else ""
            return (
                f'<tr style="{bg}">'
                f'<td style="padding:8px 12px;font-family:monospace;font-size:0.82em;color:#1a73e8;white-space:nowrap;">{_cv_esc(p.get("name",""))}</td>'
                f'<td style="padding:8px 12px;font-family:monospace;font-size:0.82em;color:#e37400;">{_cv_esc(p.get("type",""))}</td>'
                f'<td style="padding:8px 12px;font-size:0.82em;color:#c5221f;text-align:center;">{req}</td>'
                f'<td style="padding:8px 12px;font-size:0.82em;color:#5f6368;">{_md_inline(p.get("description",""))}{default_html}</td>'
                f'</tr>'
            )
        rows = "".join(_param_row(i, p) for i, p in enumerate(params))
        param_rows = (
            f'<div style="margin-top:12px;">'
            f'<p style="font-size:0.8rem;font-weight:600;color:#5f6368;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.05em;">Parameters</p>'
            f'<div style="overflow-x:auto;border-radius:6px;border:1px solid #e0e0e0;">'
            f'<table style="border-collapse:collapse;width:100%;font-size:0.9em;">'
            f'<thead><tr style="background:#f1f3f4;">'
            f'<th style="padding:8px 12px;text-align:left;font-size:0.78rem;color:#5f6368;">Name</th>'
            f'<th style="padding:8px 12px;text-align:left;font-size:0.78rem;color:#5f6368;">Type</th>'
            f'<th style="padding:8px 12px;text-align:center;font-size:0.78rem;color:#5f6368;">Req</th>'
            f'<th style="padding:8px 12px;text-align:left;font-size:0.78rem;color:#5f6368;">Description</th>'
            f'</tr></thead>'
            f'<tbody>{rows}</tbody>'
            f'</table></div></div>'
        )

    # Returns
    returns_html = ""
    if returns:
        returns_html = (
            f'<div style="margin-top:12px;">'
            f'<p style="font-size:0.8rem;font-weight:600;color:#5f6368;margin-bottom:4px;text-transform:uppercase;letter-spacing:0.05em;">Returns</p>'
            f'<p style="font-size:0.88em;color:#3c4043;">{_md_inline(returns)}</p>'
            f'</div>'
        )

    # Example
    example_html = ""
    if example:
        ex_code = example.get("code", "").replace("<", "&lt;").replace(">", "&gt;")
        ex_lang = example.get("language", "")
        ex_label = example.get("label", "Example")
        example_html = (
            f'<div style="margin-top:12px;">'
            f'<p style="font-size:0.8rem;font-weight:600;color:#5f6368;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.05em;">{_cv_esc(ex_label)}</p>'
            f'<pre style="margin:0;padding:14px;background:#f8f9fa;border-radius:6px;overflow-x:auto;font-size:0.84rem;line-height:1.6;">'
            f'<code class="language-{_cv_esc(ex_lang)}">{ex_code}</code>'
            f'</pre></div>'
        )

    k = _cv_esc(str(b['name'])) if b.get('name') else 'api_reference'
    return (
        f'<div data-cb="node" data-key="{k}" style="border:1px solid #e0e0e0;border-radius:10px;overflow:hidden;margin:1.5rem 0;">'
        f'<div style="background:{bg};padding:14px 18px;border-bottom:1px solid #e0e0e0;">'
        f'{method_badge}'
        f'<code style="font-size:1rem;font-weight:700;color:{color};">{_cv_esc(name)}</code>'
        f'{deprecated_html}'
        f'<span style="font-size:0.78rem;color:#5f6368;margin-left:10px;text-transform:uppercase;letter-spacing:0.05em;">{_cv_esc(kind)}</span>'
        f'</div>'
        f'<div style="padding:14px 18px;">'
        f'<p style="color:#3c4043;margin-bottom:8px;">{_md_inline(description)}</p>'
        f'{param_rows}'
        f'{returns_html}'
        f'{example_html}'
        f'</div></div>'
    )
_RENDERERS["api_reference"] = _render_api_reference


