def _render_rubric_card(b: dict) -> str:
    title = _text_loose(b.get('title')) or 'Assessment Rubric'
    raw = b.get('levels')
    levels = [_text_loose(l) or ('Level ' + str(i + 1)) for i, l in enumerate(raw[:12])] if isinstance(raw, list) and raw else ['Beginning', 'Developing', 'Proficient', 'Exemplary']
    rc = b.get('criteria')
    criteria = [c for c in rc[:100] if isinstance(c, dict)] if isinstance(rc, list) else []
    accent = _safe_css(b.get('accent'), '#4f46e5')
    n = len(levels)
    headers = ''.join(
        '<th scope="col" style="padding:10px 12px;text-align:center;font-size:0.6rem;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:'
        + ('#1b7c59' if i == n - 1 else (accent if i >= n - 2 else '#5f6e84')) + ';">' + _cv_esc(l) + '</th>'
        for i, l in enumerate(levels)
    )
    rows = ''
    for c in criteria:
        descs = c.get('descriptors') if isinstance(c.get('descriptors'), list) else (c.get('descriptions') if isinstance(c.get('descriptions'), list) else [])
        cells = ''.join(
            '<td style="padding:10px 12px;font-size:0.8rem;color:#374151;text-align:center;vertical-align:top;">'
            + _cv_esc((_text_loose(descs[i]) if i < len(descs) else '') or '—') + '</td>'
            for i in range(n)
        )
        rows += ('<tr><th scope="row" style="padding:10px 12px;font-weight:600;font-size:0.85rem;text-align:left;vertical-align:top;">'
                 + _cv_esc(_first_text(c.get('criterion'), c.get('name'))) + '</th>' + cells + '</tr>')
    return ('<div style="font-family:system-ui,sans-serif;overflow-x:auto;margin:1rem 0;">'
            '<div style="font-weight:700;margin-bottom:10px;">' + _cv_esc(title) + '</div>'
            '<table style="width:100%;border-collapse:collapse;font-size:0.85rem;">'
            '<thead><tr><th scope="col" style="padding:10px 12px;text-align:left;font-size:0.6rem;font-weight:700;'
            'letter-spacing:0.08em;text-transform:uppercase;color:var(--muted,#5f6368);">Criterion</th>' + headers + '</tr></thead>'
            '<tbody>' + rows + '</tbody></table></div>')


_RENDERERS["rubric_card"] = _render_rubric_card


def _render_knowledge_check(b: dict) -> str:
    uid = 'kc' + _wa_uid(b)[:6]
    question = _esc(b.get('question', 'Comprehension check'))
    # Schema says options are plain strings, but a common alternate shape sends
    # {label, value} objects; `_esc(str(o))` on a dict happened to still embed the label
    # text via Python's repr (an accident, not a design), while GAS's `_esc(options[i])`
    # on the same shape stringified to the literal text "[object Object]", losing every
    # option (surface-parity debt). Normalise explicitly instead of relying on either
    # language's incidental object-to-string behaviour. 2026-09-27.
    options = [o if isinstance(o, str) else (o.get('label') or o.get('text') or o.get('value') or str(o))
               for o in b.get('options', [])]
    correct = int(b.get('correct', 0))
    explain = _md.markdown(b.get('explanation', '')) if b.get('explanation') else ''
    opts_html = ''.join(
        f'<button onclick="{uid}pick({_cv_esc(i)})" style="display:block;width:100%;text-align:left;'
        f'padding:11px 14px;border-radius:9px;margin-bottom:7px;background:#fafafa;background:var(--a2ui-surface-muted,#fafafa);'
        f'border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);cursor:pointer;font-size:0.88rem;">{_esc(str(o))}</button>'
        for i, o in enumerate(options)
    )
    explain_div = f'<div id="{uid}ex" style="display:none;margin-top:10px;padding:12px;background:#f0fdf4;border-radius:8px;font-size:0.85rem;">{explain}</div>' if explain else ''
    js = (f'<script>function {uid}pick(i){{'
          f'var btns=document.querySelectorAll("[data-{uid}]");'
          f'btns.forEach(function(b,j){{b.style.background=j==={correct}?"#dcfce7":j===i?"#fee2e2":"#f9fafb";'
          f'b.style.borderColor=j==={correct}?"#34d399":j===i?"#f87171":"#e5e7eb";}});'
          f'var ex=document.getElementById("{uid}ex");if(ex)ex.style.display="block";}}</script>')
    opts_html2 = ''.join(
        f'<button data-cb="tile" data-key="{_esc(str(o))}" data-{uid} onclick="{uid}pick({_cv_esc(i)})" style="display:block;width:100%;text-align:left;'
        f'padding:11px 14px;border-radius:9px;margin-bottom:7px;background:#f9fafb;'
        f'border:1px solid #e5e7eb;cursor:pointer;font-size:0.88rem;">{_esc(str(o))}</button>'
        for i, o in enumerate(options)
    )
    return (
        f'<div style="font-family:system-ui,sans-serif;padding:20px;border-radius:12px;'
        f'background:#f9fafb;border:1px solid #e5e7eb;margin:1rem 0;">'
        f'<div style="font-size:0.6rem;font-weight:700;letter-spacing:0.1em;color:#4f46e5;'
        f'text-transform:uppercase;margin-bottom:8px;">Knowledge Check</div>'
        f'<div style="font-weight:600;margin-bottom:14px;">{question}</div>'
        f'{opts_html2}{explain_div}</div>{js}'
    )
_RENDERERS["knowledge_check"] = _render_knowledge_check


def _render_achievement_badge(b: dict) -> str:
    icon = _esc(b.get('icon', '🏆'))
    color = b.get('color', '#f59e0b')
    locked = bool(b.get('locked'))
    size = b.get('size', 'card')
    # Schema's field is `title` (Achievement name); this read the non-existent `name`, so
    # the badge's actual name never appeared (surface-parity debt). 2026-09-27.
    name = _esc(b.get('title', ''))
    desc = _esc(b.get('description', ''))
    unlocked_at = _esc(b.get('unlocked_at', ''))
    opacity = 'opacity:0.4;filter:grayscale(1);' if locked else ''
    lock_badge = '<span style="position:absolute;bottom:-4px;right:-4px;background:#6b7280;border-radius:50%;width:18px;height:18px;display:flex;align-items:center;justify-content:center;font-size:0.6rem;">🔒</span>' if locked else ''
    date_html = f'<div style="font-size:0.7rem;color:var(--muted,#5f6368);margin-top:4px;">Unlocked {unlocked_at}</div>' if unlocked_at and not locked else ''
    k = _esc(str(b['title'])) if b.get('title') else 'achievement_badge'
    if size == 'pill':
        return (f'<span data-cb="node" data-key="{k}" style="display:inline-flex;align-items:center;gap:6px;padding:6px 14px;'
                f'border-radius:99px;border:2px solid {_esc(color)};{opacity}margin:4px 0;">'
                f'<span>{icon}</span><span style="font-size:0.8rem;font-weight:700;">{name}</span></span>')
    return (
        f'<div data-cb="node" data-key="{k}" style="font-family:system-ui,sans-serif;display:inline-flex;flex-direction:column;'
        f'align-items:center;padding:20px 16px;border-radius:14px;border:2px solid {_esc(color)};'
        f'min-width:100px;text-align:center;{opacity}">'
        f'<div style="position:relative;font-size:2.5rem;margin-bottom:8px;">{icon}{lock_badge}</div>'
        f'<div style="font-weight:700;font-size:0.85rem;">{name}</div>'
        f'<div style="font-size:0.75rem;color:var(--muted,#5f6368);margin-top:4px;">{desc}</div>'
        f'{date_html}</div>'
    )
_RENDERERS["achievement_badge"] = _render_achievement_badge


def _render_annotation_highlight(b: dict) -> str:
    import re as _re
    raw_text = b.get('text', '')
    if isinstance(raw_text, str):
        text = raw_text
    elif isinstance(raw_text, (int, float)) and not isinstance(raw_text, bool):
        text = str(raw_text)
    else:
        text = ''

    raw_notes = b.get('notes')
    notes_list = raw_notes[:40] if isinstance(raw_notes, list) else []

    color_re = _re.compile(r'#[0-9a-fA-F]{6}')
    valid_notes = []
    for item in notes_list:
        if isinstance(item, dict) and isinstance(item.get('term'), str) and item['term']:
            col = item['color'] if isinstance(item.get('color'), str) and color_re.fullmatch(item['color']) else '#996206'
            exp = item.get('explanation') if isinstance(item.get('explanation'), str) else ''
            nid = item.get('id') if isinstance(item.get('id'), str) and item['id'] else item['term']
            valid_notes.append({
                'term': item['term'],
                'explanation': exp,
                'color': col,
                'id': nid
            })

    claimed = []
    matches = []
    for n in valid_notes:
        search_idx = 0
        term_len = len(n['term'])
        while search_idx <= len(text) - term_len:
            found = text.find(n['term'], search_idx)
            if found == -1:
                break
            end = found + term_len
            if not any(max(found, cs) < min(end, ce) for cs, ce in claimed):
                claimed.append((found, end))
                matches.append((found, end, n))
                break
            search_idx = found + 1

    matches.sort(key=lambda m: m[0])

    out = []
    cur = 0
    for start, end, n in matches:
        if start > cur:
            out.append(_cv_esc(text[cur:start]))
        esc_term = _cv_esc(text[start:end])
        col = n['color']
        out.append(
            f'<mark data-cb="ref" data-key="{_cv_esc(n["id"])}" '
            f'style="background:{col}22;border-bottom:2px solid {col};color:{col};padding:1px 3px;border-radius:3px;cursor:pointer;" '
            f'title="{_cv_esc(n["explanation"])}">{esc_term}</mark>'
        )
        cur = end
    if cur < len(text):
        out.append(_cv_esc(text[cur:]))

    return f'<div style="font-family:system-ui,sans-serif;line-height:1.7;margin:1rem 0;">{"".join(out)}</div>'
_RENDERERS["annotation_highlight"] = _render_annotation_highlight


def _render_quiz_result_summary(b: dict) -> str:
    if not isinstance(b, dict):
        return ""

    score_num = _num_loose(b.get("score"))
    score = min(max(int(score_num + 0.5), 0), 10 ** 9) if score_num is not None else 0

    total_num = _num_loose(b.get("total"))
    total = min(int(total_num + 0.5), 10 ** 9) if total_num is not None else 10
    if total <= 0:
        total = 1

    pass_num = _num_loose(b.get("pass_mark"))
    pass_mark = min(max(int(pass_num + 0.5), 0), 1000) if pass_num is not None else 70

    time_num = _num_loose(b.get("time_secs"))
    time_secs = min(max(int(time_num + 0.5), 0), 10 ** 9) if time_num is not None else 0

    quiz_id = _first_text(b.get("quiz_id"), "quiz")
    next_url = _safe_href(b.get("next_url"), ["http", "https"])
    retry_url = _safe_href(b.get("retry_url"), ["http", "https"])

    pct = int((score / total) * 100 + 0.5)
    passed = pct >= pass_mark
    col = "#1c805c" if passed else "#f87171"
    bg = "rgba(52,211,153,0.07)" if passed else "rgba(248,113,113,0.07)"
    bd_col = "rgba(52,211,153,0.2)" if passed else "rgba(248,113,113,0.2)"

    mins = time_secs // 60
    secs = time_secs % 60
    time_str = f"{mins}m {secs}s" if mins > 0 else f"{secs}s"

    questions_raw = b.get("questions")
    questions = questions_raw[:200] if isinstance(questions_raw, list) else []

    dots_list = []
    for i, q in enumerate(questions):
        q_obj = q if isinstance(q, dict) else {}
        ok = q_obj.get("correct") is True
        lbl = _first_text(q_obj.get("label"), f"Q{i+1}")
        mark = "✓" if ok else "✗"
        dot_bg = "#1c805c" if ok else "#f87171"
        dots_list.append(
            f'<div title="{_cv_esc(lbl)}" style="width:22px;height:22px;border-radius:50%;'
            f'display:flex;align-items:center;justify-content:center;font-size:0.55rem;font-weight:700;'
            f'color:#fff;background:{dot_bg};">{mark}</div>'
        )
    dots = "".join(dots_list)
    dots_html = (
        f'<div style="margin-bottom:20px;">'
        f'<div style="font-size:0.6rem;color:#475569;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:8px;">Question breakdown</div>'
        f'<div style="display:flex;flex-wrap:wrap;gap:6px;justify-content:center;">{dots}</div>'
        f'</div>'
    ) if dots else ""

    btns_list = []
    if retry_url:
        btns_list.append(
            f'<a href="{_cv_esc(retry_url)}" target="_top" style="padding:10px 22px;border-radius:9px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);color:var(--muted,#5f6368);font-size:0.8rem;font-weight:600;text-decoration:none;">↩ Retry</a>'
        )
    if next_url:
        btns_list.append(
            f'<a href="{_cv_esc(next_url)}" target="_top" style="padding:10px 22px;border-radius:9px;background:{col};color:#0f172a;font-size:0.8rem;font-weight:700;text-decoration:none;">Continue →</a>'
        )
    btns_html = f'<div style="display:flex;gap:10px;justify-content:center;">{"".join(btns_list)}</div>' if btns_list else ""

    verdict_emoji = "🎉" if passed else "📚"
    verdict_title = "Passed!" if passed else "Keep Going"
    verdict_desc = "Well done — you cleared the pass mark." if passed else f"You need {pass_mark}% to pass. Review the material and retry."

    quiz_id_esc = _cv_esc(quiz_id)

    return (
        f'<div data-cb="node" data-key="{quiz_id_esc}" data-quiz-id="{quiz_id_esc}" data-pct="{pct}" style="font-family:\'Inter\',system-ui,sans-serif;padding:28px;border-radius:16px;background:{bg};border:1px solid {bd_col};">'
        f'<div style="text-align:center;margin-bottom:24px;">'
        f'<div style="font-size:2.8rem;margin-bottom:10px;">{verdict_emoji}</div>'
        f'<div style="font-size:1.5rem;font-weight:800;color:{col};">{verdict_title}</div>'
        f'<div style="font-size:0.72rem;color:var(--muted,#5f6368);margin-top:5px;">{verdict_desc}</div>'
        f'</div>'
        f'<div style="display:flex;justify-content:center;align-items:center;gap:32px;margin-bottom:24px;flex-wrap:wrap;">'
        f'<div style="text-align:center;">'
        f'<div style="font-size:3.2rem;font-weight:900;color:{col};line-height:1;">{pct}<span style="font-size:1.4rem;">%</span></div>'
        f'<div style="font-size:0.62rem;color:var(--muted,#5f6368);margin-top:4px;">{score} / {total} correct</div>'
        f'</div>'
        f'<div style="display:flex;flex-direction:column;gap:8px;">'
        f'<div style="font-size:0.72rem;color:var(--muted,#5f6368);">⏱ Time: <strong style="color:#52739f;">{time_str}</strong></div>'
        f'<div style="font-size:0.72rem;color:var(--muted,#5f6368);">🎯 Pass mark: <strong style="color:#52739f;">{pass_mark}%</strong></div>'
        f'</div>'
        f'</div>'
        f'{dots_html}'
        f'{btns_html}'
        f'</div>'
    )


_RENDERERS["quiz_result_summary"] = _render_quiz_result_summary


import math

import math

def _render_skill_radar(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    title = _first_text(b.get("title"), "Skill Profile")
    accent = _safe_css(b.get("accent"), "#4f46e5")
    skills_raw = b.get("skills")
    skills = [s for s in (skills_raw if isinstance(skills_raw, list) else [])[:200] if isinstance(s, dict)]
    n = max(len(skills), 3)
    SIZE = 220
    CX = 110.0
    CY = 110.0
    R = 82.0
    OUTER = R + 22.0

    def pt(angle: float, radius: float):
        rad = (angle - 90.0) * math.pi / 180.0
        return (CX + radius * math.cos(rad), CY + radius * math.sin(rad))

    def polygon(vals: list, r: float) -> str:
        coords = []
        for i in range(n):
            v = vals[i] if i < len(vals) else 0.0
            p = pt(i * (360.0 / n), r * max(0.0, min(100.0, v)) / 100.0)
            coords.append(f"{p[0]:.2f},{p[1]:.2f}")
        return " ".join(coords)

    # Grid rings
    grid = ""
    for g in range(1, 5):
        rpts = []
        for k in range(n):
            p = pt(k * (360.0 / n), R * g / 4.0)
            rpts.append(f"{p[0]:.2f},{p[1]:.2f}")
        grid += f'<polygon points="{" ".join(rpts)}" fill="none" stroke="rgba(255,255,255,0.06)" stroke-width="1"/>'

    # Axes and labels
    axes = ""
    labels = ""
    for i in range(n):
        angle = i * (360.0 / n)
        op = pt(angle, R)
        axes += f'<line x1="{CX:.2f}" y1="{CY:.2f}" x2="{op[0]:.2f}" y2="{op[1]:.2f}" stroke="rgba(255,255,255,0.07)" stroke-width="1"/>'
        lp = pt(angle, OUTER)
        anchor = "start" if lp[0] > CX + 5.0 else ("end" if lp[0] < CX - 5.0 else "middle")
        label_text = _first_text(skills[i].get("label"), f"Skill {i + 1}") if i < len(skills) else f"Skill {i + 1}"
        labels += f'<text x="{lp[0]:.2f}" y="{(lp[1] + 4.0):.2f}" text-anchor="{anchor}" fill="#64748b" font-size="9" font-family="Inter,sans-serif">{_cv_esc(label_text)}</text>'

    has_before = any(isinstance(s, dict) and _num_loose(s.get("before")) is not None for s in skills)
    before_vals = []
    current_vals = []
    for s in skills:
        b_num = _num_loose(s.get("before"))
        before_vals.append(b_num if b_num is not None else 0.0)
        v_num = _num_loose(s.get("value"))
        current_vals.append(v_num if v_num is not None else 0.0)

    before_svg = ""
    if has_before:
        before_pts = polygon(before_vals, R)
        before_svg = f'<polygon points="{before_pts}" fill="rgba(255,255,255,0.03)" stroke="rgba(255,255,255,0.18)" stroke-width="1.5" stroke-dasharray="4,3"/>'

    current_pts = polygon(current_vals, R)
    current_svg = f'<polygon points="{current_pts}" fill="{accent}1f" stroke="{accent}" stroke-width="2"/>'

    # Dot markers
    dots = ""
    for i in range(n):
        v = current_vals[i] if i < len(current_vals) else 0.0
        v_clamped = max(0.0, min(100.0, v))
        dp = pt(i * (360.0 / n), R * v_clamped / 100.0)
        dots += f'<circle cx="{dp[0]:.2f}" cy="{dp[1]:.2f}" r="3" fill="{accent}" stroke="#0f172a" stroke-width="1.5"/>'

    svg_h = SIZE + 28
    svg = (
        f'<svg role="img" aria-label="Skill radar chart" width="{SIZE}" height="{svg_h}" viewBox="0 0 {SIZE} {svg_h}" style="max-width:280px;">'
        f'{grid}{axes}{before_svg}{current_svg}{dots}{labels}</svg>'
    )

    legend = ""
    if has_before:
        legend = (
            f'<div style="display:flex;gap:16px;justify-content:center;margin-top:6px;">'
            f'<div style="display:flex;align-items:center;gap:5px;font-size:0.62rem;color:var(--muted,#5f6368);"><div style="width:18px;height:0;border-top:2px dashed rgba(255,255,255,0.3);"></div>Before</div>'
            f'<div style="display:flex;align-items:center;gap:5px;font-size:0.62rem;color:var(--muted,#5f6368);"><div style="width:18px;height:2px;background:{accent};"></div>Now</div>'
            f'</div>'
        )

    return (
        f'<div style="font-family:\'Inter\',system-ui,sans-serif;text-align:center;">'
        f'<div style="font-size:0.68rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--muted,#5f6368);margin-bottom:14px;">\U0001f3af {_cv_esc(title)}</div>'
        f'<div style="display:flex;justify-content:center;">{svg}</div>'
        f'{legend}'
        f'</div>'
    )


_RENDERERS["skill_radar"] = _render_skill_radar


