def _render_canvas_plexus(b: dict) -> str:
    uid = 'plx' + _wa_uid(b)[:6]
    count = int(b.get('count', 80))
    colour = b.get('colour', '#4f46e5')
    max_dist = int(b.get('max_dist', 110))
    speed = float(b.get('speed', 0.7))
    dot_size = float(b.get('dot_size', 2.5))
    h = int(b.get('height', 280))
    bg = b.get('bg', '#0a0f1d')
    return (
        f'<div style="width:100%;height:{h}px;background:{_esc(bg)};border-radius:10px;overflow:hidden;position:relative;">'
        f'<canvas aria-hidden="true" id="{uid}" style="width:100%;height:100%;display:block;"></canvas>'
        f'<script>(function(){{var c=document.getElementById("{uid}"),x=c.getContext("2d"),'
        f'W,H,nodes=[];'
        f'function resize(){{W=c.width=c.offsetWidth;H=c.height=c.offsetHeight;}}resize();'
        f'window.addEventListener("resize",resize);'
        f'for(var i=0;i<{count};i++)nodes.push({{x:Math.random()*W,y:Math.random()*H,'
        f'vx:(Math.random()-0.5)*{speed},vy:(Math.random()-0.5)*{speed}}});'
        f'(function loop(){{requestAnimationFrame(loop);x.fillStyle="{_esc(bg)}";x.fillRect(0,0,W,H);'
        f'nodes.forEach(function(n){{n.x+=n.vx;n.y+=n.vy;'
        f'if(n.x<0||n.x>W)n.vx*=-1;if(n.y<0||n.y>H)n.vy*=-1;'
        f'x.beginPath();x.arc(n.x,n.y,{dot_size},0,Math.PI*2);x.fillStyle="{_esc(colour)}";x.fill();}});'
        f'for(var i=0;i<nodes.length;i++)for(var j=i+1;j<nodes.length;j++){{'
        f'var dx=nodes[i].x-nodes[j].x,dy=nodes[i].y-nodes[j].y,'
        f'd=Math.sqrt(dx*dx+dy*dy);if(d<{max_dist}){{'
        f'x.beginPath();x.moveTo(nodes[i].x,nodes[i].y);x.lineTo(nodes[j].x,nodes[j].y);'
        f'x.strokeStyle="rgba(99,102,241,"+(1-d/{max_dist})+")";x.lineWidth=0.6;x.stroke();}}}}}})();}})();</script>'
        f'</div>'
    )
_RENDERERS["canvas_plexus"] = _render_canvas_plexus


# ─── brick_build_3d ───────────────────────────────────────────────────────────
# Hand-kept twin of the `_RENDERERS['brick_build_3d']` shell in
# apps-script-surface/gas-wired-renderer/atoms_brick.gs. The 500-line engine and the page wiring are NOT
# copied: _brickKit and _brickMount are read out of that file at render time, so the browser code has one
# source. What is duplicated is only the prop sanitising and the ~10-line HTML shell, with JavaScript's
# number semantics (Number(), parseInt()) reproduced by the two helpers below.
# tests/test_brick_web_twin.py renders the same props through Node (the real .gs) and through this function
# and compares the output modulo the uid. Edit BOTH.
_BRICK_GS = Path(__file__).resolve().parent.parent / "apps-script-surface" / "gas-wired-renderer" / "atoms_brick.gs"
_BRICK_SHAPES = ("heart", "sphere", "torus", "helix", "pyramid", "house")
_BRICK_MAX = 3000
_BRICK_MODELS_MAX = 8
_brick_src_cache: Dict[str, str] = {}
_JS_NUM = re.compile(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$')
_JS_INT = re.compile(r'^\s*([+-]?\d+)')
_BRICK_HEX6 = re.compile(r'^#[0-9a-fA-F]{6}$')
_BRICK_HEXBG = re.compile(r'^#[0-9a-fA-F]{3,8}$')


def _brick_fn_src(name: str) -> str:
    """Source text of a top-level function in atoms_brick.gs (what Function.prototype.toString returns)."""
    if name not in _brick_src_cache:
        m = re.search(r'^function %s\(.*?\) \{.*?^\}' % re.escape(name), _BRICK_GS.read_text(encoding="utf-8"),
                      re.S | re.M)
        if not m:
            raise RuntimeError("brick_build_3d: function %s not found in %s" % (name, _BRICK_GS))
        _brick_src_cache[name] = m.group(0)
    return _brick_src_cache[name]


# Twin of atoms_brick.gs's `var LEGO_MATERIAL_PROFILE = {...}` (~L41) -- edit BOTH. _brickKit's text is
# extracted via _brick_fn_src (what Function.prototype.toString returns), which does NOT carry along a
# module-level constant it closes over, so the real .gs shell re-declares it via JSON.stringify(the live
# value) at the embed site rather than re-deriving it here; this dict + json.dumps(..., separators) must
# byte-for-byte match that JSON.stringify output (key order and all) for tests/test_brick_web_twin.py to
# pass. Found live 2026-09-29: without this, every brick_build_3d render (e.g. the public design page)
# threw "LEGO_MATERIAL_PROFILE is not defined" inside the iframe it's mounted into, and rendered nothing.
_LEGO_MATERIAL_PROFILE = {"BH": 1.2, "PL": 0.4, "SR": 0.3, "SH": 0.18, "SN": 10, "studs": True}


def _brick_material_profile_src() -> str:
    return "var LEGO_MATERIAL_PROFILE = " + _js_json(_LEGO_MATERIAL_PROFILE, separators=(",", ":")) + ";"


def _js_number(v):
    """JavaScript Number(v) for JSON scalars; nan when it would be NaN."""
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        try:
            return float(v)
        except OverflowError:
            return float("nan")
    if isinstance(v, str):
        t = v.strip()
        if t == "":
            return 0.0
        return float(t) if _JS_NUM.match(t) else float("nan")
    return float("nan")


def _js_parse_int(v):
    """JavaScript parseInt(v, 10): the leading integer, or None when it would be NaN."""
    if v is None or isinstance(v, (bool, list, dict)):
        return None
    m = _JS_INT.match(v if isinstance(v, str) else (str(int(v)) if isinstance(v, float) and v.is_integer() else str(v)))
    return int(m.group(1)) if m else None


def _brick_clamp(v, lo, hi, dflt):
    n = _js_number(v)
    if n != n or n in (float("inf"), float("-inf")):
        return dflt
    return max(lo, min(hi, math.floor(n)))


def _brick_palette(lst):
    out = []
    if not isinstance(lst, list):
        return out
    for v in lst:
        if len(out) >= 256:
            break
        out.append(v.lower() if isinstance(v, str) and _BRICK_HEX6.match(v) else "#c91a09")
    return out


def _brick_sanitise(lst, palette=None):
    if not isinstance(lst, list) or not lst:
        return None
    out = []
    for r in lst:
        if len(out) >= _BRICK_MAX:
            break
        if isinstance(r, list) and len(r) in (6, 7):
            x, y, z, w, d = r[0], r[1], r[2], r[3], r[4]
            h, c = (r[5] if len(r) == 7 else 1), r[-1]
            present = lambda key: True                   # noqa: E731  (array form: every slot is present)
        elif isinstance(r, dict):
            x, y, z, w, d, h, c = (r.get(k) for k in ("x", "y", "z", "w", "d", "h", "c"))
            present = lambda key, r=r: key in r          # noqa: E731
        else:
            continue
        # a missing key is JS `undefined` (NaN -> default); an explicit null is Number(null) = 0
        def n(key, v, lo, hi, dflt, present=present):
            return _brick_clamp(v, lo, hi, dflt) if present(key) else dflt
        if isinstance(c, (int, float)) and not isinstance(c, bool) and math.isfinite(c) and palette:
            k = math.floor(c)
            c = palette[k] if 0 <= k < len(palette) else None
        c = c.lower() if isinstance(c, str) and _BRICK_HEX6.match(c) else "#c91a09"
        out.append({"x": n("x", x, 0, 255, 0), "y": n("y", y, 0, 255, 0), "z": n("z", z, 0, 255, 0),
                    "w": n("w", w, 1, 32, 1), "d": n("d", d, 1, 32, 1), "h": n("h", h, 1, 8, 1), "c": c})
    return out or None


# Same small, hand-picked LDConfig.ldr subset as PART_ROT's neighbour in atoms_brick.gs -- see spec section 1.4.
_LDRAW_COLOURS = {0: "#1b2a34", 1: "#0055bf", 2: "#237841", 4: "#c91a09", 14: "#f2cd37", 15: "#f4f4f4",
                  25: "#d67923", 71: "#969696", 72: "#646464", 191: "#fcac00",
                  19: "#e4cd9e", 27: "#bbe90b", 28: "#958a73", 70: "#582a12", 272: "#0d325b", 288: "#184632",
                  320: "#720e0f", 484: "#a95500"}
_LDRAW_EDGE = {0: "#808080"}
# Twin of PART_ID_ALIAS in atoms_brick.gs -- edit BOTH. Known LDraw ~Moved-to aliases for ids in the curated set
# (spec/brick-parts-v0.1.md §1.3/§6): the bake only wrote the canonical id's JSON, never the common/BrickLink id.
_PART_ID_ALIAS = {"3023": "3023b", "3665": "3665a", "3660": "3660a", "60481": "60481a", "4032": "4032a",
                  "2654": "2654a", "4073": "6141"}


def _brick_parts_model_sanitise(lst):
    """Twin of _partsModelSanitise in atoms_brick.gs -- edit BOTH. Array [id,x,y,z,r,c] / [...,step] or
    {p,x,y,z,r,c,s}; position is LDU, r wraps into 0..23, c is an LDraw colour code or '#rrggbb'."""
    if not isinstance(lst, list) or not lst:
        return None
    out = []
    for r in lst:
        if len(out) >= _BRICK_MAX:
            break
        if isinstance(r, list) and 6 <= len(r) <= 7:
            p, x, y, z, rot, c = r[0], r[1], r[2], r[3], r[4], r[5]
            step = r[6] if len(r) == 7 else None
        elif isinstance(r, dict):
            p, x, y, z, rot, c, step = r.get("p"), r.get("x"), r.get("y"), r.get("z"), r.get("r"), r.get("c"), r.get("s")
        else:
            continue
        if not isinstance(p, str) or not p:
            continue
        p = _PART_ID_ALIAS.get(p, p)
        code = math.floor(c) if isinstance(c, (int, float)) and not isinstance(c, bool) else None
        colour = c.lower() if isinstance(c, str) and _BRICK_HEX6.match(c) else (_LDRAW_COLOURS.get(code) or "#c91a09")
        edge = _LDRAW_EDGE.get(code) or "#333333"
        ri = _brick_clamp(rot, 0, 999999, 0) % 24
        entry = {"p": p, "x": _brick_clamp(x, -4000, 4000, 0), "y": _brick_clamp(y, -4000, 0, 0),
                 "z": _brick_clamp(z, -4000, 4000, 0), "r": ri, "c": colour, "edge": edge}
        if step is not None:   # JS `undefined` is OMITTED by JSON.stringify, not serialised as null -- match that
            entry["step"] = _brick_clamp(step, 1, 9999, 1)
        out.append(entry)
    return out or None


def _brick_models(lst, palette=None):
    out = []
    if not isinstance(lst, list):
        return out
    for m in lst:
        if len(out) >= _BRICK_MODELS_MAX:
            break
        if not isinstance(m, dict):
            continue
        pal = _brick_palette(m["palette"]) if isinstance(m.get("palette"), list) else palette
        bl = _brick_sanitise(m.get("bricks"), pal)
        if not bl:
            continue
        nm = m.get("name")
        nm = nm.strip()[:40] if isinstance(nm, str) else ""
        out.append({"name": nm or "Model %d" % (len(out) + 1), "bricks": bl})
    return out


def _render_brick_build_3d(b: dict) -> str:
    shape = b.get("shape") if b.get("shape") in _BRICK_SHAPES else "heart"
    h = _js_parse_int(b.get("height")) or 380
    h = max(160, min(900, h))
    step = max(1, _js_parse_int(b.get("step")) or 1)
    speed = 1
    if "speed" in b:
        sp = _js_number(b["speed"])
        if sp == sp and sp not in (float("inf"), float("-inf")):
            speed = max(0.1, min(4, sp))
            speed = int(speed) if float(speed).is_integer() else speed
    bg = b.get("bg")
    palette = _brick_palette(b.get("palette"))
    bricks = _brick_sanitise(b.get("bricks"), palette)
    models, start = _brick_models(b.get("models"), palette), -1
    if not bricks and isinstance(b.get("model"), str):
        for j, m in enumerate(models):
            if m["name"] == b["model"]:
                start = j
                break
        if start >= 0:
            bricks = models[start]["bricks"]
    # Real parts (spec/brick-parts-v0.1.md): a separate field from `bricks`, never mixed in v0.1, takes precedence
    # when present -- same "explicit wins" rule as bricks vs. shape above. Mirrors atoms_brick.gs's shell exactly.
    parts_model = _brick_parts_model_sanitise(b.get("partsModel"))
    cfg = {
        "shape": shape, "bricks": None if parts_model else bricks,
        "mode": "steps" if b.get("mode") == "steps" else "animate",
        "step": step, "speed": speed,
        "orbit": b.get("orbit") is not False,
        "bg": bg if isinstance(bg, str) and _BRICK_HEXBG.match(bg) else None,
        "scrubber": b.get("scrubber") is not False, "checks": b.get("checks") is not False,
        "parts": b.get("parts") is True,
        "models": [] if parts_model else models,
        "picker": False if parts_model else (False if b.get("picker") is False else (b.get("picker") is True or len(models) > 0)),
        "start": -1 if parts_model else start,
        "partsModel": parts_model,
        # "studio" product-shot shading vs the default "instructions" booklet-render style, plus an
        # optional baseplate override. Mirrors atoms_brick.gs's cfg exactly (same field names/semantics
        # as the sibling motion_bricks atom, which already declares both).
        "look": "studio" if b.get("look") == "studio" else "instructions",
        "base": "none" if b.get("base") == "none" else (b.get("base") if isinstance(b.get("base"), str) and _BRICK_HEXBG.match(b.get("base") or "") and len(b.get("base")) == 7 else None),
    }
    uid = "brk" + _wa_uid(b)[:6]
    payload = _js_json(cfg, separators=(",", ":"), ensure_ascii=False).replace("<", "\\u003c")
    return (
        '<div style="border-radius:14px;overflow:hidden;color:#0f1c28;'
        'font:13px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;'
        'background:radial-gradient(120% 90% at 50% 30%,#fafbfd,#cdd6e0);">'
        '<div style="position:relative;height:' + str(h) + 'px;">'
        '<canvas id="' + uid + 'c" role="img" aria-label="Animated 3D brick model" '
        'style="position:absolute;top:0;left:0;width:100%;height:100%;display:block;touch-action:pan-y;cursor:grab;"></canvas>'
        '</div>'
        '<div id="' + uid + 's" style="display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center;padding:8px 14px 0;"></div>'
        '<div id="' + uid + 'n" style="display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;padding:6px 14px 0;font-size:12px;"></div>'
        '<p id="' + uid + 'i" style="margin:0;padding:6px 14px 0;font-size:12px;color:#55636f;" hidden></p>'
        '<ul id="' + uid + 'k" style="list-style:none;margin:0;padding:8px 14px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:12px;"></ul>'
        '<div id="' + uid + 'p" style="overflow-x:auto;padding:0 14px 12px;"></div>'
        '</div>'
        '<script>(function(){' + _brick_material_profile_src() + 'var __atom = ('
        + _brick_fn_src("_brickMount") + ')((' + _brick_fn_src("_brickKit") + ')(),'
        + payload + ',"' + uid + '");'
        # Host control bridge, twin of atoms_brick.gs: the MCP Apps host posts {a2uiControl:1, action, value}.
        'window.addEventListener("message",function(e){var d=e.data;if(!d||d.a2uiControl!==1)return;'
        'if(d.action==="pause")__atom.set("speed",0);'
        'else if(d.action==="play"){__atom.setMode("animate");__atom.set("speed",1);}'
        'else if(d.action==="step"){__atom.set("speed",0);__atom.setMode("steps");__atom.setStep(+d.value||0);}'
        'else if(d.action==="replay")__atom.replay();'
        'else if(d.action==="resetView")__atom.resetView();'
        'else if(d.action==="recolor"&&d.value&&Array.isArray(d.value.idxs)&&/^#[0-9a-fA-F]{6}$/.test(d.value.to))__atom.recolor(d.value.to,d.value.idxs.filter(function(i){return Number.isInteger(i)&&i>=0;}));});'
        '})();</script>'
    )
_RENDERERS["brick_build_3d"] = _render_brick_build_3d


# ─── canvas hero kit + the flow_field / *_type family ────────────────────────
# 1:1 twin of apps-script-surface/gas-wired-renderer/atoms_canvas.gs's
