def _render_scramble_reveal(b: dict) -> str:
    text = _esc(b.get('text', ''))
    title = _esc(b.get('title', ''))
    import hashlib
    uid = 'scr' + hashlib.md5((text + title).encode()).hexdigest()[:5]
