def _render_progress_reveal(b: dict) -> str:
    if not isinstance(b, dict):
        return ""
    val_raw = _num_loose(b.get("value"))
    if val_raw is None:
        val_raw = _num_loose(b.get("percent"))
    value = val_raw if val_raw is not None else 0.0
    label = _first_text(b.get("label"), b.get("title"))
    color = _safe_css(b.get("color"), "#4f46e5")
    suffix_raw = b.get("suffix")
    suffix = _text_loose(suffix_raw) if suffix_raw is not None else "%"
    height_raw = _num_loose(b.get("height"))
    height = min(int(height_raw + 0.5), 400) if height_raw is not None and height_raw > 0 else 10
    uid = _wa_uid(b)
    prefix = f"pr-{uid}"
    ck_val = _first_text(b.get("label"), "progress_reveal")
    target_val = _text_loose(max(-1e15, min(value, 1e15)))
    label_html = (
        f'<span style="font-size:0.875rem;font-weight:600;color:#374151;">{_cv_esc(label)}</span>'
        if label else '<span></span>'
    )
    return (
        f'<div data-cb="node" data-key="{_cv_esc(ck_val)}" id="{prefix}-wrap" data-target="{_cv_esc(target_val)}" data-suffix="{_cv_esc(suffix)}" style="margin:1rem 0;">'
        f'<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px;">'
        f'{label_html}'
        f'<span id="{prefix}-val" aria-hidden="true" style="font-size:0.875rem;font-weight:700;color:{color};">0{_cv_esc(suffix)}</span>'
        f'<span style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;">{_cv_esc(target_val + suffix)}</span>'
        f'</div>'
        f'<div style="height:{height}px;background:#f3f4f6;border-radius:999px;overflow:hidden;">'
        f'<div id="{prefix}-bar" style="height:100%;width:0%;background:{color};border-radius:999px;transition:width 1.3s cubic-bezier(0.34,1.1,0.64,1);"></div>'
        f'</div>'
        f'<script>(function(){{'
        f'var wrap=document.getElementById("{prefix}-wrap");'
        f'var bar=document.getElementById("{prefix}-bar");'
        f'var val=document.getElementById("{prefix}-val");'
        f'if(!wrap||!bar||!val)return;'
        f'var target=Number(wrap.getAttribute("data-target"))||0;var suf=wrap.getAttribute("data-suffix")||"";var done=false;'
        f'var calm=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;'
        f'function run(){{if(done)return;done=true;'
        f'bar.style.width=Math.max(0,Math.min(target,100))+"%";'
        f'if(calm){{bar.style.transition="none";val.textContent=Math.round(target)+suf;return;}}'
        f'var t0=null,dur=1300;'
        f'function step(ts){{if(!t0)t0=ts;var p=Math.min((ts-t0)/dur,1);val.textContent=Math.round(target*p)+suf;if(p<1)requestAnimationFrame(step);}}'
        f'requestAnimationFrame(step);}}'
        f'if("IntersectionObserver" in window){{'
        f'new IntersectionObserver(function(es,ob){{if(es[0].isIntersecting){{run();ob.disconnect();}}}},{{threshold:0.3}}).observe(wrap);'
        f'}}else{{run();}}'
        f'}})();</script>'
        f'</div>'
    )


_RENDERERS["progress_reveal"] = _render_progress_reveal


def _render_progress_store(b: dict) -> str:
    course_id = _esc(b.get('course_id', 'default'))
    import hashlib
    uid = 'ps' + hashlib.md5(course_id.encode()).hexdigest()[:5]
    return ('<div id="' + uid + '" style="margin:1rem 0;padding:14px 18px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
            'border-radius:12px;border-radius:var(--a2ui-radius,12px);background:#fafafa;background:var(--a2ui-surface-muted,#fafafa);">'
            '<div style="display:flex;justify-content:space-between;font-size:0.82rem;'
            'color:#374151;margin-bottom:6px;">'
            '<span>Progress</span><span id="' + uid + 'pct">—</span></div>'
            '<div style="background:#e5e7eb;border-radius:99px;height:8px;">'
            '<div id="' + uid + 'bar" style="width:0%;height:100%;border-radius:99px;background:#4f46e5;'
            'transition:width 0.4s;"></div></div></div>'
            '<script>(function(){'
            "var key='a2ui_prog_" + course_id + "';"
            'var pct=parseFloat(localStorage.getItem(key)||0);'
            'var bar=document.getElementById("' + uid + 'bar");'
            'var lbl=document.getElementById("' + uid + 'pct");'
            'if(bar)bar.style.width=pct+"%";'
            'if(lbl)lbl.textContent=Math.round(pct)+"%";'
            '})();</script>')
_RENDERERS["progress_store"] = _render_progress_store


def _render_stagger_list(b: dict) -> str:
    raw_items = b.get('items') if isinstance(b.get('items'), list) else []
    direction = _text_loose(b.get('direction'))
    stagger_num = _num_loose(b.get('stagger'))
    if stagger_num is None:
        stagger_num = 0.1
    stagger_num = max(0.0, min(2.0, float(stagger_num)))

    uid = _wa_uid(b)[:6]
    if direction == 'left':
        start_t = 'translateX(-22px)'
    elif direction == 'right':
        start_t = 'translateX(22px)'
    elif direction == 'down':
        start_t = 'translateY(-14px)'
    else:
        start_t = 'translateY(16px)'

    css = (
        f'<style>'
        f'.sl-{uid}{{opacity:0;animation:sl-{uid} 0.45s ease both;}}'
        f'@keyframes sl-{uid}{{from{{opacity:0;transform:{start_t};}}to{{opacity:1;transform:none;}}}}'
        f'@media (prefers-reduced-motion:reduce){{.sl-{uid}{{opacity:1;animation:none;}}}}'
        f'</style>'
    )

    items_html = []
    count = 0
    for it in raw_items:
        if count >= 100:
            break
        if isinstance(it, str):
            dly_val = _gm.floor(count * stagger_num * 100 + 0.5) / 100
            dly_str = f'{dly_val:g}s'
            items_html.append(
                f'<div class="sl-{uid}" style="animation-delay:{dly_str};padding:10px 14px;'
                f'background:#fafafa;background:var(--a2ui-surface-muted,#fafafa);'
                f'border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);'
                f'border-radius:12px;border-radius:var(--a2ui-radius,12px);'
                f'font-size:0.9rem;color:#374151;">{_md_inline(it)}</div>'
            )
            count += 1
        elif isinstance(it, dict):
            dly_val = _gm.floor(count * stagger_num * 100 + 0.5) / 100
            dly_str = f'{dly_val:g}s'
            icon = _text_loose(it.get('icon')) or '•'
            text = _text_loose(it.get('text') if it.get('text') is not None else it.get('label'))
            sub = _text_loose(it.get('sub') if it.get('sub') is not None else it.get('description'))
            sub_html = f'<div style="font-size:0.8rem;color:var(--muted,#5f6368);margin-top:2px;">{_cv_esc(sub)}</div>' if sub else ''
            items_html.append(
                f'<div class="sl-{uid}" style="animation-delay:{dly_str};padding:12px 16px;background:#f9fafb;border:1px solid #e5e7eb;'
                f'border-radius:10px;display:flex;gap:12px;align-items:flex-start;">'
                f'<span style="font-size:1.2rem;flex-shrink:0;line-height:1.4;">{_cv_esc(icon)}</span>'
                f'<div><div style="font-size:0.9rem;font-weight:600;color:#111827;">{_cv_esc(text)}</div>'
                f'{sub_html}</div></div>'
            )
            count += 1

    return f'{css}<div style="margin:1rem 0;display:flex;flex-direction:column;gap:8px;">{"".join(items_html)}</div>'
_RENDERERS["stagger_list"] = _render_stagger_list


def _render_step_reveal_sequence(b: dict) -> str:
    raw = b.get('steps')
    steps = [s for s in raw[:50] if isinstance(s, dict) or _text_loose(s)] if isinstance(raw, list) else []
    if not steps:
        return ''
    uid = 'srs-' + _wa_uid(b)
    css = '<style>'
    for i in range(len(steps)):
        css += '#' + uid + '-' + str(i) + ':checked ~ .' + uid + '-nav .' + uid + '-lbl:nth-child(' + str(i + 1) + '){background:#4f46e5;color:#fff;border-color:#4f46e5;}'
        css += '#' + uid + '-' + str(i) + ':checked ~ .' + uid + '-body .' + uid + '-panel:nth-child(' + str(i + 1) + '){display:block;}'
        css += '#' + uid + '-' + str(i) + ':focus-visible ~ .' + uid + '-nav .' + uid + '-lbl:nth-child(' + str(i + 1) + '){outline:2px solid #4f46e5;outline-offset:2px;}'
    css += '.' + uid + '-panel{display:none;padding:20px;animation:' + uid + '-in 0.3s ease;}'
    css += '@keyframes ' + uid + '-in{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}'
    css += '@media (prefers-reduced-motion:reduce){.' + uid + '-panel{animation:none;}}'
    css += '</style>'
    parts = []
    for s in steps:
        if isinstance(s, dict):
            parts.append((_first_text(s.get('title')), _first_text(s.get('text'), s.get('content'), s.get('body'))))
        else:
            parts.append((_text_loose(s), ''))
    inputs = ''.join('<input type="radio" id="' + uid + '-' + str(i) + '" name="' + uid + '"' + (' checked' if i == 0 else '') + ' style="position:absolute;opacity:0;width:1px;height:1px;margin:0;">' for i in range(len(steps)))
    nav = ('<div class="' + uid + '-nav" style="display:flex;gap:6px;flex-wrap:wrap;padding:12px 16px;border-bottom:1px solid #e5e7eb;">'
           + ''.join('<label for="' + uid + '-' + str(i) + '" class="' + uid + '-lbl" style="cursor:pointer;padding:6px 14px;border-radius:20px;border:1px solid #eaeaea;border:1px solid var(--a2ui-border,#eaeaea);font-size:0.8rem;font-weight:600;color:var(--muted,#5f6368);transition:all 0.15s;">'
                     + str(i + 1) + (('. ' + _cv_esc(t)) if t else '') + '</label>' for i, (t, _x) in enumerate(parts))
           + '</div>')
    body = ('<div class="' + uid + '-body">'
            + ''.join('<div class="' + uid + '-panel">'
                      + ('<div style="font-size:1rem;font-weight:700;color:#111827;margin-bottom:10px;">' + _cv_esc(t) + '</div>' if t else '')
                      + ('<div style="color:#374151;line-height:1.7;">' + _md_inline(x) + '</div>' if x else '')
                      + '</div>' for t, x in parts)
            + '</div>')
    return (css + '<div role="radiogroup" aria-label="Steps" style="border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;margin:1rem 0;">' + inputs + nav + body + '</div>')


_RENDERERS["step_reveal_sequence"] = _render_step_reveal_sequence


