def _render_globe_3d(b: dict) -> str:
    """Orthographic globe on the d3-geo projection math (_geo_ortho + _geo_graticule, see the ports above). The
    graticule, pins and great-circle arcs are rendered SERVER-SIDE as an SVG (complete, settled, no script needed);
    the canvas on top is a progressive enhancement that re-draws the same scene from the same maths (drag, spin,
    pulses) and hides the SVG once it has painted. Colours are theme tokens: accent from --accent unless the
    payload sets `color`, backdrop from --bg. Reduced motion: no auto-spin, pulses or travelling dots; the canvas
    paints one settled frame and redraws only on drag."""
    size = int(_g3d_num(b.get('size')) or 300)
    color = b.get('color', b.get('colour'))
    color = color.strip() if isinstance(color, str) and color.strip() else None
    speed = _g3d_num(b.get('speed'))
    speed = 0.006 if speed is None else speed
    lines = max(2, min(int(_g3d_num(b.get('lines')) or 10), 60))
    earth = b.get('theme') == 'earth'
    dots, arcs = _g3d_data(b)
    import hashlib
    import json
    uid = 'g3d' + hashlib.md5(json.dumps([size, color, dots, arcs], sort_keys=True).encode()).hexdigest()[:6]
    cfg = _g3d_js({'color': color, 'speed': speed, 'lines': lines, 'earth': earth, 'dots': dots, 'arcs': arcs, 'size': size})
    foc = _geo_focus({'dots': dots, 'arcs': arcs})
    scene = _geo_globe_scene({'lines': lines, 'dots': dots, 'arcs': arcs}, [-foc[0], -foc[1], 0], size)
    svg = _geo_svg_globe(scene, _geo_col(color, 'var(--accent,#4f46e5)'), earth, uid)
    js = (
        '(function(){'
        'var c=document.getElementById("' + uid + '");if(!c)return;'
        'var C=' + cfg + ';var x=c.getContext("2d");if(!x)return;'
        'var G=(' + _GEO_LIB_JS + ')();var sv=document.getElementById("' + uid + 's");'
        'var col=C.color||(getComputedStyle(c).getPropertyValue("--accent").trim())||"#4f46e5";'
        'var S=C.size,k=c.width/S,f=G.focus(C),aY=-f[0]*G.D2R,aX=f[1]*G.D2R,shown=false;'
        'var RM=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;'
        'var spd=RM?0:C.speed,drag=false,lx=0,ly=0,vx=0,vy=0;'
        'function draw(){'
        'if(!drag){aY+=spd+vx;aX+=vy;vx*=0.94;vy*=0.94;}'
        'aX=Math.max(-1.4,Math.min(1.4,aX));var now=Date.now();'
        'var sc=G.globeScene(C,[aY*G.R2D,-aX*G.R2D,0],S,RM?null:now);'
        'x.save();x.scale(k,k);G.paintGlobe(x,sc,col,C.earth,RM,now);x.restore();'
        'if(sv&&!shown){sv.style.visibility="hidden";shown=true;}'
        'if(!RM)requestAnimationFrame(draw);}'
        'c.addEventListener("mousedown",function(e){drag=true;lx=e.clientX;ly=e.clientY;c.style.cursor="grabbing";});'
        'document.addEventListener("mouseup",function(){drag=false;c.style.cursor="grab";});'
        'document.addEventListener("mousemove",function(e){if(!drag)return;vx=(e.clientX-lx)*0.012;vy=(e.clientY-ly)*0.012;'
        'aY+=vx;aX+=vy;lx=e.clientX;ly=e.clientY;if(RM)draw();});'
        'draw();})();'
    )
    return ('<div style="display:flex;justify-content:center;margin:1rem 0;">'
            '<div style="position:relative;width:' + str(size) + 'px;height:' + str(size) + 'px;border-radius:50%;background:var(--bg,#0a0a1a);">'
            + svg +
            '<canvas role="img" aria-label="Rotating 3D globe" id="' + uid + '" width="' + str(size) + '" height="' + str(size) + '" '
            'style="position:absolute;inset:0;border-radius:50%;cursor:grab;"></canvas></div>'
            + _g3d_alt_html(b) + '</div><script>' + js + '</script>')

_RENDERERS["globe_3d"] = _render_globe_3d


# ── spring_nodes ──────────────────────────────────────────────────────────────
# A settled force-directed graph, laid out server-side and drawn as a static SVG (no script, no physics at runtime, no CDN).
# The layout is a line-for-line port of d3-force 3.0.0 (ISC, Mike Bostock) with d3-quadtree 3.0.1: forceLink + forceManyBody (Barnes-Hut) + forceCenter,
# d3's own phyllotaxis start and LCG random source, run for a FIXED number of ticks, so the same payload always gives the same picture.
# Twin of _snLayout in apps-script-surface/*/atoms_canvas.gs; checked against the real library by tests/test_spring_nodes_force.py.
_SN_TICKS, _SN_CHARGE, _SN_MAX_NODES = 300, -300, 120


class _SnQ:
    __slots__ = ("c", "data", "next", "x", "y", "value")

    def __init__(self, c=None):
        self.c = c
        self.data = None
        self.next = None
        self.x = self.y = self.value = 0


class _SnTree:
    def __init__(self, nodes):
        nan = float("nan")
        self.x0 = self.y0 = self.x1 = self.y1 = nan
        self.root = None
        n = len(nodes)
        xz, yz = [0.0] * n, [0.0] * n
        x0 = y0 = float("inf")
        x1 = y1 = float("-inf")
        for i, d in enumerate(nodes):
            x, y = d["x"], d["y"]
            if x != x or y != y:
                continue
            xz[i], yz[i] = x, y
            if x < x0: x0 = x
            if x > x1: x1 = x
            if y < y0: y0 = y
            if y > y1: y1 = y
        if x0 > x1 or y0 > y1:
            return
        self.cover(x0, y0)
        self.cover(x1, y1)
        for i in range(n):
            self.add(xz[i], yz[i], nodes[i])

    def cover(self, x, y):
        if x != x or y != y:
            return
        x0, y0, x1, y1 = self.x0, self.y0, self.x1, self.y1
        if x0 != x0:
            x0 = math.floor(x)
            x1 = x0 + 1
            y0 = math.floor(y)
            y1 = y0 + 1
        else:
            z = (x1 - x0) or 1
            node = self.root
            while x0 > x or x >= x1 or y0 > y or y >= y1:
                i = (int(y < y0) << 1) | int(x < x0)
                parent = _SnQ([None, None, None, None])
                parent.c[i] = node
                node = parent
                z *= 2
                if i == 0: x1 = x0 + z; y1 = y0 + z
                elif i == 1: x0 = x1 - z; y1 = y0 + z
                elif i == 2: x1 = x0 + z; y0 = y1 - z
                else: x0 = x1 - z; y0 = y1 - z
            if self.root is not None and self.root.c is not None:
                self.root = node
        self.x0, self.y0, self.x1, self.y1 = x0, y0, x1, y1

    def add(self, x, y, d):
        parent = None
        node = self.root
        leaf = _SnQ()
        leaf.data = d
        x0, y0, x1, y1 = self.x0, self.y0, self.x1, self.y1
        if node is None:
            self.root = leaf
            return
        i = 0
        while node.c is not None:
            xm = (x0 + x1) / 2
            right = x >= xm
            if right: x0 = xm
            else: x1 = xm
            ym = (y0 + y1) / 2
            bottom = y >= ym
            if bottom: y0 = ym
            else: y1 = ym
            parent = node
            i = (int(bottom) << 1) | int(right)
            node = node.c[i]
            if node is None:
                parent.c[i] = leaf
                return
        xp, yp = node.data["x"], node.data["y"]
        if x == xp and y == yp:
            leaf.next = node
            if parent is not None: parent.c[i] = leaf
            else: self.root = leaf
            return
        while True:
            made = _SnQ([None, None, None, None])
            if parent is not None: parent.c[i] = made
            else: self.root = made
            parent = made
            xm = (x0 + x1) / 2
            right = x >= xm
            if right: x0 = xm
            else: x1 = xm
            ym = (y0 + y1) / 2
            bottom = y >= ym
            if bottom: y0 = ym
            else: y1 = ym
            i = (int(bottom) << 1) | int(right)
            j = (int(yp >= ym) << 1) | int(xp >= xm)
            if i != j:
                break
        parent.c[j] = node
        parent.c[i] = leaf

    def visit_after(self, cb):
        quads, nxt = [], []
        if self.root is not None:
            quads.append((self.root, self.x0, self.y0, self.x1, self.y1))
        while quads:
            q = quads.pop()
            node = q[0]
            if node.c is not None:
                x0, y0, x1, y1 = q[1], q[2], q[3], q[4]
                xm, ym = (x0 + x1) / 2, (y0 + y1) / 2
                ch = node.c
                if ch[0] is not None: quads.append((ch[0], x0, y0, xm, ym))
                if ch[1] is not None: quads.append((ch[1], xm, y0, x1, ym))
                if ch[2] is not None: quads.append((ch[2], x0, ym, xm, y1))
                if ch[3] is not None: quads.append((ch[3], xm, ym, x1, y1))
            nxt.append(q)
        while nxt:
            q = nxt.pop()
            cb(q[0])

    def visit(self, cb):
        quads = []
        if self.root is not None:
            quads.append((self.root, self.x0, self.y0, self.x1, self.y1))
        while quads:
            node, x0, y0, x1, y1 = quads.pop()
            if not cb(node, x0, x1) and node.c is not None:
                xm, ym = (x0 + x1) / 2, (y0 + y1) / 2
                ch = node.c
                if ch[3] is not None: quads.append((ch[3], xm, ym, x1, y1))
                if ch[2] is not None: quads.append((ch[2], x0, ym, xm, y1))
                if ch[1] is not None: quads.append((ch[1], xm, y0, x1, ym))
                if ch[0] is not None: quads.append((ch[0], x0, y0, xm, ym))


def _sn_layout(n, links, dist, charge, ticks):
    """d3-force 3.0.0: forceSimulation + forceLink(distance=dist) + forceManyBody(strength=charge) + forceCenter(0, 0), `ticks` ticks, no initial x/y."""
    state = [1]

    def random():
        state[0] = (1664525 * state[0] + 1013904223) % 4294967296
        return state[0] / 4294967296

    def jiggle():
        return (random() - 0.5) * 1e-6

    angle = math.pi * (3 - math.sqrt(5))
    nodes = []
    for i in range(n):
        radius = 10 * math.sqrt(0.5 + i)
        a = i * angle
        nodes.append({"index": i, "x": radius * math.cos(a), "y": radius * math.sin(a), "vx": 0.0, "vy": 0.0})
    m = len(links)
    count = [0] * n
    for s, t in ((L[0], L[1]) for L in links):
        count[s] += 1
        count[t] += 1
    bias = [count[L[0]] / (count[L[0]] + count[L[1]]) for L in links]
    strengths = [1 / min(count[L[0]], count[L[1]]) for L in links]
    alpha_min = 0.001
    alpha_decay = 1 - math.pow(alpha_min, 1 / 300)
    alpha = 1.0
    velocity_decay = 1 - 0.4
    theta2 = 0.9 * 0.9
    distance_min2 = 1
    cstr = float(charge)
    cur = [None]
    al = [1.0]

    def link_force(a):
        for j in range(m):
            source, target = nodes[links[j][0]], nodes[links[j][1]]
            x = target["x"] + target["vx"] - source["x"] - source["vx"]
            if x == 0: x = jiggle()
            y = target["y"] + target["vy"] - source["y"] - source["vy"]
            if y == 0: y = jiggle()
            l = math.sqrt(x * x + y * y)
            l = (l - dist) / l * a * strengths[j]
            x *= l
            y *= l
            b = bias[j]
            target["vx"] -= x * b
            target["vy"] -= y * b
            b = 1 - b
            source["vx"] += x * b
            source["vy"] += y * b

    def accumulate(quad):
        strength = 0
        if quad.c is not None:
            weight = 0
            x = y = 0
            for j in range(4):
                q = quad.c[j]
                if q is not None:
                    c = abs(q.value)
                    if c:
                        strength += q.value
                        weight += c
                        x += c * q.x
                        y += c * q.y
            quad.x = x / weight
            quad.y = y / weight
        else:
            quad.x = quad.data["x"]
            quad.y = quad.data["y"]
            q = quad
            while True:
                strength += cstr
                q = q.next
                if q is None:
                    break
        quad.value = strength

    def apply(quad, x1, x2):
        node, a = cur[0], al[0]
        if not quad.value:
            return True
        x = quad.x - node["x"]
        y = quad.y - node["y"]
        w = x2 - x1
        l = x * x + y * y
        if w * w / theta2 < l:
            if x == 0:
                x = jiggle()
                l += x * x
            if y == 0:
                y = jiggle()
                l += y * y
            if l < distance_min2:
                l = math.sqrt(distance_min2 * l)
            node["vx"] += x * quad.value * a / l
            node["vy"] += y * quad.value * a / l
            return True
        elif quad.c is not None:
            return False
        if quad.data is not node or quad.next is not None:
            if x == 0:
                x = jiggle()
                l += x * x
            if y == 0:
                y = jiggle()
                l += y * y
            if l < distance_min2:
                l = math.sqrt(distance_min2 * l)
        while True:
            if quad.data is not node:
                w = cstr * a / l
                node["vx"] += x * w
                node["vy"] += y * w
            quad = quad.next
            if quad is None:
                break
        return False

    def charge_force(a):
        tree = _SnTree(nodes)
        tree.visit_after(accumulate)
        al[0] = a
        for j in range(n):
            cur[0] = nodes[j]
            tree.visit(apply)

    def center_force():
        sx = sy = 0.0
        for nd in nodes:
            sx += nd["x"]
            sy += nd["y"]
        sx = (sx / n - 0) * 1
        sy = (sy / n - 0) * 1
        for nd in nodes:
            nd["x"] -= sx
            nd["y"] -= sy

    for _ in range(ticks):
        alpha += (0 - alpha) * alpha_decay
        link_force(alpha)
        charge_force(alpha)
        center_force()
        for nd in nodes:
            nd["vx"] *= velocity_decay
            nd["x"] += nd["vx"]
            nd["vy"] *= velocity_decay
            nd["y"] += nd["vy"]
    return [[d["x"], d["y"]] for d in nodes]


_SN_COLOUR_RE = re.compile(r'^(#[0-9a-fA-F]{3}|#[0-9a-fA-F]{6}|#[0-9a-fA-F]{8}|[a-zA-Z]{3,20}|(?:rgb|hsl)a?\([0-9., %]{1,40}\))$')


def _sn_colour(v, dflt):
    return v.strip() if isinstance(v, str) and _SN_COLOUR_RE.match(v.strip()) else dflt


def _sn_lum(h):
    m = re.match(r'^#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})', h)
    if not m:
        return 0.0
    t = m.group(1)
    if len(t) == 3:
        t = ''.join(ch * 2 for ch in t)
    lum = 0.0
    for k, w in zip((0, 2, 4), (0.2126, 0.7152, 0.0722)):
        c = int(t[k:k + 2], 16) / 255
        lum += w * (c / 12.92 if c <= 0.03928 else math.pow((c + 0.055) / 1.055, 2.4))
    return lum


def _sn_f(v):
    return '%.2f' % (math.floor(v * 100 + 0.5) / 100)


