# ─── fourth batch from a brand film (2026-10-12): capsule, arrow, swatches, glass, wall, tag. Twins of the last block of atoms_motion_candidates.gs ───
_M4_WS = '[ \t\n\r\f\v   -     　﻿]+'


def _m4_grow(k, chars, pad):
    return 'max-width:max(calc(' + k + '*' + _if_fmt(chars * 0.7 + pad) + 'em),calc((' + k + ' - 0.999)*1000000px));'


_CP_LOOK = {'outline': 'outline', 'solid': 'solid', 'glass': 'glass'}
_CP_RES = {'fade': 'fade', 'blur': 'blur', 'scramble': 'scramble'}
_CP_NOISE = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#%&*+=?'


def _render_motion_capsule(b: dict) -> str:
    words = [w for w in re.split(_M4_WS, _cv_str(b.get('text'), 120)) if w][:12]
    if not words:
        words = ['Text']
    n = len(words)
    look, res = _ff_pick(b.get('style'), _CP_LOOK, 'outline'), _ff_pick(b.get('resolve'), _CP_RES, 'blur')
    size, seed = _ff_int(b.get('size'), 22, 12, 64), _ff_int(b.get('seed'), 5, 0, 999)
    ink = _mo_ink(b, 'color', '#0f172a' if b.get('tone') == 'dark' else '#ffffff')
    if look == 'outline':
        box = 'border:1.5px solid ' + ink + ';'
    elif look == 'solid':
        box = 'background:' + ink + '22;border:1.5px solid ' + ink + '55;'
    else:
        box = 'background:' + ink + '1a;border:1px solid ' + ink + '40;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);'
    inner = ''
    for i, w in enumerate(words):
        k = 'clamp(0,calc(var(--p,1)*' + str(n + 1) + ' - ' + str(i) + '),1)'
        pad = '0.3em' if i else '0'
        noise = ''
        if res == 'scramble':
            nz = ''.join(_CP_NOISE[math.floor(_bx_seed(seed, i, j) * len(_CP_NOISE))] for j in range(len(w)))
            noise = '<span aria-hidden="true" style="position:absolute;left:' + pad + ';top:0;opacity:calc(1 - var(--ci));">' + _cv_esc(nz) + '</span>'
        inner += ('<span style="--ci:' + k + ';position:relative;display:inline-block;vertical-align:bottom;overflow:hidden;white-space:nowrap;padding-left:' + pad + ';' + _m4_grow('var(--ci)', len(w), 0.3 if i else 0)
                  + 'opacity:var(--ci);' + ('filter:blur(calc((1 - var(--ci))*5px));' if res == 'blur' else '') + '">' + _cv_esc(w) + noise + '</span>')
    return ('<span style="display:inline-block;box-sizing:border-box;padding:0.32em 0.95em;border-radius:999px;font-size:' + str(size) + 'px;line-height:1.25;color:' + ink + ';white-space:nowrap;' + box + 'opacity:clamp(0,calc(var(--p,1)*8),1);">' + inner + '</span>')


def _render_motion_arrow(b: dict) -> str:
    ang = [_ff_int(a, 0, -720, 720) for a in _m3_list(b.get('angles'), 6)] or [0]
    m = len(ang)
    size, wt = _ff_int(b.get('size'), 64, 12, 400), _ff_int(b.get('weight'), 3, 1, 12)
    col = _mo_ink(b, 'color', 'currentColor')
    solid, inl = b.get('style') == 'solid', b.get('inline') is True
    label = _cv_str(b.get('label'), 60) or 'Arrow'
    terms = ''.join(' + ' + str(ang[i + 1] - ang[i]) + '*clamp(0,calc(var(--s,1)*' + str(m - 1) + ' - ' + str(i) + '),1)' for i in range(m - 1))
    shaft = 'stroke-dasharray:1;stroke-dashoffset:calc(1 - clamp(0,calc(var(--p,1)*1.6),1));'
    head = 'stroke-dasharray:1;stroke-dashoffset:calc(1 - clamp(0,calc(var(--p,1)*1.6 - 0.6),1));'
    return ('<svg role="img" aria-label="' + _cv_esc(label) + '" viewBox="0 0 64 32" width="' + str(size) + '" height="' + str(_m3_round(size / 2)) + '" style="display:' + ('inline-block;vertical-align:-0.15em' if inl else 'block')
            + ';overflow:visible;transform:rotate(calc(1deg*(' + str(ang[0]) + terms + ')));transform-origin:50% 50%;" focusable="false">'
            '<path d="M4 16H58" pathLength="1" fill="none" stroke="' + col + '" stroke-width="' + str(wt) + '" stroke-linecap="round" style="' + shaft + '"/>'
            + (('<path d="M44 5L60 16L44 27Z" fill="' + col + '" stroke="' + col + '" stroke-width="' + str(wt) + '" stroke-linejoin="round" style="opacity:clamp(0,calc(var(--p,1)*1.6 - 0.6),1);"/>') if solid
               else ('<path d="M44 5L59 16L44 27" pathLength="1" fill="none" stroke="' + col + '" stroke-width="' + str(wt) + '" stroke-linecap="round" stroke-linejoin="round" style="' + head + '"/>')) + '</svg>')


_SW_LAYOUT = {'grid': 'grid', 'row': 'row', 'stack': 'stack'}


def _sw_ink(hexc):
    c = []
    for i in (1, 3, 5):
        v = int(hexc[i:i + 2], 16) / 255
        c.append(v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4)
    lum = 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
    return '#ffffff' if (1.05 / (lum + 0.05)) >= ((lum + 0.05) / 0.05) else '#000000'


def _render_motion_swatches(b: dict) -> str:
    sw = []
    for i, raw in enumerate(_m3_list(b.get('swatches'), 6)):
        o = _m3_obj(raw)
        sw.append({'name': _cv_str(o.get('name'), 20) or ('Colour ' + str(i + 1)), 'hex': _ff_hex(o.get('hex'), _CL_FILLS[i % 8])})
    while len(sw) < 2:
        sw.append({'name': 'Colour ' + str(len(sw) + 1), 'hex': _CL_FILLS[len(sw) % 8]})
    n = len(sw)
    lay = _ff_pick(b.get('layout'), _SW_LAYOUT, 'grid')
    cols = n if lay == 'row' else (1 if lay == 'stack' else (n if n <= 2 else 2))
    asp, gap, rad = _ff_num(b.get('aspect'), 1.78, 0.5, 3, 2), _ff_int(b.get('gap'), 0, 0, 24), _ff_int(b.get('radius'), 0, 0, 40)
    dirs = ['translate(calc((1 - var(--k))*-100%),0)', 'translate(0,calc((1 - var(--k))*-100%))', 'translate(calc((1 - var(--k))*100%),0)', 'translate(0,calc((1 - var(--k))*100%))']
    lis = ''
    for j, s in enumerate(sw):
        ink = _sw_ink(s['hex'])
        lis += ('<li style="--k:clamp(0,calc(var(--p,1)*' + str(n + 1) + ' - ' + str(j) + '),1);position:relative;box-sizing:border-box;padding:6% 7%;display:flex;flex-direction:column;justify-content:space-between;background:' + s['hex'] + ';color:' + ink + ';border-radius:' + str(rad)
                + 'px;overflow:hidden;transform:' + dirs[j % 4] + ';opacity:clamp(0,calc(var(--k)*4),1);"><span style="font-size:0.85em;font-weight:700;">' + _cv_esc(s['name']) + '</span><span style="font-size:0.7em;letter-spacing:0.04em;opacity:0.85;">' + s['hex'].upper() + '</span></li>')
    return ('<ul style="list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(' + str(cols) + ',1fr);grid-auto-rows:1fr;gap:' + str(gap) + 'px;width:100%;aspect-ratio:' + asp + ';overflow:hidden;border-radius:' + str(rad) + 'px;font-size:clamp(11px,2.2cqw,22px);container-type:inline-size;">' + lis + '</ul>')


def _render_motion_glass(b: dict) -> str:
    blocks = _m3_list(b.get('blocks'), 6)
    inner = ''.join(_mo_child(x) for x in blocks)
    blur, tint = _ff_int(b.get('blur'), 18, 2, 40), _ff_hex(b.get('tint'), '#ffffff')
    st, rad, pad = _ff_num(b.get('strength'), 0.14, 0.05, 0.6, 2), _ff_int(b.get('radius'), 18, 0, 40), _ff_int(b.get('padding'), 18, 0, 48)
    return ('<div style="--k:clamp(0,var(--p,1),1);position:relative;box-sizing:border-box;padding:' + str(pad) + 'px;border-radius:' + str(rad) + 'px;background:rgba(' + _ff_rgb(tint) + ',calc(' + st + '*var(--k)));'
            'backdrop-filter:blur(calc(var(--k)*' + str(blur) + 'px)) saturate(1.15);-webkit-backdrop-filter:blur(calc(var(--k)*' + str(blur) + 'px)) saturate(1.15);'
            + ('' if b.get('edge') is False else 'border:1px solid rgba(255,255,255,calc(0.4*var(--k)));') + 'box-shadow:0 8px 32px rgba(0,0,0,calc(0.18*var(--k)));opacity:var(--k);transform:scale(calc(0.96 + 0.04*var(--k)));">' + inner + '</div>')


def _render_motion_wall(b: dict) -> str:
    cols, rows = _ff_int(b.get('cols'), 6, 2, 10), _ff_int(b.get('rows'), 3, 1, 6)
    gap, rad, seed = _ff_int(b.get('gap'), 8, 0, 24), _ff_int(b.get('radius'), 8, 0, 24), _ff_int(b.get('seed'), 3, 0, 999)
    asp = _ff_num(b.get('aspect'), 1.78, 0.5, 3, 2)
    n = cols * rows
    imgs = []
    for v in _m3_list(b.get('images'), 24):
        imgs.append(_mo_img(v.get('url') if isinstance(v, dict) else ('' if isinstance(v, list) else v)))
    idx = sorted(range(n), key=lambda i: (_bx_seed(seed, i, 9), i))
    rank = {t: r for r, t in enumerate(idx)}
    out = ''
    for i in range(n):
        im = imgs[i % len(imgs)] if imgs else ''
        pic = ('<img src="' + _cv_esc(im) + '" alt="" loading="lazy" referrerpolicy="no-referrer" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;">') if im else ''
        out += ('<span style="--b:clamp(0,calc(var(--p,1)*' + str(n + 3) + ' - ' + str(i) + '),1);--v:clamp(0,calc(1 - (1 - var(--s,1))*' + str(n + 3) + ' + ' + str(rank[i]) + '),1);position:relative;display:block;overflow:hidden;border-radius:' + str(rad) + 'px;background:' + _CL_FILLS[(i + seed) % 8]
                + ';opacity:calc(var(--b)*var(--v));transform:scale(calc(0.8 + 0.2*var(--b)*var(--v)));">' + pic + '</span>')
    named = isinstance(b.get('label'), str) and b.get('label')
    return ('<div ' + ('role="img" aria-label="' + _cv_esc(_cv_str(b.get('label'), 60)) + '"' if named else 'aria-hidden="true"') + ' style="display:grid;grid-template-columns:repeat(' + str(cols) + ',1fr);grid-auto-rows:1fr;gap:' + str(gap) + 'px;width:100%;aspect-ratio:' + asp + ';overflow:hidden;pointer-events:none;">' + out + '</div>')


_TG_TONE = {'dark': 'dark', 'light': 'light', 'accent': 'accent'}


def _render_motion_tag(b: dict) -> str:
    text = _cv_str(b.get('text'), 24) or 'Label'
    f, t = _m3_obj(b.get('from')), _m3_obj(b.get('to'))
    size, tone = _ff_int(b.get('size'), 20, 12, 40), _ff_pick(b.get('tone'), _TG_TONE, 'dark')
    acc, asp = _mo_ink(b, 'accent', '#ffd166'), _ff_num(b.get('aspect'), 1.78, 0.5, 3, 2)
    fx, fy, tx, ty = _ff_num(f.get('x'), 20, 0, 100, 1), _ff_num(f.get('y'), 30, 0, 100, 1), _ff_num(t.get('x'), 55, 0, 100, 1), _ff_num(t.get('y'), 55, 0, 100, 1)
    mv, gr = 'clamp(0,calc(var(--p,1)*2.2),1)', 'clamp(0,calc((var(--p,1) - 0.45)/0.55),1)'
    bg = '#ffffff' if tone == 'light' else (acc if tone == 'accent' else '#111111')
    ink = '#ffffff' if tone == 'dark' else '#111111'
    return ('<div style="position:relative;width:100%;aspect-ratio:' + asp + ';font-size:' + str(size) + 'px;"><div style="--t:' + gr + ';position:absolute;left:calc(' + fx + '% + (' + _if_fmt(float(tx) - float(fx)) + '%)*' + mv + ');top:calc(' + fy + '% + (' + _if_fmt(float(ty) - float(fy)) + '%)*' + mv
            + ');transform:translate(0,-50%);display:flex;align-items:center;gap:0.45em;white-space:nowrap;"><span aria-hidden="true" style="width:0.7em;height:0.7em;border-radius:50%;background:' + acc + ';flex:none;opacity:clamp(0,calc(var(--p,1)*10),1);"></span>'
            '<span style="display:inline-block;overflow:hidden;box-sizing:border-box;padding:0.28em calc(var(--t)*0.95em);border-radius:999px;background:' + bg + ';color:' + ink + ';line-height:1.2;' + _m4_grow('var(--t)', len(text), 1.9) + 'opacity:var(--t);">' + _cv_esc(text) + '</span></div></div>')


for _m4_name, _m4_fn in (('motion_capsule', _render_motion_capsule), ('motion_arrow', _render_motion_arrow), ('motion_swatches', _render_motion_swatches), ('motion_glass', _render_motion_glass), ('motion_wall', _render_motion_wall), ('motion_tag', _render_motion_tag)):
    _RENDERERS[_m4_name] = _m4_fn


# ─── fifth batch from two motion-designer showreels (2026-10-12): ring, highlight, meters, discs. Twins of the last block of atoms_motion_candidates.gs ───
def _render_motion_ring(b: dict) -> str:
    text = _cv_str(b.get('text'), 40) or 'Text'
    base = list(text + ' · ')
    chars = []
    while len(chars) < 36:
        chars = chars + base
    chars = chars[:min(120, len(chars))]
    n = len(chars)
    size, turns, disc = _ff_int(b.get('size'), 360, 120, 800), _ff_int(b.get('turns'), 1, -4, 4), _ff_int(b.get('disc'), 52, 20, 80)
    fs = _ff_num(b.get('font_size'), 15, 8, 30, 1)
    col, fill = _mo_ink(b, 'color', 'currentColor'), _mo_ink(b, 'fill', '#7c3aed')
    font, weight, img = _ff_pick(b.get('font'), _FF_FONTS, 'sans'), _ff_pick(b.get('weight'), _FF_WEIGHTS, 'bold'), _mo_img(b.get('image'))
    out = ''.join('<text x="100" y="22" text-anchor="middle" transform="rotate(' + _if_fmt(i * 360 / n) + ' 100 100)">' + _cv_esc(c) + '</text>' for i, c in enumerate(chars) if c != ' ')
    return ('<div role="img" aria-label="' + _cv_esc(text) + '" style="position:relative;width:min(100%,' + str(size) + 'px);aspect-ratio:1;margin:0 auto;">'
            '<svg aria-hidden="true" focusable="false" viewBox="0 0 200 200" style="position:absolute;inset:0;width:100%;height:100%;overflow:visible;opacity:clamp(0,calc((var(--p,1) - 0.15)*3),1);transform:rotate(calc(var(--s,1)*' + str(turns * 360)
            + 'deg)) scale(calc(0.85 + 0.15*clamp(0,var(--p,1),1)));font-family:' + font + ';font-weight:' + weight + ';font-size:' + fs + 'px;fill:' + col + ';">' + out + '</svg>'
            '<div aria-hidden="true" style="position:absolute;left:50%;top:50%;width:' + str(disc) + '%;aspect-ratio:1;border-radius:50%;overflow:hidden;background:' + fill + ';transform:translate(-50%,-50%) scale(clamp(0,calc(var(--p,1)*3),1));">'
            + (('<img src="' + _cv_esc(img) + '" alt="" loading="lazy" referrerpolicy="no-referrer" style="width:100%;height:100%;object-fit:cover;display:block;">') if img else '') + '</div></div>')


_HL_LOOK = {'marker': ['0.1em', '0.04em', '-1deg'], 'underline': ['0.72em', '-0.02em', '0deg'], 'strike': ['0.46em', '0.4em', '0deg']}


def _render_motion_highlight(b: dict) -> str:
    text = _cv_str(b.get('text'), 80) or 'Text'
    look = _ff_pick(b.get('style'), {'marker': 'marker', 'underline': 'underline', 'strike': 'strike'}, 'marker')
    g, size = _HL_LOOK[look], _ff_int(b.get('size'), 40, 12, 160)
    hl, ink = _mo_ink(b, 'color', '#ffe94a'), _mo_ink(b, 'ink', '#111111' if look == 'marker' else 'currentColor')
    weight, font = _ff_pick(b.get('weight'), _FF_WEIGHTS, 'bold'), _ff_pick(b.get('font'), _FF_FONTS, 'sans')
    return ('<span style="position:relative;display:inline-block;font-family:' + font + ';font-weight:' + weight + ';font-size:' + str(size) + 'px;line-height:1.3;color:' + ink + ';white-space:nowrap;">'
            '<span aria-hidden="true" style="position:absolute;left:-0.12em;right:-0.12em;top:' + g[0] + ';bottom:' + g[1] + ';background:' + hl + ';border-radius:0.12em;transform:rotate(' + g[2] + ') skewX(-6deg);clip-path:inset(0 calc((1 - clamp(0,var(--p,1),1))*100%) 0 0);"></span>'
            '<span style="position:relative;">' + _cv_esc(text) + '</span></span>')


_MT_LAYOUT = {'sides': 'sides', 'row': 'row'}


def _render_motion_meters(b: dict) -> str:
    bars, rows = _ff_int(b.get('bars'), 14, 4, 40), _ff_int(b.get('rows'), 12, 4, 20)
    seed, cyc = _ff_int(b.get('seed'), 3, 0, 999), _ff_int(b.get('cycles'), 2, 1, 8)
    lay, gap = _ff_pick(b.get('layout'), _MT_LAYOUT, 'sides'), _ff_int(b.get('gap'), 5, 1, 20)
    cols = [_ff_hex(c, '#ffffff') for c in _m3_list(b.get('colors'), 5)] or ['#ff5ea8', '#ffd166', '#34e0c3', '#6d6af7']

    def cluster(flip, base):
        o = ''
        for j in range(bars):
            d = bars - 1 - j if flip else j
            ph, c = _if_fmt(_bx_seed(seed, base + j, 2) * 6.2832), cols[j % len(cols)]
            k = 'clamp(0,calc(var(--p,1)*' + str(bars + 2) + ' - ' + str(d) + '),1)'
            o += ('<span style="flex:1 1 0;min-width:2px;align-self:center;height:calc(' + k + '*(0.15 + 0.85*abs(sin(calc(' + ph + '*1rad + var(--s,1)*' + str(cyc) + '*6.2832rad))))*100%);'
                  'background:repeating-linear-gradient(to top,' + c + ' 0,' + c + ' ' + _if_fmt(100 / rows * 0.62) + '%,transparent ' + _if_fmt(100 / rows * 0.62) + '%,transparent ' + _if_fmt(100 / rows) + '%);"></span>')
        return '<span aria-hidden="true" style="display:flex;gap:' + str(gap) + 'px;flex:1 1 0;height:100%;align-items:center;">' + o + '</span>'
    mid = ''.join(_mo_child(x) for x in _m3_list(b.get('blocks'), 3))
    named = isinstance(b.get('label'), str) and b.get('label')
    return ('<div ' + (('role="img" aria-label="' + _cv_esc(_cv_str(b.get('label'), 60)) + '" ') if named else '') + 'style="display:flex;align-items:center;gap:4%;width:100%;height:' + str(_ff_int(b.get('height'), 180, 60, 600)) + 'px;">'
            + ((cluster(False, 0) + '<span style="flex:none;">' + mid + '</span>' + cluster(True, 100)) if lay == 'sides' else (cluster(False, 0) + (('<span style="flex:none;">' + mid + '</span>') if mid else ''))) + '</div>')


def _render_motion_discs(b: dict) -> str:
    ds = []
    for i, raw in enumerate(_m3_list(b.get('discs'), 4)):
        o = _m3_obj(raw)
        ds.append({'color': _ff_hex(o.get('color'), ['#f4d21f', '#2e6fbd', '#e63950', '#16a085'][i % 4]), 'r': _ff_num(o.get('r'), 24, 8, 50, 1)})
    while len(ds) < 2:
        ds.append({'color': ['#f4d21f', '#2e6fbd'][len(ds)], 'r': _ff_num(None, 24, 8, 50, 1)})
    n = len(ds)
    ov, asp = _ff_num(b.get('overlap'), 12, 2, 30, 1), _ff_num(b.get('aspect'), 1.78, 0.5, 3, 2)
    blend = b.get('blend') is not False
    named = isinstance(b.get('label'), str) and b.get('label')
    out = ''
    for j, d in enumerate(ds):
        a, t = _if_fmt(14 + 72 * j / (n - 1)), _if_fmt(50 + (j - (n - 1) / 2) * float(ov))
        k = 'clamp(0,calc(var(--p,1)*' + str(n + 2) + ' - ' + str(j) + '),1)'
        out += ('<span style="position:absolute;top:50%;left:calc((' + a + ' + (' + t + ' - ' + a + ')*clamp(0,var(--s,1),1))*1%);width:' + _if_fmt(float(d['r']) * 2 / float(asp)) + '%;aspect-ratio:1;border-radius:50%;background:' + d['color'] + ';'
                + ('mix-blend-mode:multiply;' if blend else '') + 'transform:translate(-50%,-50%) scale(' + k + ');"></span>')
    return ('<div ' + (('role="img" aria-label="' + _cv_esc(_cv_str(b.get('label'), 60)) + '"') if named else 'aria-hidden="true"') + ' style="position:relative;width:100%;aspect-ratio:' + asp + ';isolation:isolate;overflow:hidden;">' + out + '</div>')


for _m5_name, _m5_fn in (('motion_ring', _render_motion_ring), ('motion_highlight', _render_motion_highlight), ('motion_meters', _render_motion_meters), ('motion_discs', _render_motion_discs)):
    _RENDERERS[_m5_name] = _m5_fn


# ─── sixth batch from a food-brand film (2026-10-12): dotgrid, blade. Twins of the last block of atoms_motion_candidates.gs ───
def _render_motion_dotgrid(b: dict) -> str:
    cols, rows = _ff_int(b.get('cols'), 5, 2, 12), _ff_int(b.get('rows'), 4, 2, 10)
    seed, dot = _ff_int(b.get('seed'), 4, 0, 999), _ff_int(b.get('dot'), 70, 30, 95)
    asp = _ff_num(b.get('aspect'), 1.25, 0.5, 3, 2)
    base, tok = _mo_ink(b, 'color', '#f4ead0'), _mo_ink(b, 'accent', '#e11d48')
    hops = []
    for raw in _m3_list(b.get('hops'), 8):
        h = _m3_list(raw, 2)
        hops.append([_ff_int(h[0] if len(h) > 0 else None, 0, 0, cols - 1), _ff_int(h[1] if len(h) > 1 else None, 0, 0, rows - 1)])
    if len(hops) < 2:
        hops = [[math.floor(_bx_seed(seed, i, 1) * cols), math.floor(_bx_seed(seed, i, 2) * rows)] for i in range(5)]
    m = len(hops)
    cw, ch = _if_fmt(100 / cols), _if_fmt(100 / rows)
    cells = ''
    for r in range(rows):
        for c in range(cols):
            d = abs(c - hops[0][0]) + abs(r - hops[0][1])
            cells += ('<span style="display:flex;align-items:center;justify-content:center;"><span style="width:' + str(dot) + '%;aspect-ratio:1;border-radius:50%;background:' + base
                      + ';transform:scale(clamp(0,calc(var(--p,1)*' + str(cols + rows + 2) + ' - ' + str(d) + '),1));"></span></span>')
    tx = ''.join(' + ' + str(hops[i + 1][0] - hops[i][0]) + '*clamp(0,calc(var(--s,1)*' + str(m - 1) + ' - ' + str(i) + '),1)' for i in range(m - 1))
    ty = ''.join(' + ' + str(hops[i + 1][1] - hops[i][1]) + '*clamp(0,calc(var(--s,1)*' + str(m - 1) + ' - ' + str(i) + '),1)' for i in range(m - 1))
    tok_el = ('<span aria-hidden="true" style="position:absolute;left:0;top:0;width:' + cw + '%;height:' + ch + '%;display:flex;align-items:center;justify-content:center;transform:translate(calc((' + str(hops[0][0]) + tx + ')*100%),calc((' + str(hops[0][1]) + ty + ')*100%));">'
              '<span style="width:' + str(dot) + '%;aspect-ratio:1;border-radius:50%;background:' + tok + ';transform:translateY(calc(-0.9*abs(sin(calc(var(--s,1)*' + str(m - 1) + '*3.14159rad)))*100%)) scale(clamp(0,calc(var(--p,1)*6),1));"></span></span>')
    named = isinstance(b.get('label'), str) and b.get('label')
    return ('<div ' + (('role="img" aria-label="' + _cv_esc(_cv_str(b.get('label'), 60)) + '"') if named else 'aria-hidden="true"') + ' style="position:relative;width:100%;aspect-ratio:' + asp
            + ';"><div style="position:absolute;inset:0;display:grid;grid-template-columns:repeat(' + str(cols) + ',1fr);grid-template-rows:repeat(' + str(rows) + ',1fr);">' + cells + '</div>' + tok_el + '</div>')


_BL_SHAPE = {'disc': 'disc', 'half': 'half', 'bar': 'bar'}


def _render_motion_blade(b: dict) -> str:
    text = _cv_str(b.get('text'), 80) or 'Text'
    shape, size = _ff_pick(b.get('shape'), _BL_SHAPE, 'half'), _ff_int(b.get('size'), 48, 14, 160)
    sc, ink = _mo_ink(b, 'color', '#123524'), _mo_ink(b, 'ink', 'currentColor')
    font, weight = _ff_pick(b.get('font'), _FF_FONTS, 'sans'), _ff_pick(b.get('weight'), _FF_WEIGHTS, 'bold')
    e = 'clamp(0,var(--s,1),1)'
    if shape == 'disc':
        sh = 'width:1.5em;height:1.5em;border-radius:50%;top:-0.2em;'
    elif shape == 'half':
        sh = 'width:1.7em;height:0.85em;border-radius:1.7em 1.7em 0 0;top:0.25em;transform:rotate(calc(' + e + '*540deg - 270deg));transform-origin:50% 100%;'
    else:
        sh = 'width:0.18em;height:1.5em;border-radius:0.09em;top:-0.1em;'
    return ('<span style="position:relative;display:inline-block;font-family:' + font + ';font-weight:' + weight + ';font-size:' + str(size) + 'px;line-height:1.2;color:' + ink + ';white-space:nowrap;">'
            '<span style="display:inline-block;clip-path:inset(0 calc((1 - ' + e + ')*100% - 0.1em) 0 0);">' + _cv_esc(text) + '</span>'
            '<span aria-hidden="true" style="position:absolute;left:calc(' + e + '*100%);margin-left:-0.85em;background:' + sc + ';opacity:clamp(0,calc(var(--p,1)*8),1);' + sh + '"></span></span>')





def _render_motion_blueprint(b: dict) -> str:
    text = _cv_str(b.get('text'), 24) or 'Text'
    size, ink, gc = _ff_int(b.get('size'), 120, 24, 300), _mo_ink(b, 'color', 'currentColor'), _mo_ink(b, 'guide', '#7c3aed')
    lines = b.get('lines') is not False
    font, weight = _ff_pick(b.get('font'), _FF_FONTS, 'sans'), _ff_pick(b.get('weight'), _FF_WEIGHTS, 'black')
    gp, op, fp = 'clamp(0,calc(var(--p,1)*2.2),1)', 'clamp(0,calc((var(--p,1) - 0.2)*2.2),1)', 'clamp(0,calc((var(--p,1) - 0.6)*2.5),1)'
    g = ''
    if lines:
        for hz in (0.2, 0.42, 0.8):
            g += ('<span style="position:absolute;left:-0.35em;right:-0.35em;top:' + _if_fmt(hz) + 'em;height:1px;background:' + gc + ';transform:scaleX(' + gp + ');transform-origin:left;opacity:calc(1 - 0.7*' + fp + ');"></span>')
        g += '<span style="position:absolute;left:-0.1em;top:-0.2em;bottom:-0.2em;width:1px;background:' + gc + ';transform:scaleY(' + gp + ');transform-origin:top;opacity:calc(1 - 0.7*' + fp + ');"></span>'
        g += '<span style="position:absolute;right:-0.1em;top:-0.2em;bottom:-0.2em;width:1px;background:' + gc + ';transform:scaleY(' + gp + ');transform-origin:bottom;opacity:calc(1 - 0.7*' + fp + ');"></span>'
    return ('<span style="position:relative;display:inline-block;font-family:' + font + ';font-weight:' + weight + ';font-size:' + str(size) + 'px;line-height:1;white-space:nowrap;padding:0.1em 0;">'
            '<span aria-hidden="true" style="position:absolute;inset:0;pointer-events:none;">' + g + '</span>'
            '<span style="position:relative;color:' + ink + ';-webkit-text-fill-color:transparent;-webkit-text-stroke:1.5px ' + ink + ';opacity:' + op + ';">' + _cv_esc(text) + '</span>'
            '<span aria-hidden="true" style="position:absolute;left:0;top:0.1em;color:' + ink + ';opacity:' + fp + ';">' + _cv_esc(text) + '</span></span>')


def _render_motion_tracking(b: dict) -> str:
    text = _cv_str(b.get('text'), 80) or 'Text'
    size, frm, to = _ff_int(b.get('size'), 48, 14, 200), _ff_num(b.get('from'), 0, -0.2, 1, 2), _ff_num(b.get('to'), 0.35, -0.2, 1, 2)
    ink, font, weight = _mo_ink(b, 'color', 'currentColor'), _ff_pick(b.get('font'), _FF_FONTS, 'sans'), _ff_pick(b.get('weight'), _FF_WEIGHTS, 'bold')
    return ('<span style="display:inline-block;font-family:' + font + ';font-weight:' + weight + ';font-size:' + str(size) + 'px;line-height:1.2;color:' + ink + ';white-space:nowrap;letter-spacing:calc((' + frm + ' + (' + to + ' - ' + frm
            + ')*clamp(0,var(--s,1),1))*1em);opacity:clamp(0,calc(var(--p,1)*4),1);">' + _cv_esc(text) + '</span>')


def _render_motion_tabs(b: dict) -> str:
    items = [(_cv_str(x, 24) or ('Tab ' + str(i + 1))) for i, x in enumerate(_m3_list(b.get('items'), 6))]
    while len(items) < 2:
        items.append('Tab ' + str(len(items) + 1))
    n = len(items)
    size, ink, acc = _ff_int(b.get('size'), 28, 12, 80), _mo_ink(b, 'color', 'currentColor'), _mo_ink(b, 'accent', '#2563eb')
    pos = 'var(--s,1)*' + str(n - 1)
    cells = ''.join('<span style="text-align:center;padding:0.5em 0.4em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:calc(0.7 + 0.3*clamp(0,calc(1 - abs(' + pos + ' - ' + str(j) + ')),1));">' + _cv_esc(t) + '</span>' for j, t in enumerate(items))
    return ('<div style="position:relative;display:grid;grid-template-columns:repeat(' + str(n) + ',1fr);width:100%;font-size:' + str(size) + 'px;font-weight:600;color:' + ink + ';border-bottom:1px solid ' + ink + '33;opacity:clamp(0,calc(var(--p,1)*4),1);">' + cells
            + '<span aria-hidden="true" style="position:absolute;bottom:-1px;height:3px;border-radius:2px;background:' + acc + ';width:calc(70%/' + str(n) + ');left:calc((' + pos + ' + 0.15)*100%/' + str(n) + ');"></span></div>')


for _m6_name, _m6_fn in (('motion_dotgrid', _render_motion_dotgrid), ('motion_blade', _render_motion_blade), ('motion_blueprint', _render_motion_blueprint), ('motion_tracking', _render_motion_tracking), ('motion_tabs', _render_motion_tabs)):
    _RENDERERS[_m6_name] = _m6_fn

# ─── showpiece pack twins (atoms_motion_candidates.gs, 2026-10-12): foil, wrap, drop, flag, disperse, reveal, streak ───
def _tf_base(b, size0):
    return {'font': _ff_pick(b.get('font'), _FF_FONTS, 'sans'), 'weight': _ff_pick(b.get('weight'), _FF_WEIGHTS, 'bold'), 'size': _ff_int(b.get('size'), size0, 10, 300),
            'color': _mo_ink(b, 'color', 'var(--mt-ink,#f1f5f9)'), 'align': _ff_pick(b.get('align'), _MO_ALIGN, 'middle')}


def _tf_box(f, extra=''):
    return f"font-family:{f['font']};font-weight:{f['weight']};font-size:{f['size']}px;line-height:1.1;white-space:nowrap;color:{f['color']};text-align:{f['align']};{extra}"


_TF_ORDER = {'forward': 'forward', 'reverse': 'reverse', 'centre': 'centre', 'random': 'random'}


def _tf_order(n, mode, seed):
    m = list(range(n))
    if mode == 'reverse':
        return [n - 1 - x for x in m]
    c = (n - 1) / 2
    if mode == 'centre':
        idx = sorted(m, key=lambda a: (abs(a - c), a))
    elif mode == 'random':
        idx = sorted(m, key=lambda a: (_bx_seed(seed, a, 9), a))
    else:
        return m
    for r, t in enumerate(idx):
        m[t] = r
    return m


_FL_LOOK = {
    'chrome': ['linear-gradient(180deg,#f8fafc 0%,#94a3b8 44%,#f1f5f9 50%,#334155 56%,#cbd5e1 100%)', '#ffffff'],
    'gold': ['linear-gradient(180deg,#fff3b0 0%,#d4a017 44%,#fff0a0 50%,#8a5a00 58%,#f6d365 100%)', '#fffbe0'],
    'silver': ['linear-gradient(180deg,#ffffff 0%,#b8c0cc 48%,#eef2f7 52%,#8a94a3 100%)', '#ffffff'],
    'copper': ['linear-gradient(180deg,#ffd9b8 0%,#c8754b 45%,#ffcfa6 50%,#7a3b1d 60%,#e29a6b 100%)', '#fff0e0'],
    'holo': ['linear-gradient(110deg,#ff9ad5,#9ad1ff,#b6ff9a,#ffe39a,#ff9ad5)', '#ffffff'],
    'rainbow': ['linear-gradient(90deg,#ff4d4d,#ffb84d,#fff94d,#4dff88,#4db8ff,#a64dff)', '#ffffff'],
    'aurora': ['linear-gradient(120deg,#34e0c3,#6d6af7,#ff5ea8)', '#e8fffb'],
    'ice': ['linear-gradient(180deg,#e0f7ff,#7ac7ff 55%,#d8f0ff)', '#ffffff'],
    'oil': ['linear-gradient(135deg,#1b1b2f,#3a1c71,#d76d77,#ffaf7b,#1b1b2f)', '#ffe9d6'],
    'mono': ['linear-gradient(180deg,currentColor,currentColor)', '#ffffff'],
}
_FL_DIR = {'ltr': [100, 0, 0], 'rtl': [100, 0, 1], 'diagonal': [135, 0, 0], 'down': [180, 1, 0], 'up': [180, 1, 1]}


def _render_motion_foil(b: dict) -> str:
    text = _cv_str(b.get('text'), 60) or 'Text'
    f = _tf_base(b, 72)
    lk = _ff_pick(b.get('look'), _FL_LOOK, 'chrome')
    dr = _ff_pick(b.get('direction'), _FL_DIR, 'ltr')
    bands = _ff_int(b.get('bands'), 1, 1, 3)
    hw = _ff_int(b.get('width'), 10, 3, 30) / 2
    sh = _mo_ink(b, 'sheen', lk[1])
    cs = [50] if bands == 1 else [40, 60] if bands == 2 else [30, 50, 70]
    g = f'linear-gradient({dr[0]}deg,transparent 0%'
    for c in cs:
        g += f',transparent {_if_fmt(c - hw)}%,{sh} {c}%,transparent {_if_fmt(c + hw)}%'
    g += ',transparent 100%)'
    pos = 'clamp(0,var(--s,1),1)' if dr[2] else '(1 - clamp(0,var(--s,1),1))'
    return (f'<div style="{_tf_box(f)}"><span style="display:inline-block;background-image:{g},{lk[0]};background-size:' + ('100% 300%' if dr[1] else '300% 100%') + ',100% 100%;background-position:' +
            (f'0 calc({pos}*100%)' if dr[1] else f'calc({pos}*100%) 0') + ',0 0;background-repeat:no-repeat;-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;opacity:clamp(0,calc(var(--p,1)*4),1);">' + _cv_esc(text) + '</span></div>')


_WR_FORM = {'cylinder': 'cylinder', 'wheel': 'wheel', 'helix': 'helix', 'ribbon': 'ribbon'}


def _render_motion_wrap(b: dict) -> str:
    text = _cv_str(b.get('text'), 40) or 'Text'
    f = _tf_base(b, 56)
    form = _ff_pick(b.get('form'), _WR_FORM, 'cylinder')
    arc = _ff_int(b.get('arc'), 360, 60, 360)
    R = _ff_int(b.get('radius'), 220, 60, 800)
    turns = _ff_int(b.get('turns'), 1, -3, 3)
    lean = _ff_int(b.get('lean'), -10, -45, 45)
    base = list(text + ' · ' if arc >= 300 else text)
    chars = []
    while len(chars) < (14 if arc >= 300 else 1):
        chars = chars + base
    chars = chars[:48]
    N = len(chars)
    step = arc / N
    rot = f'calc(var(--s,1)*{turns * 360}deg)'
    out = ''
    for i in range(N):
        th = _if_fmt((i - (N - 1) / 2) * step)
        phi = f'calc({th}deg + {rot})'
        front = f'clamp(0,calc((cos({phi}) + 1)*0.7 - 0.2),1)'
        if form == 'wheel':
            tf = f'rotateX({th}deg) translateZ({R}px)'
        elif form == 'helix':
            tf = f'translateY({_if_fmt((i - (N - 1) / 2) * f["size"] * 0.26)}px) rotateY({th}deg) translateZ({R}px)'
        elif form == 'ribbon':
            tf = f'translateY(calc(sin(calc({th}deg*2 + {rot}))*{_if_fmt(f["size"] * 0.4)}px)) rotateY({th}deg) translateZ({R}px)'
        else:
            tf = f'rotateY({th}deg) translateZ({R}px)'
        out += f'<span aria-hidden="true" style="position:absolute;left:50%;top:50%;margin:-0.55em 0 0 -0.3em;white-space:pre;transform:{tf};opacity:calc({front}*clamp(0,calc(var(--p,1)*3),1));">{_cv_esc(chars[i])}</span>'
    spin = f'rotateX(calc({lean}deg)) rotateY(0deg) rotateX({rot})' if form == 'wheel' else f'rotateX({lean}deg) rotateY({rot})'
    hgt = _if_round(f['size'] * 2.6 + (R * 0.2 if form == 'wheel' else 0))
    return (f'<div role="img" aria-label="{_cv_esc(text)}" style="position:relative;width:100%;height:{hgt}px;perspective:1100px;overflow:visible;{_tf_box(f)}">'
            f'<span aria-hidden="true" style="position:absolute;inset:0;transform-style:preserve-3d;transform:scale(calc(0.7 + 0.3*clamp(0,var(--p,1),1))) {spin};">{out}</span></div>')


_DR_MODE = {'bounce': 'bounce', 'spring': 'spring', 'rain': 'rain', 'pile': 'pile', 'rise': 'rise', 'swing': 'swing'}


def _render_motion_drop(b: dict) -> str:
    text = _cv_str(b.get('text'), 48) or 'Text'
    f = _tf_base(b, 64)
    mode = _ff_pick(b.get('mode'), _DR_MODE, 'bounce')
    H = _ff_int(b.get('height'), 200, 20, 800)
    B = _ff_int(b.get('bounces'), 3, 1, 8)
    S = _ff_int(b.get('overlap'), 3, 1, 8)
    seed = _ff_int(b.get('seed'), 3, 0, 999)
    ordm = _ff_pick(b.get('order'), _TF_ORDER, 'forward')
    chars = list(text)
    N = len(chars)
    om = _tf_order(N, ordm, seed)
    out = ''
    for i in range(N):
        u = f'clamp(0,calc((var(--p,1)*{N + S} - {om[i]})/{S}),1)'
        e = 'calc(1 - var(--u))'
        op = 'clamp(0,calc(var(--u)*6),1)'
        org = ''
        rs = _if_fmt((_bx_seed(seed, i, 3) - 0.5) * 80)
        xs = _if_fmt((_bx_seed(seed, i, 5) - 0.5) * f['size'] * 4)
        if mode == 'bounce':
            tf = f'translateY(calc(-{H}px*{e}*{e}*abs(cos(calc(var(--u)*{B}*3.14159rad))))) scaleY(calc(1 - 0.3*clamp(0,calc(1 - abs(cos(calc(var(--u)*{B}*3.14159rad)))*8),1)*{e}))'
        elif mode == 'spring':
            tf = f'translateY(calc(-{H}px*{e}*cos(calc(var(--u)*{B}*6.28318rad))))'
        elif mode == 'rain':
            tf = f'translateY(calc(-{H}px*{e}*{e}*{e})) rotate(calc({rs}deg*{e}))'
        elif mode == 'pile':
            tf = f'translate(calc({xs}px*{e}*{e}),calc(-{H}px*{e}*{e})) rotate(calc({rs}deg*{e}))'
        elif mode == 'rise':
            tf = f'translate(calc({_if_fmt(float(xs) / 4)}px*{e}*sin(calc(var(--u)*9.42rad))),calc({H}px*{e}*{e}))'
        else:
            tf = f'rotate(calc({_if_fmt(28 + _bx_seed(seed, i, 7) * 20)}deg*{e}*cos(calc(var(--u)*{B}*6.28318rad))))'
            org = 'transform-origin:50% -0.15em;'
        out += f'<span aria-hidden="true" style="--u:{u};display:inline-block;white-space:pre;{org}opacity:{op};transform:{tf};">{_cv_esc(chars[i])}</span>'
    return f'<div style="{_tf_box(f)}">{_mo_sr(text)}<span aria-hidden="true" style="display:block;">{out}</span></div>'


_FG_MODE = {'flag': 'flag', 'ripple': 'ripple', 'ribbon': 'ribbon', 'breeze': 'breeze'}


def _render_motion_flag(b: dict) -> str:
    text = _cv_str(b.get('text'), 48) or 'Text'
    f = _tf_base(b, 64)
    mode = _ff_pick(b.get('mode'), _FG_MODE, 'flag')
    A = _ff_int(b.get('amp'), 18, 2, 80)
    W = _ff_int(b.get('waves'), 2, 1, 5)
    C = _ff_int(b.get('cycles'), 2, 1, 6)
    shade = b.get('shade') is not False
    pin = 'right' if b.get('pin') == 'right' else 'left'
    chars = list(text)
    N = len(chars)
    out = ''
    env = 'sin(calc(var(--s,0)*3.14159rad))'
    for i in range(N):
        x = i / (N - 1) if N > 1 else 0
        fr = 1 - x if pin == 'right' else x
        ph = f'calc({_if_fmt(x * W * 6.28318)}rad - var(--s,0)*{C * 6.28318}rad)'
        amp = f'{A}px*{_if_fmt(fr)}' if mode == 'flag' else f'{A}px*{_if_fmt(0.4 + 0.6 * _bx_seed(7, i, 1))}' if mode == 'breeze' else f'{A}px'
        ty = f'calc({amp}*{env}*sin({ph}))'
        rt = f'calc({_if_fmt(A * 0.5 * (fr if mode == "flag" else 1))}deg*{env}*cos({ph}))'
        tf = f'translateY({ty}) rotateX(calc(60deg*{env}*sin({ph}))) rotate({rt})' if mode == 'ribbon' else f'translateY({ty}) rotate({rt})'
        out += (f'<span aria-hidden="true" style="display:inline-block;white-space:pre;transform:{tf};' + (f'filter:brightness(calc(1 + 0.3*{env}*cos({ph})));' if shade else '') +
                f'opacity:clamp(0,calc(var(--p,1)*{N + 2} - {i}),1);">{_cv_esc(chars[i])}</span>')
    return f'<div style="{_tf_box(f, "perspective:700px;")}">{_mo_sr(text)}<span aria-hidden="true" style="display:block;">{out}</span></div>'


_DP_MODE = {'smoke': 'smoke', 'shatter': 'shatter', 'rise': 'rise', 'sink': 'sink', 'implode': 'implode', 'explode': 'explode', 'wind': 'wind', 'evaporate': 'evaporate'}


def _render_motion_disperse(b: dict) -> str:
    text = _cv_str(b.get('text'), 48) or 'Text'
    f = _tf_base(b, 64)
    mode = _ff_pick(b.get('mode'), _DP_MODE, 'smoke')
    S = _ff_int(b.get('overlap'), 3, 1, 8)
    seed = _ff_int(b.get('seed'), 3, 0, 999)
    ordm = _ff_pick(b.get('order'), _TF_ORDER, 'forward')
    D = _ff_int(b.get('distance'), 90, 10, 400)
    chars = list(text)
    N = len(chars)
    om = _tf_order(N, ordm, seed)
    out = ''
    for i in range(N):
        dx = (_bx_seed(seed, i, 1) - 0.5) * 2
        dy = (_bx_seed(seed, i, 2) - 0.5) * 2
        rr = (_bx_seed(seed, i, 3) - 0.5) * 2
        c = (i - (N - 1) / 2) / max(N, 1)
        d = 'var(--d)'
        op = f'calc(1 - {d})'
        fl = ''
        if mode == 'smoke':
            tf = f'translate(calc({_if_fmt(dx * D * 0.6)}px*{d}),calc(-{D}px*{d})) scale(calc(1 + {d}*0.6))'
            fl = f'filter:blur(calc({d}*10px));'
        elif mode == 'shatter':
            tf = f'translate(calc({_if_fmt(dx * D * 1.4)}px*{d}),calc({_if_fmt(dy * D * 1.4)}px*{d})) rotate(calc({_if_fmt(rr * 200)}deg*{d}))'
        elif mode == 'rise':
            tf = f'translateY(calc(-{D}px*{d}))'
        elif mode == 'sink':
            tf = f'translateY(calc({D}px*{d}*{d})) rotate(calc({_if_fmt(rr * 30)}deg*{d}))'
        elif mode == 'implode':
            tf = f'translateX(calc({_if_fmt(-c * 2 * N * f["size"] * 0.5)}px*{d})) scale(calc(1 - {d}))'
            op = f'calc(1 - {d}*{d})'
        elif mode == 'explode':
            tf = f'translate(calc({_if_fmt(dx * D * 2)}px*{d}),calc({_if_fmt(dy * D * 2)}px*{d})) scale(calc(1 + {d}*2.5))'
            op = f'calc(1 - {d})'
        elif mode == 'wind':
            tf = f'translate(calc({_if_fmt(D * 2 + dx * D * 0.5)}px*{d}),calc({_if_fmt(dy * D * 0.3)}px*{d})) rotate(calc({_if_fmt(rr * 120)}deg*{d}))'
            fl = f'filter:blur(calc({d}*3px));'
        else:
            tf = f'translateY(calc(-{_if_fmt(D * 0.35)}px*{d})) scaleY(calc(1 + {d}*0.8))'
            fl = f'filter:blur(calc({d}*8px));'
            op = f'calc(1 - {d}*1.2)'
        out += (f'<span aria-hidden="true" style="--d:clamp(0,calc((var(--s,0)*{N + S} - {om[i]})/{S}),1);display:inline-block;white-space:pre;transform:{tf};opacity:calc({op}*clamp(0,calc(var(--p,1)*4),1));{fl}">{_cv_esc(chars[i])}</span>')
    return f'<div style="{_tf_box(f)}">{_mo_sr(text)}<span aria-hidden="true" style="display:block;">{out}</span></div>'


_RV_MODE = {'blinds': 'blinds', 'slats': 'slats', 'iris': 'iris', 'diamond': 'diamond', 'clock': 'clock', 'halftone': 'halftone', 'searchlight': 'searchlight', 'laser': 'laser', 'soft': 'soft', 'diagonal': 'diagonal'}


def _render_motion_reveal(b: dict) -> str:
    raw = (b.get('text') if isinstance(b.get('text'), str) else '').split('\n')
    lines = []
    for r in raw:
        if len(lines) >= 4:
            break
        ln = r.strip()[:60]
        if ln:
            lines.append(ln)
    if not lines:
        lines = ['Text']
    f = _tf_base(b, 64)
    mode = _ff_pick(b.get('mode'), _RV_MODE, 'blinds')
    n = _ff_int(b.get('slats'), 8, 3, 24)
    fe = _ff_int(b.get('feather'), 18, 0, 40)
    lc = _mo_ink(b, 'line', '#34e0c3')
    K = 'clamp(0,var(--p,1),1)'
    size = ''
    if mode == 'blinds':
        m = f'linear-gradient(180deg,#000 calc({K}*100%),transparent calc({K}*100%))'
        size = f'100% {_if_fmt(100 / n)}%'
    elif mode == 'slats':
        m = f'linear-gradient(90deg,#000 calc({K}*100%),transparent calc({K}*100%))'
        size = f'{_if_fmt(100 / n)}% 100%'
    elif mode == 'diagonal':
        m = f'linear-gradient(135deg,#000 calc({K}*100%),transparent calc({K}*100%))'
        size = f'{_if_fmt(100 / n)}% {_if_fmt(100 / n)}%'
    elif mode == 'halftone':
        m = f'radial-gradient(circle,#000 calc({K}*75%),transparent calc({K}*75% + 1px))'
        size = f'{_if_fmt(100 / n)}% {_if_fmt(100 / (n / 2))}%'
    elif mode == 'iris':
        m = f'radial-gradient(circle at 50% 50%,#000 calc({K}*75%),transparent calc({K}*75% + {fe}%))'
    elif mode == 'clock':
        m = f'conic-gradient(from 0deg,#000 calc({K}*360deg),transparent calc({K}*360deg))'
    elif mode == 'searchlight':
        m = f'radial-gradient(circle at calc({K}*100%) 50%,#000 calc({K}*70%),transparent calc({K}*70% + {fe + 12}%))'
    elif mode == 'laser':
        m = f'linear-gradient(90deg,#000 calc({K}*100%),transparent calc({K}*100%))'
    else:
        m = f'linear-gradient(90deg,#000 calc({K}*(100% + {fe}%) - {fe}%),transparent calc({K}*(100% + {fe}%)))'
    msk = f'mask-image:{m};-webkit-mask-image:{m};' + (f'mask-size:{size};-webkit-mask-size:{size};' if size else '')
    if mode == 'diamond':
        msk = f'clip-path:polygon(50% calc(50% - {K}*75%),calc(50% + {K}*75%) 50%,50% calc(50% + {K}*75%),calc(50% - {K}*75%) 50%);'
    body = '<br>'.join(_cv_esc(x) for x in lines)
    extra = ''
    if mode == 'laser':
        extra = f'<span aria-hidden="true" style="position:absolute;top:-4%;bottom:-4%;left:calc({K}*100%);width:2px;margin-left:-1px;background:{lc};box-shadow:0 0 14px 4px {lc};opacity:clamp(0,calc(1 - {K}*1.1),1)"></span>'
    return f'<div style="position:relative;{_tf_box(f)}"><span style="display:inline-block;{msk}">{body}</span>{extra}</div>'


_SK_DIR = {'left': [-1, 0], 'right': [1, 0], 'up': [0, -1], 'down': [0, 1], 'diagonal': [-1, -1]}


def _render_motion_streak(b: dict) -> str:
    text = _cv_str(b.get('text'), 60) or 'Text'
    f = _tf_base(b, 72)
    dr = _ff_pick(b.get('direction'), _SK_DIR, 'left')
    G = _ff_int(b.get('ghosts'), 5, 2, 10)
    D = _ff_num(b.get('distance'), 6, 1, 14, 1)
    tint = _mo_ink(b, 'tint', '')
    k = 'clamp(0,var(--p,1),1)'
    e = f'(1 - {k})'
    out = ''
    for i in range(1, G + 1):
        fr = _if_fmt(i / G)
        out += (f'<span aria-hidden="true" style="position:absolute;left:0;top:0;white-space:nowrap;' + (f'color:{tint};' if tint else '') +
                f'transform:translate(calc({dr[0]}*{D}em*{e}*(1 + {fr}*0.7)),calc({dr[1]}*{D}em*{e}*(1 + {fr}*0.7)));opacity:calc({_if_fmt(0.5 * (1 - i / (G + 1)))}*{e}*clamp(0,calc({k}*6),1));filter:blur(calc({_if_fmt(i * 0.6)}px*{e}));">{_cv_esc(text)}</span>')
    return (f'<div style="{_tf_box(f)}">{_mo_sr(text)}<span aria-hidden="true" style="position:relative;display:inline-block;white-space:nowrap;">{out}'
            f'<span style="position:relative;display:inline-block;transform:translate(calc({dr[0]}*{D}em*{e}),calc({dr[1]}*{D}em*{e}));opacity:clamp(0,calc({k}*4),1);">{_cv_esc(text)}</span></span></div>')


for _sp_name, _sp_fn in (('motion_foil', _render_motion_foil), ('motion_wrap', _render_motion_wrap), ('motion_drop', _render_motion_drop), ('motion_flag', _render_motion_flag),
                         ('motion_disperse', _render_motion_disperse), ('motion_reveal', _render_motion_reveal), ('motion_streak', _render_motion_streak)):
    _RENDERERS[_sp_name] = _sp_fn



# ─── motion_selection (I73, owner's video review 2026-10-21, event 40): a design-tool selection frame round its own content ───
# Twin of the motion_selection block in atoms_motion_candidates.gs. Frame, tint, handles and toolbar are decorative (aria-hidden); the content is real text or up to 3 child atoms.
_SL_TOOLS = ['B', 'I', 'U', 'Aa', '…']
_SL_FONT = 'ui-sans-serif,system-ui,-apple-system,Segoe UI,Helvetica Neue,Arial,sans-serif'


def _render_motion_selection(b: dict) -> str:
    acc = _mo_ink(b, 'color', 'var(--mt-acc,#38bdf8)')
    sz = _ff_int(b.get('size'), 0, 0, 160)
    sz = max(12, sz) if sz else 0
    inner = ''.join(_mo_child(x) for x in _m3_list(b.get('blocks'), 3))
    if not inner.strip():
        inner = _cv_esc(_cv_str(b.get('text'), 120) or 'Selected text')
    raw = b.get('toolbar')
    tools = [t for t in (_cv_str(x, 6) for x in raw[:6]) if t] if isinstance(raw, list) else _SL_TOOLS
    hide = 'aria-hidden="true" '
    nop = 'pointer-events:none;'
    bar = ''
    if tools:
        cells = ''.join('<span data-sel="tool" style="box-sizing:border-box;min-width:2em;height:2em;padding:0 0.42em;display:inline-flex;align-items:center;justify-content:center;border-radius:0.33em;'
                        'font:600 1em/1 ' + _SL_FONT + ';color:var(--text,#0f172a);">' + _cv_esc(t) + '</span>' for t in tools)
        bar = ('<div ' + hide + 'data-sel="bar" style="' + nop + 'box-sizing:border-box;max-width:100%;display:flex;flex-wrap:wrap;gap:0.17em;padding:0.25em;border-radius:0.58em;font-size:max(12px,0.32em);background:var(--surface,#ffffff);'
               'border:1px solid var(--border,#cbd5e1);box-shadow:0 2px 8px rgba(0,0,0,0.18);opacity:var(--k4);transform:translateY(calc((1 - var(--k4))*8px));">' + cells + '</div>')
    tint = ('<span ' + hide + 'data-sel="tint" style="' + nop + 'position:absolute;inset:0;background:' + acc + ';opacity:calc(0.22*var(--k2));"></span>') if b.get('tint') is not False else ''
    handles = ''
    if b.get('handles') is not False:
        for pos in ('left:calc(var(--hs)/-2);top:calc(var(--hs)/-2);', 'right:calc(var(--hs)/-2);top:calc(var(--hs)/-2);', 'left:calc(var(--hs)/-2);bottom:calc(var(--hs)/-2);', 'right:calc(var(--hs)/-2);bottom:calc(var(--hs)/-2);'):
            handles += ('<span ' + hide + 'data-sel="handle" style="' + nop + 'position:absolute;' + pos + 'box-sizing:border-box;width:var(--hs);height:var(--hs);border-radius:50%;background:var(--surface,#ffffff);'
                        'border:max(1.5px,0.04em) solid ' + acc + ';opacity:var(--k3);transform:scale(var(--k3));"></span>')
    frame = '<span ' + hide + 'data-sel="frame" style="' + nop + 'position:absolute;inset:0;box-sizing:border-box;border:max(1px,0.025em) solid ' + acc + ';clip-path:inset(0 calc((1 - var(--k1))*100%) 0 0);"></span>'
    return ('<div style="--k1:clamp(0,calc(var(--p,1)*2.5),1);--k2:clamp(0,calc((var(--p,1) - 0.15)*4),1);--k3:clamp(0,calc((var(--p,1) - 0.3)*4),1);--k4:clamp(0,calc((var(--p,1) - 0.5)*2),1);--hs:max(10px,0.2em);'
            + ('font-size:' + str(sz) + 'px;' if sz else '')
            + 'box-sizing:border-box;display:inline-flex;flex-direction:column;align-items:flex-start;gap:max(8px,0.18em);max-width:100%;padding:max(6px,0.14em);">' + bar
            + '<div style="position:relative;box-sizing:border-box;max-width:100%;padding:max(4px,0.1em) max(8px,0.2em);">' + tint + frame + handles
            + '<div data-sel="body" style="--p:1;position:relative;overflow-wrap:anywhere;">' + inner + '</div></div></div>' + _hg_version_note(b, 'motion_selection'))


_RENDERERS['motion_selection'] = _render_motion_selection


# ─── motion_lightning (I68, owner's video review 2026-10-21, event 3): forked, jagged bolts that strike across a block from a point ───
# Twin of the motion_lightning block in atoms_motion_candidates.gs. Bolts are SVG paths made by a seeded midpoint displacement (a fixed LCG, never a random
# call), drawn in with p (stroke-dashoffset on a pathLength of 1) with an optional glow (drop-shadow on the svg) and an optional brief flash. The bolts and the
# flash are aria-hidden; the optional children (up to 3) are held at p = 1 and stay readable. WCAG 2.3.1: the flicker is ONE sinusoid of at most 6 rad over
# p 0..1 (under one cycle, so one flash) shared by every bolt, the flash is one pulse, so a strike of any duration makes at most 2 flashes; the flash is a pale tint
# (the colour mixed 85% toward white) at most 0.3 strong, never a saturated red area. Sines use a pure-arithmetic approximation so both twins agree to the bit.
_LT_EDGE = {'top': (50, 0, 0), 'bottom': (50, 100, 180), 'left': (0, 50, 90), 'right': (100, 50, 270), 'center': (50, 50, -1)}


def _lt_sin(a):
    a = a - 360 * math.floor(a / 360)
    if a < 180:
        return 4 * a * (180 - a) / (40500 - a * (180 - a))
    a -= 180
    return -(4 * a * (180 - a) / (40500 - a * (180 - a)))


def _lt_coord(v):
    return float(max(0, min(100, v))) if isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) else 50.0


def _lt_path(pts):
    return 'M' + ' L'.join(_ff_num(x, 0, -200, 300, 1) + ',' + _ff_num(y, 0, -200, 300, 1) for x, y in pts)


def _render_motion_lightning(b: dict) -> str:
    col = _mo_ink(b, 'color', '#e6f0ff')
    n = _ff_int(b.get('bolts'), 3, 1, 6)
    nb = _ff_int(b.get('branches'), 3, 0, 4)
    seed = _ff_int(b.get('seed'), 7, 0, 9999)
    og = b.get('origin')
    if isinstance(og, dict):
        ox, oy = _lt_coord(og.get('x')), _lt_coord(og.get('y'))
        dx, dy = ox - 50, oy - 50
        base = -1 if (abs(dx) <= 10 and abs(dy) <= 10) else ((0 if dy < 0 else 180) if abs(dy) >= abs(dx) else (90 if dx < 0 else 270))
    else:
        e = _LT_EDGE[og] if isinstance(og, str) and og in _LT_EDGE else _LT_EDGE['top']
        ox, oy, base = float(e[0]), float(e[1]), e[2]
    gx, gy = ox * 1.6, oy * 0.9   # the bolts are drawn in a fixed 160 x 90 space and sliced into the box, so angles and proportions hold in any box shape
    par = 'x' + ('Min' if ox < 34 else 'Max' if ox > 66 else 'Mid') + 'Y' + ('Min' if oy < 34 else 'Max' if oy > 66 else 'Mid') + ' slice'
    st = [(seed * 7919 + 104729) % 2147483646 + 1]

    def rnd():
        st[0] = st[0] * 16807 % 2147483647
        return st[0] / 2147483647

    def jag(ax, ay, bx, by, depth):
        pts = [(ax, ay), (bx, by)]
        for _ in range(depth):
            nw = [pts[0]]
            for i in range(len(pts) - 1):
                x0, y0 = pts[i]
                x1, y1 = pts[i + 1]
                r = rnd() * 2 - 1
                nw.append(((x0 + x1) / 2 - (y1 - y0) * r * 0.17, (y0 + y1) / 2 + (x1 - x0) * r * 0.17))
                nw.append((x1, y1))
            pts = nw
        return pts
    freq = 3 + rnd() * 2.5
    ff = _ff_num(freq, 4, 3, 5.5, 1)
    circle = base < 0
    spread = min(100, 20 + 16 * (n - 1))
    rgb = _ff_rgb(col)
    groups = ''
    for i in range(n):
        if circle:
            a = i * 360 / n + (rnd() - 0.5) * 20
        else:
            a = base + ((i - (n - 1) / 2) * spread / (n - 1 if n > 1 else 1)) + (rnd() - 0.5) * 16
        ln = (70 + rnd() * 25) * 0.9
        pts = jag(gx, gy, gx + _lt_sin(a) * ln, gy + _lt_sin(a + 90) * ln, 4)
        d0 = i * 0.04
        ph = _ff_num(rnd() * 6.2, 0, 0, 7, 1)
        inner = ('<path data-lt="bolt" d="' + _lt_path(pts) + '" class="lt-p" fill="none" stroke="' + col + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"></path>')
        for k in range(nb):
            j = 4 + int(rnd() * 9)
            sg = 1 if k % 2 == 0 else -1
            ba = a + sg * (25 + int(rnd() * 25))
            bl = 18 + rnd() * 14
            q = pts[j]
            bp = jag(q[0], q[1], q[0] + _lt_sin(ba) * bl, q[1] + _lt_sin(ba + 90) * bl, 3)
            inner += ('<path data-lt="branch" d="' + _lt_path(bp) + '" class="lt-p" fill="none" stroke="' + col + '" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"></path>')
        groups += ('<g class="lt-g" data-lt="grow" style="clip-path:circle(calc(clamp(0,calc((var(--p,1) - ' + _ff_num(d0, 0, 0, 1, 2) + ')*3),1)*110%) at ' + _ff_num(ox, 50, 0, 100, 1) + '% ' + _ff_num(oy, 50, 0, 100, 1) + '%) view-box;opacity:calc(1 - 0.45*(1 - clamp(0,var(--p,1),1))*(0.5 + 0.5*sin(calc(var(--p,1)*' + ff + ' + ' + ph + '))));">' + inner + '</g>')
    glow = ('filter:drop-shadow(0 0 3px rgba(' + rgb + ',0.9)) drop-shadow(0 0 9px rgba(' + rgb + ',0.6));') if b.get('glow') is not False else ''
    kids = ''.join(_mo_child(x) for x in _m3_list(b.get('blocks'), 3))
    fade = bool(kids.strip())   # over children the strike happens and is gone when the scene settles (p 0.6 to 1)
    svg = ('<svg' + (' class="lt-fade"' if fade else '') + ' aria-hidden="true" focusable="false" viewBox="0 0 160 90" preserveAspectRatio="' + par + '" style="position:absolute;left:0;top:0;width:100%;height:100%;pointer-events:none;overflow:hidden;'
           + ('opacity:clamp(0,calc((1 - var(--p,1))*2.5),1);' if fade else '') + glow + '">' + groups + '</svg>')
    flash = ''
    if b.get('flash') is True:
        fc = ','.join(str(math.floor(int(c) + (255 - int(c)) * 0.85 + 0.5)) for c in rgb.split(','))
        flash = ('<span class="lt-flash" data-lt="flash" aria-hidden="true" style="position:absolute;left:0;top:0;width:100%;height:100%;pointer-events:none;background:rgb(' + fc + ');'
                 'opacity:calc(0.3*clamp(0,min(calc((var(--p,1) - 0.04)*12),calc((0.2 - var(--p,1))*12)),1));"></span>')
    body = ('<div data-lt="body" style="--p:1;position:relative;overflow-wrap:anywhere;">' + kids + '</div>') if kids.strip() else ''
    return ('<style>@media (prefers-reduced-motion:reduce),print{.lt-flash{display:none!important}.lt-g{clip-path:none!important;opacity:1!important}.lt-fade{display:none!important}}</style>'
            '<div data-lt="root" style="position:relative;display:block;box-sizing:border-box;width:100%;max-width:100%;isolation:isolate;' + ('' if body else 'aspect-ratio:16/9;') + '">'
            + body + flash + svg + '</div>' + _hg_version_note(b, 'motion_lightning'))


_RENDERERS['motion_lightning'] = _render_motion_lightning


# ─── motion_shatter (I69, owner's video review 2026-10-21, event 11): cracks radiate from an impact point, then the block breaks into shards that fall away ───
# Twin of the motion_shatter block in atoms_motion_candidates.gs. The shards are a seeded Voronoi partition of the box (sites placed by a fixed LCG, densest near the
# impact point, cells made by clipping the box against each bisector, never a random call); each shard is an aria-hidden, inert copy of the content clipped to its cell
# and moved by p alone. END STATE: p = 1 is GONE (the source shows the block gone, revealing what is behind), p = 0 whole. The real content is drawn only while p <= 0.3
# (the cracks), then the shards stand in for it at the same place; it is hidden from assistive tech (visibility) only when p reaches 1, by a paused keyframe whose
# delay is read from p. Reduced motion: no shards, no cracks, no falling, the block fades plainly to the same gone end. Print: whole. WCAG 2.3.1: nothing oscillates.
def _sh_fold(c, m):
    if c < 2:
        c = 4 - c
    if c > m - 2:
        c = 2 * (m - 2) - c
    return max(2.0, min(m - 2.0, c))


def _sh_clip(poly, mx, my, dx, dy):
    out = []
    n = len(poly)
    for k in range(n):
        a, b = poly[k], poly[(k + 1) % n]
        fa = (a[0] - mx) * dx + (a[1] - my) * dy
        fb = (b[0] - mx) * dx + (b[1] - my) * dy
        if fa <= 0:
            out.append(a)
        if (fa < 0 and fb > 0) or (fa > 0 and fb < 0):
            t = fa / (fa - fb)
            out.append((a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t))
    return out


def _render_motion_shatter(b: dict) -> str:
    n = _ff_int(b.get('shards'), 12, 4, 24)
    seed = _ff_int(b.get('seed'), 7, 0, 9999)
    spin = _ff_int(b.get('spin'), 40, 0, 180)
    out_fall = b.get('fall') == 'out'
    og = b.get('origin')
    if isinstance(og, dict):
        ox, oy = _lt_coord(og.get('x')), _lt_coord(og.get('y'))
    else:
        e = _LT_EDGE[og] if isinstance(og, str) and og in _LT_EDGE else _LT_EDGE['top']
        ox, oy = float(e[0]), float(e[1])
    st = [(seed * 7919 + 104729) % 2147483646 + 1]

    def rnd():
        st[0] = st[0] * 16807 % 2147483647
        return st[0] / 2147483647
    gx, gy = ox * 1.6, oy * 0.9   # the partition is made in a fixed 160 x 90 space (like the lightning bolts) so shards are not stretched in a 16:9 box; the output is in percent of the box
    sites = []
    for i in range(n):
        r1, r2 = rnd(), rnd()
        if i == 0:
            sites.append((_sh_fold(gx + (r1 - 0.5) * 6, 160), _sh_fold(gy + (r2 - 0.5) * 6, 90)))
        else:
            a = i * 137.5 + r1 * 40
            rr = 6 + 100 * (i / n) * (0.75 + 0.5 * r2)
            sites.append((_sh_fold(gx + _lt_sin(a + 90) * rr, 160), _sh_fold(gy + _lt_sin(a) * rr, 90)))
    box = [(0.0, 0.0), (160.0, 0.0), (160.0, 90.0), (0.0, 90.0)]
    kids = ''.join(_mo_child(x) for x in _m3_list(b.get('blocks'), 3))
    has = bool(kids.strip())
    face = ('<div data-sh="face" style="--p:1;position:relative;overflow-wrap:anywhere;">' + kids + '</div>') if has else \
        '<div data-sh="face" style="--p:1;position:relative;box-sizing:border-box;width:100%;height:100%;border:1px solid var(--border,#cbd5e1);border-radius:12px;background:var(--surface,#f1f5f9);"></div>'
    copy = re.sub(r'[ \t\n\r](?:id|data-mt-id)="[^"]*"', '', face)
    shards, seen, edges = '', set(), []
    for i in range(n):
        poly = box
        for j in range(n):
            if j != i and poly:
                dx, dy = sites[j][0] - sites[i][0], sites[j][1] - sites[i][1]
                poly = _sh_clip(poly, (sites[i][0] + sites[j][0]) / 2, (sites[i][1] + sites[j][1]) / 2, dx, dy)
        if len(poly) < 3:
            continue
        pts = [(_ff_num(x / 1.6, 0, 0, 100, 1), _ff_num(y / 0.9, 0, 0, 100, 1)) for x, y in poly]
        cx = sum(x for x, _ in poly) / len(poly)
        cy = sum(y for _, y in poly) / len(poly)
        for k in range(len(pts)):
            a, c = pts[k], pts[(k + 1) % len(pts)]
            if a == c or (a[0] == c[0] and a[0] in ('0', '100')) or (a[1] == c[1] and a[1] in ('0', '100')):
                continue
            key = (a, c) if a <= c else (c, a)
            if key in seen:
                continue
            seen.add(key)
            edges.append('M' + a[0] + ',' + a[1] + ' L' + c[0] + ',' + c[1])
        r_tx, r_ty, r_rot, r_rx, r_ry, r_dl = rnd(), rnd(), rnd(), rnd(), rnd(), rnd()
        dist = math.sqrt((cx - gx) * (cx - gx) + (cy - gy) * (cy - gy))
        if out_fall:
            vx, vy = cx - gx, cy - gy
            ln = math.sqrt(vx * vx + vy * vy)
            if ln < 0.000001:
                vx, vy, ln = _lt_sin(r_tx * 360 + 90), _lt_sin(r_tx * 360), 1.0
            k = (40 + r_ty * 40) / ln
            tx, ty = vx * k, vy * k * 1.7778
        else:
            tx, ty = (r_tx - 0.5) * 30, 60 + r_ty * 70
        rz = (1 if r_rot < 0.5 else -1) * spin * (0.35 + 0.65 * r_dl)
        d = 0.05 + 0.25 * min(1.0, dist / 110) + r_dl * 0.05
        kf = 1 / (1 - d)
        shards += ('<div data-sh="shard" style="position:absolute;inset:0;pointer-events:none;user-select:none;--u:clamp(0,calc((var(--sh-t) - ' + _ff_num(d, 0, 0, 1, 3) + ')*' + _ff_num(kf, 1, 1, 2, 3)
                   + '),1);--tx:' + _ff_num(tx, 0, -300, 300, 1) + ';--ty:' + _ff_num(ty, 0, -300, 300, 1) + ';--rz:' + _ff_num(rz, 0, -180, 180, 1)
                   + ';--rx:' + _ff_num((r_rx - 0.5) * 60, 0, -30, 30, 1) + ';--ry:' + _ff_num((r_ry - 0.5) * 60, 0, -30, 30, 1)
                   + ';clip-path:polygon(' + ','.join(x + '% ' + y + '%' for x, y in pts) + ');transform-origin:' + _ff_num(cx / 1.6, 50, 0, 100, 1) + '% ' + _ff_num(cy / 0.9, 50, 0, 100, 1)
                   + '%;opacity:clamp(0,calc(var(--sh-on)*(0.9 - var(--u))*2.5),1);transform:perspective(900px) translate(calc(var(--tx)*var(--u)*var(--u)*1%),calc(var(--ty)*var(--u)*var(--u)*1%)) '
                   'rotate(calc(var(--rz)*var(--u)*var(--u)*1deg)) rotateX(calc(var(--rx)*var(--u)*1deg)) rotateY(calc(var(--ry)*var(--u)*1deg));">'
                   '<div style="--p:1;width:100%;height:100%;">' + copy + '</div></div>')
    cracks = ''
    if b.get('cracks') is not False and edges:
        dd = ' '.join(edges)
        cracks = ('<svg class="sh-cracks" data-sh="cracks" aria-hidden="true" focusable="false" viewBox="0 0 100 100" preserveAspectRatio="none" style="position:absolute;left:0;top:0;width:100%;height:100%;pointer-events:none;overflow:hidden;'
                  'clip-path:circle(calc(clamp(0,calc(var(--p,1)*3.5),1)*150%) at ' + _ff_num(ox, 50, 0, 100, 1) + '% ' + _ff_num(oy, 50, 0, 100, 1) + '%) view-box;opacity:clamp(0,calc((0.42 - var(--p,1))*8),1);">'
                  '<path d="' + dd + '" fill="none" stroke="var(--bg,#0b1020)" stroke-opacity="0.55" stroke-width="2.6" stroke-linecap="round" vector-effect="non-scaling-stroke"></path>'
                  '<path d="' + dd + '" fill="none" stroke="var(--text,#e8ecf4)" stroke-width="1.2" stroke-linecap="round" vector-effect="non-scaling-stroke"></path></svg>')
    css = ('<style>@keyframes sh-gone{from{visibility:visible}to{visibility:hidden}}'
           '.sh-body{opacity:clamp(0,calc((0.301 - var(--p,1))*1000),1);animation:sh-gone 1s linear paused both;animation-delay:calc(var(--p,1)*-1s)}'
           '@media (prefers-reduced-motion:reduce){.sh-shards,.sh-cracks{display:none!important}.sh-body{opacity:clamp(0,calc((1 - var(--p,1))*1.4286),1)}}'
           '@media print{.sh-shards,.sh-cracks{display:none!important}.sh-body{opacity:1!important;animation:none!important}}</style>')
    return (css + '<div data-sh="root" style="position:relative;display:block;box-sizing:border-box;width:100%;max-width:100%;overflow-x:clip;isolation:isolate;'
            '--sh-t:clamp(0,calc((var(--p,1) - 0.3)*1.4286),1);--sh-on:clamp(0,calc((var(--p,1) - 0.299)*1000),1);' + ('' if has else 'aspect-ratio:16/9;') + '">'
            '<div class="sh-body" data-sh="body" style="position:relative;' + ('' if has else 'height:100%;') + '">' + face + '</div>'
            '<div class="sh-shards" data-sh="shards" aria-hidden="true" inert style="position:absolute;inset:0;pointer-events:none;">' + shards + '</div>' + cracks + '</div>'
            + _hg_version_note(b, 'motion_shatter'))


_RENDERERS['motion_shatter'] = _render_motion_shatter


# ─── motion_map3d v2 (I72, owner's reference video): a tilted 3D city map; camera descends, legs draw on station by station, messages travel, a clock counts ───
# Twin of the motion_map3d block in atoms_motion_candidates.gs. CSS 3D only (perspective + rotateX/rotateZ on a plane, boxes made of three faces), no WebGL,
# no map tiles, no fetch. Every moving value is a pure function of var(--p, 1): the camera takes p 0 to 0.3, the route draws p 0.3 to 0.92 segment by segment
# (stroke-dashoffset on pathLength 1), the stations go idle > active > their own state as the route reaches and leaves them, messages travel along legs, and
# the clock counts over the same window. p = 1 (no timeline, no script, reduced motion, print) is the settled picture. The scene is aria-hidden; a visually
# hidden text lists route/legs, stations, messages and clock. Two planes keep station pins/messages above city blocks. Only sqrt, + - * / and floor are used,
# so both twins make the same bytes.
_MAP3D_P0, _MAP3D_P1, _MAP3D_U = 0.3, 0.92, 0.62
_MAP3D_ID = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,23}')
_MAP3D_CLK = re.compile(r'[ ]*([0-9]{1,2}):([0-9]{2})[ ]*')
_MAP3D_STATES = ('idle', 'active', 'done', 'warn', 'error')
_MAP3D_TURNS = (-28.0, 52.0, -10.0, 38.0, -34.0, 64.0)   # camera.follow angles, in turn order


def _map3d_version_note(b):
    v = _if_g(b, 'version')
    if isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) != _HG_INF and v == math.floor(v) and v > 2:
        return _hg_note('Written for motion_map3d version ' + _if_numstr(v) + '; drawn as version 2.')
    return ''


def _map3d_n(v, dflt, lo, hi):
    ok = isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)
    return max(lo, min(hi, float(v) if ok else float(dflt)))


def _map3d_f(x, places=2):
    return _ff_num(x, 0, -100000, 100000, places)


def _map3d_clock(v):
    m = _MAP3D_CLK.fullmatch(v) if isinstance(v, str) else None
    if not m or int(m.group(1)) > 23 or int(m.group(2)) > 59:
        return None
    return int(m.group(1)) * 60 + int(m.group(2))


def _map3d_hhmm(t):
    t = t % 1440
    return _cv_pad(t // 60) + ':' + _cv_pad(t % 60)


def _map3d_keyed(keys, j, places):
    """Piecewise-linear calc() of column j of the camera keys over var(--p,1): held before the first key and after the last."""
    out = 'calc(' + _map3d_f(keys[0][j], places)
    for i in range(len(keys) - 1):
        d = keys[i + 1][j] - keys[i][j]
        if d != 0:
            out += ' + ' + _map3d_f(d, places) + '*clamp(0,calc((var(--p,1) - ' + _map3d_f(keys[i][0], 3) + ')/' + _map3d_f(keys[i + 1][0] - keys[i][0], 3) + '),1)'
    return out + ')'


def _map3d_segdist(px, py, ax, ay, bx, by):
    dx, dy = bx - ax, by - ay
    ll = dx * dx + dy * dy
    t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / ll)) if ll > 0 else 0.0
    ex, ey = ax + t * dx - px, ay + t * dy - py
    return math.sqrt(ex * ex + ey * ey)


def _render_motion_map3d(b: dict) -> str:
    acc = _mo_ink(b, 'color', 'var(--mt-acc,#38bdf8)')
    tilt = _map3d_n(b.get('tilt'), 55, 0, 75)
    cam = _m3_obj(b.get('camera'))
    z0, z1 = _map3d_n(cam.get('from'), 0.55, 0.3, 3), _map3d_n(cam.get('to'), 1.0, 0.3, 3)
    # camera.keys (v2): poses {at, turn, tilt, zoom} the camera passes through over the whole film, replacing the default descent
    ckeys, kbad = [], 0
    kraw = cam.get('keys') if isinstance(cam.get('keys'), list) else []
    for k in kraw[:8]:
        k = _m3_obj(k)
        at = k.get('at')
        if not (isinstance(at, (int, float)) and not isinstance(at, bool) and math.isfinite(at) and 0 <= at <= 1) or (ckeys and at <= ckeys[-1][0]):
            kbad += 1
            continue
        pv = ckeys[-1] if ckeys else (0.0, 22.0, tilt, z1)
        ckeys.append((float(at), _map3d_n(k.get('turn'), pv[1], -180, 180), _map3d_n(k.get('tilt'), pv[2], 0, 75), _map3d_n(k.get('zoom'), pv[3], 0.3, 3)))
    kbad += max(0, len(kraw) - 8)
    seed = _ff_int(b.get('seed'), 7, 0, 9999)
    notes = []
    # stations: unique ids, at most 24
    sts, byid, bad = [], {}, 0
    raw = b.get('stations') if isinstance(b.get('stations'), list) else []
    for i, s in enumerate(raw[:24]):
        s = _m3_obj(s)
        sid = s.get('id') if isinstance(s.get('id'), str) and _MAP3D_ID.fullmatch(s.get('id')) else 's' + str(i + 1)
        if sid in byid:
            bad += 1
            continue
        lab = _cv_str(s.get('label'), 24) or sid
        st = {'id': sid, 'x': _map3d_n(s.get('x'), 50, 0, 100), 'y': _map3d_n(s.get('y'), 50, 0, 100), 'label': lab,
              'state': s.get('state') if s.get('state') in _MAP3D_STATES else 'idle', 'on': False}
        byid[sid] = st
        sts.append(st)
    if len(raw) > 24:
        bad += len(raw) - 24
    if bad:
        notes.append(str(bad) + (' station was' if bad == 1 else ' stations were') + ' left out (duplicate id or more than 24).')
    if not sts:
        notes.append('No stations to show.')

    # legs / route processing
    raw_legs = b.get('legs') if isinstance(b.get('legs'), list) else None
    valid_legs = []
    dropped_legs = 0
    legs_mode = False

    def clean_route(rraw):
        rt, u = [], 0
        r_slice = rraw[:32] if isinstance(rraw, list) else []
        for rid in r_slice:
            if isinstance(rid, str) and rid in byid:
                if not rt or rt[-1] != rid:
                    rt.append(rid)
            else:
                u += 1
        if isinstance(rraw, list) and len(rraw) > 32:
            u += len(rraw) - 32
        return rt, u

    if raw_legs is not None:
        for idx, leg_item in enumerate(raw_legs):
            if idx >= 4:
                dropped_legs += 1
                continue
            leg_obj = _m3_obj(leg_item)
            l_route_raw = leg_obj.get('route') if isinstance(leg_obj.get('route'), list) else []
            l_rt, l_unk = clean_route(l_route_raw)
            if l_unk:
                notes.append(str(l_unk) + (' route entry was' if l_unk == 1 else ' route entries were') + ' not a known station and ' + ('was' if l_unk == 1 else 'were') + ' skipped.')
            is_back = leg_obj.get('back') is True
            if is_back:
                l_rt.reverse()
            if len(l_rt) < 2:
                dropped_legs += 1
            else:
                l_col = _ff_hex(leg_obj.get('color'), '') or acc
                valid_legs.append({'route': l_rt, 'color': l_col, 'back': is_back})
        if dropped_legs:
            notes.append(str(dropped_legs) + (' leg was' if dropped_legs == 1 else ' legs were') + ' left out (fewer than two known stations).')

    if valid_legs:
        legs_mode = True
        legs = valid_legs
    else:
        # fallback to top-level route
        rraw = b.get('route') if isinstance(b.get('route'), list) else []
        rt, unk = clean_route(rraw)
        if unk:
            notes.append(str(unk) + (' route entry was' if unk == 1 else ' route entries were') + ' not a known station and ' + ('was' if unk == 1 else 'were') + ' skipped.')
        legs = [{'route': rt, 'color': acc, 'back': False}] if len(rt) >= 2 else []

    # Concatenate all legs' segments in order
    segs = []
    for leg_idx, leg in enumerate(legs):
        l_rt = leg['route']
        for i in range(len(l_rt) - 1):
            a, c = byid[l_rt[i]], byid[l_rt[i + 1]]
            segs.append({
                'leg': leg_idx,
                'from': l_rt[i],
                'to': l_rt[i + 1],
                'ax': a['x'],
                'ay': a['y'],
                'bx': c['x'],
                'by': c['y'],
                'len': math.sqrt((c['x'] - a['x']) * (c['x'] - a['x']) + (c['y'] - a['y']) * (c['y'] - a['y'])),
                'color': leg['color']
            })

    total = 0.0
    for s in segs:
        total += s['len']
    n_segs = len(segs)
    W = _MAP3D_P1 - _MAP3D_P0
    dw = min(0.04, W * 0.3 / max(1, n_segs - 1)) if n_segs else 0.04
    draw = W - dw * max(0, n_segs - 1)
    cum = 0.0
    seen = {}
    for i, s in enumerate(segs):
        share = (s['len'] / total) if total > 0 else 1.0 / n_segs
        s['s'] = _MAP3D_P0 + dw * i + draw * cum
        s['w'] = draw * share
        cum += share
        k = s['from'] + '-' + s['to']
        seen[k] = seen.get(k, 0) + 1
        s['key'] = k if seen[k] == 1 else k + '-' + str(seen[k])

    # Leg drawing start and total drawing time
    seg_idx_by_leg = {}
    for i, s in enumerate(segs):
        l_idx = s['leg']
        if l_idx not in seg_idx_by_leg:
            seg_idx_by_leg[l_idx] = []
        seg_idx_by_leg[l_idx].append(i)

    leg_draw_info = []
    for leg_idx, leg in enumerate(legs):
        s_indices = seg_idx_by_leg.get(leg_idx, [])
        if s_indices:
            first_s = segs[s_indices[0]]
            last_s = segs[s_indices[-1]]
            leg_start = first_s['s']
            leg_w = (last_s['s'] + last_s['w']) - first_s['s']
            if leg_w < 0.05:
                leg_w = 0.05
        else:
            leg_start = _MAP3D_P0
            leg_w = 0.05
        leg_draw_info.append({'start': leg_start, 'w': leg_w})

    # Station reach/leave timing
    for leg_idx, leg in enumerate(legs):
        l_rt = leg['route']
        s_indices = seg_idx_by_leg.get(leg_idx, [])
        for j, rid in enumerate(l_rt):
            st = byid[rid]
            if leg_idx == 0 and j == 0:
                r = _MAP3D_P0 - dw
            elif j == 0:
                r = segs[s_indices[0]]['s']
            else:
                prev_seg = segs[s_indices[j - 1]]
                r = prev_seg['s'] + prev_seg['w']

            if j < len(l_rt) - 1:
                cur_seg = segs[s_indices[j]]
                lv = cur_seg['s']
            else:
                lv = r + 0.05

            if not st['on']:
                st['on'], st['r'] = True, r
            st['l'] = lv

    # messages
    msg_raw = b.get('messages') if isinstance(b.get('messages'), list) else []
    messages = []
    dropped_msgs = 0
    for idx, m_item in enumerate(msg_raw):
        if len(messages) >= 12:
            dropped_msgs += 1
            continue
        m_obj = _m3_obj(m_item)
        m_leg_val = m_obj.get('leg')
        if m_leg_val is None:
            m_leg = 0
        elif isinstance(m_leg_val, (int, float)) and not isinstance(m_leg_val, bool) and math.isfinite(m_leg_val) and int(m_leg_val) == m_leg_val:
            m_leg = int(m_leg_val)
        else:
            dropped_msgs += 1
            continue

        if m_leg < 0 or m_leg >= len(legs):
            dropped_msgs += 1
            continue

        m_text = _cv_str(m_obj.get('text'), 24)
        if not m_text:
            dropped_msgs += 1
            continue

        at_val = m_obj.get('at')
        if isinstance(at_val, (int, float)) and not isinstance(at_val, bool) and math.isfinite(at_val) and 0.0 <= at_val <= 1.0:
            a = float(at_val)
        else:
            a = leg_draw_info[m_leg]['start']

        w = leg_draw_info[m_leg]['w']
        if a + w > 1.0:
            a = max(0.0, 1.0 - w)

        m_back = m_obj.get('back') is True
        messages.append({
            'leg': m_leg,
            'text': m_text,
            'a': a,
            'w': w,
            'back': m_back
        })

    if dropped_msgs:
        notes.append(str(dropped_msgs) + (' message was' if dropped_msgs == 1 else ' messages were') + ' left out.')

    # the city
    blocks = []
    braw = b.get('blocks') if isinstance(b.get('blocks'), list) else []
    if braw:
        for e in braw:
            if isinstance(e, dict):
                blocks.append((_map3d_n(e.get('x'), 0, 0, 100), _map3d_n(e.get('y'), 0, 0, 100), _map3d_n(e.get('w'), 8, 1, 100), _map3d_n(e.get('h'), 8, 1, 100), _map3d_n(e.get('height'), 6, 0, 40)))
        if len(blocks) > 200:
            notes.append('Showing the first 200 of ' + str(len(blocks)) + ' blocks.')
            blocks = blocks[:200]
    else:
        rs = [(seed * 7919 + 104729) % 2147483646 + 1]

        def rnd():
            rs[0] = rs[0] * 16807 % 2147483647
            return rs[0] / 2147483647
        N = 7
        c = 100 / N
        for gy in range(N):
            for gx in range(N):
                r1, r2, r3, r4 = rnd(), rnd(), rnd(), rnd()
                bw, bh = c - 3 - r2 * 4, c - 3 - r3 * 4
                bx, by = gx * c + 1.5, gy * c + 1.5
                cx, cy = bx + bw / 2, by + bh / 2
                if r1 < 0.12:
                    continue
                dm = 1000.0
                for s in segs:
                    dm = min(dm, _map3d_segdist(cx, cy, s['ax'], s['ay'], s['bx'], s['by']))
                for s in sts:
                    dm = min(dm, math.sqrt((s['x'] - cx) * (s['x'] - cx) + (s['y'] - cy) * (s['y'] - cy)) - 3)
                if dm < 7:
                    continue
                d = math.sqrt((cx - 50) * (cx - 50) + (cy - 50) * (cy - 50)) / 70.7
                blocks.append((bx, by, bw, bh, (3 + (1 - d) * 14 * r4 + r4 * 4) * max(0.2, min(1.0, (dm - 7) / 18))))
    faces = ''
    for (x, y, w, h, ht) in blocks:
        faces += ('<div class="m3-b" style="left:' + _map3d_f(x) + '%;top:' + _map3d_f(y) + '%;width:' + _map3d_f(w) + '%;height:' + _map3d_f(h) + '%;--hh:' + _map3d_f(ht * _MAP3D_U) + 'cqw;">'
                  '<i class="m3-t"></i><i class="m3-s"></i><i class="m3-e"></i></div>')

    # route svg
    paths = ''
    for s in segs:
        # a back leg drives in its own lane: shifted 1.2 map units to its right, so a reply never hides the request it answers
        ox = oy = 0.0
        if legs[s['leg']]['back'] and s['len'] > 0:
            ox, oy = -(s['by'] - s['ay']) / s['len'] * 1.2, (s['bx'] - s['ax']) / s['len'] * 1.2
        paths += ('<path data-cb="link" data-key="' + _cv_esc(s['key']) + '" data-leg="' + str(s['leg']) + '" data-m3="seg" d="M' + _map3d_f(s['ax'] + ox, 1) + ',' + _map3d_f(s['ay'] + oy, 1) + ' L' + _map3d_f(s['bx'] + ox, 1) + ',' + _map3d_f(s['by'] + oy, 1)
                  + '" pathLength="1" fill="none" stroke="' + s['color'] + '" stroke-width="1.4" stroke-linejoin="round" style="stroke-dasharray:1 1;stroke-dashoffset:calc(1 - clamp(0,calc((var(--p,1) - '
                  + _map3d_f(s['s'], 3) + ')/' + _map3d_f(max(s['w'], 0.001), 3) + '),1));"></path>')
    svg = ('<svg class="m3-route" aria-hidden="true" focusable="false" viewBox="0 0 100 100" preserveAspectRatio="none">' + paths + '</svg>') if paths else ''

    # stations (pins)
    pins = ''
    for st in sts:
        reach = leave = None
        if st['on']:
            reach = 'clamp(0,calc((var(--p,1) - ' + _map3d_f(st['r'], 3) + ')*40),1)'
            leave = 'clamp(0,calc((var(--p,1) - ' + _map3d_f(st['l'], 3) + ')*40),1)'
        lay = ''
        for name in _MAP3D_STATES:
            final = st['state'] == name
            if reach is None:
                if not final:
                    continue
                op = '1'
            elif name == 'idle':
                op = 'calc(1 - ' + reach + (' + ' + leave if final else '') + ')'
            elif name == 'active':
                op = 'calc(' + reach + '*(1 - ' + leave + ')' + (' + ' + leave if final else '') + ')'
            elif final:
                op = leave
            else:
                continue
            glyph = '!' if name == 'warn' else ('\u00d7' if name == 'error' else '')
            lay += '<span class="m3-pin m3-' + name + '" style="opacity:' + op + ';">' + glyph + '</span>'
        pins += ('<div class="m3-st" data-cb="node" data-key="' + _cv_esc(st['id']) + '" data-m3="station" data-state="' + st['state'] + '" style="left:' + _map3d_f(st['x'], 1) + '%;top:' + _map3d_f(st['y'], 1) + '%;">'
                 '<div class="m3-bb">' + lay + '<span class="m3-lab" data-cb="label" data-key="' + _cv_esc(st['id']) + '">' + _cv_esc(st['label']) + '</span></div></div>')

    # message markup
    msg_html = ''
    for m in messages:
        leg = legs[m['leg']]
        l_rt = list(reversed(leg['route'])) if m['back'] else list(leg['route'])
        pts = [byid[rid] for rid in l_rt]
        # Calculate cumulative lengths
        seg_lens = []
        tot_l = 0.0
        for pi in range(len(pts) - 1):
            dx = pts[pi + 1]['x'] - pts[pi]['x']
            dy = pts[pi + 1]['y'] - pts[pi]['y']
            slen = math.sqrt(dx * dx + dy * dy)
            seg_lens.append(slen)
            tot_l += slen

        cum_f = [0.0]
        cur_l = 0.0
        for slen in seg_lens:
            cur_l += slen
            cum_f.append(cur_l / tot_l if tot_l > 0 else 1.0)
        cum_f[-1] = 1.0

        q_str = 'clamp(0,calc((var(--p,1) - ' + _map3d_f(m['a'], 3) + ')/' + _map3d_f(m['w'], 3) + '),1)'

        x_terms = [_map3d_f(pts[0]['x'], 1)]
        y_terms = [_map3d_f(pts[0]['y'], 1)]
        for pi in range(len(pts) - 1):
            if seg_lens[pi] <= 0:
                continue
            c_prev = cum_f[pi]
            c_next = cum_f[pi + 1]
            c_span = c_next - c_prev
            if c_span <= 0:
                continue
            dx = pts[pi + 1]['x'] - pts[pi]['x']
            dy = pts[pi + 1]['y'] - pts[pi]['y']
            term_sub = 'clamp(0,calc((' + q_str + ' - ' + _map3d_f(c_prev, 3) + ')/' + _map3d_f(c_span, 3) + '),1)'
            if dx != 0:
                x_terms.append(_map3d_f(dx, 1) + '*' + term_sub)
            if dy != 0:
                y_terms.append(_map3d_f(dy, 1) + '*' + term_sub)

        left_calc = 'calc((' + ' + '.join(x_terms) + ')*1%)'
        top_calc = 'calc((' + ' + '.join(y_terms) + ')*1%)'
        op_calc = 'calc(clamp(0,calc((var(--p,1) - ' + _map3d_f(m['a'], 3) + ')*40),1)*(1 - clamp(0,calc((var(--p,1) - ' + _map3d_f(m['a'] + m['w'], 3) + ')*40),1)))'
        col = leg['color']
        msg_html += ('<div class="m3-msg" data-m3="msg" data-leg="' + str(m['leg']) + '" style="left:' + left_calc + ';top:' + top_calc + ';opacity:' + op_calc + ';"><div class="m3-bb"><span class="m3-chip" style="background:'
                     + col + ';">' + _cv_esc(m['text']) + '</span></div></div>')

    # over plane
    over_content = pins + msg_html
    over_plane = ('<div class="m3-plane m3-over" style="transform:rotateX(calc(var(--tilt)*var(--e)*1deg)) rotateZ(calc(var(--rz)*var(--e)*1deg)) scale(var(--zm));">'
                  + over_content + '</div>') if over_content else ''

    # clock
    ck = _m3_obj(b.get('clock'))
    c_unit = ck.get('unit') if isinstance(ck.get('unit'), str) else 'hhmm'
    chip = ''
    clock_alt = ''
    if c_unit in ('s', 'ms'):
        raw_c0 = ck.get('from')
        raw_c1 = ck.get('to')
        c0_ok = isinstance(raw_c0, (int, float)) and not isinstance(raw_c0, bool) and math.isfinite(raw_c0) and raw_c0 >= 0
        c1_ok = isinstance(raw_c1, (int, float)) and not isinstance(raw_c1, bool) and math.isfinite(raw_c1) and raw_c1 >= 0
        cap = 86400 if c_unit == 's' else 3600000
        if c0_ok and c1_ok:
            fc0 = int(math.floor(raw_c0))
            fc1 = int(math.floor(raw_c1))
            if fc0 <= cap and fc1 <= cap and fc1 >= fc0:
                chip = ('<div class="m3-clk m3-clk-u" data-m3="clock" data-u="' + c_unit + '" aria-hidden="true" style="--m0:' + str(fc0) + ';--m1:' + str(fc1) + ';"><span class="m3-cs">'
                        + str(fc1) + ' ' + c_unit + '</span><span class="m3-cn"></span></div>')
                clock_alt = 'Clock runs from ' + str(fc0) + ' ' + c_unit + ' to ' + str(fc1) + ' ' + c_unit + '.'
    else:
        c0, c1 = _map3d_clock(ck.get('from')), _map3d_clock(ck.get('to'))
        if c0 is not None and c1 is not None:
            if c1 < c0:
                c1 += 1440
            chip = ('<div class="m3-clk" data-m3="clock" aria-hidden="true" style="--m0:' + str(c0) + ';--m1:' + str(c1) + ';"><span class="m3-cs">' + _map3d_hhmm(c1) + '</span><span class="m3-cn"></span></div>')
            clock_alt = 'Clock runs from ' + _map3d_hhmm(c0) + ' to ' + _map3d_hhmm(c1) + '.'

    # text alternative
    alt = []
    if legs:
        if len(legs) == 1 and not legs_mode:
            alt.append('Route: ' + ', then '.join(byid[r]['label'] for r in legs[0]['route']) + '.')
        elif len(legs) == 1:
            back_str = ' (back)' if legs[0]['back'] else ''
            alt.append('Leg 1' + back_str + ': ' + ', then '.join(byid[r]['label'] for r in legs[0]['route']) + '.')
        else:
            leg_sentences = []
            for idx, leg in enumerate(legs):
                back_str = ' (back)' if leg['back'] else ''
                leg_sentences.append('Leg ' + str(idx + 1) + back_str + ': ' + ', then '.join(byid[r]['label'] for r in leg['route']) + '.')
            alt.append(' '.join(leg_sentences))

    if sts:
        alt.append('Stations: ' + '; '.join(s['label'] + ' (' + s['state'] + ')' for s in sts) + '.')

    if messages:
        m_parts = []
        for m in messages:
            leg = legs[m['leg']]
            l_rt = list(reversed(leg['route'])) if m['back'] else list(leg['route'])
            start_lab = byid[l_rt[0]]['label']
            end_lab = byid[l_rt[-1]]['label']
            m_parts.append(m['text'] + ' (' + start_lab + ' to ' + end_lab + ')')
        alt.append('Messages: ' + '; '.join(m_parts) + '.')

    if clock_alt:
        alt.append(clock_alt)

    altx = '<div data-m3="alt" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);">' + _cv_esc(' '.join(alt) or 'City map.') + '</div>'
    css = ('<style>@property --m3m{syntax:"<integer>";initial-value:0;inherits:false}@property --m3h{syntax:"<integer>";initial-value:0;inherits:false}@property --m3n{syntax:"<integer>";initial-value:0;inherits:false}'
           '.m3-root{position:relative;display:block;box-sizing:border-box;width:100%;max-width:100%;aspect-ratio:16/9;overflow:hidden;container-type:inline-size;isolation:isolate;border-radius:12px;'
           'background:color-mix(in srgb,var(--text,#0f172a) 6%,var(--surface,#f8fafc))}'
           '.m3-stage{position:absolute;inset:0;perspective:90cqw;perspective-origin:50% 50%}'
           '.m3-plane{position:absolute;left:19cqw;top:-3cqw;width:62cqw;height:62cqw;transform-style:preserve-3d;'
           'background:color-mix(in srgb,var(--text,#0f172a) 11%,var(--surface,#f8fafc));box-shadow:0 0 0 0.3cqw var(--border,#cbd5e1)}'
           '.m3-plane.m3-over{background:none;box-shadow:none;pointer-events:none}'
           '.m3-b{position:absolute;transform-style:preserve-3d}.m3-b i{position:absolute;display:block}'
           '.m3-t{inset:0;transform:translateZ(var(--hh));background:color-mix(in srgb,var(--text,#0f172a) 4%,var(--surface,#ffffff))}'
           '.m3-s{left:0;top:100%;width:100%;height:var(--hh);transform-origin:50% 0;transform:rotateX(90deg);background:color-mix(in srgb,var(--text,#0f172a) 26%,var(--surface,#ffffff))}'
           '.m3-e{left:100%;top:0;width:var(--hh);height:100%;transform-origin:0 50%;transform:rotateY(-90deg);background:color-mix(in srgb,var(--text,#0f172a) 17%,var(--surface,#ffffff))}'
           '.m3-route{position:absolute;inset:0;width:100%;height:100%;overflow:visible;transform:translateZ(0.15cqw);pointer-events:none}'
           '.m3-st{position:absolute;width:0;height:0;transform-style:preserve-3d}'
           '.m3-bb{position:absolute;left:0;top:0;transform-style:preserve-3d;transform:rotateZ(calc(var(--rz)*var(--e)*-1deg)) rotateX(calc(var(--tilt)*var(--e)*-1deg)) scale(calc(1/var(--zm))) translateY(-1.5cqw)}'
           '.m3-pin{position:absolute;left:-1.1cqw;top:-1.1cqw;width:2.2cqw;height:2.2cqw;box-sizing:border-box;border-radius:50%;border:0.45cqw solid var(--surface,#fff);'
           'display:flex;align-items:center;justify-content:center;color:#fff;font:800 1.5cqw/1 ui-sans-serif,system-ui,sans-serif}'
           '.m3-idle{background:var(--muted,#64748b)}.m3-active{background:' + acc + ';box-shadow:0 0 0 0.5cqw color-mix(in srgb,' + acc + ' 35%,transparent)}.m3-done{background:var(--mt-ok,#22c55e)}'
           '.m3-warn{background:var(--mt-warn,#f59e0b)}.m3-error{background:var(--mt-err,#dc2626)}'
           '.m3-lab{position:absolute;left:1.6cqw;top:-1.1cqw;white-space:nowrap;font:600 max(10px,1.7cqw)/1.2 ui-sans-serif,system-ui,sans-serif;color:var(--text,#0f172a);'
           'background:color-mix(in srgb,var(--surface,#ffffff) 88%,transparent);padding:0.15cqw 0.7cqw;border-radius:0.6cqw}'
           '.m3-msg{position:absolute;width:0;height:0;transform-style:preserve-3d}'
           '.m3-chip{position:absolute;left:-0.2cqw;top:-4.4cqw;white-space:nowrap;font:700 max(10px,1.5cqw)/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;color:#fff;padding:0.3cqw 0.8cqw;border-radius:0.6cqw;box-shadow:0 1px 4px rgba(0,0,0,0.3)}'
           '.m3-clk{position:absolute;left:2.4cqw;top:2.4cqw;z-index:2;font:700 max(13px,2.6cqw)/1 ui-monospace,SFMono-Regular,Menlo,monospace;font-variant-numeric:tabular-nums;color:var(--text,#0f172a);'
           'background:var(--surface,#ffffff);border:1px solid var(--border,#cbd5e1);border-radius:999px;padding:0.8cqw 1.8cqw;box-shadow:0 2px 8px rgba(0,0,0,0.15)}'
           '.m3-cn{display:none}'
           '@supports (width:round(down,1px,1px)){.m3-cs{display:none}.m3-cn{display:inline;--m3m:calc(var(--m0) + (var(--m1) - var(--m0))*clamp(0,calc((var(--p,1) - 0.3)/0.62),1));'
           '--m3h:mod(round(down,calc(var(--m3m)/60),1),24);--m3n:mod(var(--m3m),60);counter-reset:m3h var(--m3h) m3n var(--m3n)}'
           '.m3-clk:not(.m3-clk-u) .m3-cn::before{content:counter(m3h,decimal-leading-zero) ":" counter(m3n,decimal-leading-zero)}'
           '.m3-clk-u .m3-cn{counter-reset:m3t var(--m3m)}.m3-clk-u[data-u="s"] .m3-cn::before{content:counter(m3t) " s"}.m3-clk-u[data-u="ms"] .m3-cn::before{content:counter(m3t) " ms"}}'
           '@media (prefers-reduced-motion:reduce),print{.m3-root{--p:1!important}}</style>')
    root_vars = ('--tilt:' + _map3d_f(tilt, 1) + ';--rz:22;--z0:' + _map3d_f(z0, 2) + ';--z1:' + _map3d_f(z1, 2) + ';'
                 '--c:clamp(0,calc(var(--p,1)/0.3),1);--e:calc(var(--c)*var(--c)*(3 - 2*var(--c)));--zm:calc(var(--z0) + (var(--z1) - var(--z0))*var(--e));')
    # camera.follow (v2): with no keys, re-angle the camera as the route arrives at every Nth station and at the last one
    fol = _ff_int(cam.get('follow'), 0, 0, 6) if cam.get('follow') is not None else 0
    if not ckeys and fol and segs:
        ckeys = [(0.0, 0.0, 0.0, z0), (_MAP3D_P0, 22.0, tilt, z1)]
        stops = [i for i in range(len(segs)) if (i + 1) % fol == 0 or i == len(segs) - 1]
        for j, i in enumerate(stops):
            arr = segs[i]['s'] + segs[i]['w']
            last = i == len(segs) - 1
            pose = (22.0 - 45.0, max(0.0, tilt - 10), min(3.0, z1 * 1.3)) if last else (_MAP3D_TURNS[j % 6], tilt if j % 2 else max(0.0, tilt - 12), z1)
            t0 = max(ckeys[-1][0] + 0.001, arr - 0.06)
            if t0 < arr:
                ckeys.append((t0,) + ckeys[-1][1:])
                ckeys.append((arr,) + pose)
    if ckeys:
        root_vars = ('--tilt:' + _map3d_keyed(ckeys, 2, 1) + ';--rz:' + _map3d_keyed(ckeys, 1, 1) + ';--e:1;--zm:' + _map3d_keyed(ckeys, 3, 2) + ';')
    if kbad:
        notes.append(str(kbad) + (' camera key was' if kbad == 1 else ' camera keys were') + ' left out (at must be a number from 0 to 1, each later than the one before; at most 8).')
    plane = ('<div class="m3-plane" style="transform:rotateX(calc(var(--tilt)*var(--e)*1deg)) rotateZ(calc(var(--rz)*var(--e)*1deg)) scale(var(--zm));">'
             + faces + svg + '</div>')
    note = _hg_note(' '.join(notes)) if notes else ''
    return (css + '<div class="m3-root" data-m3="root" style="' + root_vars + '">' + altx + '<div class="m3-stage" aria-hidden="true">' + plane + over_plane + '</div>' + chip + '</div>'
            + note + _map3d_version_note(b))


_RENDERERS['motion_map3d'] = _render_motion_map3d


# ─── heatmap variants (additive; twin of the heatmap block at the end of atoms_infographic.gs) ───────────────────────────────────────
