_HM_NAMES = {k.lower(): k for k in _HM_SCALES}
_HM_KEYS = ('z_min', 'z_max', 'z_mid', 'scale', 'show_colorbar', 'show_values', 'value_format', 'version')
_HM_CAP = 40
_HM_COMPACT = 8


def _hm_num(v):
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) <= 1e12 else None


def _hm_rgb(sc, t):
    st = _HM_SCALES[sc] if isinstance(sc, str) else sc
    t = min(1.0, max(0.0, t))
    for i in range(1, len(st)):
        if t <= st[i][0] or i == len(st) - 1:
            p0, c0 = st[i - 1]
            p1, c1 = st[i]
            f = 0.0 if p1 == p0 else min(1.0, max(0.0, (t - p0) / (p1 - p0)))
            return tuple(_if_round(c0[k] + (c1[k] - c0[k]) * f) for k in range(3))
    return st[0][1]


def _hm_domain(vals, zmin, zmax, zmid):
    lo = zmin if zmin is not None else min(vals)
    hi = zmax if zmax is not None else max(vals)
    if zmid is not None and not (zmin is not None and zmax is not None):
        d = max(abs(zmid - lo), abs(hi - zmid))
        lo, hi = zmid - d, zmid + d
    return (lo, hi if hi > lo else lo + 1)


def _hm_fmt(x, spec):
    """d3-format subset: [,][.N][f|%|d]. Anything else (or none) is the default: two decimals, trailing zeros trimmed."""
    m = re.fullmatch(r'(,)?(?:\.([0-9]))?([f%d])?', spec) if isinstance(spec, str) and spec else None
    if m is None:
        s = _if_fixed(x, 2)
        return (s.rstrip('0').rstrip('.') if '.' in s else s)
    typ = m.group(3)
    d = int(m.group(2)) if m.group(2) else (0 if typ in ('%', 'd') else 2)
    if typ is None and not m.group(2):
        s = _if_fixed(x, 2)
        s = s.rstrip('0').rstrip('.') if '.' in s else s
    else:
        s = _if_fixed(x * 100 if typ == '%' else x, d)
    if m.group(1):
        neg = s.startswith('-')
        ip, _, fp = s.lstrip('-').partition('.')
        g = ''
        while len(ip) > 3:
            g = ',' + ip[-3:] + g
            ip = ip[:-3]
        s = ('-' if neg else '') + ip + g + ('.' + fp if fp else '')
    return s + ('%' if typ == '%' else '')


def _hm_hex_scale(v):
    if not isinstance(v, list) or len(v) < 2:
        return None
    out = []
    for c in v[:32]:
        m = re.fullmatch(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})', c) if isinstance(c, str) else None
        if not m:
            return None
        h = m.group(1)
        h = ''.join(ch + ch for ch in h) if len(h) == 3 else h
        out.append((len(out), (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))))
    n = len(out) - 1
    return [(i / n, c) for i, (_, c) in enumerate(out)]


def _hm_lab(v):
    """A label is a non-empty string or a finite non-zero number; anything else (objects, arrays, booleans) counts as missing."""
    if isinstance(v, str):
        return v or None
    if isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) != float('inf') and v != 0:
        return _if_str(v)
    return None


def _hm_pivot(raw):
    """Legacy [{row, col, value}] items -> (matrix, row labels, col labels), in order of first appearance; None if raw is not that shape."""
    if not (isinstance(raw, list) and raw and all(isinstance(x, dict) for x in raw) and any('value' in x for x in raw)):
        return None
    ry, cx, cell = [], [], {}
    for x in raw:
        r, c = _hm_lab(_if_g(x, 'row')), _hm_lab(_if_g(x, 'col'))
        if r is None or c is None:
            continue
        if r not in ry:
            ry.append(r)
        if c not in cx:
            cx.append(c)
        cell[(r, c)] = _if_g(x, 'value')
    return [[cell.get((r, c)) for c in cx] for r in ry], ry, cx


def _hm_ext(b):
    raw = _if_g(b, 'data')
    piv = _hm_pivot(raw)
    if piv:
        raw = piv[0]
    rows_in = raw if isinstance(raw, list) else []
    nr_all = len(rows_in)
    nc_all = max([len(r) for r in rows_in if isinstance(r, list)] + [0])
    R, C = min(_HM_CAP, nr_all), min(_HM_CAP, nc_all)
    grid = [[_hm_num(rows_in[i][j]) if isinstance(rows_in[i], list) and j < len(rows_in[i]) else None for j in range(C)] for i in range(R)]
    vals = [v for r in grid for v in r if v is not None]
    capnote = ''
    if nr_all > R:
        capnote += _hg_note('Showing the first ' + str(R) + ' of ' + str(nr_all) + ' rows.')
    if nc_all > C:
        capnote += _hg_note('Showing the first ' + str(C) + ' of ' + str(nc_all) + ' columns.')
    if not vals:
        return _if_wrap(_if_title(b) + '<div style="' + _if_card() + '">A heatmap needs at least one number in data.</div>' + capnote + _hg_version_note(b, 'heatmap'))
    ly, lx = _if_g(b, 'labels_y'), _if_g(b, 'labels_x')
    ly = ly if isinstance(ly, list) else (_if_g(b, 'rows') if isinstance(_if_g(b, 'rows'), list) else [])
    lx = lx if isinstance(lx, list) else (_if_g(b, 'cols') if isinstance(_if_g(b, 'cols'), list) else [])
    if piv:
        ly, lx = piv[1], piv[2]
    rl = [_hm_lab(ly[i])[:24] if i < len(ly) and _hm_lab(ly[i]) else 'Row ' + str(i + 1) for i in range(R)]
    cl = [_hm_lab(lx[j])[:24] if j < len(lx) and _hm_lab(lx[j]) else 'Col ' + str(j + 1) for j in range(C)]
    notes = capnote
    sname, stops = _if_g(b, 'scale'), None
    if isinstance(sname, str) and sname.lower() in _HM_NAMES:
        stops = _HM_SCALES[_HM_NAMES[sname.lower()]]
    elif _if_truthy(sname):
        notes += _hg_note('Unknown scale' + (' "' + _if_s(sname, 30) + '"' if isinstance(sname, str) else '') + '; drawn with Viridis.')
    if stops is None:
        stops = (_hm_hex_scale(_if_g(b, 'color_scale')) if not _if_truthy(sname) else None) or _HM_SCALES['Viridis']
    zmin, zmax, zmid = _hm_num(_if_g(b, 'z_min')), _hm_num(_if_g(b, 'z_max')), _hm_num(_if_g(b, 'z_mid'))
    lo, hi = _hm_domain(vals, zmin, zmax, zmid)
    mid_on = zmid is not None and not (zmin is not None and zmax is not None)
    spec = _if_g(b, 'value_format')
    if _if_truthy(spec) and not (isinstance(spec, str) and re.fullmatch(r'(,)?(?:\.([0-9]))?([f%d])?', spec)):
        notes += _hg_note('value_format "' + _if_s(spec, 20) + '" is not understood (use , .N and f, % or d); values use the default format.')
        spec = None

    def f(x):
        return _hm_fmt(x, spec)
    unit = _if_str(_if_g(b, 'unit'))[:12] if _if_truthy(_if_g(b, 'unit')) else ''
    us = ' ' + unit if unit else ''
    show = _if_g(b, 'show_values') is True
    compact = C > _HM_COMPACT
    if compact:
        if show:
            notes += _hg_note('Values are not drawn above ' + str(_HM_COMPACT) + ' columns (the grid is squeezed to fit); hover a cell or read the table.')
        show = False
        k = -(-C // 4)
        hdr = ''.join('<div style="font-size:12px;line-height:1.25;text-align:left;overflow-wrap:anywhere;color:var(--muted,#475569);padding:0 2px 2px;grid-column:span ' + str(min(k, C - j)) + ';">' + _if_s(cl[j], 24) + '</div>' for j in range(0, C, k))
    else:
        hdr = ''.join('<div style="font-size:12px;line-height:1.25;text-align:center;overflow-wrap:anywhere;color:var(--muted,#475569);padding:0 2px 2px;">' + _if_s(c, 24) + '</div>' for c in cl)
    mh = '16' if compact else '32'
    cells = '<div></div>' + hdr
    nmiss = 0
    for i in range(R):
        cells += '<div style="font-size:12px;line-height:1.25;text-align:right;overflow-wrap:anywhere;max-width:110px;display:flex;align-items:center;justify-content:flex-end;padding-right:6px;color:var(--muted,#475569);">' + _if_s(rl[i], 24) + '</div>'
        for j in range(C):
            v = grid[i][j]
            tip = _if_s(rl[i] + ', ' + cl[j] + ': ', 60)
            if v is None:
                nmiss += 1
                cells += '<div class="hmc hmn" title="' + tip + 'no data" style="min-height:' + mh + 'px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;font-size:12px;border:1px dashed var(--muted,#475569);color:var(--muted,#475569);">–</div>'
                continue
            r, g, bl = _hm_rgb(stops, (v - lo) / (hi - lo))
            fg = '#fff' if 0.299 * r + 0.587 * g + 0.114 * bl < 140 else '#111'
            cells += ('<div class="hmc" title="' + tip + _if_s(f(v) + us, 30) + '" style="min-height:' + mh + 'px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;font-size:12px;overflow-wrap:anywhere;background:rgb('
                      + str(r) + ',' + str(g) + ',' + str(bl) + ');color:' + fg + ';">' + (_if_s(f(v), 20) if show else '') + '</div>')
    if nmiss:
        notes += _hg_note(str(nmiss) + (' cell has' if nmiss == 1 else ' cells have') + ' no usable number and ' + ('is' if nmiss == 1 else 'are') + ' marked "no data".')
    aria = 'Heatmap, ' + str(R) + (' row' if R == 1 else ' rows') + ' by ' + str(C) + (' column' if C == 1 else ' columns') + ', values from ' + f(min(vals)) + ' to ' + f(max(vals)) + us + '.'
    grid_html = ('<div class="hms" style="max-width:100%;overflow-x:auto;"><div role="img" aria-label="' + _if_s(aria, 200) + '" style="display:grid;grid-template-columns:minmax(72px,auto) repeat(' + str(C) + ',minmax(0,1fr));gap:2px;width:100%;max-width:' + str(120 + C * 96) + 'px;">' + cells + '</div></div>')
    bar = ''
    if _if_g(b, 'show_colorbar') is not False:
        grad = ','.join('rgb(%d,%d,%d) %s%%' % (*c, _if_fmt(p * 100)) for p, c in stops)
        bar = ('<div class="hmb" style="display:flex;align-items:center;gap:8px;margin-top:8px;font-size:12px;color:var(--muted,#475569);"><span style="max-width:35%;overflow-wrap:anywhere;">' + _if_s(f(lo) + us, 30)
               + '</span><div style="flex:1 0 60px;height:12px;border:1px solid var(--border,#CBD5E1);border-radius:3px;background:linear-gradient(to right,' + grad + ');"></div><span style="max-width:35%;overflow-wrap:anywhere;">' + _if_s(f(hi) + us, 30) + '</span></div>')
        if mid_on:
            bar += _hg_note('Colour midpoint: ' + _if_s(f(zmid) + us, 30) + '.')
    table = _if_table(['Row'] + cl, [[rl[i]] + [('no data' if grid[i][j] is None else f(grid[i][j]) + us) for j in range(C)] for i in range(R)])
    return _if_wrap('<div class="ifhm" style="max-width:100%;">' + _if_title(b) + grid_html + bar + notes + _hg_version_note(b, 'heatmap') + table + '</div>')


def _hm_matrix_prep(b):
    """Schema-shaped payload (data = list of lists): the legacy color_scheme name (purple, blue, ...) becomes a named scale when no scale or
    color_scale is given, so the grid reads the same fields as the Apps Script twin."""
    if not isinstance(b, dict) or _if_truthy(_if_g(b, 'scale')) or _hm_hex_scale(_if_g(b, 'color_scale')):
        return b
    cs = _if_g(b, 'color_scheme')
    if isinstance(cs, str):
        for k in (cs.lower(), cs.lower() + 's'):
            if k in _HM_NAMES:
                return dict(b, scale=_HM_NAMES[k])
    return b


def _hm_wrap(prev):
    def go(b):
        if isinstance(b, dict) and (any(k in b for k in _HM_KEYS) or _hmg_is_matrix(b.get('data'))):
            return _hm_ext(_hm_matrix_prep(b))
        return prev(b)
    return go


_RENDERERS['heatmap'] = _hm_wrap(_RENDERERS['heatmap'])
# ─── histogram2d (preview): d3.bin() twice, drawn through the heatmap atom ───────────────────────────────────────────────────────────
# Twin of _h2* in apps-script-surface/gas-wired-renderer/atoms_infographic.gs. The bin edges are d3-array 3.2.4 bin() (ISC, Mike Bostock; see _hg_bin),
# one run per axis; a cell counts the points that fall in both bins. The drawing, colour bar and hidden table are the registered heatmap renderer's.
_H2_PTS = 20000
_H2_BINS = 40


def _h2_axis(vals, target):
    """d3 bin edges for one axis and the bin index of every value: ([(x0, x1), ...], [index, ...])."""
    import bisect as _bisect
    edges, _ = _hg_bin(vals, target)
    inner = [e[0] for e in edges[1:]]
    return edges, [_bisect.bisect_right(inner, v) for v in vals]


def _h2_axis_capped(vals, target):
    """Like _h2_axis, but asks for fewer bins until the heatmap's 40-column cap holds (d3 may return up to about twice the requested count)."""
    t = target
    while True:
        edges, idx = _h2_axis(vals, t)
        if len(edges) <= _H2_BINS:
            return edges, idx
        t = (t if t is not None else max(1, math.ceil(math.log(len(vals)) / math.log(2)) + 1)) - 1
        if t < 2:
            return edges, idx


def _h2_counts(edges_x, ix, edges_y, iy):
    counts = [[0] * len(edges_x) for _ in edges_y]
    for a, c in zip(ix, iy):
        counts[c][a] += 1
    return counts


def _h2_bin(xs, ys, nx, ny):
    """d3.bin() on x and on y; returns (x edges, y edges, counts[y bin][x bin]), y ascending. xs, ys: equal-length finite floats, at least one."""
    ex, ix = _h2_axis(xs, nx)
    ey, iy = _h2_axis(ys, ny)
    return ex, ey, _h2_counts(ex, ix, ey, iy)


def _h2_labels(edges):
    d = _hg_decimals([e for p in edges for e in p])
    return [_hg_num(a, d) if a == b else _hg_num(a, d) + '\u2013' + _hg_num(b, d) for a, b in edges]


def _h2_block(b):
    """-> (heatmap block or None, notes html, usable point count)."""
    rx, ry = _if_g(b, 'x'), _if_g(b, 'y')
    rx, ry = rx if isinstance(rx, list) else [], ry if isinstance(ry, list) else []
    total = min(len(rx), len(ry))
    pts = [(float(u), float(v)) for u, v in zip(rx, ry)
           if isinstance(u, (int, float)) and not isinstance(u, bool) and isinstance(v, (int, float)) and not isinstance(v, bool) and abs(u) <= 1e12 and abs(v) <= 1e12]
    notes = ''
    skipped = total - len(pts)
    if skipped:
        notes += _hg_note(str(skipped) + (' pair was' if skipped == 1 else ' pairs were') + ' not two usable numbers and ' + ('was' if skipped == 1 else 'were') + ' skipped.')
    if len(pts) > _H2_PTS:
        notes += _hg_note('Using the first ' + _hg_num(_H2_PTS, 0) + ' of ' + _hg_num(len(pts), 0) + ' points.')
        pts = pts[:_H2_PTS]
    if len(pts) < 2:
        return None, notes, len(pts)
    xs, ys = [p[0] for p in pts], [p[1] for p in pts]
    ex, ix = _h2_axis_capped(xs, _hg_target(_if_g(b, 'nbinsx')))
    ey, iy = _h2_axis_capped(ys, _hg_target(_if_g(b, 'nbinsy')))
    counts = _h2_counts(ex, ix, ey, iy)
    sname = _if_g(b, 'scale')
    hb = {'type': 'heatmap', 'data': counts[::-1], 'labels_x': _h2_labels(ex), 'labels_y': _h2_labels(ey[::-1]),
          'scale': sname if _if_truthy(sname) else 'YlGnBu', 'value_format': ',.0f',
          'show_values': (len(ex) <= _HM_COMPACT) if _if_g(b, 'show_values') in (None, _IF_UNDEF) else _if_g(b, 'show_values') is not False, 'show_colorbar': _if_g(b, 'show_colorbar') is not False}
    if _if_truthy(_if_g(b, 'title')):
        hb['title'] = _if_g(b, 'title')
    xl, yl = _if_g(b, 'x_label'), _if_g(b, 'y_label')
    peak = max(max(r) for r in counts)
    notes = (_hg_note('Columns bin x' + (' (' + _if_s(xl, 40) + ')' if _if_truthy(xl) else '') + ', rows bin y' + (' (' + _if_s(yl, 40) + ')' if _if_truthy(yl) else '')
                      + ', highest y at the top. ' + _hg_num(len(pts), 0) + ' points in ' + str(len(ey)) + (' row' if len(ey) == 1 else ' rows') + ' by ' + str(len(ex))
                      + (' column' if len(ex) == 1 else ' columns') + '; the busiest cell holds ' + _hg_num(peak, 0) + '.') + notes)
    return hb, notes, len(pts)


def _render_histogram2d(b):
    hb, notes, n = _h2_block(b if isinstance(b, dict) else {})
    ver = _hg_version_note(b, 'histogram2d')
    if hb is None:
        return _if_wrap(_if_title(b) + '<div style="' + _if_card() + '">A histogram2d needs at least two points with a usable x and y.</div>' + notes + ver)
    hm = _RENDERERS['heatmap'](hb)   # already wrapped: put the notes inside its wrapper, not in a second one
    return hm[:-6] + notes + ver + '</div>'


_RENDERERS['histogram2d'] = _render_histogram2d


# ─── image_plot (preview): a pixel matrix or a safe image source, with axes ─────────────────────────────────────────────────────────
# Twin of _ip* in apps-script-surface/gas-wired-renderer/atoms_infographic.gs. Tick labels are HTML text (12px at any width); the pixels are one SVG of
# crisp rectangles (equal neighbours in a row merged); a src is drawn only when it is an https URL or a base64 PNG/JPEG/GIF/WebP data: URI.
_IP_CAP = 64
_IP_HEX = re.compile(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})')
_IP_HTTPS = re.compile(r'https://[A-Za-z0-9.-]+(:[0-9]{1,5})?(/[A-Za-z0-9\-._~:/?#\[\]@!$&()*+,;=%]*)?')
_IP_DATA = re.compile(r'data:image/(png|jpeg|gif|webp);base64,[A-Za-z0-9+/]+={0,2}')


def _ip_num(v):
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and abs(v) <= 1e12 else None


def _ip_color(c):
    if isinstance(c, str):
        m = _IP_HEX.fullmatch(c)
        if not m:
            return None
        h = m.group(1).lower()
        return '#' + (''.join(ch * 2 for ch in h) if len(h) == 3 else h)
    if isinstance(c, list) and len(c) == 3:
        n = [_ip_num(v) for v in c]
        if None in n:
            return None
        return '#' + ''.join('%02x' % int(min(255, max(0, _if_round(v)))) for v in n)
    return None


def _ip_src(v):
    if not isinstance(v, str):
        return None
    if len(v) <= 2000 and _IP_HTTPS.fullmatch(v):
        return v
    if len(v) <= 300000 and _IP_DATA.fullmatch(v):
        return v
    return None


def _ip_range(v):
    if isinstance(v, list) and len(v) == 2:
        a, b = _ip_num(v[0]), _ip_num(v[1])
        if a is not None and b is not None and a != b:
            return a, b
    return None


def _ip_axis(rng, vertical, room):
    """Tick labels for one axis as absolutely positioned HTML text: (html, widest label in characters). The tick count is lowered from 5 until the labels fit in `room` px."""
    a, b = rng
    lo, hi = min(a, b), max(a, b)
    for cnt in (5, 4, 3, 2):
        ticks = [t for t in _hg_ticks(lo, hi, cnt) if lo <= t <= hi]
        d = _hg_decimals(ticks)
        labs = [_hg_num(t, d) for t in ticks]
        w = max([len(x) for x in labs] + [0])
        if len(ticks) * (30 if vertical else w * 7 + 16) <= room:
            break
    html = ''
    for t, lab in zip(ticks, labs):
        pct = (t - a) / (b - a) * 100
        if vertical:
            pos = 'right:0;top:' + _if_fmt(pct) + '%;transform:translateY(-50%);'
        else:
            pos = 'left:' + _if_fmt(pct) + '%;transform:translateX(' + ('0' if pct < 6 else '-100%' if pct > 94 else '-50%') + ');'
        html += '<span style="position:absolute;' + pos + 'font-size:12px;line-height:1;white-space:nowrap;">' + _if_s(lab, 20) + '</span>'
    return html, w


def _ip_range_text(r):
    d = _hg_decimals(list(r))
    return _hg_num(r[0], d) + ' to ' + _hg_num(r[1], d)


def _render_image_plot(b):
    b = b if isinstance(b, dict) else {}
    notes = ''
    z, src_raw = _if_g(b, 'z'), _if_g(b, 'src')
    rows_in = z if isinstance(z, list) else []
    R = min(_IP_CAP, len(rows_in))
    C = min(_IP_CAP, max([len(r) for r in rows_in if isinstance(r, list)] + [0]))
    grid = [[_ip_color(rows_in[i][j]) if isinstance(rows_in[i], list) and j < len(rows_in[i]) else None for j in range(C)] for i in range(R)]
    nvalid = sum(1 for r in grid for c in r if c)
    src = _ip_src(src_raw)
    as_matrix = R > 0 and C > 0 and nvalid > 0
    if as_matrix and _if_truthy(src_raw):
        notes += _hg_note('Both z and src were given; z is drawn.')
    if not as_matrix and src is None:
        if _if_truthy(src_raw) and isinstance(src_raw, str):
            return _if_wrap(_if_title(b) + _hg_note('The image source is not allowed (use an https URL or a base64 PNG, JPEG, GIF or WebP data: URI); nothing was drawn.') + _hg_version_note(b, 'image_plot'))
        return _if_wrap(_if_title(b) + '<div style="' + _if_card() + '">An image_plot needs a z matrix or a src.</div>' + _hg_version_note(b, 'image_plot'))
    if as_matrix:
        if len(rows_in) > R:
            notes += _hg_note('Showing the first ' + str(R) + ' of ' + str(len(rows_in)) + ' rows.')
        wide = max([len(r) for r in rows_in if isinstance(r, list)] + [0])
        if wide > C:
            notes += _hg_note('Showing the first ' + str(C) + ' of ' + str(wide) + ' columns.')
        nb = R * C - nvalid
        if nb:
            notes += _hg_note(str(nb) + (' cell is' if nb == 1 else ' cells are') + ' not a colour and ' + ('was' if nb == 1 else 'were') + ' left blank.')
    xr_in, yr_in = _if_g(b, 'x_range'), _if_g(b, 'y_range')
    xr, yr = _ip_range(xr_in), _ip_range(yr_in)
    for nm, raw, got in (('x_range', xr_in, xr), ('y_range', yr_in, yr)):
        if _if_truthy(raw) and got is None:
            notes += _hg_note(nm + ' must be two different numbers; ' + ('the cell numbers are used.' if as_matrix else 'no ticks are drawn.'))
    if as_matrix:
        xr, yr = xr or (0.0, float(C)), yr or (0.0, float(R))
    wmin = min(250, min(640, max(40, C * 20))) if as_matrix else 250
    hmin = max(36, wmin * R / C) if as_matrix else 100
    xt, xw = _ip_axis(xr, False, wmin) if xr else ('', 0)
    yt, yw = _ip_axis(yr, True, hmin) if yr else ('', 0)
    alt = _if_g(b, 'alt')
    if as_matrix:
        aria = 'Image, ' + str(R) + (' row' if R == 1 else ' rows') + ' by ' + str(C) + (' column' if C == 1 else ' columns') + ' of pixels, x from ' + _hg_num(xr[0], _hg_decimals(list(xr))) + ' to ' + _hg_num(xr[1], _hg_decimals(list(xr))) + ', y from ' + _hg_num(yr[0], _hg_decimals(list(yr))) + ' to ' + _hg_num(yr[1], _hg_decimals(list(yr))) + '.'
        rects = ''
        for i in range(R):
            j = 0
            while j < C:
                c = grid[i][j]
                k = j
                while c and k + 1 < C and grid[i][k + 1] == c:
                    k += 1
                if c:
                    rects += '<rect x="' + str(j) + '" y="' + str(i) + '" width="' + str(k - j + 1) + '" height="1" fill="' + c + '"/>'
                j = k + 1
        plot = ('<svg viewBox="0 0 ' + str(C) + ' ' + str(R) + '" preserveAspectRatio="none" shape-rendering="crispEdges" aria-hidden="true" focusable="false" '
                'style="display:block;width:100%;height:auto;aspect-ratio:' + str(C) + '/' + str(R) + ';min-height:36px;">' + rects + '</svg>')
        maxw = str(min(640, max(40, C * 20)) + 56)
        table = _if_table(['Row'] + ['Col ' + str(j + 1) for j in range(C)], [['Row ' + str(i + 1)] + [grid[i][j] or 'blank' for j in range(C)] for i in range(R)])
    else:
        aria = 'Picture, no text description given' + (', x from ' + _ip_range_text(xr) + ', y from ' + _ip_range_text(yr) if xr and yr else '') + '.'
        plot = '<img src="' + _esc(src) + '" alt="" referrerpolicy="no-referrer" loading="lazy" decoding="async" style="display:block;width:100%;height:auto;">'
        maxw = '640'
        rr = [['x', _if_fmt(xr[0]), _if_fmt(xr[1])] if xr else ['x', 'none', 'none'], ['y', _if_fmt(yr[0]), _if_fmt(yr[1])] if yr else ['y', 'none', 'none']]
        table = _if_table(['Axis', 'From', 'To'], rr)
    if _if_truthy(alt) and isinstance(alt, str):
        aria = alt
    ylab, xlab = _if_g(b, 'y_label'), _if_g(b, 'x_label')
    muted = 'font-size:12px;line-height:1.3;color:var(--muted,#475569);overflow-wrap:anywhere;'
    ycol = _if_numstr(min(8, max(1.5, _if_round((yw * 0.65 + 0.4) * 10) / 10))) + 'em' if yt else '0'
    grid_html = ('<div style="display:grid;grid-template-columns:' + ycol + ' minmax(0,1fr);column-gap:6px;width:100%;max-width:' + maxw + 'px;padding-top:6px;box-sizing:border-box;">'
                 + '<div style="position:relative;">' + yt + '</div>'
                 + '<div role="img" aria-label="' + _if_s(aria, 200) + '" style="min-width:0;' + ('' if as_matrix else 'min-height:100px;') + 'border:1px solid var(--border,#CBD5E1);">' + plot + '</div>'
                 + '<div></div><div style="position:relative;height:' + ('1.6em' if xt else '0') + ';margin-top:4px;">' + xt + '</div></div>')
    yl = ((('<div style="' + muted + 'margin-bottom:2px;">' + _if_s(ylab, 40) + '</div>') if _if_truthy(ylab) else ''))
    xl = ((('<div style="' + muted + 'text-align:center;max-width:' + maxw + 'px;">' + _if_s(xlab, 40) + '</div>') if _if_truthy(xlab) else ''))
    return _if_wrap('<div data-cb="node" data-key="' + _ck(_if_g(b, 'title'), 'image_plot') + '" class="ifip" style="max-width:100%;">' + _if_title(b) + yl + grid_html + xl + notes + _hg_version_note(b, 'image_plot') + table + '</div>')


_RENDERERS['image_plot'] = _render_image_plot

# --- shared scale/reading helpers choropleth_map needs (defined once in the chart-reading and d3 radial layers on the round-one branch; copied here because this base predates them; identical bodies, drop at the round-one merge) ---
_CR_ACC = 'var(--a2ui-accent,#4f46e5)'

_CR_ACC2 = 'var(--a2ui-accent2,#0e7490)'

_CR_SURF = 'var(--a2ui-surface,#ffffff)'

_CR_TEXT = 'var(--a2ui-text,var(--text,#171717))'

_CR_MUTED = 'var(--a2ui-muted,var(--muted,#595959))'

_CR_SCHEMES = {'sequential': ('accent', 'accent2'), 'diverging': ('accent_pair',), 'categorical': ('accent_cycle',)}

def _cr_mix(a, pa, b):
    return 'color-mix(in srgb,' + a + ' ' + str(pa) + '%,' + b + ')'

_CR_SR = 'position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;'

_CR_BORDER = '1px solid var(--a2ui-muted,var(--muted,#595959))'

_CR_CB_CSS = '<style>[data-cb-root] .cb-fade{opacity:var(--k,1);}</style>'

def _cr_cb(kind, i, n, style='', key=None):
    return (' data-cb="' + kind + '"' + ('' if key is None else ' data-key="' + key + '"') + ' class="cb-fade" style="' + style + '--k:clamp(0,calc(var(--p,1)*' + str(n + 1) + ' - ' + str(i) + '),1);"')

def _cr_s(v, mx):
    """Text field: a string only (anything else is empty), cut to mx characters, escaped."""
    return _cv_esc(v[:mx]) if isinstance(v, str) else ''

def _cr_id(*parts):
    """Per-payload id suffix: 32-bit FNV-1a over the UTF-16 code units of the parts (the same arithmetic as _crId in the JavaScript twin), base 36."""
    h = 2166136261
    raw = '\x1f'.join(parts).encode('utf-16-le')
    for i in range(0, len(raw), 2):
        h = ((h ^ (raw[i] | (raw[i + 1] << 8))) * 16777619) & 0xFFFFFFFF
    n, out = h, ''
    while True:
        out = '0123456789abcdefghijklmnopqrstuvwxyz'[n % 36] + out
        n //= 36
        if not n:
            return out

def _cr_fixed(x, d):
    """JavaScript Number.prototype.toFixed: exact binary value, ties rounded up in magnitude, a sign for any x < 0."""
    q = decimal.Decimal(abs(x)).quantize(decimal.Decimal(1).scaleb(-d), rounding=decimal.ROUND_HALF_UP)
    return ('-' if x < 0 else '') + format(q, 'f')

def _cr_trim(x):
    """Up to three decimals, trailing zeros dropped, never '-0'."""
    s = _cr_fixed(x, 3)
    s = re.sub(r'(\.\d*?)0+$', r'\1', s)
    s = re.sub(r'\.$', '', s)
    return '0' if s == '-0' else s

def _cr_num(v):
    """A finite number that is not a boolean and is at most 1e15 in size; None otherwise."""
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        return None
    try:
        v = float(v)
    except OverflowError:
        return None
    return v if v == v and abs(v) <= 1e15 else None

def _d3_round(x):
    """JavaScript Math.round: nearest, ties toward +infinity."""
    f = math.floor(x)
    return f + 1 if x - f >= 0.5 else f


# ─── choropleth_map (I41, 2026-10-21, stage: preview; D3 target, owner decision D10). Twin of apps-script-surface/*/atoms_choropleth.gs. ───
# Server-side SVG, one path per region, quantized (equal-interval) classes coloured from the theme tokens of the shared scale helpers. The region outlines are the
# bundled sets under atoms/geo (Natural Earth 110m via world-atlas, US Census 10m via us-atlas, both ISC; no custom GeoJSON). Projections are ports of d3-geo 3.1.1 (ISC,
# Mike Bostock): geoEqualEarth and geoAlbersUsa are added here (checked against the real library to 1e-9 by tests/test_choropleth_map.py); geoMercator is _geo_merc above.
# The renderer projects vertices only (no adaptive resampling, no clipping): the 110m data is already coarse and the frame crops what lies outside it.
_CH_SETS = ('world-countries', 'us-states', 'europe-countries')
_CH_PROJ = ('equal-earth', 'mercator', 'albers-usa')
_CH_DIR = Path(__file__).resolve().parent.parent / 'atoms' / 'geo'
_CH_CACHE = {}
_CH_EA = (1.340264, -0.081106, 0.000893, 0.003796)
_CH_EA_M = _gm.sqrt(3) / 2
# Fit window (lon0, lon1, lat0, lat1) per set: only vertices inside it count when the frame is fitted, so Antarctica-free world, Europe without the Russian Far East, and
# the lower 48 plus Alaska and Hawaii without the Aleutians that cross 180 degrees. Vertices outside the window are still drawn and cropped by the frame.
_CH_WIN = {'world-countries': (-180, 180, -58, 84), 'europe-countries': (-25, 45, 34, 72), 'us-states': (-180, -60, 15, 74)}


def _ch_nice(x):
    """Legend break rounded to three significant digits (display only; class edges stay equal intervals)."""
    if x == 0:
        return 0
    e = 2 - math.floor(math.log10(abs(x)))
    if e >= 0:
        m = 10 ** e
        return math.floor(x * m + 0.5) / m
    m = 10 ** (-e)
    return math.floor(x / m + 0.5) * m


def _ch_load(name):
    if name not in _CH_CACHE:
        d = _json.loads((_CH_DIR / (name + '.json')).read_text(encoding='utf-8'))
        if d.get('enc') == 'd100':  # rings are stored as centi-degree integer deltas (first pair absolute); decoded to the same floats the old files held
            for r in d['regions']:
                for poly in r['p']:
                    for k, ring in enumerate(poly):
                        ax = ay = 0
                        out = []
                        for i in range(0, len(ring), 2):
                            ax += ring[i]
                            ay += ring[i + 1]
                            out += [ax / 100, ay / 100]
                        poly[k] = out
        _CH_CACHE[name] = d
    return _CH_CACHE[name]


def _ch_regions(rset):
    """[(id, name, polygons)] in file order; europe-countries is the filtered subset of world-countries."""
    if rset == 'europe-countries':
        ids = set(_ch_load('europe-countries')['ids'])
        return [(r['id'], r['name'], r['p']) for r in _ch_load('world-countries')['regions'] if r['id'] in ids]
    return [(r['id'], r['name'], r['p']) for r in _ch_load(rset)['regions']]


def _ch_equal_earth(k, tx, ty, nowrap=False):
    """d3.geoEqualEarth().scale(k).translate([tx, ty]) -> f(lon, lat) = [x, y]. nowrap leaves a longitude beyond +-180 where it is (a map drawn across the seam)."""
    def f(lo, la):
        q = (lo * _GEO_D2R, la * _GEO_D2R) if nowrap else _geo_ident(lo * _GEO_D2R, la * _GEO_D2R)
        t = _gm.asin(_CH_EA_M * _gm.sin(q[1]))
        t2 = t * t
        t6 = t2 * t2 * t2
        a1, a2, a3, a4 = _CH_EA
        x = q[0] * _gm.cos(t) / (_CH_EA_M * (a1 + 3 * a2 * t2 + t6 * (7 * a3 + 9 * a4 * t2)))
        y = t * (a1 + a2 * t2 + t6 * (a3 + a4 * t2))
        return [tx + k * x, ty - k * y]
    return f


def _ch_conic(p0, p1, rot, cen, k, tx, ty):
    """d3.geoConicEqualArea().parallels([p0, p1]).rotate([rot, 0]).center(cen).scale(k).translate([tx, ty])."""
    y0, y1 = p0 * _GEO_D2R, p1 * _GEO_D2R
    sy0 = _gm.sin(y0)
    n = (sy0 + _gm.sin(y1)) / 2
    c = 1 + sy0 * (2 * n - sy0)
    r0 = _gm.sqrt(c) / n
    rl = _geo_rl(rot * _GEO_D2R)

    def raw(lam, phi):
        r = _gm.sqrt(c - 2 * n * _gm.sin(phi)) / n
        lam = lam * n
        return [r * _gm.sin(lam), r0 - r * _gm.cos(lam)]
    ce = raw(cen[0] * _GEO_D2R, cen[1] * _GEO_D2R)
    dx, dy = tx - k * ce[0], ty + k * ce[1]

    def f(lo, la):
        q = rl(lo * _GEO_D2R, la * _GEO_D2R)
        r = raw(q[0], q[1])
        return [dx + k * r[0], dy - k * r[1]]
    return f


def _ch_albers_parts(k, tx, ty):
    """The three projections of d3.geoAlbersUsa (lower 48, Alaska, Hawaii) and their clip extents (x0, y0, x1, y1)."""
    e = _GEO_EPS
    return [(_ch_conic(29.5, 45.5, 96, (-0.6, 38.7), k, tx, ty), (tx - 0.455 * k, ty - 0.238 * k, tx + 0.455 * k, ty + 0.238 * k)),
            (_ch_conic(55, 65, 154, (-2, 58.5), k * 0.35, tx - 0.307 * k, ty + 0.201 * k), (tx - 0.425 * k + e, ty + 0.120 * k + e, tx - 0.214 * k - e, ty + 0.234 * k - e)),
            (_ch_conic(8, 18, 157, (-3, 19.9), k, tx - 0.205 * k, ty + 0.212 * k), (tx - 0.214 * k + e, ty + 0.166 * k + e, tx - 0.115 * k - e, ty + 0.234 * k - e))]


def _ch_albers_usa(k, tx, ty):
    """d3.geoAlbersUsa().scale(k).translate([tx, ty]) -> f(lon, lat) = [x, y], or None where no part of the composite shows the point."""
    parts = _ch_albers_parts(k, tx, ty)

    def f(lo, la):
        for pr, (x0, y0, x1, y1) in parts:
            p = pr(lo, la)
            if x0 <= p[0] <= x1 and y0 <= p[1] <= y1:
                return p
        return None
    return f


def _ch_r1(v):
    return _gm.floor(v * 10 + 0.5) / 10


def _ch_path(polys, pr):
    d = ''
    for poly in polys:
        for ring in poly:
            pts, lx, ly = '', None, None
            n = 0
            for i in range(0, len(ring), 2):
                p = pr(ring[i], ring[i + 1])
                x, y = _ch_r1(p[0]), _ch_r1(p[1])
                if x != lx or y != ly:
                    pts += (' ' if n else '') + _geo_jsnum(x) + ' ' + _geo_jsnum(y)
                    n += 1
                    lx, ly = x, y
            if n >= 3:
                d += 'M' + pts + 'Z'
    return d


def _ch_merc_nowrap(lo, la):
    """d3.geoMercator() at k=1, no translate, with no wrap of a longitude beyond +-180 (a map drawn across the seam)."""
    p = max(-_GEO_MAXLAT, min(_GEO_MAXLAT, la * _GEO_D2R))
    return [0 + lo * _GEO_D2R, 0 - _gm.log(_gm.tan((_GEO_PI / 2 + p) / 2))]


def _ch_w180(x):
    """x wrapped into -180..180 the way d3 wraps a longitude (180 stays 180)."""
    return x - _geo_round(x / 360) * 360 if abs(x) > 180 else x


def _ch_lam0(fr):
    """Central meridian of a travel frame: the frame's centre when it crosses the antimeridian (lon_min above lon_max) or reaches +-180, else 0 (nothing rotates)."""
    if fr is None:
        return 0
    if fr[0] > fr[1]:
        return (fr[0] + fr[1] + 360) / 2
    if fr[0] <= -180 or fr[1] >= 180:
        return (fr[0] + fr[1]) / 2
    return 0


def _ch_in_lon(fr, x):
    return (fr[0] <= x <= fr[1]) if fr[0] <= fr[1] else (x >= fr[0] or x <= fr[1])


def _ch_path_f(polys, pr, rid, fr, lam0, w, h):
    """The outline path of one region: _ch_path for an unframed map; in a frame the rings are also drawn a world to the west and east (so land past +-180 shows when the canvas
    reaches there), and under a rotated central meridian each ring is unwrapped first so a ring crossing the new seam stays one piece instead of streaking across the canvas."""
    if fr is None:
        return _ch_path(polys, lambda lo_, la_: pr(rid, lo_, la_))
    d = ''
    for poly in polys:
        for ring in poly:
            n2 = len(ring) // 2
            if lam0:
                lons = []
                prev = None
                for i in range(n2):
                    r = _ch_w180(ring[2 * i] - lam0) if prev is None else prev + _ch_w180(ring[2 * i] - lam0 - prev)
                    lons.append(r + lam0)
                    prev = r
            else:
                lons = [ring[2 * i] for i in range(n2)]
            for sh in (0, 360, -360):
                pts, lx, ly, n = '', None, None, 0
                bx0 = by0 = float('inf')
                bx1 = by1 = float('-inf')
                for i in range(n2):
                    p = pr(rid, lons[i] + sh, ring[2 * i + 1])
                    x, y = _ch_r1(p[0]), _ch_r1(p[1])
                    bx0, bx1, by0, by1 = min(bx0, x), max(bx1, x), min(by0, y), max(by1, y)
                    if x != lx or y != ly:
                        pts += (' ' if n else '') + _geo_jsnum(x) + ' ' + _geo_jsnum(y)
                        n += 1
                        lx, ly = x, y
                if n >= 3 and ((sh == 0 and not lam0) or (bx1 >= 0 and bx0 <= w and by1 >= 0 and by0 <= h)):
                    d += 'M' + pts + 'Z'
    return d


_CH_FRAME_KEYS = ('lon_min', 'lon_max', 'lat_min', 'lat_max')


def _ch_frame_read(f, proj, notes):
    """The optional frame {lon_min, lon_max, lat_min, lat_max} as (lon0, lon1, lat0, lat1), or None (with a note when it was given but not usable).
    Longitude is clamped to -180..180, latitude to -85..85 (Mercator has no poles), and a span under 1 degree is widened to 1 around its centre."""
    if f is None:
        return None
    if proj == 'albers-usa':
        notes.append('frame is not used with the albers-usa projection (a fixed composite); the whole map is drawn.')
        return None
    v = [_cr_num(f.get(k)) for k in _CH_FRAME_KEYS] if isinstance(f, dict) else [None] * 4
    if any(x is None for x in v):
        notes.append('frame must be {lon_min, lon_max, lat_min, lat_max}, four finite numbers; the whole map is drawn.')
        return None
    lo0, lo1, la0, la1 = max(-180.0, min(180.0, v[0])), max(-180.0, min(180.0, v[1])), max(-85.0, min(85.0, v[2])), max(-85.0, min(85.0, v[3]))
    if lo0 == lo1 or lo0 - lo1 == 360 or not la0 < la1:
        notes.append('frame needs lat_min below lat_max and lon_min different from lon_max (after clamping to -180..180 and -85..85; lon_min above lon_max crosses the antimeridian); the whole map is drawn.')
        return None
    if lo0 > lo1:   # crosses the antimeridian: lon_min .. 180, -180 .. lon_max
        if lo1 + 360 - lo0 < 1:
            c = (lo0 + lo1 + 360) / 2
            lo0, lo1 = _ch_w180(c - 0.5), _ch_w180(c + 0.5)
    elif lo1 - lo0 < 1:
        c = (lo0 + lo1) / 2
        lo0, lo1 = max(-180.0, c - 0.5), min(180.0, c + 0.5)
    if la1 - la0 < 1:
        c = (la0 + la1) / 2
        la0, la1 = max(-85.0, c - 0.5), min(85.0, c + 0.5)
    return lo0, lo1, la0, la1


def _ch_frame(rset, proj, regs, fr=None):
    """(project(region_id, lon, lat), width, height): albers-usa is d3's default frame; the others are fitted to the set's window, or to fr = (lon0, lon1, lat0, lat1)
    when a travel frame is given: then the canvas is always 960 x 540 (so two frames of one film share a box) and the frame is centred in it; the map beyond the
    frame is drawn and cropped by the viewBox."""
    if proj == 'albers-usa':
        lo48, ak, hi = (p[0] for p in _ch_albers_parts(1070, 480, 250))
        return (lambda rid, lo, la: ak(lo, la) if rid == 'AK' else hi(lo, la) if rid == 'HI' else lo48(lo, la)), 960, 500
    if fr is not None:
        u = _ch_equal_earth(1, 0, 0, True) if proj == 'equal-earth' else _ch_merc_nowrap
        lam0 = _ch_lam0(fr)
        lo0, lo1, la0, la1 = fr
        lo0, lo1 = lo0 - lam0, (lo1 + 360 if lo0 > lo1 else lo1) - lam0   # the frame in the rotated longitude (centred on lam0)
        x0 = y0 = float('inf')
        x1 = y1 = float('-inf')
        for t in range(33):
            a, c = lo0 + (lo1 - lo0) * t / 32, la0 + (la1 - la0) * t / 32
            for lo_, la_ in ((a, la0), (a, la1), (lo0, c), (lo1, c)):
                q = u(lo_, la_)
                x0, x1, y0, y1 = min(x0, q[0]), max(x1, q[0]), min(y0, q[1]), max(y1, q[1])
        pad = 4
        k = min((960 - 2 * pad) / (x1 - x0), (540 - 2 * pad) / (y1 - y0))
        tx, ty = 480 - k * (x0 + x1) / 2, 270 - k * (y0 + y1) / 2

        def fitf(rid, lo, la):
            q = u(lo - lam0, la)
            return [tx + k * q[0], ty + k * q[1]]
        return fitf, 960, 540
    u = _ch_equal_earth(1, 0, 0) if proj == 'equal-earth' else _geo_merc([0, 0], 1, 0, 0)
    w0, w1, a0, a1 = _CH_WIN[rset]
    x0 = y0 = float('inf')
    x1 = y1 = float('-inf')
    for _id, _nm, polys in regs:
        for poly in polys:
            for ring in poly:
                for i in range(0, len(ring), 2):
                    if w0 <= ring[i] <= w1 and a0 <= ring[i + 1] <= a1:
                        p = u(ring[i], ring[i + 1])
                        x0, x1, y0, y1 = min(x0, p[0]), max(x1, p[0]), min(y0, p[1]), max(y1, p[1])
    pad = 4
    k = (960 - 2 * pad) / (x1 - x0)
    h = (y1 - y0) * k + 2 * pad
    if h > 640:
        k = (640 - 2 * pad) / (y1 - y0)
        h = 640
    h = _gm.ceil(h)
    tx, ty = 480 - k * (x0 + x1) / 2, h / 2 - k * (y0 + y1) / 2

    def fit(rid, lo, la):
        p = u(lo, la)
        return [tx + k * p[0], ty + k * p[1]]
    return fit, 960, h


_CH_SEAS = 'border-radius:10px;'


def _ch_sea(w, h, rset, fr):
    """A framed map reads as a window: a sea tint (a mix of two theme tokens) behind the land, and rounded corners on the svg. No tint when the frame reaches past the region set's
    window (Europe's North Africa and Asia Minor are not in the set, so a tint would paint them as sea)."""
    w0, w1, a0, a1 = _CH_WIN[rset]
    if fr[0] < w0 or fr[1] > w1 or fr[2] < a0 or fr[3] > a1 or (fr[0] > fr[1] and (w0 > -180 or w1 < 180)):
        return ''
    return '<rect data-sea="1" width="' + str(w) + '" height="' + str(h) + '" style="fill:' + _cr_mix(_CR_ACC2, 16, _CR_SURF) + ';"/>'


def _ch_frame_note(regs, fr, notes):
    """A note when no outline of the set has a vertex inside the frame."""
    for _id, _nm, polys in regs:
        for poly in polys:
            for ring in poly:
                for i in range(0, len(ring), 2):
                    if _ch_in_lon(fr, ring[i]) and fr[2] <= ring[i + 1] <= fr[3]:
                        return
    notes.append('frame contains no region of this set, so no outline is drawn inside it.')


_CH_CATMAX = 6
_CH_CATTOK = {'accent': _CR_ACC, 'accent2': _CR_ACC2, 'text': _CR_TEXT, 'muted': _CR_MUTED}
# Pattern per category slot, so colour is never the only cue: dots, horizontal, vertical, cross-hatch, backslash stripes and large dots. The
# "no data" hatch of choropleth_map is the forward slash on the surface colour, so it cannot be mistaken for a category.
_CH_PATS = ('<circle cx="4" cy="4" r="1.5"/>', '<line x1="0" y1="4" x2="8" y2="4"/>', '<line x1="4" y1="0" x2="4" y2="8"/>',
            '<line x1="0" y1="4" x2="8" y2="4"/><line x1="4" y1="0" x2="4" y2="8"/>', '<line x1="4" y1="0" x2="4" y2="8" transform="rotate(-45 4 4)"/>', '<circle cx="4" cy="4" r="2.8"/>')


def _ch_ws(v):
    """Strip the same six ASCII whitespace characters in both twins (str.strip and String.trim differ on exotic spaces)."""
    return v.strip(' \t\n\r\f\v')


def _ch_cat_default(j):
    return (_CR_ACC, _CR_ACC2, _cr_mix(_CR_ACC, 45, _CR_SURF), _cr_mix(_CR_ACC2, 45, _CR_SURF), _cr_mix(_CR_TEXT, 45, _CR_SURF), _cr_mix(_CR_MUTED, 40, _CR_SURF))[j]


def _ch_cat_read(cats, cc, entries, field, index, notes, derive):
    """(cats, colours, got {region id: category index}, error, unknown ids, repeated ids). cats are the category names (text, max 40, up to 6); b['categories'] fixes their order, else (derive)
    they are the first-seen names of the entries. colours: b['category_colors'] maps a name to a theme token name (accent, accent2, text or muted), else the default palette
    by slot. An entry (id, field) with an id not in the map, a repeated id, or a category that is not in categories is skipped and counted in a note."""
    if cats is not None and (not isinstance(cats, list) or any(not isinstance(c, str) or _ch_ws(c) == '' for c in cats) or len(cats) < 1):
        return None, None, None, 'categories must be a list of 1 to ' + str(_CH_CATMAX) + ' category names.', None, None
    if cats is not None:
        cats = [_ch_ws(c)[:40] for c in cats]
        cats = [c for k, c in enumerate(cats) if c not in cats[:k]]
        if len(cats) > _CH_CATMAX:
            notes.append('Only the first ' + str(_CH_CATMAX) + ' categories were used.')
            cats = cats[:_CH_CATMAX]
    elif derive:
        cats = []
        for e in entries:
            c = e.get(field) if isinstance(e, dict) else None
            if isinstance(c, str) and _ch_ws(c) != '' and _ch_ws(c)[:40] not in cats and len(cats) < _CH_CATMAX:
                cats.append(_ch_ws(c)[:40])
    else:
        return None, None, None, 'categories must be a list of 1 to ' + str(_CH_CATMAX) + ' category names.', None, None
    cc = cc if isinstance(cc, dict) else {}
    cols, badc = [], 0
    for j, c in enumerate(cats):
        t = cc.get(c)
        if t is not None and not (isinstance(t, str) and t in _CH_CATTOK):
            badc += 1
        cols.append(_CH_CATTOK[t] if isinstance(t, str) and t in _CH_CATTOK else _ch_cat_default(j))
    if badc:
        notes.append(str(badc) + (' category colour is' if badc == 1 else ' category colours are') + ' not accent, accent2, text or muted; the default colour was used.')
    got, unknown, dup, skipped, nocat = {}, [], [], 0, 0
    for e in entries:
        c = e.get(field) if isinstance(e, dict) else None
        rid = e.get('id') if isinstance(e, dict) else None
        if not isinstance(c, str) or _ch_ws(c) == '' or not isinstance(rid, str) or _ch_ws(rid) == '':
            skipped += 1
            continue
        rid = _ch_ws(rid).upper()
        c = _ch_ws(c)[:40]
        if rid not in index:
            unknown.append(rid)
        elif rid in got:
            dup.append(rid)
        elif c not in cats:
            nocat += 1
        else:
            got[rid] = cats.index(c)
    if skipped:
        notes.append(str(skipped) + (' entry was' if skipped == 1 else ' entries were') + ' skipped: each needs an id and a category name.')
    if nocat:
        notes.append(str(nocat) + (' entry names' if nocat == 1 else ' entries name') + ' a category that is not in categories and was skipped.')
    return cats, cols, got, None, unknown, dup


def _ch_cat_defs(pid, cols):
    """The <pattern> elements of the used category slots (every slot has a pattern)."""
    d = ''
    for j, c in enumerate(cols):
        d += ('<pattern id="' + pid + 'c' + str(j) + '" width="8" height="8" patternUnits="userSpaceOnUse"><rect width="8" height="8" style="fill:' + c + ';"/><g style="fill:' + _CR_TEXT
              + ';stroke:' + _CR_TEXT + ';stroke-width:1.4;stroke-opacity:0.65;fill-opacity:0.65;">' + _CH_PATS[j] + '</g></pattern>')
    return d


def _ch_cat_fill(pid, cols, j):
    return 'url(#' + pid + 'c' + str(j) + ')'


def _ch_cat_swatch(pid, cols, j):
    return ('<svg aria-hidden="true" focusable="false" width="16" height="16" viewBox="0 0 16 16" style="flex:none;"><rect width="16" height="16" rx="3" style="fill:' + _ch_cat_fill(pid, cols, j)
            + ';stroke:' + _CR_MUTED + ';"/></svg>')


def _ch_err(b, msg):
    t = _cr_s(b.get('title'), 80)
    return ('<div role="note" style="margin:var(--a2ui-block-gap,1.25rem) 0;border:' + _CR_BORDER + ';border-radius:8px;padding:8px 10px;font-size:0.85rem;color:' + _CR_TEXT + ';">'
            + ('<div style="font-weight:700;margin-bottom:4px;">' + t + '</div>' if t else '') + 'Choropleth map not drawn: ' + _cr_s(msg, 200) + '</div>')


def _ch_ids(ids):
    s = ', '.join(_cr_s(i, 12) for i in ids[:8])
    return s + (' and ' + str(len(ids) - 8) + ' more' if len(ids) > 8 else '')


def _ch_color(kind, scheme, j, steps, lo, hi):
    """Class j (0 = lowest) of a quantized scale: the theme-token ramp of the legend, sampled at the class centre."""
    if kind == 'sequential':
        top = _CR_ACC2 if scheme == 'accent2' else _CR_ACC
        return _cr_mix(top, _d3_round(12 + 88 * j / (steps - 1)), _CR_SURF)
    c = lo + (hi - lo) * (j + 0.5) / steps
    m = 0 if lo < 0 < hi else (lo + hi) / 2
    den = max(m - lo, hi - m)
    s = abs(c - m) / den if den > 0 else 0
    p = _d3_round(100 * s)
    return _CR_SURF if p == 0 else _cr_mix(_CR_ACC2 if c < m else _CR_ACC, p, _CR_SURF)


def _render_choropleth_categorical(b: dict, rset: str, proj: str) -> str:
    """choropleth_map with categories: every value is a category name; one colour and one pattern per category (see _ch_cat_read), a legend that lists them, a hidden table."""
    vals = b.get('values')
    if not isinstance(vals, list) or len(vals) < 1:
        return _ch_err(b, 'values must be a list of 1 to 250 {id, value}, each value a category name.')
    notes = []
    if len(vals) > 250:
        notes.append('Only the first 250 of ' + str(len(vals)) + ' values were used.')
        vals = vals[:250]
    regs = _ch_regions(rset)
    index = {r[0]: i for i, r in enumerate(regs)}
    cats, cols, got, err, unknown, dup = _ch_cat_read(b.get('categories'), b.get('category_colors'), vals, 'value', index, notes, False)
    if err:
        return _ch_err(b, err)
    codes = '2-letter USPS codes' if rset == 'us-states' else 'ISO 3166-1 alpha-3 codes'
    if unknown:
        notes.append('Not in the map: ' + _ch_ids(unknown) + '. Ids are ' + codes + '.')
    if dup:
        notes.append('Repeated ids, the first category was used: ' + _ch_ids(dup) + '.')
    if not got:
        return _ch_err(b, 'no value matched a region of ' + rset + ' (ids are ' + codes + ') with a category from categories.')
    valued = sorted(got, key=lambda r: (got[r], index[r]))
    nodata = [r for r in regs if r[0] not in got]
    order = [regs[index[r]] for r in valued] + nodata
    n_tiles = len(order)
    n_all = n_tiles + len(cats)
    frm = _ch_frame_read(b.get('frame'), proj, notes)
    if frm is not None:
        _ch_frame_note(regs, frm, notes)
    pr, w, h = _ch_frame(rset, proj, regs, frm)
    uid = 'ch' + _cr_id('choropleth_map', rset, proj, 'categories', *cats, *cols, *[r + '=' + str(got[r]) for r in valued], *([_cr_trim(x) for x in frm] if frm else []))
    paths = ''
    for i, (rid, nm, polys) in enumerate(order):
        if rid in got:
            fill, tip = _ch_cat_fill(uid, cols, got[rid]), _cr_s(nm, 80) + ': ' + _cv_esc(cats[got[rid]])
        else:
            fill, tip = 'url(#' + uid + ')', _cr_s(nm, 80) + ': no category'
        paths += ('<path' + _cr_cb('tile', i, n_all, 'fill:' + fill + ';stroke:' + _CR_MUTED + ';stroke-width:0.4;fill-rule:evenodd;', _cr_s(rid, 12)) + ' d="'
                  + _ch_path_f(polys, pr, rid, frm, _ch_lam0(frm), w, h) + '"><title>' + tip + '</title></path>')
    defs = _ch_cat_defs(uid, cols)
    if nodata:
        defs += ('<pattern id="' + uid + '" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="6" height="6" style="fill:' + _CR_SURF
                 + ';"/><line x1="0" y1="0" x2="0" y2="6" style="stroke:' + _CR_MUTED + ';stroke-width:1.5;"/></pattern>')
    defs = '<defs>' + defs + '</defs>' if defs else ''
    title = _cr_s(b.get('title'), 80)
    label = (title or 'Choropleth map') + ': ' + str(len(got)) + ' of ' + str(len(regs)) + ' regions have a category, in ' + str(len(cats)) + (' category' if len(cats) == 1 else ' categories')
    svg = ('<svg viewBox="0 0 ' + str(w) + ' ' + str(h) + '" width="100%" role="img" aria-label="' + label + '" focusable="false" style="display:block;max-width:' + str(w) + 'px;height:auto;' + (_CH_SEAS if frm is not None else '') + '">'
           + (_ch_sea(w, h, rset, frm) if frm is not None else '') + defs + paths + '</svg>')
    lt = _cr_s(b.get('legend_title'), 60)
    lis = ''
    for j, c in enumerate(cats):
        lis += ('<li style="display:inline-flex;align-items:center;gap:6px;">' + _ch_cat_swatch(uid, cols, j) + '<span' + _cr_cb('label', n_tiles + j, n_all, '', 'class-' + str(j + 1)) + '>'
                + _cv_esc(c) + '</span></li>')
    if nodata:
        lis += ('<li style="display:inline-flex;align-items:center;gap:6px;"><span aria-hidden="true" style="display:inline-block;flex:none;width:14px;height:14px;border-radius:3px;border:' + _CR_BORDER
                + ';background:repeating-linear-gradient(45deg,' + _CR_MUTED + ' 0 1.5px,' + _CR_SURF + ' 1.5px 5px);"></span><span>No category</span></li>')
    legend = ('<div style="margin-top:8px;">' + ('<div style="font-weight:600;margin-bottom:4px;">' + lt + '</div>' if lt else '')
              + '<ul style="list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:4px 14px;">' + lis + '</ul></div>')
    nt = ''.join('<p role="note" style="margin:6px 0 0;font-size:0.8rem;color:' + _CR_MUTED + ';">' + x + '</p>' for x in notes) + _hg_version_note(b, 'choropleth_map')
    nd = ''
    if nodata:
        nd = ('<details style="margin-top:6px;"><summary>' + str(len(nodata)) + (' region has' if len(nodata) == 1 else ' regions have') + ' no category (hatched)</summary><p style="margin:4px 0 0;">'
              + ', '.join(_cr_s(r[1], 80) for r in nodata) + '</p></details>')
    rows = ''.join('<tr><th scope="row">' + _cr_s(regs[index[r]][1], 80) + '</th><td>' + r + '</td><td>' + _cv_esc(cats[got[r]]) + '</td></tr>' for r in valued)
    table = ('<table style="' + _CR_SR + '"><caption>' + (title or 'Choropleth map') + ', regions with a category, in category order</caption>'
             '<thead><tr><th scope="col">Region</th><th scope="col">Code</th><th scope="col">Category</th></tr></thead><tbody>' + rows + '</tbody></table>')
    return ('<div role="group" aria-label="' + (title or 'Choropleth map') + '" data-cb-root style="--n:' + str(n_all) + ';margin:var(--a2ui-block-gap,1.25rem) 0;color:' + _CR_TEXT + ';font-size:0.85rem;">'
            + _CR_CB_CSS + ('<div style="font-weight:700;font-size:1.05rem;margin:0 0 8px;">' + title + '</div>' if title else '') + svg + legend + nt + nd + table + '</div>')


def _render_choropleth_map(b: dict) -> str:
    b = b if isinstance(b, dict) else {}
    rset = b.get('region_set')
    if rset not in _CH_SETS:
        return _ch_err(b, 'region_set must be world-countries, us-states or europe-countries.')
    proj = b.get('projection')
    if proj is not None and proj not in _CH_PROJ:
        return _ch_err(b, 'projection must be equal-earth, mercator or albers-usa.')
    if proj == 'albers-usa' and rset != 'us-states':
        return _ch_err(b, 'albers-usa only works with region_set us-states.')
    proj = proj or ('albers-usa' if rset == 'us-states' else 'equal-earth')
    if b.get('categories') is not None:
        return _render_choropleth_categorical(b, rset, proj)
    sc = b.get('scale')
    if sc is not None and not isinstance(sc, dict):
        return _ch_err(b, 'scale must be an object {kind, scheme}.')
    sc = sc or {}
    kind = sc.get('kind', 'sequential')
    if kind not in ('sequential', 'diverging'):
        return _ch_err(b, 'scale.kind must be sequential or diverging.')
    scheme = sc.get('scheme')
    scheme = scheme if scheme in _CR_SCHEMES[kind] else _CR_SCHEMES[kind][0]
    vals = b.get('values')
    if not isinstance(vals, list) or len(vals) < 1:
        return _ch_err(b, 'values must be a list of 1 to 250 {id, value}.')
    notes = []
    if len(vals) > 250:
        notes.append('Only the first 250 of ' + str(len(vals)) + ' values were used.')
        vals = vals[:250]
    steps = 5
    if b.get('steps') is not None:
        sv = _cr_num(b.get('steps'))
        if sv is None:
            notes.append('steps must be a number from 3 to 9; using 5.')
        else:
            steps = int(max(3, min(9, _d3_round(sv))))
            if steps != sv:
                notes.append('steps must be a whole number from 3 to 9; using ' + str(steps) + '.')
    regs = _ch_regions(rset)
    index = {r[0]: i for i, r in enumerate(regs)}
    got, unknown, dup, skipped = {}, [], [], 0
    for e in vals:
        v = _cr_num(e.get('value')) if isinstance(e, dict) else None
        rid = e.get('id') if isinstance(e, dict) else None
        if v is None or not isinstance(rid, str) or rid.strip() == '':
            skipped += 1
            continue
        rid = rid.strip().upper()
        if rid not in index:
            unknown.append(rid)
        elif rid in got:
            dup.append(rid)
        else:
            got[rid] = v
    codes = '2-letter USPS codes' if rset == 'us-states' else 'ISO 3166-1 alpha-3 codes'
    if skipped:
        notes.append(str(skipped) + (' entry was' if skipped == 1 else ' entries were') + ' skipped: each needs an id and a finite number value.')
    if unknown:
        notes.append('Not in the map: ' + _ch_ids(unknown) + '. Ids are ' + codes + '.')
    if dup:
        notes.append('Repeated ids, the first value was used: ' + _ch_ids(dup) + '.')
    if not got:
        return _ch_err(b, 'no value matched a region of ' + rset + ' (ids are ' + codes + ').')
    lo, hi = min(got.values()), max(got.values())
    unit_raw = b.get('unit') if isinstance(b.get('unit'), str) else ''
    unit = _cr_s(unit_raw, 12)
    us = (('' if unit_raw[:12] == '%' else ' ') + unit) if unit else ''

    def klass(v):
        return 0 if hi == lo else min(steps - 1, int(_gm.floor((v - lo) / (hi - lo) * steps)))
    fills = [_ch_color(kind, scheme, j, steps, lo, hi) for j in range(steps)]
    bounds = [lo + (hi - lo) * j / steps if j < steps else hi for j in range(steps + 1)]
    valued = sorted(got, key=lambda r: (-got[r], index[r]))
    nodata = [r for r in regs if r[0] not in got]
    order = [regs[index[r]] for r in valued] + nodata
    n_tiles = len(order)
    n_all = n_tiles + steps
    frm = _ch_frame_read(b.get('frame'), proj, notes)
    if frm is not None:
        _ch_frame_note(regs, frm, notes)
    pr, w, h = _ch_frame(rset, proj, regs, frm)
    uid = 'ch' + _cr_id('choropleth_map', rset, proj, kind, str(steps), *[r + '=' + _cr_trim(got[r]) for r in valued], *([_cr_trim(x) for x in frm] if frm else []))
    paths = ''
    for i, (rid, nm, polys) in enumerate(order):
        if rid in got:
            fill, tip = fills[klass(got[rid])], _cr_s(nm, 80) + ': ' + _cr_trim(got[rid]) + us
        else:
            fill, tip = 'url(#' + uid + ')', _cr_s(nm, 80) + ': no data'
        paths += ('<path' + _cr_cb('tile', i, n_all, 'fill:' + fill + ';stroke:' + _CR_MUTED + ';stroke-width:0.4;fill-rule:evenodd;', _cr_s(rid, 12)) + ' d="'
                  + _ch_path_f(polys, pr, rid, frm, _ch_lam0(frm), w, h) + '"><title>' + tip + '</title></path>')
    defs = ''
    if nodata:
        defs = ('<defs><pattern id="' + uid + '" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="6" height="6" style="fill:' + _CR_SURF
                + ';"/><line x1="0" y1="0" x2="0" y2="6" style="stroke:' + _CR_MUTED + ';stroke-width:1.5;"/></pattern></defs>')
    title = _cr_s(b.get('title'), 80)
    label = (title or 'Choropleth map') + ': ' + str(len(got)) + ' of ' + str(len(regs)) + ' regions have a value, from ' + _cr_trim(lo) + us + ' to ' + _cr_trim(hi) + us
    svg = ('<svg viewBox="0 0 ' + str(w) + ' ' + str(h) + '" width="100%" role="img" aria-label="' + label + '" focusable="false" style="display:block;max-width:' + str(w) + 'px;height:auto;' + (_CH_SEAS if frm is not None else '') + '">'
           + (_ch_sea(w, h, rset, frm) if frm is not None else '') + defs + paths + '</svg>')
    lt = _cr_s(b.get('legend_title'), 60)
    lis = ''
    for j in range(steps):
        lis += ('<li style="display:inline-flex;align-items:center;gap:6px;"><span aria-hidden="true" style="display:inline-block;flex:none;width:14px;height:14px;border-radius:3px;border:' + _CR_BORDER
                + ';background:' + fills[j] + ';"></span><span' + _cr_cb('label', n_tiles + j, n_all, '', 'class-' + str(j + 1)) + '>' + _cr_trim(_ch_nice(bounds[j])) + ' to ' + _cr_trim(_ch_nice(bounds[j + 1])) + us + '</span></li>')
    if nodata:
        lis += ('<li style="display:inline-flex;align-items:center;gap:6px;"><span aria-hidden="true" style="display:inline-block;flex:none;width:14px;height:14px;border-radius:3px;border:' + _CR_BORDER
                + ';background:repeating-linear-gradient(45deg,' + _CR_MUTED + ' 0 1.5px,' + _CR_SURF + ' 1.5px 5px);"></span><span>No data</span></li>')
    legend = ('<div style="margin-top:8px;">' + ('<div style="font-weight:600;margin-bottom:4px;">' + lt + '</div>' if lt else '')
              + '<ul style="list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:4px 14px;">' + lis + '</ul></div>')
    nt = ''.join('<p role="note" style="margin:6px 0 0;font-size:0.8rem;color:' + _CR_MUTED + ';">' + x + '</p>' for x in notes) + _hg_version_note(b, 'choropleth_map')
    nd = ''
    if nodata:
        nd = ('<details style="margin-top:6px;"><summary>' + str(len(nodata)) + (' region has' if len(nodata) == 1 else ' regions have') + ' no value (hatched)</summary><p style="margin:4px 0 0;">'
              + ', '.join(_cr_s(r[1], 80) for r in nodata) + '</p></details>')
    rows = ''
    for r in valued:
        v = got[r]
        rows += ('<tr><th scope="row">' + _cr_s(regs[index[r]][1], 80) + '</th><td>' + r + '</td><td>' + _cr_trim(v) + us + '</td><td>' + str(klass(v) + 1) + ' of ' + str(steps) + '</td></tr>')
    table = ('<table style="' + _CR_SR + '"><caption>' + (title or 'Choropleth map') + (' (' + unit + ')' if unit else '') + ', regions with a value, largest first</caption>'
             '<thead><tr><th scope="col">Region</th><th scope="col">Code</th><th scope="col">Value</th><th scope="col">Class</th></tr></thead><tbody>' + rows + '</tbody></table>')
    return ('<div role="group" aria-label="' + (title or 'Choropleth map') + '" data-cb-root style="--n:' + str(n_all) + ';margin:var(--a2ui-block-gap,1.25rem) 0;color:' + _CR_TEXT + ';font-size:0.85rem;">'
            + _CR_CB_CSS + ('<div style="font-weight:700;font-size:1.05rem;margin:0 0 8px;">' + title + '</div>' if title else '') + svg + legend + nt + nd + table + '</div>')


_RENDERERS['choropleth_map'] = _render_choropleth_map


# ─── geo_map (scattergeo parity, 2026-10-21, stage: preview). Twin of apps-script-surface/gas-wired-renderer/atoms_geo_map.gs. ───
# Points and great-circle lines on the choropleth_map outlines and projections (no tiles, no network, no custom GeoJSON). The great circle is the d3-geo 3.1.1 geoInterpolate
# (ISC, Mike Bostock) ported by hand and checked against the real library by tests/test_geo_map.py. Shape + colour per group and a dash per line, so colour is never the only cue.
_GM_SHAPES = ('circle', 'square', 'diamond', 'triangle')
_GM_COLS = (_CR_ACC, _CR_ACC2, _CR_TEXT, _CR_MUTED)
_GM_DASH = ('', '7 4', '2 4')
_GM_MAXPTS, _GM_MAXLINES, _GM_MAXVERT, _GM_MAXGROUPS = 500, 40, 20, 6


def _gm_style(gi):
    """(shape, colour) of group slot gi: the colour index moves on by one every fourth slot, so the 7 slots (6 groups and the ungrouped points) are all different pairs."""
    return _GM_SHAPES[gi % 4], _GM_COLS[(gi + gi // 4) % 4]


def _gm_kb(e, fb):
    """Key of a point or line: its id (text, max 60), else its label (max 40), else fb ('p3' / 'l0': the position in the list as given)."""
    i = e.get('id')
    i = _cr_s(i.strip(), 60) if isinstance(i, str) else ''
    return i or _cr_s(e.get('label'), 40) or fb


def _gm_route_cb(li, i, n, key, style):
    """A route has no fade: it is drawn on by the mask of its mask element (see _render_geo_map), so it carries data-cb/data-key but not cb-fade."""
    return ' data-cb="link" data-key="' + key + '" mask="url(#@@' + str(li) + ')" style="' + style + '"'


def _gm_uniq(base, seen):
    k, n = base, 1
    while k in seen:
        n += 1
        k = base + '~' + str(n)
    seen.add(k)
    return k


def _gm_interp(a, b):
    """d3.geoInterpolate(a, b) -> (f(t) = [lon, lat], distance in radians)."""
    r = _GEO_D2R
    x0, y0, x1, y1 = a[0] * r, a[1] * r, b[0] * r, b[1] * r
    cy0, sy0, cy1, sy1 = _gm.cos(y0), _gm.sin(y0), _gm.cos(y1), _gm.sin(y1)
    kx0, ky0, kx1, ky1 = cy0 * _gm.cos(x0), cy0 * _gm.sin(x0), cy1 * _gm.cos(x1), cy1 * _gm.sin(x1)
    hv = lambda v: _gm.sin(v / 2) ** 2
    d = 2 * _gm.asin(_gm.sqrt(min(1.0, hv(y1 - y0) + cy0 * cy1 * hv(x1 - x0))))
    k = _gm.sin(d)
    if not d:
        return (lambda t: [x0 / r, y0 / r]), d

    def f(t):
        t = t * d
        bb, aa = _gm.sin(t) / k, _gm.sin(d - t) / k
        x, y, z = aa * kx0 + bb * kx1, aa * ky0 + bb * ky1, aa * sy0 + bb * sy1
        return [_gm.atan2(y, x) / r, _gm.atan2(z, _gm.sqrt(x * x + y * y)) / r]
    return f, d


def _gm_err(b, msg):
    t = _cr_s(b.get('title') if isinstance(b, dict) else None, 80)
    return ('<div role="note" style="margin:var(--a2ui-block-gap,1.25rem) 0;border:' + _CR_BORDER + ';border-radius:8px;padding:8px 10px;font-size:0.85rem;color:' + _CR_TEXT + ';">'
            + ('<div style="font-weight:700;margin-bottom:4px;">' + t + '</div>' if t else '') + 'Geo map not drawn: ' + _cr_s(msg, 200) + '</div>')


def _gm_coord(e):
    if not isinstance(e, dict):
        return None
    la, lo = _cr_num(e.get('lat')), _cr_num(e.get('lon'))
    return (la, lo) if la is not None and lo is not None and -90 <= la <= 90 and -180 <= lo <= 180 else None


def _gm_marker(shape, x, y, r, cb, tip):
    a = ' data-shape="' + shape + '" data-r="' + _cr_trim(r) + '" data-xy="' + _geo_jsnum(x) + ',' + _geo_jsnum(y) + '"'
    if shape == 'circle':
        return '<circle' + cb + a + ' cx="' + _geo_jsnum(x) + '" cy="' + _geo_jsnum(y) + '" r="' + _cr_trim(r) + '"><title>' + tip + '</title></circle>'
    if shape == 'square':
        return '<rect' + cb + a + ' x="' + _geo_jsnum(_ch_r1(x - r)) + '" y="' + _geo_jsnum(_ch_r1(y - r)) + '" width="' + _geo_jsnum(_ch_r1(2 * r)) + '" height="' + _geo_jsnum(_ch_r1(2 * r)) + '"><title>' + tip + '</title></rect>'
    pts = ([(0, -1.25), (1.25, 0), (0, 1.25), (-1.25, 0)] if shape == 'diamond' else [(0, -1.2), (1.1, 0.9), (-1.1, 0.9)])
    d = 'M' + 'L'.join(_geo_jsnum(_ch_r1(x + px * r)) + ' ' + _geo_jsnum(_ch_r1(y + py * r)) for px, py in pts) + 'Z'
    return '<path' + cb + a + ' d="' + d + '"><title>' + tip + '</title></path>'


def _render_geo_map(b: dict) -> str:
    b = b if isinstance(b, dict) else {}
    rset = b.get('region_set') if b.get('region_set') is not None else 'world-countries'
    if rset not in _CH_SETS:
        return _gm_err(b, 'region_set must be world-countries, us-states or europe-countries.')
    proj = b.get('projection')
    if proj is not None and proj not in _CH_PROJ:
        return _gm_err(b, 'projection must be equal-earth, mercator or albers-usa.')
    if proj == 'albers-usa' and rset != 'us-states':
        return _gm_err(b, 'albers-usa only works with region_set us-states.')
    proj = proj or ('albers-usa' if rset == 'us-states' else 'equal-earth')
    notes = []
    pts_in, lines_in = b.get('points'), b.get('lines')
    pts_in = pts_in if isinstance(pts_in, list) else []
    lines_in = lines_in if isinstance(lines_in, list) else []
    if len(pts_in) > _GM_MAXPTS:
        notes.append('Only the first ' + str(_GM_MAXPTS) + ' of ' + str(len(pts_in)) + ' points were used.')
        pts_in = pts_in[:_GM_MAXPTS]
    if len(lines_in) > _GM_MAXLINES:
        notes.append('Only the first ' + str(_GM_MAXLINES) + ' of ' + str(len(lines_in)) + ' lines were used.')
        lines_in = lines_in[:_GM_MAXLINES]
    pts, bad = [], 0
    seen = set()
    for ei, e in enumerate(pts_in):
        c = _gm_coord(e)
        if c is None:
            bad += 1
            continue
        pts.append((c[0], c[1], _cr_s(e.get('label'), 40), _cr_num(e.get('value')), e.get('group') if isinstance(e.get('group'), str) and e.get('group').strip() else '', _gm_kb(e, 'p' + str(ei))))
    lines = []
    for ei, e in enumerate(lines_in):
        raw = e.get('path') if isinstance(e, dict) else None
        cs = [_gm_coord(c) for c in raw[:_GM_MAXVERT]] if isinstance(raw, list) else []
        if len(cs) < 2 or any(c is None for c in cs):
            bad += 1
            continue
        lines.append((_cr_s(e.get('label'), 40), cs, _gm_kb(e, 'l' + str(ei))))
    lkeys = [_gm_uniq(l[2], seen) for l in lines]
    pkeys = [_gm_uniq(q[5], seen) for q in pts]
    if bad:
        notes.append(str(bad) + (' entry was' if bad == 1 else ' entries were') + ' skipped: a point needs lat (-90 to 90) and lon (-180 to 180) numbers, a line a path of 2 to ' + str(_GM_MAXVERT) + ' of them.')
    if not pts and not lines:
        return _gm_err(b, 'give points (each {lat, lon}) or lines (each {path: [{lat, lon}, ...]}).')
    groups = []
    for p in pts:
        if p[4] not in groups:
            groups.append(p[4])
    named = [g for g in groups if g != '']
    if len(named) > _GM_MAXGROUPS:
        keep = named[:_GM_MAXGROUPS - 1]
        notes.append('More than ' + str(_GM_MAXGROUPS) + ' groups: the groups after the first ' + str(_GM_MAXGROUPS - 1) + ' are shown as Other.')
        pts = [p[:4] + (p[4] if p[4] in keep or p[4] == '' else 'Other',) + p[5:] for p in pts]
        named = keep + ['Other']
    gidx = {g: i for i, g in enumerate(named)}
    ungi = len(named)
    has_ung = any(p[4] == '' for p in pts)
    vals = [p[3] for p in pts if p[3] is not None]
    lo, hi = (min(vals), max(vals)) if vals else (0, 0)
    unit_raw = b.get('unit') if isinstance(b.get('unit'), str) else ''
    unit = _cr_s(unit_raw, 12)
    us = (('' if unit_raw[:12] == '%' else ' ') + unit) if unit else ''
    regs = _ch_regions(rset)
    fr = _ch_frame_read(b.get('frame'), proj, notes)
    if fr is not None:
        _ch_frame_note(regs, fr, notes)
    pr, w, h = _ch_frame(rset, proj, regs, fr)
    lam0 = _ch_lam0(fr)
    usa = _ch_albers_usa(1070, 480, 250) if proj == 'albers-usa' else None
    shade = b.get('regions')
    shade = shade[:250] if isinstance(shade, list) else []
    cats = cols = None
    got = {}
    if shade:
        cats, cols, got, serr, sunk, sdup = _ch_cat_read(b.get('categories'), b.get('category_colors'), shade, 'category', {r[0]: i for i, r in enumerate(regs)}, notes, True)
        if serr:
            notes.append('regions not shaded: ' + serr)
            cats = cols = None
            got = {}
        else:
            if sunk:
                notes.append('Not in the map: ' + _ch_ids(sunk) + '.')
            if sdup:
                notes.append('Repeated region ids, the first category was used: ' + _ch_ids(sdup) + '.')
            if not got:
                cats = cols = None
            else:
                cols = [_cr_mix(c, 38, _CR_SURF) for c in cols]   # a tint, so the strong marker and route colours (the same tokens) stay readable on a shaded region
    index_ = {r[0]: i for i, r in enumerate(regs)}
    keyed = fr is not None or bool(got)
    pid = ('gc' + _cr_id('geo_map', 'regions', *cats, *cols, *([_cr_trim(x) for x in fr] if fr else []), *[r + '=' + str(got[r]) for r in sorted(got, key=lambda r: index_[r])], *pkeys, *lkeys,
                         *[_cr_trim(x) for q in pts for x in q[:2]], *[_cr_trim(x) for q in lines for c in q[1] for x in c])) if got else ''

    def at(lat, lon):
        if usa:
            return usa(lon, lat)
        if fr is None:
            p = pr('', lon, lat)
            return p if 0 <= p[0] <= w and 0 <= p[1] <= h else None
        lon = lam0 + _ch_w180(lon - lam0) if lam0 else lon
        for sh in (0, 360, -360):   # the world drawn to the west and east of the frame's own (see _ch_path_f)
            p = pr('', lon + sh, lat)
            if 0 <= p[0] <= w and 0 <= p[1] <= h:
                return p
        return None
    base = ''
    for rid, nm, polys in regs:
        fill = _ch_cat_fill(pid, cols, got[rid]) if rid in got else _cr_mix(_CR_MUTED, 12, _CR_SURF)
        kk = (' data-cb="tile" data-key="' + _cr_s(rid, 12) + '"') if keyed else ''
        tt = ('<title>' + _cr_s(nm, 80) + ': ' + _cv_esc(cats[got[rid]]) + '</title>') if rid in got else ''
        base += ('<path data-base="1"' + kk + ' style="fill:' + fill + ';stroke:' + _CR_MUTED + ';stroke-width:' + ('0.9' if fr is not None else '0.4') + ';fill-rule:evenodd;" d="' + _ch_path_f(polys, pr, rid, fr, lam0, w, h)
                 + '"' + ('>' + tt + '</path>' if tt else '/>'))
    n_all = len(lines) + len(pts)
    i, cut = 0, 0
    route_svg, masks = '', ''
    ds_all = []
    for li, (lab, cs, _kb) in enumerate(lines):
        d, seg, prev, pq, lu = '', [], None, None, None
        legs = []
        last = None
        for k in range(len(cs) - 1):
            f, dist = _gm_interp((cs[k][1], cs[k][0]), (cs[k + 1][1], cs[k + 1][0]))
            n = 1 if dist < 1e-9 or _gm.sin(dist) < 1e-9 else max(1, min(64, int(_gm.ceil(dist / 0.0349))))
            ld, lseg = '', ([last] if (k > 0 and prev is not None and last is not None) else [])
            for s_ in range(0 if k == 0 else 1, n + 1):
                q = f(s_ / n) if n > 1 else ([cs[k][1], cs[k][0]] if s_ == 0 else [cs[k + 1][1], cs[k + 1][0]])
                if lam0:   # a rotated frame: the route's longitude is unwrapped, so it runs on across +-180 as one piece
                    lu = lam0 + _ch_w180(q[0] - lam0) if lu is None else lu + _ch_w180(q[0] - pq)
                p = at(q[1], q[0]) if usa else pr('', lu if lam0 else q[0], q[1])
                if p is None:
                    cut += 1
                if p is None or (prev is not None and not lam0 and ((abs(q[0] - pq) > 180) if fr is not None else (abs(p[0] - prev[0]) > w / 2))):
                    if len(seg) >= 2:
                        d += 'M' + ' '.join(seg)
                    seg = []
                    if len(lseg) >= 2:
                        ld += 'M' + ' '.join(lseg)
                    lseg = []
                if p is not None:
                    last = _geo_jsnum(_ch_r1(p[0])) + ' ' + _geo_jsnum(_ch_r1(p[1]))
                    seg.append(last)
                    lseg.append(last)
                prev, pq = p, q[0]
            if len(lseg) >= 2:
                ld += 'M' + ' '.join(lseg)
            legs.append(ld)
        if len(seg) >= 2:
            d += 'M' + ' '.join(seg)
        ds_all.append(d)
        dash = _GM_DASH[li % 3]
        col = _GM_COLS[li % 4]
        tip = (lab or 'Line ' + str(li + 1)) + ': ' + str(len(cs)) + ' points'
        route_svg += ('<path' + _gm_route_cb(li, i, n_all, lkeys[li], 'fill:none;stroke:' + col + ';stroke-width:3;stroke-linecap:round;stroke-linejoin:round;'
                      + ('stroke-dasharray:' + dash + ';' if dash else '')) + ' d="' + d + '"><title>' + tip + '</title></path>')
        masks += ('<mask id="@@' + str(li) + '" maskUnits="userSpaceOnUse" x="0" y="0" width="' + str(w) + '" height="' + str(h) + '">'
                  + ''.join('<path d="' + ld + '" pathLength="1" style="fill:none;stroke:#fff;stroke-width:8;stroke-dasharray:1;stroke-dashoffset:calc(1px*(1 - clamp(0,calc((var(--p,1)*'
                            + str(n_all + 1) + ' - ' + str(i) + ')*' + str(len(legs)) + ' - ' + str(j) + '),1)));"/>' for j, ld in enumerate(legs) if ld) + '</mask>')
        i += 1
    mid = 'gm' + _cr_id('geo_map', rset, proj, *lkeys, *ds_all)
    route_svg = route_svg.replace('url(#@@', 'url(#' + mid)
    masks = masks.replace('id="@@', 'id="' + mid)
    defs_m = '<defs>' + masks + (_ch_cat_defs(pid, cols) if got else '') + '</defs>' if (masks or got) else ''
    mark_svg, outside = '', []
    for pi, (la, lo_, lab, v, g, _pk) in enumerate(pts):
        p = at(la, lo_)
        if p is None:
            outside.append(pi)
            continue
        gi = gidx.get(g, ungi)
        shp, colr = _gm_style(gi)
        r = 8 if not vals else (6 if v is None else (12 if hi == lo else 7 + 11 * _gm.sqrt((v - lo) / (hi - lo))))
        tip = (lab + ': ' if lab else '') + _cr_trim(la) + ', ' + _cr_trim(lo_) + ('' if v is None else ' = ' + _cr_trim(v) + us) + (' (' + _cr_s(g, 40) + ')' if g else '')
        mark_svg += _gm_marker(shp, _ch_r1(p[0]), _ch_r1(p[1]), r, _cr_cb('node', i, n_all, 'fill:' + colr + ';stroke:' + _CR_SURF + ';stroke-width:1.5;', pkeys[pi]), tip)
        i += 1
    if outside:
        notes.append(str(len(outside)) + (' point is' if len(outside) == 1 else ' points are') + ' outside this map\'s frame and not drawn (still listed in the table).')
    if cut:
        notes.append('Lines are cut where they leave the map: the US composite has no place for the path between the lower 48 and Alaska or Hawaii.')
    title = _cr_s(b.get('title'), 80)
    label = ((title or 'Geo map') + ': ' + str(len(pts) - len(outside)) + ' of ' + str(len(pts)) + ' points drawn' + (', ' + str(len(lines)) + (' line' if len(lines) == 1 else ' lines') if lines else '')
             + (' in ' + str(len(named)) + (' group' if len(named) == 1 else ' groups') if named else '')
             + (', ' + str(len(got)) + (' region shaded' if len(got) == 1 else ' regions shaded') + ' in ' + str(len(cats)) + (' category' if len(cats) == 1 else ' categories') if got else ''))
    svg = ('<svg viewBox="0 0 ' + str(w) + ' ' + str(h) + '" width="100%" role="img" aria-label="' + label + '" focusable="false" style="display:block;max-width:' + str(w) + 'px;height:auto;' + (_CH_SEAS if fr is not None else '') + '">'
           + (_ch_sea(w, h, rset, fr) if fr is not None else '') + defs_m + base + route_svg + mark_svg + '</svg>')
    lt = _cr_s(b.get('legend_title'), 60)
    sw = lambda shape, col: ('<svg aria-hidden="true" focusable="false" width="16" height="16" viewBox="-8 -8 16 16" style="flex:none;">' + {
        'circle': '<circle r="5.5"', 'square': '<rect x="-5" y="-5" width="10" height="10"', 'diamond': '<path d="M0 -7L7 0L0 7L-7 0Z"', 'triangle': '<path d="M0 -6.5L6 5L-6 5Z"'}[shape]
        + ' style="fill:' + col + ';stroke:' + _CR_SURF + ';"/></svg>')
    lis = ''
    for gi, g in enumerate(named + (['Ungrouped'] if named and has_ung else [])):
        lis += '<li style="display:inline-flex;align-items:center;gap:6px;">' + sw(*_gm_style(gi)) + '<span>' + _cr_s(g, 40) + '</span></li>'
    for j, c in enumerate(cats or []):
        lis += '<li style="display:inline-flex;align-items:center;gap:6px;">' + _ch_cat_swatch(pid, cols, j) + '<span>' + _cv_esc(c) + '</span></li>'
    for li, (lab, cs, _kb) in enumerate(lines):
        dash = _GM_DASH[li % 3]
        lis += ('<li style="display:inline-flex;align-items:center;gap:6px;"><svg aria-hidden="true" focusable="false" width="28" height="16" viewBox="0 0 28 16" style="flex:none;"><line x1="1" y1="8" x2="27" y2="8" style="stroke:'
                + _GM_COLS[li % 4] + ';stroke-width:2;' + ('stroke-dasharray:' + dash + ';' if dash else '') + '"/></svg><span>' + (lab or 'Line ' + str(li + 1)) + '</span></li>')
    size = (' <p style="margin:4px 0 0;">Marker size: value, from ' + _cr_trim(lo) + us + ' (smallest) to ' + _cr_trim(hi) + us + ' (largest)' + ('; points without a value are smallest' if any(p[3] is None for p in pts) else '') + '.</p>') if vals else ''
    legend = ('<div style="margin-top:8px;">' + ('<div style="font-weight:600;margin-bottom:4px;">' + lt + '</div>' if lt else '')
              + ('<ul style="list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:4px 14px;">' + lis + '</ul>' if lis else '') + size + '</div>')
    nt = ''.join('<p role="note" style="margin:6px 0 0;font-size:0.8rem;color:' + _CR_MUTED + ';">' + x + '</p>' for x in notes) + _hg_version_note(b, 'geo_map')
    prow = ''.join('<tr><th scope="row">' + (lab or 'Point ' + str(k + 1)) + '</th><td>' + _cr_trim(la) + '</td><td>' + _cr_trim(lo_) + '</td><td>' + ('' if v is None else _cr_trim(v) + us) + '</td><td>' + _cr_s(g, 40)
                   + '</td><td>' + ('outside the frame' if k in outside else 'drawn') + '</td></tr>' for k, (la, lo_, lab, v, g, _pk) in enumerate(pts))
    ptable = ('<table style="' + _CR_SR + '"><caption>' + (title or 'Geo map') + ', points</caption><thead><tr><th scope="col">Point</th><th scope="col">Latitude</th><th scope="col">Longitude</th>'
              '<th scope="col">Value</th><th scope="col">Group</th><th scope="col">Status</th></tr></thead><tbody>' + prow + '</tbody></table>') if pts else ''
    lrow = ''.join('<tr><th scope="row">' + (lab or 'Line ' + str(k + 1)) + '</th><td>' + ' to '.join(_cr_trim(c[0]) + ', ' + _cr_trim(c[1]) for c in cs) + '</td><td>' + str(len(cs)) + '</td></tr>' for k, (lab, cs, _kb) in enumerate(lines))
    ltable = ('<table style="' + _CR_SR + '"><caption>' + (title or 'Geo map') + ', lines (great-circle arcs between the listed points)</caption><thead><tr><th scope="col">Line</th>'
              '<th scope="col">Stops (lat, lon), in order</th><th scope="col">Points</th></tr></thead><tbody>' + lrow + '</tbody></table>') if lines else ''
    rtable = ''
    if got:
        ridx = {r[0]: r for r in regs}
        rtable = ('<table style="' + _CR_SR + '"><caption>' + (title or 'Geo map') + ', shaded regions</caption><thead><tr><th scope="col">Region</th><th scope="col">Code</th><th scope="col">Category</th></tr></thead><tbody>'
                  + ''.join('<tr><th scope="row">' + _cr_s(ridx[r][1], 80) + '</th><td>' + _cr_s(r, 12) + '</td><td>' + _cv_esc(cats[got[r]]) + '</td></tr>' for r in sorted(got, key=lambda r: (got[r], list(ridx).index(r))))
                  + '</tbody></table>')
    return ('<div role="group" aria-label="' + (title or 'Geo map') + '" data-cb-root' + (' data-mtr-follow' if keyed else '') + ' style="--n:' + str(n_all) + ';margin:var(--a2ui-block-gap,1.25rem) 0;color:' + _CR_TEXT + ';font-size:0.85rem;">'
            + _CR_CB_CSS + ('<div style="font-weight:700;font-size:1.05rem;margin:0 0 8px;">' + title + '</div>' if title else '') + svg + legend + nt + ptable + ltable + rtable + '</div>')


_RENDERERS['geo_map'] = _render_geo_map


# ─── series[] for chartjs_line and scatter_trend (preview, optional field; absent = the old drawing, byte for byte) ──────────────────
# Plotly scatter / scattergl: per-series x (numbers or dates), y, mode, colour, dash, line shape, marker size and symbol, fill.
# Dates: a UTC subset of d3-time-format (parse ISO 8601, the %-specifiers below) and d3-scale scaleUtc().ticks() (d3-time 3.1.0 tick intervals),
# checked against the real modules by tests/fixtures/series_time_golden.json. Twin: apps-script-surface/gas-wired-renderer/atoms_unstub_series.gs.
_PS_W, _PS_H, _PS_M = 320, 200, 6
_PS_MAX_SERIES, _PS_READ_CAP, _PS_TEXT_CAP = 8, 20000, 30
_PS_MS_MAX, _PS_MS_MIN = 253402300799999, -62135596800000
_PS_PAL = ['#2563EB', '#D97706', '#059669', '#DB2777', '#7C3AED', '#65A30D']
_PS_SYMS = ['circle', 'square', 'diamond', 'triangle-up', 'cross', 'x']
_PS_DASH_NAMES = ['solid', 'dash', 'dot', 'dashdot', 'longdash', 'longdashdot']
_PS_DASH = {'solid': '', 'dash': '6 4', 'dot': '2 4', 'dashdot': '8 4 2 4', 'longdash': '12 5', 'longdashdot': '12 4 2 4'}
_PS_SHAPES = ['linear', 'spline', 'hv', 'vh', 'hvh', 'vhv']
_PS_MODES = ['lines', 'markers', 'text']
_PS_MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
_PS_MONL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
_PS_DAY = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
_PS_DAYL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
_PS_DATE_RE = re.compile(r'^([0-9]{4})(?:-([0-9]{2})(?:-([0-9]{2})(?:[T ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]{1,3})[0-9]*)?)?)?)?)?(Z)?$')
_PS_DIM = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


_PS_NUM_MAX = 1e15   # above the largest epoch-ms date (2.5e14); a larger number is refused, never converted (a Python int can exceed a float)
_PS_WS = ' \t\n\v\f\r\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'   # JavaScript's String.trim set


def _ps_isnum(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) <= _PS_NUM_MAX


def _ps_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _ps_days(y, m, d):
    """Days since 1970-01-01 of a proleptic Gregorian civil date (m 1-12)."""
    y -= 1 if m <= 2 else 0
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _ps_civil(ms):
    """ms -> (Y, M, D, h, mi, s, ms, weekday 0=Sunday, day of year)."""
    ms = int(ms)
    r = ms % 86400000
    z = (ms - r) // 86400000
    h, r = r // 3600000, r % 3600000
    mi, r = r // 60000, r % 60000
    s, milli = r // 1000, r % 1000
    wd = (z + 4) % 7
    z += 719468
    era = z // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    y += 1 if m <= 2 else 0
    yd = _ps_days(y, m, d) - _ps_days(y, 1, 1) + 1
    return (y, m, d, h, mi, s, milli, wd, yd)


def _ps_ms(y, m, d, h, mi, s, milli):
    return _ps_days(y, m, d) * 86400000 + h * 3600000 + mi * 60000 + s * 1000 + milli


def _ps_parse_date(v):
    """ISO 8601 date or date-time string (UTC) -> ms since the epoch, or None."""
    if not isinstance(v, str) or len(v) > 40:
        return None
    m = _PS_DATE_RE.fullmatch(v.strip(_PS_WS))
    if not m:
        return None
    y = int(m.group(1))
    mo = int(m.group(2) or 1)
    d = int(m.group(3) or 1)
    h, mi, s = int(m.group(4) or 0), int(m.group(5) or 0), int(m.group(6) or 0)
    milli = int((m.group(7) or '0').ljust(3, '0'))
    if y < 1 or not 1 <= mo <= 12 or d < 1 or d > _PS_DIM[mo - 1] + (1 if mo == 2 and _ps_leap(y) else 0) or h > 23 or mi > 59 or s > 59:
        return None
    return _ps_ms(y, mo, d, h, mi, s, milli)


def _ps_p2(n, w=2):
    return str(n).rjust(w, '0')


def _ps_utc_format(ms, spec):
    y, m, d, h, mi, s, milli, wd, yd = _ps_civil(ms)
    out = ''
    i = 0
    while i < len(spec):
        c = spec[i]
        if c == '%' and i + 1 < len(spec):
            i += 1
            k = spec[i]
            out += {'Y': lambda: _ps_p2(y, 4), 'y': lambda: _ps_p2(y % 100), 'm': lambda: _ps_p2(m), 'd': lambda: _ps_p2(d),
                    'e': lambda: str(d).rjust(2, ' '), 'H': lambda: _ps_p2(h), 'I': lambda: _ps_p2(h % 12 or 12), 'p': lambda: 'AM' if h < 12 else 'PM',
                    'M': lambda: _ps_p2(mi), 'S': lambda: _ps_p2(s), 'L': lambda: _ps_p2(milli, 3), 'b': lambda: _PS_MON[m - 1],
                    'B': lambda: _PS_MONL[m - 1], 'a': lambda: _PS_DAY[wd], 'A': lambda: _PS_DAYL[wd], 'j': lambda: _ps_p2(yd, 3),
                    '%': lambda: '%'}.get(k, lambda: '%' + k)()
        else:
            out += c
        i += 1
    return out


def _ps_ceil_unit(ms, unit):
    """The first unit boundary at or after ms. unit: second minute hour day week month year."""
    ms = int(ms)
    size = {'second': 1000, 'minute': 60000, 'hour': 3600000, 'day': 86400000}.get(unit)
    if size:
        return -((-ms) // size) * size
    return _ps_floor_unit(ms, unit) if _ps_floor_unit(ms, unit) == ms else _ps_next_unit(_ps_floor_unit(ms, unit), unit)


def _ps_floor_unit(ms, unit):
    ms = int(ms)
    size = {'second': 1000, 'minute': 60000, 'hour': 3600000, 'day': 86400000}.get(unit)
    if size:
        return ms - ms % size
    y, m, d, h, mi, s, milli, wd, yd = _ps_civil(ms)
    day0 = _ps_days(y, m, d)
    if unit == 'week':
        return (day0 - wd) * 86400000
    if unit == 'month':
        return _ps_days(y, m, 1) * 86400000
    return _ps_days(y, 1, 1) * 86400000


def _ps_next_unit(ms, unit):
    """ms is on a boundary of unit; the next boundary."""
    size = {'second': 1000, 'minute': 60000, 'hour': 3600000, 'day': 86400000, 'week': 604800000}.get(unit)
    if size:
        return int(ms) + size
    y, m = _ps_civil(ms)[:2]
    if unit == 'month':
        return _ps_days(y + (1 if m == 12 else 0), 1 if m == 12 else m + 1, 1) * 86400000
    return _ps_days(y + 1, 1, 1) * 86400000


_PS_TICK_IVL = [['second', 1, 1e3], ['second', 5, 5e3], ['second', 15, 15e3], ['second', 30, 30e3], ['minute', 1, 6e4], ['minute', 5, 3e5],
                ['minute', 15, 9e5], ['minute', 30, 18e5], ['hour', 1, 36e5], ['hour', 3, 108e5], ['hour', 6, 216e5], ['hour', 12, 432e5],
                ['day', 1, 864e5], ['day', 2, 1728e5], ['week', 1, 6048e5], ['month', 1, 2592e6], ['month', 3, 7776e6], ['year', 1, 31536e6]]


def _ps_every_ok(ms, unit, k):
    y, m, d, h, mi, s = _ps_civil(ms)[:6]
    if k <= 1:
        return True
    # d3's utc ticker uses unixDay (no field): the day count since the epoch, not the day of the month
    return {'second': s, 'minute': mi, 'hour': h, 'day': int(ms) // 86400000, 'month': m - 1}.get(unit, 0) % k == 0


def _ps_time_ticks(start, stop, count):
    """d3.scaleUtc().domain([start, stop]).ticks(count), as ms."""
    start, stop = int(start), int(stop)
    rev = stop < start
    if rev:
        start, stop = stop, start
    target = abs(stop - start) / count
    i = 0
    while i < len(_PS_TICK_IVL) and _PS_TICK_IVL[i][2] <= target:
        i += 1
    out = []
    lim = stop + 1
    if i == len(_PS_TICK_IVL):
        inc = _hg_tick_increment(start / 31536e6, stop / 31536e6, count)
        k = int(math.floor(inc if inc > 0 else 1 / -inc))
        if k >= 1:
            y = _ps_civil(start)[0]
            yy = (y // k) * k
            t = _ps_days(yy, 1, 1) * 86400000
            while t < start:
                yy += k
                t = _ps_days(yy, 1, 1) * 86400000
            while t < lim and len(out) < 2000:
                out.append(t)
                yy += k
                t = _ps_days(yy, 1, 1) * 86400000
    elif i == 0:
        # a zero-width domain: d3-array's tickIncrement is -Infinity there, so the step is 1 ms
        inc = -_HG_INF if start == stop else _hg_tick_increment(start, stop, count)
        k = max(inc if inc > 0 else 1 / -inc, 1)
        k = int(math.floor(k))
        t = -((-start) // k) * k
        while t < lim and len(out) < 2000:
            out.append(t)
            t += k
    else:
        unit, k = (_PS_TICK_IVL[i - 1] if target / _PS_TICK_IVL[i - 1][2] < _PS_TICK_IVL[i][2] / target else _PS_TICK_IVL[i])[:2]
        t = _ps_ceil_unit(start, unit)
        while t < lim and len(out) < 2000:
            if _ps_every_ok(t, unit, k):
                out.append(t)
            t = _ps_next_unit(t, unit)
    return out[::-1] if rev else out


def _ps_tick_label(ms):
    """d3's multi-scale time tick format, with the month shortened to %b."""
    ms = int(ms)
    if _ps_floor_unit(ms, 'second') < ms:
        return _ps_utc_format(ms, '.%L')
    if _ps_floor_unit(ms, 'minute') < ms:
        return _ps_utc_format(ms, ':%S')
    if _ps_floor_unit(ms, 'hour') < ms:
        return _ps_utc_format(ms, '%I:%M')
    if _ps_floor_unit(ms, 'day') < ms:
        return _ps_utc_format(ms, '%I %p')
    if _ps_floor_unit(ms, 'month') < ms:
        return _ps_utc_format(ms, '%a %d' if _ps_floor_unit(ms, 'week') < ms else '%b %d')
    return _ps_utc_format(ms, '%b' if _ps_floor_unit(ms, 'year') < ms else '%Y')


def _ps_c(v):
    return _if_numstr(_if_round(v * 100) / 100)


def _ps_numstr(v):
    s = _if_fixed(v, 6)
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return '0' if s == '-0' else s


def _ps_xstr(ms):
    y, m, d, h, mi, s, milli, wd, yd = _ps_civil(ms)
    return _ps_utc_format(ms, '%Y-%m-%d' if not (h or mi or s) else ('%Y-%m-%d %H:%M' if not s else '%Y-%m-%d %H:%M:%S'))


def _ps_color(v, i):
    return v if isinstance(v, str) and re.fullmatch(r'#[0-9a-fA-F]{3}|#[0-9a-fA-F]{6}|[a-zA-Z]{3,20}', v) else _PS_PAL[i % len(_PS_PAL)]


def _ps_expand(p, shape):
    n = len(p)
    if n < 2 or shape == 'linear':
        return list(p)
    out = [p[0]]
    if shape == 'spline':
        if n < 3:
            return list(p)
        for i in range(n - 1):
            p0, p1, p2, p3 = p[max(i - 1, 0)], p[i], p[i + 1], p[min(i + 2, n - 1)]
            for j in range(1, 9):
                t = j / 8
                t2, t3 = t * t, t * t * t
                out.append((0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
                            0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3)))
        return out
    for i in range(n - 1):
        a, b = p[i], p[i + 1]
        if shape == 'hv':
            out.append((b[0], a[1]))
        elif shape == 'vh':
            out.append((a[0], b[1]))
        elif shape == 'hvh':
            xm = (a[0] + b[0]) / 2
            out.append((xm, a[1]))
            out.append((xm, b[1]))
        else:
            ym = (a[1] + b[1]) / 2
            out.append((a[0], ym))
            out.append((b[0], ym))
        out.append(b)
    return out


def _ps_path(pts, close=False):
    return ''.join(('M' if i == 0 else 'L') + _ps_c(x) + ' ' + _ps_c(y) for i, (x, y) in enumerate(pts)) + ('Z' if close else '')


def _ps_marker(sym, cx, cy, r):
    f = _ps_c
    if sym == 'square':
        return 'M' + f(cx - r) + ' ' + f(cy - r) + 'h' + f(2 * r) + 'v' + f(2 * r) + 'h' + f(-2 * r) + 'z'
    if sym == 'diamond':
        k = r * 1.3
        return 'M' + f(cx) + ' ' + f(cy - k) + 'l' + f(k) + ' ' + f(k) + 'l' + f(-k) + ' ' + f(k) + 'l' + f(-k) + ' ' + f(-k) + 'z'
    if sym == 'triangle-up':
        return 'M' + f(cx) + ' ' + f(cy - r) + 'l' + f(r) + ' ' + f(2 * r) + 'h' + f(-2 * r) + 'z'
    if sym == 'cross':
        return 'M' + f(cx - r) + ' ' + f(cy) + 'h' + f(2 * r) + 'M' + f(cx) + ' ' + f(cy - r) + 'v' + f(2 * r)
    if sym == 'x':
        return 'M' + f(cx - r) + ' ' + f(cy - r) + 'l' + f(2 * r) + ' ' + f(2 * r) + 'M' + f(cx - r) + ' ' + f(cy + r) + 'l' + f(2 * r) + ' ' + f(-2 * r)
    return 'M' + f(cx - r) + ' ' + f(cy) + 'a' + f(r) + ' ' + f(r) + ' 0 1 0 ' + f(2 * r) + ' 0a' + f(r) + ' ' + f(r) + ' 0 1 0 ' + f(-2 * r) + ' 0'


def _ps_stroke_sym(sym):
    return sym in ('cross', 'x')


def _ps_legend_swatch(col, dash, sym, lines, markers):
    inner = ''
    if lines:
        inner += '<path d="M1 7H29" fill="none" stroke="' + col + '" stroke-width="2"' + (' stroke-dasharray="' + _PS_DASH[dash] + '"' if _PS_DASH[dash] else '') + '/>'
    if markers or not lines:
        inner += '<path d="' + _ps_marker(sym, 15, 7, 4) + '" ' + ('fill="none" stroke="' + col + '" stroke-width="1.6"' if _ps_stroke_sym(sym) else 'fill="' + col + '"') + '/>'
    return '<svg width="30" height="14" viewBox="0 0 30 14" aria-hidden="true" focusable="false" style="flex:none;">' + inner + '</svg>'


def _ps_render(b, atom):
    ser = b['series']
    pre = _if_s(b.get('title'), 80) if _ps_isstr(b.get('title')) else ''
    cap = 2000
    mp = b.get('max_points')
    if _ps_isnum(mp):
        cap = int(_hg_round(min(2000, max(50, mp))))
    xt = b.get('x_type') if b.get('x_type') in ('linear', 'date') else None
    if xt is None:
        xt = 'linear'
        for s in ser:
            xs = s.get('x') if isinstance(s, dict) else None
            if isinstance(xs, list) and xs and isinstance(xs[0], str):
                xt = 'date' if _ps_parse_date(xs[0]) is not None else 'linear'
                break
            if isinstance(xs, list) and xs:
                break
    notes = ''
    skipped = 0
    rows = []
    items = []
    anytext = False
    beyond = max(0, len(ser) - _PS_MAX_SERIES)
    for si, s in enumerate(ser[:_PS_MAX_SERIES]):
        s = s if isinstance(s, dict) else {}
        label = s.get('label') if _ps_isstr(s.get('label')) and s.get('label').strip(_PS_WS) else 'Series ' + str(si + 1)
        xs, ys, tx = s.get('x'), s.get('y'), s.get('text')
        ysl = ys if isinstance(ys, list) else []
        n = min(len(ysl), _PS_READ_CAP)
        if len(ysl) > _PS_READ_CAP:
            notes += _hg_note('Only the first 20,000 points of ' + _if_s(label, 40) + ' were read.')
        pts = []
        for i in range(n):
            yv = ysl[i]
            xv = xs[i] if isinstance(xs, list) and i < len(xs) else (i if not isinstance(xs, list) else None)
            if xt == 'date':
                xm = _ps_parse_date(xv) if isinstance(xv, str) else (math.floor(xv) if _ps_isnum(xv) and _PS_MS_MIN <= xv <= _PS_MS_MAX else None)
                xv = float(xm) if xm is not None else None
            elif not _ps_isnum(xv):
                xv = None
            if xv is None or not _ps_isnum(yv):
                skipped += 1
                continue
            pts.append((i, float(xv), float(yv)))
        total = len(pts)
        if total > cap:
            pts = [pts[(k * (total - 1)) // (cap - 1)] for k in range(cap)]
            notes += _hg_note(_if_s(label, 40) + ' has ' + _ps_thousands(total) + ' points; ' + _ps_thousands(cap) + ' evenly spaced points are drawn and listed in the table.')
        mode = s.get('mode')
        toks = mode.split('+') if isinstance(mode, str) else []
        if not toks or any(t not in _PS_MODES for t in toks):
            toks = ['lines', 'markers'] if total <= 20 else ['lines']
        sym = s.get('symbol') if s.get('symbol') in _PS_SYMS else _PS_SYMS[si % len(_PS_SYMS)]
        dash = s.get('dash') if s.get('dash') in _PS_DASH_NAMES else _PS_DASH_NAMES[si % len(_PS_DASH_NAMES)]
        shape = s.get('shape') if s.get('shape') in _PS_SHAPES else 'linear'
        fill = s.get('fill') if s.get('fill') in ('tozeroy', 'tonexty') else ''
        sz = s.get('size')
        items.append({'label': label, 'pts': pts, 'tx': tx if isinstance(tx, list) else None, 'lines': 'lines' in toks, 'markers': 'markers' in toks, 'text': 'text' in toks,
                      'sym': sym, 'dash': dash, 'shape': shape, 'fill': fill, 'col': _ps_color(s.get('color'), si), 'sz': sz})
        anytext = anytext or isinstance(tx, list)
    if beyond:
        notes += _hg_note(str(beyond) + (' series beyond the first 8 was' if beyond == 1 else ' series beyond the first 8 were') + ' not drawn.')
    if skipped:
        notes += _hg_note(str(skipped) + (' point was' if skipped == 1 else ' points were') + ' not a usable number' + (' or date' if xt == 'date' else '') + ' and ' + ('was' if skipped == 1 else 'were') + ' skipped.')
    notes += _hg_version_note(b, atom)
    allp = [p for it in items for p in it['pts']]
    ttl = '' if not pre else '<div style="font-weight:700;font-size:1.05rem;margin:0 0 10px;">' + pre + '</div>'
    if not allp:
        return _if_wrap(ttl + _hg_note('There are no points to draw.') + notes)
    xl, yl = _ps_axis_label(b, 'x'), _ps_axis_label(b, 'y')
    xv = [p[1] for p in allp]
    yv = [p[2] for p in allp]
    seen = False
    for it in items:   # tozeroy fills down to y = 0; tonexty fills to the previous drawn series, and to y = 0 only where there is none
        if it['fill'] == 'tozeroy' or (it['fill'] == 'tonexty' and not seen and it['pts']):
            yv = yv + [0.0]
            break
        seen = seen or bool(it['pts'])
    x0, x1 = min(xv), max(xv)
    if x0 == x1:
        x0, x1 = (x0 - 43200000, x1 + 43200000) if xt == 'date' else (x0 - 1, x1 + 1)
    y0, y1 = min(yv), max(yv)
    if y0 == y1:
        y0, y1 = y0 - 1, y1 + 1
    y0, y1 = _hg_nice(y0, y1, 5)
    yt = _hg_ticks(y0, y1, 5) or [y0, y1]
    xt_ = _ps_time_ticks(x0, x1, 4) if xt == 'date' else (_hg_ticks(x0, x1, 4) or [x0, x1])
    if not xt_:
        xt_ = [x0, x1]
    iw, ih = _PS_W - 2 * _PS_M, _PS_H - 2 * _PS_M
    px = lambda v: _PS_M + (v - x0) / (x1 - x0) * iw
    py = lambda v: _PS_M + (1 - (v - y0) / (y1 - y0)) * ih
    pct = lambda v, d: _if_fixed(v / d * 100, 2) + '%'
    dy = _hg_decimals(yt)
    dx = _hg_decimals(xt_) if xt != 'date' else 0
    yz = min(_PS_H - _PS_M, max(_PS_M, py(0)))
    grid = ''
    ylab = ''
    for t in yt:
        gy = py(t)
        if _PS_M - 0.001 <= gy <= _PS_H - _PS_M + 0.001:
            grid += '<line x1="' + str(_PS_M) + '" y1="' + _ps_c(gy) + '" x2="' + str(_PS_W - _PS_M) + '" y2="' + _ps_c(gy) + '" stroke="var(--border,#CBD5E1)" stroke-width="1" vector-effect="non-scaling-stroke"/>'
            ylab += '<div style="position:absolute;right:100%;top:' + pct(gy, _PS_H) + ';transform:translateY(-50%);padding-right:6px;font-size:0.75rem;line-height:1;white-space:nowrap;color:' + _IF_MUTED + ';">' + _cv_esc(_hg_num(t, dy)) + '</div>'
    xlab = ''
    lused = set()
    for t in xt_:
        gx = px(t)
        if _PS_M - 0.001 <= gx <= _PS_W - _PS_M + 0.001:
            grid += '<line x1="' + _ps_c(gx) + '" y1="' + str(_PS_M) + '" x2="' + _ps_c(gx) + '" y2="' + str(_PS_H - _PS_M) + '" stroke="var(--border,#CBD5E1)" stroke-width="1" vector-effect="non-scaling-stroke"/>'
            tl = _ps_tick_label(t) if xt == 'date' else _hg_num(t, dx)
            xlab += '<div data-cb="label" data-key="' + _cb_ukey(tl, lused) + '" style="position:absolute;top:100%;left:' + pct(gx, _PS_W) + ';transform:translateX(-50%);margin-top:8px;font-size:0.75rem;line-height:1;white-space:nowrap;color:' + _IF_MUTED + ';">' + _cv_esc(tl) + '</div>'
    grid += ('<line x1="' + str(_PS_M) + '" y1="' + str(_PS_M) + '" x2="' + str(_PS_M) + '" y2="' + str(_PS_H - _PS_M) + '" stroke="var(--muted,#475569)" stroke-width="1" vector-effect="non-scaling-stroke"/>'
             '<line x1="' + str(_PS_M) + '" y1="' + str(_PS_H - _PS_M) + '" x2="' + str(_PS_W - _PS_M) + '" y2="' + str(_PS_H - _PS_M) + '" stroke="var(--muted,#475569)" stroke-width="1" vector-effect="non-scaling-stroke"/>')
    fills = lines = marks = labels = ''
    prev = None
    legend = ''
    sused = set()
    for si, it in enumerate(items):
        sk = _cb_ukey(it['label'], sused)
        sp = [(px(p[1]), py(p[2])) for p in it['pts']]
        ex = _ps_expand(sp, it['shape'])
        col = it['col']
        if it['fill'] and sp:
            if it['fill'] == 'tonexty' and prev:
                poly = ex + prev[::-1]
            else:
                poly = ex + [(ex[-1][0], yz), (ex[0][0], yz)]
            fills += '<path d="' + _ps_path(poly, True) + '" fill="' + col + '" fill-opacity="0.15" stroke="none"/>'
        if it['lines'] and len(ex) > 1:
            da = _PS_DASH[it['dash']]
            lines += '<path data-cb="branch" data-key="' + sk + '" d="' + _ps_path(ex) + '" fill="none" stroke="' + col + '" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"' + (' stroke-dasharray="' + da + '"' if da else '') + ' vector-effect="non-scaling-stroke"/>'
        if it['markers']:
            fd = sd = ''
            for k, p in enumerate(it['pts']):
                z = it['sz'][p[0]] if isinstance(it['sz'], list) and p[0] < len(it['sz']) else it['sz']
                r = min(40, max(2, z)) / 2 if _ps_isnum(z) else 3.5
                if _ps_stroke_sym(it['sym']):
                    sd += _ps_marker(it['sym'], sp[k][0], sp[k][1], r)
                else:
                    fd += _ps_marker(it['sym'], sp[k][0], sp[k][1], r)
            mk = ' data-cb="node" data-key="' + (_cb_ukey(it['label'] + '/markers', sused) if it['lines'] and len(ex) > 1 else sk) + '"'
            if fd:
                marks += '<path' + mk + ' d="' + fd + '" fill="' + col + '" stroke="var(--bg,#fff)" stroke-width="0.8"/>'
            if sd:
                marks += '<path' + mk + ' d="' + sd + '" fill="none" stroke="' + col + '" stroke-width="1.6" vector-effect="non-scaling-stroke"/>'
        if it['text']:
            for k, p in enumerate(it['pts']):
                if k >= _PS_TEXT_CAP:
                    notes += _hg_note('Only the first ' + str(_PS_TEXT_CAP) + ' point labels of ' + _if_s(it['label'], 40) + ' are drawn; all values are in the table.')
                    break
                tv = it['tx'][p[0]] if it['tx'] is not None and p[0] < len(it['tx']) else None
                tt = tv if _ps_isstr(tv) or _ps_isnum(tv) else _ps_numstr(p[2])
                labels += '<div style="position:absolute;left:' + pct(sp[k][0], _PS_W) + ';top:' + pct(sp[k][1], _PS_H) + ';transform:translate(-50%,-135%);font-size:0.75rem;line-height:1;white-space:nowrap;color:var(--text,#0F172A);">' + _if_s(tt, 20) + '</div>'
        prev = ex if sp else prev
        legend += '<span style="display:inline-flex;align-items:center;gap:6px;">' + _ps_legend_swatch(col, it['dash'], it['sym'], it['lines'], it['markers']) + '<span>' + _if_s(it['label'], 40) + '</span></span>'
        for p in it['pts']:
            tv = it['tx'][p[0]] if it['tx'] is not None and p[0] < len(it['tx']) else ''
            rows.append([it['label'], _ps_xstr(p[1]) if xt == 'date' else _ps_numstr(p[1]), _ps_numstr(p[2])] + ([tv if _ps_isstr(tv) or _ps_isnum(tv) else ''] if anytext else []))
    gist = ('Scatter chart' if atom == 'scatter_trend' else 'Line chart') + (' ' + _if_s(b.get('title'), 60) if _ps_isstr(b.get('title')) and b.get('title') else '') + ': ' + '; '.join(
        _if_s(it['label'], 30) + ' (' + str(len(it['pts'])) + ' points' + (', y from ' + _ps_numstr(min(p[2] for p in it['pts'])) + ' to ' + _ps_numstr(max(p[2] for p in it['pts'])) if it['pts'] else '') + ')' for it in items) + '. x runs from ' + (_ps_xstr(min(xv)) if xt == 'date' else _ps_numstr(min(xv))) + ' to ' + (_ps_xstr(max(xv)) if xt == 'date' else _ps_numstr(max(xv))) + '.'
    mb = 30
    plot = ('<div role="img" aria-label="' + gist + '" style="position:relative;aspect-ratio:' + str(_PS_W) + '/' + str(_PS_H) + ';margin:6px 18px ' + str(mb) + 'px 48px;">'
            '<svg viewBox="0 0 ' + str(_PS_W) + ' ' + str(_PS_H) + '" width="100%" height="100%" aria-hidden="true" focusable="false" style="position:absolute;left:0;top:0;display:block;overflow:visible;" xmlns="http://www.w3.org/2000/svg">'
            + grid + fills + lines + marks + '</svg>' + ylab + xlab + labels
            + '</div>' + ('<div style="margin:0 18px 4px 48px;text-align:center;font-size:0.75rem;line-height:1.2;color:' + _IF_MUTED + ';">' + xl + '</div>' if xl else ''))
    head = '<div style="font-size:0.75rem;color:' + _IF_MUTED + ';margin:0 0 2px;">' + yl + '</div>' if yl else ''
    leg = '<div style="display:flex;flex-wrap:wrap;gap:6px 16px;font-size:0.75rem;line-height:1.2;margin-top:2px;">' + legend + '</div>' if len(items) > 1 else ''
    return _if_wrap(ttl + '<div class="ifps" style="' + _if_card() + '">' + head + plot + leg + '</div>' + _if_table(['Series', 'X', 'Y'] + (['Label'] if anytext else []), rows) + notes)


def _ps_isstr(v):
    return isinstance(v, str)


def _ps_thousands(n):
    return re.sub(r'\B(?=(\d{3})+(?!\d))', ',', str(n))


def _ps_axis_label(b, ax):
    v = b.get(ax + '_label')
    v = b.get('label_' + ax) if not _ps_isstr(v) or not v else v
    return _if_s(v, 60) if _ps_isstr(v) and v else ''


def _ps_wrap(prev, atom):
    def f(b):
        if isinstance(b.get('series'), list) and b['series']:
            return _ps_render(b, atom)
        return prev(b)
    return f


_RENDERERS['chartjs_line'] = _ps_wrap(_RENDERERS['chartjs_line'], 'chartjs_line')
_RENDERERS['scatter_trend'] = _ps_wrap(_RENDERERS['scatter_trend'], 'scatter_trend')


# ─── conversion_funnel `shape: "area"` (Plotly funnelarea) and gauge_sla scale mode (Plotly indicator gauge), wave B ───
# Both are additive: without `shape: "area"` / without `min` or `steps` the previous renderer runs untouched. Twin of the
# wrappers at the end of atoms_unstub.gs. Labels live in HTML (not SVG text) so they are never scaled below 12px.
_CF_COLOR = re.compile(r'#[0-9a-fA-F]{3,8}|var\(--[a-z-]+(?:,#[0-9a-fA-F]{3,8})?\)')


_CF_MAX = 1e15   # a larger number is refused, never converted: a Python int past 1.8e308 raises OverflowError in float(), and >= 1e21 prints differently in the twins
_CF_NUMSTR = re.compile(r'[ \t]*[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?[ \t]*')


def _cf_isnum(v):
    """A real number in range (strict type: the mode switches use this)."""
    return isinstance(v, (int, float)) and not isinstance(v, bool) and v == v and abs(v) <= _CF_MAX


def _cf_n(v):
    """The usable number in v, or None: a number in range, or a plain decimal string (like the legacy renderers' float()). Never raises."""
    if isinstance(v, str):
        if len(v) > 40 or not _CF_NUMSTR.fullmatch(v):
            return None
        v = float(v)
    return v if _cf_isnum(v) else None


def _cf_given(v):
    """Present and not null (a field the caller wrote)."""
    return not (v is None or v is _IF_UNDEF)


def _cf_name(v):
    return '' if (v is None or v is _IF_UNDEF) else _if_str(v)[:40]


def _cf_pt(cx, cy, r, frac):
    a = math.pi * (1 + frac)
    return _if_fmt(cx + r * math.cos(a)) + ' ' + _if_fmt(cy + r * math.sin(a))


def _cf_area(b):
    raw = _if_g(b, 'steps')
    rows, skipped = [], 0
    for s in (raw[:500] if isinstance(raw, list) else []):
        v = _cf_n(_if_g(s, 'value'))
        if v is None or v < 0:
            skipped += 1
            continue
        nm = _if_g(s, 'stage')
        if not _if_truthy(nm):
            nm = _if_g(s, 'label')
        rows.append((_cf_name(nm) or 'Step %d' % (len(rows) + 1), v))
    capped = len(rows) > 12
    n_all = len(rows)
    rows = rows[:12]
    notes = ''
    if skipped:
        notes += _hg_note(str(skipped) + (' entry' if skipped == 1 else ' entries') + ' skipped: not a usable stage (it needs a number value of 0 or more).')
    if capped:
        notes += _hg_note('Showing the first 12 of ' + str(n_all) + ' stages.')
    notes += _hg_version_note(b, 'conversion_funnel')
    tot = 0.0
    for r in rows:
        tot += r[1]
    if not rows or not tot > 0:
        return _if_wrap('<div class="ifcf">' + _if_title(b) + _hg_note('Nothing to draw: the funnel has no stage with a value above zero.') + notes + '</div>')
    H, W0 = 240, 400
    polys, cum, prev_y = '', 0.0, 0
    pused, lused = set(), set()
    for k, (nm, v) in enumerate(rows):
        cum += v
        y2 = max(0.0, H * (1 - math.sqrt(max(0.0, 1 - cum / tot))))
        if v > 0:
            w1, w2 = W0 * (1 - prev_y / H), W0 * (1 - y2 / H)
            pts = [(200 - w1 / 2, prev_y), (200 + w1 / 2, prev_y), (200 + w2 / 2, y2), (200 - w2 / 2, y2)]
            polys += ('<polygon data-cb="bar" data-key="' + _cb_ukey(nm, pused) + '" class="cfb" points="' + ' '.join(_if_fmt(x) + ',' + _if_fmt(y) for x, y in pts)
                      + '" fill="' + _IF_CAT[k % 4] + '" stroke="var(--bg,#fff)" stroke-width="2"></polygon>')
        prev_y = y2
    first = rows[0][1]
    gist = 'Funnel area chart, area proportional to value: ' + ', '.join(nm + ' ' + _if_numstr(v) for nm, v in rows) + '.'
    svg = ('<svg role="img" aria-label="' + _cv_esc(gist[:400]) + '" viewBox="0 0 400 240" style="display:block;width:100%;max-width:420px;height:auto;margin:0 auto;">' + polys + '</svg>')
    sw = 'flex:none;width:12px;height:12px;border:1px solid var(--border,#64748B);border-radius:2px;align-self:center;'
    legend = '<ol class="cfl" style="list-style:none;margin:10px 0 0;padding:0;font-size:0.9rem;">' + ''.join(
        '<li data-cb="label" data-key="' + _cb_ukey(nm, lused) + '" style="display:flex;align-items:baseline;gap:8px;padding:2px 0;"><span aria-hidden="true" style="' + sw + 'background:' + _IF_CAT[k % 4] + ';"></span>'
        '<span style="flex:1;min-width:0;overflow-wrap:anywhere;">' + str(k + 1) + '. ' + _cv_esc(nm) + '</span>'
        '<span style="flex:none;font-weight:600;font-size:0.9rem;">' + _if_s(_if_numstr(v), 30) + (' · ' + _if_fmt(v / first * 100) + '%' if first > 0 else '') + '</span></li>'
        for k, (nm, v) in enumerate(rows)) + '</ol>'
    table = _if_table(['Stage', 'Value', 'Of first', 'Of total area'],
                      [[nm, _if_numstr(v), (_if_fmt(v / first * 100) + '%') if first > 0 else 'n/a', _if_fmt(v / tot * 100) + '%'] for nm, v in rows])
    return _if_wrap('<div class="ifcf">' + _if_title(b) + svg + legend + table + notes + '</div>')


def _cf_gauge(b):
    val, mn, mx, thr = _cf_n(_if_g(b, 'value')), _cf_n(_if_g(b, 'min')), _cf_n(_if_g(b, 'max_value')), _cf_n(_if_g(b, 'threshold'))
    bad = [k for k, v in (('min', mn), ('max_value', mx), ('threshold', thr)) if v is None and _cf_given(_if_g(b, k))]
    mn = mn if mn is not None else 0
    mx = mx if mx is not None else 100
    unit, label = _cf_name(_if_g(b, 'unit'))[:12], _if_s(_if_g(b, 'label'), 40)
    notes = (_hg_note(', '.join(bad) + (' was' if len(bad) == 1 else ' were') + ' not a usable number (it needs a plain number below 1e15) and ' + ('was' if len(bad) == 1 else 'were') + ' ignored.') if bad else '') + _hg_version_note(b, 'gauge_sla')
    ROOT = '<div class="ifgs" data-cb="node" data-key="' + _ck(_if_g(b, 'title'), 'gauge_sla') + '">'
    if val is None:
        return _if_wrap(ROOT + _if_title(b) + _hg_note('The value is not a number, so there is nothing to draw.') + notes + '</div>')
    if not mx > mn:
        return _if_wrap(ROOT + _if_title(b) + _hg_note('The maximum must be larger than the minimum, so there is nothing to draw.') + notes + '</div>')
    span = mx - mn

    def fr(x):
        return min(1.0, max(0.0, (x - mn) / span))
    raw = _if_g(b, 'steps')
    bands, skipped = [], 0
    for s in (raw[:500] if isinstance(raw, list) else []):
        f, t, c = _cf_n(_if_g(s, 'from')), _cf_n(_if_g(s, 'to')), _if_g(s, 'color')
        if f is None or t is None or not f < t:
            skipped += 1
            continue
        f, t = max(mn, f), min(mx, t)
        if not f < t:
            skipped += 1
            continue
        bands.append((f, t, c if isinstance(c, str) and _CF_COLOR.fullmatch(c) else None))
    capped = len(bands) > 8
    n_all = len(bands)
    bands = bands[:8]
    if skipped:
        notes += _hg_note(str(skipped) + ' step' + ('' if skipped == 1 else 's') + ' skipped: not a usable band (it needs a numeric from below its to).')
    if capped:
        notes += _hg_note('Showing the first 8 of ' + str(n_all) + ' bands.')
    cx, cy, R = 150, 140, 100
    arc = lambda a, z: 'M ' + _cf_pt(cx, cy, R, a) + ' A 100 100 0 0 1 ' + _cf_pt(cx, cy, R, z)
    g = '<path d="' + arc(0, 1) + '" fill="none" stroke="var(--border,#CBD5E1)" stroke-width="14"></path>'
    for k, (f, t, c) in enumerate(bands):
        g += '<path data-cb="arc" data-key="Band ' + str(k + 1) + '" class="gsb" d="' + arc(fr(f), fr(t)) + '" fill="none" stroke="' + (c or _IF_CAT[k % 4]) + '" stroke-width="14"></path>'

    def seg(frac, r1, r2, cls, w):
        a = math.pi * (1 + frac)
        return ('<line class="' + cls + '" x1="' + _if_fmt(cx + r1 * math.cos(a)) + '" y1="' + _if_fmt(cy + r1 * math.sin(a)) + '" x2="' + _if_fmt(cx + r2 * math.cos(a))
                + '" y2="' + _if_fmt(cy + r2 * math.sin(a)) + '" stroke="var(--text,#0F172A)" stroke-width="' + str(w) + '" stroke-linecap="round"></line>')
    if thr is not None:
        g += seg(fr(thr), 88, 114, 'gst', 3)
    g += seg(fr(val), 0, 82, 'gsn', 4) + '<circle cx="150" cy="140" r="7" fill="var(--text,#0F172A)"></circle>'
    vs = _if_fmt(val)
    gist = ('Gauge' + (': ' + _cf_name(_if_g(b, 'title'))[:60] if _if_truthy(_if_g(b, 'title')) else '') + ', value ' + vs + unit + ' on a scale from ' + _if_fmt(mn) + ' to ' + _if_fmt(mx)
            + ((', threshold ' + _if_fmt(thr)) if thr is not None else '') + ((', ' + str(len(bands)) + ' bands') if bands else '') + '.')
    svg = '<svg role="img" aria-label="' + _cv_esc(gist) + '" viewBox="0 0 300 160" style="display:block;width:100%;max-width:360px;height:auto;margin:0 auto;">' + g + '</svg>'
    status = ''
    if thr is not None:
        status += 'At or above the threshold of ' + _if_fmt(thr) + '.' if val >= thr else 'Below the threshold of ' + _if_fmt(thr) + '.'
    if val < mn or val > mx:
        status += (' ' if status else '') + 'The value is off the scale; the needle stops at the end.'
    sw = 'flex:none;width:12px;height:12px;border:1px solid var(--border,#64748B);border-radius:2px;align-self:center;'
    items = ''.join('<li style="display:flex;gap:8px;padding:2px 0;"><span aria-hidden="true" style="' + sw + 'background:' + (c or _IF_CAT[k % 4]) + ';"></span><span>Band ' + str(k + 1) + ': '
                    + _if_fmt(f) + ' to ' + _if_fmt(t) + '</span></li>' for k, (f, t, c) in enumerate(bands))
    if thr is not None:
        items += '<li style="display:flex;gap:8px;padding:2px 0;"><span aria-hidden="true" style="flex:none;font-weight:700;">|</span><span>Threshold: ' + _if_fmt(thr) + '</span></li>'
    legend = '<ul class="gsl" style="list-style:none;margin:8px 0 0;padding:0;font-size:0.9rem;">' + items + '</ul>' if items else ''
    rows = [['Band %d' % (k + 1), _if_fmt(f), _if_fmt(t)] for k, (f, t, c) in enumerate(bands)] + [['Scale', _if_fmt(mn), _if_fmt(mx)], ['Value', vs, vs]]
    if thr is not None:
        rows.append(['Threshold', _if_fmt(thr), _if_fmt(thr)])
    return _if_wrap(ROOT + _if_title(b) + svg
                    + '<div style="display:flex;justify-content:space-between;max-width:360px;margin:0 auto;font-size:0.9rem;color:' + _IF_MUTED + ';"><span>' + _if_fmt(mn) + '</span><span>' + _if_fmt(mx) + '</span></div>'
                    + '<div style="text-align:center;font-weight:800;font-size:1.6rem;">' + vs + _cv_esc(unit) + '</div>'
                    + ('<div style="text-align:center;font-size:0.9rem;color:' + _IF_MUTED + ';">' + label + '</div>' if label else '')
                    + ('<div style="text-align:center;font-size:0.9rem;">' + status + '</div>' if status else '') + legend
                    + _if_table(['Band', 'From', 'To'], rows) + notes + '</div>')


_cf_prev_funnel, _cf_prev_gauge = _RENDERERS['conversion_funnel'], _RENDERERS['gauge_sla']


def _cf_legacy(prev, b, atom):
    """The previous renderer, unchanged; a number it cannot convert (a 400-digit integer, say) gives a note instead of failing the whole page."""
    try:
        return prev(b)
    except (OverflowError, ValueError, ZeroDivisionError, TypeError):
        return _if_wrap('<div class="if' + ('cf' if atom == 'conversion_funnel' else 'gs') + '">' + _if_title(b) + _hg_note('A value in this block is not a number the chart can draw (it needs a plain number below 1e15), so there is nothing to draw.') + '</div>')


def _render_conversion_funnel_shaped(b):
    return _cf_area(b) if _if_g(b, 'shape') == 'area' else _cf_legacy(_cf_prev_funnel, b, 'conversion_funnel')


def _render_gauge_sla_scaled(b):
    return _cf_gauge(b) if _cf_isnum(_if_g(b, 'min')) or isinstance(_if_g(b, 'steps'), list) else _cf_legacy(_cf_prev_gauge, b, 'gauge_sla')


_RENDERERS['conversion_funnel'] = _render_conversion_funnel_shaped
_RENDERERS['gauge_sla'] = _render_gauge_sla_scaled


# MUST stay the last statement that touches _RENDERERS: wraps every registered renderer so the generic `enter` prop works on any atom.
_mo_install()
_gd_install()  # payload guard wraps OUTSIDE the motion wrapper; must stay after _mo_install()

